INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6ae767047d2c0b13', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Idiom: To take the bull by the horns means ____?', '{"A":"To handle it by fierce attack","B":"To grapple courageously with a difficulty that lies in our way","C":"To punish a person severely for his arrogance","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To take the bull by the horns: To approach, confront, or deal with a problem or difficult situation directly and with clear, confident action.', 0, 0, 0, 1790961793518) ON CONFLICT(id) DO NOTHING;
