INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_937bdf58cacaa84d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'She kicked up a row when she was denied entry to the amusement park. In the above sentence, the idiom "Kicked up a row" means', '{"A":"Created a fuss","B":"Kicked the guard","C":"Waited in a queue","D":"Cried with sorrow","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kick off means شروع کرناkick up means شروعات کرناKick up a row means ہنگامہ کھڑاکردینا، شور مچادینا', 0, 0, 0, 1790961793863) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_891e46c3a323c018', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'The idiom "A square peg in a round hole" means?', '{"A":"In a financial crisis","B":"a misfit in the environment","C":"unhappy and regretful","D":"in a favourable situation","E":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The idiom "A square peg in a round hole" means غیر مناسب ماحول میںFor Example" She found herself a square peg in a round hole when she married a poor farmer and moved to a small village.', 0, 0, 0, 1790961793863) ON CONFLICT(id) DO NOTHING;
