INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4279dd84ffc8a6dc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'The idiom “Pass the buck” means?', '{"A":"keep something in hand","B":"To evade responsibility","C":"To Warn","D":"Come to know someone’s secrets","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pass the buck means کوئی مشکل معالمہ کسی اور کے ذمے لگاناDo not try to the pass the buck - this is not your responsibility, not mine.معاملہ میرے ذمے نہ لگاؤ، یہ آپ کی ذمہ داری ہے میری نہیں۔', 0, 0, 0, 1790961794041) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c409ac6ebeb40c10', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'The idiom “cast iron stomach” means', '{"A":"A person who is fat","B":"A person who can drive fast","C":"A person who can cook fast","D":"A person who can eat a lot","E":"All of the above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A person with a cast iron stomach can eat or drink anything without any ill effects. The idiom “cast iron stomach” means ایسا شخص جو بہت کچھ کھا سکتا ہوFor Example:You must have a cast-iron stomach if you''re eating pickles with peanut butter!', 0, 0, 0, 1790961794041) ON CONFLICT(id) DO NOTHING;
