INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ea85a12b4c18c1dc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_one_word', 'Ophthalmology is the study of ____?', '{"A":"Nerves","B":"Blood","C":"Eyes","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ophthalmology is the study and medical specialty concerned with the eyes and vision.It deals with the structure, function, diseases, and treatment of the eyes.A doctor specializing in this field is called an ophthalmologist.Common eye conditions include cataracts, glaucoma, and refractive errors.Last verified on 08-08-2026', 0, 0, 0, 1790961794309) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b93d3e2e90ceb14a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_one_word', 'A person who is womanish in his habits?', '{"A":"Feminist","B":"Effeminate","C":"Philanderer","D":"Philatelist"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A man who is womanish in his habits is known as Effeminate.whilePHILANDERER is a man who has sexual relations with many women.', 0, 0, 0, 1790961794309) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b2835e5702741b82', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_one_word', 'A person who believes that the primary purposes of life are to eat, drink, and marry is called ____?', '{"A":"Cynic","B":"Epicurean","C":"Materialistic","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A Epicurean is someone who believes that the pursuit of pleasure and enjoyment, such as eating, drinking, and marrying, is the most important goal in life. This philosophy emphasizes seeking pleasure and avoiding pain as the primary purpose of living.', 0, 0, 0, 1790961794309) ON CONFLICT(id) DO NOTHING;
