INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5ce67972686fa5b7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_one_word', 'Shale : Geologist ::', '{"A":"Reef : Astrologer","B":"Love : Philologist","C":"Obelisk : Fireman","D":"Aster : Botanist"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Shale is a type of rock studied by geologists.Aster is a type of plant studied by botanists.The analogy shows object : specialist relationship.Shale means ایک قسم کا پتھرGeologist means علم زمین کا ماہرAster means ایک قسم کا پھول Botanist means نباتیات کا ماہر', 0, 0, 0, 1790961794393) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ae2829bdadd77cc8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_one_word', 'The Study of Universe it''s origin, nature and evaluation is called?', '{"A":"Astronomy","B":"Archaeology","C":"Geography","D":"Cosmology"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The study of the universe''s origin, nature, and evolution is called CosmologyEdwin Powell Hubble is called the father of Cosmology.The term cosmology was first used in English in 1656 in Thomas Blount''s Glossographia, with the meaning of "a speaking of the world"', 0, 0, 0, 1790961794393) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1367dee93b3db858', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_one_word', 'The study of the earth and its features is known as ______?', '{"A":"Geology","B":"Geography","C":"Crystallography","D":"Petrolgy"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Geography is the study of the Earth, its physical features, and human activities.It helps us understand landforms, climate, and the relationship between humans and the environment.', 0, 0, 0, 1790961794393) ON CONFLICT(id) DO NOTHING;
