INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_007c464b152d55bb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_one_word', 'A person who has been unusual habits ______?', '{"A":"Eccentric","B":"Misogynist","C":"Misogamist","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A person with unusual habits or behaviors is often described as eccentric.Eccentricity refers to unconventional or quirky habits, interests, or behaviors that set someone apart from others.', 0, 0, 0, 1790961794478) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0bcdc8154e37402a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_one_word', 'One word Substitution: Study of and exploration of caves is?', '{"A":"Ornithology","B":"Geology","C":"Speleological","D":"Oratory"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Speleology is the scientific study and exploration of caves.The word comes from the Greek words "spelaion", meaning "cave", and "-logy", meaning "study" or "science".', 0, 0, 0, 1790961794478) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_21be64c8b3b58593', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_one_word', 'One word Substitution: A person who insists on something?', '{"A":"Stickler","B":"Boaster","C":"Disciplinarian","D":"Instantaneous"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A stickler is a person who insists on something, especially a rule or a detail, and is unwilling to compromise or be flexible.Boaster: A person who talks with pride about their achievements or possessions.Disciplinarian: A person who believes in and enforces strict rules and punishments.Instantaneous: Happening or done immediately, without delay.', 0, 0, 0, 1790961794478) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_956e54e961410878', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_one_word', 'Fear of lightning and thunder is known as _____?', '{"A":"Aquaphobia","B":"Trypanophobia","C":"Astraphobia","D":"Glossophobia"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fear of lightning and thunder is known as astraphobia. It comes from the Greek words “astrape” (lightning) and “phobos” (fear).', 0, 0, 0, 1790961794478) ON CONFLICT(id) DO NOTHING;
