INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4833fb7341142b81', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_one_word', 'One Word Substitute: A person who kills his/her brother or sister?', '{"A":"Drunkard","B":"Incurable","C":"Fratricide","D":"Germicide"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fratricide refers to the act of killing one''s own brother or sister. The term is derived from the Latin words "frater," meaning brother, and "cidium," meaning killing.Drunkard: A person who drinks excessively.Incurable: A disease or condition that cannot be cured.Germicide: A substance that kills germs or microorganisms.', 0, 0, 0, 1790961794567) ON CONFLICT(id) DO NOTHING;
