INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5d089ddc094ce4f3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_one_word', 'Febriphobia is a fear of________', '{"A":"Fire","B":"Wealth","C":"Fever","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Febriphobia is the fear of fever.whileAerophobia is an extreme fear of flying.Laliophobia is a fear of speakingNyctophobia is the fear of Darkness.Anthophobia is the fear of flora.Heliophobia is the fear of the Sun, sunlight, or any bright light.Hemophobia, or blood phobia,', 0, 0, 0, 1790961794808) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b35c7f15b37f7fe5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_one_word', 'Which term is refer to the study of speech process?', '{"A":"Phonology","B":"Phonetic substances","C":"Phonetics","D":"Semantics"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Phonology refers to the study of speech sounds of a given language and their function within the sound system. Phonetics is the study of speech process. Syntax and Morphology are sub-levels of the grammatical system.', 0, 0, 0, 1790961794808) ON CONFLICT(id) DO NOTHING;
INSERT INTO subject (id, user_id, name, parent_id, total_mcqs, created_at) VALUES ('top_eng_voice', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'Active & Passive Voice', 'top_english', 78, 1790961794885) ON CONFLICT(id) DO UPDATE SET total_mcqs = 78;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2b833ed243d9a43d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Choose the correct active/passive voice: The police arrested the suspect.', '{"A":"The suspect has arrested by the police","B":"The suspect was arrested by the police","C":"The police was arrested the suspect","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The given sentence is in active voice; its passive form is: Subject (The suspect) + was + past participle (arrested) + by the police.Hence, “The suspect was arrested by the police.” is correct.Last verified on 07-09-2026', 0, 0, 0, 1790961794971) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_17518b58c7ccc3b9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change the voice: She wrote a letter.', '{"A":"A letter is written by her.","B":"A letter was written by her.","C":"A letter has been written by her.","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sentence "She wrote a letter" is in past simple tense.The passive voice of a past simple sentence is formed as:Object + was/were + past participle + by + subjectSo, "A letter was written by her." is correct.Last verified on 04-05-2026', 0, 0, 0, 1790961794971) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_666f334ae83aa8d7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change the voice of the following sentence: Does she writes a letter?', '{"A":"Is a letter written by her?","B":"Has the letter been written by her?","C":"Is she writing a letter?","D":"A letter is written by her?"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The passive voice of "Does she write a letter?" is "Is a letter written by her?"The sentence is in the Simple Present Tense.Object: a letter → becomes the subject.Use is for the singular noun "letter."write → written (past participle).she → her after "by."Last update 0n 21-07-2026 by NA', 0, 0, 0, 1790961794971) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_59a76b013e0c5ef2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change the Voice: People say that honesty is the best policy.', '{"A":"It was said that honesty is the best policy","B":"It is said that honesty is the best policy","C":"It should be said that honesty is the best policy","D":"It will be said that honesty is the best policy"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Passive: It is said that honesty is the best policy.Active: People say that honesty is the best policy.Tense: Simple PresentVerb Change: say → is saidSubject "People" is omitted because it is a general subject.Last verified on 18-07-2026', 0, 0, 0, 1790961794971) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_30e72880dc6f639f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change into passive: ''He is reading a book.''', '{"A":"A book read him","B":"A book is read by him","C":"A book is being read by him","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sentence is in Present Continuous Tense (is reading).Passive form uses is/am/are + being + past participle.So: A book is being read by him.Last verified on 15-05-2026', 0, 0, 0, 1790961794971) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fbe82b5def2abe35', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change the voice: Why does an officer neglect duties?', '{"A":"Why is the duties neglected by an officer?","B":"Why the duties neglected by an officer?","C":"Why are the duties neglected by an officer?","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active voice: Why does an officer neglect duties?Passive voice: Why are the duties neglected by an officer?In passive voice, "duties" becomes the subject, and are + past participle (neglected) is used.Last verified on 01-07-2026', 0, 0, 0, 1790961794971) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_978b78c741a17229', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change the voice: "People speak English all over the world".', '{"A":"English is spoken by people.","B":"English was spoken by people.","C":"English was spoken all over the world.","D":"English is spoken all over the world."}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation English is spoken all over the world.The active sentence is in the Simple Present Tense, so the passive form uses is/am/are + past participle.The object "English" becomes the subject in the passive voice.The agent "people" is omitted because it is general and unnecessary.Last verified on 08-06-2026', 0, 0, 0, 1790961794971) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_38105720e9a22736', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change the voice: Lion does not eat grass, however hungry he may be.', '{"A":"Grass is not eaten by a lion, however hungry he may be.","B":"Grass was being not eaten by a lion, however hungry he may be.","C":"Grass is eaten not by a lion, however hungry he may be.","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sentence is in Simple Present Tense: Lion does not eat grass.Passive voice structure: Object + is/am/are + not + past participle + by + subject.Therefore, “Grass is not eaten by a lion, however hungry he may be.” is correct.Last verified on 05-06-2026', 0, 0, 0, 1790961794971) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_de57df624055e894', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', '“They have finished the homework.” (Change into passive voice)', '{"A":"The homework is finished by them","B":"The homework has been finished by them","C":"The homework was finished by them","D":"The homework will be finished by them"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The homework has been finished by them.• The sentence is in Present Perfect Tense.• Passive structure of Present Perfect:Has/Have + been + past participleLast verified on 09-05-2026', 0, 0, 0, 1790961795064) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b0892fa8a95bcb12', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change the voice: Open the window.', '{"A":"Let the window be opened.","B":"Let the window will be opened.","C":"Let the window was opened.","D":"Let the window is been opened."}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Let the window be opened. Given sentence is in simple future tense and it is in active voice. Rule: Subject + be + V3 + Other agentsLast updated question by NA on 07 May 2026', 0, 0, 0, 1790961795064) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e35f38d1b38ec9fd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change the voice: The pilot landed the plane safely.', '{"A":"The plane was to be landed safely by the pilot.","B":"The plane had been landed safely by the pilot.","C":"The plane was landed safely by the pilot.","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The original sentence is in simple past tense ("landed"), so the passive form also uses simple past: "was landed."The object "the plane" becomes the subject in passive voice, followed by "was landed" and agent "by the pilot."Last verified on 19-04-2026', 0, 0, 0, 1790961795064) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_840162b74ff5f4ef', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change the voice: The boys elected Mohsin captain.', '{"A":"Mohsin was elected captain by the boys.","B":"Boys were elected captain by Mohsin.","C":"Mohsin is elected captain by the boys.","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active sentence (past tense) changes to passive with “was + past participle” (was elected).Object “Mohsin” becomes subject, and subject “the boys” becomes agent.Last verified on 03-04-2026', 0, 0, 0, 1790961795064) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a7c2c646c6af0097', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change the voice: Someone has stolen my wallet.', '{"A":"My wallet is being stolen.","B":"My wallet is stolen.","C":"My wallet has been stolen.","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation My wallet has been stolen.In passive voice, the correct structure for recent events uses "has been" with the past participle.It indicating that the action occurred recently but the focus is on the result.', 0, 0, 0, 1790961795064) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1c2e04c298c1183a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Which type of sentence contains verb and is not converted into passive voice?', '{"A":"Linking","B":"Intransitive","C":"Transitive","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Intransitive verbs do not take a direct object, so they cannot be converted into passive voice.', 0, 0, 0, 1790961795064) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bcddb116087eb4a0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change the voice: Please help me.', '{"A":"You are requested to help me.","B":"You are being requested to help me.","C":"You were requested to help me.","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In passive voice, "Please" changes to a polite request: You are requested.The tense remains present, so "are requested" is correct.', 0, 0, 0, 1790961795064) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_56dfd169c1769b14', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change the voice: I know him.', '{"A":"He is known to me","B":"He is known by me","C":"He has been known to me","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice: I (subject) know (verb) him (object).Passive Voice: He (object → subject) is known to me.', 0, 0, 0, 1790961795064) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_df504752d0a2b7fe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Choose the correct active/passive voice: People made him king.', '{"A":"People made them king","B":"He was made king by the people","C":"He made king by the people","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In passive voice, the object “him” becomes the subject “he.”Correct transformation: “People made him king.” → “He was made king by the people.”', 0, 0, 0, 1790961795160) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e4a9ee46099c73c6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Choose the correct active voice/passive voice: I have been invited to the party.', '{"A":"To a party I had been invited","B":"Someone had invited me to party","C":"Someone has invited me to the party","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The given sentence “I have been invited to the party” is passive voice.Its correct active voice form is “Someone has invited me to the party.”', 0, 0, 0, 1790961795160) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_11d49eb81923a71b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change the voice: Which teacher teaches you English?', '{"A":"By which teacher are you taught English?","B":"By which teacher were you taught English?","C":"By which teacher will you taught English?","D":"By which teacher should you taught English?"}', 'A', NULL, 0, 0, 0, 1790961795160) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6e649f59a35bc1be', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'You must obey your parents. (Passive Voice)', '{"A":"Your parents must obeyed by you","B":"Your parents must been obeyed by you","C":"Your parents must be obeyed by you","D":"Your parents must being obeyed by you","E":"All are wrong"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice: You must obey your parents.Passive Voice: Your parents must be obeyed by you. Use be in passive voice.Use third form of a verb in passive voice', 0, 0, 0, 1790961795160) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_440208627415a14a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change the voice: Please give me your pen and take your seat.', '{"A":"Let your pen given me and take your seat.","B":"You are requested to give me your pen and take your seat.","C":"You are warned to give me your pen and take your seat.","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation You are requested to give me your pen and take your seat.This option is polite and correctly conveys a formal request, maintaining the original meaning while using appropriate language.', 0, 0, 0, 1790961795160) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_49b6ab723736d2da', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change the voice: The money was stolen by an employee of the bank.', '{"A":"An employee of the bank stole the money.","B":"An employee of the bank had stolen the money.","C":"An employee of the bank steal the money.","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An employee of the bank stole the money.The original sentence is in past simple passive ("was stolen").In active voice, it becomes past simple active: "stole the money."', 0, 0, 0, 1790961795160) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ca659de4c688c582', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change the voice: The held a meeting very early.', '{"A":"A meeting was hold by them very early.","B":"A meeting will be held by them very early.","C":"A meeting was held by them very early.","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A meeting was held by them very early.The original sentence is in simple past tense: held → passive form is was/were + past participle."Meeting" is singular, so use was held.', 0, 0, 0, 1790961795160) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_10ce9fa18c1103f1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change the voice: Why did you disobey your parents?', '{"A":"Why were your parents disobeyed by you?","B":"Why do your parents was disobey by you?","C":"Why your parents was disobeyed by you?","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Why were your parents disobeyed by you?In passive voice, the object (your parents) becomes the subject, and the verb adjusts to match the correct tense and structure.', 0, 0, 0, 1790961795160) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8cb48fedc3a91588', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change the voice: "Who taught you English"?', '{"A":"By whom was you taught English?","B":"By whom you were taught English?","C":"By which were you taught English?","D":"By who were you taught English?"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct passive voice of "Who taught you English?" is "By whom were you taught English?".In passive voice, the object of the active sentence becomes the subject."Who" changes to "whom" to reflect the passive structure correctly.', 0, 0, 0, 1790961795244) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2026a469ffcb3f35', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change the voice: Amjad has solved the the issue.', '{"A":"The issue have been solved by Amjad.","B":"The issue has been solved by Amjad.","C":"The issue was solved by Amjad.","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice: Amjad has solved the the issue.Passive voice: The issue has been solved by Amjad.Passive voice formula of Present Perfect Tense: Object + has/have + been + past participle (V3) + (by + subject).', 0, 0, 0, 1790961795244) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_336c9cf786fb4b48', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change the voice: The child could not have done this mischief.', '{"A":"This mischief could not been done by the child.","B":"This mischief could not have been done by the child.","C":"This mischief could not be done by the child.","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active voice: The child could not have done this mischief.In passive voice, structure:could not have + been + past participleSo: "This mischief could not have been done by the child." is correct.', 0, 0, 0, 1790961795245) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8e2cfc78b3c9e0a5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change the voice: They were laughing at her.', '{"A":"She was laughed at by them.","B":"They were being laughed at by her.","C":"She was being laughed at by them.","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The active sentence "They were laughing at her" is in past continuous tense.In passive voice, it becomes:"She was being laughed at by them."Structure: was/were being + past participle (laughed).', 0, 0, 0, 1790961795245) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_544c7d0f3e042824', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change the voice: The People elected him the president of their country.', '{"A":"He has been elected the president of thier country by the people.","B":"He was elected the president of their country by the people.","C":"He was being elected the president of thier country by the people.","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active voice: The People elected him the president of their country.This is simple past tense, so the passive voice should also be in simple past → was elected.The correct structure:Subject + was elected + complement + by + agent→ He was elected the president of their country by the people.', 0, 0, 0, 1790961795245) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2bc3cea6f3344097', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change the voice: We have warned you.', '{"A":"You have been warned.","B":"We have you warned.","C":"Warned you have been.","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Given sentence is in Present Perfect tense and It is in active Voice. Rule : Subject + (has / have) + been +V3 + Optional Agents.', 0, 0, 0, 1790961795245) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_93c56a0c4bd98424', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change the voice: Don’t mistrust the sincere.', '{"A":"Let the sincere not be mistrusted.","B":"Let the sincere not being mistrusted.","C":"Let the sincere not to be mistrusted.","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Negative imperative in passive voice uses: "Let + object + not be + past participle.""Don’t mistrust" becomes "Let ... not be mistrusted."Hence, "Let the sincere not be mistrusted" is correct.', 0, 0, 0, 1790961795245) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c0857851ed99044c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change the voice: They have completed the project.', '{"A":"The project is completed by them","B":"The project had been completed by them","C":"The project has been completed by them","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sentence "They have completed the project" is in the active voice, and the passive form is "The project has been completed by them".This maintains the same tense (present perfect) while changing the subject and object.', 0, 0, 0, 1790961795245) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ae9c981a09d4dfff', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change the voice: Let us play together.', '{"A":"It is suggested that we should  play together","B":"It was suggested that we should  play together","C":"It will be suggested that we should  play together","D":"It should be suggested that we should  play together"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice: Let + us + first form of a verb.Passive Voice: It is suggested + that + we + should + first form of a verb.Active Voice: Let us play together. Passive Voice: It is suggested that we should play together.', 0, 0, 0, 1790961795338) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5d87e0e53dec3cb3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change the voice: She has discussed the matter with her teacher.', '{"A":"The matter has discussed with her teacher by her.","B":"The matter has been discussed with her teacher by her.","C":"The matter is being discussed with her teacher by her.","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The matter has been discussed with her teacher by her.Rules of Voice Change (Present Perfect Tense):Active: Subject (She) + has/have + past participle (discussed) + object (the matter).Passive: Object (The matter) + has/have been + past participle (discussed) + by + subject (her).', 0, 0, 0, 1790961795338) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_35ce188e1d873b7a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change the voice: The Engineers are repairing all the broken bridges.', '{"A":"All the broken bridges are being repaired by the Engineers.","B":"All the broken bridges were repaired by the Engineers.","C":"All the broken bridges are repaired by the Engineers.","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation All the broken bridges are being repaired by the Engineers."Are repairing" is present continuous tense → passive becomes "are being repaired".Subject (The Engineers) becomes agent at the end: "by the Engineers".', 0, 0, 0, 1790961795338) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0e2010e4eff91d7a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Choose the correct passive voice: They sent a parcel on Monday.', '{"A":"A parcel has been sent by them","B":"A parcel was sent by them on Monday","C":"A parcel is sent by them on Monday","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sentence is in simple past tense, so the passive form should be "was sent.""A parcel was sent by them on Monday" correctly maintains the tense and structure.', 0, 0, 0, 1790961795338) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6b23750c2e01ee7f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change into passive voice: We do not waste time.', '{"A":"Let time be saved","B":"Let time be wasted","C":"Time is not wasted by us","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active: We do not waste time.Passive: Time is not wasted by us.(Subject becomes the object, and the verb is changed appropriately.)', 0, 0, 0, 1790961795338) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a7af81f641931a9f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'What is the active voice of the sentence: "Let the door be shut"?', '{"A":"Shut the door","B":"The door is shut","C":"You are shutting the door","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Imperative passive sentences starting with "Let" become direct commands in active voice."Let the door be shut" → "Shut the door" in active voice.', 0, 0, 0, 1790961795338) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_828d46442d74adb2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Choose the correct passive voice of the sentence: "Who taught you such things?"', '{"A":"By whom were you taught such things?","B":"By whom you were taught such things?","C":"By who were you taught such things?","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation By whom were you taught such things?In passive voice, the structure changes to "By whom + auxiliary verb + subject + past participle.""Were" is correctly placed before "you" to maintain proper question formation.', 0, 0, 0, 1790961795338) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_98afbb72c0a38862', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change the voice: He asked me if I could drive a car.', '{"A":"I was asked I could drive a car","B":"I was requested if I could drive a car","C":"I were asked if I could drive a car","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct passive voice is: I was asked if I could drive a car."Asked" remains unchanged, and the structure follows: Subject + was/were + past participle.', 0, 0, 0, 1790961795338) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f2bf63d4c830b26d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change from Active to Passive voice: "A doctor wrote the book."', '{"A":"The book is written by a doctor","B":"The book was written by a doctor","C":"The book was being written by a doctor","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In passive voice, the object of the active sentence ("the book") becomes the subject, and the verb tense remains consistent (past tense: "was written").The passive structure emphasizes the action or the object rather than the doer (the doctor).', 0, 0, 0, 1790961795422) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_539eaf63383d2937', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Choose the correct passive voice: Elizabeth keeps pets.', '{"A":"Pets are being kept by Elizabeth","B":"Pets are keeped by Elizabeth","C":"Pets are kept by Elizabeth","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sentence is in simple present tense, so the passive voice follows the structure:Object + is/are + past participle + by + subjectHence, "Pets are kept by Elizabeth" is correct.', 0, 0, 0, 1790961795422) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bee258bafb0cea5a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Passive Voice: He does not sing a song.', '{"A":"A song is not being sung by him","B":"A song was not being sung by him","C":"A song is not sung by him","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In passive voice, the object of the active sentence becomes the subject."A song is not sung by him" is the correct passive construction for the present tense.', 0, 0, 0, 1790961795422) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_47cc4abfe20ccd93', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change the voice: "The rainy season breeds mosquitoes".', '{"A":"Mosquitoes are bred by the rainy season","B":"Mosquitoes is bred by the rainy season","C":"Mosquitoes are breeded by the rainy season","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sentence is in active voice with a present tense verb.In passive voice, the object "mosquitoes" becomes the subject, and "breeds" changes to "are bred."', 0, 0, 0, 1790961795422) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_89c23c055b21ddcc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change the voice: "Tara makes breakfast at 6 AM".', '{"A":"Breakfast are made by Tara at 6 AM","B":"Breakfast is made by Tara at 6 AM","C":"Breakfast has made by Tara at 6 AM","D":"Breakfast have made by Tara at 6 AM"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In passive voice, the subject "breakfast" is acted upon, and "is made" is the correct verb form to match the present simple tense.The structure follows: Object + is/are + past participle + by + subject.', 0, 0, 0, 1790961795422) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1a74d80a8cc7d5bf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change the voice: I will have finished that book.', '{"A":"That book will have been finished by me","B":"That book has been finished by me","C":"That book will be finished by me","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In passive voice, the object ("that book") becomes the subject, and the verb tense is adjusted accordingly.The sentence changes from "I will have finished that book" to "That book will have been finished by me."', 0, 0, 0, 1790961795422) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2105dad75cf3895f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Turn to Passive voice: The girl is riding the horse?', '{"A":"The horse has been ridden by the girl","B":"The horse was being ridden by the girl","C":"The horse is being ridden by the girl","D":"The horse is ridden by the girl"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct passive voice transformation is "The horse is being ridden by the girl."This conveys that the action of riding is currently happening, with the focus shifted to the horse.', 0, 0, 0, 1790961795422) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3fd4084a994c7035', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Select the correct Passive voice speech of the sentence: “Why did he not invite me in dinner?” the given choice?', '{"A":"Why I was not invited by him to dinner","B":"Why was I not invited by him to dinner","C":"Why I was not invite by him to dinner","D":"Why was I not invite by him to dinner"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In passive voice, the structure is "Why + was/were + subject + past participle + by agent.""Invited" is the correct past participle of "invite," making this sentence grammatically accurate.', 0, 0, 0, 1790961795422) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_131cb0d87f69e595', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Find out the correct Passive Voice sentence: "They showed the visitors the historical monuments of Lahore".', '{"A":"The historical monuments had been shown to the visitors.","B":"The visitors will be shown the historical monuments of Lahore.","C":"The visitors were shown the historical monuments of Lahore","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The visitors were shown the historical monuments of Lahore.Past Simple passive: was/were + past participle (V³).Showed changes to were shown.The object "the visitors" becomes the subject.Last updated 18-07-2026 by NA', 0, 0, 0, 1790961795530) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_89dccec6f6f23f26', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change the Voice: Can those happy moments be ever forgotten by me?', '{"A":"Shall I ever forget those happy moments?","B":"Can I ever forget those happy moments?","C":"Will I ever forget those happy moments?","D":"Could I ever forget those happy moments?"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Can I ever forget those happy moments?The sentence is changed from passive to active voice, maintaining the same meaning while restructuring it.', 0, 0, 0, 1790961795530) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_218cae65c8aef551', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Passive voice of: "The box can contain no more".', '{"A":"No more this box can contain","B":"No more can be contained in the box","C":"No more could be contained in the box","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The passive voice of the sentence "The box can contain no more" is "No more can be contained in the box".This sentence structure emphasizes the limitation of the box''s capacity, rather than the box itself.', 0, 0, 0, 1790961795530) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f68d28b169404fe8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'In a sentence in passive voice _______ is not required.', '{"A":"Subject","B":"Object","C":"Verb","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In a passive voice sentence, the subject is not always required, as the focus is on the action and the object.For example, "The cake was eaten" (no subject mentioned).', 0, 0, 0, 1790961795530) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bd98b3998428ecf8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change the voice of the following sentences: "Do you know my father"?', '{"A":"Is my father known to you?","B":"Did you know my father?","C":"Does my father known to you?","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active voice emphasizes the doer (you), while passive voice emphasizes the receiver (my father).The passive voice construction "Is my father known to you?" makes the focus on "my father" and whether they are known to you.', 0, 0, 0, 1790961795530) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_acaf377270463dbf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change the Voice of the following sentence: "Have you laughed at them?"', '{"A":"\"Why have you laughed at them?\"","B":"\"Have they been laughed at by you?\"","C":"\"You have been laughed at by them.\"","D":"\"They have been laughed at by you.\""}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The passive voice of the sentence "Have you laughed at them?" is: Have they been laughed at by you?', 0, 0, 0, 1790961795530) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_02d1d35e52b67153', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Turn to Passive voice: "The child chose the hat."', '{"A":"The hat should be chosen by the child","B":"The hat was being chosen by the child","C":"The hat was chosen by the child","D":"The hat is chosen by the child"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The hat was chosen by the child is the correct passive form.In passive voice:The object "hat" becomes the subject.The verb "chose" is changed to "was chosen" to reflect the action done by the child.', 0, 0, 0, 1790961795530) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0f3a03847a592699', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change the Voice: Our lives are being spent in expectation?', '{"A":"We are spending our lives in expectation","B":"We was spending our lives in expectation","C":"We were spending our lives in expectation","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct active voice is: "We are spending our lives in expectation."This correctly converts the sentence from passive to active voice.', 0, 0, 0, 1790961795530) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e1e734be66721ed6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'The dealer has sold the car? (Passive Voice)', '{"A":"The car has been sold by the dealer","B":"The car have been sold by the dealer","C":"The car had been sold by the dealer","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This sentence belongs to Present Perfect TenseActive: Subject + Verb + objectPassive: Object + has + been + main verb + by + subject', 0, 0, 0, 1790961795624) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_063c8691b7039f56', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'He helped me. (Passive Voice)', '{"A":"I am helped by him","B":"I will be helped by him","C":"I was being helped by him","D":"I was helped by him"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This sentence belongs to Past Indefinite Tense.Active Voice: He helped me. Passive Voice: I was helped by him.', 0, 0, 0, 1790961795624) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_882f2df12ce46824', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'The police inquired into the case. (Passive Voice)', '{"A":"The case was inquired by the police","B":"The case is inquired by the police","C":"The case should be inquired by the police","D":"The case will be inquired by the police","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Past Indefinite Tense Active formula: Subject + past tense form of the verb + objectActive: The police inquired into the case. Passive formula: Object of the active sentence + was/were + past participle form of the verb + by + subject of the active sentence Passive: The case was inquired by the police OR The case was inquired into by the police.', 0, 0, 0, 1790961795624) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_18770a82862e4a66', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'It is time to give final warning. (Passive Voice)', '{"A":"It is time to give final warning.","B":"It is time for the final warning to be given.","C":"It is time to be given final warning.","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice: It is time to give final warningPassive Voice: It is time for the final warning to be given.Passive voice formula: It is time + for + noun/pronoun + to be + v3.', 0, 0, 0, 1790961795624) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_85366b36d7e78df5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change the voice: The government has not approved the construction.', '{"A":"The construction has not been approved by the government","B":"The construction is not been approved by the government","C":"The construction will not have been approved by the government","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active: Subject + has/have+ v3+ objectPassive: Object + has/have + been + v3 + by + subject.', 0, 0, 0, 1790961795624) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0fd1528ed5e49cb7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Sajid appears to behave ______, actively helping class fellows to have their home assignments done', '{"A":"Aggressively","B":"Rudely","C":"Cooperatively","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ساجد باہمی تعاون کے ساتھ برتاؤ کرتے نظر آتے ہیں، کلاس فیلوز کو ان کے گھر کے کام کرنے میں فعال طور پر مدد کرتے ہیں*"Cooperatively "is best to keep the meaning of the original sentence. Sajjid shows positive behaviour. So, "OptionA" is the best **if we choose another option "it changes the meaning of the whole sentence"Aggressivelyجارحانہ انداز میںRudelyبدتمیزی سے***ND4-12-2022', 0, 0, 0, 1790961795624) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_eba8a74499592590', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'The boys were playing cricket. Passive Voice?', '{"A":"Cricket was being played by the boys.","B":"Cricket was played by the boys.","C":"Cricket has been played by the boys.","D":"Cricket had been played by the boys."}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The given sentence is in Past Continuous Tense and it is in active voice. We need to change it into Passive voice.Rule :Subject + (was /were) + being + V3 + Optional Agents.', 0, 0, 0, 1790961795624) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c07c1fdc8e750304', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Was she sewing the curtains? (Make Passive Voice)', '{"A":"Were the curtains being sewed by her?","B":"Are the curtains being sewed by here?","C":"Will the curtains being sewed by here?","D":"Was the curtains being sewed by here?","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Past Continuous TenseActive Voice Formula: Subject + was/were + v4+ object.Passive Voice Formula: Object + was/were being + v3 + by + subject', 0, 0, 0, 1790961795624) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_23b484688f3a1967', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Do not laugh at me. (Passive Voice)', '{"A":"Let me be not laughed at","B":"Let I be not laughed at","C":"Let we be not laughed at","D":"Let my be not laughed at","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice: Do not laugh at me. Passive Voice: Let me be not laughed at. Active Voice: Let + indirect object + first form of a verb + direct object.Passive Voice: Let + direct object + be + third form of a verb + by + indirect object.', 0, 0, 0, 1790961795754) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_15f143b865f03ba8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'The doctor had examined him. (Passive Voice)', '{"A":"He has been examined by the doctor","B":"He had been examined by the doctor","C":"He will have been examined by the doctor","D":"He could have been examined by the doctor","E":"All of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This question belongs to Past Perfect Tense.Rule in passive: Object + had been + 3rd form of a verb + by + subject', 0, 0, 0, 1790961795754) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ccbf0a161f338b03', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Fazal attends a wedding party. write its passive voice?', '{"A":"A wedding party is attended by Fazal.","B":"A wedding party is being attended by Fazal.","C":"A wedding party was being attended by Fazal.","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fazal attends a wedding party. کا ہےPresent Indefinite یہ فقرہ لگے گاis....helping verbبنائیں گے تو اس کے ساتھ passiveجب ہم اس کو', 0, 0, 0, 1790961795754) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b1635fab82ff2487', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', '"Why did he defraud you of your earnings" choose the correct Active voice', '{"A":"Why I  was defraud of your earnings","B":"Why were you defraud of your earning","C":"Why were you defraud of my earning","D":"Why was he defraud of my earning"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice Passive Voice (Auxiliary Verb – is/am/are)Subject + V1+s/es+ object Object+ is/am/are+ V3+ by + subjectSubject + Do/does+ not + V1 + Object Object + is/am/are+ not + V3+ by SubjectDoes+ Subject+ V1+Object+? Is/am/are + Object+ V3+ by subject +?', 0, 0, 0, 1790961795754) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_67ab31528583d16a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Did you do it on purpose? (Passive Voice)', '{"A":"Was it being done by you on purpose","B":"Was it done by you on purpose","C":"Were you doing it on purpose","D":"All are correct","E":"All are wrong"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Passive voice: Did you do it on purpose?Active voice: Was it done by you on purpose (was /were) + subject + V3 + Optional Agents.ND2-08-2023', 0, 0, 0, 1790961795754) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_81c2e5572aa893e9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Cut the tree. Change into Passive Voice', '{"A":"You were ordered to cut the tree","B":"You will be ordered to cut the tree","C":"You can be ordered to cut the tree","D":"You are ordered to cut the tree","E":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sentence having an order.Active Voice: First form of verb + ObjectPassive Voice: You + are + ordered + to + first form of verb + object.', 0, 0, 0, 1790961795754) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_93971e8bd8a48b56', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Select the correct passive voice speech of the sentence "She reads a book" from the given choices.', '{"A":"A book was read by her","B":"A book is read by her","C":"she is reading a book","D":"she was reading a book"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation She reads a book (Present Indefinite tense) For the passive voice, we use Present continuous tense', 0, 0, 0, 1790961795754) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_acb462e8fc470663', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change the voice: Sweets are not liked by us', '{"A":"We do not like sweets","B":"Sweets have not been liked by us","C":"We are not liking sweets","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Sweets are not liked by us" is Passive It is used here Present continues when we change to Active voice we will use Present Indefinite tense so, Us = we Are not = do not Liked = like Sweet= Sweets', 0, 0, 0, 1790961795754) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f6ece4b97141e109', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Active Voice of “Indiscipline should not be encouraged by us”.', '{"A":"We shall not encouraging indiscipline","B":"We have not encouraging indiscipline","C":"We should not encourage Indiscipline","D":"We must not encouraged indiscipline","E":"All of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We should not encourage Indiscipline because "should" has not been mentioned in option A, B & C.Note:- It may be noted that more valuable details about this question shall be upload here very soon.', 0, 0, 0, 1790961795880) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_171d17a31bf83ee6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'A fair resolution to the matter is being sought by the Board of Directors: ( Choose the correct Passive voice)', '{"A":"The board of directors are seeking a fair resolution to the matter","B":"The directors are seeking a fair resolution to the matter","C":"The board of directors were seeking a fair resolution to the matter","D":"The board of directors are seeks a fair resolution to the matter"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790961795880) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_199d7352245b4526', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Select the correct passive voice speech of the sentence "I am writing a letter" from the given choice', '{"A":"A letter has been written by me","B":"Aletter has written by me","C":"A letter is being written by me","D":"A letter was being written by me"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In case present continuous tense when we make passive we add begin with helping verb Like is being.I am writing a letter A letter is being written by me', 0, 0, 0, 1790961795881) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6b087d352fa34f45', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change the voice: The burglar destroyed several items in the room. Even the carpet has been torn.', '{"A":"Several items destroyed in the room by the burglar. Even the carpet he has torn","B":"Several items in the room were destroyed by the burglar. Even the carpet was torn","C":"Including the carpet, several items in the room have been torn by the burglar","D":"The burglar, being destroyed several items in the room, also carpet has torn","E":"All Of The Above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Above it contains two sentence one is in Past Simple sentence (Active Voice) and Second sentence is in Present Perfect tense (Passive Voice). We change First sentence according to voice rule and second sentence also be change according to same rule but tense of both sentence become same.', 0, 0, 0, 1790961795881) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a653a052c136b378', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Maaz appears to behave _____, actively helping class fellows to have their home assignment done.', '{"A":"Mysteriously","B":"Rudely","C":"Cooperatively","D":"Aggressively"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Sentence asks you to look for a word that describes how Maaz behaves. The information after the comma told that Maaz “actively help his class fellows”. So Cooperatively is Correct.', 0, 0, 0, 1790961795881) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f6079e0d1849e773', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_voice', 'Change in to passive voice? Open the door.', '{"A":"Let the door be open.","B":"Let the door be opened.","C":"Let the door be opene.","D":"Let the door opened."}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active voice:- Open the door. Passive voice:- Let the door be opened.For order:Active Voice Formula: V + object.Passive Voice Formula: Let + subject + be + VLast updated question by NS on 11 May 2026', 0, 0, 0, 1790961795881) ON CONFLICT(id) DO NOTHING;
INSERT INTO subject (id, user_id, name, parent_id, total_mcqs, created_at) VALUES ('top_eng_narration', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'Direct & Indirect Speech', 'top_english', 49, 1790961795971) ON CONFLICT(id) DO UPDATE SET total_mcqs = 49;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ad93f11a7cbba4f2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Change the narration: He said, "I am tired."', '{"A":"He told that he is tired.","B":"He said that I was tired.","C":"He said that he was tired.","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He said that he was tired.Am changes to was because the reporting verb said is in past tense.The pronoun I changes to he to agree with the subject.Last verified on 07-05-2026', 0, 0, 0, 1790961796142) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a8642736aabf1fd2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'He said to her, "May you succeed" (Change into indirect narration).', '{"A":"He prayed to God that she may succeed","B":"He said to her that she might succeed","C":"He told her that she might succeed","D":"He wished her success"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He wished her success.“May you succeed” expresses a wish or blessing.In indirect speech, such sentences are changed into wish + object + noun form.Last verified on 11-06-2026', 0, 0, 0, 1790961796142) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3630d55df2925227', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Change the narration: He exclaimed with joy that Pakistan had won the Sahara Cup.', '{"A":"He said, \"Hurrah! Pakistan has won the Sahara Cup\"","B":"He said, \"Pakistan has won the Sahara Cup\"","C":"He said, \"Pakistan won the Sahara Cup\"","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He said, "Hurrah! Pakistan has won the Sahara Cup."The phrase "exclaimed with joy" suggests happiness or excitement, reflected by "Hurrah!" in direct speech. The past perfect tense in indirect speech ("had won") is converted to the present perfect ("has won") in direct speech.Last verified on 07-05-2026', 0, 0, 0, 1790961796142) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c85354f47421033c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Change the narration: "I have finished my work," she said.', '{"A":"She said that she had finished her work.","B":"She said the she has finished her work.","C":"She said the I had finished her work.","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation She said that she had finished her work.In indirect speech, the present perfect (have finished) changes to past perfect (had finished), and “that” is added.Last verified on 05-05-2026', 0, 0, 0, 1790961796142) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b8771e14db32eafa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Change into Indirect: He said, "Honesty is the best policy.“', '{"A":"He said that Honesty is the best policy","B":"He said that Honesty was the best policy","C":"He said that Honesty would be the best policy","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He said that Honesty is the best policy.This sentence expresses a universal truth.In indirect speech, universal truths do not change tense.Only quotation marks are removed and “that” is added.The meaning remains exactly the same.Last verified on 20-04-2026', 0, 0, 0, 1790961796142) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7b1649a897e6664e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Change the narration: She says, "She was playing"?', '{"A":"She says  she was playing","B":"She says that she was playing","C":"She says that she had been playing","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Direct: She says, “She was playing.”Indirect: She says that she was playing.The reporting verb “says” is in present tense, so the tense of the reported speech does not change.The pronoun “she” remains the same (assuming it refers to the same person).', 0, 0, 0, 1790961796142) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8d7cbb67bb74a88f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Convert the following sentence to indirect speech: "Don''t sleep."', '{"A":"You are advised not to sleep.","B":"You are instructed not to sleep.","C":"You are asked not to sleep.","D":"You are told not to sleep."}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In indirect speech, the imperative sentence "Don''t sleep" is converted into "You are instructed not to sleep." The reporting verb "instructed" is used to convey the command.Last verified on 04-02-2026', 0, 0, 0, 1790961796142) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9fca86f92a55ae17', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Change the narration: She said, “I will call you tomorrow.”', '{"A":"She said that she called me tomorrow.","B":"She said that she would call me the next day.","C":"She said that she would call me tomorrow.","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation She said that she would call me the next day.In indirect speech, "will" changes to "would," and "tomorrow" becomes "the next day" to reflect the shift in time.', 0, 0, 0, 1790961796142) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_157e153a9776d360', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Convert the Direct speech into Indirect speech: Asad said, "I shall be 21 tomorrow."', '{"A":"Asad said that I shall be 21 tomorrow","B":"Asad said that he shall be 21 tomorrow","C":"Asad said that he would be 21 the following day","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Asad said that he would be 21 the following day.In indirect speech, “shall” changes to “would” when the reporting verb is in the past tense.“Tomorrow” becomes “the following day.”', 0, 0, 0, 1790961796340) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3598f25ca94edc04', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Choose the correct indirect speech for the following sentence: She said, ''I am going to the market.', '{"A":"She said that she is going to the market.","B":"She said that I was going to the market.","C":"She said that she was going to the market.","D":"She said that she had gone to the market."}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The reporting verb "said" is in the past tense.Therefore, the verb in the reported speech also shifts one step back in tense:"Am going" (present continuous) → "was going" (past continuous).The pronoun "I" changes to "she" to match the subject.Correct Answer: c) She said that she was going to the market.', 0, 0, 0, 1790961796341) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0f786ae63ea3eb7d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Change into indirect narration: He said, "What a beautiful scene!"', '{"A":"He exclaimed that it was a very beautiful scene","B":"He wondered that it was a beautiful scene","C":"He exclaimed what a beautiful scene it was","D":"He said that what a beautiful scene it was"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He exclaimed that it was a very beautiful sceneExclamatory sentences change to “exclaimed that” in indirect speech.The sentence expresses strong emotion, so “exclaimed” is used appropriately.', 0, 0, 0, 1790961796341) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_58729002a0a817df', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Change the narration: He said he goes for a walk every morning.', '{"A":"He said, “I went for a walk every morning.”","B":"He said, “I will go for a walk every morning.”","C":"He said, “I go for a walk every morning.”","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He said, “I go for a walk every morning.”Said is in the past tense.Simple Present → Simple Past in indirect speech.I → He (pronoun changes).Go → Went after backshifting.Last updated 18-07-2026 by NA', 0, 0, 0, 1790961796341) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c10274bf8f30711e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Change the narration: "I’ll clean the car tomorrow," Tim said to his father.', '{"A":"Tim told his father that he would clean the car tomorrow.","B":"Tim told his father that he would clean the car the following day.","C":"Tim said to his father that he will clean the car the following day.","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tim told his father that he would clean the car the following day."I’ll" becomes "he would" in reported speech."Tomorrow" changes to "the following day."', 0, 0, 0, 1790961796341) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f16c85d2725159b1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Change the narration: He said to me ,"I expect you to attend the function."', '{"A":"He told me that he expected me to attend the function.","B":"He told me that he had expected me to attendance the function.","C":"He told me that he have expected me to attend the function.","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He told me that he expected me to attend the function.Direct speech: He said to me, "I expect you to attend the function."Reported speech: "Said to" changes to told, and present tense expect changes to past tense expected."You" becomes "me", and "to attend" remains the same (infinitive structure).', 0, 0, 0, 1790961796341) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_562c1af38dbc6762', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Change the narration: "I’ve forgotten to bring my lunch with me," he said.', '{"A":"He did inform that he had forgotten to bring his lunch.","B":"He said that he had forgotten to bring his lunch with him.","C":"He said he had forgot his lunch to bring.","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He said that he had forgotten to bring his lunch with him.Direct speech: "I’ve forgotten..." (present perfect)Indirect speech: changes to past perfect → "he had forgotten..."Pronoun "my" changes to "his".', 0, 0, 0, 1790961796341) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_20923211394e49fc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Change the narration: I said to Riaz "Who are you waiting for?"', '{"A":"I asked Riaz that for whom you are waiting.","B":"I asked Riaz who he was waiting for.","C":"I asked Riaz whom for he is waiting.","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I asked Riaz who he was waiting for.The question "Who are you waiting for?" changes to "who he was waiting for" in indirect speech.The tense shifts from present continuous to past continuous, and "you" changes to "he".No question mark is used in indirect speech.', 0, 0, 0, 1790961796341) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_89dd58f6f7a5b84f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Change the narration: "Will you be home soon?" she asked her husband.', '{"A":"She asked her husband would you be home soon.","B":"She asked her husband if he would be home soon.","C":"She told her husband will he be home soon.","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation She asked her husband if he would be home soon."Will you be..." (direct question) changes to "if he would be..." (indirect speech).The question form becomes a statement in reported speech, and "will" changes to "would."', 0, 0, 0, 1790961796483) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_58403cacb25b3410', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Change the narration: Nazir said, "I did my duty with full justice."', '{"A":"Nazir said that he has done his duty with full justices","B":"Nazir said he has done his duty with full justice.","C":"Nazir said that he had done his duty with full justice.","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Direct Speech: Nazir said, "I did my duty with full justice."In indirect speech:"I" becomes "he" (subject change)"did" (past simple) becomes "had done" (past perfect) to maintain the timeline correctly in indirect speech.So, the correct indirect speech would be:Nazir said that he had done his duty with full justice.', 0, 0, 0, 1790961796483) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1498700c5b10a50a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Change the narration: I told him that he was not working hard.', '{"A":"I said to him \"he is not working hard.\"","B":"I told to him \"you are not working hard.\"","C":"I said to him \"you are not working hard.\"","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Direct speech of "I told him that he was not working hard." is:"I said to him, ''You are not working hard.''""He was" in indirect becomes "You are" in direct.', 0, 0, 0, 1790961796483) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_03c9d46940f2e86b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Change the narration: "I’ve been working for the same company since 1960" he said to me.', '{"A":"He told me that he had been working for the same company since 1960.","B":"He said to me that he have been working for the same company for 1960.","C":"He said to me that he had been working for the same company for 1960.","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He told me that he had been working for the same company since 1960.Direct speech: "I’ve been working..." (present perfect continuous)Indirect speech: changes to past perfect continuous → "he had been working...""Since 1960" stays the same because it refers to a specific point in time.', 0, 0, 0, 1790961796483) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f0f4865ee473bafa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Change the narration: Emily said, "I may leave tomorrow."', '{"A":"Emily said that she might leave tomorrow.","B":"Emily said that she might leave the next day.","C":"Emily informed me to leave tomorrow.","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Emily said that she might leave the next day.In indirect speech, "may" changes to "might," and "tomorrow" is adjusted to "the next day" to reflect the change in time.', 0, 0, 0, 1790961796483) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_32971eabcec6a6af', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Change the narration: He said to me, "Why are you sad today"?', '{"A":"He had asked me why I am sad today.","B":"He asked me why I was so sad that day.","C":"He said to me why I was sad that day.","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Direct speech: He said to me, "Why are you sad today?"Indirect speech rules:Said to → changes to asked (since it''s a question).Are → was (present to past).Today → that day (change in time expression).He asked me why I was so sad that day.', 0, 0, 0, 1790961796483) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ac8b61d68706b7de', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Change the narration: Shahid''s brother said to him, “Please wait for me.”', '{"A":"Shahid''s brother order him to wait for him","B":"Shahid''s brother requested him to wait for him","C":"Shahid''s brother suggested him to wait for him","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The original sentence ("Please wait for me.") uses the word "Please," which indicates a polite request, not an order or suggestion.In indirect speech, such requests are reported using "requested + object + to + verb."', 0, 0, 0, 1790961796483) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c29489008c9eab58', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Change the narration: He said to me, "I was ill".', '{"A":"He told me that he had been ill.","B":"He said to me that I was ill","C":"He said to me that he has been ill.","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He told me that he had been ill.Rules of Narration Change:Reporting Verb: "Said to" → "Told" (more natural in reported speech).Tense Shift: Past ("was") → Past Perfect ("had been") (since the original statement was about a past condition).Pronoun Shift: "I" → "he" (to match the subject "He").', 0, 0, 0, 1790961796483) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cb310f513604bb37', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Change the narration: "Please don''t go away, he said to me.', '{"A":"He requested me not to go away.","B":"He begged that I should not go away.","C":"He told me not to go away.","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Correct Narration Change:The original sentence ("Please don''t go away," he said to me.) is an implored request (polite command).In indirect speech, "said to" changes to "requested" (for polite pleas) or "told" (neutral)."Don’t go away" becomes "not to go away" (infinitive structure in reported speech).', 0, 0, 0, 1790961796700) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_eb0d1a143fef988d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Choose the correct indirect speech: He said to his mother, “I will come home early this night.”', '{"A":"He told his mother that he will come home early that night.","B":"He told his mother that he would come home early that night.","C":"He said to his mother that he would come home early this night.","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He told his mother that he would come home early that night."Said to" changes to "told" in indirect speech."Will" changes to "would" in reported speech. "This night" changes to "that night" as per time expressions in indirect speech.', 0, 0, 0, 1790961796700) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c20a77fa49bcfc8c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Change into Indirect Speech: He said to me, "I have the duty."', '{"A":"He told me that he had the duty.","B":"He said me that he has the duty.","C":"He told me that he has the duty.","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He told me that he had the duty.Present perfect ("have") changes to past perfect ("had") in indirect speech.', 0, 0, 0, 1790961796700) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cffbe321587bf90a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Change into direct speech: She said, "How can I, a girl, wjo cannot ride or use sword or  lance, be of any help? Rather would I stay at home and spin beside my dear mother?"', '{"A":"She asked how she, a girl, who could not ride or use sword or lance, could be of any help. Rather would she stay at home and spin beside her dear mother.","B":"She asks that how she, a girl, who could not ride or use sword or lance, can be of any help. Rather would she stay at home and spin beside her dear mother.","C":"She explains that how she, a girl, who can not ride or use sword or lance, can be of any help. Rather would she stay at home and spin beside her mother.","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation She asked how she, a girl, who could not ride or use sword or lance, could be of any help. Rather would she stay at home and spin beside her dear mother.The reporting verb "said" changes to "asked" to match the question format in indirect speech.Tenses are correctly shifted from present to past ("can" → "could", "cannot" → "could not").The rest of the sentence maintains the original meaning and structure.', 0, 0, 0, 1790961796700) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fddd09e2ef87782b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Choose the correct indirect speech: She said to him, "can I do anything for you".', '{"A":"She asked him if she could do anything for him.","B":"She asked her if she could do anything for him.","C":"She asked to him if she could do anything for him.","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation She asked him if she could do anything for him.In indirect speech, "said to" changes to "asked" in yes/no questions.The pronoun "I" changes to "she," and "can" changes to "could" in reported speech.', 0, 0, 0, 1790961796700) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_aa928e33d640a6f0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Choose the correct indirect speech: "Please wait here till I return", she told him.', '{"A":"She requested him to wait till she returned.","B":"She should him to wait till she returned.","C":"She will him to wait till she returned.","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The word "Please" indicates a request, so the reporting verb becomes "requested".The verb tense and pronouns are correctly changed in indirect speech.', 0, 0, 0, 1790961796700) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e6a55e69b59c91d0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Change the narration: The master said to the servant, "Bring a new flower today."', '{"A":"The master ordered the servant to bring you a new flower that day.","B":"The master says the servant to bring him a new flower that day.","C":"The master ordered the servant to bring him a new flower that day.","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The master ordered the servant to bring him a new flower that day."Said to" changes to "ordered" in indirect speech for a command."Bring a new flower today" changes to "to bring him a new flower that day", adjusting pronouns and time expressions.', 0, 0, 0, 1790961796700) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_35c8e1fcf9e23209', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Choose the correct indirect speech: The peon said, “May I help you Sir”.', '{"A":"The peon respectfully asked if he could help him.","B":"The peon told that he would help him.","C":"The peon said that he could help him.","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The peon respectfully asked if he could help him."May I" in direct speech changes to "if he could" in indirect speech.The word "respectfully" is added to reflect the polite tone of the original sentence.', 0, 0, 0, 1790961796700) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_54b09f8d61a0db18', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Change into indirect: He said to me "Do you like rice"?', '{"A":"He asked me if I liked rice.","B":"He told me that I liked rice.","C":"He said to me that do you like rice.","D":"None of these."}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The reporting verb "said to" changes to "asked" in indirect speech.The question "Do you like rice?" is a yes/no question, so we use "if" or "whether" in indirect speech.The verb "like" changes to "liked" (backshift in tense).', 0, 0, 0, 1790961796812) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_004831e662f1b2fd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Choose the correct indirect speech: He said to them, “Will you listen to such a man”.', '{"A":"He asked them if they listen to such a man","B":"He asked them if they would listen to such a man","C":"He asked him if they would listen to such a man","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He asked them if they would listen to such a man.In indirect speech, the question form "Will you" changes to "if they would" and the pronouns are adjusted accordingly.The reporting verb "said to" changes to "asked" in a question.', 0, 0, 0, 1790961796812) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cc6503e89c0d6142', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Change narration: The mother said to her son, "May you be successful".', '{"A":"The mother prayed that his son might be successful","B":"The mother prayed by her son might be successful","C":"The mother prayed that her son might be successful","D":"The mother prayed that her son may be successful"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sentence is an optative sentence (expressing a wish), and "May you" changes to "might" in indirect speech.The pronoun "her" replaces "your" to maintain proper narration.', 0, 0, 0, 1790961796812) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_89a06f64608fcfba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'He said to me "please help me". change direct into indirect speech.', '{"A":"He requested me to help him","B":"He told me please help him","C":"He asked to help him","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When converting direct speech to indirect speech, the words spoken are reported rather than quoted directly. In this case, the direct speech is:"He said to me, ''Please help me.''"To convert this to indirect speech, we use the verb "requested" to report the action, and the words spoken are rephrased as:"He requested me to help him."', 0, 0, 0, 1790961796813) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2abb2ce1203c15cb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'He says, My name is Abdullah.(Narration)', '{"A":"He says that his name was Abdullah","B":"He says that his name is Abdullah","C":"He says that his name will beAbdullah","D":"He says that his name can be Abdullah","E":"All are wrong"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation If reporting verb is in Present Tense, we cannot change it into past.He says,"My father is sick."He says that his father is sick.He says,"My brother is a student."He says that his brother is a student.', 0, 0, 0, 1790961796813) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bd5aaffa73481c50', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Change into Indirect: I remember my sister taking me to the museum.', '{"A":"I remember I was taken to the museum by my sister.","B":"I remember being taken to the museum by my sister.","C":"I remember myself being taken to the museum by my sister.","D":"I remember taken to the museum by my sister."}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The question asks to convert a sentence into indirect speech (passive voice in this case)."I remember myself being taken to the museum by my sister." – The word "myself" is unnecessary and grammatically incorrect here.', 0, 0, 0, 1790961796813) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_742754a543c42799', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Change into Indirect: Haris said, "How clever I am."', '{"A":"Haris exclaimed that he was very clever.","B":"Haris exclaimed with sorrow that he was very clever.","C":"Haris exclaimed that we was very clever.","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sentence "Haris said, ''How clever I am''" is a statement, but the phrase "How clever I am" is an exclamation that indicates excitement or pride.So, the correct interpretation is that Haris exclaimed (or said with emphasis and excitement) that he was very clever.', 0, 0, 0, 1790961796813) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fae751ae361ad8b9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Change the narration: The old lady said to her son" Is it not your duty to help me in my old age"?', '{"A":"The old lady asked her son if it was not his duty to help her in her old age","B":"The old lady asked her son if it was not his duty to help him in her old age","C":"The old lady asked her son That it was not his duty to help her in her old age","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The original statement is a direct quote, whereas the correct answer is a reported speech, which is a more polite and formal way of expressing the same sentence.In reported speech, we change the sentence structure to:"She asked him + question word + subject + verb"So, the direct quote:"Is it not your duty to help me in my old age?"Becomes:"She asked him if it was not his duty to help her in her old age."', 0, 0, 0, 1790961796813) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7cf715199006dd95', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Complete the sentences in the reported speech: "Meet me at the cinema." he said.', '{"A":"He asked me to met him at the cinema.","B":"He asked me to meet you at the cinema.","C":"He asked me to meet him at the cinema.","D":"He asked me to me meet me at the cinema."}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When we report someone''s speech, we need to change the pronouns to match the context.In this case, "he" asked "me" to meet "him" (not "me" or "you").So, the correct reported speech is:"He asked me to meet him at the cinema."', 0, 0, 0, 1790961796919) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f9be719edab3f672', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Select the correct Indirect Speech of the sentence, She said, "my book is new" from the given options:', '{"A":"she told that my book was new","B":"she told that her book is new","C":"she told that she has new book","D":"she told that she possess new book"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation She said, "My book is new" (Present Continuous tense use here) she told that her book is new', 0, 0, 0, 1790961796919) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_813261c5c36605c4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Change the narration: She said to him, "Consult a doctor".', '{"A":"She ordered him to please consult a physician","B":"She told him that he should go to a medical practitioner","C":"She said to him to consult a doctor immediately","D":"She advised him to consult a doctor"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation She said to him, "Consult a doctor".She advised him to consult a doctor', 0, 0, 0, 1790961796919) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_069f8a4c1e866f4b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'He said to her ," What a hot day? choose the correct indirect speech', '{"A":"He said that it was a hot day","B":"He exclaimed that it was a hot day","C":"He exclaimed that it is a hot day","D":"He exclaimed sorrowfully that it was a hot day"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation General rules for changing direct speech into indirect speech. Omit all inverted commas or quotation marks. End the sentence with a full stop.', 0, 0, 0, 1790961796919) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f3bdfb1ef84b4a56', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'He reminded them to wish shandana when they were saying goodbye.(choose the correct narration)', '{"A":"HeHe said to them,","B":"He said to them,","C":"He said to they,","D":"He said to them,"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation narration is the action or process of narrating a story.', 0, 0, 0, 1790961796919) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9a1828ad454c647b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Find correct indirect speech of He asked: “Who speak French?”', '{"A":"He asked who speak French.","B":"They asked “Who speak French?”","C":"He wanted to know who spoke French","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He wanted to know who spoke French', 0, 0, 0, 1790961796919) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9f3666688d8e225e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Select the correct indirect speech of the sentence "He said my father is going with me" from the given choices', '{"A":"he told that his father was going with me","B":"I told that he was going with his father","C":"he told that he is going with his father","D":"he told that his father was going with him"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He said my father is going with me. (Present Continues tense) He told that his father was going with him (Past Continues tense)', 0, 0, 0, 1790961796919) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9a479d938ea6e97c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'They said to him "Do not tell a lie". change direct into indirect speech', '{"A":"They asked him to not told a lie.","B":"They forbade him to told a lie.","C":"They stopped him to telling a lie.","D":"They forbade him to tell a lie."}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation They said to him "Do not tell a lie"They forbade him to tell a lie.', 0, 0, 0, 1790961796919) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ba778468e94f4027', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_narration', 'Indirect speech of : She said, “I shall get up early in the morning”.', '{"A":"She said that she would get up early in the morning.","B":"She said that he will get up early in the morning.","C":"She asked that he would get up early in the morning.","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation She said, “I shall get up early in the morning”. She said that she would get up early in the morning.', 0, 0, 0, 1790961797005) ON CONFLICT(id) DO NOTHING;
INSERT INTO subject (id, user_id, name, parent_id, total_mcqs, created_at) VALUES ('top_eng_tenses', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'Tenses', 'top_english', 18, 1790961797108) ON CONFLICT(id) DO UPDATE SET total_mcqs = 18;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_66d96b98be7cfdcc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_tenses', 'Past tense of went is _____?', '{"A":"Go","B":"Went","C":"Gone","D":"Going"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Went is the past tense of go.Go is an irregular verb, and its past tense is went.Gone is the past participle of go.', 0, 0, 0, 1790961797221) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5fae13c8e9bf3317', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_tenses', 'Choose the correct from of tense: "If he _____ earlier, he would have caught the help."', '{"A":"Was arriving","B":"Arrives","C":"Had arrived","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This is a Third Conditional sentence.It talks about a past unreal situation.Structure: If + past perfect, would have + V3.So correct form is “had arrived”.Last verified on 27-04-2026', 0, 0, 0, 1790961797221) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9c572a65aceac32f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_tenses', 'Find the correct spelling: Existence, Existense, Existense, None of these', '{"A":"Existence","B":"Existense","C":"Existense","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Existence means موجودگیExistence means Presence.Last verified on 07-02-2026', 0, 0, 0, 1790961797221) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f87a1c6c63ca4ec1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_tenses', 'Select the correct tense used in the sentence "the weather will have changed before we reach there" from the given Choice:', '{"A":"Present Perfect Tense","B":"Future Perfect Tense","C":"Future Indefinite Tense","D":"Future Perfect Continuous Tense"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Future Perfect TenseBecause "will have changed" follows the Future Perfect structure:will + have + past participle (changed).It expresses an action that will be completed before a specific future time.', 0, 0, 0, 1790961797221) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_65a0eaa341c49678', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_tenses', 'He is crying at the top of his voice. Which tense is this?', '{"A":"Present indefinite tense","B":"Present continuous tense","C":"Past indefinite tense","D":"Future tense"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The verb "is crying" shows an action that is happening right now, which is the hallmark of present continuous tense.Present continuous is formed with is/am/are + verb-ing (e.g., is crying).', 0, 0, 0, 1790961797221) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ba4ae28d1b04ca4b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_tenses', 'The thief had been arrested by the police . ( tense)', '{"A":"Past Perfect","B":"Present Perfect","C":"Past Perfect continuous","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The past perfect shows an action completed recently.', 0, 0, 0, 1790961797221) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8bae6ee8f2d3f81a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_tenses', 'He plays cricket in the evening. (Change into interrogative form of Past Indefinite Tense)', '{"A":"Did he plays cricket in the evening?","B":"Did he play cricket in the evening?","C":"Does he plays cricket in the evening?","D":"Did he played cricket in the evening?"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Formula for interrogative sentences of Past Indefinite Tense: Did + subject + first form of a verb + object + other words.Correct answer: Did he play cricket in the evening?AGM 24-12-2022', 0, 0, 0, 1790961797221) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_584666cb0b2917f6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_tenses', 'We were listening to the radio all evening. Which tense is this?', '{"A":"Past Perfect Tense","B":"Past Continuous Tense","C":"Past Perfect Continuous Tense","D":"Present Perfect Tense"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Past Continuous Tense: Subject + Was/Were +first form of a verb + ing + object.', 0, 0, 0, 1790961797221) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1a612f5c3fdc9b1e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_tenses', 'Select the correct tense use in the sentence. "The servant was washing the clothes" from the given choices:', '{"A":"Past Perfect Tense","B":"Past Continuous Tense","C":"Past Perfect Continuous Tense","D":"Past Indefinite Tense"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Past Perfect Tense: HadPast Continuous Tense: Was/WerePast Perfect Continuous Tense: Had been Past Indefinite Tense: Verb 2nd form', 0, 0, 0, 1790961797336) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_10e82d0674966eef', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_tenses', 'It is time to ring the bell. (Change to present continuous tense)', '{"A":"It is being time to ring the bell.","B":"It is time for the bell to ring.","C":"It is time for the bell to be rung.","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation It is time for the bell to be rung.Given sentence is in present continuous tense and it is in active voice.Rule :Subject + (is/am/are) + to be + V3', 0, 0, 0, 1790961797336) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_943d0212402802ca', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_tenses', 'He began to move quickly. (Which tense is it?)', '{"A":"Past perfect","B":"Present Indefinite","C":"Future Tense","D":"Past Indefinite"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Begin is a verb which means start.The second form of the verb begin is began while the third form of the verb begin is begun.Second form of the verb is used in past indefinite tense (in simple sentences)', 0, 0, 0, 1790961797336) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_030e172a191b482b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_tenses', '. Grammar: he had been singing a son since five hours', '{"A":"He had been singing a song to five hours.","B":"He had been singing a sond until five hours.","C":"He had been singing a song till five hours.","D":"He had been singing a song for five hours.","E":"None"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Past perfect continuous tense.', 0, 0, 0, 1790961797336) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d512b6a0f1c78588', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_tenses', 'We had been looking for a month.', '{"A":"ہم ایک ماہ سے کھیل رئے تھے","B":"ہم ایک ماہ سے پڑھ رئے تھے","C":"ہم ایک ماہ سے تیر رئے تھے","D":"ان میں سے کوئی نہیں"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We had been looking for a month means ہم ایک ماہ سے تلاش کررئے تھے۔ The phrasal verb look for means search۔ Look for means تلاش کرنا', 0, 0, 0, 1790961797336) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6c38e5ffc97cf44d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_tenses', 'I will be having lunch with him. Mark the tense', '{"A":"Past continuous","B":"present continuous","C":"Future continuous","D":"Past perfect"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Future continuous tense is formed using the construction will + be + the present participle (the root verb + -ing).', 0, 0, 0, 1790961797336) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_75c1d78af4593599', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_tenses', 'It was afternoon by now and Mr. Hassan gave the boys a delicious lunch prepared mainly form the farm`s own produce. Later, the students visited the mango orchard and were delighted to see green fruits, hanging from the branches in large numbers. The trunks of the trees had been white washed with lime and the ground below was neat and clean. They did not see any weeds pr wild grasses around. Mr. Hassan told them that it was very necessary to protect them from pests and diseases which destroy the plants as well the fruits. The trunk of the trees were white washed with lime:', '{"A":"To attract pests and diseases","B":"To protect them from pests and diseases","C":"To make them visible","D":"To increase the growth of pests","E":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation It was afternoon by now and Mr. Hassan gave the boys a delicious lunch prepared mainly form the farm`s own produce. Later, the students visited the mango orchard and were delighted to see green fruits, hanging from the branches in large numbers. The trunks of the trees had been white washed with lime and the ground below was neat and clean. They did not see any weeds pr wild grasses around. Mr. Hassan told them that it was very necessary to protect them from pests and diseases which destroy the plants as well the fruits.', 0, 0, 0, 1790961797336) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7efb82aef40bcefd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_tenses', 'It was afternoon by now and Mr. Hassan gave the boys a delicious lunch prepared mainly form the farm`s own produce. Later, the students visited the mango orchard and were delighted to see green fruits, hanging from the branches in large numbers. The trunks of the trees had been white washed with liner and the ground below was neat and clean. They did not see any weeds pr wild grasses around. Mr. Hassan told them that it was very necessary to protect them from pests and diseases which destroy the plants as well the fruits. The boys did the lunch at:', '{"A":"Dawn","B":"Noon","C":"Afternoon","D":"Evening","E":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation It was afternoon by now and Mr. Hassan gave the boys a delicious lunch prepared mainly form the farm`s own produce. Later, the students visited the mango orchard and were delighted to see green fruits, hanging from the branches in large numbers. The trunks of the trees had been white washed with liner and the ground below was neat and clean. They did not see any weeds pr wild grasses around. Mr. Hassan told them that it was very necessary to protect them from pests and diseases which destroy the plants as well the fruits.', 0, 0, 0, 1790961797336) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a62511c0c0d39ae1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_tenses', 'It was afternoon by now and Mr. Hassan gave the boys a delicious lunch prepared mainly form the farm`s own produce. Later, the students visited the mango orchard and were delighted to see green fruits, hanging from the branches in large numbers. The trunks of the trees had been white washed with liner and the ground below was neat and clean. They did not see any weeds pr wild grasses around. Mr. Hassan told them that it was very necessary to protect them from pests and diseases which destroy the plants as well the fruits. The colour of mangoes, when the boys visited the farm was:', '{"A":"Orange","B":"Yellow","C":"Green","D":"Red","E":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation It was afternoon by now and Mr. Hassan gave the boys a delicious lunch prepared mainly form the farm`s own produce. Later, the students visited the mango orchard and were delighted to see green fruits, hanging from the branches in large numbers. The trunks of the trees had been white washed with liner and the ground below was neat and clean. They did not see any weeds pr wild grasses around. Mr. Hassan told them that it was very necessary to protect them from pests and diseases which destroy the plants as well the fruits.', 0, 0, 0, 1790961797429) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_86b0dea36d571af1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_tenses', 'It was afternoon by now and Mr. Hassan gave the boys a delicious lunch prepared mainly form the farm`s own produce. Later, the students visited the mango orchard and were delighted to see green fruits, hanging from the branches in large numbers. The trunks of the trees had been white washed with liner and the ground below was neat and clean. They did not see any weeds pr wild grasses around. Mr. Hassan told them that it was very necessary to protect them from pests and diseases which destroy the plants as well the fruits. The lunch Mr. Hassan gave to boys was prepared from:', '{"A":"Farm`s own produce","B":"Produce borrowed from the neighbors","C":"Produce bought from market","D":"Produce of any other form","E":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation It was afternoon by now and Mr. Hassan gave the boys a delicious lunch prepared mainly form the farm`s own produce. Later, the students visited the mango orchard and were delighted to see green fruits, hanging from the branches in large numbers. The trunks of the trees had been white washed with liner and the ground below was neat and clean. They did not see any weeds pr wild grasses around. Mr. Hassan told them that it was very necessary to protect them from pests and diseases which destroy the plants as well the fruits.', 0, 0, 0, 1790961797429) ON CONFLICT(id) DO NOTHING;
INSERT INTO subject (id, user_id, name, parent_id, total_mcqs, created_at) VALUES ('top_eng_prepositions', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'Prepositions & Fill in the Blanks', 'top_english', 22, 1790961797537) ON CONFLICT(id) DO UPDATE SET total_mcqs = 22;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_df1ccfcc360416a1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_prepositions', 'Fill in the blank: The report was ______ flawed that it was rejected.', '{"A":"So","B":"Very","C":"Such","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The report was so flawed that it was rejected.The correct pattern is so + adjective + that.Flawed is an adjective, so so is used.Such is used before a noun (e.g., such a flawed report).Last verified on 07-07-2026', 0, 0, 0, 1790961797639) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f75f8ec63ac0f938', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_prepositions', 'Identify the preposition in the sentence: The cat is under the table.', '{"A":"Is","B":"Table","C":"Under","D":"The"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The words like on, over, at, under, by etc. are called Prepositions."Under" is a preposition showing the relationship between the cat and the table.Prepositions indicate position, direction, or time in a sentence.Last verified on 23-05-2026', 0, 0, 0, 1790961797639) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c1d2d95823094340', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_prepositions', 'Which one is a Preposition? Run, Under, Fast, Strong', '{"A":"Run","B":"Under","C":"Fast","D":"Strong"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Under is a preposition because it shows relation of place (position below something).Example: The cat is under the table.Prepositions are words that link nouns/pronouns with other words in a sentence.Last verified on 07-05-2026', 0, 0, 0, 1790961797639) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_90995587bc337d08', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_prepositions', 'Fill in the blank: There has been a fall ________prices?', '{"A":"In","B":"With","C":"To","D":"On"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct preposition is "in" when referring to a reduction or decrease in something, such as prices. Other options:About: Does not fit the context of describing a decrease.On: Incorrect in this context.Of: Refers to possession or belonging, not a decrease.', 0, 0, 0, 1790961797639) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a2a3f0489c03f151', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_prepositions', 'Choose the correct preposition in the following sentence: He drowned ______ the pond.', '{"A":"In","B":"Into","C":"Near","D":"At"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct sentence would be: "He drowned in the pond."صحیح جملہ یہ ہوگا: وہ تالاب میں ڈوب گیا۔', 0, 0, 0, 1790961797639) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f61a18f3483f4f70', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_prepositions', 'Fill in the blanks: The report concludes sadly that ________ students have ___________ knowledge of Physics.', '{"A":"Some/A lot","B":"Both/While","C":"None/Any","D":"Very Few/Some"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The report concludes sadly that very few students have some knowledge of Physics.رپورٹ افسوسناک طور پر یہ نتیجہ اخذ کرتی ہے کہ بہت کم طلباء کو فزکس کا کچھ علم ہے۔The sentence suggests a contrast, where "Very Few" students possess "Some" knowledge of Physics.This construction emphasizes the scarcity of students with even basic knowledge.', 0, 0, 0, 1790961797639) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f3f0d483d85582fe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_prepositions', 'Fill in the blank: It is awful to be afflicted _____ a sense of inferiority.', '{"A":"For","B":"With","C":"In","D":"to"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation It is awful to be afflicted with a sense of inferiority.احساسِ کمتری کا شکار ہونا بہت بری بات ہے۔We use with to refer to what we use to do something: They opened the package with a knife. I''ll tie it with some tape to keep it closed.', 0, 0, 0, 1790961797639) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9a776f3da19e0870', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_prepositions', 'Fill in the blank: "___ book on the table is mine."', '{"A":"A","B":"An","C":"The","D":"No article needed"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The book on the table is mine."The" is used because "on the table" makes the book specific and identifiable.', 0, 0, 0, 1790961797640) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7f34ea30cd8468e2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_prepositions', 'Fill in the blanks: "New legislation ______ in the Assembly but it _______ by many."', '{"A":"Was introduced/ was not accepted","B":"Introduced/did not accept","C":"Is introduced/won''t accept","D":"Introduced/hadn''t been accepted"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The complete sentence would be: "New legislation was introduced in the Assembly but it was not accepted by many."This sentence indicates that a new law or bill was proposed (introduced) in the Assembly, but it did not gain approval or support from a significant number of people (was not accepted).', 0, 0, 0, 1790961797757) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ee436284a2c37cfb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_prepositions', 'Fill in the blanks: There is no reason ______ anyone should behave cruelly.', '{"A":"Which","B":"That","C":"Why","D":"Because"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct sentence is: "There is no reason why anyone should behave cruelly."The word "why" is used to introduce a clause that explains the reason or purpose behind something.In this sentence, "why" indicates that there is no justification or explanation for someone to behave cruelly.', 0, 0, 0, 1790961797757) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_41469399170471b3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_prepositions', 'Fill in the correct preposition: "I will be ready _______ the time you get here"', '{"A":"At","B":"By","C":"Of","D":"On"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "I will be ready by the time you get here."The correct preposition to use in this context is "by".It indicating that readiness will be achieved before the specified time of arrival.', 0, 0, 0, 1790961797757) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_df1731c5e75ddd38', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_prepositions', 'Fill in the blanks: _____ his children, his nephews and nieces were also present.', '{"A":"Besides","B":"Outside","C":"Beside","D":"Before"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Beside means بغل میںBesides means کے علاوہ Besides his children, his nephews were also present.ان کے بچوں کے علاوہ ان کے بھانجے بھی موجود تھے۔', 0, 0, 0, 1790961797757) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7842f15860f1ed11', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_prepositions', 'Fill in the blank . He has good ___over the world famous languages.', '{"A":"Hold","B":"Expertise","C":"Command","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Command means گرفت یا پکڑ', 0, 0, 0, 1790961797757) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_12fda452d75f72cb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_prepositions', 'Fill in the blanks: She was accompanied ______ her mother.', '{"A":"By","B":"With","C":"To","D":"Beside"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The word accompany is followed by the preposition by.Accompanied by someone means ہمراہ ہوناHe was accompanied by his father.', 0, 0, 0, 1790961797757) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_801f80fda6ca107e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_prepositions', 'Fill in the blanks: The police probe ___ the case', '{"A":"In","B":"Into","C":"Over","D":"With"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Probe into the case means مقدمے کی تحقیقات کرنا', 0, 0, 0, 1790961797757) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ba53749a9453707d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_prepositions', 'Fill in the blanks by inserting appropriate preposition in the statement, “I could not get in _______ the door so I had to climb _______ a window” from the given choice.', '{"A":"Between, into","B":"out of, between","C":"through, in","D":"out of, into"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Use of Through.From one end or side of something to the other. we walked slowly through the door. Use of INWhen something is located inside of a defined space. Like window, glass, box etc. Space does not need to be closed on all sides.', 0, 0, 0, 1790961797757) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3b7feee4b9a61ab7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_prepositions', 'Fill in the blanks: Start now and go on ____ you reach the river', '{"A":"To","B":"Unless","C":"Up","D":"Until"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ابھی شروع کریں اور اس وقت تک جاری رکھaیں جب تک آپ ندی تک نہ پہنچیں', 0, 0, 0, 1790961797890) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d3ee57b14d64ce14', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_prepositions', 'Fill in the blank "Aslam is senior ________ me "', '{"A":"for","B":"to","C":"on","D":"of"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To use as a preposition. meaning of To, like “toward” & “until.”', 0, 0, 0, 1790961797890) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8279e2d2ff1a73aa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_prepositions', 'Fill in the blank by inserting appropriate preposition in the statement "Nobody in our group has a genius _______ winning friend and convincing people"', '{"A":"of","B":"on","C":"in","D":"for"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Genius for use when any one very good at doing something.', 0, 0, 0, 1790961797890) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f206c772e6cd2393', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_prepositions', 'Fill in the blanks: He prohibited entering ______', '{"A":"In","B":"From","C":"To","D":"At"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation اس نے داخل ہونے سے منع کیا تھا Entering from', 0, 0, 0, 1790961797890) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f16223c0f876ef0e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_prepositions', 'Choose the appropriate preposition. Wreckage from the plane was scattered ____ a wide area.', '{"A":"Over","B":"From","C":"On","D":"At"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Wreckage from the plane was scattered over a wide area.', 0, 0, 0, 1790961797890) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_abaf3f335aedffde', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_prepositions', 'Choose the appropriate Preposition: Dr Baker is very good ________, Children', '{"A":"By","B":"Of","C":"With","D":"From"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation With is used in a number of expressions that say how people express their emotions and sensations. Common expressions are: green with envy, blue with cold, white with fear or rage, red with anger or embarrassment etc.', 0, 0, 0, 1790961797890) ON CONFLICT(id) DO NOTHING;
