INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4ebed0f68ea1b1bd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_articles', 'We should buy pure food articles. Here ''buy'' is?', '{"A":"Regular verb","B":"Transitive verb","C":"Helping verb","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Buy" is a transitive verb because it requires a direct object ("food articles") to complete its meaning.The sentence implies an action done to something — we buy what? — food articles.', 0, 0, 0, 1790961799529) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0e75d0dc788b143b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_articles', 'Find the correct indirect sentence: He said, "Let us wait for the award."', '{"A":"He asked them to wait for the award.","B":"He suggested that they should wait for the award","C":"He told them to wait for the award.","D":"He proposed that they should wait for the award."}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct indirect sentence is: He proposed that they should wait for the award.The direct statement "Let us wait for the award" implies a suggestion or proposal.The word "proposed" accurately captures the intention of the original statement in indirect speech.', 0, 0, 0, 1790961799529) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_830ad6e13c23df2d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_articles', 'What is the correct contraction of "I have"?', '{"A":"I''have","B":"I''ve","C":"I''ve","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A contraction is a shortened form of two words using an apostrophe."I''ve" is the correct contraction for "I have" (e.g., I''ve seen that movie).', 0, 0, 0, 1790961799529) ON CONFLICT(id) DO NOTHING;
