INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_97792b937f308530', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_articles', 'They were the heroes of their respective countries. In the above sentence, the word "their" is a/an:', '{"A":"Personal pronoun","B":"noun","C":"adverb","D":"indefinite pronoun"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation They is the subjective personal pronoun whereas their is the possessive personal pronoun.', 0, 0, 0, 1790961800477) ON CONFLICT(id) DO NOTHING;
