INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e982bac67916d19a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Antonyms of APPEAR.', '{"A":"Disappear","B":"Vanish","C":"Seem","D":"Unseen"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation APPEAR means ظاہر ہوناDisappear means غائب ہونا', 0, 0, 0, 1790961812159) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2eb9fb19bf4aa302', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The sun ____ in the west', '{"A":"Sets","B":"Set","C":"is Seting","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sun Sets in the west.یہاں پر پریزنٹ سیمپل ٹینس آے گا۔ کیونکہ قدرتی عمل میں یہ ٹینس آستعمال کرتے ہیں', 0, 0, 0, 1790961812159) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8b276e4849776f5f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I’ll have my assistant ________ for an appointment.', '{"A":"Called","B":"Calling","C":"Will call","D":"Call"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "I’ll have my assistant call for an appointment."In this sentence, the verb "have" is followed by the bare infinitive ("call"), which is the base form of the verb without "to." This is a causative construction, where someone is made or asked to do something.', 0, 0, 0, 1790961812260) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b52503979a729413', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She has been ill but now she is back in ___________ .', '{"A":"Movement","B":"Motion","C":"Circulation","D":"Moving"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "She has been ill, but now she is back in circulation."The phrase "back in circulation" is an idiom meaning that someone has returned to their normal social life or routine after being absent due to illness or other reasons."Motion" refers to physical movement (e.g., walking, running).', 0, 0, 0, 1790961812261) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5ee48b6c081fc83c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Never tell your secrets _______ a stranger.', '{"A":"With","B":"At","C":"On","D":"To"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We generally use to after tell.To is a preposition here. Never tell your secrets to a stranger نے راز کو کسی اجنبی کے ساتھ مت بتائیں۔', 0, 0, 0, 1790961812261) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bb055384d1d45554', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I entrusted him ___________ this work.', '{"A":"From","B":"With","C":"Of","D":"For"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We generally use with after entrust.With is a preposition here.Entrust with means to assign the responsibility. Entrust with means ذمے داری سونپناI entrusted him with this work میں نے اس کو یہ زمہ داری سونپ دی', 0, 0, 0, 1790961812261) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3568131d1a083627', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It is __________ to call than to write.', '{"A":"Quickest","B":"Quickly as","C":"Quicker","D":"Quicker than"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Quick is the positive degree of Adjective.Quicker is the comparative degree of Adjective.We use comparative degree of two compensations (call & write. It is quicker to call than to write means لکھنے سے زیادہ کال کرنا تیز ہے', 0, 0, 0, 1790961812261) ON CONFLICT(id) DO NOTHING;
