INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d9d4f4ba83491c89', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It is a small car, yet, it is surprisingly spacious. (here ''yet'' is an example of)', '{"A":"Preposition","B":"Pronoun","C":"Conjunction","D":"Adverb","E":"Noun"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Words like for, and, nor, but, or, yet, and so are examples of Coordinating Conjunctions.Coordinating Conjunctions are seven in number. Conjunction means حروف عطف', 0, 0, 0, 1790961812335) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_af3aba0b3070f684', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'These figures do not bode well for the company''s future. (here ''bode'' is an example of)', '{"A":"Adjective","B":"Adverb","C":"Conjunction","D":"Verb","E":"Preposition"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The word ''bode'' is a verb.Bode means to indicate or hint.Bode means نشان دہی کرنا', 0, 0, 0, 1790961812335) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_381ebcbaea5a6a29', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'A thief made away ________ my cell phone.', '{"A":"For","B":"About","C":"By","D":"With","E":"Of"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Make away with is a phrase.Make away with means چراکر لے جاناA thief made away with my cell phone means ایک چور میرا سیل فون چرا کر لے گیا', 0, 0, 0, 1790961812335) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5e7e14b25fbf8616', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'You ________ stones __________ the window.', '{"A":"trough,throw","B":"through, thorough","C":"throw, through","D":"throw, though"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Throw is a verbThrough is a preposition. You throw stones through the window means آپ کھڑکی سے پتھر پھینکتے ہیں', 0, 0, 0, 1790961812414) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3e55d6b0ca7498f8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'What an adorable child (here meaning of ADORABLE is)', '{"A":"Attractive and loveable","B":"Loving and innocent","C":"Young and loving","D":"Fascinating and smiling"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Adorable is used to describe someone or something that makes you love or like them, usually because they are attractive and often small.', 0, 0, 0, 1790961812414) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_811b41dc508a84bb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Mark to mark an abrupt turn or break in a sentence is called?', '{"A":"Dash","B":"Bracket","C":"Comma","D":"Full Stop","E":"All of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A punctuation mark used to indicate an abrupt turn or break in a sentence is called a dash (specifically, an em dashFunction: To mark a sudden break or interruption in a sentence. Appearance: Usually longer than a hyphen. Example: "I was going to the store, but then - I remembered I forgot my wallet."', 0, 0, 0, 1790961812414) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4efd8c3d87b9986c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Select the lettered pair that best expresses the relationship similar to that expressed in the original pair. SPY: CLANDESTINE', '{"A":"Furrier : Rambunctious","B":"Accountant : Meticulous","C":"Shepherded : Garrulous","D":"Astronaut :Opulent"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation SPY: CLANDESTINEAccountant: Meticulous***SPY: CLANDESTINE جاسوس: خفیہAccountant: Meticulous اکاؤنٹنٹ: محتاط', 0, 0, 0, 1790961812414) ON CONFLICT(id) DO NOTHING;
