INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_11ad696db61c2d1b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Vitamin D is essential ______ growth?', '{"A":"Bottled in","B":"Bottled up","C":"Bottled on","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bottled up means to keep (a feeling or emotion) inside instead of expressing it: to hideA) Bottled in: This is not a meaningful word choice in the context of the sentence.C) Bottled on: This is also not a meaningful word choice in the context of the sentence.', 0, 0, 0, 1790961813525) ON CONFLICT(id) DO NOTHING;
