INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1b0d4ca058d5a0e1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Parenthesis:Explanation', '{"A":"Ellipsis :Omission","B":"Synopsis:affectation","C":"Apostrophe:annotation","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A parenthesis is a remark that is made in the middle of a piece of speech or writing, and which gives a little more information about the subject being discussed.', 0, 0, 0, 1790961813618) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_582dd74d081f3ad5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He was sentenced _________death', '{"A":"on","B":"with","C":"to","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sentence takes to.To is a preposition here.Sentence to death means سزائے موت سنانا', 0, 0, 0, 1790961813618) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_649f2b856b78ef73', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The thief ___into the house .', '{"A":"break","B":"broke","C":"broken","D":"none"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Break into is a phrasal verb which means to enter by force.Break into means زبردستی گھسناThe thief broke into the house.', 0, 0, 0, 1790961813618) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0e5c9a1e8df70fe9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I should ___ my investment to pay charges', '{"A":"Dig out","B":"Dig in","C":"Begin with","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dig Out Meaning in English to Urdu is کھودنا باہرIn this context, "dig out" implies retrieving or accessing your investment funds to cover expenses', 0, 0, 0, 1790961813618) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5e219e41c939fced', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'In the question given below one term is missing. based on the relation ship in the two given words find the missing term from the given option._____:obfuscate::hider:help', '{"A":"Obscure","B":"whip","C":"lie","D":"none"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Explain is right answer', 0, 0, 0, 1790961813618) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fa109b56c2babab4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '"To say the word "means', '{"A":"Conversation","B":"Talk","C":"Tell","D":"None"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation meaning of say the word: to give an order When you want to leave (just) say the word', 0, 0, 0, 1790961813618) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4eda4097963fcf70', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'We should not jeer ____ the poor', '{"A":"at","B":"In","C":"On","D":"With"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jeer at means laugh at.At is a preposition here.Do not jeer at the poor غریبوں کا مذاق مت اڑاؤ', 0, 0, 0, 1790961813619) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7b0d2c7e9fa9e370', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Man-men', '{"A":"Goose geese","B":"Duck duckling","C":"Mouse mouses","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The plural of goose is geese. Geese are waterfowl belonging to the Anatidae family.', 0, 0, 0, 1790961813619) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_487f8a1a74fbcecd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It was the car ___', '{"A":"Which caused a accident","B":"Which cause an accident","C":"Which caused an accident","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We use which in questions as a determiner and interrogative pronoun to ask for specific information: ''Which car are we going in? '' he asked Alexander.', 0, 0, 0, 1790961813705) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_976b6a9f28d356d9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'To cut a sorry figure', '{"A":"To render an apology","B":"To break a record","C":"To make a sculpture","D":"To create a poor impression"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To cut a sorry figure is an English idiomTo cut a sorry figure means to create an unfavorable impression or present oneself poorly or negatively.To cut a sorry figure means خراب تاثر پیدا کرنا', 0, 0, 0, 1790961813705) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ecd1a28126252b23', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '___the contrary, I am proud of it .', '{"A":"in","B":"on","C":"at","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The preposition ''on'' indicates that something is already in the position. ''Onto'' indicates a movement from one place onto to surface of some type.', 0, 0, 0, 1790961813705) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_10dc4868e745771a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '_____ elderly couple strolled along ___ beach', '{"A":"An /the","B":"A /the","C":"An /that","D":"none"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation English has two articles: the and a/an. The is used to refer to specific or particular nouns; a/an is used to modify non-specific or non-particular nouns. We call the the definite article and a/an the indefinite article. For example, if I say, "Let''s read the book," I mean a specific book.', 0, 0, 0, 1790961813705) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4036659f67b0e8ca', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'مزموم meaning in English', '{"A":"evil","B":"Null and void","C":"Tussle","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation evilبرائی', 0, 0, 0, 1790961813705) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1af266e1c90fc6c5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Tomorrow at 3 PM you _______ matches.', '{"A":"Have","B":"Will be having","C":"Will have","D":"Will have had","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This sentence belongs to Future Perfect Tense.Formula: Subject + will + have + 3rd form of a verb + object.Tomorrow at 3 PM you will have matches.کل سہ پہر 3 بجے آپ کے میچ ہوں گے۔agm.5.3.23', 0, 0, 0, 1790961813705) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dcea1e9d2c7653a0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'By next week we shall ________ the course.', '{"A":"To completed","B":"Have completed","C":"Completing","D":"Completed"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Here next week indicates future. This sentence belongs to Future Perfect Tense.Have + third form of a verb is used in this tense. By next week we shall have completed the course. اگلے ہفتے تک ہم کورس مکمل کر لیں گے۔agm.5.3.23', 0, 0, 0, 1790961813705) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c9b3b8b4134812bc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They ________________ here next week to see my office.', '{"A":"Come","B":"Will come","C":"Have come","D":"Had come"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Next week indicates future and we use will for future tense.Have come indicates present tense while had come indicates past.', 0, 0, 0, 1790961813705) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e7990d10345c0228', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I will buy ____ cell phone next week.', '{"A":"An","B":"A","C":"Both A and B","D":"No article"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cell gives consonant sound.We use a when there is consonant sound.A is an article here.I will buy a cell phone next week..میں اگلے ہفتے ایک سیل فون خریدوں گا', 0, 0, 0, 1790961813774) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9309b85e7dea1757', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'As crow flies ___ the sky', '{"A":"in","B":"on","C":"at","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To refer to a place, use the prepositions "in" (the point itself)', 0, 0, 0, 1790961813774) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b2e793e01d2dae73', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I enjoyed reading________ book you gave me.', '{"A":"The","B":"A","C":"Any","D":"Some"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Here this sentence is talking about a particular book.We use the before a particular thing.The is an article here. I enjoyed reading the book you gave me.', 0, 0, 0, 1790961813774) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ec05c1be67c4aba9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The doctor advised him ______ eat rice.', '{"A":"do not","B":"to not","C":"not to","D":"prohibit","E":"All Of The Above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice: The doctor advised him not to eat rice. Passive Voice: He was advised by the doctor not to eat rice.', 0, 0, 0, 1790961813774) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_414a5acbc6d0993e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Should doctors tell patients that they have a ______________________illness?', '{"A":"Terminal","B":"Fatal","C":"Contagious","D":"None of these","E":"All of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Should doctors tell patients that they have a fatal illness? ***Fatal illness means جان لیوہ مرض A fatal accident or illness causes someone''s death."fetal" is best to keep the meaningful sentenceND06-08-2023', 0, 0, 0, 1790961813774) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_33f6690ab737404b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She will become ________ doctor.', '{"A":"A","B":"An","C":"The","D":"No Article"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We use Articles A & An before professions.Doctor gives consonant sound. Therefore, He is a doctor۔ I am a student. She is a teacher. کسی کا شعبہ یا فیلڈ بتانے کیلئے ہم (ارٹیکل اے) کا استعمال کرتے ہیں۔We use an when the profession gives vowel sound.e.g. She is an actress. You are an actor. I am an author.', 0, 0, 0, 1790961813774) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b0e01a1a92d4570b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He began his career 20 years ago ___ a doctor.', '{"A":"Like","B":"As","C":"Such as","D":"Of"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We generally use as to refer a profession.He began his career 20 years ago as a doctor means انہوں نے اپنے کیریئر کا آغاز 20 سال قبل بطور ڈاکٹر کیا تھا۔', 0, 0, 0, 1790961813774) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a72c686fc2358ea3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '___ money is important but I can''t buy ____ happiness.', '{"A":"The/The","B":"A/The","C":"An/An","D":"No article"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Money is important but I can''t buy happiness.پیسا اہم ہے لیکن میں اس سے خوشی نہیں خرید سکتا ہوں۔No article required here', 0, 0, 0, 1790961813774) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_67b8825ad7740746', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I wanted to buy __ car.', '{"A":"A","B":"An","C":"Both A and B","D":"No article"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Car gives consonant sound.We use a before car.A is an article.I wanted to buy a car.میں ایک کار خریدنا چاہتا تھا۔', 0, 0, 0, 1790961813858) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7176f627a344cf65', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'His father will buy him new books', '{"A":"New books were bought for him","B":"New books was bought for him","C":"New books will  bought for him","D":"New books will be bought for him"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Subject + will/shall + first form of the verb + object. Passive: Object of the active sentence + will/shall + be + past participle form of the verb + by + subject of the active sentence. Active: I will write a letter. Passive: A letter will be written by me. Active: She will help me.', 0, 0, 0, 1790961813858) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a841325a1ff29f67', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He will buy this house', '{"A":"This house would be bought by him","B":"This house will be bought by him","C":"This house would have been bought by him","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation After WILL we use BE in Direct & indirect speech.Direct speech: He will buy this house.Indirect speech: This house will be bought by him', 0, 0, 0, 1790961813858) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3e1951ba81fb1b03', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He will buy a new camera', '{"A":"A new camera will be bought by him","B":"A new camera is bought by him","C":"A new camera is being bought by him","D":"A new camera was being bought by him"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He will buy a new cameraوہ نیا کیمرہ خریدے گا۔Passive voice: A new camera will be bought by him', 0, 0, 0, 1790961813858) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7a398cdcd90784c6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The prime minister did not give up _____.', '{"A":"hope","B":"hopes","C":"to hope","D":"hoping"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Here hoping means امید He did not give up hoping.agm.04.03.23', 0, 0, 0, 1790961813858) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b49de93fd27d7b29', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The doctor advised me to give up sweets.', '{"A":"To me give up sweets was advised by doctor","B":"The doctor advised to give up sweets me","C":"I was advised by the doctor to give up sweets","D":"I was advised to give up eat sweets by the doctor","E":"All of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Given sentence is in simple past tense.Subject + (was / were) + V3 + Optional Agents.', 0, 0, 0, 1790961813858) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_120a26c683e71e2f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'This place gets ___ crowded with tourists every summer.', '{"A":"always more","B":"crowded and more","C":"more and more","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This place gets more and more crowded with tourists every summer.یہ جگہ ہر موسم گرما میں سیاحوں سے زیادہ ہجوم ہو جاتی ہے۔more and moreزیادہ سے زیادہSH16-8-2023', 0, 0, 0, 1790961813858) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_db160dd49944a235', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He heard train___ coming.', '{"A":"Is","B":"were","C":"will","D":"was"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He heard the train was coming.***The above sentence is a past continuous form of tense so we use "was"Past continuous: We use was/were + the -ing form of the verb.was is the first and third-person singular past tense of the verb the verb was is used in the past continuous tense', 0, 0, 0, 1790961813858) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f3ff5b5762891e94', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Can he swim?I do not think he knows ___', '{"A":"Swimming","B":"To swim","C":"How to swim","D":"How can he swim"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "how to swim" is the most grammatically correct and natural way to express the idea that someone doesn''t understand the process or technique of swimming."swimming" is a noun and doesn''t fit the sentence structure."to swim": is an infinitive and, while related, doesn''t directly convey the idea of knowing how to do something."How can he swim?": is a question, not a statement****', 0, 0, 0, 1790961813953) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d606edb98c9fe27f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '____ directors may terminate ____ chairman''s appointment at any time.', '{"A":"The/A","B":"The/The","C":"A/The","D":"A/A"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The directors may terminate the chairman''s appointment at any time.', 0, 0, 0, 1790961813953) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_33f59d57b6a10c74', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Sodium: Salt ::', '{"A":"Room: House","B":"Lime: Limestone","C":"Calcium: Marble","D":"Potassium: Phosphorous"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sodium is a mineral, and one of the chemical elements found in saltCalcium is a compound found in Marble', 0, 0, 0, 1790961813953) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_86567d43a7e50c10', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Distance: Mile', '{"A":"Bushel: corn","B":"Weight: scale","C":"Fame: gain","D":"Liquid: litre"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A mile is a unit of measurement for distance.A litre is a unit of measurement for liquid — this is a similar relationship.', 0, 0, 0, 1790961813953) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9eda5f1057eb0109', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '______ dog is a faithful animal.', '{"A":"A","B":"An","C":"The","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Here the dog means all the dogs in the world."The" is a definite article used when referring to a specific thing or group of things. In this case, "the dog" refers to all dogs, not just a single dog. "A" and "an" are indefinite articles used when referring to any member of a group or class, not a specific one.', 0, 0, 0, 1790961813953) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3ff9d8ae633098a7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The white and black dog ___ barking', '{"A":"is","B":"are","C":"were","D":"was"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Use is with singular subjects and are with plural subjects.', 0, 0, 0, 1790961813953) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f3da962256996e4d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I do not trust anybody in this office', '{"A":"Nobody is trusted by me in this office","B":"Nobody was trusted by me in this office","C":"Nobody should be trusted by me in this office","D":"Nobody will be trusted by me in this office","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This is a sentence of Present Indefinite Tense.Present Indefinite TenseActive Voice: Subject + Verb + Object Passive Voice: Object + is/am/are+ third form of a verb + by + subject.', 0, 0, 0, 1790961813953) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_168878a95601c723', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'You should abide by this promise.', '{"A":"This promise should be abided by by you","B":"This promise should be abided by you","C":"This promise should be abided by by your","D":"This promise should be abide by by you","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active: You should abide by this promise. Passive: This promise should be abided by by you. Abide by is a phrasal verb which means to accept/agree.Abide is always followed by by.', 0, 0, 0, 1790961813953) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4858289efb35a997', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'You must adhere _______ your promise.', '{"A":"For","B":"With","C":"To","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Usually “To” is used after “adhere”You must adhere to your promise. آپ کو اپنے وعدے پر قائم رہنا چاہیے۔***AGM 23.02.2023', 0, 0, 0, 1790961814032) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_07bec62ebf90df2b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'One must keep one''s promises.', '{"A":"One''s promises are kept","B":"Ones promises must kept","C":"Ones promises were kept","D":"One''s promises must be kept","E":"All of the above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Keep is a verb which means to maintain.Kept is the second and third form of Keep.The subject ''One'' has to be replaced with ''One''s promises'' keeping the tense same.Active voice: One must keep one''s promises.Passive voice: One''s promises must be kept', 0, 0, 0, 1790961814032) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1e7382db8df7eccf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Why ____ you break your promise?', '{"A":"is","B":"done","C":"does","D":"did","E":"being"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To make a question in the Past Tense in English we normally put the auxiliary DID at the beginning of the question or before the main subject.', 0, 0, 0, 1790961814032) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a60458adfb94aece', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I am glad ____ your shortcoming?', '{"A":"from","B":"for","C":"of","D":"to"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I am glad for your shortcoming***Using the Preposition “for”It can serve as another means of disclosing distance, quantity, or duration of time the shortcoming is a quality', 0, 0, 0, 1790961814032) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3101132ef4d60488', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I am sorry about what happened yesterday. It_____ happen again.', '{"A":"Shan''t","B":"won''t","C":"was","D":"none"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation won''t means will not.', 0, 0, 0, 1790961814032) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8c19485b7fa84bb5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Kindly share your knowledge.', '{"A":"You are requested to share his knowledge.","B":"You are requested to kindly share your knowledge.","C":"You are requested to share your knowledge.","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Passive Voice Formula for request: You are requested + to + V1+ object.', 0, 0, 0, 1790961814032) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_df9875d7517b0be3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'LIMB is to body as branch is to', '{"A":"Tree","B":"Office","C":"Seed","D":"Hou"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation LIMB is to the body as a branch is to a tree. Analogy Type: Part-to-Whole Relationship.Last updated by NA on 27 April 2026', 0, 0, 0, 1790961814032) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6a72d204e4be8ceb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Your pen is similar ____ mine.', '{"A":"To","B":"Too","C":"With","D":"Of"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Generally similar and equal are followed by to.To is a preposition hereYour pen is similar to mine.', 0, 0, 0, 1790961814032) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_25d7fe4130ed97b3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Wine is made _____________ grapes.', '{"A":"From","B":"Of","C":"With","D":"In","E":"All Of The Above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Usage of “From” and “Of” Wine is made from grapes. (Material has lost its original composition) The table is made of wood. (Material remain unchanged)', 0, 0, 0, 1790961814122) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_56ba599bcc5ba622', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Who is waiting __________ the door?', '{"A":"on","B":"at","C":"of","D":"in"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We use at for a specif location.At is a preposition here.Who is waiting at the door?', 0, 0, 0, 1790961814122) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e956d846f8c6ea9d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'ASEAN is an alliance ____________ the ten south-east Asian nations.', '{"A":"Among","B":"Between","C":"Upon","D":"On","E":"Along"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Among is used when referring to a group of three or more.ASEAN is an alliance among the ten Southeast Asian nations, meaning it involves all ten countries.', 0, 0, 0, 1790961814122) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5329183c2e2bfc7a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Wait __________ tomorrow.', '{"A":"With","B":"Till","C":"For","D":"Of"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Wait till tomorrow": is a shortened and informal version of "wait until tomorrow,""Wait till" means to wait up to a certain point in time — very natural and commonly used.', 0, 0, 0, 1790961814122) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b189f9554833fc74', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'A large procession was taken__________ against rising prices.', '{"A":"about","B":"Out","C":"In","D":"For"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct preposition to fill in the blank is "out"."A large procession was taken out against rising prices."The phrase "taken out" is commonly used when referring to processions, rallies, or demonstrations', 0, 0, 0, 1790961814122) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9aa990c64e932bca', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Choose the word that is similar in meaning DAINTY', '{"A":"Reduce","B":"Refined","C":"Groan","D":"Trap"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation DAINTY: دلکشRefined: بہتر', 0, 0, 0, 1790961814122) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_98e26f12a55776c4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Ahmad______ smoking abruptly.', '{"A":"Gave to","B":"Gave in","C":"Gave up","D":"Gave for","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ahmad gave up smoking abruptly.احمد نے اچانک سگریٹ نوشی ترک کر دی۔Give up is a phrasal verb that means چھوڑدینا یا ترک کرینا"Gave up " is the best t make a meaningful sentenceND16-8-2023', 0, 0, 0, 1790961814122) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_137d402cedbc51e6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He was unfit _________ the job as he was lacking _______ communication.', '{"A":"For, In","B":"To, on","C":"For, At","D":"Among, under"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Unfit for the jobLacking in communication', 0, 0, 0, 1790961814122) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c99ad811cfc4d71a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Never laugh ______ the old persons.', '{"A":"With","B":"On","C":"For","D":"At","E":"Of"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Laugh is an intransitive verb.Laugh at someone means کسی پر ہنسنا یا مذاق اڑانا Laugh is generally followed by atNever laugh at the old persons بوڑھے لوگوں پر کبھی نہ ہنسو', 0, 0, 0, 1790961814218) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5708f3a786607b28', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I hold you liable _____ the murder.', '{"A":"At","B":"With","C":"From","D":"For","E":"To"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Liable for means responsible forLiable for ذمہ دار قرار دیناLiable to means entitled to.Liable to حقدارI hold you liable for the murder.', 0, 0, 0, 1790961814218) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c748a96e309d891e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'My teacher lives near our village. ___ will come to our home. Choose the appropriate pronoun.', '{"A":"He","B":"We","C":"You","D":"They"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation My teacher lives near our village. he will come to our home.– میرا استاد میرے گھر کے پاس رہتا ہے **"HE" is best to keep the meaning of the original sentenceHe, him, and she are singular third-person pronouns.***"he" used to refer to a man, boy, or male animal previously mentioned or easily identified-------', 0, 0, 0, 1790961814218) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_01ccc7a9f727f560', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The place ___________ they live is unhealthy.', '{"A":"Where","B":"Who","C":"Whose","D":"Whom"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The place where they live is unhealthy.Here the word where means جہاں', 0, 0, 0, 1790961814218) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cd31c9c8e2a8bcfc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '________ fish can''t live without water.', '{"A":"A","B":"An","C":"The","D":"No article required"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Universal Truth doesn''t require article.Fish can''t live without water.', 0, 0, 0, 1790961814218) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dc8202192a641d1c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The dog jumped ـــــــــــــ the cat.', '{"A":"On","B":"Upon","C":"In","D":"Into","E":"All of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation On and Upon On = (Placed in contact)Upon = (In Motion) The books were on the table. The dog jumped upon the cat means کتے نے بلی پر چھلانگ لگائی', 0, 0, 0, 1790961814218) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5fa1c7c01b8cc699', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The divers jumped ---- the river to take out the lost necklace.', '{"A":"On","B":"In","C":"Into","D":"TO"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Usage of IN and INTOIn = inside to inside.My mother is in the house.Into = motion inwardThe driver jumped into the river.****', 0, 0, 0, 1790961814218) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1b757c1ede9b6889', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I saw him jumping _______ the wall.', '{"A":"on","B":"at","C":"over","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Over can be used in the following ways: as a preposition (followed by a noun or a pronoun) a bridge over the river Two men were fighting over her.I saw him jumping over the wall.', 0, 0, 0, 1790961814218) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3ab9fd3da56fad31', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He came ________ the room and jumped _________ the swimming pool.', '{"A":"Out, In","B":"Out, Into","C":"Out of, into","D":"Out of, in"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The preposition in denotes located inside or within.The preposition into denotes motion.He came out of the room means وہ کمرے سے باہر آیاAGM25.01.23', 0, 0, 0, 1790961814312) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b8858ab2243a91ab', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Fish Jumped from one pond ________ the other pond.', '{"A":"In","B":"Into","C":"To","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fish Jumped from one pond into the other pond.***We can use "into" as a preposition to indicate a movement or an action is happening Fish jump from one pound to the other pound. This sentence shows the "fish" movement or action so we use the "into" preposition***hence "in" preposition is used to indicate position', 0, 0, 0, 1790961814312) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6c62df9c5563b7f6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Refrain from interfering _____ the course of justice.', '{"A":"At","B":"With","C":"Of","D":"To","E":"In"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Interfere in مداخلت کرناInterfere with روکناWith is a preposition here.Refrain from interfering with the course of justice.', 0, 0, 0, 1790961814312) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_506cf050e81ae324', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The police are inquiring ____ the case.', '{"A":"At","B":"With","C":"Of","D":"Into","E":"In"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Inquire takes into.Into is a preposition. Inquire into means to investigate.Inquire into means تحقیقات کرناThe police are inquiring into the case پولیس مقدمے کی تحقیقات کررئی ہے', 0, 0, 0, 1790961814312) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7d367bc71eada542', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Khadija yearned ___ the return to her own home.', '{"A":"Over","B":"Upon","C":"For","D":"To","E":"By"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Yearn takes for.Yearn for means desire for.Yearn means ترسناShe yearns for her child وہ اپنے بچے کیلئے ترستی ہے', 0, 0, 0, 1790961814312) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_39b0387002b3d053', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The king gave her a reward.', '{"A":"She was given by the king a reward","B":"She was given a reward by the king","C":"She were given a reward by the king","D":"A reward was given by her to the king","E":"All of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Given sentence is in Past simple tense and it is in active voice, we need to change it into passive voice. Formula: Subject + (was / were) + V3 + Optional Agents.', 0, 0, 0, 1790961814312) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_33eff64a85fde574', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He ruled wisely for many years. In the above setence the word "wisely" is an', '{"A":"Adjective","B":"Adverb","C":"Article","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Wisely is an adverb which means عقلمندی سے', 0, 0, 0, 1790961814312) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c5394475f87599b7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I heard there was ___ burglary in our neighborhood last night.', '{"A":"The","B":"A","C":"An","D":"No article"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I heard there was a burglary in our neighborhood last night.میں نے سنا گزشتہ رات ہمارے پڑوس میں ایک چوری ہوئی۔ Article A is the correct option', 0, 0, 0, 1790961814312) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4c4280a2c2e4b069', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I heard the echo in the cave: choose the plural form.', '{"A":"I heard the echo in the caves","B":"I heard the echoes in the cave","C":"I hear the echoes in the cave","D":"All"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation echo plural echoesecho بازگشت', 0, 0, 0, 1790961814402) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_68751954f6686d1f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He had heard the story many times and as many times', '{"A":"has felt such melancholy that he thought his eyes will water","B":"had felt such melancholy that he thinks his eyes would water","C":"had felt such melancholy that he thought his eyes would water","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He had heard the story many times and as many times, had felt such melancholy that he thought his eyes would waterاس نے کہانی کئی بار سنی تھی اور جتنی بار، اتنی اداسی محسوس کی تھی کہ اسے لگا کہ اس کی آنکھوں میں پانی آجائے گا۔', 0, 0, 0, 1790961814402) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e43e10a813485325', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I like ……… music.', '{"A":"Listening","B":"To Listening","C":"Listening to","D":"Listen to"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I like To Listening music.مجھے موسیقی سننا پسند ہے۔*** present participle: Listening"Listen" or "listening" is an important difference in verb tense; "to" is a preposition, as would be "with" if your meaning were different. Both your verb tense and choice of prepositions determine the meaning of the sentence. For example, at first glance: "Listen to music"', 0, 0, 0, 1790961814402) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6374ccd8527e7a55', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I need not enlarge _____________ the problem and waste your time.', '{"A":"To","B":"form","C":"on","D":"in"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We generally use on after enlarge.On is a preposition here.Enlarge on کسی چیز کے بارے میں بہت باتیں کرنا', 0, 0, 0, 1790961814402) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d3e6c8d08979ebec', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The boy entered ________ the classroom.', '{"A":"In","B":"Into","C":"On","D":"With","E":"No Preposition Required"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In and Into In = (Located inside or within)Into = (Indicates entry or insertion)The girl jumped into the sea.They were sitting in the room. Note: “Into” is not used with “Enter” as the sentence becomes superfluous.She entered the room.', 0, 0, 0, 1790961814402) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c2a2b73047abb964', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'China and Pakistan entered _______________ various agreements.', '{"A":"Into","B":"in","C":"on","D":"for"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We generally do not use into after enter.Enter into is a phrase.Enter into agreement means معاہدہ طئے پاناPakistan and China enter into an agreement.', 0, 0, 0, 1790961814402) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8f68ec326f0eff35', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The government has embarked ____ the implementation of the 20 point program vigorously', '{"A":"with","B":"upon","C":"on","D":"for"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "The government has embarked on the implementation of the 20-point program vigorously."Explanation:The word "on" is used when something is started or initiated towards a particular activity.****', 0, 0, 0, 1790961814402) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_315a348dd83f3082', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'You cannot dispense ___________ the use of fan in summer.', '{"A":"By","B":"with","C":"on","D":"to"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dispense with means dispose of.Dispense with means چھٹکارہ پاناYou can''t dispense with the use of fan in summer.', 0, 0, 0, 1790961814402) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ffa0e2909459a2ac', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Despite his illness Asad was ___ in winning his team', '{"A":"Disappointing","B":"Instrumental","C":"Useless","D":"Vagarious"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Despite his illness, Inzamam was instrumental in winning his team."This means that even though he was sick, he played a crucial role in his team''s victory. The contrast between "illness" and still being "instrumental" makes the sentence meaningful.', 0, 0, 0, 1790961814481) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7d3855ca65362bea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She lived here ____ ten years', '{"A":"till","B":"since","C":"for","D":"from"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Since: point of timeFor: period of timeShe lived here for ten days.******', 0, 0, 0, 1790961814481) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c71b314c78e6423f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I have no desire ____ fame.', '{"A":"With","B":"For","C":"In","D":"To"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Desire is generally followed by for.For is a preposition here.I have no desire for fame مجھے شہرت کی خواہش نہیں', 0, 0, 0, 1790961814481) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5aad9d68c3ee166f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I talked to the stranger____ car had broken down on the road.', '{"A":"Who","B":"Whose","C":"Which","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Whose is a possessive pronoun. Whose shows belongings of someone.Whose means جس کا', 0, 0, 0, 1790961814481) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bb990a0a149d1263', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Man does not live by _________ alone.', '{"A":"Meals","B":"Food","C":"Bread","D":"Diet"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Man does not live by bread aloneاس کا مطلب ہے لوگوں کو صرف روٹی نہیں بہت سی چیزیں ضرورت ہوتی ہیں۔', 0, 0, 0, 1790961814481) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5b4d790d184bf4b1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Success in the examination depends _____ hard work alone.', '{"A":"Over","B":"On","C":"With","D":"In","E":"Of"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Depend is generally followed by the preposition OnDepend on something means کسی چیز پر منحصر ہونا In this sentence, the preposition "on" is used to indicate a specific time or opportunity.', 0, 0, 0, 1790961814481) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3243d1a56e48dd07', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Total senses of a human being is?', '{"A":"1","B":"4","C":"5","D":"8"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation humans have five senses: taste, smell, vision, hearing, touch.', 0, 0, 0, 1790961814481) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3b3fc19bd2b8d7da', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Salman complained _______ my father against me.', '{"A":"to","B":"with","C":"in","D":"none"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We word complain is followed by to/about.To & about are prepositions here.Complain to someone کسی انسان سے شکایت کرناComplain about something کسی معاملے پر شکایت کرناSalman complained to my father against me.', 0, 0, 0, 1790961814481) ON CONFLICT(id) DO NOTHING;
