INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_74ee4b3f9331d689', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Something that is hard but liable to break easily is known as?', '{"A":"Flexible","B":"Resilient","C":"Supple","D":"Brittle"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Brittle: hard but liable to break easily.Brittle means نازکAGM 09-2-2023', 0, 0, 0, 1790961814618) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b3c2e0215459f6dd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'What is the meaning of Banton?', '{"A":"Afresh","B":"Good manners","C":"Farewell","D":"Authority","E":"All of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Banton means Good MannersBANTON اچھے آدابAGM 09-2-2023', 0, 0, 0, 1790961814618) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b05c43c8cb1ed72c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I saw a _______ birds in the sky.', '{"A":"Bunch","B":"Tam","C":"Flock","D":"Crowd","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Flock of birds is a singular word which means پرندوں کا جھنڈAGM 09-2-2023', 0, 0, 0, 1790961814618) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7f925c0bf0118a1e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Talk : Stammer :: Walk : ___', '{"A":"walker","B":"Stagger","C":"Run","D":"Nonee"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation stammer : A speech disorder involving hesitations and involuntary repetitions of certain sounds. رک رک کر بولنا تتلانا ہکلانا ہچکچاتے ھوئے بولناStaggerلڑکھڑانا', 0, 0, 0, 1790961814618) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d97c366d1a03ef69', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Pakistan as well as India _______poor', '{"A":"Is","B":"are","C":"was","D":"were"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The phrase "as well as" means in "addition to" or "and also" in the context of the example that you have mentioned. When "as well as" is used as a conjunction, there is no need to use commas before or after the phrase. Moreover, it should always be used with a singular verb.', 0, 0, 0, 1790961814618) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9e31c65ffb9e4415', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He went to Lahore______train', '{"A":"On","B":"With","C":"By","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We use preposition by for means of transport. When we use "by" this way, it means "close to" "next to" or "beside."', 0, 0, 0, 1790961814618) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_766fe2cfd7497fda', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Antonyms of Stalwart ______?', '{"A":"weak","B":"soft","C":"flimsy","D":"feeble"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Stalwart means brave or doughty.Stalwart means وفادارStalwart is an adjective.Antonyms of Stalwart: Timid, Scary, unreliableSynonyms: committed, faithful, loyalFeeble means کمزور', 0, 0, 0, 1790961814692) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7faebdce38a7d93d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'His hands numbed __ cold', '{"A":"from","B":"with","C":"at","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When things happen we use the word with to explain where things are. His hands numbed with cold.', 0, 0, 0, 1790961814692) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6bd21db7e8ecbc95', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Keep the car __________ the flower beds.', '{"A":"Off","B":"Of","C":"In","D":"With","E":"To"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Off is a preposition here.Here off means at a distanceKeep the car off the flower beds', 0, 0, 0, 1790961814692) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_065b19643170df5b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'You should to go bed __________ 10 o` clock.', '{"A":"On","B":"At","C":"With","D":"For","E":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We use at for certain time. You should to go bed at 10 o` clock. آپ کو دس بجے سونا چائیے', 0, 0, 0, 1790961814692) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_aceec30c70fa69fc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'My father is quite concerned _______ my progress at school.', '{"A":"For","B":"From","C":"Against","D":"About","E":"On"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We generally use about with concerned.About is a preposition here.Concerned about something means کسی کے بارے میں فکرمند ہوناI am not concerned about his affairs.', 0, 0, 0, 1790961814692) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_774050d969d91ea8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I am not concerned______ his affairs.', '{"A":"of","B":"about","C":"for","D":"none of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We generally use about with concerned.About is a preposition here.Concerned about something means کسی کے بارے میں فکرمند ہوناI am not concerned about his affairs.', 0, 0, 0, 1790961814692) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a8ec2f4b51e87684', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I prefer __________ by air.', '{"A":"Going","B":"To going","C":"To be going","D":"to go"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Generally prefer is followed by To.To is a preposition here.Prefer means ترجیع دیناI prefer to go by air.', 0, 0, 0, 1790961814692) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_47dafcf38f0d53fc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I prefer ____die than humiliation:', '{"A":"by","B":"to","C":"off","D":"than","E":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Generally prefer is followed by To.To is a preposition here.Prefer means ترجیع دیناI prefer to die.', 0, 0, 0, 1790961814692) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5442d4ca55c07008', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I prefer driving ____ travelling by train', '{"A":"on","B":"to","C":"from","D":"none"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The word Prefer is generally followed by Preposition To. Use the preposition ''to'' when indicating that there is movement from one place to another.I prefer driving to travelling by train.', 0, 0, 0, 1790961814760) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_85cc04be016f24b9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The young, thin boy surprised his wrestling opponent with his ______ strength', '{"A":"Wiry","B":"Fraudulent","C":"Frolicsome","D":"None of these","E":"All of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The young, thin boy surprised his wrestling opponent with his wiry strengthWiry means پتلا لیکن طاقتور Someone who is wiry is somewhat thin but is also strong.wiry is the best option to make a meaningful sentenceND-8-08-2023', 0, 0, 0, 1790961814760) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_596e0c1b70b6a974', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He is the youngest _____ seven children.', '{"A":"Of","B":"Among","C":"From","D":"In","E":"All of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He is the youngest among the seven children.Between دو لوگوں کیلیئے استعمال ہوتا ہےAmong دو سے زائد لوگوں کیلیئے استعمال ہوتا ہے', 0, 0, 0, 1790961814760) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_709f48977635b6c5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They ___ asked to give an opinion in their own words:', '{"A":"Maybe","B":"could be","C":"might","D":"have being"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation They may be asked to give an opinion in their own words.***Remember, maybe is an adverb, and it''s used alongside verbs or as a standalone answer to a question. "Maybe" functions as a verb. If you can replace the term with possibly or perhaps, use maybe. If you can replace the term with might be, use may be.', 0, 0, 0, 1790961814760) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9a56a40e36c76435', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I got _____ the bus and went to the Hotel.', '{"A":"upon","B":"on","C":"in","D":"none of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I got ON the bus and went to the Hotel.کیونکہ بس پر بیٹھ کر گیا اس لیے ان لگا', 0, 0, 0, 1790961814760) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f2109da106f75ab8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I went ____________ her home.', '{"A":"To","B":"In","C":"Above","D":"About","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Note:- If “possessive adjective” or “a noun with an apostrophe” is used before “home”, “to” is used before “home” only in case of specific verbs (Not with “arrive” and “reach”. I went to her home.', 0, 0, 0, 1790961814760) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7fea7124cdd97799', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Salman went ______ to oblige his superior.', '{"A":"On his way","B":"Out of his way","C":"In his way","D":"With his way"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Out of way = unusual, not on the route that you planned to', 0, 0, 0, 1790961814761) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_280de85fe3f8916c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She went_____________________ home.', '{"A":"To","B":"Too","C":"Upto","D":"Till","E":"No Preposition Required"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Note:- We do not use any preposition before “Home” with the following verbs. Go, Bring, Get, Reach, Arrive & Come.Went is the second form and Gone is the third form of Go.She went home.', 0, 0, 0, 1790961814761) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d7137f1c86c1a739', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '______________ having finished my work, I went home.', '{"A":"After","B":"To","C":"With","D":"From","E":"No Preposition Required"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sometimes, Prepositions are inserted where they are not required.After having finished my work, I went home. (Incorrect Sentence)Having finished my work, I went home. (Complete & Correct Sentence)', 0, 0, 0, 1790961814850) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0c10c1cde3930183', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'You say, "I went to Paris Yesterday."', '{"A":"You said that you gone to Paris the previous day","B":"You said that you will go to Paris the previous day","C":"You said that you was going to Paris the previous day","D":"You say that you went to Paris the previous day","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Remove inverted commasDo not change the tense into past because it is in Present Tense.Add thatDo not change pronouns', 0, 0, 0, 1790961814850) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c5c5912d2bd9639e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The girl laughed at the beggar.', '{"A":"The beggar was laughed by the girl","B":"The beggar was being laughed by the girl","C":"The beggar was being laughed at by the girl","D":"The beggar was laughed at by the girl","E":"All of the above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation (the girl) will become subject and subject (The beggar) will be object. We also use helping verb of past simple tense was with V3 form of the main verb.Keep it in mind that the preposition at must be retained with the verb.Rule : Subject + (was /were) + V3 + Other Agents.', 0, 0, 0, 1790961814851) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dbc10dd3db159a92', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'We met Hania yesterday. _______ made us laugh.', '{"A":"We","B":"He","C":"She","D":"I","E":"Her"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We met Hania yesterday. She made us laugh.She is a personal pronoun used to indicate a Feminine Gender.', 0, 0, 0, 1790961814851) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fd6819ec19ff1849', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Who laughs at you?', '{"A":"By whom are you laughed at?","B":"By whom are you being laughed at?","C":"By whom were you laughed at?","D":"All of the above","E":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Who laughs at you is an interrogative sentence of Present Indefinite Tense.Who laughs at you means آپ پر کون ہنستا ہے؟Present Indefinite TenseActive Voice: Subject + Verb + ObjectPassive Voice: Object + is/am/are+ third form of a verb + by + subject.', 0, 0, 0, 1790961814851) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8f1c4396d7e07612', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Mother did not approve ____smoking.', '{"A":"With","B":"of","C":"off","D":"from","E":"on"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Approve is generally followed by of.Of is a preposition here.Mother did not approve of smoking.', 0, 0, 0, 1790961814851) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_411bc31fe5fbf86d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Where did she put the _________ which were on the ________ ?', '{"A":"Knifes/Shelfes","B":"Knives/Shelves","C":"Knifs/Shelfs","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Where did she put the knifes which were on the shelves?Knives is the plural of knife (چاقو)Shelves is the plural of Shelf (خانہ)', 0, 0, 0, 1790961814851) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_74ca311092325f7b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Tania has decided ___________ her computer.', '{"A":"To Selling","B":"Sold","C":"To sell","D":"Sell","E":"All of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Decide and sell are verbs here.Usually to is used between two verbs.Tania has decided to sell her computer means تانیا اپنا کمپیوٹر فروخت کرنے کا فیصلہ کرچکی ہے', 0, 0, 0, 1790961814851) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8aa4322cc2b18c7c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The case was put _______ the judge.', '{"A":"At","B":"Before","C":"From","D":"On"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The word "Before" means In Front Of.Before سامنےمقدمہ جج کے سامنے رکھا گیا۔', 0, 0, 0, 1790961814942) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8f8c403be63dbc04', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They have a dispute ________money.', '{"A":"for","B":"over","C":"In","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dispute is generally followed by over.Over is a preposition here.Dispute over something means کسی بات پر تنازع', 0, 0, 0, 1790961814942) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7dc4d537c44548a9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Pakistan must not put reliance ___ IMF', '{"A":"on","B":"for","C":"to","D":"all","E":"none"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Generally, reliance is followed by on.On is a preposition here.Reliance on something means کسی پر انحصارPakistan must not reliance on IMF.', 0, 0, 0, 1790961814942) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bb33444c37843dab', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Put a blanket __________ the child.', '{"A":"Over","B":"On","C":"Upon","D":"Into","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Over is sometimes also used to cover the whole surface.Over is a preposition here. Put a blanket over the child means بچے پر ایک کمبل ڈال دو', 0, 0, 0, 1790961814942) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3133db78be74d593', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He takes honor…..his great command in Computer Science.', '{"A":"from","B":"with","C":": in","D":"without"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He takes honor with his great command in Computer Science.***The words like, with, at, on, near, over, etc. are called Prepositions.We use with to refer to what we use to do something:', 0, 0, 0, 1790961814942) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7f3c69ba2b75cd73', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Children are fond __________ chocolates and computing.', '{"A":"With","B":"Off","C":"In","D":"On","E":"Of"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Generally fond is followed by of.Fond of means کسی چیز کا شوقین ہوناChildren are fond of chocolates.', 0, 0, 0, 1790961814942) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0d42edff31ee36c5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He has the good reputation ______ being a teacher.', '{"A":"of","B":"with","C":"in","D":"none of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We generally use of with reputation.Of is a preposition here.Reputation means شہرت', 0, 0, 0, 1790961814942) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b6fddeb6e0e6420f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He ordered me to bring a glass of water.', '{"A":"I am ordered to bring a glass of water by him","B":"I was ordered to bring a glass of water by him","C":"I will be ordered to bring a glass of water by him","D":"I should be ordered to bring a glass of water by him","E":"All of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active: Subject + past tense form of the verb + object Passive: Object of the active sentence + was/were + past participle form of the verb + by + subject of the active sentencePassive: I was ordered to bring a glass of water by him', 0, 0, 0, 1790961814942) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7a641aa288616e19', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The word HINDERING means:', '{"A":"Coining","B":"Rearing","C":"Closing","D":"Obstructing","E":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hinder means رکاوٹ ڈالنا Obstruct means رکاوٹ ڈالنا', 0, 0, 0, 1790961815040) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cb33639c3b25ba01', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The apartment ___________ I live is very small.', '{"A":"That","B":"Where","C":"Which","D":"Were"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Here ''where'' means جہاںThe apartment where I live is very small means وہ اپارٹمنٹ جہاں میں رہتا ہوں بہت ہی چھوٹا ہے', 0, 0, 0, 1790961815040) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c656a8707545a798', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The train departs ---- 3 am', '{"A":"at","B":"for","C":"by","D":"in"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The preposition ''at'' is used with specific times of the day. The flight departs at 9 PM.The train leaves at 7 AM.', 0, 0, 0, 1790961815040) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_010d01174743e0b0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Are you coming to ____ Party', '{"A":"A","B":"An","C":"The","D":"Towards"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Are you coming to the Party.Here we are talking about a particular party.We use article the for specific things. ******RY 23-12-2022', 0, 0, 0, 1790961815040) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4c4fd70bb736c76f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I went to ________ Japanese department with Mr. John who is a well known lecturer.', '{"A":"A","B":"An","C":"The","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Usually Article the is used for Nationalty.Like, The Chinese, The Japanese, The Indian', 0, 0, 0, 1790961815040) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3b4af9b4256c9b7a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I gave him a surprise party when he came back home', '{"A":"A surprise party was given to him when he came back home","B":"A surprise party were given to him when he came back home","C":"A surprise party is given to him when he came back home","D":"none"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Use helping verb was/were according to the subject of the Passive Voice sentence.Use 3rd form of the verb.Then use the word “by”, to show the doer.Then convert the subject of the Active Voice Sentence into the object of the Passive Voice sentence.In the end, add the remaining words if there are any in the Active Voice Sentence.', 0, 0, 0, 1790961815040) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_885f9550c78100dd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Fate smiled ———— him in all his ventures', '{"A":"At","B":"On","C":"Over","D":"above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fate smiled on Hamza means تقدیر حمزہ پر مہربان ہوا', 0, 0, 0, 1790961815040) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9509bfb855fd2a24', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'A believer smiles in public and ____ in private.', '{"A":"wept","B":"weeping","C":"weep","D":"weeps","E":"None"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Here ''smiles'' shows this sentence belongs to Present Indefinite Tense.Therefore, weeps is the correct answer.He smiles وہ مسکراتا ہےHe weeps وہ روتا ہے', 0, 0, 0, 1790961815040) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_966bbb3421943c4a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Nabeel was annoyed _________ his wife.', '{"A":"With","B":"For","C":"To","D":"By","E":"In"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Angry with someone means کسی سے ناراض ہوناAngry with: کسی انسان سے ناراض ہوناAngry on: کسی بات پہ ناراض ہوناAngry at برتاو یا رویے پر ناراض ہوناHe is annoyed with his wife.', 0, 0, 0, 1790961815139) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_afea031d66f35687', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He annoyed us.', '{"A":"We were annoyed with him","B":"We were annoyed at him","C":"We are annoyed with him","D":"We were  be annoyed with him","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We were annoyed with him.Annoy is a verb which means ناراض کرنا یا ہوناPast Indefinite tenseActive Voice= Subject + Second Form of Verb + Object.Passive Voice = Object + was/were + third of verb + by + subject.', 0, 0, 0, 1790961815139) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_be7c699382ea320e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They were angry __________________ me.', '{"A":"With","B":"along","C":"from","D":"on","E":"in"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation They were angry with me means وہ مجھ سے ناراض تھے Angry with someone means کسی سے ناراض ہوناAngry with: کسی انسان سے ناراض ہوناAngry on: کسی بات پہ ناراض ہوناAngry at برتاو یا رویے پر ناراض ہونا', 0, 0, 0, 1790961815139) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_150ebf9884b63fba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The manager is angry _________________ the assistant for not attending to the work.', '{"A":"On","B":"With","C":"In","D":"Upon","E":"No preposition required"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Angry with someone means کسی سے ناراض ہوناAngry with: کسی انسان سے ناراض ہوناAngry on: کسی بات پہ ناراض ہوناAngry at برتاو یا رویے پر ناراض ہونا', 0, 0, 0, 1790961815139) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8a09e7551f2658d7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The father was angry and cast ________ his son.', '{"A":"Off","B":"Of","C":"Down","D":"About"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cast off is phrasal verb which means برطرف کردینا', 0, 0, 0, 1790961815139) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_403d6b214a4a2621', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I was angry ___ him ___ lying to me.', '{"A":"For-With","B":"To-For","C":"With-For","D":"To-With"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Angry with someone means کسی سے ناراض ہوناAngry with: کسی انسان سے ناراض ہوناAngry on: کسی بات پہ ناراض ہوناAngry at برتاو یا رویے پر ناراض ہونا', 0, 0, 0, 1790961815139) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6897176f10120a58', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He deals ___ sugar.', '{"A":"with","B":"of","C":"in","D":"to","E":"on"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Deal with a matter means کسی معاملے کو نمٹاناDeal in something means کاروبار کرنا یا روزی روٹی کماناDeal out تقسیم کرناHe deals in sugar means وہ چینی کا کاروبار کرتا ہے', 0, 0, 0, 1790961815139) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6414ad1ea7e1816c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He deals _____ Rice.', '{"A":"Out","B":"Of","C":"In","D":"On"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Deal with a matter means کسی معاملے کو نمٹاناDeal in something means کاروبار کرنا یا روزی روٹی کماناDeal out تقسیم کرناHe deals in rice means وہ چاول کا کاروبار کرتا ہے', 0, 0, 0, 1790961815139) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_17c0505de9e22a90', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'You must learn how to deal ___________ costumers.', '{"A":"By","B":"with","C":"from","D":"none of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Deal with a person or thing معاملہ طئے کرنا یا نمٹناDeal in کاروبار کرناDeal out تقسیم کرناYou should deal with the costumers.', 0, 0, 0, 1790961815247) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_91853a5b9af74cf2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Some people were helping the wounded man.', '{"A":"The wounded man was helped by some people?","B":"The wounded man was being helped by some people","C":"The wounded man is being helped by some people","D":"The wounded man is helped by some people","E":"All of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Keyboard is an input device.Keyboard is similar to electric typewriter.Keyboard uses serial port to connect with computer.Keys on keyboard are of mainly three types:Alphanumeric keys: letters and numbers Punctuation keys: comma, period, semicolon, etc.Special keys: function keys, arrow keys, caps lock key, etc.', 0, 0, 0, 1790961815247) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_05e76229f11b86a9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I have been wounded in _____ head.', '{"A":"A","B":"An","C":"The","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Usually Article the is used with parts of body name.', 0, 0, 0, 1790961815247) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5b970eabd7ec399f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The doctors hope that the soldier''s wound will soon _______?', '{"A":"Mend","B":"Heal","C":"Recover","D":"Restore","E":"All are correct"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We generally use heal with wound.Wound will heal means زخم بھر جائے گا', 0, 0, 0, 1790961815247) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c88ec8fc14d53716', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The lamp is _____ the table.', '{"A":"In","B":"Of","C":"On","D":"Out","E":"From"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We use on to refer a surface. On is a preposition here.On: کسی چیز کے اوپر ہوناThe lamp is on the table.AGM 5.2.23', 0, 0, 0, 1790961815247) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_284b911e112fa9ac', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He is capable _______ being an excellent student', '{"A":"Of","B":"For","C":"To","D":"With"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ø Of is a preposition that indicates relationships between other words, such as belonging,Things made of other things, Things that contain other things, or a point of reckoning. Ø Off is usually used as an adverb or a preposition. In both cases, it indicates separation or disconnection.', 0, 0, 0, 1790961815247) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4e86b5b861343945', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I have taught ___ English to thousands of ____ students.', '{"A":"The/the","B":"A/A","C":"A/An","D":"No article"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I have taught English to thousands of students.Generally no article required before a language (English)', 0, 0, 0, 1790961815247) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_abe1b732a8db9149', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The new leader showed ------------------ about hitting the students.', '{"A":"quotations","B":"qualia","C":"quakes","D":"none of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The new leader showed quotations about hitting the students....quotations meaning:کوٹیشن A quotation is a group of words taken from a text or speechA quotation repeated by someone other than the original author or speaker.', 0, 0, 0, 1790961815247) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5dd9aaadbe05ff19', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'This man was an accomplice ________ the thief.', '{"A":"Of","B":"In","C":"With","D":"From"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Accomplice is generally followed of.Accomplice means a partner in crime.Accomplice means جرم میں ساتھ دینے والا He was an accomplish of the thief.', 0, 0, 0, 1790961815366) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_56d3ba404b88f52a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The thief was caught.', '{"A":"Someone caught the thief in the street","B":"Someone catch the thief in the street","C":"Someone can be caught the thief in the street","D":"Someone caught the thief","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Past Indefinite tenseActive Voice= Subject + Second Form of Verb + Object.Active: The thief was caught. Passive Voice = Object + was/were + third of verb + by + subject.Passive: Someone caught the thief in the street', 0, 0, 0, 1790961815366) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dfc3e9079eaa560f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'What is the solution interval of the inequality 6x-2> 3x+10', '{"A":"(infinnte . 4)","B":"(- infinite . 4)","C":"(- 4. infinte)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation SH14-8-2023', 0, 0, 0, 1790961815366) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5257d2d57c4f91d7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The prime minister will meet the employees this evening.', '{"A":"The employees will be met by the prime minister this evening","B":"The employees will be meet by the prime minister this evening","C":"The employees will were met by the prime minister this evening","D":"The employees can be met by the prime minister this evening","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The prime minister will meet the employees this evening is a sentence of Future Indefinite Tense.Active Voice Formula: Subject + Will/Shall + Verb (Ist form) + Object + (.)Passive Voice Formula: Convert Object to Subject + Will/Shall + Be + Verb (3rd form) + By + Convert Subject to Object + Remaining + (.)', 0, 0, 0, 1790961815366) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_501570f17a1ed5a5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I am looking forward for admission_______ in a private or government college.', '{"A":"Either","B":"Neither","C":"Until","D":"Both","E":"From"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Generally or is used after either.Either or means یا تو یہ یا پھر وہI am looking forward for admission either in a private or government collegeمیں کسی پرائیویٹ یا گورنمنٹ کالج میں داخلہ کا منتظر ہوں', 0, 0, 0, 1790961815366) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9df54d792fe82058', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'One Astronomical Unit is the average distance between:', '{"A":"Earth and Sun","B":"Jupiter and Sun","C":"Pluto and Sun","D":"Earth and Moon"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A unit of length equal to the average distance between the earth and sun is called Astronomical Unit. One Astronomical Unit is the average distance between Earth and Sun.', 0, 0, 0, 1790961815366) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3daf1a7393f3e697', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The kitchen was infested ----- ants', '{"A":"with","B":"by","C":"to","D":"in"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We generally use with after infested and filled.Infested with something means کسی چیز سے بھرا ہواThe kitchen was infested with ants*******RY 14-01-2023', 0, 0, 0, 1790961815366) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_424818ee2bed86ec', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He said, "He does not like beef".', '{"A":"He said that he does not like beef","B":"He said that he did not liked beef","C":"He said that he did not like beef","D":"He told that he does not liked beef","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Direct: He said, "He does not like beef".Indirect: He said that he did not like beefRemove inverted commasConvert present into past tenseAdd that***ND1-2-2023', 0, 0, 0, 1790961815366) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9d985203a0d59ddd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The girl said, "I like sleeping."', '{"A":"The girl said the she likes sleeping","B":"The girl said the she liked sleeping","C":"The girl says the she liked sleeping","D":"The girl said the she like sleeping","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Change into past as reporting verb is in past.Add thatRemove inverted commas***ND1-2-2023', 0, 0, 0, 1790961815476) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_62d7931bf77e71d2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Aslam said to me, "If I hear any news, I will phone you."', '{"A":"Aslam said me that if I heard any news, I would phone me.","B":"Aslam told me that if he hear any news, he will phone me.","C":"Aslam told me that if he heard any news, he would phone me.","D":"Aslam told me that if he hear any news, he will phone me","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Direct: Aslam said to me, "If I hear any news, I will phone you."Indirect: Aslam told me that if he heard any news, he would phone me. If the tense of reporting speech is in simple present Tense then convert the reported speech tense into simple past tense. ***ND1-2-2023', 0, 0, 0, 1790961815476) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bb024ff383c3bf7a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'What is another word for beady?', '{"A":"Plain","B":"Pleasant","C":"Small","D":"Quick","E":"All of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Beady means موتی جیسا چھوٹاSmall چھوٹا***ND1-2-2023', 0, 0, 0, 1790961815476) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_076614bcfb1e66d5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I could be there ---- stadium', '{"A":"in","B":"on","C":"at","D":"by"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In general, we use: at for a POINT. in for an ENCLOSED SPACE.', 0, 0, 0, 1790961815476) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9352301b7c288536', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They ____ playing in the stadium', '{"A":"are","B":"is","C":"am","D":"none"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation They is a pronoun here.Is for singular pronoun.Are is used with plural noun ******VU FIA CONSTABLE PAPER 2021', 0, 0, 0, 1790961815476) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_06e7ebf6b114f1c5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I was addicted ___________ smoking.', '{"A":"To","B":"Too","C":"With","D":"Off","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Addicted to is a phrase which means عادی ہوناAddicted to is generally followed by verb + ing formHe was addicted to drinking. I was addicted to smoking.', 0, 0, 0, 1790961815476) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f2eae61173206f8c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The doctor advised me to give _________ smoking.', '{"A":"Off","B":"Up","C":"In","D":"Over","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Give Up is a phrasal verb which means ترک کردیناYou need to give up bad habits means آپ کو بری عادتیں ترک کردینی کی ضرورت ہے', 0, 0, 0, 1790961815476) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_94f28a6becc9d421', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Put your signature __ blue ink.', '{"A":"In","B":"Of","C":"With","D":"Through","E":"All of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When we use ( pen) to write, we use ( ink) instead of (pen). Then we have to use the preposition ( in ) but not ( with).eg. I write in ink.When we use pencil, we have to use ( with) but not ( in). eg. I wrote with a pencil.', 0, 0, 0, 1790961815476) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3b46f7242fbc6df3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He was compensated __________________ the loss of her belongings.', '{"A":"Over","B":"In","C":"For","D":"Against","E":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Compensate for” means ازالہ کرنا یا معاوضہ ادا کرنا (کسی نقصان پر) Belongings means سامان وغیرہHe was compensated for the loss.', 0, 0, 0, 1790961815583) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_16966d737e87c043', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'We should always stick to our decisions otherwise the people will mock ____ us.', '{"A":"With","B":"For","C":"To","D":"At","E":"In"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The words mock and laugh are always followed by at.At is a preposition here.Mock at someone means کسی پر ہنسنا یا مزاق اڑانا', 0, 0, 0, 1790961815583) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_75bb17605b4838d6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He mocks at me.', '{"A":"I am mocked at by him","B":"I was mocked at to him","C":"I will be mocked at him","D":"All Of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He mocks at me is a tense of present indefinite tense.Mock + at (fixed preposition) Mock at means مذاق اڑاناPresent Indefinite TenseActive Voice: Subject + Verb + Object Passive Voice: Object + is/am/are+ third form of a verb + by + subject.', 0, 0, 0, 1790961815583) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c1e7e23551febe28', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'You must adapt yourself _____ your new surroundings.', '{"A":"Towards","B":"For","C":"To","D":"By","E":"In"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Adapt is generally followed by to. To is a preposition here. Adapt to means ڈھالنا You must adapt yourself to your new surroundings.', 0, 0, 0, 1790961815583) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_93c632fc3c29f9b8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Who painted it:', '{"A":"whom was it painted by","B":"By  whom it was painted by","C":"it had  painted by whom","D":"none of the above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active voice: WhoPassive voice: By whomActive: Who painted it?Passive: By whom was it painted?', 0, 0, 0, 1790961815583) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_52587f749433768a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Are you…….that house?', '{"A":"Buy","B":"Buys","C":"Buying","D":"Bought"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Are you Buying that house?کیا آپ وہ گھر خرید رہے ہیں؟***"Buying" is a verb (used with object), bought, buy·ing."Buying" is best to keep the meaning of the original sentence**The "-ing" form can function as a noun. These nouns are called gerunds and can be the subject of a clause, followed by a third-person singular (he/she/it) form of the verb', 0, 0, 0, 1790961815583) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_15657e10e6b57fcd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He does not leave his house --- 9 am', '{"A":"on","B":"in","C":"at","D":"by"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We can also use by before a specific time.By is a preposition here.Here by 9 means نو بجے تک', 0, 0, 0, 1790961815583) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_263bed83f6640894', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He has decorated his brother''s house with colorful lights', '{"A":"His brothers''s house had been decorated by him with colorful lights","B":"His brothers''s house have been decorated by him with colorful lights","C":"His brothers''s house has been decorated by him with colorful lights","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Formula of Passive verb: put has/have + been before the past participle form of the verb. Active voice: He has decorated his brother''s house with colorful lights. Passive voice: His brothers''s house has been decorated by him with colorful lights', 0, 0, 0, 1790961815583) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c1d1c6276583c735', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'My family rented a beach house for our summer vacations . rented is', '{"A":"infinitive","B":"transitive verb","C":"interjection","D":"article"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A transitive verb is a verb that accepts one or more objects. This contrasts with intransitive verbs, which do not have objects.', 0, 0, 0, 1790961815666) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6e060103dbb1aa05', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They had a lot of difficulty ____________ finding the house.', '{"A":"To","B":"In","C":"With","D":"Upon","E":"All of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Difficulty in doing something makes sense.In finding the house means مکان کو تلاش کرنے میں', 0, 0, 0, 1790961815666) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1115e39a87512c9f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'We can not get ____ the house without a key.', '{"A":"into","B":"onto","C":"in","D":"none"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We can not get into the house without a key.Into refers a motion. Into is a preposition here.', 0, 0, 0, 1790961815666) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8df9f289fddcac7e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I was very tired. _______, I could not join them.', '{"A":"Meanwhile","B":"Furthermore","C":"For Example","D":"Consequently","E":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Here Consequently means جس کے نتیجے میں', 0, 0, 0, 1790961815666) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1dd03f68a576b52a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He got tired _________ over work.', '{"A":"Over","B":"Because of","C":"For","D":"With"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He got tired because of over work.Because: کسی وجہ کو ظاہر کرتا ہے Because is a conjunction.', 0, 0, 0, 1790961815666) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_061b9da46eedb85e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'You should not jest ___________ his poverty.', '{"A":"On","B":"Of","C":"In","D":"At","E":"With"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We use at after jest and laugh. Jest at someone means کسی کا مذاق اڑاناAt is a preposition. We should never jest at his poverty.', 0, 0, 0, 1790961815666) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_29ef50aaa7034b56', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I told the tailor to put red buttons _____ the dress he is making for me.', '{"A":"In","B":"With","C":"On","D":"From","E":"Of"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I told the tailor to put red buttons on the dress he is making for me. If you are an expert, let us know more details about this question please', 0, 0, 0, 1790961815666) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fc5224d8f2f1b6d9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I am not acquainted ____ her father.', '{"A":"Of","B":"With","C":"On","D":"From","E":"In"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Acquainted is followed by with.With is a preposition here.Acquainted with someone means کسی سے واقفیت ہوناI am not acquainted with her father.', 0, 0, 0, 1790961815666) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_85065936fd5469da', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I looked _______ her children when she was ____ hospital', '{"A":"After, In","B":"After, At","C":"At, In","D":"Towards, at"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Look after is a phrasal verb which means دیکھ بھال کرناIn hospital means that you are a patient in the hospital.I looked after her children when she was in hospital.AGM 08-01-2023', 0, 0, 0, 1790961815732) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1c0a149c475238b7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I parted the curtains……looked out into the audience.', '{"A":"And","B":"but","C":"we","D":"are"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I parted the curtains and looked out into the audience***"And" can only be used once in a sentence to connect big ideas. "And" can be used two times in a sentence when making a list of things.And can be used in the following ways: as conjunction (joining two words, phrases, or clauses):', 0, 0, 0, 1790961815732) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f9c45dcda3237d4e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'You will be well looked after.', '{"A":"They will look after you well","B":"They can look after you well","C":"They may look after you well","D":"They shall look after you well","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Future Indefinite Tense-Passive Voice Convert Active object into subject of the Passive.use helping verb will be/shall be. use 3rd form of Verb. After that, use the word “by”, in order to show the doer.Correct passive: They will look after you well', 0, 0, 0, 1790961815732) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d9f7e7d3ae9870a5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I was writing on the book ____ is mine when he arrived.', '{"A":"Which","B":"Who","C":"Whome","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We use which to refer to animals and to things.Which is a Relative Pronoun here.', 0, 0, 0, 1790961815732) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0b8eff8fa9cb4f64', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He succeeded ____ killing the tiger.', '{"A":"Into","B":"From","C":"Of","D":"In","E":"On"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We generally use in after succeed.In is a preposition here.Succeed in something means کسی کام میں کامیاب ہونا', 0, 0, 0, 1790961815732) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a9220e0b1da16a59', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She succeeded by __________ hard.', '{"A":"Work","B":"Working","C":"Continuous work","D":"Continuous working","E":"Works"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation She succeeded by working hard means وہ سخت محنت سے کامیاب ہوئی ی Either third form of verb or ing form of verb is used after by.', 0, 0, 0, 1790961815732) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6238039e4bead61c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Everyone should _____________ himself against illness since medical care has now become expensive.', '{"A":"Vaccinate","B":"Insure","C":"Brace","D":"Ensure","E":"All of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Insure means کسی نقصان کی بنا پر انتظام کرنا', 0, 0, 0, 1790961815732) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_68de029a0dc378f1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Alice is not at home at the movement . She ____ work .', '{"A":"Is at","B":"Is on","C":"Was at","D":"Was on"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation She is at work .We usually use preposition at before work. ******RY 15-01-2023', 0, 0, 0, 1790961815732) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a315827497b62bef', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Even Children in the elementary schools ________ assigned homework.', '{"A":"Is","B":"Are","C":"Was","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Child is a singular noun.Children is a plural noun.We use plural verb (are) with plural noun (children.Children are assigned homework.', 0, 0, 0, 1790961815811) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_087920c4f1487985', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He was arrested at his home.', '{"A":"At his home he was arrested by the police","B":"Police arrested him at his home","C":"Police had arrested him at his home","D":"Police have arrested him at his home"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This is a a sentence of Past Indefinite Tense.Active Voice= Subject + Second Form of Verb + Object. Passive Voice = Object + was/were + third of verb + by + subject.Police arrested him at his home', 0, 0, 0, 1790961815811) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0b3466d873cf386e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I need to go back home. I think I left ___ stove on.', '{"A":"A","B":"An","C":"The","D":"No article"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I need to go back home. I think I left the stove on.We use article The for particular nouns.', 0, 0, 0, 1790961815811) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_373137bd7d6bef06', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Must finish your homework ___ two hours.', '{"A":"of","B":"for","C":"into","D":"Within","E":"on"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Within is used to express that some stated time or less will pass before something happens.Within two hours means دو گھنٹوں کے اندر اندر', 0, 0, 0, 1790961815811) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3ef96038e61014fd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'My new home is not ___________finished.', '{"A":"Altogether","B":"All together","C":"All by together","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation My new home is not altogether finishedAltogether is an adverb that means completely/totally. ND06-08-2023', 0, 0, 0, 1790961815811) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e6b7051019cf1644', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She arrived ___________ her home.', '{"A":"At","B":"To","C":"Towards","D":"Above","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Note:- If “possessive adjective” or “a noun with an apostrophe” is used before “home”, “to” or "at" is used before “home” only in case of specific verbs (Not with “arrive” and “reach”.She arrived at his home means وہ اس کے گھر پہنچی تھی', 0, 0, 0, 1790961815811) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_efb5e1d8a19e2f31', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She lost her home and all her money but she never lost her____________', '{"A":"Modesty","B":"Dignity","C":"Pride","D":"None of these","E":"All of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation She lost her home and all her money but she never lost her dignity. Dignity means عزت و وقار', 0, 0, 0, 1790961815811) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9233daa9e94d04ca', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She made her children _________ their homework every evening.', '{"A":"Do","B":"To do","C":"Doing","D":"Did","E":"All of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Do is the first form of verb.Someone can make someone to do something.She made her children do work.', 0, 0, 0, 1790961815811) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fdef2add51f371df', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They were brought ___________ home.', '{"A":"To","B":"Too","C":"Into","D":"In","E":"No preposition required"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Note:- We do not use any preposition before “Home” with the following verbs.Go, Bring, Get, Reach, Arrive & Come.Brought is the second and third form of Bring.', 0, 0, 0, 1790961815895) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bb86f8469bb8c174', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She (as well as) her sister is engaged.', '{"A":"Adverb","B":"Adjective","C":"Preposition","D":"Conjunction"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation She (as well as) her sister is engaged.** (as well as) : Conjunction ''As well as is a conjunction (a connecting word or phrase) that means ''in addition to', 0, 0, 0, 1790961815895) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_056340dcaddf00da', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'In what are you engaged _____ present?', '{"A":"In","B":"With","C":"From","D":"At"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Generally at is used before present.In what are you engaged at present?', 0, 0, 0, 1790961815895) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3f4ab1ee4f94d613', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He is aware __________ and engaged in his work.', '{"A":"Of","B":"With","C":"Off","D":"To","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Generally aware is followed by of.Aware of something means باخبر رہنا، آگاہ رہناHe is aware of and engaged in his work.', 0, 0, 0, 1790961815895) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2a62ca786657aec7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Travelling from place to place is called', '{"A":"journeying","B":"itinerant","C":"vacationing","D":"none"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Itinerant means travelling from place to place.Itinerant means سفری یا خانہ بدوش', 0, 0, 0, 1790961815895) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9d76a4b9ec54c5cb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'While travelling to Karachi, I ran __________ a very old friend of mine.', '{"A":"Up","B":"Across","C":"Against","D":"Into","E":"Of"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Run into someone is a phrasal verb which means کسی سے غیر متوقع طور پر ملنا', 0, 0, 0, 1790961815895) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8e2c0de7a3520505', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'You are fond _____ music.', '{"A":"On","B":"From","C":"Of","D":"Off"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Generally fond is followed by of.Fond of means کسی چیز کا شوقین ہوناYou are fond of music.', 0, 0, 0, 1790961815895) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_68a7fb9c46198f06', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I am fond _________ reading newspapers.', '{"A":"Off","B":"Of","C":"In","D":"For","E":"With"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Generally fond is followed by of.Fond of means کسی چیز کا شوقین ہوناI am fond of reading newspapers.', 0, 0, 0, 1790961815895) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8e672b1951c550ce', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He was sick _________ hunger. He hadn’t eaten anything for two days.', '{"A":"By","B":"At","C":"With","D":"From"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation With is used in a number of expressions that say how people express their emotions and sensations.', 0, 0, 0, 1790961815985) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a8c4e5da763cd72b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'According to me, she is sick or As I know, she is sick. (Sentence Correction)', '{"A":"According to me, she is sick.","B":"As far as I know, she is sick.","C":"\"In my opinion, she is sick.","D":"Both B&C"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "As far as I know, she is sick" is correct and commonly used. It means that based on the information you have, you believe she is sick."In my opinion, she is sick" is also correct. It expresses your personal belief or judgment.So, the correct and more natural options are:B) As far as I know, she is sick.C) In my opinion, she is sick.', 0, 0, 0, 1790961815985) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_edfcd9317cbae798', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He is capable __________ doing this work within the stipulated period.', '{"A":"At","B":"Of","C":"From","D":"With","E":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He is capable of doing this work.Generally of is used after capable.', 0, 0, 0, 1790961815985) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bd754396bac35901', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She is capable of winning the race. (Here WINNING is used as)', '{"A":"participle","B":"gerund","C":"noun","D":"pronoun"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A participle is a verbal that is used as an adjective and most often ends in -ing or -ed. Winning is used as participle', 0, 0, 0, 1790961815985) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e3a0942f1e88d262', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It is our problem, not _______________?', '{"A":"There","B":"Their","C":"Theirs","D":"Them"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Here theirs is a pronoun which means ان کا', 0, 0, 0, 1790961815985) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d37f8c2be3fb2742', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The main problem Jim __ too many parking tickets.', '{"A":"will have","B":"will have been","C":"was","D":"were"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We use will have when we are looking back from a point in time in the future: By the end of the decade, scientists will have discovered a cure for influenza.', 0, 0, 0, 1790961815985) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_30cb18ac54dab809', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'We must now deal with these problems.', '{"A":"These problems must be dealt with by us","B":"These problems must now be dealing with by us","C":"These problems must now deal with by us","D":"These problems are to be dealt with by us","E":"All of  the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Deal is a verb.Dealt is the second and third form of Deal.Active: We must now deal with these problems.Passive: These problems must be dealt with by us.', 0, 0, 0, 1790961815985) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f5f4e68e36639952', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'We need to find ________ method to solve this problem.', '{"A":"Other","B":"The other","C":"Another","D":"Others"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We need to find another method. Here another is a pronoun.Another means ایک اور', 0, 0, 0, 1790961815985) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f64c4777cb4c3cc6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Who solved that problem?', '{"A":"By whom is that problem solved?","B":"By whom will that problem be solved?","C":"By whom can that problem be solved?","D":"By whom was that problem solved?"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice: WhoPassive Voice: By whomThis is a sentence of Past Indefinite Tense.Was and Were are the helping verbs of Past Indefinite Tense.Active: Who solved that problem?Passive: By whom was that problem solved?', 0, 0, 0, 1790961816074) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_10276af715760a21', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Honest and hardworking people____ liked by everyone.', '{"A":"Are","B":"Is","C":"Am","D":"Was"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Honest and hardworking people Are liked by everyone***we use the word " are" because there is more than one noun, such as "Honest and hardworking people"', 0, 0, 0, 1790961816075) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5603954e44d76f24', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He advised ____________ me to work hard.', '{"A":"To","B":"With","C":"Beyond","D":"Above","E":"No Preposition Required"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “To” should not be used with “Advise, ask, beg, tell, command, encourage, request, inform, thank, welcome, warn, forbid, order, remind, congratulate, compliment” He advised me to work hard.', 0, 0, 0, 1790961816075) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9ac27c606ac49b63', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He worked hard lest he _____ fare badly at the examination .', '{"A":"would","B":"could","C":"should","D":"none"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Should is used to give advice and to make recommendations. It is also used to express obligation and expectation.', 0, 0, 0, 1790961816075) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8e4d6b7a88f5715d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Work Hard.', '{"A":"You are advised to work hard","B":"You were advised to work hard","C":"You will be advised to work hard","D":"You should be advised to work hard","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Order: Let + object + be + third form of a verbSuggestion: Object + should be + third form of a verbRequest: You are requested/advised to + first form of a verb + object. Note: Please and kindly are not used in passive voice.', 0, 0, 0, 1790961816075) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_64d1df99d512f034', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '_______ Chinese were hardworking and had the usual fortune attending those who work hard', '{"A":"A","B":"An","C":"The","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Usually Article the is used for Nationality.Like, The Chinese, The Japanese, The Indian', 0, 0, 0, 1790961816075) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fa0e4eaf102a6091', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I took the glass and hide it _________ the table.', '{"A":"Below","B":"Under","C":"Above","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We use preposition under to indicate beneath of something. I hide it under the table.', 0, 0, 0, 1790961816075) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8e1feb8bb6e722fc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I brought him a glass of water. Brought word is', '{"A":"Direct objective","B":"Indirect objective","C":"Subject","D":"Adjective"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A direct object is a word or phrase that receives the action of the verb. The students eat cake, the direct object is cake; the word eat is the verb and cake is what''s being eaten.', 0, 0, 0, 1790961816075) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_af02d3db89f65d19', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'His income ___ than yours', '{"A":"less","B":"is less","C":"least","D":"little"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation less means کمHis income is less than yours.', 0, 0, 0, 1790961816147) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5b7c8b33b1f417dc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Just take care of yourself. (Here OF is an example of)', '{"A":"Preposition","B":"Noun","C":"Verb","D":"Adjective","E":"Adverb"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Words like Of, Off, In, Into, On, Near, Beside etc are considered to be Prepositions. AGM 08-01-2023', 0, 0, 0, 1790961816147) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_af881ab660384206', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The District Police Officer is invested _____ Magistrate Powers.', '{"A":"for","B":"of","C":"with","D":"none of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The District Police Officer is invested with Magistrate Powers. We use preposition with to show additional powers of someone.', 0, 0, 0, 1790961816147) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_55edb23f7c0d66c5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '____ by_________ she is becoming weaker.', '{"A":"Day/Day","B":"Days/Days","C":"Day/Days","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation If two nouns are joined by preposition, the noun on either side singular and the verb is also singular.Day by day is the correct sentence.', 0, 0, 0, 1790961816147) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_adcfceb5ce492cd4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He is afraid ___ change', '{"A":"of","B":"in","C":"at","D":"on"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Afraid is generally followed by preposition of.Afraid of means خوفزدہ', 0, 0, 0, 1790961816147) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bf2ea442d7e66ac8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Don`t worry. There is nothing to be afraid ____.', '{"A":"In","B":"Of","C":"At","D":"To","E":"With"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Afraid is generally followed by preposition of.Afraid of means خوفزدہ', 0, 0, 0, 1790961816147) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0920b17b15294a3d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'There is a mosque to worship.', '{"A":"There was a mosque to be worshiped","B":"There will be a mosque to be worshiped","C":"There is a mosque to be worshiped","D":"None of the above","E":"All of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There is a mosque to worship is a sentence of present tense.Worship is a verb, worshiped is the second and third form of worship.Passive voice: There is a mosque to be worshiped', 0, 0, 0, 1790961816147) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0e6cde231efe3938', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'How would you escape ____ the locked room?', '{"A":"In","B":"Of","C":"From","D":"Between"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Escape is generally followed by from.Escape from means بچ نکلنا', 0, 0, 0, 1790961816147) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_59b70c48d32432bf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Heavy rain prevented us __________ going to the cinema.', '{"A":"From","B":"To","C":"Towards","D":"With","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prevent someone from something.Prevent someone from doing something means کسی کو کسی کام سے روکنا', 0, 0, 0, 1790961816241) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f5561fe6a82a02fe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The noise from all the Aeroplanes __ louder in the afternoon.', '{"A":"gets","B":"get","C":"have gotten","D":"none"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The word Noise is singular.We use gets with singular nouns.Since this is a continuous action, we need to use Present Indefinite Tense here.', 0, 0, 0, 1790961816241) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_10a09bbdb04c438f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'We found that Ali and Fatima___ not attending Ahmad''s wedding ceremony', '{"A":"is","B":"are","C":"was","D":"were"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ali and Fatima are two names that`s why we need to put plural helping verb i.e. Were.', 0, 0, 0, 1790961816241) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_38df705d6cfb021c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Villagers fell all the trees.', '{"A":"All the trees are felled by villagers","B":"All the trees were felled by villagers","C":"All the trees will be  felled by villagers","D":"All the trees should be felled by villagers","E":"All of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This is a sentence of Past Indefinite Tense.Fell means گراناFelled is the second and third form of Fell.Active Voice: Villagers fell all the trees.Passive voice: All the trees were felled by villagers', 0, 0, 0, 1790961816241) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5b5b589d5e9aca59', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Try to reach the village ........ the sunset.', '{"A":"Upon","B":"On","C":"With","D":"In","E":"Before"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The preposition “before” means پہلے پہلے Before means prior to.', 0, 0, 0, 1790961816241) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_844223e0a6fb1f03', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Hundreds of townsmen and thousands of villagers _______ assembled in the field.', '{"A":"Was","B":"were","C":"is","D":"am"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hundreds of generally takes a plural noun (villagers) and plural verb (were).', 0, 0, 0, 1790961816241) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1f857613a0d8cad1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They like swimming. Whenever they have a leisure time. (Which word is a verbal noun?)', '{"A":"Leisure","B":"Time","C":"Like","D":"Swimming"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The verbal noun is a verb which functions as a noun.Swimming is functioning as a noun here.', 0, 0, 0, 1790961816241) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a33ab5a2e07e463b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They were not swimming.', '{"A":"وہ کھانہیں رئے تھے","B":"وہ کھیل نہیں رئے تھے","C":"وہ پڑھ نہیں رئے تھے","D":"ان میں سے کوئی نہیں"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation They were not swiming means وہ تیر نہیں رئے تھےHere the word swim is a verb which means تیرنا', 0, 0, 0, 1790961816241) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dbfe4078e9c6d893', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '______ boy is swimming in the pool.', '{"A":"A","B":"An","C":"The","D":"No Article required"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Here boy is not specific.We use the for specific nouns.A boy is swimming in the pool. (Correct)', 0, 0, 0, 1790961816314) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_34395b552604c1a6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '_____________ fire broke out in his village last night.', '{"A":"The","B":"An","C":"A","D":"No article required"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Article A is used because F gives consonant sound.To break out is a phrasal verb which means اچانک بھڑک اٹھنا', 0, 0, 0, 1790961816314) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8a0e0ca24278d088', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She was very angry _____ my behaviour.', '{"A":"At","B":"On","C":"With","D":"From","E":"Of"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Angry with someone means کسی سے ناراض ہوناAngry with: کسی انسان سے ناراض ہوناAngry on: کسی بات پہ ناراض ہوناAngry at برتاو یا رویے پر ناراض ہونا', 0, 0, 0, 1790961816314) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f35eb0348437163e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Everyone in this universe is accountable to God ----his actions .', '{"A":"for","B":"against","C":"of","D":"about"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation For is a preposition here.For is used to refer a reason.For actions means اعمال کےلئے', 0, 0, 0, 1790961816314) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5016e619e8f621f1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I am envious ____ his new car .', '{"A":"From","B":"For","C":"Of","D":"Between"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Envious is generally followed by of.Envious of means jealous of.Envious means حاسد', 0, 0, 0, 1790961816314) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_53fc65486b22f75d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He is good ________ tennis.', '{"A":"Of","B":"At","C":"On","D":"For"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Be good at something means be expert.Good at means ماہر ہونا', 0, 0, 0, 1790961816314) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e017c50c7c246b29', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I am quite content to stay here. (Here content means)', '{"A":"Happy","B":"Frightened","C":"Eager","D":"Determined"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Content means خوش یا مطئمن ہوناHappy means خوش ہوناI am content to stay here means میں یہاں رہنے کیلئے خوش ہوں', 0, 0, 0, 1790961816314) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0b19227cccf7f667', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'You can go neither by train ___ by Bus', '{"A":"no","B":"nor","C":"or","D":"and"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation You can go neither by train nor by Bus Neither and nor means ناتو یہ ناتو وہ******', 0, 0, 0, 1790961816314) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dfdecfe5517748dd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Kindly help me.', '{"A":"You are requested to help me","B":"You were requested to help me","C":"You should be requested to help me","D":"You can be requested to help me","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Order: Let + object + be + third form of a verbSuggestion: Object + should be + third form of a verbRequest: You are requested/advised to + first form of a verb + object. Note: Please and kindly are not used in passive voice.', 0, 0, 0, 1790961816401) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_409c79b45efe50d7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Why did you not agree to my proposal?', '{"A":"Why was my proposal not agreed to by you?","B":"Why is my proposal not agreed to by you?","C":"Why will my proposal not agreed to by you?","D":"Why can my proposal not agreed to by you?","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice: Why did you not agree to my proposal? Passive Voice: Why was my proposal not agreed to by you?Past Indefinite tenseActive Voice= Subject + Second Form of Verb + Object. Passive Voice = Object + was/were + third of verb + by + subject.', 0, 0, 0, 1790961816401) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ca016a06cabe4ab5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I differ _________ you on the views of life.', '{"A":"By","B":"with","C":"for","D":"to"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Differ with means اختلاف رکھناI differ with you on the views of life.', 0, 0, 0, 1790961816401) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9ba0cd99b0f05cac', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I thanked ______ him.', '{"A":"To","B":"Of","C":"Off","D":"On","E":"No Preposition Required"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “To” should not be used with the following verbs when followed by an object “Advise, ask, beg, tell, command, encourage, request, inform, thank, welcome, warn, forbid, order, remind, congratulate, compliment” I thanked him.', 0, 0, 0, 1790961816401) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6769edfefc0b7c63', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'You are ____ Afridi of our class.', '{"A":"A","B":"An","C":"The","D":"No article"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To show similarity ÷ A/An or The = proper noun.', 0, 0, 0, 1790961816401) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2ec9933beba5a194', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I am ____________ sure as you are.', '{"A":"Quite","B":"As","C":"Very","D":"Perfectly"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I am as sure of it as you are“As … as” is used to show equality.', 0, 0, 0, 1790961816401) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_891abe01ecddeed7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The train was ____________ time.', '{"A":"Behind","B":"Beyond","C":"During","D":"With","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Usage of Behind Behind --- In, to or towards the near or later in time.Examples: He followed behind.The girls were far behind the car. The train was behind time.', 0, 0, 0, 1790961816401) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cf84f77ecf64f96d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The train has passed ____________ the tunnel.', '{"A":"Through","B":"Within","C":"Into","D":"To","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The train has passed through the tunnel."Through" is used when something moves from one side to the other side of an enclosed space (like a tunnel). "Within" means "inside" and would not fit here', 0, 0, 0, 1790961816401) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_90b893b40cd5c9f4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I will go there by train or by ______ bus.', '{"A":"A","B":"An","C":"The","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Go by train or by a bus.A is an article here.Here A bus means کسی بس پر', 0, 0, 0, 1790961816490) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ed61bfe623ce96aa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'At last he yielded __________ the temptation.', '{"A":"Off","B":"About","C":"On","D":"To"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation At last, he yielded to the temptationThe phrase "yield to" indicates that you are surrendering To" shows the receiver of the action (the temptation).', 0, 0, 0, 1790961816490) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_83a11ac1f9d6989f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It was warm, so I ------------------ off my coat.', '{"A":"Put","B":"Put on","C":"ear","D":"Putt off"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation It was warm, so I put off my coat.***put off. verb. cause to feel intense dislike or distaste.', 0, 0, 0, 1790961816490) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2468ad0e2f397aa9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'A tree fell ________ the railway line that caused an accident.', '{"A":"Across","B":"Into","C":"On","D":"Till","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Across has two different meanings.1.On the opposite sideFor Example: She has been waiting for me across the road.2. Both sides For Example: A tree fell across the railway line that caused an accident.', 0, 0, 0, 1790961816490) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b97e044d82843924', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I fell over _________ chair again.', '{"A":"an","B":"a","C":"the","D":"on"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I fell over the chair again.(The chair is specific. It is known to the audience.)', 0, 0, 0, 1790961816490) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0330f86fbf3e3731', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They sometimes fell------------ for the mountains and see.', '{"A":"Tearing","B":"Yelling","C":"yielding","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation They sometimes fell yelling for the mountains and see.....yelling at someone means چیخناyelling means shouting at someone or something, usually in anger.', 0, 0, 0, 1790961816490) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c268bb3ac12e1e6b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I am grateful ____ you for the timely help.', '{"A":"To","B":"With","C":"For","D":"Up"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Generally grateful is followed by to.Grateful to someone means کسی انسان کا احسان مند ہوناGrateful for something means کسی چیز کیلئے احسان مند ہوناI am grateful to you for the timely help.', 0, 0, 0, 1790961816490) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_16b0b41d15fdbfe1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She is going to quit her job-------- they give her pay rice?', '{"A":"or","B":"until","C":"unless","D":"providing"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Conditional clauses can begin with unless. Unless means something similar to ‘if … not’ or ‘except if’."the above sentence is " related to the conditional situation" So we select " the option unless" **ND10-1-2023', 0, 0, 0, 1790961816490) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_23d3bcb1b6d153c9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The girl is sitting ___ her mother', '{"A":"Besides","B":"Beside","C":"With","D":"On"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The girl is sitting beside her mother.Beside: Means "next to" or "at the side of". It indicates the girl is sitting right next to her mother.Last update question on NA 29 June 2026', 0, 0, 0, 1790961816578) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_914c1a019d5df14b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She resembles ______ her mother.', '{"A":"With","B":"To","C":"At","D":"From","E":"Of"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The word Resemble is followed by To.Resemble to mother means والدہ سے مشابہت رکھنا', 0, 0, 0, 1790961816578) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f863e29659004e68', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I am reading a novel that my mother ____________ last year.', '{"A":"Is","B":"Will","C":"Be","D":"Had","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The had is also used to show past possessions.She had a book.I had a phone. He had a car.', 0, 0, 0, 1790961816578) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_267cf125fc9d6d6a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He has not met her Mother___ long;', '{"A":"Since","B":"For","C":"At","D":"With"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Since long is a phrase which means a long time ago.Since long means کافی عرصے سے', 0, 0, 0, 1790961816578) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_571dd65cd5634390', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Neha is traveling _____the school', '{"A":"Off","B":"Of","C":"Toward","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Neha is traveling toward the school****The preposition to·wards is used in the direction of somewhereFor example, Neha is traveling in the direction (toward) the schoolSo the option "toward" is the best to keep the meaning of the original sentenceSH24-8-2023', 0, 0, 0, 1790961816578) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6aee7a01631ed7e9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Do you have--- passport? you need --- passport to travel outside--- country.', '{"A":"a/a","B":"the/the","C":"an /the","D":"a/a./the"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Article A is used before common things, places or persons.Article The is used before particular things, person or places.', 0, 0, 0, 1790961816578) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_919a9109a7611d85', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Check the weather condition _____ travelling.', '{"A":"Previous","B":"Earlier","C":"Initial","D":"None of the above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Check the weather condition before traveling.Main uses of before (earlier than)Before means earlier than the time or event mentionedND13-07-2023', 0, 0, 0, 1790961816578) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ec58b3dfaa1e7fbe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '____________ Arshad, Aslam was also present in the meeting.', '{"A":"Beside","B":"Besides","C":"On","D":"Upon","E":"From"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Beside means بغل میںBesides means کے علاوہ Besides Arshad means ارشد کے علاوہ', 0, 0, 0, 1790961816578) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a1e3e98b17a645df', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Antonyms of Dishevelled.', '{"A":"untidy","B":"unkempt","C":"scruffy","D":"tidy"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Disheveled منتشر۔ خراب کرنا, بے ترتیب کرناTidy صاف ستھرا, نفیس', 0, 0, 0, 1790961816668) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ee9ba545f947cd5a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Jane took a little nap. (Here LITTLE is an example of)', '{"A":"Adverb","B":"Adjective","C":"Noun","D":"Preposition"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In linguistics, an adjective is a word that modifies a noun or noun phrase or describes its referent.Little is used as adjective', 0, 0, 0, 1790961816668) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7b906b17fc8cce96', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'You are blind ________ your shortcomings.', '{"A":"In","B":"on","C":"to","D":"of","E":"All of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Blind means اندھاBlind to means عقل سے اندھا Blind in means ایک آنکھ سے اندھا', 0, 0, 0, 1790961816668) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_43d670201544dd59', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She _________ working in a factory since 2007.', '{"A":"is","B":"has been","C":"was","D":"had"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation She has been working in a factory since 2007.Words like, morning, evening, midnight, June 2014, etc. are generally followed by the preposition Since.', 0, 0, 0, 1790961816668) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_78b261641986e8c5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The bridge was built ________ the river', '{"A":"On","B":"Over","C":"Into","D":"Upon","E":"All of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Over is sometimes also used to cover the whole surface no matter whether there is physical contact or not. The bridge was built over the river means دریا پر پل تعمیر کی گئی', 0, 0, 0, 1790961816668) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ea2f20b05510b779', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'We suffer __________ you neglect.', '{"A":"To","B":"From","C":"Of","D":"With"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We suffer from you neglect.We always use preposition From after suffer.Suffer from something means متاثر ہونا', 0, 0, 0, 1790961816668) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fdf3f21fb693cfa2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He is ______ doctor.', '{"A":"A","B":"An","C":"The","D":"No Article"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We use Articles A & An before professions.Doctor gives consonant sound. Therefore, He is a doctor۔ I am a student. She is a teacher. کسی کا شعبہ یا فیلڈ بتانے کیلئے ہم (ارٹیکل اے) کا استعمال کرتے ہیں۔We use an when the profession gives vowel sound.e.g. She is an actress. You are an actor. I am an author.', 0, 0, 0, 1790961816668) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2c25a2d4c13fcbab', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'If Naseem is older than Waseem but Younger than Ahmed who is the oldest?', '{"A":"Naseem","B":"Waseem","C":"Ahmed","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ahme is oldest because Naseem is older than Waseem and Waseem is younger than Ahmed', 0, 0, 0, 1790961816668) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8c3d42ec3999713e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She did not eat any fruit. (Here ANY is an example of)', '{"A":"Noun","B":"Adverb","C":"Adjective","D":"Preposition","E":"Interjection"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The word Any is an Adverb which is used in Negative sentence.', 0, 0, 0, 1790961816736) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_64dad0d7379c131d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Cartography is the science of drawing:', '{"A":"Isotherns","B":"Maps","C":"Isobars","D":"Village life scenes"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cartography is the art and science of graphically representing a geographical area​, usually on a flat surface such as a map or chart.Cartography means نقشہ نگاری', 0, 0, 0, 1790961816736) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0aa301ca1a21ec41', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Even if she _______ them, they wouldn’t have come.', '{"A":"Asks","B":"Has asked","C":"Had asked","D":"Would ask","E":"Would have asked"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Even if she had asked them, they wouldn’t have come.Formula for third conditional sentences: If + past perfect, would/wouldn''t have + past participle. MUG 11-12-2022', 0, 0, 0, 1790961816736) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c582b014f2d0a187', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '____ keys are these?', '{"A":"which","B":"who","C":"whose","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Whose is a possessive pronoun. Use it when you''re asking to whom something belongs.', 0, 0, 0, 1790961816736) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_aebbe0bc10d3f24f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The plural form of the word GUY is:', '{"A":"Guyz","B":"Guys","C":"Guyes","D":"Guy"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Guy means کوئی آدمی لڑکا یا شخصGuy is a noun.Guys is the plural of Guy.', 0, 0, 0, 1790961816736) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_66cea5dcff90f435', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He can afford to be generous _________ he is rich.', '{"A":"That","B":"If so","C":"Because","D":"Unless"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Here that means وہ Because means کیوںکہ while unless means جب تک', 0, 0, 0, 1790961816736) ON CONFLICT(id) DO NOTHING;
