INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8ff0406f0589bd7a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I''ve read this paragraph three times, and I ___ understand it', '{"A":"can''t still","B":"can''t yet","C":"still can''t","D":"none"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I''ve read this paragraph three times, and I still can''t understand itمیں نے اس پیراگراف کو تین بار پڑھا ہے، اور میں اب بھی اسے سمجھ نہیں پایاstill can''tاب بھی نہیں کر سکتےcan is verb******RY 23-12-2022Sh16-8-2023', 0, 0, 0, 1790961816736) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dd69adfe1964958f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Choose the one which best expresses the meaning of the given word. FATIGUE:', '{"A":"Sweating","B":"Drowsiness","C":"Weariness","D":"Tension"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation FATIGUE: تھکاوٹWeariness: تھکاوٹ*******VU FIA PAPER 18-12-2021******RY 23-12-2022', 0, 0, 0, 1790961816818) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5842b6cceaa98c21', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'If sheep is to whool as cat is to?', '{"A":"hair","B":"fur","C":"head","D":"none of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation If sheep is to whool as the cat is to fur.Whool is a fiber obtained from sheep Similarly, fur is a fiber obtained from the cat.sheep skin is converted into wool while that of cat is converted into fur.', 0, 0, 0, 1790961816818) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3ccc7ca8d95238ab', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'KEEP: IMPREGNABLE :', '{"A":"Message : indecipherable","B":"compartment : sealed","C":"code : unbreakable","D":"warrior : invincible"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation IMPREGNABLE: not capable of being captured or entered by forceWarrior: a person taking part or experienced in conflict, esp. war; soldierinvincible: that cannot be overcome; unconquerableKEEP:رکھوIMPREGNABLE: ناقابل تسخیرWarrior:جنگجوinvincible ناقابل تسخیرND4-12-2022', 0, 0, 0, 1790961816818) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c50707dbab2b1663', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'PLAUSIBLE: EXPLANATION::', '{"A":"Gullible : deception","B":"watertight : alibi","C":"attractive : proposal","D":"defensible : theory"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation PLAUSIBLE: قابل تعریفEXPLANATION: وضاحت defensible: قابل دفاع theory: نظریہND4-12-2022', 0, 0, 0, 1790961816818) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_87731d8e3dcc7dab', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Wow!, Ah!, Oh! are the examples of', '{"A":"Preposition","B":"Conjunction","C":"Interjection","D":"Noun"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An interjection is a part of speech that shows the emotion or feelings of the author. Interjection means حروف فجائیہ Ouch!, wow! Oh! Are examples of interjection******ND3-12-2022', 0, 0, 0, 1790961816818) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a99f41ec1163fb60', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The cost of living is ___. Every year things are more expensive .', '{"A":"Expensive","B":"Diminishing","C":"Rising","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The cost of living is the amount a person needs to spend to cover basic expenses such as housing, food, taxes, and healthcare in a particular place.', 0, 0, 0, 1790961816818) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cfcbc1fe7cc9b335', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'You need not worry that you will be left on your own because I'' ll always ___ you.', '{"A":"Stand for","B":"Stand with","C":"Stand by","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The phrase Stand By someone means کسی کا ساتھ دیناMUG 05-12-2022', 0, 0, 0, 1790961816818) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f3d145c8384c2aea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I have been studying __________ three months.', '{"A":"Since","B":"For","C":"With","D":"Within","E":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation .For = period of time For example: I have been studying for three months میں تین ماہ سے مطالعہ کررہا ہوں', 0, 0, 0, 1790961816818) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e106a86167e2643b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I like teaching ____ children.', '{"A":"A","B":"An","C":"The","D":"No article"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I like teaching children.میں بچوں کو پڑھانا پسند کرتا ہوں۔No article required', 0, 0, 0, 1790961816903) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bb75f546ac5328da', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Iqbal was popular ____ the people.', '{"A":"Among","B":"With","C":"For","D":"To"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Iqbal was popular among the people means اقبال لوگوں میں مقبول تھے', 0, 0, 0, 1790961816903) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_77ff58795d1d6f9a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Synonyms of Keenness is', '{"A":"Acuity","B":"Likeness","C":"Kindness","D":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Keenness شوق, تمنا, آرزومندی zestzealardourAcuity ( تیزی سے دیکھنے کی قوت )', 0, 0, 0, 1790961816903) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2533bbf41bce8e84', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He is waiting __________ meet you since morning.', '{"A":"for","B":"to","C":"up to","D":"for to"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He is waiting to meet you since morning.ٹو لگے گا کیونکہ وہ کسی سے ملنے جا رہا ہےاور اس کا انتطار کر رہااس ٹاپک کے متعلق انتہائی اہم سوالات پڑھیں Completion Sentence', 0, 0, 0, 1790961816903) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6380e22efd71ca48', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '____ you ever been to Amsterdam?', '{"A":"Do","B":"Does","C":"Have","D":"none"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Have you ever been to Amsterdam? کیا آپ کبھی ایمسٹرڈیم گئے ہیں؟****The Above sentence is going to present perfect tensehave/has + past participle. you------> nounEver'' and ''never'' are always placed before the main verb (past participle). Ever is used: In questions ****Option C is correct "as ever been "indicates the use of the present perfect tense. Also, have is used as an auxiliary here.An auxiliary verb is used to form tenses, moods, tones, etc.***The other options are wrong as no other tense other than the present perfect tense can be used.', 0, 0, 0, 1790961816903) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c17a7ad2a4ac7ad3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I shall look _______ the matter.', '{"A":"In","B":"Onto","C":"Into","D":"With","E":"From"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I shall look Into the matter.***The above sentence belongs to a future sentence.I (subject) + will/shall + look (first form of verb) + into the matter (rest of the sentence)SHALL is —used to express what is inevitable or seems likely to happen in the futureLook into the matter means معاملے کو حل کرنا یا جانچ پڑتال کرناSH6-9-2023', 0, 0, 0, 1790961816903) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6a2f77cbaabaedf0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The air was clear and fresh _____________ all the traffic.', '{"A":"Although","B":"Even though","C":"In spite of","D":"Because of"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In spite of means کے باوجود', 0, 0, 0, 1790961816903) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3eb58110e54f2faa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The manager could not accept the union leader''s proposals.', '{"A":"The union leader''s proposals could not be accepted by the manager","B":"The union leader''s proposals were not accepted by the manager","C":"The union leader''s proposals will not be accepted by the manager","D":"The union leader''s proposals would not be accepted by the manager","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The given sentence contains one of Model verb (Model Verb = will, shall, can, may, might, could, might, must, would). It is in active voice and a negative sentence.Rule : Subject + Model verb +not + be + V3 + Optional Objects', 0, 0, 0, 1790961816904) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dc488df6e826de61', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The president could not accept the union leader''s proposals.', '{"A":"The union leader''s proposals could not be accepted by the president","B":"The union leader''s proposals were not accepted by the president","C":"The union leader''s proposals will not be accepted by the president","D":"The union leader''s proposals would not be accepted by the president","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The given sentence contains one of Model verb. It is in active voice and a negative sentence. Rule : Subject + Model verb +not + be + V3 + Optional Objects.', 0, 0, 0, 1790961816984) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9cd4d3a7a08f4ecf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She is suffering ______ a bad throat infection.', '{"A":"from","B":"in","C":"on","D":"it"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We generally use from with diseases.From is a preposition here. She is suffering from a bad throat infection.', 0, 0, 0, 1790961816984) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c768e41f56795c60', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Sana is popular _____ her friend.', '{"A":"Among","B":"by","C":"Over","D":"With"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sana is popular with her friends.- Popular with someone = liked or admired by a group of people. - He is popular with students. - The show is popular with young viewers.', 0, 0, 0, 1790961816984) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_da6ee4017d1ff982', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I will see you _________ Eid-Ul-Azha.', '{"A":"Within","B":"By","C":"since","D":"from","E":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I will see you by Eid-Ul-Azha means میں آپ سے عید الاضحی تک ملوں گا۔', 0, 0, 0, 1790961816984) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4c8c0b7c5c90eee6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The people clamoring _______ lower prices of essential goods', '{"A":"in","B":"to","C":"for","D":"with"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation For (to indicate the reason or because of) — I am really happy for you. For (to indicate the duration or time) — I attended the session for one year only. For (specify the use of something) — She is preparing for her final exam.', 0, 0, 0, 1790961816984) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3d7c0164e675725d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'You ___ maintain a healthy life, if you keep exercising.', '{"A":"Can","B":"Was kept","C":"Keep","D":"Were kept"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation You can maintain a healthy life, if you keep exercising.', 0, 0, 0, 1790961816984) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ba59f236821bc6dd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Professor : Lecture : : Doctor : ?', '{"A":"Hospital.","B":"Disease.","C":"Medicine.","D":"Patient."}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Professor: Lecture: : Doctor: Medicine. ***Professor delivers lectures to his students.Similarly, a doctor gives medicine to his patients.', 0, 0, 0, 1790961816984) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_331adade594b5ca1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I had worn blue shoes.', '{"A":"Blue shoes had been wear by me.","B":"Blue shoes was worn by me.","C":"Blue shoes had been worn by me.","D":"Blue shoes are worn by me."}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This sentence belongs to Past Perfect TenseActive Voice Formula: Subject + had + V3+ object.Passive Voice Formula: Object + had+ been + V3 + (By + subject)', 0, 0, 0, 1790961816984) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_157e1977eff4f096', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '__________ the wife ________ the husband were not on good terms.', '{"A":"Both/and","B":"either/and","C":"nobody/and","D":"anybody/and"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Both is a pronoun, both is also an adjective.Both is used in positive sentences.Generally And is used after Both.Both is not used in negative sentences.', 0, 0, 0, 1790961817066) ON CONFLICT(id) DO NOTHING;
