INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bea13a96ba0c543d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The word “illicit” means what?', '{"A":"Illegible","B":"ill-tempered","C":"iIl-advised","D":"illegal"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The word “illicit” means جو جائز نہ ہو ناجائز ہو', 0, 0, 0, 1790961817066) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3dce67d4ddcbb241', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Are you going to the bank? No, I have already ---------- there.', '{"A":"Been","B":"Gone","C":"has Gone","D":"Had gone"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Are you going to the bank? No, I have already gone there....“Gone” is the past participle of “go,”“Gone” is used to form the past perfect (pluperfect) verb tense.', 0, 0, 0, 1790961817066) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_58e26dc65c60ab7c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I am doing sums.', '{"A":"Sums are done by me","B":"Sums were being done by me","C":"Sums are being done by me","D":"Sums should be done by me","E":"All Of The Above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Present Continuous TenseActive Voice: Subject + is/am/are + First of verb + ing + obect. Passive Voice: Object + is being/am being/ are being + third form of verb + by + subject. Active Voice: I am doing sums.Passive Voice: Sums are being done by me.Do is a regular verb which means کرناDo means perform.Did is the second form while done is the third form of Do.', 0, 0, 0, 1790961817066) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2379224a4ba9271f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Does he dare _______ them.', '{"A":"Scolds","B":"scolded","C":"to scold","D":"is scolding"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Both dare and scold are verbs. Therefore, the preposition to should be used between them.', 0, 0, 0, 1790961817066) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6a5b23e6b96f0e40', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The term "Oasis" is associated with?', '{"A":"Galleries","B":"Deserts","C":"Island","D":"Forest"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The term "Oasis" is associated with Deserts**An oasis is a small patch of vegetation surrounded by desert.', 0, 0, 0, 1790961817066) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_90ce6f4aa29d9dfd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He is taller than_____.', '{"A":"I","B":"me","C":"is","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He is taller than me. The above sentence is grammatically correct, because in this sentence ''than'' is used as a preposition.', 0, 0, 0, 1790961817066) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_050f4c0f27a19546', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She has been waiting for me ______ the road.', '{"A":"Across","B":"Through","C":"Via","D":"Into","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Across has two different meanings.1.On the opposite sideFor Example: She has been waiting for me across the road.2. Both sides For Example: A tree fell across the railway line that caused an accident', 0, 0, 0, 1790961817154) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5db4b250b3cfe417', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Prepare yourself for the worst.', '{"A":"You be prepared for the worst","B":"The worst should be prepared by yourself.","C":"For the worst, preparation should be made by you.","D":"Be prepared for the worst.","E":"All of the above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Be prepared for the worst is the correct option here.More details about this question will be uploaded soon.', 0, 0, 0, 1790961817154) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cfbe730917d633d3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Mr. Aslam is senior _____________ and older than Mr. Sajad.', '{"A":"To","B":"Too","C":"With","D":"Of","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Note:- If two verbs/adjectives etc take two different prepositions, we must use appropriate prepositions along with the verb/adjective. Mr. Aslam is senior to and older than Mr. Sajad.', 0, 0, 0, 1790961817154) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7e95f5d2dbcce6f8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She always speaks _____ truth.', '{"A":"A","B":"An","C":"The","D":"No Article required"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Generally the is used before truth.She always speaks the truth means وہ ہمیشہ سچ بولتی ہے', 0, 0, 0, 1790961817154) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6edd0073d6bb6aa1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'If I ____________ this record, I would give you a big treat.', '{"A":"Break","B":"Breaks","C":"Broken","D":"Broke","E":"Breaking"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation If I broke this record, I would give you a big treat.This sentence belongs to conditional sentence.', 0, 0, 0, 1790961817154) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ad9cf6bd0835203a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Essay Topics: Write only One Essay (LAT Paper held in July-2019)', '{"A":"Life of Prophet Muhammad ﷺ During the preaching of Islam","B":"World is becoming global village","C":"Advantages and disadvantages of Social Media","D":"Write only One Essay"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Essay Topics: Write only One Essay (Paper held in July-2019)Life of Prophet Muhammad ﷺ During the preaching of IslamWorld is becoming global villageAdvantages and disadvantages of Social Media', 0, 0, 0, 1790961817154) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_675c355ce070f4f2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Islamabad has _____ ideal climate.', '{"A":"A","B":"An","C":"The","D":"No article"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Islamabad has an ideal climate. Because ideal gives vowel sound.', 0, 0, 0, 1790961817154) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f7bddf0558b2bc40', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'There is no need to ______________ the fact that we lost by three goals.', '{"A":"Rub in","B":"rub out","C":"rub with","D":"rub into"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Rub In is phrasal verb which means افسوس کرنا یا پچھتانا', 0, 0, 0, 1790961817154) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_23a4a8b05bfbb025', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '____ Shazia wants to meet you.', '{"A":"A","B":"An","C":"The","D":"No article required"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A Shazia wants to meet you means کوئی شازیہ آپ سے ملنا چاہتی ہےArticle A and An are used for unknown persons.', 0, 0, 0, 1790961817229) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_623683e431279843', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'How is that you did not ___ us even about your address and phone number?', '{"A":"Telling","B":"Tell","C":"Tells","D":"Told"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation First form of verb is used with did.', 0, 0, 0, 1790961817229) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8c5ea6aba5dbc35a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '_________ your phone while driving.', '{"A":"Turn around","B":"turn off","C":"turn","D":"turning","E":"none of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Turn off is a phrasal verb which means بند کرنا', 0, 0, 0, 1790961817229) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5bf5bc3a560517da', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I am sorry this property is not available any longer ,it ---- to a businessman.', '{"A":"Was being sold","B":"is sold","C":"will be sold","D":"has been sold"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation It has been sold to a businessman means اس (مکان) کو کسی بزنس مین کو فروخت کیا جا چکا ہے', 0, 0, 0, 1790961817229) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1959b6e7527935fa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '______ Urdu is a sweet language of Pakistan.', '{"A":"A","B":"An","C":"The","D":"None of the above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Usually no article required before languages.Urdu is a sweet language of Pakistan.', 0, 0, 0, 1790961817229) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4cfc4c27b8b31d93', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Before festivals the shops are thronged with men, women and children making various purchase.', '{"A":"Men, women and children throng the shops before festival making various purchases","B":"The shops are thronged by people making purchases","C":"During festival people throng the shops","D":"Men, women and children make purchases during festivals","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Given sentence is in Passive voice and in Present Simple Tense. We need to change it into active voice. While changing the voice objects becomes subject and subject changes into object.Rule : Subject + V1 + Other agents.', 0, 0, 0, 1790961817229) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7269eb27df3f7de0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Rizwan will ______ Ayan for his misconduct.', '{"A":"Deal in","B":"Deal on","C":"Deal by","D":"Deal with","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Rizwan will deal with Ayan for his misconduct.رضوان آیان کے ساتھ اس کی بدتمیزی کا معاملہ کرے گا۔Deal With means: to do something about (a person or thing that causes a problem or difficult situation) ND16-8-2023', 0, 0, 0, 1790961817229) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ebe1f43e0317b70c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'We must take care of all living species on earth.', '{"A":"All living species on earth must be taken care of by us","B":"All living species on earth must taken care of by us","C":"All living species on Earth had been taken care of by us","D":"All living species on earth will be taken care of by us","E":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The given sentence contains one of Model verb (Model Verb = will, shall, can, may, might, could, might, must, would). It is in active voice. Rule : Subject + Model verb + be + V3 + Optional Objects.', 0, 0, 0, 1790961817229) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_30c15a432cc192e0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He took me to hospital and the doctors operated me.', '{"A":"I was taken to hospital by her and operated by the doctors","B":"I am taken to hospital by her and operated by the doctors","C":"I should be taken to hospital by her and operated by the doctors","D":"I was being taken to hospital by her and operated by the doctors","E":"I was taken to hospital by him and operated by the doctors"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Note:- While covering active into passive both parts should be made into passive.Active Voice (Part 1): He took me to hospital.Correct Passive Voice: I was taken to hospital by him.Active Voice (Part 2): And the doctors operated me.Correct Passive Voice: And operated by the doctors.Present Indefinite TenseActive Voice: Subject + Verb + Object Passive Voice: Object + is/am/are+ third form of a verb + by + subject.', 0, 0, 0, 1790961817290) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c2cbd4760e2762df', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Susan is the woman ____ husband is in hospital', '{"A":"her","B":"hers the","C":"whose","D":"none"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Whose is a possessive pronoun. Use it when you''re asking (or telling) to whom something belongsSH16-8-2023', 0, 0, 0, 1790961817290) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_83adf2819f7b9698', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The film was criticized for its gratuitous violence. Here “Gratuitous” means:', '{"A":"Unasked for","B":"Harsh","C":"Ugly","D":"None of these","E":"All of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Gratuitous means unnecessary. (جس کی ضرورت نہ ہو)', 0, 0, 0, 1790961817290) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cdc21222d12ea55c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Will you walk ______ my parlour?', '{"A":"In","B":"Into","C":"Of","D":"Off"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Here into means expressing movement or action with the result that someone or something makes physical contact with something else.', 0, 0, 0, 1790961817290) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bd49506075883d84', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It isn''t in the least cold, and _____ moon is just coming up over the sea.', '{"A":"A","B":"An","C":"The","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Usually Article the is used before unique things like Sun, Earth, Moon etc.', 0, 0, 0, 1790961817290) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d11bf657dee06f2c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I thought _____ moon was shining.', '{"A":"A","B":"An","C":"The","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Usually Article the is used before unique things like Sun, Earth, Moon etc.', 0, 0, 0, 1790961817290) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_73448271fe7872ac', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Don’t eat an apple __________ three days.', '{"A":"From","B":"Since","C":"For","D":"Until"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Usually the preposition for is used before days, months, years etc.For example: for three days, for two months, for six years', 0, 0, 0, 1790961817290) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3e4a62d2636c61c9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '_______ dolphin is a very intelligent animal.', '{"A":"A","B":"The","C":"An","D":"No article"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The dolphin is a very intelligent animal.Article ''the'' is used before particular animals.', 0, 0, 0, 1790961817290) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a5c6fd3e8f5cfb91', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '____ higher you go, ___ cooler you feel.', '{"A":"A/A","B":"A/The","C":"An/An","D":"The/The"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The higher you go, the more difficult it becomes to breathe.The higher you go, the cooler you feel.Article ''the'' should be used here.', 0, 0, 0, 1790961817378) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fe7f91280475d630', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The income tax raid was too sudden _____', '{"A":"So that the man escaped","B":"For the man escaping","C":"Then the man escaped","D":"For the man to escape"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The income tax raid was too sudden for the man to escape.“Too” is used in positive sentences, to show agreementLast updated 15-feb-2026', 0, 0, 0, 1790961817378) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_42859cadfeb8a69f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I saw ____ elephant yesterday.', '{"A":"A","B":"An","C":"Both A and B","D":"No Article"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I saw an elephant yesterday.Article ''An'' is used before elephant.', 0, 0, 0, 1790961817378) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2a0651c2969133a8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '______ Pakistani team will arrive England tomorrow.', '{"A":"A","B":"An","C":"The","D":"No article required"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Usually Article the is used for Nationalty.Like, The Chinese, The Japanese, The Indian', 0, 0, 0, 1790961817378) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_da5f5e7bc2368a79', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Who has deceived you?', '{"A":"By whom had you been deceived?","B":"By whom have you been deceived?","C":"By whom were you been deceived?","D":"By whom should you been deceived?","E":"By can you you been deceived?"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice: WhoPassive Voice: By whomThis is a sentence of Present Perfect Tense.Have been and Has been are the helping verbs of Present Perfect Tense', 0, 0, 0, 1790961817378) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d724b6436b40c11e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'If the camera was working, we __________ a movie.', '{"A":"could made","B":"could make","C":"would made","D":"would make"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Modal verbs like can, could,shall, should are generally followed by first form of a verb (make)If the camera was working, we could make a movie.', 0, 0, 0, 1790961817378) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_43843111d2cec752', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Who knows you?', '{"A":"To whom you are known?","B":"To whom are you known?","C":"To whom were you known","D":"To whom are you being known?","E":"All Of The Above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Interrogative sentencesActive Voice = ToPassive Voice = To whomKnow is an irregular verb which means جانناKnew is the second form while known is the third form of know.', 0, 0, 0, 1790961817378) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9e0c16adf5d6a37c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She knows me.', '{"A":"I am known to her","B":"I am known to him","C":"I am knew to her","D":"All of the above","E":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation She knows me means وہ مجھے جانتی ہےKnow is a verb.Knew is the second form while known is the third form of Know.Past Indefinite tenseActive Voice= Subject + Second Form of Verb + Object. Passive Voice = Object + was/were + third of verb + by + subject.', 0, 0, 0, 1790961817378) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cd4565ee48a7fe91', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'At least you are original I have never heard "that kind of an excuse" until now.', '{"A":"That kind of excuse","B":"These kinds of excuses","C":"That sort of an excuse","D":"That kind of an excuse","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation At least you are original I have never heard "that kind of an excuse" until now.eliminates an error in the sentenceAt least you are original I have never heard "These kinds of excuses" until now.کم از کم آپ اصلی ہیں میں نے آج تک "اس قسم کے بہانے" کبھی نہیں سنے ہیں۔ND16-8-2023', 0, 0, 0, 1790961817471) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e301311ff83c6f82', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Who believes others easily and can be cheated', '{"A":"Incredible","B":"Native","C":"Fraud","D":"Gullible"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Gullible means one believes others easily and can be cheated.Gullible means بھولا · سادہ دل · سادہ مزاج · سیدھا سادہ', 0, 0, 0, 1790961817471) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7be59fb5f63cffff', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Choose the one which best expresses the meaning of the given word. TEDIOUS', '{"A":"Painful","B":"Lengthy","C":"Tiresome","D":"Troublesome"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation TEDIOUS: تھکا دینے والاTiresome: تھکا دینے والا', 0, 0, 0, 1790961817471) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_15568d6127eb2cb2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Choose the word nearest in meaning to ERRAND', '{"A":"Foolishness","B":"Mission","C":"Misadventure","D":"Error"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Foolishness: lack of good sense or judgment; stupidity.Mission: an important assignment given to a person or group of people, typically involving travel abroad.', 0, 0, 0, 1790961817471) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_97565478f3ce1e20', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Do not smoke here.', '{"A":"You are advised not to smoke here","B":"You are advised not to smoke there","C":"You were advised not to smoke here","D":"You should be advised not to smoke here","E":"all of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Order: Let + object + be + third form of a verbSuggestion: Object + should be + third form of a verbRequest: You are requested/advised to + first form of a verb + object. Note: Please and kindly are not used in passive voice.', 0, 0, 0, 1790961817471) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6f2ed03c0e5e3d49', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The fight started when one of the drivers made a rude _______ at someone.', '{"A":"Posture","B":"Stance","C":"Gesture","D":"Look","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The fight started when one of the drivers made a rude gesture at someone.لڑائی اس وقت شروع ہوئی جب ایک ڈرائیور نے کسی کی طرف بدتمیزی کی۔***Rude Gesture means بیہودہ اشارہND06-08-2023', 0, 0, 0, 1790961817471) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_95ded51154ee7d30', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She is looking for a job.', '{"A":"A job is being looked for by her","B":"A job is looked for by her","C":"A job was being looked for by her","D":"A job will be being looked for by her","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A job being looked for by her is the correct passive.Looked is the second and third form of Look.Present Continuous TenseActive Voice: Subject + is/am/are + First of verb + ing + object. Passive Voice: Object + is being/am being/ are being + third form of verb + by + subject.ND06-08-2023', 0, 0, 0, 1790961817471) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1229d1f5c468bcba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They said to us, "Are you leaving tomorrow."?', '{"A":"They asked us if we are leaving tomorrow","B":"They asked us if we were leaving tomorrow","C":"They asked us if we were to leave tomorrow","D":"They asked us if we were leaving the next day","E":"all are wrong"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation incorrect: They said to us, "Are you leaving tomorrow."?correct: They asked us if we were leaving the next dayRules:Said changes to asked.Remove inverted commas. Make it simple from interrogative.Add if.Tomorrow changes to the next day. ND2-08-2023', 0, 0, 0, 1790961817471) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e82bb41024306055', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Who is creating this mess?', '{"A":"Who has been created this mess?","B":"By whom has this mess been created?","C":"By whom this mess is being created?","D":"By whom is this mess being created?","E":"All of the above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice: Who is creating this mess?Passive Voice: By whom is this mess being created?Use structure “By + question word + subject + auxiliary + past participle”ND12_8_2023', 0, 0, 0, 1790961817543) ON CONFLICT(id) DO NOTHING;
