INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_516e02e5aa3245ea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I am overcome _____ hunger.', '{"A":"Of","B":"In","C":"About","D":"By"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hunger means بھوک This is a sentence of passive voice.Therefore, "By" should be used.', 0, 0, 0, 1790961817759) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_27e838278c47c83f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'If Melt is to Liquid then Freeze is to:', '{"A":"Solid","B":"Ice","C":"Crystal","D":"Condense","E":"All of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When anything freezes it forms solid', 0, 0, 0, 1790961817759) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7f2dd27224b1eb12', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Sometimes, absolute silence is the most satisfying sound. Here ''Absolute'' means:', '{"A":"Mute","B":"Silent","C":"Utter","D":"Valuable","E":"All of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Utter means complete.', 0, 0, 0, 1790961817759) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_03119d56923f7245', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I have been teaching English _____________ June.', '{"A":"For","B":"From","C":"Since","D":"Till","E":"All of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation For is used for period.Since is used for point of time.', 0, 0, 0, 1790961817759) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_16c97d089aa2da54', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Choose the one which best expresses the meaning of the italicized part of the sentence. Seeds need sufficient water and air to germinate.', '{"A":"Purposiveness","B":"Management","C":"Sprout","D":"Reproduce"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sprout : (of a plant) put out shoots.Germinate : (of a seed or spore) start to develop and put out shoots after a period of dormancy. Synonym of Germinate is Sprout', 0, 0, 0, 1790961817759) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9b5b2b4bd8b944d2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I have no hatred ____ him.', '{"A":"For","B":"In","C":"With","D":"To"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hatred is generally followed by for.Hatred means عداوت', 0, 0, 0, 1790961817759) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9f6eafcbbaa2d826', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'When a computer starts, ___________ checks all the ___________and loads their drivers so a user can work properly.', '{"A":"File Manager","B":"Operating System","C":"Application Software","D":"Hard Disk","E":"All of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Operating System: system software that manages computer hardware & software resources.', 0, 0, 0, 1790961817759) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3282c849c2acda19', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '_____ earth rotates on its axis.', '{"A":"A","B":"An","C":"The","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Usually Article the is used before unique things like Sun, Earth, Moon etc.', 0, 0, 0, 1790961817759) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_913ca7811d9bdfd5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The books were __________ the table.', '{"A":"On","B":"Onto","C":"In","D":"Into","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation On and Upon On = (Placed in contact)Upon = (In Motion) The books were on the table The dog jumped upon the cat.', 0, 0, 0, 1790961817839) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d127ff574f1ba8df', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I never miss a football match.I ____ fond of it since my childhood.', '{"A":"Will be","B":"Has been","C":"Have been","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "have been" is used for first- and second-person singular and all plural uses. The present perfect tense refers to an action that began at some time in the past and is still in progress', 0, 0, 0, 1790961817839) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0143aa1c0fb45d63', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'You are sitting _______ us and talking against us.', '{"A":"Amidst","B":"Among","C":"Between","D":"From","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Amid/Amidst is used for more than two.These prepositions are used before uncountable nouns too. You are sitting amidst us and talking against us.', 0, 0, 0, 1790961817839) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2554a346a364b5b4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'This book contains maps.', '{"A":"Maps will be contained in this book","B":"Maps were contained in this book","C":"Maps contained be contained in this book","D":"Maps will be contained in this book","E":"Maps are contained in this book"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Maps are contained in this book is the correct passive.Contain is a regular verb.Contained is the second and third form of contain.Present Indefinite TenseActive Voice: Subject + Verb + ObjectPassive Voice: Object + is/am/are+ third form of a verb + by + subject.', 0, 0, 0, 1790961817839) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_86b7842e4559ce13', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'You should not discuss about the matter with friends who are likely to find it offensive. Choose the error in the above sentence (if any)', '{"A":"You should not discuss","B":"about the matter","C":"with friends likely","D":"no error"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Generally, the word about is not used after discuss.', 0, 0, 0, 1790961817839) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0fcb563ad00f93bb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I visit Faisal Mosque _______ I go to Islamabad.', '{"A":"Wherever","B":"Whenever","C":"Where","D":"Once"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I visit Faisal Mosque whenever I go to Islamabad. جب بھی میں اسلام آباد جاتاہوں تو فیصل مسجد بھی جاتاہوں۔', 0, 0, 0, 1790961817839) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_985f61adb87a8fc3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'A man''s best friend is his _______.', '{"A":"Dog","B":"Shirt","C":"Money","D":"House"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A man''s best friend is his Dog."Man''s best friend" is a common phraseIt refers to animals that are of use to human beings, mostly used to address dogs.', 0, 0, 0, 1790961817839) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_662c007b1c5dc638', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Successful people are genuinely very efficient in ____________ their tasks.', '{"A":"Making","B":"Attaining","C":"Achieving","D":"Accomplishing","E":"Completing"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Accomplish is a verb which means کامیابی سے مکمل کرنا', 0, 0, 0, 1790961817839) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5c918ec81e86af50', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Did he remember the date and time?', '{"A":"Are the date and time remembered by him?","B":"Was he remembering the date and time?","C":"Were the date and time remembered by him?","D":"Did the date and time be remembered by him?","E":"All of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This is an interrogative sentence of Past Indefinite Tense.Active: Did + Subject + verb (Ist form) + object...Passive: Was/Were + Object + verb (3rd form) + by + subject...', 0, 0, 0, 1790961817923) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3edc3f558d87f726', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They have made a drama based on this novel.', '{"A":"A drama has been made based on this novel by them","B":"A drama was been made based on this novel by them","C":"A drama will be made based on this novel by them","D":"A drama has been made based on this novel by us","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This is a sentence of Present Perfect Tense.Active sentences in the present perfect tense have the following structure: Subject + has/have + past participle form of the verb + object Passive sentences in the present perfect tense have the following structure: Object of the active sentence + has/have + been + past participle form of the verb + by + subject of the active sentence', 0, 0, 0, 1790961817923) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e3cf6f8173ce08d2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I have never felt so embarrassed in my life. In the above sentence, the word "never" is:', '{"A":"Adverb of frequency","B":"Adverb of degree","C":"Adjective","D":"none"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Words like always, usually, often, sometimes, rarely, and never are called Adverb of Frequency.', 0, 0, 0, 1790961817923) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_618ed0827ade5fd6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Who taught Political Science to you?', '{"A":"By whom was Political Science taught to you?","B":"By whom is Political Science taught to you?","C":"By whom will Political Science taught to you?","D":"By whom should Political Science be taught to you?","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice: Who + second form of a verb + clausePassive Voice: By whom + was/were + object + third form of a verb + clause', 0, 0, 0, 1790961817923) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_254bba928681b9e9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Who taught you Urdu?', '{"A":"By who were you taught Urdu","B":"By which were you taught Urdu","C":"By whom you were taught Urdu?","D":"By whom were you taught Urdu?","E":"All of the above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice: Who + second form of a verb + clause Passive Voice: By whom + was/were + object + third form of a verb + clause', 0, 0, 0, 1790961817923) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3f4904b5b3985718', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '____ honestly shown by Sarfraz Ahmed during the match was praised by all.', '{"A":"A","B":"An","C":"The","D":"No article"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Generally Abstract Noun takes article the.', 0, 0, 0, 1790961817923) ON CONFLICT(id) DO NOTHING;
