INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3b8ada97273d3f3b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Everyone must read this book.', '{"A":"This book should be read by everyone","B":"This book has to be red by everyone","C":"This book is to be read by everyone","D":"This book must be read by everyone","E":"All of the above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The given sentence contains one of Model verb. Formula: Subject + Model verb + be + V3 + Optional Objects.', 0, 0, 0, 1790961817999) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_930dabdd29293bb7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The lawyers of Pakistan have always struggled ------- justice and rule of law.', '{"A":"for","B":"with","C":"of","D":"none"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The answer should have been "for" .', 0, 0, 0, 1790961817999) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_58f15d8f6b4d8f9a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He gave me a gift.', '{"A":"I was given a gift by him","B":"I am given a gift by him","C":"I should be given a gift by him","D":"I will be given a gift by him","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Past Indefinite tenseActive Voice= Subject + Second Form of Verb + Object. Passive Voice = Object + was/were + third of verb + by + subject.', 0, 0, 0, 1790961817999) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_af8dcef120262419', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Select the pair of words which is odd from the following', '{"A":"Wrong and Right","B":"Canal and River","C":"Long and short","D":"Senior and Junior"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation That pair of words should be writing this way otherwise wrong.Right and wrong Canal and River Junior and senior', 0, 0, 0, 1790961817999) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b15c53c6c2725ef2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Friend is to enemy as love is to _____', '{"A":"Friendship","B":"Jealousy","C":"Mistrust","D":"Hatred"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Love : Friend : : Hate : Enemy کیونکہ محبت دوست سے ہوتی اسی طری نفرت دشمن سے', 0, 0, 0, 1790961817999) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f1051cdfd890f3b1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Will she tell us the truth?', '{"A":"Is the truth told to us by her?","B":"The truth will be told to us by her","C":"Will the truth be told to us by her","D":"Will the truth be told us by her?","E":"All of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Question word (will) + subject (she) + verb (tell) + indirect object (us) + direct object (the truth)'' will change to''Question word (will) + new subject (the truth) + verb (be told) + to + indirect object (us) + by + new object (her)''', 0, 0, 0, 1790961817999) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_922b405eed2becc4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'If you don''t care for the blemishes of his style, you will find that the writer has a powerful message to convey', '{"A":"excellences","B":"qualities","C":"accusations","D":"faults"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation blemishes: داغfaults: غلطی', 0, 0, 0, 1790961817999) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5a753c20ddaaea93', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Your present statement has allayed my fears.', '{"A":"relieved","B":"obliterated","C":"aroused","D":"eradicated"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation allayed: ختمrelieved: سکون', 0, 0, 0, 1790961818072) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_831553d11dd0e135', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He does not know how to hatband his resources', '{"A":"manage","B":"govern","C":"rule","D":"watch"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation manage: انتظام', 0, 0, 0, 1790961818072) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_31103e6319b5ca20', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He gave an expeditious reply', '{"A":"exact","B":"slow","C":"elaborate","D":"prompt"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation expeditious: تیز رفتارprompt: فوری طور پر', 0, 0, 0, 1790961818072) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c96344baa4443a3d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'His style is quite transparent', '{"A":"witty","B":"lucid","C":"involved","D":"verbose"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation transparent: شفافlucid: اجاگر', 0, 0, 0, 1790961818072) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3f965076b32bd0c5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The Border Securty Force intercepted yesterday a thick carrying arms And ammunition', '{"A":"found","B":"stopped","C":"met","D":"interrupted"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation intercepted: روکاstopped: روک دیا', 0, 0, 0, 1790961818072) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e3f2378369dd8a74', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Brevity pays in debate', '{"A":"Conciseness","B":"Sharpness","C":"Quickness","D":"Confidence"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Conciseness : جامعیتBrevity : concise and actual use of phrases in writing or speech.', 0, 0, 0, 1790961818072) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1b08025eb46212c3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She has and will read a novel.', '{"A":"A novel has been and will be read by her","B":"A novel been and will be read by her","C":"A novel is been and will be read by her","D":"A novel should be  been and will be read by her","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active sentences in the present perfect tense have the following structure: Subject + has/have + past participle form of the verb + object Passive sentences in the present perfect tense have the following structure: Object of the active sentence + has/have + been + past participle form of the verb + by + subject of the active sentence The sentence is in Simple Past Tense.', 0, 0, 0, 1790961818072) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d1e6d91006fd7ef8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Change Voice of the following: She takes tea.', '{"A":"She is drunken tea.","B":"She is taken by tea.","C":"Tea is being taken by her.","D":"Tea is taken by her."}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation She takes tea.Tea is taken by her.', 0, 0, 0, 1790961818072) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4f76fe38557382cb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'One of them will help the poor.', '{"A":"The poor will be helped by one of them","B":"The poor is be helped by one of them","C":"The poor was be helped by one of them","D":"The poor should be helped by one of them","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The given sentence is in Future Indefinite Tense.Future Indefinite Tense-Passive Voice Convert the object of the Active Voice Sentence into the subject of the Passive Voice sentence.Then use helping verb will be/shall be according to the subject of the Passive Voice Sentence.Then use the 3rd form of Verb. After that, use the word “by”, in order to show the doer.', 0, 0, 0, 1790961818158) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1bde16433bc8650d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'One of my friends ____________ coming today.', '{"A":"Is","B":"are","C":"were","D":"did"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation One of my friends is coming today means میرے دوستوں میں سے ایک آج آرہا ہے', 0, 0, 0, 1790961818158) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fcc2c7abf715e2e7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'One cannot gather grapes from thistles.', '{"A":"Thistles cannot be gathered from grapes","B":"Grapes cannot be gathered from thistles","C":"Thistles cannot be gathered by one","D":"Grapes cannot be gathered by them","E":"All of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In both form of sentence meaning is same only structures of words are changed. In active sentence subject is ‘’Grapes’’ object is ‘’thistles’’ and verb is ‘’gather’’. When we change into passive voice object ‘’thistles’’ will become subject and subject ‘’grapes’’ will become object. In passive form after ‘’cannot’’ ‘’be’’ will be used and verb will be written in past participle.', 0, 0, 0, 1790961818158) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b137b2af330b38a7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Oh my God that is stunning! It is a _____________ sentence.', '{"A":"Compound","B":"Declarative","C":"Exclamatory","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An exclamatory sentence makes a statement that conveys strong emotion or excitement.', 0, 0, 0, 1790961818158) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b9b981de7f373921', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'My friends were playing cricket.', '{"A":"Cricket is being played by my friends","B":"Cricket will be played by my friends","C":"Cricket should be played by my friends","D":"Cricket was being played by my friends","E":"All of the above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation My friends were playing cricket is a sentence of Present Continuous Tense.My friends were playing cricket means میرے دوست کرکٹ کھیل رئے تھےPresent Continuous TenseActive Voice: Subject + is/am/are + First of verb + ing + object. Passive Voice: Object + is being/am being/ are being + third form of verb + by + subject.', 0, 0, 0, 1790961818158) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_01357c7c088d92e9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'My pen is similar --- your pen', '{"A":"too","B":"to","C":"in","D":"of"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Use the preposition ''to'' when indicating that there is movement from one place to another.', 0, 0, 0, 1790961818158) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8288eb18ecf6b388', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'My watch can’t be repaired by anyone,', '{"A":"No one will repair my watch","B":"No one can repair my watch","C":"No one can’t repair my watch","D":"No one will be able to repair my watch","E":"All of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sentence is in Simple Present Tense. Present Indefinite TenseActive Voice: Subject + Verb + Object Passive Voice: Object + is/am/are+ third form of a verb + by + subject.', 0, 0, 0, 1790961818158) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_47770b6a46e79cc1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'My brother helps the honest.', '{"A":"The honest are helped by my brother","B":"The honest were helped by my brother","C":"The honest should be helped by my brother","D":"The honest will be helped by my brother","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Present Indefinite TenseActive Voice: Subject + Verb + Object Passive Voice: Object + is/am/are+ third form of a verb + by + subject.', 0, 0, 0, 1790961818158) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9d9df69cca9c1a9e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Mr Razzak is worth ___ honor.', '{"A":"of","B":"in","C":"out","D":"at"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We use of when we want to show that people or things relate to other things or people.', 0, 0, 0, 1790961818240) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_90ae0cca981abf07', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Mr. Tanveer ____ is a teacher lives in the street next to mine.', '{"A":"Who","B":"Whome","C":"Which","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Who should be used to refer to the subject of a sentence. Whom should be used to refer to the object of a verb or preposition.', 0, 0, 0, 1790961818240) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c74ac0accffa680f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Mr Ajmal was going to continue ____, but he lost his job.', '{"A":"work","B":"working","C":"worked","D":"to work"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790961818240) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_803236aa11cd13fa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Miss Rani manages the marketing division on this company.', '{"A":"The marketing division of this company is managed by Miss Rani","B":"The marketing of this company is managed by Miss Rani","C":"The marketing division of this company has managed by Miss Rani","D":"none"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This is a sentence of Present Indefinite TenseActive Voice Formula: Subject + verb + ObjectPassive Voice Formula: Object+is/am/are+third form of a verb+by+subject', 0, 0, 0, 1790961818240) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_33e2d982f5133ffb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Misappropriation of money', '{"A":"Robbery","B":"Theft","C":"Fraud","D":"Embezzlement","E":"Dismissal"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Embezzlement means خورد برد', 0, 0, 0, 1790961818240) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5d53cb90db1755ad', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '____ iron is a hard metal.', '{"A":"A","B":"An","C":"The","D":"No article"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Generally no article before material noun.', 0, 0, 0, 1790961818240) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_69f1b6c5e90c18fd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Look before you leap', '{"A":"preposition","B":"Adverb","C":"Adjective","D":"Conjunction"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In grammar, a conjunction is a part of speech that connects words, phrases, or clauses that are called the conjuncts of the conjunctions.Before used as Conjunction', 0, 0, 0, 1790961818240) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2ac00ce9a36440be', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Knife : Chopper', '{"A":"Walking : Fitness","B":"Swim : Float","C":"Scissors : Cloth","D":"Quilt : Blanket"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Both knife and chopper are used for the same purpose i.e.cuttingSimilarly both quilts and blankets are used for protection from cold.', 0, 0, 0, 1790961818240) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a66a6f5912d7cc21', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I will wait until Friday. In the above sentence, the word "Until" is a:', '{"A":"Preposition","B":"pronoun","C":"verb","D":"conjunction"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Until is a conjunction and preposition also.Unless is always conjunction.Until is used for telling time.Unless is used for condition.', 0, 0, 0, 1790961818337) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_26974e6443c858a4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It was ____ insight and perseverance of the lady doctor that many women were able to lead normal life.', '{"A":"A","B":"An","C":"The","D":"No article required"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790961818337) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3cd2cc81cb1648de', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It was __________ who came running into the classroom.', '{"A":"Her","B":"Hers","C":"She","D":"Herself","E":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation It was she who came running into the classroom.She is acting as subject in this sentence.', 0, 0, 0, 1790961818337) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_61221c89ad0ab501', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It will take all of your energy and will to be able to walk again. Select the answer choice that identifies the noun in the sentence.', '{"A":"Take","B":"All","C":"Your","D":"Energy"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Energy is a noun, as is will here.Take is a verb. All is an adverb modifying take. “Your” is an adjective modifying energy and will.', 0, 0, 0, 1790961818337) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a13ff14111ec97b5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It would be lunacy to climb this mountain in this weather. In the above sentence the word "Lunacy" is a:', '{"A":"Pronoun","B":"Noun","C":"verb","D":"preposition"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lunacy means بے وقوفیLunacy means stupidity or madness.Antonyms of lunacy: sane or wiseFor example: It would be lunacy to climb this mountain in this weather.اس موسم میں اس پہاڑ پر چڑھنا بے وقوفی ہوگی۔', 0, 0, 0, 1790961818337) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_59b06ca9923c487e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It`s high time she ____ the work.', '{"A":"Does","B":"Did","C":"Do","D":"Doing"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation With expressions such as "It`s time", "It`s high time" and "it`s about time", Simple pas is used.', 0, 0, 0, 1790961818337) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dab6d2b88cfdc2cc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It`s time he __________ to school.', '{"A":"Goes","B":"Went","C":"Gone","D":"Had gone"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation It’s time he went to school.اس کے سکول جانے کا وقت ہے۔After "It’s time", we use the simple past tense to express present or future obligation.', 0, 0, 0, 1790961818337) ON CONFLICT(id) DO NOTHING;
