INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1d97df094e082cf1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It is time to close the shop.', '{"A":"It is time the shop be close.","B":"It is time the shop be closed.","C":"It is time for the shop to be closed.","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Passive voice formula: It is time + for + noun/pronoun + to be + v3.', 0, 0, 0, 1790961818426) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_10fb9c9faa441822', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It is said that in our province education is available only to those ______ can afford it.', '{"A":"Whom","B":"Whose","C":"Who","D":"Which","E":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Who is used for human beings.', 0, 0, 0, 1790961818426) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_966b53bf1185e514', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It is ____ great pity that all pupils in the city cannot have the same chances.', '{"A":"A","B":"An","C":"The","D":"No article required"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Articles "A" and "AN" are used with some expressions.For example:Make a noise, give a warning, have a pain, have a great education etc.', 0, 0, 0, 1790961818426) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8fbaccb0b8b83bad', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I took a rope ____ a snake.', '{"A":"At","B":"In","C":"On","D":"For"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I took a rope for a snake. میں نے رسی کو غلطی سے سانپ سمجھ لیا۔Take for means غلطی سے سمجھ لینا', 0, 0, 0, 1790961818426) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_45154ed783e05c82', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I took pity _____ the beggar.', '{"A":"Over","B":"At","C":"On","D":"To"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pity is generally followed by on.', 0, 0, 0, 1790961818426) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_356cc101794d79dc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It is a pity that the son of _____ billionaire is involved in the bank robbery.', '{"A":"A","B":"An","C":"The","D":"No article required"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Here article A means any.Here A means کسییہ ایک افسوس کی بات ہے کی بینک ڈکیتی میں کسی ارب پتی کا بیٹا بھی ملوث ہے۔', 0, 0, 0, 1790961818506) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4dd6adae9792f4a7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It is based ________ two principles.', '{"A":"On","B":"Upon","C":"With","D":"None of the above","E":"All of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Usage of UponWe use upon for more formal term compared to “on”/ used in phrases and idioms/ to denote them.It is based upon two principles.Once upon a time there was a king.He set the tray upon the table. The cat jumped upon the rat.', 0, 0, 0, 1790961818506) ON CONFLICT(id) DO NOTHING;
