INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d3bef68a6c840a4e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I planted ____ tree ? in my garden last year. ____ tree ? has now grown big.', '{"A":"A/An","B":"A/The","C":"The/The","D":"An/The"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I planted a tree ? in my garden last year. The tree ? has now grown big.Note 1: Use "A" or "An" to talk about a person or thing unknown to your listener.Note 2: Use "The" to talk about a person known to your listener.', 0, 0, 0, 1790961818587) ON CONFLICT(id) DO NOTHING;
