INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_41d1c7d7d307d7ab', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Choose the appropriate pronouns to complete the sentence: When the little boy grabbed the lizard _____ tail broke off in _____ hand.', '{"A":"It’s/his","B":"Its/his","C":"Its/he’s","D":"It’s/one’s"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Its" refers to the possessive form of the pronoun "it." For example, when referring to a pair of shoes, you might say, "That''s not its box." Meanwhile, "it''s" is the contraction for the words "it is" or "it has." For example, "It''s (it is) going to be a fabulous night" or "It''s (it has) been a fabulous night."', 0, 0, 0, 1790961820042) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a37657afb53b29e1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Choose the best option that express the meaning of the word " Obloquy":', '{"A":"Sermon","B":"Opprobrium","C":"Fetid","D":"Obsession"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation بلوغ Obloquy', 0, 0, 0, 1790961820042) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_880429083693bffc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Choose correct Analogy Constellation: Stars:', '{"A":"Earth : Moon","B":"Center : Circle","C":"Rain: Water","D":"Troupe: Actors"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A constellation is made of starsA Troupe is made of Actors', 0, 0, 0, 1790961820042) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_acaa2361ea9b8021', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Can we send this big parcel by air?', '{"A":"Can this big parcel be sent by air?","B":"Can this big parcel sent by air?","C":"Could this big parcel be sent by air?","D":"Could this big parcel sent by us by air?","E":"Can this big parcel be send by air?"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Send is a verb which means بھیجناSent is the second and third from of Send.Can this big parcel be sent by air? (Passive) The sentence is in Simple Present Tense. (Active) Modal (can) has been used.', 0, 0, 0, 1790961820042) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_809bf24e28202366', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Can he see his wife again? No he ___', '{"A":"can not","B":"Could not","C":"can","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Can" is one of the most commonly used modal verbs in English. It can be used to express ability or opportunity, to request or offer permission, and to show possibility or impossibility', 0, 0, 0, 1790961820042) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dde871f8f2a49cb2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Can we rely on him?', '{"A":"Can he be relied on?","B":"Can we be relied by him?","C":"Can he be relied by us?","D":"Can we be relied on by him?","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The given sentence contains one of Model verb (Model Verb = will, shall, can, may, might, could, might, must, would). It is in active voice. Formula: Model verb + be + V3 + Optional Objects + ?', 0, 0, 0, 1790961820042) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_417c6962cb0b86de', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'BAKERY : BREAD', '{"A":"Cafe: salad","B":"Cafe :coffee","C":"Cafe :water","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Second is the place where the first is manufactured.', 0, 0, 0, 1790961820096) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ceae1b7966a3f63d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'A young person who learns the particular skills or trades is called:', '{"A":"Learner","B":"Recruit","C":"Apprentice","D":"Probationer","E":"All Of The Above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Apprentice is someone who works for an expert to learn a particular skill or job. Apprentice means نو آموز، کار آموز For example: He worked for two months as a plumber’s apprentice', 0, 0, 0, 1790961820096) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_16e83d13935e030a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'A word formed from the initial letters of other words?', '{"A":"Acronym","B":"Palindrome","C":"Anagram","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Acronyms: Pronounced as a word (e.g., NATO, SCUBA, UNICEF).Initialisms: Pronounced letter-by-letter (e.g., NHS, CEO, USA).Definition: They act as abbreviations and are often used for convenience, according to Merriam-Webster.', 0, 0, 0, 1790961820096) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_677533f8c0a1e5ea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'At first glance, It looks like a diplomatic love-fest. (Which word is a compund noun)?', '{"A":"Love-fest","B":"Glance","C":"Like","D":"Diplomatic","E":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A compound noun is a noun that is made tih two or more words. A compound noun is usually [noun + noun] or [adjective + noun]', 0, 0, 0, 1790961820096) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0d4c631a7ac49b73', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Aslam is believed ________________ this window.', '{"A":"To break","B":"To be broken","C":"To have broken","D":"To breaking","E":"All of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Aslam is believed to have broken this window means مانا جاتا ہیکہ یہ کھڑکی اسلم توڑ چکا ہےThis is a sentence of Passive Voice.Break an irregular verb here.Broke is the second and broken is the third form of Break.', 0, 0, 0, 1790961820096) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d6ab8117fdc620ee', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Aslam is ___ a book.', '{"A":"wrote","B":"writing","C":"write","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Base Form (Infinitive): To WritePast Simple: WrotePast Participle: Written3rd Person Singular: WritesPresent Participle/Gerund: Writing', 0, 0, 0, 1790961820096) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_77f9be1b4d968bb8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Aslam likes Sajad to start the show.', '{"A":"Aslam liked the show to be started by Sajad","B":"Aslam liked the show to be start by Sajad","C":"Aslam was liked the show to be started by Sajad","D":"Aslam likes the show to be started by Sajad","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice = Subject + verb + Noun/Pronoun + to + first form of a verb + Object.Passive Voice = Subject + verb + Object + to be + third form of a verb + by + noun.', 0, 0, 0, 1790961820096) ON CONFLICT(id) DO NOTHING;
