INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_59d53c78c2f2126b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Choose the one which best expresses the meaning of the italicized part of the sentence. Poets and writers are sensuous by nature.', '{"A":"Sensitive","B":"Sensible","C":"Aesthetic","D":"Sensual"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation AANS:Sensuous : relating to or influencing the senses instead of the intellect.Delicate : quick to identify or react to slight changes, signals, or impacts.', 0, 0, 0, 1790961820434) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_693cf93703e07d00', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Choose the one which best expresses the meaning of the italicized part of the sentence. The antidote to these problems is hard to find.', '{"A":"Consequence of","B":"Result of","C":"Remedy for","D":"Cause for"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Antidote : something that neutralizes an repulsive feeling or situation.Remedy : a means of checking or disposing of something undesirable.', 0, 0, 0, 1790961820434) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a0ddc49742527460', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Choose the one which best expresses the meaning of the italicized part of the sentence. For quick promotion. He hit on a plan to propitiate the manager.', '{"A":"Incite","B":"Praise","C":"Conciliate","D":"Evict"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation CANS:Propitiate : win or recapture the support of (a god, soul, or individual) by doing something that satisfies them.Conciliate : stop (somebody) being irate or malcontented; pacify.', 0, 0, 0, 1790961820434) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9870425df086d771', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Choose the one which best expresses the meaning of the italicized part of the sentence. They tolerated him though they dished his craven behavior.', '{"A":"Indecent","B":"Cowardly","C":"Silly","D":"Mean"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation BAND:Cowardly : lacking courage.Craven : contemptibly lacking in courage; cowardly.So the Synonym of Craven is Cowardly', 0, 0, 0, 1790961820434) ON CONFLICT(id) DO NOTHING;
