INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_56a220833b916717', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'One should not give unsolicited advice.', '{"A":"Unsolicited advice is not to be given","B":"Unsolicited advice can''t be given","C":"Unsolicited advice may not be given","D":"Unsolicited advice should not be given","E":"All of the above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active: One should not give unsolicited advicePassive: Unsolicited advice should not be givenUnsolicited advice should not be given means بلاجواز مشورہ نہ دیا جائےActive voice: should not Passive voice: should not be ******', 0, 0, 0, 1790961820519) ON CONFLICT(id) DO NOTHING;
