INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ac9a9bc9a92311a0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Adults suffering _________ chicken pox can develop all kinds of complications.', '{"A":"From","B":"To","C":"With","D":"Off","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Suffer + from is a fixed preposition.Suffering from chicken pox means خسرہ میں مبتلا ہونا', 0, 0, 0, 1790961820759) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ed2c205779c99d6d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Patient is too___ to walk .', '{"A":"veek","B":"weak","C":"week","D":"veak"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation weak کمزور', 0, 0, 0, 1790961820759) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_76a1925d33e8a290', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'People believe that donkeys are the stupid creatures.', '{"A":"It was believed that donkeys are the stupid creatures","B":"It will be believed that donkeys are the stupid creatures","C":"It is believed that donkeys are the stupid creatures","D":"It can be believed that donkeys are the stupid creatures","E":"All of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation People believe that donkeys are the stupid creatures means لوگوں کا ماننا ہیکہ گدھے احمق مخلوق ہیں It is believed that donkeys are the stupid creatures مانا جاتا ہیکہ گدھے احمق مخلوق ہیںSometimes we have to skip "People" while converting the sentence into passive.Present Indefinite TenseActive Voice: Subject + Verb + Object Passive Voice: Object + is/am/are+ third form of a verb + by + subject.', 0, 0, 0, 1790961820759) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5143642adcd9d38a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'People who work together at the same place', '{"A":"Friends","B":"Agents","C":"Colleagues","D":"Rivals","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The term for people working in the same department or office is colleagues or co-workers.', 0, 0, 0, 1790961820759) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_27aca2f3c891a5e2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'People of the older generation ______ over the good old school days.', '{"A":"Reminisce","B":"Retributive","C":"Remind","D":"Remember","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Reminisce over means ماضی کی باتیں کرناRemember means یاد کرناRemind means یاد دلانا', 0, 0, 0, 1790961820848) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6c7bd7458b87d7d0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'People believe that every child is born with different abilities.', '{"A":"It is believed that every child is born with different abilities","B":"It was believed that every child is born with different abilities","C":"It should be believed that every child is born with different abilities","D":"It can be believed that every child is born with different abilities","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice = Subject + believe/find/claim/consider/know/report/say/think/ + that + clause.Passive Voice = It + be + third form of a verb + clause.', 0, 0, 0, 1790961820848) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_71acd007d1180364', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Person who believes that God is every thing and everything is god', '{"A":"Agnostic","B":"Theist","C":"Pantheist","D":"Pantechnicon"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Agnostic: a person who believes that nothing is known or can be known of the existence or nature of God.Theist: a person who believes in the existence of a god or gods, specifically of a creator who intervenes in the universe.Pantheist: person who believes that reality is identical with divinity, or that all-things compose an all-encompassing, immanent god. Pantechnicon: a large van for transporting furniture.', 0, 0, 0, 1790961820848) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5191551145cec34f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Please open the door.', '{"A":"You are requested to open the door","B":"You were requested to open the door","C":"You will be requested to open the door","D":"You should be requested to open the door","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Impetrative Sentences Order: Let + object + be + third form of a verbSuggestion: Object + should be + third form of a verb Request: You are requested/advised to + first form of a verb + object.', 0, 0, 0, 1790961820848) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1eaf5ca085c45089', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Please mind the gap.', '{"A":"You are requested to mind the gap","B":"You were requested to mind the gap","C":"You will be requested to mind the gap","D":"You should be requested to mind the gap","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Rule: Please /kindly → You are requested to. You are requested + rest of sentence.Note: Please and kindly are not used in passive voice.', 0, 0, 0, 1790961820848) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0d1ec2fec71fcb45', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Please finish the task in time.', '{"A":"You are request to finish the task in time","B":"You were requested to finish the task in time","C":"You are requesting to finish the task in time","D":"You have been request to finish the task in time","E":"You are requested to finish the task in time"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Please /kindly → You are requested to. You are requested + rest of sentence.Note: Please and kindly are not used in passive voice.', 0, 0, 0, 1790961820848) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6e8e7966e25a4e4b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Please do not laugh _____________ those beggars.', '{"A":"For","B":"Against","C":"At","D":"From"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Generally At is used after laugh.Laugh is a verb.', 0, 0, 0, 1790961820848) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f935d7060146f010', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Please do not disturb me.', '{"A":"You were requested not to disturb me","B":"You are requested not to disturb me","C":"You will be requested not to disturb me","D":"You should be requested not to disturb me","E":"All of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Order: Let + object + be + third form of a verbSuggestion: Object + should be + third form of a verbRequest: You are requested/advised to + first form of a verb + object. Note: Please and kindly are not used in passive voice.', 0, 0, 0, 1790961820848) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8417dfcc820fcc0e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Please shut the door and leave.', '{"A":"You are requested to shut the door and leave","B":"You were requested to shut the door and leave","C":"You will be requested to shut the door and leave","D":"You should be requested to shut the door and leave","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Please /kindly → You are requested to. You are requested + rest of sentence. Note: Please and kindly are not used in passive voice.', 0, 0, 0, 1790961820946) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1923244d4c0ce195', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Please shut the door and go to sleep.', '{"A":"The door is to be shut and you are to go to sleep","B":"Let the door to be shut and you be asleep","C":"You were requested to shut the door and go to sleep","D":"The door is to be shut and you are requested to sleep","E":"You are requested to shut the door and go to sleep"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice: Please shut the door and go to sleep.Passive Voice: You are requested to shut the door and go to sleep.Given sentence is an Imperative sentence and started with Please that means sentence contains a request in it.Rule: Please /kindly → You are requested to. You are requested + rest of sentence. Note: Please and kindly are not used in passive voice.', 0, 0, 0, 1790961820946) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4e36c863ab830d9e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Pointing a man in a photograph woman said,his brothers father is the only son of my grand father" how is the woman related to man?', '{"A":"Sister","B":"Mother","C":"Grandfather","D":"Father"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Only son of woman''s grandfather — Woman''s father.Man''s brother''s father — Man''s fatherSo. the woman is man''s sister.', 0, 0, 0, 1790961820946) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3fbaf0eb068b68b0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'PROPINQUITY', '{"A":"Capacity","B":"Tendency","C":"Nearness","D":"Habit"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Answer:C: Nearness: A state close to someone or something, Neighborhood.PROPINQUITY: A state close to someone or something, Neighborhood.Capacity: the maximum amount that something can containTendency: Specific traits or behavioral actionHabit: Fixed or regular trends or practices, especially those that are difficult to give up.', 0, 0, 0, 1790961820946) ON CONFLICT(id) DO NOTHING;
