INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8ebf1c0a85b98ead', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Servant is making tea .', '{"A":"Verb of Movement","B":"Verb of Action","C":"Verb of Existence","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An action verb is a verb that describes an action, like run, jump, kick, eat, break, cry, smile, or think.', 0, 0, 0, 1790961821093) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_55258ea8016d7e83', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She died ـــــــــــ a few days', '{"A":"After","B":"Among","C":"Across","D":"Though","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Usage of After and In After is used to refer a past period of time.In is used to refer a future period of time. Examples: She died after a few days means وہ کچھ دنوں بعد انتقال کرگئی', 0, 0, 0, 1790961821093) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8c91c3e99dd904ed', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She didn''t win the prize.', '{"A":"The prize was not won by her.","B":"The prize is not won by her.","C":"The prize was not being won by her.","D":"The prize did not won by her."}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation She didn''t win the prize. (Past Indefinite Tense)The prize was not won by her. (Past Continue Helping verb used as per rule)', 0, 0, 0, 1790961821093) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_772b6e82656bcafb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She has not been working for two hours .this sentence related to which type', '{"A":"positive","B":"negative","C":"Interrogative","D":"none"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation She has not been working for two hoursوہ دو گھنٹے سے کام نہیں کر رہی۔', 0, 0, 0, 1790961821176) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8995bc1cffc9a5bd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She has brought them the massage.', '{"A":"The massage has been brought to them by her","B":"The massage was been brought to them by her","C":"The massage will be brought to them by her","D":"The massage should be brought to them by her","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active sentences in the present perfect tense have the following structure: Subject + has/have + past participle form of the verb + object Passive sentences in the present perfect tense have the following structure: Object of the active sentence + has/have + been + past participle form of the verb + by + subject of the active sentence', 0, 0, 0, 1790961821176) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dbe3ddfe1d7cecc5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She is abnormally thin.Abnormally is a ?', '{"A":"Adverb","B":"Verb","C":"Adjective","D":"Noun"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An adverb is a word or an expression that modifies a verb, adjective, another adverb, determiner, clause, preposition, or sentence', 0, 0, 0, 1790961821176) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4eb5f1aaa19e34d0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She informed __________ me of the event.', '{"A":"To","B":"With","C":"Of","D":"Off","E":"No Preposition Required"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “To” should not be used with the following verbs when followed by an object “Advise, ask, beg, tell, command, encourage, request, inform, thank, welcome, warn, forbid, order, remind, congratulate, compliment” She informed me of the event.', 0, 0, 0, 1790961821176) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6b7afb752a70501c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She is very talented, ____________ she has a bright future.', '{"A":"Undoubtedly","B":"While","C":"Otherwise","D":"When"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Here undoubtedly means certainly.Here undoubtedly means without doubt.Here undoubtedly means بلا شک و شبہ', 0, 0, 0, 1790961821176) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e51f28e0227de6ef', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She passed her examination because she ____ very hard.', '{"A":"studies","B":"studing","C":"studied","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation She passed her examination because she studied very hard.', 0, 0, 0, 1790961821176) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_54371055903f06a8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She must be back _____________ 9 PM.', '{"A":"By","B":"On","C":"In","D":"With","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "By" refers to a point of time and means "Some time before that".Examples:She must be back by 9 PM.You must arrest him by June.He must write a letter by evening.', 0, 0, 0, 1790961821176) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0758366ace21c49f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She lies to everyone_________ nobody likes her.', '{"A":"So","B":"As","C":"If","D":"Where"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Here the word So is a conjunction.Here So means اس وجہ سے', 0, 0, 0, 1790961821176) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5ec6a8b604d7458c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She said to the children, “you must not play with fire”', '{"A":"She told the children they were not to play with fire.","B":"She told the children that they must not play with fire.","C":"She told the children not to play with fire.","D":"She told the children they were not to play with fire."}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation She told the children that they must not play with fire. Sub V object prep V Pro obj', 0, 0, 0, 1790961821245) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3533c3076eda3a5e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She said, "Ruby`s clothes caught fire while she was cooking."', '{"A":"She said that Ruby`s clothes had caught fire while she is cooking","B":"She said that Ruby`s clothes had caught fire while she had been cooking","C":"She said that Ruby`s clothes have caught fire while she was cooking","D":"She says that Ruby`s clothes had caught fire while she is cooking"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Catch fire means آگ لگناCaught is the second and third form of the verb Catch.', 0, 0, 0, 1790961821245) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f008582baa540747', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She wants people like her.', '{"A":"She wants to be liked","B":"She wanted to be liked","C":"She is wanting to be liked","D":"She will want to be liked","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice = Subject + verb + Noun/Pronoun + to + first form of a verb + Object.Passive Voice = Subject + verb + Object + to be + third form of a verb + by + noun. Active Voice: She wants people like her.Passive Voice: She wants to be liked.', 0, 0, 0, 1790961821245) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a6dcb4f65e6e64d0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She usually _______ the baby down for sleep at her time.', '{"A":"Lies","B":"Lied","C":"Lays","D":"Lay"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lay someone down means کسی کو لٹاناThis is a sentece of present indefinite tense.Therefore, lays down should be used.', 0, 0, 0, 1790961821245) ON CONFLICT(id) DO NOTHING;
