INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b7b34235c75daf0c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Somebody recommended me another doctor for my treatment.', '{"A":"I was recommended another doctor for my treatment","B":"I am recommended another doctor for my treatment","C":"I will be recommended another doctor for my treatment","D":"I should be recommended another doctor for my treatment","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This is a sentence of Past Indefinite Tense.Past Indefinite tenseActive Voice= Subject + Second Form of Verb + Object. Passive Voice = Object + was/were + third of verb + by + subject.', 0, 0, 0, 1790961821304) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8523153f3c32207e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Someone saw him picking up a gun.', '{"A":"He was seen pick up a gun by someone","B":"He was seen picking up a gun by someone","C":"He is seen picking up a gun by someone","D":"He was seen by someone pick a gun","E":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Given sentence is in Past simple tense and it is in active voice, we need to change it into passive voice. Rule : Subject + (was / were) + V3 + Optional Agents.', 0, 0, 0, 1790961821304) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_45d816f2ce8271d8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Someone pulled the bull violently.', '{"A":"The bull was pulled violently","B":"The bull is pulled violently","C":"The bull can be pulled violently","D":"The bull should be pulled violently","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Past Indefinite tenseActive Voice= Subject + Second Form of Verb + Object. Passive Voice = Object + was/were + third of verb + by + subject.', 0, 0, 0, 1790961821304) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8a3614467d6fb187', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Someone is following us.', '{"A":"We are being followed (by someone)","B":"We are followed (by someone)","C":"We had been followed (by someone)","D":"He is following us","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Present Continuous TenseActive Voice: Subject + is/am/are + First of verb + ing + object. Passive Voice: Object + is being/am being/ are being + third form of verb + by + subject.', 0, 0, 0, 1790961821304) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cc95efa957300895', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Some boys threw stones at the dogs ------- other wrote letters .', '{"A":"while","B":"when","C":"what","D":"none"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Use a comma before while in the middle of a sentence when you mean “whereas” or “although.', 0, 0, 0, 1790961821304) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8d42367b8cd49148', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Someone has lit the fire.', '{"A":"The fire was lit by someone","B":"You are requested to light the fire by someone","C":"The fire has been lit by someone","D":"The fire had been lit by someone","E":"All of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The given sentence is in active voice and it is in Present Perfect Tense. Rule : Subject + (has /have) + been + V3 + Other agents.', 0, 0, 0, 1790961821304) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cc00c2586497aaa9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Something which is fit to be eaten', '{"A":"Edible","B":"unpalatable","C":"tasty","D":"delicious","E":"all of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Edible قابل تناولUnpalatable بدمزہTasty مزیدارDelicious لذیز', 0, 0, 0, 1790961821395) ON CONFLICT(id) DO NOTHING;
