INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_29ef69baacc84fdb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Synonyms of Largely.', '{"A":"Closely","B":"mostly","C":"barely","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Largely بڑی حد تک', 0, 0, 0, 1790961821471) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_19485c7f3f3a543d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Take your medicines.', '{"A":"You are advised to take your medicines","B":"You were advised to take your medicines","C":"You will be advised to take your medicines","D":"You should be advised to take your medicines","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation should not – (Modal) changes to should not be in Passive. Given sentence is an Imperative sentence and started with Please that means sentence contains a request in it. Rule: Please /kindly → You are requested to. You are requested + rest of sentence. Note: Please and kindly are not used in passive voice.', 0, 0, 0, 1790961821471) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_72776fb35b15f27a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Ten new candidates _____selected', '{"A":"has","B":"are","C":"Have","D":"is"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation While the verb to have has many different meanings, its primary meaning is “to possess, own, hold for use, or contain.” Have and has indicate possession in the present tense.', 0, 0, 0, 1790961821471) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_02e2857de20c2177', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'That new process was brown’s idea', '{"A":"Participle","B":"Gerund","C":"complement","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In grammar, a complement is a word, phrase, or clause that is necessary to complete the meaning of a given expression. Complements are often also arguments', 0, 0, 0, 1790961821471) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f346899adf1a031d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'That is what the spring is all about.', '{"A":"Noun clause","B":"Adverb clause","C":"Adjective clause","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A noun clause plays the role of a noun. It contains a subject and a verb but it does not express a complete thought and cannot stand alone as a complete sentence.', 0, 0, 0, 1790961821548) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e2ae55cfcd8a01e6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'That fine circus elephant now belongs to my sister and ______________', '{"A":"I","B":"me","C":"mine","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct form of pronoun is me', 0, 0, 0, 1790961821548) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8f8a592defd37040', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'That which is no longer in use?', '{"A":"Obsolete","B":"Obscure","C":"inviolable","D":"extempore","E":"All of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Obsolete means متروک یا منسوخ شدہ', 0, 0, 0, 1790961821548) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9a5a55512de81e6a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The accountant took the money from the customer.', '{"A":"The money is taken from the customer by the accountant","B":"The money was taken from the customer by the accountant","C":"The customer was taken the money by the accountant","D":"The money had been taken from the customer by the accountant","E":"All of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Given sentence is in Past simple tense and it is in active voice, we need to change it into passive voice. Rule : Subject + (was / were) + V3 + Optional Agents', 0, 0, 0, 1790961821548) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_78cce3056e7bfd40', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The actor was shocked _____ the news of his cat`s death.', '{"A":"By","B":"At","C":"Of","D":"With","E":"All of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Generally preposition at is used after shock.Shocked at something means صدمے میں ہونا', 0, 0, 0, 1790961821548) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8eba69a864f4cc95', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The applicant answered tough question with _____ candor, winning over many interviews who had previously supported his rival.', '{"A":"Unintentional","B":"Impatient","C":"Disarming","D":"Planed"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Disarming candor” means “with great confidence” in general. Obviously, it can get hold over the rival', 0, 0, 0, 1790961821548) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1166e49ccfb9ee46', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The authorities have urged students and parents to check the official website only for information. Find the error in above sentence (If Any)', '{"A":"Remove check","B":"Add","C":"Add","D":"Add","E":"This is a correct sentence"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ad Adverb comes before the word it describes not after.Only is an Adverb which means صرف', 0, 0, 0, 1790961821548) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a44fd0046aab30cb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The book you want is out of print. THE word is?', '{"A":"Adjective","B":"Indefinite articles","C":"Definite article","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In English total three article, there is just one definite article: "the". There are two indefinite articles: "a" and "an".', 0, 0, 0, 1790961821548) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e7d59ecc9f16cb5f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The boys were digging a hole in the ground.', '{"A":"A hole in the ground was being dug by the boys","B":"A hole in the ground is being dug by the boys","C":"A hole in the ground will being dug by the boys","D":"A hole in the ground can be dug by the boys","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This is a sentence of Past Continuous Tense.Active sentences in the past continuous tense have the following structure: Subject + was/were + -ing form of the verb + object Passive sentences in the past continuous tense have the following structure: Object of the active sentence + was/were + being + past participle form of the verb + by + subject of the active sentence', 0, 0, 0, 1790961821630) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c74870e460965658', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The boy has rung the bell.', '{"A":"The bell has been rung by the boy","B":"The bell was being rung by the boy","C":"The bell was rung by the boy.","D":"The bell has been being rung by the boy","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The given sentence is in active voice and it is in Present Perfect Tense. Rule : Subject + (has /have) + been + V3 + Other agents.', 0, 0, 0, 1790961821630) ON CONFLICT(id) DO NOTHING;
