INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0b5a7af55f6095be', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The farmer ploughed the field.', '{"A":"The field is being ploughed by the farmer","B":"The field was plouged by the farmer","C":"The field is ploughed by the farmer","D":"The field will be ploughed by the farmer","E":"All Of The Above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The farmer ploughed the field means کسان نے کھیت میں ہل چلایاCorrect Passive Voice: The field was plouged by the farmer.Past Indefinite tenseActive Voice= Subject + Second Form of Verb + Object. Passive Voice = Object + was/were + third of verb + by + subject.Plough is a regular verb which means ہل چلاناPloughed is second and third form of Plough.Field means کھیتFarmer means کسان', 0, 0, 0, 1790961821716) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0650cc4df6c9119d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The fire spread through the building very quickly, but fortunately everybody ___ escape.', '{"A":"Could","B":"Succeeded To","C":"Was Able To","D":"Will Be Able To","E":"All Of The Above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Singular verb is used after an indefinite pronoun.Everybody, anybody, everything etc. are called Indefinite Pronouns.', 0, 0, 0, 1790961821716) ON CONFLICT(id) DO NOTHING;
