INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a0efc872f8108356', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The paramedics attempted to -------------- the victim.', '{"A":"Stabilize","B":"Stablize","C":"Stablieze","D":"stabalize"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Stabilize means make stronger', 0, 0, 0, 1790961821861) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7be3daec7c63abe6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The people sitting ____the shade of tree.', '{"A":"On","B":"Under","C":"Below","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When we use under as a preposition, it is similar to below. We use under to talk about something that is below or lower than something else: The cat is under the table.', 0, 0, 0, 1790961821861) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1db62e7f69d3be29', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The peon refused him admittance.', '{"A":"He was refused admittance by the peon","B":"Admittance is refused to him by the peon","C":"Admittance was refused by the peon to him","D":"Admittance is refused him by the peon","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Given sentence is in Past simple tense and it is in active voice, we need to change it into passive voice. Rule : Subject + (was / were) + V3 + Optional Agents', 0, 0, 0, 1790961821861) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6c483859b170ee63', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The person who collects or studies stamps', '{"A":"Notaphilist","B":"Scripophilist","C":"Coleopterist","D":"Philatelist","E":"None of the above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Philatelist means وہ شخس جو ٹکٹ کا مطالعہ کرے یا جمع کرے', 0, 0, 0, 1790961821861) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e556e28e204949b0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The police are ________ our safety.', '{"A":"Since","B":"For","C":"From","D":"Till","E":"All of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation For is also used to show purpose.کسی مقصد کو دکھانے کیلئے بھی استعمال ہوتا ہے The police are for our safety means پولیس ہماری حظاظت کیلئے ہے', 0, 0, 0, 1790961821945) ON CONFLICT(id) DO NOTHING;
