INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_25638e8c54ae9a07', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'To hit below the belt means?', '{"A":"To strike at the exact position","B":"To harm unfairly","C":"To work confidentially","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To hit below the belt: To say something that is often too personal, usually irrelevant, and always unfair.', 0, 0, 0, 1790961822674) ON CONFLICT(id) DO NOTHING;
