INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_71d518e4802cc97c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Mark the adjective used in the sentence “Athar wanted to rent a Commodious building” from the following option.', '{"A":"Building","B":"flent","C":"Commodious","D":"Wanted"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Adjectives mean those words who describe the qualities of nouns like: fun, fast, beautiful, happy.Commodious سامان', 0, 0, 0, 1790961822826) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7b4bd8e4bb4b8428', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Many a person has been saved from the man-eaters by the hunters', '{"A":"These hunters will save many a person from the man-eaters","B":"These hunters save many a person from the man-eaters","C":"These hunters saved many a person from the man-eaters","D":"These hunters have saved many a person from the man-eaters","E":"All of the above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Past Indefinite tenseActive Voice= Subject + Second Form of Verb + Object. Passive Voice = Object + was/were + third of verb + by + subject.', 0, 0, 0, 1790961822826) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7d5fcee8ca00d8a4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Make the adjective used in the sentence "We have put in the suitcase all pressed shirts" from the given choice', '{"A":"suitcase","B":"pressed","C":"shirts","D":"none of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Adjectives mean those words who describe the qualities of nouns like fun, fast, beautiful, happy.same hereShirt is none. “Pressed” increase in the meaning of none.', 0, 0, 0, 1790961822826) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5dd39724ae8c22f9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Live is to Die as pretty is to ______?', '{"A":"Dul","B":"Die","C":"Ugly","D":"Lovely"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Live is to Die as pretty is to UglyPretty خوبصورت opposite is ugly بدصورت', 0, 0, 0, 1790961822902) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1228c332c32eddc5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Let me do this.', '{"A":"Let us do this","B":"This is to be done by me","C":"Let this be done by me","D":"Let I do this","E":"All of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation If a sentence is started with Let the passive voice of that sentence also be started with Let. Rule : Let +Subject +be + V3 + Other agents.', 0, 0, 0, 1790961822902) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_640ece99b9309c18', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Let me do this work.', '{"A":"Let this work be done by me","B":"Let this work be do by me","C":"Let this work should be done by me","D":"Let this work be done by I","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice: Let + indirect object + first form of a verb + direct object.Passive Voice: Let + direct object + be + third form of a verb + by + indirect object. Active Voice: Let me do this work. Passive Voice: Let this work be done by me.', 0, 0, 0, 1790961822902) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8b753850b255eeb4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Let me write an essay.', '{"A":"Let an essay be written by me","B":"Let an essay is written by me","C":"Let an essay be write by me","D":"Let an essay can be written by me","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice: Let + indirect object + first form of a verb + direct object. Passive Voice: Let + direct object + be + third form of a verb + by + indirect object.', 0, 0, 0, 1790961822902) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ae433fe6d6287f16', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Let me ______ you to pronounce words.', '{"A":"Helps","B":"Help","C":"Helped","D":"Helping"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Usually first form of verb is used with let.', 0, 0, 0, 1790961822902) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_91b6e555c39f182a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Lets play ___ game of Hockey', '{"A":"The","B":"an","C":"a","D":"them"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The definite article is used before singular and plural nouns when the noun is specific or particular.', 0, 0, 0, 1790961822902) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7c07f262c5cbf367', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Lets ___ a cup of tea', '{"A":"Has","B":"Have","C":"Come","D":"Be"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Let''s is a contraction of “let us.” You use it to make suggestions about what you and someone else should do', 0, 0, 0, 1790961822902) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b8b9b664a3e98c6b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Let her sing a song.', '{"A":"Let a song be sang by her","B":"Let a song be sing by her","C":"Let a song be sung by her","D":"Let a song be sung by her","E":"All of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice: Let + indirect object + first form of a verb + direct object.Passive Voice: Let + direct object + be + third form of a verb + by + indirect object.', 0, 0, 0, 1790961822902) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_021f1afaf071adfe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Let him play cricket.', '{"A":"Let cricket be played by him","B":"Let cricket is played by him","C":"Let cricket was played by him","D":"Let cricket should be played by him","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice: Let + indirect object + first form of a verb + direct object. Passive Voice: Let + direct object + be + third form of a verb + by + indirect object.', 0, 0, 0, 1790961822983) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e96bcb90d3d33882', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Last week, some innocent people were kidnapped for ransom. (Which word is a Noun ______)', '{"A":"people","B":"Innocent","C":"kidnapped","D":"ransom","E":"none"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ransom is a sum of money demanded or paid for the release of a captive.', 0, 0, 0, 1790961822983) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_935f7a6f2cab1e57', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Just let ____ be', '{"A":"his","B":"her","C":"I","D":"she"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation let be is used as Leave undisturbed, refrain from interfering with.', 0, 0, 0, 1790961822983) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f1cb3e11ac337cf1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'John Keats died of:', '{"A":"Cancer","B":"Tuberculosis","C":"Malaria","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation John Keats was an English Romantic poet. He was one of the main figures of the second generation of Romantic poets, along with Lord Byron and Percy Bysshe Shelley, despite his works having been in publication for only four years before his death from tuberculosis at the age of 25.', 0, 0, 0, 1790961822983) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e4ab9e7825fdcd59', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I will complete this project ________ a week.', '{"A":"In","B":"On","C":"From","D":"During","E":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In & WithinIn = completion of timeWithin = Before the completion of timeI will complete this project in a week میں ایک ہفتے میں یہ پروجیکٹ مکمل کروںگاI will complete this project within a week. Both sentences are correct', 0, 0, 0, 1790961822983) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cf795748a73cffcd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I will join your classes ___________ Saturday.', '{"A":"For","B":"Since","C":"From","D":"None of the above","E":"All of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Preposition means before a position. A word placed before noun or a pronoun to show its relation to some other word in the sentence.From = point of time (present, past & future)I will join your classes from Saturday means میں ہفتے سے آپ کے کلاسز جوائن کروںگا۔', 0, 0, 0, 1790961822983) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_75c9b740675a7ff0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I ___________ you that you shall win today''s competition.', '{"A":"Guarantee","B":"Ensure","C":"Assure","D":"Decline"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ü To ensure something is to make sure it happens -- to guarantee it.ü To insure something or someone is to cover it with an insurance policy. ü To assure someone is to remove someone’s doubts.', 0, 0, 0, 1790961822983) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a895180d3406d725', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I will give you a lift if it____________.', '{"A":"Rain","B":"Was raining","C":"Raining","D":"Rains"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I will give you a lift if it rains means اگر برسات ہوتی ہے تو میں آپ کو لفٹ دونگا', 0, 0, 0, 1790961822983) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_52f1de91df59460a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I will not make the same mistakes that you did.', '{"A":"Adjective clause","B":"Adverb clause","C":"Noun clause","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An adjective clause is a dependent clause that, like an adjective, modifies a noun or pronoun. An adjective clause begin with words such as that, when, where, who, whom, whose, which, and why.', 0, 0, 0, 1790961823058) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a9cd33d3b2986f65', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I was _________ a bad temper so I fought with my friend.', '{"A":"in","B":"on","C":"at","D":"with"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In a bad temper means غصے میں ہونا', 0, 0, 0, 1790961823058) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b470987b29ac1ece', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It is time to take tea.', '{"A":"It will be time to take tea","B":"It is time to taken tea","C":"It was time to be taken tea","D":"It is time for tea to be take","E":"None of the above"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice: It is time to take tea.Passive Voice: It is time for tea to be taken.Third form of verb is always used in passive voice sentence.Take tea means چائے پیناIt is time to take tea means چائے پینے کا وقت آچکا ہےTake is a verb Took is the second form and taken is the third form of Tea.', 0, 0, 0, 1790961823058) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_367c2fb6e561e27a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It is useless ___ cry now.', '{"A":"Of","B":"To","C":"By","D":"From"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Preposition is used to make relation of words', 0, 0, 0, 1790961823058) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f6eac7e8eaa6be1b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It is time to complete the assignments.', '{"A":"It is time for the assignments to be completed","B":"It was time for the assignments to be completed","C":"It will be time for the assignments to be completed","D":"It should be time for the assignments to be completed","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice: It + be + to + first form of a verb + other sentence Passive Voice: It + be + for + object + to + be + third form of a verb.', 0, 0, 0, 1790961823058) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6a04673b923f9e59', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It is time to prepare for CSS exams.', '{"A":"It is time for CSS exams to be prepared","B":"It was time for CSS exams to be prepared","C":"It should be time for CSS exams to be prepared","D":"It will be time for CSS exams to be prepared","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice = Subject + verb + Noun/Pronoun + to + first form of a verb + Object. Passive Voice = Subject + verb + Object + to be + third form of a verb + by + noun.', 0, 0, 0, 1790961823058) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b7cc1c6fd6a6b24b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It is impossible to do this.', '{"A":"Doing this is impossible","B":"This must not be done","C":"This is impossible to be done","D":"This can’t be done","E":"All of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the given sentence, Verb = (am /is /are/ was /were ) +to + verb1 Rule: Subject + (am /is /are/ was /were ) +to + Be + verb3', 0, 0, 0, 1790961823058) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7716a921adf86eb1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It is my meagerness ___ attend ceremony', '{"A":"to","B":"in","C":"by","D":"all"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Use the preposition ''to'' when indicating that there is movement from one place to another.', 0, 0, 0, 1790961823058) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0d91289ec1427675', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It is necessary for the Government to ____ their people''s life better.', '{"A":"Make","B":"Made","C":"Making","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Make is a first form of verb.Made is the second form of verb.', 0, 0, 0, 1790961823116) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_36385b95c50bbe04', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It is a nice day .I ___ we go out for a walk .', '{"A":"Acclaim","B":"Suggest","C":"Recommend","D":"All"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation تجویز Suggest', 0, 0, 0, 1790961823116) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ba6d7838802c6a36', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It is a ___ factory. Five hundred people are employed there.', '{"A":"good","B":"reputed","C":"big","D":"none"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Big" is best option to keep the meaning of original senetence', 0, 0, 0, 1790961823116) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_944400d6b87f4842', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It is Good __________ him to help me in time.', '{"A":"of","B":"for","C":"to","D":"by"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The phrase "It is good of him" is idiomatic and commonly used to express appreciation or approval for someone''s positive actions or behavior. Here, "of" is used to indicate that the action of helping in time is a commendable or praiseworthy quality that belongs to him. Therefore, the correct preposition to fill in the blank is "of".', 0, 0, 0, 1790961823116) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3c3c0046d5c312ba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I take down my notes carefully. In the above sentence, "take down" means what?', '{"A":"To hide","B":"To remove","C":"To publish","D":"To write down"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Write down means تحریر میں لانا', 0, 0, 0, 1790961823116) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1142e8d424230bc6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It has been proven that cockroaches ___________ for several weeks even after their heads have been cut off.', '{"A":"are serviving","B":"can survive","C":"Serviving","D":"that servive"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Can use to express ability or opportunity, to request or offer permission, and to show possibility or impossibility. Examples:ü I can ride a horse. abilityü We can stay with my uncle when we are in Lahore. Opportunityü Any child can grow up to be president. possibilityü he cannot stay out after 11 PM. permission ü Can you hand me the pen? request', 0, 0, 0, 1790961823116) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cc36fe5e40764d8c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I should have met her yesterday.', '{"A":"She should have been met by me yesterday","B":"She should be meeting me yesterday","C":"She should have been meeting by me yesterday","D":"She should be meet by me yesterday","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Present Perfect Tense*********Active sentences in the present perfect tense have the following structure:Subject + has/have + past participle form of the verb + object Passive sentences in the present perfect tense have the following structure: Object of the active sentence + has/have + been + past participle form of the verb + by + subject of the active sentence', 0, 0, 0, 1790961823116) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_24d15146043e999f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Is being pushed ___ donkey.', '{"A":"by","B":"in","C":"on","D":"none"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “By” is usually a preposition but sometimes acts as an adverb.', 0, 0, 0, 1790961823116) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c842138c2b1685b3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I ran ten kilometres with out', '{"A":"Stopping","B":"stopped","C":"none","D":"stop"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The word WITHOUT in the sentence tells us that the speaker has run without breaks.', 0, 0, 0, 1790961823197) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ca32d0f4b91581c6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'In Anglo-Saxon heroic poetry, what is the fate of those who fail to observe the sacred duty of blood vengeance?', '{"A":"Banishment","B":"Everlasting shame","C":"conversation to Christianity","D":"Mild melancholia"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The literature of the Anglo-Saxons is abundant in heroic, or epic, poetry: narrative poems which recount the deeds of heroic figures who overcome significant challenges in the pursuit of goals that were deemed virtuous by the standards of the day.', 0, 0, 0, 1790961823197) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_334dd22d74a4f21f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Incapable of being affected, or cancelled ,or obliterated:', '{"A":"Indelible","B":"Obviously Option","C":"Delegate Option","D":"Delible"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation indelibleناقابل تسخیر', 0, 0, 0, 1790961823197) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ecf6ae26309364e3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I know her.', '{"A":"She is known to me","B":"She was known to me","C":"She will be known to me","D":"She should be known to me","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Note: There are some verbs which never follow preposition “by” they have their own fixed preposition when the sentence is changed into Passive Voice.', 0, 0, 0, 1790961823197) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fb20580ceb8ff2d4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I like my new jeans.', '{"A":"My new jeans are liked by me","B":"My new jeans were liked by me","C":"My new jeans will be liked by me","D":"My new jeans can be liked by me","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This is a simple sentence of Present Indefinite Tense.Present Indefinite TenseActive Voice: Subject + Verb + Object Passive Voice: Object + is/am/are+ third form of a verb + by + subject.', 0, 0, 0, 1790961823197) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b5e096da8284c821', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I make him ______ a letter for me.', '{"A":"to write","B":"wrote","C":"writing","D":"None of these."}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790961823197) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_885b9d4ea72e2056', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I have two cars __ neighter are air conditioned', '{"A":"But","B":"Because","C":"Where","D":"And"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790961823197) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fa9c1f748c1067e1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I know about__________.', '{"A":"He","B":"Him","C":"His","D":"All of the above","E":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Generally, objective case comes after a preposition.Examples:examples: I know about him. “He” is the subjective case while “him” is the objective case."About" is the preposition here.', 0, 0, 0, 1790961823197) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0a2a6bfe144c256c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I got ____ headache.', '{"A":"The","B":"An","C":"A","D":"No article"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Articles "A" and "AN" are used with some expressions.For example:Make a noise, give a warning, have a pain, have a great education etc.', 0, 0, 0, 1790961823253) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b1f38de0bbd9c07c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I had privilege ___ knowing him.', '{"A":"With","B":"Of","C":"To","D":"From"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Preposition connect the words', 0, 0, 0, 1790961823253) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_606f4f72e8f0da69', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I have been in such a picke since I saw you last. In the above sentence the word "Since" is a:', '{"A":"Preposition","B":"Conjunction","C":"Determiner","D":"Adverb"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We use since from a particular time in the past until a later time, or until now.', 0, 0, 0, 1790961823253) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dfb7716278c68bb9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I have been living in this city ___ ten years.', '{"A":"since","B":"for","C":"from","D":"none"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation for is used with a period of time. Since is used to refer to a specific point in time.', 0, 0, 0, 1790961823253) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_aef339d287fed40d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'If you ___________ go by bus, you will get late.', '{"A":"Will","B":"Shall","C":"May","D":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This is a conditional sentence which means اگر آپ بس پر جائیں گے تو آپ کو دیر ہوجائےگی۔', 0, 0, 0, 1790961823253) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ce2be778fda38117', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I expected a reply to my letter _________ the next few days', '{"A":"Of","B":"On","C":"In","D":"Out"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation You use "in" in this sentence because it refers to a period of time that will pass before something happens.', 0, 0, 0, 1790961823253) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4ec1ce6a99dd0cf6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I do not like people hating me.', '{"A":"I do not like hated by people","B":"I do not like people hating by me","C":"I did not like people hating me","D":"I was not like people hating me","E":"I do not like being hated"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice: I do not like people hating me.Correct Passive Voice: I do not like being hated.Note:- It may be noted that more valuable details about this question shall be upload here very soon.', 0, 0, 0, 1790961823253) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1fa62cf1645249a9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I do not see why he is so unkind _________ his brother', '{"A":"Of","B":"At","C":"With","D":"To"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Use the preposition ''to'' when indicating that there is movement from one place to another. In other words, the preposition ''to'' with verbs such as drive, walk, go, hike, fly, sail, etc.', 0, 0, 0, 1790961823253) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2240795443c467c0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Identify the jumbled (confused or meaningless) sentence from the following set of sentences:', '{"A":"I hope everything went well there","B":"Not all is well with the world","C":"I wished him all the best in the future","D":"I wanted to become an officer","E":"We look receiving you forward to date an early"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We look forward to receive you at an early date is the meaningful sentence.', 0, 0, 0, 1790961823317) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2ef1e5f7ba27d593', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Identify the word Bold in the given sentence: I was just Walking ALONG singing to myself.', '{"A":"Conjection","B":"Adverb","C":"Adjective","D":"Interjection","E":"Preposition"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation کی جگہ استعمال کریں گےAdverb کہیں گے۔ ورنہ یہ اسکو Preposition آجائے تو ہم اسکو None کے بعد ALONGاگر', 0, 0, 0, 1790961823317) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_26886042a28b7eab', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I consider him ________ my best friend.', '{"A":"As","B":"As for as","C":"Off","D":"To","E":"No preposition required"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Certain words when used in “Active Voice” are not followed by any preposition. “Accompany, affect, consider, compromise, emphasize, resemble, ensure, attack, invade, order, reach, describe, discuss, tell” etc.I consider him my best friend.', 0, 0, 0, 1790961823317) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_92fa56e8ca2c5ddf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I could not get a seat in the front seat ___________ I came early.', '{"A":"Though","B":"Because","C":"When","D":"As"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I could not get a seat in the first row though I came early.اگرچہ میں سویرا آیا پھر بھی پہلی قطار میں سیٹ حاصل نہ کرسکا۔', 0, 0, 0, 1790961823317) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_64c8942d43bbf1fa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I cannot draw this picture.', '{"A":"This picture cannot be drawn by me","B":"This picture cannot be drawn by I","C":"This picture could not be drawn by me","D":"This picture could not be drawn by I","E":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sentence is in Simple Present Tense. The model (can) has been used in active which changed to can be in passive.', 0, 0, 0, 1790961823317) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_25c01eb3fc587021', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I can`t get out this stain. In the above sentence the phrasal verb "Get out" means what?', '{"A":"Remove","B":"spead","C":"polish","D":"figured"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In this context, get out means مٹانا', 0, 0, 0, 1790961823317) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2de3c3f0e3542b6c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I as well as he __________ in the meeting', '{"A":"Is","B":"Am","C":"Are","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation If the noun is singular, use is. If it is plural or there is more than one noun, use are.', 0, 0, 0, 1790961823317) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fef458aa0fc985b0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I begged __________ him to give a piece of bread.', '{"A":"To","B":"About","C":"With","D":"Of","E":"No Preposition Required"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “To” should not be used with the following verbs when followed by an object “Advise, ask, beg, tell, command, encourage, request, inform, thank, welcome, warn, forbid, order, remind, congratulate, compliment” I begged him to give a piece of bread.', 0, 0, 0, 1790961823317) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4091ae33a79f71e0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I am not ___ good.', '{"A":"Feel","B":"feeling","C":"felt","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Base Form (Infinitive): To FeelPast Simple: FeltPast Participle: Felt3rd Person Singular: FeelsPresent Participle/Gerund: Feeling', 0, 0, 0, 1790961823406) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3cb07bd899d7f675', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I accompanied _________ him.', '{"A":"With","B":"Without","C":"Above","D":"About","E":"No preposition required"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Certain words when used in “Active Voice” are not followed by any preposition.“Accompany, affect, consider, compromise, emphasize, resemble, ensure, attack, invade, order, reach, describe, discuss, tell” etc. I accompanied him.', 0, 0, 0, 1790961823406) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c11c0658fbcda515', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I am bargaining ___ him', '{"A":"with","B":"on","C":"to","D":"all"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation With means ''in the same place as someone or something'' or ''accompanying'': She arrived with her boyfriend.', 0, 0, 0, 1790961823406) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a8b0a190d6ca8211', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I am bit week ________ geography but I am trying hard.', '{"A":"in","B":"at","C":"on","D":"over"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A word governing, and usually preceding, a noun or pronoun and expressing a relation to another word or element in the clause is called preposition.', 0, 0, 0, 1790961823406) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_334f72be8ac5ec84', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I, ____ your king, will lead you.', '{"A":"who is","B":"who am","C":"who","D":"who was"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation If you can replace the word with “he”'' or “''she,” use who. If you can replace it with “him” or “her,” use whom.', 0, 0, 0, 1790961823406) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7c6bc1606404fa61', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'How ___ money do you have?', '{"A":"more","B":"much","C":"many","D":"none"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Use ''Much'' with uncountable nouns. We use much with singular nouns. Question: "How much petrol is in the car?" ...Use ''Many'' with countable nouns. We use many with plural nouns. Question: "How many people were at the meeting?" ...Use a ''A lot of'' and ''Lots of'' with both. Both mean a large amount.', 0, 0, 0, 1790961823406) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2a45b3245779d54a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'How often do you go out? In the above sentence, the words "How Often" denote:', '{"A":"Place","B":"Frequency","C":"Duration","D":"Distance","E":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation How often means کتنی مرتبہFrequency means happening.', 0, 0, 0, 1790961823406) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4328b01eddd7f36f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'How pretty she is ! this sentence is related to which type?', '{"A":"negative","B":"positive","C":"Interrogative","D":"Exclamatory Sentences"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation It is Exclamatory Sentence due to sign / mark of Exclamation (!)', 0, 0, 0, 1790961823406) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6cfad49c43ef41f5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'How many plays ___ Shakespeare write?', '{"A":"Have","B":"did","C":"do","D":"none"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To make a question in the Past Tense in English we normally put the auxiliary DID at the beginning of the question or before the main subject. DID is used with regular AND irregular verbs in English.', 0, 0, 0, 1790961823487) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_296a32b5e390ce0d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'How does he look like ? I know he shaves his head ,but does he have any facial?', '{"A":"Expressions","B":"Hairs","C":"Nose","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790961823487) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_15bacb524924cb78', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Which is the singular subject pronoun in the sentences "I like to walk in the rain for a long time because no one could see my tears."', '{"A":"My","B":"I","C":"Could","D":"Tears"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Which is the singular subject pronoun in the sentences "I like to walk in the rain for a long time because no one could see my tears."Correct answer my.', 0, 0, 0, 1790961823487) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a9e27a9e7e39efc2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Which of the following was a group that tried to spread catholic teaching after the reformation?', '{"A":"The Jesults","B":"The Baptists","C":"The Protestants","D":"The Calvinists"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790961823487) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5a7cee99dc9abead', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Which of the following word is closest in meaning to ZENITH ?', '{"A":"Over","B":"Promulgate","C":"Top","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Zenith سمت الراس', 0, 0, 0, 1790961823487) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ad91717c9d021fcf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Which word is a predicative noun. Solar energy can be an alternative source of power.', '{"A":"Solar","B":"Can be","C":"Alternative source of power","D":"Energy"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Solar energy can be an alternative source of power.Correct answer C', 0, 0, 0, 1790961823487) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1072ef05c9b0386e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Who asked you to draft this letter?', '{"A":"By whom were you asked to draft this letter?","B":"By whom are you asked to draft this letter?","C":"By whom will you asked to draft this letter?","D":"By whom should you asked to draft this letter?","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This is an interrogative sentence of Past Indefinite Tense.Past Indefinite tenseActive Voice= Subject + Second Form of Verb + Object. Passive Voice = Object + was/were + third of verb + by + subject.', 0, 0, 0, 1790961823487) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0be0e11a9fcb0f88', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Who can complete this task?', '{"A":"By whom can this task be completed?","B":"By whom could this task be completed?","C":"By whom was this task be completed?","D":"By whom should this task be completed?","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice: WhoPassive Voice: By whomWho can complete this task means اس کام کو کون مکمل کرسکتا ہے', 0, 0, 0, 1790961823487) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_82f73a17b84410bd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Who can break this stick?', '{"A":"By whom can this stick be broken?","B":"By whom could this stick be broken?","C":"By whom should this stick be broken?","D":"By whom can this stick be broke?","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice: WhoPassive Voice: By WhomBreak is a verb which means توڑناBroke is the second form while Broken is the third form of Break.', 0, 0, 0, 1790961823582) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_286dafc170a5e077', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Who called Dryden the Father of English Criticism?', '{"A":"Joseph Addison","B":"Dr. Johnson","C":"Coleridge","D":"Matthew Arnold"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dr Johnson, was an English writer who made lasting contributions to English literature as a poet, playwright, essayist, moralist, literary critic, biographer, editor, and lexicographer.', 0, 0, 0, 1790961823582) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c2122c032426b819', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Who designed a car?', '{"A":"By whom a car designed","B":"By whom a car had designed","C":"By whom a car was designed","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A car is a wheeled motor vehicle used for transportation.', 0, 0, 0, 1790961823582) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f06be32df34fd8f9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Who deals ____ routine correspondence?', '{"A":"At","B":"With","C":"For","D":"On"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Deal is either followed by with or in.', 0, 0, 0, 1790961823582) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_90d4242ddd12f43d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Who gave you ice-cream?', '{"A":"By whom were you given ice-cream?","B":"By whom was you given ice cream?","C":"Who had given you ice cream?","D":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sentence is in Simple Past Tense. Past Indefinite tenseActive Voice= Subject + Second Form of Verb + Object. Passive Voice = Object + was/were + third of verb + by + subject.', 0, 0, 0, 1790961823582) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a73f42292a5ccb5f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Who is that woman over there talking to ____ Rehman?', '{"A":"The","B":"A","C":"An","D":"No article"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Who is that woman over there talking to Rehman?وہاں وہ عورت کون ہے جو رحمان سے باتیں کررہی ہے؟No article', 0, 0, 0, 1790961823582) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3a3dce99dbe48e1d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Who is telling a lie?', '{"A":"By whom is a lie being told?","B":"By whom was a lie being told?","C":"By whom will a lie being told?","D":"None of the above","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Who is telling a lie is an interrogative sentence of Present Continuous Tense.Who is telling a lie means کون جھوٹ بول رہا ہےWho means کونTell a lie means جھوٹ بولناPresent Continuous TenseActive Voice: Subject + is/am/are + First of verb + ing + obect.Passive Voice: Object + is being/am being/ are being + third form of verb + by + subject.', 0, 0, 0, 1790961823582) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0a941b970d62d96c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Who translated the original Bengali poems of Geetanjali into English?', '{"A":"Sir Edmund Goose","B":"W B Yeats","C":"Rev. Edmund Thomson","D":"Rabindranath Tagore"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Rabindranath Tagore was an Indian polymath- poet, writer, composer, philosopher and painter from Bengal.', 0, 0, 0, 1790961823582) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3a0e0a5ca289681d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Who was the leading figure of Christian humanism?', '{"A":"Thomas More","B":"Martin Luthar","C":"Johan Tetzel","D":"Erasmus"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Erasmus was a Dutch philosopher and Christian scholar.', 0, 0, 0, 1790961823685) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4bc495724a9a025b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Who will write an essay?', '{"A":"By whom will an essay be written?","B":"By whom should an essay be written?","C":"By whom was an essay be written?","D":"By whom can an essay be written?","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice: Who Passive Voice: By whomWho will write an essay means ایک مضمون کون لکھے گاFuture Indefinite Tense Active Voice Formula: Subject + Will/Shall + Verb (Ist form) + Object + (.) Passive Voice Formula: Convert Object to Subject + Will/Shall + Be + Verb (3rd form) + By + Convert Subject to Object + Remaining + (.)', 0, 0, 0, 1790961823685) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9a02194959ff65fa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Who will not have cleaned the number of tables?', '{"A":"By whom will the number of tables not have been cleaned?","B":"By whom was the number of tables not have been cleaned?","C":"By whom shall the number of tables not have been cleaned?","D":"By whom is the number of tables not have been cleaned?","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This is in interrogative sentence of Future Perfect Tense.Active verb form: will/shall + have + past participle form of the verbPassive verb form: will/shall + have been + past participle form of the verb', 0, 0, 0, 1790961823685) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5a013318f00398ea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Who will help him in difficulty?', '{"A":"By whom will he be helped in difficulty?","B":"By whom is he helped in difficulty?","C":"By whom was he be helped in difficulty?","D":"By whom can he be helped in difficulty?","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice: WhoPassive Voice: By whomThis is a sentence of Future Indefinite Tense.Will be and Shall be are the helping verbs of Future Indefinite Tense.', 0, 0, 0, 1790961823685) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3fda76204aa34c98', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Who wrote, ‘Milton! thou shouldst be living at this hour’.', '{"A":"Dryden","B":"Pope","C":"Gray","D":"Wordsworth"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation William Wordsworth was an English Romantic poet who, with Samuel Taylor Coleridge, helped to launch the Romantic Age in English literature with their joint publication Lyrical Ballads.', 0, 0, 0, 1790961823685) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_af74004dfe3fb75b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Why do you waste your money?', '{"A":"Why is money been wasted by you?","B":"Why has money been wasted by you?","C":"Why is your money wasted by you?","D":"Why is your money being wasted by you?","E":"All of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The given sentence is in Present Indefinite Tense.Why do you waste your money means تم اپنا پیسہ کیوں ضائع کرتے ہو؟Waste is a verb here.Wasted is the second and third form of Waste.Present Indefinite TenseActive Voice: Subject + Verb + Object Passive Voice: Object + is/am/are+ third form of a verb + by + subject.', 0, 0, 0, 1790961823685) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8ee5b3631f3070b3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Why do you buy so much books , when you do not read ----- of the them', '{"A":"all","B":"each","C":"any","D":"none"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation How to Use ANY in EnglishWe use ''any'' in negative sentences (with doesn''t, don''t, didn''t, etc.) ...“He never says anything.”“We didn''t stop anywhere."“Did anyone understand this?”', 0, 0, 0, 1790961823686) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3e257d1278789e2c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Why does he teach the children?', '{"A":"Why are children taught by him?","B":"Why children are taught by him?","C":"Why do he teach the children?","D":"No passive"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790961823686) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2ff669d225af244b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Why was I not invite to dinner by Him? Change voice', '{"A":"Why was he not invite me to dinner","B":"Why did he not invite me to dinner","C":"Why would he not invite me to dinner","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Past Participlewas change into did', 0, 0, 0, 1790961823774) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_923a029f307cfa7b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Will you be showcasing the architecture models___you prepared in China last year?', '{"A":"Which","B":"Who","C":"Whose","D":"That"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We use which in relative clauses to refer to animals and to things', 0, 0, 0, 1790961823774) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_41acdc807f2be732', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Will they not have solved one of the questions?', '{"A":"Will one of the questions not have been solved by them?","B":"Was one of the questions not have been solved by them?","C":"Can one of the questions not have been solved by them?","D":"Should one of the questions not have been solved by them?","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This is an interrogative sentence of Future Perfect Tense.Active verb form: will/shall + have + past participle form of the verb Passive verb form: will/shall + have been + past participle form of the verb', 0, 0, 0, 1790961823774) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bad0a64f5071f74c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Women like men to flatter them.', '{"A":"Men are liked by women to flatter them","B":"Women like to be flattered by men","C":"Women like that men should flatter them","D":"Women are liked to be flattered by men","E":"All Of The Above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We cannot start this sentence from "men".We should start this sentence from "women".While changing active into passive we should not change the sense of a sentence.If we start this sentence from "men", the sense of the sentence will be changed.Women like to be flattered by men is the correct passive.', 0, 0, 0, 1790961823774) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_14896db84d2fa8d6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'With the less rapid expansion of the economy, we should make _____ progress toward stable price levels.', '{"A":"Detailed","B":"Substantial","C":"Define","D":"Indefinite"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790961823774) ON CONFLICT(id) DO NOTHING;
