INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6ca38cecffc55230', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Would the number of politicians not have helped a number of poor people?', '{"A":"Would a number of poor people not have been helped by the number of politicians?","B":"Would a number of poor people not has been helped by the number of politicians?","C":"Would a number of poor people not have been help by the number of politicians?","D":"Would a number of poor people not have helped by the number of politicians?","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice: Would have + third form of a verb Passive Voice: Would have been + third form of a verb.', 0, 0, 0, 1790961823774) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ca2eddab732dc4f3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'You are to write an essay.', '{"A":"An essay is to be written by you","B":"An essay was to be written by you","C":"An essay will be written by you","D":"An essay should be written by you","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sentence With Infinitive Passive Voice: Helping Verb + To be + third form of a verb + by + ……..', 0, 0, 0, 1790961823774) ON CONFLICT(id) DO NOTHING;
