INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bd52872a79b81fda', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '_______ the constitution of new housing units at the rate of one every month, there is still a shortage of accomodation.', '{"A":"Through","B":"Despite","C":"By","D":"For"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Here despite means کے باوجود', 0, 0, 0, 1790961824321) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a6658bc4ae828e85', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '_______ is state of calmness and tranquility.', '{"A":"Peace","B":"war","C":"aggression","D":"all of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Calmness is the mental state of peace of mind being free from agitation, excitement, or disturbance.', 0, 0, 0, 1790961824321) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d9a781196a6b876b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '_________ food, the pilgrims carried some medicines.', '{"A":"Beside","B":"Besides","C":"Regarding","D":"Offering","E":"All of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Beside means بغل میں Besides means اس کے علاوہBesides food, the pilgrims carried some medicines meansخوراک کے علاوہ زائرین نے کچھ دوائیاں بھی اٹھائیں', 0, 0, 0, 1790961824321) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d470d1ceb0a62b47', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '________ pollution control measures are expensive, many industries hesitate to adopt them.', '{"A":"Because","B":"However","C":"Although","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Because pollution control measures are expensive, many industries hesitate to adopt them.', 0, 0, 0, 1790961824413) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bba77f6dae33faa9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '________ moon gave no light!', '{"A":"A","B":"An","C":"The","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Usually Article the is used before unique things like Sun, Earth, Moon etc.', 0, 0, 0, 1790961824413) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_882593646ccc97a7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '_________ you search his pocket you will find the watch.', '{"A":"For","B":"If","C":"As","D":"As far as"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This is a conditional sentence.If means اگر', 0, 0, 0, 1790961824413) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_021206251f3bb4a3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '_________ of them will refute the charges.', '{"A":"Both","B":"Neither","C":"Either","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Neither of them will refute the charges.This is a double negative, which implies that both will refute the charges.But in standard usage, it''s better to avoid double negatives. So, the sentence should ideally be:', 0, 0, 0, 1790961824413) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8f8c7bb1fee86932', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '___________ of the two pencils will do it must be black in color and its length must be shorter.', '{"A":"Either","B":"Any","C":"Some","D":"All of the above","E":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Either of the two pencils will do it must be black in color and its length must be shorter.Either is a pronoun here.', 0, 0, 0, 1790961824413) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_80c31235cbdb4f94', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '___________ honest man is always respected by all', '{"A":"a","B":"an","C":"as","D":"none of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ''An'' would be the right article.', 0, 0, 0, 1790961824413) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4e3a1aee9112928b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '___________ his children his nephews were also present at the ceremony.', '{"A":"Beside","B":"Besides","C":"From","D":"Since","E":"All of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Beside means بغل میں Besides means کے علاوہBesides his children his nephews were also present at the ceremony meansاس کے بچوں کے علاوہ اس کے بھتیجے بھی تقریب میں موجود تھے۔', 0, 0, 0, 1790961824413) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4a028ce8aa75cb3a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '___________ climber has a sudden fall', '{"A":"Hasty","B":"Mountain","C":"Fall","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hasty climber has a sudden fallجلدی کام شیطان کا', 0, 0, 0, 1790961824413) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c52d7455bddca458', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '___________ only dark chocolates are delicious, _________ also they can be healthy too.', '{"A":"If, but","B":"Not, but","C":"If, then","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Generally not only is followed by but also.', 0, 0, 0, 1790961824507) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ed861c043d75b4bb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '_________________ of the two students will complete the project.', '{"A":"Either","B":"Any","C":"Both A and B","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Any is used for more than two while either is used for two.', 0, 0, 0, 1790961824507) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_52a8e3a32e9f996a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '________________ but some students was present.', '{"A":"Nothing","B":"nobody","C":"Both A and B","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Everybody, everything, nobody, nothing, somebody, something anybody, anything are the examples of pronoun. These pronouns considered as singular.These pronouns are used for people and things.', 0, 0, 0, 1790961824507) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_90bd579bc87ed3e6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '_____________ section of the society is feeling the pinch of rising prices and corruptions.', '{"A":"Everyone","B":"Every","C":"Anybody","D":"None of the above."}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We use pronoun instead of a noun.We cannot use noun and pronoun at the same place.Here the word every is an adjective not pronoun.', 0, 0, 0, 1790961824507) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3668ca145b506d30', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '____________________ the two students did the work.', '{"A":"Neither","B":"Either","C":"None","D":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation None gives negative sense. Neither is used for two.', 0, 0, 0, 1790961824508) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ca8560aaeba24c2a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They will have completed the work by the time we get there.', '{"A":"The work will be completed by the time we get there","B":"The work will have been completed by them  by the time we get there","C":"The work will have completed by the time we get there","D":"The work will have been completed by the time we have got there","E":"All of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Only the finite verbs (verbs that show or decide the tense of the whole sentence) undergo voice change. Here ‘will have completed’ is the finite verb. (Incidentally, the verb ‘get’ in the subordinate clause ‘by the time we get there’ is intransitive in nature. It has no object in this context.)', 0, 0, 0, 1790961824508) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1c8e14cebb2ab1ce', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '“Acclimatize” means what?', '{"A":"To get used to","B":"To rest","C":"to face the challenge","D":"to train oneself"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Acclimatize means نئے حالات کا عادی ہونا', 0, 0, 0, 1790961824508) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4c0602ffa1cd463a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '“Comprehensive” mans what?', '{"A":"Lengthy","B":"Complete in every respect","C":"Laborious","D":"Brief"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Including all or nearby all elements or aspects of something.', 0, 0, 0, 1790961824508) ON CONFLICT(id) DO NOTHING;
