INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_52b760ed105780d4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'A verse of Holy Quran which sahabi name.', '{"A":"Hazart Zaid bin Sabit ( R.A)","B":"Hazart Zaid Bin Haris ( R.A)","C":"Hazart Abu Bin Talib ( R.A)","D":"Hazart Abdullah bin Massoud ( R.A)"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Zayd Bin Harith (R.A) name is mentioned in the Al-Ahzab 33rd Surah of Quran verse number 37. Zayd Bin Harith (R.A), the adopted son and Sahabi of Prophet Muhammad (P.B.U.H) whose name mentioned in the Quran.', 0, 0, 0, 1790964555426) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_e8faa964ecf418f9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_quran', 'How many parts of Holy Quran?', '{"A":"30","B":"40","C":"114","D":"20","E":"16"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Quran is divided into 30 equal parts called Juz (pl. Ajza) The Quran is organized into 114 chapters', 0, 0, 0, 1790964555426) ON CONFLICT(id) DO NOTHING;
