INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_f1d766573c8fa1af', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Prophet Muhammad (PBUH) had __________ sons.', '{"A":"4","B":"3","C":"2","D":"1"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Three Sons of Prophet (PBUH)Hazrat Al-Qasim was born from HAZRAT KHADIJ. buried in Jannat ul Moalla, MeccaHazrat Abdullah was born from HAZRAT KHADIJ. buried in Jannat ul Moalla, MeccaHazrat Ibrahim was the third son and born from Hazrat Mari. Buried in Jannat ul Baki, Madina. Hazrat Maria was gifted by the Ruler of Sikandria to the Holy Prophet.*********There are Four Daughters of Prophet (PBUH).Last updated by NA on 25-April-2026', 0, 0, 0, 1790964559473) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_7651c19c77e2319e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Who claimed to be prophet during the period of Hazrat Abu Bakar Siddique?', '{"A":"Muselima Kazzeb","B":"Asvad Ansi","C":"Talhea Bin Khavaled","D":"Sajah Binte Khavaled"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Musailama al Kazzab False Prophet Was Called The Liar’ By The Holy Prophet Wahshi ibn Harb killed Muslema Kazab (Musailamah al Kazzab)He was killed in the Battle of Yamama in 632 CE.', 0, 0, 0, 1790964559473) ON CONFLICT(id) DO NOTHING;
