INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_d4e035cddbd573bb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Who accompanied the Holy Prophet (PBUH) in the Cave of Saur?', '{"A":"Hazrat Ali (RA)","B":"Hazrat Umar (RA)","C":"Hazrat Abu Bakr (RA)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Also known as Ghar Thawr and Ghar e Saur. According to Islamic legends, this cave is where the Holy Prophet and his companion Abu Bakr al-Siddiq found shelter when fleeing from Quraish search parties.The Prophet (PBUH) and his companion Abu Bakr (RA) hid for three days.', 0, 0, 0, 1790964559473) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_ti_73a048668db5c2ce', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_isl_prophets', 'Holy Prophet (PBUH) the phase secret preaching continued for how many years?', '{"A":"2 years","B":"3 years","C":"4 years","D":"5 years"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Muhammad SAW preached Islam secretly for three years. Openly preaching start in 4 Nabvi.', 0, 0, 0, 1790964559473) ON CONFLICT(id) DO NOTHING;
