INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_0a76e357043e4bd4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'The atmospheric pressure (air pressure) at any place is measured by _____?', '{"A":"Altimeter","B":"Pressure Meter","C":"Barometer","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A Barometer is an instrument used to measure air (atmospheric) pressure.It helps in weather forecasting by measuring changes in atmospheric pressure.The mercury barometer is the oldest type of barometer.It was invented by Evangelista Torricelli in 1643.Barometers are widely used in meteorology and aviation.Last verified on 09-07-2026', 0, 0, 0, 1790965657720) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_e71e13b8c8d1f8b9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'The Currency of Sudan is _____?', '{"A":"Pound","B":"Dinar","C":"Som","D":"Franc"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sudan Currency is Sudanese Pound.Sudan Capital is Khartoum.Sudan official language is Arabic; English.Sudan located is in Continent Africa.Sudan Primary Religion is Islam.Tricks for RememberPOUND S-E-S-UMind Trick : Sheshu(a name) plays in the Pond.**S-E-S-U**S - South SudanE - EgyptS - SyriaU - UK Last verified on 09-09-2026', 0, 0, 0, 1790965657720) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_771966bb62fae209', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Statue of Liberty in New York was designed and prepared in ______?', '{"A":"United States of America","B":"France","C":"England","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Statue of Liberty in New York was designed and prepared in France.Location: Liberty Island, New York City, USAIt was a gift from France to the United States as a symbol of friendship.Construction Started: 1876Construction Completed: 1886Dedicated: 28 October 1886Additional information:Height: 93 meters (305 feet)Designer: Frédéric Auguste Bartholdi (French sculptor).It was designated a U.S. National Monument on 15 October 1924.It became a UNESCO World Heritage Site in 1984.Last verified on 26-07-2026', 0, 0, 0, 1790965657720) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_5c684b9256cfffe7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'During World War I, which side did the Ottoman Caliphate support?', '{"A":"Germany","B":"Britain","C":"France","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Ottoman Caliphate in World War IJoined the Central Powers.Allied with Germany in August 1914.Entered the war in October 1914.Declared Jihad against the Entente in November 1914.Defeated in 1918, the empire collapsed.Republic of Turkey was established in 1923.', 0, 0, 0, 1790965657720) ON CONFLICT(id) DO NOTHING;
