INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_ddd1923949ce1808', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Khushal Khan Khattak was a famous poet of which language?', '{"A":"Siraiki","B":"Punjabi","C":"Balochi","D":"Pashto"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Khushal Khan Khattak was a famous poet of the Pashto language.He was a renowned Pashtun poet, warrior, and tribal chief of the 17th century.He is also widely known as Khushal Baba.He was born in 1613.He was died in 1689.His poetry covers themes such as bravery, honour, wisdom, love, and Pashtun unity.Last verified on 08-08-2026', 0, 0, 0, 1790965658538) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_ae2d80a0fbefb478', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', '‘Grameen Bank’ a pioneer in the field of microfinance was the brainchild of ______?', '{"A":"Prof. Muhammad Younus","B":"Dr. Riaz Rahman","C":"Fazle Hussain Abid","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prof. Muhammad Yunus, a Bangladeshi economist and founder of Grameen Bank, pioneered microfinance.He provided small loans to rural women in Bangladesh, empowering them to break the cycle of poverty.His innovative approach earned him the Nobel Peace Prize in 2006.', 0, 0, 0, 1790965658538) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_2ac4461bd300633e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'The United States completed its withdrawal from Afghanistan on which date?', '{"A":"28 August 2021","B":"31 August 2021","C":"2 September 2021","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The United States Armed Forces completed their withdrawal from Afghanistan 2021 Date: 29 February 2020 – 30 August 2021 (1 year, 6 months and 1 day)In February 2020, the first Trump administration and the Taliban signed the United States–Taliban deal in Doha, QatarLast updated question 18-02-2026', 0, 0, 0, 1790965658538) ON CONFLICT(id) DO NOTHING;
