INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_e3a095ba7ebdd909', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'When did the United Kingdom (UK) leave the European Union (Brexit)?', '{"A":"28 January 2020","B":"29 January 2020","C":"30 January 2020","D":"31 January 2020"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The United Kingdom officially left the European Union (EU) on 31 January 2020 at 11:00 p.m. GMT.It is known as Brexit (British Exit).It ended the UK''s 47-year membership of the European Union.The transition period lasted until 31 December 2020.Referendum Date: 23 June 2016Article 50 Triggered: 29 March 2017Referendum Result: Leave – 51.9%, Remain – 48.1%Last verified on 08-04-2026', 0, 0, 0, 1790965658829) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_7cf6d6f616ae1cd7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', '18th July has officially been declared by _____ as Mandela Day.', '{"A":"United Nations","B":"United States of America","C":"World Bank","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nelson Mandela International Day is an annual international day in honour of Nelson Mandela, celebrated each year on 18 July, Mandela''s birthday.The day was officially declared by the United Nations in November 2009, with the first UN Mandela Day held on 18 July 2010. ***', 0, 0, 0, 1790965658829) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_301e45335386d2dd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'What is the definition of terrorism?', '{"A":"The calculated use of violence and fear to achieve political goals","B":"The calculated use of violence and fear to achieve ideological goals","C":"The calculated use of violence and fear to achieve religious goals","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Terrorism generally refers to the calculated use or threat of violence and fear to achieve political, ideological, or religious objectives.It aims to intimidate governments, societies, or specific groups.Terrorism may be carried out by individuals, groups, or organizations.Last verified on 28-07-2026', 0, 0, 0, 1790965658829) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_bb6a5e831a54d7fe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'What is the new name of the organization that replaced RCD (Regional Cooperation for Development) in 1985?', '{"A":"ILO","B":"UNHCR","C":"ECO","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Renamed: Economic Cooperation Organization (ECO) in 1985Purpose: Economic, technical, and cultural cooperationRCD: Regional Cooperation for DevelopmentFounded by: Iran, Pakistan, and TurkeyECO Headquarters: Tehran, IranEstablished: 21 July 1964RCD dissolved: 1979Last updated 26-07-2026 by NA', 0, 0, 0, 1790965658829) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_7782977f0abe5cb1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'X-rays have been discovered by ______?', '{"A":"Charles Babbage","B":"Wilhelm Conrad Roentgen","C":"Ernest Rutherford","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Wilhelm Conrad Rontgen discovered X-rays He was discovered on 8 November 1895.He got the Nobel Prize in Physics in 1901.Additional questionsThe penetrating power of X-rays depends on their frequencyLast updated 26-07-2026 by NA', 0, 0, 0, 1790965658829) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_a1479caa7920a169', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Land ports are established primarily to:', '{"A":"Promote tourism and improve cultural exchange across borders","B":"Facilitate legal trade, customs, and immigration at land borders","C":"Develop maritime trade and manage commercial seaport operations","D":"Expand domestic air transport and improve airport infrastructure"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Land ports facilitate trade and immigration.Land ports provide customs and immigration clearance.Customs Department operates at land ports.Land ports are established at international borders.Land ports are governed by Land Port Authority Act, 2023.Pakistan Land Port Authority was established in 2023.PLPA improves border management and trade facilitation.Torkham is a major land port of Pakistan.Torkham is on the Pakistan–Afghanistan border.Land ports ensure secure legal trade.زمینی سرحدوں پر تجارت اور امیگریشن کو آسان بنانے کے لیے۔', 0, 0, 0, 1790965658829) ON CONFLICT(id) DO NOTHING;
