INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_3194fcb8b2133be0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Bullfighting is a famous sport of?', '{"A":"Brazil","B":"Italy","C":"Spain","D":"Germany"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bullfighting (Corrida de Toros) is a traditional sport of Spain.It has been practiced in Spain for centuries.The main performer is called a Matador.Last verified on 21-07-2026', 0, 0, 0, 1790965659344) ON CONFLICT(id) DO NOTHING;
