INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_d93bc28b8a6588bd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', '____ is called the father of Artificial Intelligence ?', '{"A":"Mark Zuckerberg","B":"Alan Turing","C":"John McCarthy","D":"Bill Gates"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation John McCarthy is called the father of artificial intelligence. He was an American computer scientist He coined the term "artificial intelligence" in 1955Organized the 1956 Dartmouth Conference, which is considered the birth of AI as a field of study. Received the Nobel Prize of Computing in 1971', 0, 0, 0, 1790965661585) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_8a1789a2948ca9bc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'The sacrifice involved when you choose a particular course of action is called?', '{"A":"Opportunity Cost","B":"Alternative","C":"Consumer Cost","D":"Producer Cost"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sacrifice involved when you choose a particular course of action is called "Opportunity Cost."It represents the value of the next-best alternative that is forgone or given up when a decision is made.', 0, 0, 0, 1790965661585) ON CONFLICT(id) DO NOTHING;
