INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_8ff1263c0f9eca90', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Aswan Dam is located is in?', '{"A":"Iran","B":"Iraq","C":"Egypt","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Aswan Dam was located in Aswan, Egypt.It was built across the Nile river.Additional information:It is one of the largest embankment dams in the world. Construction began on January 9, 1960.The dam was opened on July 21, 1970. Its maximum length is 550 km (340 mi).It has a height of 111 m (364 ft).Last verified on 02-02-2026', 0, 0, 0, 1790965661705) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_bfc2eaed5af99800', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Which city is called "Forbidden City"?', '{"A":"Beijing","B":"Lhasa","C":"Moscow","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Forbidden City is located in Beijing, China.It was the imperial palace of the Ming and Qing dynasties.It was built between 1406 and 1420 by the Yongle Emperor.The last emperor of China, Puyi, was expelled from the Forbidden City in 1925.It became a public museum in 1925.Last verified on 02-02-2026', 0, 0, 0, 1790965661705) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_5c0996716178a120', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'How many goals have been included in the Sustainable Development Goals?', '{"A":"17","B":"12","C":"15","D":"26"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There are 17 Sustainable Development Goals (SDGs).Established by the United Nations in 2015.Additional information:No PovertyZero HungerGood Health and Well-beingQuality EducationGender EqualityClean Water and SanitationAffordable and Clean EnergyDecent Work and Economic GrowthIndustry, Innovation, and InfrastructureReduced InequalitiesSustainable Cities and CommunitiesResponsible Consumption and ProductionClimate ActionLife Below WaterLife on LandPeace, Justice, and Strong InstitutionsPartnerships for the GoalsLast verified on 16-01-2026', 0, 0, 0, 1790965661705) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_d933fd5df5f8294f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'When was Osama bin Laden killed in Abbottabad?', '{"A":"August 2, 2008","B":"May 2, 2011","C":"September 11, 2001","D":"December 25, 2009"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Osama bin LadenAllegation: Pakistan was alleged to have provided support to Osama bin Laden.Death: He was killed by U.S. Navy SEALs on 2 May 2011.Location of Compound: Just half a mile from Pakistan Military Academy (PMA), Kakul, Abbottabad.U.S. Response: President Barack Obama requested Pakistan to investigate the network supporting bin Laden.Last verified on 28-01-2026', 0, 0, 0, 1790965661705) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_839a22cc09c4d4a1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'What does the term "Crypto Winter" mean?', '{"A":"A surge in cryptocurrency prices","B":"A period of stability in crypto markets","C":"A prolonged decline in cryptocurrency prices","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Crypto Winter” refers to a prolonged period of falling cryptocurrency prices.During this time, market values drop sharply, and investor confidence is low.Additional information:Examples: 2018 crypto crash after Bitcoin’s 2017 peak.Term is similar to a “bear market” in traditional finance.Last verified on 22-01-2026', 0, 0, 0, 1790965661705) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_7855453c1a935f40', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Our sweetest songs are those that tell us of saddest thoughts these words are attributed to?', '{"A":"Shelley","B":"Kets","C":"John Locke","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The famous line, "Our sweetest songs are those that tell of saddest thought," Poet: Percy Bysshe Shelley (1792–1822).A major English Romantic poet, suggesting that profound sorrow often inspires the most beautiful and moving art.', 0, 0, 0, 1790965661705) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_39fb40f569021954', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'What is the new name of Leningrad?', '{"A":"St.Petersburg","B":"New York","C":"Washington","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The new name of Leningrad is Saint Petersburg. In a referendum held in 1991The city of Saint Petersburg was founded by Tsar Peter the Great on 27 May 1703.It became the capital of the Russian Empire', 0, 0, 0, 1790965661705) ON CONFLICT(id) DO NOTHING;
