INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_3a9567c7aff0a40b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Which poet wrote the famous line "A thing of beauty is a joy forever"?', '{"A":"Byron","B":"Keats","C":"Shelley","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A thing of beauty is a joy forever: its loveliness increases; it will never pass into nothingness.This famous verse is from John Keats'' poem Endymion, emphasizing the everlasting joy and value of beautiful things.', 0, 0, 0, 1790965663519) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_fbf11bf19eb54865', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'What separates Asian part of Turkiye from its European part?', '{"A":"Strait of Gibraltar","B":"Strait of Hurmuz","C":"Strait of Bosporus","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The European and Asian parts of Turkey are separated by a series of waterways known as the Turkish Straits. This system includes: The Dardanelles Strait: Connects the Aegean Sea and the Sea of Marmara.The Sea of Marmara: An inland sea entirely within Turkey.The Bosphorus Strait: Connects the Sea of Marmara with the Black Sea and runs through Istanbul, dividing the city into its European and Asian sides.', 0, 0, 0, 1790965663519) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_453f23023a80f3fc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Where is Bathsheba Beach?', '{"A":"Barbados","B":"Greece","C":"Australia","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bathsheba Beach is located on the eastern coast of Barbados, a Caribbean island nation.It is known for its stunning natural beauty, .The beach is named after Queen Bathsheba, the wife of King David in the Bible.', 0, 0, 0, 1790965663519) ON CONFLICT(id) DO NOTHING;
