INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_1bdf616e9e266489', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'What is the length of Great Wall of China?', '{"A":"32400 km","B":"21600 km","C":"31200 km","D":"21,196 km"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Great Wall of China was built during the reign of Qin Shi Huang.He is the First Emperor who united China.Initially constructed around 221 BC.The wall was created as a defense against the Mongols.The length of the Ming Great Wall is 8,851 km (5,500 mi).The official total length of the Great Wall is 21,196 km (13,170 mi).', 0, 0, 0, 1790965663519) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_47698d38a20c4f6a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'The birthplace of the World Wide Web was____?', '{"A":"NASA","B":"Pentagon","C":"CERN","D":"Netscape"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation World Wide Web (WWW)World-Wide Web Worm (WWWW)English scientist Tim Berners-Lee invented the World Wide Web in 1989.WWW Birthplace CERN near Geneva, Switzerland.The browser was released to the general public in August 1991.', 0, 0, 0, 1790965663519) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_0169c956956ee568', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Which body of people is sometimes referred to as ‘The Fourth Estate’?', '{"A":"Judiciary","B":"The Press","C":"Executive","D":"Senate"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The press is referred to as "The Fourth Estate".Due to its role in influencing public opinion and holding other branches of government accountable.This role complements the functions of the judiciary, executive, and legislature, which are considered the three main estates of government.', 0, 0, 0, 1790965663519) ON CONFLICT(id) DO NOTHING;
