INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_d751ae224e706ec4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'The United Nation General Assembly shall do all of the following EXCEPT?', '{"A":"Consider and approve the budget of the organization","B":"Consider and approve any financial and budgetary arrangements with specialized agencies refereed to in Article 57 of the UN charter","C":"Contact the international donors to provide the donations for the organizations as provided in the articles","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The UN General Assembly (UNGA) is the main policy-making organ of the Organization. Comprising all Member States, it provides a unique forum for multilateral discussion of the full spectrum of international issues covered by the Charter of the United Nations.', 0, 0, 0, 1790965663881) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_49fe385dd690e534', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'As per Article 8 of the Statute of the International Court of Justice, The General Assembly and the Security Council shall proceed ______ to elect the members of the Court.', '{"A":"With mutual consensus","B":"Independently of one another","C":"In joint sitting","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Article 8 of the ICJ Statute provides that the General Assembly and Security Council elect judges independently.This ensures balance and prevents dominance of one organ over the election process.', 0, 0, 0, 1790965663881) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_24d9824663574938', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'How many Judges to the international Court of Justice are elected by The Security Council and the General Assembly for the term of 9 year?', '{"A":"35","B":"25","C":"15","D":"20"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Judges are in the International Court of Justice (ICJ): 15The tenure of a Judge of the ICJ is: 9 yearsIt was established in June 1945 Established by the Charter of the UNO ICJ began work in April 1946.The seat of the Court is at the Peace Palace in The Hague (Netherlands)As per Article 3(1) of the Statute of the International Court of Justice, the Court shall consist of 15 members, no two of whom may be the nationals of the same State.', 0, 0, 0, 1790965663881) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_f9ebe78f36a56fee', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'The atomic bomb was dropped on the city of Hiroshima on?', '{"A":"03 August 1945","B":"06 August 1945","C":"09 August 1945","D":"12 August 1945"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Little Boy type of bomb, was dropped on the Japanese city of Hiroshima on 6 August 1945 during World War II.The Fat Man was dropped on Nagasaki, Japan, on August 9, 1945, at 11:01 AM.Hiroshima deaths: around 40,000Nagasaki deaths: around 80,000**', 0, 0, 0, 1790965663881) ON CONFLICT(id) DO NOTHING;
