INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_4c9bd7aeb2450720', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'The famous book on statecraft "The Prince" was written by _____?', '{"A":"Plato","B":"Machiavelli","C":"Lord Macaulay","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Prince was written by Niccolò Machiavelli in 1513.A 16th-century political treatise by an Italian diplomat and political theorist.First published in 1532.', 0, 0, 0, 1790965665409) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_6926e07581ef7b36', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'The coastline of Afghanistan is ______ km.', '{"A":"600","B":"800","C":"0","D":"1000"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Afghanistan is a landlocked country and does not have a coastline.Afghanistan is located in Southern Asia.It is bordered by Pakistan, Iran, Turkmenistan, Uzbekistan, Tajikistan, and China.The nearest coast to Afghanistan is the Arabian Sea.It is about 300 miles (480 km) to the south.', 0, 0, 0, 1790965665409) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_d1128c8d75d62fca', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'What is ''Scotland Yard''?', '{"A":"London Police Headquarters","B":"A palace of the British Monarch in Scotland","C":"Royal Family Graveyard in the UK","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Scotland Yard, the headquarters of the London Metropolitan Police.By association, a name often used to denote that force.It is located on the River Thames at Victoria Embankment just north of Westminster Bridge in the City of Westminster.', 0, 0, 0, 1790965665409) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_d896d55d654ccae4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Scotland Yard is the Police Force of _____?', '{"A":"USA","B":"UK","C":"Scotland","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Scotland Yard is the headquarters of the Metropolitan Police Service of London, UK.By association, a name often used to denote that force.It is located on the River Thames at Victoria Embankment just north of Westminster Bridge in the City of Westminster.', 0, 0, 0, 1790965665409) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_02eed1a8f847abba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Salisbury is the old name of _____?', '{"A":"Khartoum","B":"Harare","C":"Nairobi","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Harare, formerly known as Salisbury, It is the capital and largest city of ZimbabweThe city was founded on 12 September 1890 by the Pioneer Column,Incorporated (city): 1935Renamed Harare: 18 April 1982It was named Fort Salisbury after the British Prime Minister Lord Salisbury.', 0, 0, 0, 1790965665409) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_5f16eaeb73a102a6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'The UN Security Council consists of _____?', '{"A":"5 members","B":"11 members","C":"15 members","D":"20 members"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Security Council has 15 members:Five everlasting members with veto power:ChinaFranceRussian Federationunited kingdom of remarkable Britain and northerly irelandUSA10 non-permanent contributors, Five of them are elected every year by using the overall assembly for a two-year term at firstSet the sample for geographic representation as follows:five from African and Asian States1 from japanese eu States2 from Latin American States2 from Western ecu and other States', 0, 0, 0, 1790965665409) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_ae6b9ddca9ecd97b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Which was the last battle of Napoleon?', '{"A":"Battle of Leipzig","B":"Battle of Waterloo","C":"Battle of Austerliz","D":"Battle of Trafalgar","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Napoleon was defeated in the Battle of Waterloo.The Battle of Waterloo was fought on 18 June 1815.The battle was fought between Napoleon''s French Army and a coalition led by the Duke of Wellington and Marshal Blücher.Battle of Waterloo resulted in:End of the Seventh Coalition Final Defeat of NapoleonENd of the Napoleonic War.Additional information:Napoleon Bonaparte was the Emperor of the French.He ruled France twice.The first reign was from 1804 to 1814The second reign was in 1815.He fought more than 70 battles 5', 0, 0, 0, 1790965665409) ON CONFLICT(id) DO NOTHING;
