INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_94369316a84c17a6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', '"Ottawa convention 1997" is related to ______?', '{"A":"Environment protection","B":"Preserving wild life","C":"Banning land mines","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Ottawa Convention 1997" is related to Banning land mines.The Ottawa Treaty prohibits the development and production of anti-personnel mines.It was accepted in Oslo on 18 September 1997.History:In October 1996, at the first Ottawa Conference, Canadian Minister of Foreign Affairs Lloyd Axworthy launched the Ottawa Process, which led to the ratification of the Mine Ban Treatysigned by 122 countriesat the Second Ottawa Conference in December 1997.', 0, 0, 0, 1790965665551) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_9cadb62faed05eba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Greenwich, a city of London, is famous for ______?', '{"A":"Beautiful garden","B":"Calculating the time of all the countries","C":"Country","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Greenwich is famous for its calculating the time of all the countries.Greenwich is an area in south-east London, EnglandIt lies on the south bank of the River Thames in the historic county of Kent.It is famous for the Prime Meridian (0° longitude).Greenwich is famous for calculating the time for all countries.The Greenwich meridian, also known as the prime meridian, passes through the following countries:EnglandFranceSpainAlgeriaMaliBurkina FasoTogoGhana Antarctica', 0, 0, 0, 1790965665551) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_92d0baf8e5e7f56c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Great Bear is a _____?', '{"A":"Lake","B":"Monument","C":"Historical place","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Great Bear Lake is the largest lake entirely in Canada.It is the fourth-largest in North America.It is located in the Northwest Territories.It is known for its pristine waters and natural beauty.', 0, 0, 0, 1790965665551) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_6560ff53bc89713e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'The atomic bomb on Nagasaki was dropped on which date?', '{"A":"12 August 1945","B":"6 August 1945","C":"9 August 1945","D":"12 August 1943"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Fat Man was dropped on Nagasaki, Japan, on August 9, 1945, at 11:01 AM.The atomic bomb pm Nagasaki was dropped on 9 August 1945.** The United States detonated two atomic bombs over the Japanese cities of Hiroshima and Nagasaki On August 9, 1945. The two bombings killed between 129,000 and 226,000 people“Fat Man” dropped an atomic bomb at 11:02 that morning.Little Boy was the name of the Atomic Bomb dropped on the city of Hiroshima.**', 0, 0, 0, 1790965665551) ON CONFLICT(id) DO NOTHING;
