INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_7348a7998135623b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Violating International Law, Israel has constructed a concrete wall to divide the Palestinians in _______?', '{"A":"Golden Heights","B":"Gaza","C":"West Bank","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The wall spans 708 km in the West Bank.85% of the wall runs inside Palestinian territory.It isolates 9% of the land and impacts 25,000 Palestinians.', 0, 0, 0, 1790965665647) ON CONFLICT(id) DO NOTHING;
