INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_edc929e4a4c203f2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Which of the following is the main reason of Tsunami?', '{"A":"Wind Storm","B":"Earthquake","C":"Storm in the sea","D":"Hall Storm"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A tsunami is a series of powerful sea waves.It typically caused by underwater earthquakes or volcanic eruptions.It leading to coastal flooding.', 0, 0, 0, 1790965665647) ON CONFLICT(id) DO NOTHING;
