INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_01de1e465f16b2d0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Ricky Ponting was the captain of _____?', '{"A":"Australia","B":"South Africa","C":"England","D":"New Zealand"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ricky Ponting was captain of the Australian national team during its "golden era", between 2004 and 2011 in Test cricketand 2002 and 2011 in One Day Internationals (ODIs)Ricky Ponting played 168 Tests for Australia Ricky Ponting is the most successful captain in international cricket history, with 220 victories in 324 matches with a winning rate of 67.91%.******ND30-12-2022', 0, 0, 0, 1790965666631) ON CONFLICT(id) DO NOTHING;
