INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_23f8db72eabd7469', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Von Thunen Model of agriculture was presented in _____?', '{"A":"1526","B":"1626","C":"1726","D":"1826"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Von Thünen model explains agricultural land use patterns based on distance from a central market.Johann Heinrich von Thünen developed it, and it was first published in 1826.', 0, 0, 0, 1790965666781) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_f9e4b96248831fbb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Which calendar was introduced by famous astronomer Omer Khayyam?', '{"A":"Jalali Calendar","B":"Chess","C":"Pin hole camera","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Omer-Khayam was born in Iran in 1048 AD.Omer-Khayam was a poet, Mathematician & Astronomer. Omer-Khayam introduced the modern Solar Hijri calendar, the Jalali calendar.Place of burial: Tomb of Omar Khayyam, IranMain interests:Mathematics (medieval Islamic); astronomy; Persian philosophy; Persian poetryND11-07-2023*****RY 4-12-2022', 0, 0, 0, 1790965666782) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_233b7a64b6bc37a2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'A line on a map joining places of equal rainfall is called an _____?', '{"A":"Isotherm","B":"Isohyet","C":"Isobar","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Isohyet is a line drawn on a map connecting points that receive equal amounts of rainfall in a given period. A map with isohyets is called an isohyetal map.', 0, 0, 0, 1790965666782) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_ba5d32dcb72e17a2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'What is BREXIT?', '{"A":"The UK Withdrawal from the European Union","B":"Name of English Medicine","C":"The British Policy of Non-International","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The United Kingdom voted to leave the EU in a national referendum in June 2016,and left in 2020.The United Kingdom left the European Union on 31 January 2020, at midnight (Dutch time).Theresa May was prime minister at the Time of BrexitBrexit is the withdrawal of the United Kingdom (UK) from the European Union (EU) and the European Atomic Energy Community (EAEC) .The UK is to date the first and only country to formally leave the EU after 47 years of membership.', 0, 0, 0, 1790965666782) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_fe8d7a9073ae68ab', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'The real name of Ibn e Tamiyyah is ______?', '{"A":"Zaki ud din","B":"Taqi ud din","C":"Naqi ud din","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The real name of Ibn Taymiyyah is Taqi ud din Abu''l-Abbas Ahmad ibn Abd al-Halim ibn Abd as-Salam al-Najdi al-Harrani.He was a renowned Islamic scholar, theologian, and reformer who lived from 1263 to 1328 CE.', 0, 0, 0, 1790965666782) ON CONFLICT(id) DO NOTHING;
