INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_5eaf5e78c02966d1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Which region of the world was declared "Free of Wild Polio" on 25th August 2020?', '{"A":"Africa","B":"South Asia","C":"East Asia","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Africa is free from wild poliovirus, the World Health Organization (WHO) announced on 25 August By 2020, all three strains of the wild poliovirus (type 1, type 2, and type 3) have been eradicated in Africa.In 2020 two countries where the virus remains endemic, are Afghanistan and Pakistan.whileType 2 wild poliovirus was declared eradicated in September 2015. ND27-7-2023', 0, 0, 0, 1790965667087) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_47f69691677ecff0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'The book always has _____?', '{"A":"Page","B":"Ink","C":"Paper","D":"Story"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The logic is:1) Ink → Ink is related to pen 2) Page → The book always has page3) Paper → Paper is related to the tree.4) Story → Story is related to literature.', 0, 0, 0, 1790965667087) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_94a5de3b893f191a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'The main export of Saudi Arabia is _____?', '{"A":"Crude oil","B":"Natural gas","C":"Dates","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Saudi Arabia is the world''s largest exporter of crude oil.It is the backbone of its economy.Saudi Arabia imports machinery and equipment to support industrial growth and infrastructure development.', 0, 0, 0, 1790965667331) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_3b885c7fdc189368', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Which of the following presidents of America abolished slavery?', '{"A":"Abraham Lincoln","B":"Thomas Jefferson","C":"George Washington","D":"Stanley Jackson"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The United States criminalized the international slave trade: 1808Slavery was made unconstitutional: 1865Note: American Civil War started in 1861 and ended in 1865.', 0, 0, 0, 1790965667331) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_cc8e4bd711be7fc6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Slavery was abolished in America in the which year?', '{"A":"1861","B":"1865","C":"1808","D":"1898"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The United States criminalized the international slave trade in 1808.Slavery was made unconstitutional in 1865, following the American Civil War.It lasted from 1861 to 1865.', 0, 0, 0, 1790965667331) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_8c3a51effaf43166', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'In June 1948, under Soviet Union influence, Germany built a wall between East and West Germany?', '{"A":"To divide Berlin into two parts","B":"To stop their citizens from escaping to the west","C":"Both A and B","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In June 1948, the Soviet Union, under the leadership of Joseph Stalin, blocked the Western Allies'' access to Berlin.It was deep within the Soviet-occupied zone of Germany.In response, the Western Allies organized the Berlin Airlift to supply the city.However, it was in 1961, under the leadership of Nikita Khrushchev, that the Soviet Union built the Berlin Wall to:Divide Berlin into two parts (East Berlin and West Berlin)Stop East German citizens from escaping to the West', 0, 0, 0, 1790965667332) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_a9d7f93ace1361be', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'In the early period which endemic is called black death?', '{"A":"Sars","B":"Liporasy","C":"Plague","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the early period, the endemic known as the "Black Death" is the plague.The plague is a pandemic disease that devastated Europe in the 14th century, killing an estimated 75 to 200 million people, approximately 30-60% of Europe''s population.', 0, 0, 0, 1790965667332) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_9100688d03cc86a3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'When Switzerland got the status of neutral state?', '{"A":"1800","B":"1810","C":"1815","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Switzerland gained the status of a neutral state in 1815, at the Congress of Vienna, which was held after the Napoleonic Wars.The Congress of Vienna recognized Switzerland''s independence and sovereignty, and established its permanent neutrality.', 0, 0, 0, 1790965667332) ON CONFLICT(id) DO NOTHING;
