INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_aba68bc78131f317', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'Pakistan and China established diplomatic relations on _____?', '{"A":"21 May 1951","B":"21 May 1950","C":"21 May 1952","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan becomes the third non-communist country, and first Muslim one, to recognize the People''s Republic of China. In 1951 Beijing and Karachi establish diplomatic relations.Pakistan and China established diplomatic relations on May 21, 1951.This marked the beginning of a strong bilateral relationship.The partnership has grown in various sectors, including trade, defense, and cultural exchange.', 0, 0, 0, 1790965667652) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_844fd9b2bbadea48', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'The word ''Monsoon'' has originated from which language?', '{"A":"English language","B":"Persian Language","C":"Arabic Language","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The word ''Monsoon'' has originated from Arabic Language.The word “monsoon” is derived from the Arabic word mausim, which means season.Monsoon means برسات کا موسم****', 0, 0, 0, 1790965667652) ON CONFLICT(id) DO NOTHING;
