INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_8dabf6c235425ecd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_general', 'The Human Security Network has _______ members .', '{"A":"9","B":"12","C":"15","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Human Security Network (HSN) is a group of countries that share a common interest in promoting human security.It is a people-centered approach to security that focuses on protecting individuals and communities from threats such as conflict, poverty, and natural disasters.The HSN was established in 1998 and currently has 12 member countries:1. Austria2. Canada3. Chile4. Costa Rica5. Greece6. Ireland7. Jordan8. Liechtenstein9. Mali10. Norway11. Slovenia12. Switzerland', 0, 0, 0, 1790965667754) ON CONFLICT(id) DO NOTHING;
