INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_6e3e141a6fff7ba7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'AFP is the news agency of which country?', '{"A":"France","B":"UK","C":"USA","D":"Spain"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Agence France-Presse (AFP) is a French international news agency.Headquarters: Paris, FranceFounder: Charles-Louis HavasFounded: 1835, Paris, FranceIt is the world''s oldest news agency. AFP has regional headquarters in:NicosiaMontevideoHong KongWashingtonLast verified on 26-05-2026', 0, 0, 0, 1790965673356) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_38bc8d25d83f5ee6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which continent has no permanent human residence?', '{"A":"Asia","B":"Antarctica","C":"Europe","D":"Australia"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Antarctica is the only continent without a permanent human population.People live there temporarily, mainly for scientific research.Additional information:Antarctica is located around the South Pole.It is the coldest, driest, and windiest continent on Earth.The Antarctic Treaty was signed in 1959 and entered into force in 1961.Last verified on 27-09-2026', 0, 0, 0, 1790965673356) ON CONFLICT(id) DO NOTHING;
