INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_3005eba422db6bb6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Nelson Mandela was the President of which country?', '{"A":"Nigeria","B":"South Africa","C":"Sudan","D":"Congo"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nelson Mandela became the first Black President of South Africa on 10 May 1994.He served as president until 1999.He was imprisoned in 1962.He spent 27 years in prison.Nelson Mandela International Day is celebrated on 18 July.He died on 5 December 2013.Last verified on 03-06-2026', 0, 0, 0, 1790965673356) ON CONFLICT(id) DO NOTHING;
