INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_2b930a5be6153a67', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Qantas is an airline of which country?', '{"A":"Saudi Arabia","B":"Australia","C":"UAE","D":"Malaysia"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Country: AustraliaFounded: 16 November 1920Headquarters: Mascot, New South Wales, AustraliaFirst International Passenger Flight: May 1935Full Name: Qantas Airways Limited (Originally: Queensland and Northern Territory Aerial Services)Additional information:Emirates → United Arab Emirates (UAE)Saudia → Saudi ArabiaMalaysia Airlines → MalaysiaPakistan International Airlines (PIA) → PakistanLast verified on 21-07-2026', 0, 0, 0, 1790965674174) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_a1ef76b3737dfddb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Caspian Sea, Red Sea and Aral Sea are actually?', '{"A":"Rivers","B":"Lakes","C":"Canals","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Caspian Sea, Red Sea and Aral Sea are actually lakes.The Caspian Sea and Aral Sea are actually endorheic (inland) salt lakes.They are called “seas” due to their large size and historical naming.Additional information:The Caspian Sea lies between Europe and Asia.The Aral Sea has drastically shrunk due to river diversion for irrigation.The Red Sea connects to the Indian Ocean via the Gulf of Aden.Last verified on 06-07-2026', 0, 0, 0, 1790965674174) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_a73b79ded03e6ebf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which of the following countries first introduced (invented) paper currency (banknotes) in the world?', '{"A":"China","B":"USA","C":"Greece","D":"France"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Country: ChinaFirst use: 806 AD (approx.)Early name: Feiqian (Flying Money)Dynasty: Tang Dynasty → Song Dynasty (official issue)Importance: First-ever paper-based monetary systemLast verified on 11-06-2026', 0, 0, 0, 1790965674174) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_84a09879ef62c7d3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which strait separates Asia from North America?', '{"A":"Bering Strait","B":"Strait of Hormuz","C":"Bosporus Strait","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Name: Bering StraitLocation: Between Russia and AlaskaConnected seas: Arctic Ocean & Pacific OceanWidth: ~85 kmImportant islands: Diomede Islands lie in the middleLast verified on 16-05-2026', 0, 0, 0, 1790965674174) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_82a387991aba53a7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which country is known as “Land of Rising Sun”?', '{"A":"Russia","B":"Canada","C":"Korea","D":"Japan"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Japan is known as the "Land of the Rising Sun."In Japanese, Nihon (日本) or Nippon means "Origin of the Sun" or "Sun''s Origin."The name reflects Japan''s location east of China, where the sun appears to rise.Japan is an island country in East Asia.It is located in the northwestern Pacific Ocean.Additional information:Capital: TokyoCurrency: Japanese Yen (JPY)Official Language: JapaneseContinent: AsiaParliament: The National Diet (Diet)National Animal: Japanese Macaque (Snow Monkey)Last verified on 09-07-2026', 0, 0, 0, 1790965674174) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_6ce2fb630d021378', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'River Nile originates (primary source) from ______?', '{"A":"Lake Victoria","B":"Cherangani Hills","C":"Lake Nyasa","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Nile River originates mainly from Lake Victoria (White Nile).It has two main tributaries: White Nile and Blue Nile.The Blue Nile starts from Lake Tana.Both rivers meet at Khartoum (Sudan).Additional information:Total Length: ~6,650 kmOutflow: Mediterranean SeaThe Nile is the longest river in the world.Egypt is called the “Gift of the Nile” because it depends heavily on it.Last verified on 31-03-2026', 0, 0, 0, 1790965674174) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_e0a3cfefae6e4c44', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'The longest river in Europe is?', '{"A":"Amazon River","B":"Danube River","C":"Volga River","D":"Ural River"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Volga River is the longest river in Europe, It is with a length of approximately 3,531 km (2,194 miles).It flows entirely through Russia and empties into the Caspian Sea.Additional information:Danube – 2,857 km (Flows through 10 countries)Ural – 2,428 km (Russia & Kazakhstan)Dnieper – 2,201 km (Russia, Belarus & Ukraine)Don – 1,950 km (Russia)Last verified on 20-07-2026', 0, 0, 0, 1790965674174) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_d211d67fc254331c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which country has the largest reserves of Oil?', '{"A":"Qatar","B":"Russia","C":"Saudi Arabia","D":"Venezuela"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Venezuela has the largest proven oil reserves in the world.Additional information:Venezuela – ~303 billion barrelsSaudi Arabia – ~267 billion barrelsIran – ~209 billion barrelsCanada – ~163 billion barrelsIraq – ~145 billion barrelsLast verified on 20-07-2026', 0, 0, 0, 1790965674247) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_b653ea7a0152ebce', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'The country which leads in the production of rubber is?', '{"A":"China","B":"Thailand","C":"Indonesia","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Thailand is the world''s leading producer of natural rubber.Rubber is mainly used in the tyre, automobile, and manufacturing industries.Additional information:Top 5 Natural Rubber Producing Countries:ThailandIndonesiaChinaIndiaVietnamLast verified on 03-07-2026', 0, 0, 0, 1790965674247) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_7067dac21bafdea9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Great Victoria Desert is located in which country?', '{"A":"China","B":"Australia","C":"Sudan","D":"New Zealand"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Location: Southern Australia.States: Western Australia and South Australia.Area: About 348,750 km².Features: Sand dunes, grasslands, salt lakes, and an arid climate.Additional information:Great Sandy Desert – AustraliaGibson Desert – AustraliaSimpson Desert – AustraliaTanami Desert – AustraliaLast verified on 20-07-2026', 0, 0, 0, 1790965674247) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_9de1ae81a52bbe00', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'The country Panama is situated in _____?', '{"A":"North America","B":"Central America","C":"South America","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Location: Central America (Isthmus of Panama).Connects: North America and South America.Borders: Costa Rica (west) and Colombia (southeast).Famous For: Panama Canal, connecting the Atlantic Ocean (Caribbean Sea) and the Pacific Ocean.Additional information:Panama Canal construction started: 4 May 1904.Panama Canal officially opened: 15 August 1914Length of the Panama Canal: Approximately 82 km (51 miles).Last verified on 20-07-2026', 0, 0, 0, 1790965674247) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_bbd6e76f73457151', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which of following is not a member of G-7 countries? Japan, Russia, Italy, France', '{"A":"Japan","B":"Russia","C":"Italy","D":"France"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Russia is not a member of the G7.It joined in 1998, forming the G8.But its membership was suspended in 2014 after the annexation of Crimea.Additional information:The Group of Seven (G7) consists of Canada, France, Germany, Italy, Japan, the United Kingdom, and the United States.Founded: 1975 (initially as the G6; Canada joined in 1976 to form the G7).Purpose: To promote cooperation on global economic, political, and security issues among the world''s major advanced economies.Last verified on 20-07-2026', 0, 0, 0, 1790965674247) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_016ccd21cce6d523', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which of the following is the latest country to abolish monarchy?', '{"A":"Nepal","B":"Laos","C":"Afghanistan","D":"Barbados"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The latest country to abolish its monarchy is Barbados.Date: November 30, 2021Legislation: Constitution (Amendment) (No. 2) Act, 2021New Office: President of BarbadosLast Monarch: Queen Elizabeth IIAdditional informationNepal: Abolished monarchy in 2008.Mauritius: Abolished monarchy in 1992.Fiji: Abolished monarchy in 1987.Last updated 18-07-2026 by NA', 0, 0, 0, 1790965674247) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_12f3cd7e187657bf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'The capital of Nepal is _____?', '{"A":"Thimphu","B":"Kathmandu","C":"Dhaka","D":"Tokyo"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The capital of Nepal is Kathmandu,Founded by: ManjushriAdditional informationNepal''s currency is the Nepalese Rupee.The official language is Nepali.Located is in Continent Asia.Primary Religion is Hindu, Buddhism, Islam.Parliament called Federal Parliament of Nepal.Tricks for RememberRUPEEMind Tricks : PICS of MN***PICS***P - PakistanI - IndiaC - CeylonS - Srilanka**MN**M - MaritiusN - Nepal درالحکومت اور کرنسی کے بارے سولات ضرور پوچھے جاتے۔ ان کو ضرور پڑھ کر جائیںClick here RK20-11-22', 0, 0, 0, 1790965674247) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_7dd7da5942eb074a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Mount Kinabalu is located in _____?', '{"A":"Malaysia","B":"Kenya","C":"Botswana","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mount Kinabalu is located in Sabah, Malaysia,On the island of Borneo.Elevation: 4,095 m (13,435 ft)It is the third-highest peak of an island on EarthThe 28th-highest peak in Southeast AsiaLast updated 18-07-2026 by NA', 0, 0, 0, 1790965674247) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_a747232b23faa201', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Baglihar Dam is constructed by India on over which river?', '{"A":"Sutlej","B":"Ravi","C":"Jhelum","D":"Chenab"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Baglihar Dam is a hydroelectric project constructed by India.It is built on the Chenab River in Jammu and Kashmir.The project was planned in 1992 and approved in 1996.Construction began in 1999 and the dam was completed in phases.Commissioning:Stage I: 2008–2009Stage II: 2015–2016Estimated Cost: Around US$1 billionLast verified on 16-05-2026', 0, 0, 0, 1790965674303) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_44f297d80a4c9e27', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'What is the Capital of Ethiopia?', '{"A":"Addis Ababa","B":"Berlin","C":"Libreville","D":"Conakry"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ethiopia Capital is Addis Ababa.Ethiopia Currency is Birr.Ethiopia official language is Amharic.Ethiopia located is in Continent Africa.Ethiopia Primary Religion is Islam, Christianity.Ethiopia Parliament called Federal Council And House Of Representative.Last verified on 07-06-2026', 0, 0, 0, 1790965674303) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_f8dbb74f6606210b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which country is called the ''Land of Golden Fiber''?', '{"A":"Bangladesh","B":"India","C":"China","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bangladesh is known as the "Land of Golden Fiber".Because of its large-scale production of jute.Jute is the country''s main cash crop.It is called the Golden Fiber due to its golden color and economic importance.Bangladesh is located in South Asia.Last verified on 06-07-2026', 0, 0, 0, 1790965674303) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_dcbe016344d9f68c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which country is called Land of Thousand Lakes?', '{"A":"Indonesia","B":"Maldives","C":"Finland","D":"Iceland"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Finland is called the "Land of a Thousand Lakes".Because it has over 188,000 lakes.It covering about 10% of its land area.It is a Nordic country located in Northern Europe.Additional information:Land of the Rising Sun: JapanLand of the Midnight Sun: NorwayLand of Fire and Ice: IcelandLand of White Elephant: ThailandLast verified on 03-07-2026', 0, 0, 0, 1790965674303) ON CONFLICT(id) DO NOTHING;
