INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_a4a34c6143dcf1bd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Nippon is the former name of which country?', '{"A":"Japan","B":"Finland","C":"Indonesia","D":"Brazil"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nippon is the former name for Japan. It translates to "origin of the sun" Located in Asia.Japan is also called the Land of the Rising Sun. The yen is the currency of Japan.The official language is Japanese.The capital of Japan is Tokyo. Parliament is called the Diet.Last updated 17 july 2026 by NA', 0, 0, 0, 1790965674303) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_b51012c7a3c859d1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which country hosted the first-ever Asian Games?', '{"A":"China","B":"Pakistan","C":"India","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation India hosted the first-ever Asian Games in 1951.The Games were held in New Delhi from 4–11 March 1951.The Asian Games are organized every four years.They are the largest multi-sport event in Asia.The official motto of the Asian Games is "Ever Onward."Last verified on 17-07-2026', 0, 0, 0, 1790965674303) ON CONFLICT(id) DO NOTHING;
