INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_663a712574c5c5c2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which is the largest natural fresh water lake of Pakistan?', '{"A":"Kaghan Lake","B":"Satpara Lake","C":"Manchhar Lake","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Manchhar Lake is the largest natural freshwater lake in Jamshoro Sindh Pakistan.It collects water from the Kithar mountain range.It is one of South Asia''s largest.It covers an area of 23.5 km (14.6 mi)It is the part of Indus River basin.Last verified on 31-03-2026', 0, 0, 0, 1790965674909) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_0f1c4bc39ab3e533', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'The Sahara is a desert located on the ____ continent.', '{"A":"Asian","B":"African","C":"Australian","D":"All of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Sahara is a desert on the African continent.It is the largest hot desert in the world.Area: 9.2 million km²Length: 4,800 km (3,000 mi)Width: 1,800 kmLast verified on 11-06-2026', 0, 0, 0, 1790965674909) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_1bf1a63bbf48a571', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Mohenjo-Daro is located in which district of Sindh?', '{"A":"Dadu District","B":"Larkana District","C":"Hyderabad District","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mohenjo-Daro is located in the Larkana district of Sindh.Mohenjo Daro means Mound of the Dead.It was discovered in 1922 by R. D. Banerji.It is a 4000-year-old city of the Indus Civilization.It was built around 2500 BC.Last verified on 11-06-2026', 0, 0, 0, 1790965675012) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_175842175a173a18', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Peso is the currency of which country? Argentina, Spain, Italy, Both A and B', '{"A":"Argentina","B":"Spain","C":"Italy","D":"Both A and B"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Peso is the currency of Argentina and the Philippines.The term “peso” originally means “weight” in Spanish.Additional information:Countries Using Peso:ChileColombiaCubaDominican RepublicMexicoUruguayLast verified on 11-06-2026', 0, 0, 0, 1790965675012) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_95de42abde695d90', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which of the following is the largest river of the world?', '{"A":"Yangtze","B":"Congo","C":"Nile","D":"Amazon"}', 'D', NULL, 0, 0, 0, 1790965675012) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_4dce7435f1462815', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'The second highest plateau of world located in Pakistan is?', '{"A":"Tibetan Plateau","B":"Potwar Plateau","C":"Deosai Plains","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The second highest plateau in the world located in Pakistan is the Deosai Plains.Location: Gilgit-Baltistan, PakistanHeight: ~4,114 meters above sea levelArea: Around 3,000+ square kilometersFamous river/lake: Sheosar LakeStatus: Deosai National ParkIt is known as the “Land of Giants” due to its high altitude and unique landscape.Additional information:The highest plateau in the world is the Tibetan Plateau.Last verified on 09-06-2026', 0, 0, 0, 1790965675012) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_d029bd4e81524033', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which country is called the Land of Thunder Dragon?', '{"A":"Nepal","B":"Sri Lanka","C":"Bhutan","D":"Bangladesh"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bhutan is called the “Land of the Thunder Dragon”.Its local name is Druk Yul.It is a small Himalayan country in South Asia.The name comes from stormy Himalayan thunder sounds.It is a peaceful and mountainous country.Last verified on 06-06-2026', 0, 0, 0, 1790965675012) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_b60c1ca556259911', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Angel Falls is the world''s tallest waterfalls, located in which country?', '{"A":"Canada","B":"Russia","C":"Venezuela","D":"Mexico"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Angel Falls is a waterfall in Venezuela.Height: 979 mElevation: 1,283 mLongest drop: 807 mNumber of drops: 2 It is the world''s tallest uninterrupted waterfall.The waterfall has been known as Angel Falls since the mid-20th century.Angel Falls is named after Jimmie Angel, a U.S. aviator, who was the first person to fly over the falls.Last verified on 06-06-2026', 0, 0, 0, 1790965675012) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_a1d9a0d7a16a7bf0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Greenwich is located in ____?', '{"A":"France","B":"Finland","C":"Germany","D":"England"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Greenwich is an area in south-east London, England.It lies on the south bank of the River Thames in the historic county of Kent.It is famous for the Prime Meridian (0° longitude).It is used as the reference for Greenwich Mean Time (GMT).It is famous for calculating the time for all countries.The Greenwich meridian, also known as the prime meridian, passes through the following countries:EnglandFranceSpainAlgeriaMaliBurkina FasoTogoGhana AntarcticaLast verified on 31-03-2026', 0, 0, 0, 1790965675012) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_cfde07e14962bf14', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Belgrade is a capital of ____?', '{"A":"Serbia (Yugoslavia)","B":"UK","C":"Chilli","D":"Switzerland"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Serbia Capital is Belgrade.Serbia Currency is Serbian Dinar.Serbia official language is Serbian.Serbia located is in Continent Europe.Serbia Primary Religion is Christianity.Serbia Head of Govt. is Prime Minister – Ana Brnabić.Serbia Parliament called .Tricks for RememberDINAR K-S in J-A-I-L**K-S**K-KuwaitS-Sudan**J-A-I-L***J-JordenA-AlgeriaI-IraqL-Libya Last verified on 30-05-2026', 0, 0, 0, 1790965675012) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_ac2633d667032bc6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'The major river of the Egypt is?', '{"A":"Euphrates","B":"Nile","C":"Niger","D":"Limpopo"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The main rivers in Egypt are the Nile River and its tributaries.The Nile is the longest river in the world at 6,650 km.It is located in Northeast Africa.It is the only river that flows from south to north.Last verified on 29-05-2026', 0, 0, 0, 1790965675109) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_43e240d51dc8e4fb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which of the following is not a country? Iceland, Greenland, New Zealand, Finland', '{"A":"Iceland","B":"Greenland","C":"New Zealand","D":"Finland"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Greenland is the world''s largest island.It is an autonomous country within the Kingdom of Denmark.It is geographically a part of the North American continent.It has been politically and culturally associated with Europe for about a millennium.Last verified on 26-05-2026', 0, 0, 0, 1790965675109) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_a2c8b61ef8278ebe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which of the following is a landlocked country? Uganda, Hungry, Kenya, Both A and', '{"A":"Uganda","B":"Hungry","C":"Kenya","D":"Both A and B"}', 'D', NULL, 0, 0, 0, 1790965675109) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_3046e83e741458b7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', '“Dasht-e-Lut” desert is located in _____?', '{"A":"Iran","B":"Iraq","C":"Libya","D":"China"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dasht-e Lut is located in southeastern Iran.It lies mainly in the provinces of Kerman and Sistan & Balochistan (Iran).Area: 51,800 km²Length: 480 km (approx.)Rank: 33rd largest desert in the worldUNESCO listing: 17 July 2016Last verified on 02-05-2026', 0, 0, 0, 1790965675109) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_b36730afb6c3103e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', '"Tenge" is the currency of which country?', '{"A":"Malaysia","B":"New Zealand","C":"USA","D":"Kazakhstan"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tenge is the currency of Kazakhstan.It''s capital is Astana.Official language is Kazakh and Russian.Located in Continent Asia/Europe.Primary religion is Islam and Christianity.Additional information:The ringgit is the currency of Malaysia.New Zealand Dollar is the currency of New Zealand.US Dollar is the currency of the USA.Last verified on 17-05-2026', 0, 0, 0, 1790965675109) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_eccb5a000db51c84', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which city is situated on the bank of Tigris River?', '{"A":"Damascus","B":"Beirut","C":"Riyadh","D":"Baghdad"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Baghdad is the city situated on the bank of the Tigris River in Iraq.It is the capital of Iraq.Founded by Caliph Al-Mansur in 762 CE.It was known as the “City of Peace” (Madinat al-Salam).It became a major center of learning during the Abbasid Caliphate.Today, it is one of the largest cities in the Arab world.Last verified on 16-05-2026', 0, 0, 0, 1790965675109) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_b97f529cded57fce', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which of the following river passes the Equator twice?', '{"A":"Congo","B":"Nile","C":"Amazon","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The main tributary, the Congo River has a total length of 4,370 km.It is the only major river to cross the equator twice.It is the Second longest river in Africa.Last verified on 16-05-2026', 0, 0, 0, 1790965675109) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_cea32eb4d5557e81', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which is the fourth largest country in the world in population?', '{"A":"China","B":"USA","C":"India","D":"Indonesia"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Indonesia is the fourth-largest country in the world in population at 277,534,122 people.It is the world''s largest island group with more than 17,000 islands.Indonesia''s population is equivalent to 3.45% of the total world population.Top 5 countries by populationCountryPopulationIndia1,428,627,663 China1,425,671,352 US339,996,563 Indonesia277,534,122 Pakistan240,485,658 Last verified on 16-05-2026', 0, 0, 0, 1790965675109) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_58d5253b778e7c5d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'The only fertile desert in the world is__________?', '{"A":"Sahara Desert","B":"Dasht -e Lut Desert","C":"Great Thar Desert","D":"Chihuahuan Desert"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The only fertile desert in the world is the Tharparkar Desert, Located in Sindh, Pakistan. Known as the world''s 18th-largest desert, It is deemed "fertile" because, unlike typical arid deserts,Around 85% of the desert is in India, while the remaining part is in SindhLast updated question by NS on 11 May 2026', 0, 0, 0, 1790965675180) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_d1075d4f6f9db753', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Bosphorus strait connects the Black Sea with _____?', '{"A":"Aegean Sea","B":"Red Sea","C":"Rose Sea","D":"Marmara Sea"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Bosphorus Strait is a narrow natural waterway in Turkey.It connects the Black Sea with the Sea of Marmara.It is the forming part of the boundary between Europe and Asia.Strategically important for international shipping and naval routes.Additional information:Length: ~30 kmWidth: 700 m – 3.7 kmMaximum depth: ~110 mNumber of bridges across: 3Number of tunnels (undersea): 2Last verified on 12-03-2026', 0, 0, 0, 1790965675180) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_673a8323c4476e9a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'How many countries have a border with the Black Sea?', '{"A":"8","B":"6","C":"5","D":"4"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Six countries have a border with the Black Sea.These countries are:TurkeyBulgariaRomaniaUkraineRussiaGeorgiaAdditional information:The Bosphorus Strait is a narrow natural waterway in Turkey.It connects the Black Sea with the Sea of Marmara.It is the forming part of the boundary between Europe and Asia.Last verified on 10-05-2026', 0, 0, 0, 1790965675180) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_d6a094632464ada7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which country is called the Land of Flowers?', '{"A":"Netherlands","B":"Holland","C":"Indonesia","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Netherlands is widely known as the "Land of Flowers." Due to its massive flower industry, expansive tulip fieldsPeshawar: Historically known as the "City of Flowers".It was known as Pushapura, a Sanskrit term for the city of flowersAdditional information Manchester of Pakistan. Faisalabad.Gateway of Pakistan. Karachi.Brasilia of Pakistan. Islamabad.Land of Flowers, Netherlands .City of Textiles. Faisalabad. Last updated by NS on 06 May 2026', 0, 0, 0, 1790965675180) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_af53dc7aefcd1845', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Copenhagen is the capital of?', '{"A":"Belgium","B":"Denmark","C":"France","D":"Canada"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Denmark Capital is Copenhagen.Denmark Currency is Danish Krone.Denmark official language is Danish.Denmark located is in Continent Europe.Denmark Primary Religion is Christianity.Denmark Head of Govt. is Prime Minister – Mette Frederiksen.Denmark Parliament called Folketing.Last verified on 03-05-2026', 0, 0, 0, 1790965675180) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_03d1f985f10b0fa7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'The cold and dense downslope mountain wind is termed as?', '{"A":"Katabatic Trade","B":"Anabatic","C":"Katabatic","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Katabatic wind is a cold, dense wind that flows downhill due to gravity.It forms when air over highlands becomes very cold and heavy.This air moves down slopes into valleys or plains.It is common in polar regions and high mountains.These winds can be very strong and cold.Last verified on 02-05-2026', 0, 0, 0, 1790965675180) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_8571c1d9e5c24482', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'The Hagia Sophia is situated in which city?', '{"A":"Izmier","B":"Istanbul","C":"Ankara","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hagia Sophia is located in Istanbul, Türkiye.It was completed in AD 537 during the Byzantine era.Originally, it was a Greek Orthodox church.Later, it was converted into a mosque, then a museum.In 2020, Hagia Sophia was reconverted into a mosque.Last verified on 29-01-2026', 0, 0, 0, 1790965675180) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_09b9f60124a1f3f2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which country is called the Land of Prophets?', '{"A":"Saudi Arabia","B":"Syria","C":"Palestine","D":"Iraq"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Palestine is the land of prophets.Because many prophets were born, lived, or died there, Including Ibrahim, Lut, Dawood, Suleiman, Musa, Zakariya, Yahya, and Isa (A.S).Baitul-Maqdis (Jerusalem) in Palestine was the first Qibla for Muslims.Muslims prayed facing it for 14 years before the Qibla changed to Kaaba in 2nd Hijri.Last updated by NA on 25-April-2026', 0, 0, 0, 1790965675180) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_2c065c938d23a8a8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'What is the Longest River in the World?', '{"A":"Nile","B":"Amazon","C":"Missi pissi","D":"Yangtze"}', 'A', NULL, 0, 0, 0, 1790965675248) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_367a67eb8a8afb81', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'What is the name of the ocean that lies between Europe and the United States?', '{"A":"Atlantic ocean","B":"Pacific ocean","C":"Arctic ocean","D":"Mediterranean Sea"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ocean: Atlantic OceanRank: 2nd largest oceanArea: ~106 million km²Borders: Europe, Africa, North & South AmericaImportance: Trade and transportation routeLast verified on 27-04-2026', 0, 0, 0, 1790965675249) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_7a9db7602036f43d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'The Hundred Years'' War was fought between which two countries?', '{"A":"USA and Canada","B":"France and Germany","C":"Japan and Germany","D":"France and England"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hundred Years'' War was fought between England and France.It lasted from 24 May 1337 to 19 October 1453 AD (with breaks).The war was mainly over territorial claims in France.France eventually won the war.It is one of the longest wars in history.Last verified on 27-04-2026', 0, 0, 0, 1790965675249) ON CONFLICT(id) DO NOTHING;
