INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_4474757c8ed2cc05', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'The Capital of Oman is _____?', '{"A":"Muscat","B":"Riyadh","C":"Doha","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Oman Capital is Muscat.Oman Currency is Omani Rial.Oman official language is Arabic.Oman located is in Continent Asia.Oman Primary Religion is Islam.Norway Parliament called Monarchy.Last verified on 14-03-2026', 0, 0, 0, 1790965675554) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_f16da8fa5b22ba75', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which is the Capital of Lebanon country?', '{"A":"Beriut","B":"Cairo","C":"Bako","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lebanon Capital is Beirut.Lebanon Currency is Lebanese Pound.Lebanon official language is Arabic; French.Lebanon located is in Continent Asia.Lebanon Primary Religion is Islam, Christianity.Lebanon Head of Govt. is Prime Minister –Najib Mikati.Lebanon Parliament called .Tricks for RememberPOUND S-E-S-UMind Trick : Sheshu(a name) plays in the Pond.**S-E-S-U**S - South SudanE - EgyptS - SyriaU - UK Last verified on 14-03-2026', 0, 0, 0, 1790965675554) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_86124fa39db6d89c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'The Continent Antarctica lies at the?', '{"A":"North Pole","B":"South North Pole","C":"South Pole","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Antarctica is the southernmost continent on Earth.It is centered around the South Pole.It is covered with ice.It is the coldest continent.No permanent human settlements, only research stations.Additional information:Area: About 14 million km²Ice coverage: ~98% of the continentInteresting fact: Holds around 90% of the world’s iceWildlife: Penguins, seals, and migratory birdsLast verified on 14-03-2026', 0, 0, 0, 1790965675555) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_30c92baab25259c1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'What is the Capital of Malaysia?', '{"A":"Kuala Lumpur","B":"Wellington","C":"Niamey","D":"Warsaw"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Malaysia Capital is Kuala Lumpur.Malaysia Currency is Ringgit.Malaysia official language is Malay.Malaysia located is in Continent Asia.Malaysia Primary Religion is Islam.Malaysia Head of Govt. is Prime Minister – Anwar IbrahimMalaysia Parliament called Majilis.Last verified on 13-03-2026', 0, 0, 0, 1790965675555) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_77e121d7973b25ee', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which Strait connects Persian Gulf with/to Gulf of Oman/Arabian Sea?', '{"A":"Malacca","B":"English Channel","C":"Hormuz","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Strait of Hormuz connects the Persian Gulf with the Gulf of Oman, which leads to the Arabian Sea.It lies between Iran and Oman.It is one of the most important oil shipping routes in the world.Many Middle Eastern countries export oil through this strait.Additional information:Strait of Malacca – Indian Ocean ↔ South China SeaBab-el-Mandeb Strait – Red Sea ↔ Gulf of AdenStrait of Gibraltar – Atlantic Ocean ↔ Mediterranean SeaBering Strait – Pacific Ocean ↔ Arctic OceanLast verified on 11-03-2026', 0, 0, 0, 1790965675555) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_d6e44d1358bcbe0a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'World’s famous leader Willy Brandt Belonged to which country of Europe?', '{"A":"France","B":"Austria","C":"Germany","D":"Belgium"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Willy BrandtCountry: GermanyBorn: 18 December 1913Died: 8 October 1992Position: Chancellor of West Germany (1969–1974)Award: Nobel Peace Prize (1971) for improving East–West relationsLast verified on 11-03-2026', 0, 0, 0, 1790965675666) ON CONFLICT(id) DO NOTHING;
