INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_c6b0ceaa5fe9e456', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'These are only two double landlocked countries in the world. Name both the countries?', '{"A":"Uzbekistan and Mali","B":"Uzbekistan and Liechtenstein","C":"Liechtenstein and Chad","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Double landlocked means a land-locked country that is also surrounded by landlocked neighboring countries.Uzbekistan is bordered by Afghanistan, Kazakhstan, Kyrgyzstan, Tajikistan, and Turkmenistan.Liechtenstein bordered by Austria and Switzerland.Last verified on 09-03-2026', 0, 0, 0, 1790965675666) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_9df02bb9959711e9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Ales Bialiatski, one among recipients of 2022 Peace Prize, belongs to which country?', '{"A":"Ukraine","B":"Russia","C":"Belarus","D":"Serbia"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 2022 Nobel Peace Prize RecipientsAles Bialiatski – BelarusMemorial Organization – RussiaCenter for Civil Liberties – UkraineLast verified on 09-03-2026', 0, 0, 0, 1790965675666) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_1b93686fc776d677', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which country was the runner up of ICC men''s T20 World Cup 2022?', '{"A":"England","B":"Pakistan","C":"Australia","D":"New Zealand"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ICC Men''s T20 World Cup 2022Runner-up: PakistanWinner: EnglandAdditional information:Edition: 8thHosted by: AustraliaHeld: 16 October to 13 November 2022England won by: 5 WicketsEngland won: Second timeParticipating teams: 16Total matches: 45Player of series: Sam Curran (England)Most runs: Virat Kohli (296 runs)Most wickets: Wanindu Hasaranga (Sri Lankan), (15 wickets)Last verified on 08-03-2026', 0, 0, 0, 1790965675666) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_d645a511bb194dc7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which ocean is known as the third largest ocean of the world?', '{"A":"Atlantic ocean","B":"Pacific Ocean","C":"Indian Ocean","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Indian Ocean is the third largest ocean in the world.It covers about 70 million square kilometers of Earth''s surface.It lies between Africa, Asia, Australia, and Antarctica.It is named after India, because India lies at its northern boundary.Additional information:Pacific Ocean – Largest ocean (~165 million km²)Atlantic Ocean – Second largest (~106 million km²)Indian Ocean – Third largest (~70 million km²)Southern Ocean – Fourth largestArctic Ocean – Smallest oceanLast verified on 06-03-2026', 0, 0, 0, 1790965675666) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_0e9171d7b8a40db9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which country is the biggest producer of Uranium in the world?', '{"A":"South Africa","B":"France","C":"Canada","D":"Kazakhstan","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kazakhstan is the world''s largest producer of uraniumApproximately 43% of global output in 2022 (over 21,000 tonnes) Maintaining its top position since 2009. Top 5 Uranium Producing Countries (2022/2023):Kazakhstan: ~43%Canada: ~15%Namibia: ~11%Australia: ~8-9%Uzbekistan: ~7-8%Last updated question 26 feb 2026', 0, 0, 0, 1790965675666) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_f00feb0911e695b0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Ottawa is the capital of:', '{"A":"Cambodia","B":"Canada","C":"Cuba","D":"Monaco"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ottawa is the capital city of Canada. Selected by Queen Victoria in 1857Became the permanent capital in 1867.It is the political center of Canada and the headquarters of the federal government.It is the fourth-largest in the country.Ottawa was founded in 1855Last updated question 26 feb 2026', 0, 0, 0, 1790965675788) ON CONFLICT(id) DO NOTHING;
