INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_3367bf289a7b421c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which country is not included in BRICS? India and Russia, Belgium and Japan, China and Brazil, None of these', '{"A":"India and Russia","B":"Belgium and Japan","C":"China and Brazil","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation BRICS Full Form: Brazil, Russia, India, China, South Africa (original)Belgium and Japan are not members of this bloc.Founded: June 2009First Conference Hosted By: Russia (2009)Headquarters: Shanghai, China (New Development Bank)Purpose: Economic cooperation, trade, development, and global influenceLast verified on 08-02-2026', 0, 0, 0, 1790965675868) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_413a2546011bc3e2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'The country that exited the European Union in 2020 is _____?', '{"A":"Norway","B":"Switzerland","C":"United Kingdom","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Brexit is the withdrawal of the UK from the EU and EAEC.UK voted to leave in a national referendum in June 2016.Officially left on 31 January 2020 (midnight, Dutch time).Theresa May was the UK Prime Minister at the time.UK is the first and only country to formally leave the EU after 47 years of membership.Last verified on 07-02-2026', 0, 0, 0, 1790965675868) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_ee6a9896666500bd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'The Name of World''s third largest Mountain is?', '{"A":"Cho You","B":"K2","C":"Mount Everest","D":"Kangchenjunga"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The 3rd highest mountain in the world is KangchenjungaIt is located on the border between Nepal and India (Himalayas).It stands at 8,586 meters (28,169 feet) tall.1st largest mountain: Mount Everest at 8,848 meters (29,029 feet).It is located on the border of Nepal and China (Himalayas).2nd largest mountain: K2 at 8,611 meters (28,251 feet).It is located on the China-Pakistan border (Karakoram).', 0, 0, 0, 1790965675868) ON CONFLICT(id) DO NOTHING;
