INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_9a03eb5981e51be0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'The Strait of Gibraltar connects which of the following?', '{"A":"Red Sea - Mediterranean Sea","B":"Red Sea - Arabian Sea","C":"Atlantic Ocean - Mediterranean Sea","D":"Mediterranean Sea - Black Sea"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Strait of Gibraltar connects the Atlantic Ocean to the Mediterranean Sea.It is located in the Iberian Peninsula (Spain).Separates Europe from AfricaThe two continents are separated by 7.7 nautical miles (14.2 kilometers, 8.9 miles) at its narrowest pointThe name comes from the Rock of Gibraltar,', 0, 0, 0, 1790965676044) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_6aae58deafd0df67', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Taj Mahal is located on the Bank of the river?', '{"A":"Yamuna","B":"Ganga","C":"Indus","D":"Nerbaba"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Taj Mahal is located in Agra, Uttar Pradesh, IndiaOn the west side of the Yamuna River.ADDITIONAL INFORMATION REALTED TAJ MEHALThe Taj Mahal, "Crown of Palaces", also "the Taj"It is a white marble mausoleum.It is located in Agra, Uttar Pradesh, IndiaConstruction started1632Construction completed1647Built byMughal Emperor Shah JehanBuilt-in the memory ofthe memory of his third wife, Mumtaz Mahal.Height73 MArchitectureUstad Ahmed Lahori', 0, 0, 0, 1790965676044) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_6985660970cae22a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which of the following countries expelled the PLO in 1970?', '{"A":"Syria","B":"Lebanon","C":"Jordan","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Palestine Liberation Organization was founded on May 28, 1964, in JerusalemIt is a Palestinian nationalist, political, and militant organizationLeadership: Mahmoud Abbas (Chairman of Executive Committee)Founders: Arab League, Ahmad Shukeiri', 0, 0, 0, 1790965676044) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_d0f6fe687881a3d7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'London is situated on the bank of river _____?', '{"A":"Themes","B":"Nile","C":"Amazon","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation London is located in southeastern England on the River Thames.London Tower is situated on the banks of the Thames.Thames flows through central London, including Tower Bridge, London Eye, Tower of London.Additional information:River Thames facts:Part of the longest river system in EnglandHas 45 locksHome to 25+ fish speciesTower Bridge: movable double-leaf bascule bridgeLast verified on 17-01-2026', 0, 0, 0, 1790965676122) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_3b1fb9370a35d389', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which country won the third cricket world cup in 1983?', '{"A":"West Indies","B":"Australia","C":"India","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Winner: IndiaRunner-up: West IndiesFinal Score: India 183/8 (54.4 overs) vs West Indies 140 (52 overs)Captain: Kapil DevVenue: Lord’s Cricket Ground, LondonAdditional information:West Indies had won the first two World Cups (1975 & 1979)Last verified on 16-01-2026', 0, 0, 0, 1790965676122) ON CONFLICT(id) DO NOTHING;
