INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_621f01541fa20813', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Normandy is in which country?', '{"A":"France","B":"Italy","C":"England","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Normandy, a region in northwest France.It became a province in 1450.It was reorganized after the French Revolution.It is famous as the site of the Allied D-Day invasion on June 6, 1944, during World War II.The D-Day landing, the largest amphibious invasion in history.It spanned 70 km from Sainte-Marie-du-Mont to Ouistreham.', 0, 0, 0, 1790965676192) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_63b73a1ae747ea00', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Petra an archaeological site is among the new seven Wonder of the world located in_________?', '{"A":"Jordan","B":"Italy","C":"India","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Petra is an archaeological site located in Jordan.It is famous for its rock-cut architecture and water conduit system.Petra was the capital of the Nabataean Kingdom around 4th century BC.It was declared a UNESCO World Heritage Site in 1985 and named one of the New Seven Wonders of the World in 2007.', 0, 0, 0, 1790965676192) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_d3030c4c22cd4539', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', '"KHAD and RAMA" secret agencies of which country?', '{"A":"Russia","B":"Afghanistan","C":"Tajikistan","D":"Uzbekistan"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Afghan Government with the collaboration of the Indian Intelligence agency "RAW", Russian Intelligence agency"KHAD" and the Central Intelligence Agency (CIA) of the US have constituted a new intelligence agency with the name Research and Analysis Mili Afghan (RAMA) to destabilize Pakistan.', 0, 0, 0, 1790965676192) ON CONFLICT(id) DO NOTHING;
