INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_9e2c8e5b3fbcbc7f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Syria is located in ____?', '{"A":"Central Asia","B":"Middle East","C":"East Asia","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Syria is a country located in the Middle East, which is a region that includes countries such as Lebanon, Jordan, Israel, Palestine, Iraq, and others.The Middle East is a transcontinental region that spans parts of Western Asia and North Africa.', 0, 0, 0, 1790965677223) ON CONFLICT(id) DO NOTHING;
