INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_103dd93467e3ae1f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which country is called as “Land of Mountains”?', '{"A":"Pakistan","B":"Bhutan","C":"Norway","D":"Nepal","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nepal is called the land of mountainsBecause it is home to the world''s highest and most famous mountain peaksThere are more than 1310 mountains in NepalMount Everest (World Heigest Mountain) is present in Nepal Additional information:Nepal''s Capital is Kathmandu.Its Currency is the Nepalese Rupee.Its official language is Nepali.Its Primary religions are Hinduism, Buddhism, and Islam.Its Head of Govt. is Prime Minister – Pushpa Kamal DahalIts Parliament is called the Federal Parliament of Nepal.', 0, 0, 0, 1790965677223) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_b3666b02426f8ea9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'First Islamic Summit Conference was held in _____ from _____ in which _____ countries participated.', '{"A":"Tehran, 27-30 September 1970, 24","B":"Riyadh, 20-23 October 1970, 25","C":"Rabat, 22-25 September 1969, 24","D":"Ankara, August 23-25 1969, 24"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first Islamic Summit Conference was held in Rabat from 22-25 September 1969, with 24 countries participating.The conference was convened in response to the burning of the Al-Aqsa Mosque.', 0, 0, 0, 1790965677319) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_cebed8bceebbf4eb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'What is the capital of Jordan?', '{"A":"Amman","B":"Beirut","C":"Gaza","D":"New Delhi"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jordan Capital is Amman.Jordan Currency is Jordanian Dinar.Jordan official language is Arabic.Jordan located is in Continent Asia.Jordan Primary Religion is Islam.Jordan Head of Govt. is Prime Minister – Bishr Al-Khasawneh.Jordan Parliament called National Assembly.Tricks for RememberDINAR K-S in J-A-I-L**K-S**K-KuwaitS-Sudan**J-A-I-L***J-JordenA-AlgeriaI-IraqL-Libya', 0, 0, 0, 1790965677319) ON CONFLICT(id) DO NOTHING;
