INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_6689c6d7e0d730a2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'The slogan "No taxation without representation" was first raised in which country?', '{"A":"America","B":"France","C":"Germany","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The slogan "No taxation without representation" was first raised in the American colonies in the 18th century.It was a key phrase used by American colonists to protest British taxation policies, such as the Stamp Act and Townshend Acts.This slogan became a rallying cry for the American Revolution.', 0, 0, 0, 1790965678909) ON CONFLICT(id) DO NOTHING;
