INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_e0a797e689abf171', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which is the highest mountain Range in the world?', '{"A":"Himalays","B":"Andes","C":"Ural","D":"The Alps","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Himalayas are the highest mountain range in the worldThe Himalayas span five countries: Nepal, India, China, Bhutan, and Pakistan.Peak: Mount Everest, Nepal, ChinaElevation: 8,848.86 m (29,031.7 ft)Located in AsiaAdditional informationAndes: Longest continental range (Length: ~7,000 km), located in South America.K2 is the world’s second-highest peak, 8,611 metersMount Everest first highest mountain in the worldThe Sutter Buttes are the smallest mountain range in the world.Last updated question by NA on 28 April 2026', 0, 0, 0, 1790965678909) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_5b590b5411ce6be1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Lake Baikal is situated in the which country?', '{"A":"Russia","B":"Denmark","C":"USA","D":"Canada"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lake Baikal is situated in southern Siberia, Russia, It is a rift lake and the deepest lake in the world It has a length of 397 miles (640 km).It has a maximum width of 49 miles.', 0, 0, 0, 1790965678909) ON CONFLICT(id) DO NOTHING;
