INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_5099b628c934aa92', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Louvre museum is located in _______?', '{"A":"UK","B":"USA","C":"Paris","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Louvre, is located in Paris, France.Largest art museum in the world with an area size of 782,910 square feet. This museum is considered a historic monument in Paris and is part of the Louvre Palace, which was built in the 12th century.Founded: August 10, 1793Architect: I. M. PeiDate completed: 1793******ND25-7-2023', 0, 0, 0, 1790965679090) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_4dd8cc508739f7b1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'The Empire State Building is located in _____?', '{"A":"London","B":"Birmingham","C":"Paris","D":"New Delhi","E":"New York City"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Empire State Building is a 102-story Art Deco skyscraper in Midtown Manhattan in New York City, United States. Built from 1930 to 1931. Its name is derived from "Empire State", the nickname of the state of New York.', 0, 0, 0, 1790965679090) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_1a8627ab87e897ae', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which one Country abolished the post of Prime Minister?', '{"A":"UK","B":"UAE","C":"Senegal","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Country: SenegalYear of Abolition: 2019Reason: To streamline government operations and enhance executive efficiency.Action Taken: Constitutional amendment to abolish the position of Prime Minister.Result: Executive powers were concentrated in the President''s office, and the role of the Prime Minister was eliminated.', 0, 0, 0, 1790965679090) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_5bf3398af065b1c9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Where is Whitehaven beach is located in Australia?', '{"A":"Perth","B":"Queensland","C":"Aid Leads","D":"Canberra"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Whitehaven Beach is located in Queensland, Australia.It is famous for its white silica sand.It is part of the Whitsunday Islands.It offering stunning views and clear turquoise waters.', 0, 0, 0, 1790965679090) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_f44e4c1722e96cdd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which of the following is the narrowest strait of the world?', '{"A":"Strait of Tartar","B":"Malacca Strait","C":"Palk Strait","D":"Strait Yucatan"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Strait of Tartar is the narrowest in the world. It is 7.3 km wide at the narrowest point. It is located between the Russian island of Sakhalin and mainland AsiaConnecting the Sea of Okhotsk in the north with the Sea of Japan to the south.', 0, 0, 0, 1790965679090) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_1834528244a783d6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'In March 2021, North Korea ended its diplomatic relations with which of the following country South Korea?', '{"A":"Malaysia","B":"USA","C":"China","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In March 2021, North Korea ended its diplomatic relations with Malaysia.This occurred after a Malaysian court allowed the extradition of a North Korean citizen to the United States.North Korea deemed this a hostile act.', 0, 0, 0, 1790965679090) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_e0cbced2d495bc96', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which country is the World''s top supplier of weapons?', '{"A":"Israel","B":"Russia","C":"America","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The United States is the world''s largest arms exporter.It accounted for 37% of global arms sales between 2016 and 2020, and 38.6% between 2017 and 2021, according to SIPRI.The U.S. is followed by Russia, France, China, and Germany.U.S. arms exports increased by 15% between 2016 and 2020 compared to the previous five years.', 0, 0, 0, 1790965679090) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_c6d2b61337e6eb65', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'How many countries are members of the Gulf Cooperation Council (GCC)?', '{"A":"10","B":"8","C":"6","D":"4"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Gulf Cooperation Council (GCC) was formed by six countries: Bahrain, Kuwait, Oman, Qatar, Saudi Arabia, and the United Arab Emirates.The charter was signed on May 25, 1981.The GCC is headquartered in Riyadh, Saudi Arabia.', 0, 0, 0, 1790965679090) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_10d4ad9caa20eb62', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which desert of Pakistan also lies in India:', '{"A":"Thal","B":"Thar","C":"Rohi","D":"Kharan"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Thar desert covers an area of 200,000 km2 (77,000 sq mi) in India and Pakistan.About 85% of the Thar Desert is in India, and about 15% is in Pakistan.The portion in India also extends into: Gujarat PunjabHaryana The portion in Pakistan extends into:Sindh Punjab It is the largest desert of PakistanIt is the world''s 18th-largest desertThe world''s 9th-largest hot subtropical desert', 0, 0, 0, 1790965679168) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_af5de3b01eee9068', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Line of Actual Control (LAC) is a border among which countries?', '{"A":"India and Pakistan","B":"China and India","C":"China and Pakistan","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Line of Control (LoC) was established in 1949 after the Karachi Agreement, following the first Indo-Pak war over Kashmir.It was originally called the Ceasefire Line and renamed the LoC in the 1972 Simla Agreement.The LoC is approximately 740 km long.', 0, 0, 0, 1790965679168) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_b00011b29680f7a5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which of the following countries declared 2019 as the ‘Year of Tolerance’?', '{"A":"UAE","B":"Germany","C":"France","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The United Arab Emirates (UAE) declared 2019 as the ''Year of Tolerance.''This initiative aimed to promote values of coexistence and respect among different cultures and religions.Sheikh Khalifa bin Zayed Al Nahyan, has declared 2019 as “Year of Tolerance”.', 0, 0, 0, 1790965679168) ON CONFLICT(id) DO NOTHING;
