INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_a7e0751d5789d211', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Member countries of BRICS are?', '{"A":"Britain Russia Isreal China Saudi Arabia","B":"Bolivia Romania India Cuba Syria","C":"Brazil Russia India China and South Africa","D":"Britain Russia India Cuba South Africa"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Know everything about BRICS: BRICS founded: June 2009BRICS Member countries: Brazil, Russia, India, China, South Africa, Egypt, Ethiopia, Iran, Saudi Arabia and the United Arab EmiratesBRICS total members: 10 South Africa joined BRICS: 2010BRICS headquarters: Shanghai, ChinaBRICS first conference hosted by: Russia (2009)', 0, 0, 0, 1790965679943) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_3ae7524007c6ab2f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'Which city of London is famous for calculating the time of all the countries?', '{"A":"Greenwich","B":"Hague","C":"Manchester","D":"Leads"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Greenwich is famous for its naval and military connections and its green spaces.The Greenwich Meridian became the international standard for the prime meridian. The prime meridian also sets Coordinated Universal Time (UTC)ND27-7-2023', 0, 0, 0, 1790965679943) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_61a16b2ae3106c08', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_geography', 'The first case of monkeypox in humans was recorded in which country?', '{"A":"South Sudan","B":"Kenya","C":"DR Congo","D":"China"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Monkeypox virus, a zoonotic orthodox DNA virus related to the virus that causes smallpox, was first described in humans in 1970 in the Democratic Republic of Congo.Mpox can spread from person to person or occasionally from animal to people****Health officials have confirmed the first case of monkeypox (mpox) in Islamabad, Pakistan, as of April 21. ND17-7-2023', 0, 0, 0, 1790965679943) ON CONFLICT(id) DO NOTHING;
