INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_4689dfb44d829690', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_intl_org', 'How many countries are members of ASEAN?', '{"A":"10","B":"11","C":"12","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ASEAN (Association of Southeast Asian Nations) members (11): Brunei Cambodia Indonesia Laos Malaysia Myanmar Philippines Singapore Thailand VietnamTimor LesteAdditional information:Founded: 8 August 1967, Bangkok, ThailandHeadquarters: Jakarta, IndonesiaOfficial language: No single official language (English commonly used)Purpose: Promote economic, cultural, and political cooperation in Southeast Asia.Last verified on 16-01-2026', 0, 0, 0, 1790965684224) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_f7acae8eb1a24bbf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_intl_org', 'Who is known as Father of Geography?', '{"A":"Herodotus","B":"Aristotle","C":"Erastosthenes","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The term Geography was first used by the Greek scholar Eratosthenes.He lived in the 3rd century BC (around 276–194 BC).He is also known as the “Father of Geography”.He calculated the circumference of the Earth with remarkable accuracy.His work laid the foundation of modern geographical studies.Last verified on 02-05-2026', 0, 0, 0, 1790965684224) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_be654a4e57d9fbb8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_intl_org', 'Who was the first and last woman ruler of India (Delhi)?', '{"A":"Chand BiBi","B":"Maryam Noor","C":"Mumtaz Mahal","D":"Razia Sultana"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Razia Sultana was the first and last female ruler of Delhi Sultanate.She ruled India from 1236 to 1240.She was the daughter of Sultan Shams-ud-Din Iltutmish and Turkan Khatun.Known for her bravery, intelligence, and administrative skills.Last verified on 02-02-2026', 0, 0, 0, 1790965684224) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_9538097650413ce1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_intl_org', 'Who is the Current President of Russia?', '{"A":"Mikhail Mishustin","B":"Vladimir Putin","C":"Volodymyr Zelenskyy","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Vladimir Putin has served continuously as president or prime minister since 1999: As prime minister from 1999 to 2000 and from 2008 to 2012, As president from 2000 to 2008, and since 2012Born: 7 October 1952, Leningrad, Russian SFSR, Soviet UnionParty: Independent (1991–1995, 2001–2008, since 2012).Last updated by NA on 27 April 2026', 0, 0, 0, 1790965684224) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_5f83ce25ab59a245', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_intl_org', 'Who was considered as Father/Expert of Modern Optics?', '{"A":"Abū Mūsā Jābir ibn Ḥayyān","B":"Jafar Ibn Hayyan","C":"Ḥasan Ibn al-Haytham","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ibn al-Haytham is known as the Father of Modern Optics.He made groundbreaking discoveries about light and vision.His famous book is Kitab al-Manazir (Book of Optics).His research was done around 1011–1021 AD.Last verified on 27-04-2026', 0, 0, 0, 1790965684224) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_25c9a599eccb331f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_intl_org', 'Headquarters of International Olympic Committee (IOC) located in?', '{"A":"France","B":"Switzerland","C":"USA","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Headquarters: Lausanne, SwitzerlandFounded: 23 June 1894Founder: Pierre de Coubertin & Demetrios VikelasCurrent President: Thomas BachType: International sports organizationLast verified on 27-04-2026', 0, 0, 0, 1790965684224) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_d7255b2051b55d94', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_intl_org', 'Who among the following was a Historian, justice, philosopher as well as Politician?', '{"A":"Abu Bakar Muhammad Yahya","B":"Abdur Rehman bin Khaldun","C":"Shams ud din bin Khalkan","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Abdur Rehman bin Khaldun was an Arab sociologist, philosopher, and historian. Born: May 27, 1332, in TunisDied: March 17, 1406, in EgyptHe made major contributions to historiography, sociology, economics, and demography.His best-known book is the "Muqaddimah" or "Prolegomena" ("Introduction").Last verified on 27-04-2026', 0, 0, 0, 1790965684224) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_460b76816bd28403', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_intl_org', 'Who declared Nile River as Sayed Ul Anhar??', '{"A":"Hazrat Usman (RA)","B":"Hazrat Ali (RA)","C":"Hazrat Umar (RA)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Umar ibn al-Khattab (RA) declared the Nile River as Sayed ul Anhar (Chief of Rivers).This happened during his caliphate (634–644 AD).The Nile River was highly valued for its importance to Egypt.Length of Nile River: ~6650 kmOrigin: Lake Victoria (East-Central Africa)Last verified on 27-04-2026', 0, 0, 0, 1790965684314) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_b4e72ceb6176a3f3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_intl_org', 'Who was the conqueror of Spain?', '{"A":"Tariq bin Ziad","B":"Musa bin Naseer","C":"Muhammad bin Qasim","D":"Khalid bin Waleed"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The conqueror of Spain was Tariq ibn Ziyad.He led the Muslim army in 711 AD and began the conquest of the Iberian Peninsula.He defeated the Visigothic ruler King Roderic at the Battle of Guadalete.His landing place is famously known as Jabal al-Tariq (Gibraltar).Last verified on 25-04-2026', 0, 0, 0, 1790965684314) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_6256e3a8a15dd138', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_intl_org', 'IMF stands for _____?', '{"A":"Iraq Monetary Fund","B":"Indonesia Monetary Fund","C":"Iran Monetary Fund","D":"International Monetary Fund"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The International Monetary Fund (IMF) A major financial agency of the United Nations and an international financial institution.Pakistan officially became a member of the IMF on July 11, 1950.IMF founded: 27 December 1945Headquarters: Washington, USATotal members: 190Official language: EnglishLast updated by NA on 24-April-2026', 0, 0, 0, 1790965684314) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_783630499b37b83d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_intl_org', 'The tenure of Judge of International Court of Justice (ICJ) is?', '{"A":"9 years","B":"10 years","C":"13 years","D":"15 years"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The headquarters of the International Court of Justice is in The Hague, Netherlands.ICJ is one of the six principal organs of the United Nations.It consists of 15 judges, elected for 9-year terms.Additional information:Founded: 1945Official Languages: English, FrenchMember States: UN member countriesMain Function: Settling legal disputes between statesLast verified on 15-01-2026', 0, 0, 0, 1790965684314) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_31d58e806a98f576', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_intl_org', 'Pakistan and India join Shanghai cooperation organization (SCO) in ______?', '{"A":"2016, June 7th","B":"2017, June 9th","C":"2018, June 11th","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation On 9 June, 2017 India and Pakistan became full members of the Shanghai Cooperation Organisation (SCO).The SCO Headquarters: Beijing, ChinaThe SCO Founded: June 15, 2001The SCO currently comprises of nine Members States (China, India, Kazakhstan, Kyrgyzstan, Russia, Pakistan, Tajikistan, Iran and Uzbekistan), four Observer StatesLast verified on 09-03-2026', 0, 0, 0, 1790965684314) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_5e6738318bb3774c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_intl_org', 'Who is the current Secretary General of NATO?', '{"A":"Anders Fogh Rasmussen","B":"Antonio Guterres","C":"Mark Rutte","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mark Rutte is the current Secretary General of NATO since October 2024He has also served as the prime minister of Netherlands.He replaced Jens Stoltenberg to become NATO Secretary General. *********VU FIA UDC CONSTABLE PAST PAPER 31-12-2021Verified and updated on 05 April 2026', 0, 0, 0, 1790965684314) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_e6d123dc45287548', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_intl_org', 'The headquarter of the United Nations Human Rights Council (UNHRC) is located/based in ______?', '{"A":"London","B":"Oslo","C":"Washington","D":"Geneva"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The United Nations Human Rights Council headquarters in Geneva, Switzerland.It is also the European headquarters of the UN.Date of formation: March 15, 2006Subsidiary body of the UN General Assembly.Replaced the UN Commission on Human Rights.47 member states (tenure of membership three-year terms)', 0, 0, 0, 1790965684314) ON CONFLICT(id) DO NOTHING;
