INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_9530e0f159ac01bf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_intl_org', 'Asian Development Bank (ADB) was established in _____?', '{"A":"1966","B":"1964","C":"1968","D":"1960"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Asian Development Bank (ADB)Established: 19 December 1966Headquarters: Manila, PhilippinesMembership: 68 countriesAsia & Pacific: 49Outside region (Non-Asian): 19Additional information:Largest recipient of ADB loans: PakistanPakistan received highest ADB loans in 2022: $5.58 billionADB loans & grants to Pakistan (2021): $1.31 billionLargest shareholder of ADB: JapanLast verified on 20-06-2026', 0, 0, 0, 1790965684424) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_7abb30d332b0fee4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_intl_org', 'Who developed the polio Vaccine?', '{"A":"Richard Gatling","B":"Joseph Priesty","C":"Jonas Edward Salk","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Polio Vaccines: Developed to prevent poliomyelitis, a viral disease causing paralysis.Jonas Salk (US, 1950s): Created the first inactivated (killed) polio vaccine; tested on himself and family in 1953; officially used in 1955.Albert Sabin (1961): Developed the live attenuated (weakened) oral polio vaccine.Recent Campaigns: Israel launched a polio vaccine drive in April 2022 after 1988 efforts.Last verified on 03-04-2026', 0, 0, 0, 1790965684424) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_7a01f1997bfc7e54', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_intl_org', 'Who was the first woman (female) Prime Minister of world?', '{"A":"Benazir Bhutto (Pakistan)","B":"Junko Taibei (Japan)","C":"Sirimavo Bandaranaike (Sri Lanka)","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sirimavo BandaranaikeFirst female Prime Minister in the world; belonged to Sri Lanka.Leader of the Sri Lanka Freedom Party.Served three terms: 1960–65, 1970–77, and 1994–2000.Preceded by Chandrika Kumaratunga.Succeeded by Ratnasiri Wickremanayake.Last verified on 02-04-2026', 0, 0, 0, 1790965684424) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_fe6fc9d4ca6203a8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_intl_org', 'Which is not the official language of the United Nation (UNO)?', '{"A":"French","B":"Persian","C":"English","D":"Arabic"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Persian is not the official language of the United Nation.United Nations (UNO) recognizes six official working languages.Additional information:Official Languages: Arabic, Chinese, English, French, Russian, SpanishFounded: 24 October 1945Headquarters: New York, USAPurpose: Promote international peace, security, and cooperationMembers: 193 countriesLast verified on 15-01-2026', 0, 0, 0, 1790965684424) ON CONFLICT(id) DO NOTHING;
