INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_ec6a38afb4c57651', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'The highest waterfall of the world is?', '{"A":"Angel falls","B":"Great fall","C":"Victoria falls","D":"Boyoma Falls"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The highest waterfall in the world is Angel Falls.Country: VenezuelaElevation: 1,283 metresHeight: 979 metresLongest drop: 807 metresThe waterfall is named after Jimmie Angel, a U.S. aviator who was the first person to fly over the falls.Last verified on 27-09-2026', 0, 0, 0, 1790965688487) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_2911d6db5507fb05', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'The largest producer of cotton in the world is ______?', '{"A":"India","B":"USA","C":"China","D":"Pakistan"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation China: Largest cotton-producing country.Textile Industry: 7,500 companies.Annual Production: US $73 billion of cotton cloth.Additional information:India: Second largest cotton producer.USA: Third largest cotton producer.Last verified on 23-01-2026', 0, 0, 0, 1790965688487) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_e453a3f34d9a182a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'The fastest person in the world in 100 and 200-meter sprints is ______?', '{"A":"Kim Coliris","B":"Usain Bolt","C":"Dwain Chambers","D":"Justin Gatlin"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Usain Bolt is the world-record holder in both the 100-meter and 200-meter sprints.He set the 100m world record of 9.58 seconds in 2009.He set the 200m world record of 19.19 seconds in 2009.Last verified on 08-09-2026', 0, 0, 0, 1790965688487) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_b66748b0be8d5efd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'Which of the following is the world''s largest inland water body?', '{"A":"Sea of Azov","B":"Black Sea","C":"Caspian Sea","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Largest inland water body: Caspian SeaBordering countries: 5 (Russia, Iran, Azerbaijan, Kazakhstan, and Turkmenistan)Surface area: ~371,000 km²Volume: ~78,200 km³Largest river flowing into it: Volga RiverLast verified on 07-09-2026', 0, 0, 0, 1790965688597) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_af8d5904f427a54d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'The first Muslim woman to receive Nobel Prize in 2003 is ______?', '{"A":"Malala Yousafzai","B":"Shirin Ebadi","C":"Dr. Habiba Sarabi","D":"Ilmas Durkhain"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Name: Shirin EbadiCountry: IranAward: Nobel Peace PrizeYear: 2003Recognition: Human rights and democracyLast verified on 02-09-2026', 0, 0, 0, 1790965688597) ON CONFLICT(id) DO NOTHING;
