INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_6a3a24d18a099f0e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'Which of following is considered the worlds oldest city?', '{"A":"Damascus","B":"Baghdad","C":"Cairo","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Damascus, Syria is considered the oldest city in the world.Its origins date back to the seventh millennium BC.Known as the "Pearl of the East" for its historical significance.', 0, 0, 0, 1790965688823) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_f90630b82678c98f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'The World''s Largest subway System is in---?', '{"A":"Shanghai","B":"Tokyo","C":"London","D":"New York"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Shanghai Metro is the world''s longest metro network (subway) at 803 kilometersBegan-----> on 28 May 1993; 29 years agoIt is also the second biggest by the number of stations with 396 stations The Shanghai Metro is the highest annual ridership at 2.83 billion trips**LIST OF METRO SYSTEM (Subway) :The London Underground makes it the world''s oldest metro system.the New York City Subway has the greatest number of stations with 472.The country with the most metro systems in China, with 44 in operationND23-4-2023', 0, 0, 0, 1790965688823) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_ca6d69375a064775', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'The oldest anthem of the world is?', '{"A":"Taiwan","B":"Japan","C":"Thailand","D":"Iran"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Kimigayo" is the national anthem of Japan.Its lyrics, originating from the Heian period (794–1185), are the oldest among national anthems.With only 32 characters, it is the world''s shortest national anthem.The lyrics are from a waka poem written by an unnamed author.', 0, 0, 0, 1790965688917) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_aa8414f2bc5740a8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'For Economics category a first Nobel prize was given in _______?', '{"A":"1945","B":"1901","C":"1969","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation First Nobel Prize in Economics – Key PointsYear & Recipients: 1969, awarded to Ragnar Frisch and Jan Tinbergen.Reason: For developing and applying dynamic models to analyze economic processes.', 0, 0, 0, 1790965688917) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_36d80c6752953893', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'World oldest international organization was?', '{"A":"UNO","B":"IMF","C":"World Bank","D":"League of Nation"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation · The League of Nations was the first worldwide intergovernmental organization. · The League of Nations principal mission was to maintain world peace. · The League of Nations was founded on 10 January 1920 by the Paris Peace Conference. · The League of Nations was ended the First World War. · The League of Nations Founder: Woodrow Wilson · The League of Nations Founded: January 10, 1920 · The League of Nations Headquarters: Geneva, Switzerland', 0, 0, 0, 1790965688917) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_a7626a820b72ae8b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'The second largest ethnic group in Afghanistan is _____?', '{"A":"Uzbek","B":"Tajik","C":"Hazaras","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pashtun are the largest ethnic group in Afghanistan. Tajiks are the second largest ethnic group in Afghanistan.It comprise between 25-30% of the population.The Tajiks in Afghanistan are mainly Sunni Muslims who follow the Hanafi sect.', 0, 0, 0, 1790965688917) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_4799ecc25db2334d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'Oldest human right organization?', '{"A":"UNO","B":"IMF","C":"World Bank","D":"Anti-slavery International"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Anti-Slavery International is the world''s oldest human rights organisation. Founded: 1839 (as the British and Foreign Anti-Slavery Society).It is an international non-governmental organisation, registered charity, and advocacy group, based in the United Kingdom.Abbreviation: Anti-SlaveryFounded: 1839; 187 years agoPurpose: Anti-slaveryHeadquarters: London, SW9, United Kingdom', 0, 0, 0, 1790965688917) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_e645c133fe25c94a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_records', 'When did the Wright brothers make the first successful powered air flight?', '{"A":"1899","B":"1903","C":"1910","D":"1925"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kill Devil Hills, near Kitty Hawk, North Carolina.Date: December 17, 1903.Pilot: Orville Wright was at the controls for the first flight.Details of the first flight: It lasted 12 seconds and covered 120 feet.Later flights: The brothers completed three more successful flights that day, with the final one lasting 59 seconds and covering 852 feet.', 0, 0, 0, 1790965688917) ON CONFLICT(id) DO NOTHING;
