INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_3bf4cff7c8870acf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_current', 'The father of former President Barrack Obama, belonged to _____?', '{"A":"Canada","B":"Indonesia","C":"Kenya","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Barack Obama Sr., father of former U.S. President Barack ObamaHe belongs to the Nyang''oma Kogelo, Kenya ( Citizenship: British Kenyan)Born on June 18, 1936The 44th president of the United States.Passed away on November 24, 1982, in Nairobi, Kenya.', 0, 0, 0, 1790965690451) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_26cf608ab3244ddc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_current', 'The Treaty of Versailles settled peace in ______?', '{"A":"Middle East","B":"Africa","C":"Europe","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Treaty of Versailles (1919)Signed On: 28 June 1919Parties Involved: Allied Powers vs GermanyPurpose: To establish peace and codify terms after World War IKey Fact: Primary treaty from the Paris Peace ConferenceRegion Affected: EuropeAdditional Points:Imposed war guilt on Germany (Article 231)Enforced reparations and military restrictions on GermanyLaid foundations that later influenced World War IILast Verified on 13-01-2026', 0, 0, 0, 1790965690451) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_a3c887831ebe60a0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_current', 'Treaty of Sevres was signed in ________?', '{"A":"1920","B":"1989","C":"1962","D":"1955"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Date: August 10, 1920Location: Sèvres, FranceSignatories: The Allied Powers and the Ottoman EmpirePurpose: To partition the Ottoman Empire after World War IThe treaty ceded large parts of Ottoman territory to:Francethe United KingdomGreece and ItalyThe 1923 Treaty of Lausanne, which superseded the Treaty of Sèvres', 0, 0, 0, 1790965690451) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_3ec62a7080bfda1f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_current', 'Martin Luther King, Jr. is a/an ______?', '{"A":"Welsh","B":"American","C":"Galeic","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Martin Luther King Jr. was an American civil rights leader He fought against racial segregation in the United States.He is best known for his “I Have a Dream” speech and was awarded the Nobel Peace Prize in 1964.History 1st President of the Southern Christian Leadership Conference - January 10, 1957 – April 4, 1968Born: January 15, 1929, Atlanta, Georgia, U.S.Died: April 4, 1968 (aged 39), Memphis, Tennessee, U.S.Manner of death: Assassination by gunshotResting place: Martin Luther King Jr. National Historical Park', 0, 0, 0, 1790965690451) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_6cb6106e17ddd6a2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_current', 'Napoleon Bonaparte was the King of ______?', '{"A":"France","B":"Italy","C":"Greece","D":"Russia"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Napoleon Bonaparte was the first emperor of France (1804–14/15).He was born on August 15, 1769, in Ajaccio, FranceHe was later known by his regnal name Napoleon IHe was defeated in the Battle of Waterloo in 1815The British exiled Napoleon Bonaparte to the remote island of Saint Helena in the Atlantic, Where he died in 1821 at the age of 51', 0, 0, 0, 1790965690451) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_91a14a93a7dcecf2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_current', '_____ in Pakistan is responsible for the formulation of monetary policy.', '{"A":"SECP","B":"Ministry of Finance","C":"State Bank of Pakistan","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The State Bank of Pakistan (SBP) is responsible for the formulation of monetary policy in Pakistan.It manages the country''s monetary policy to ensure economic stability and control inflation.', 0, 0, 0, 1790965690451) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_80322c8fe72223e4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_current', 'Which foreign leader addressed the Pakistan assembly for 3rd time?', '{"A":"Recep Tayyip Erdogan","B":"Xi Jinping","C":"Mahathir Muhamad","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The foreign leader who addressed the Pakistan assembly for the third time is Recep Tayyip Erdogan, the Turkish President.He addressed the Joint Session of Parliament for 27 minutes in February 2020.He had previously addressed the Joint Sessions on May 20, 2012, and October 2009, when he was the Prime Minister of Turkey.', 0, 0, 0, 1790965690569) ON CONFLICT(id) DO NOTHING;
