INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_dc0ea797c01e406d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_current', 'Watergate Scandal Led to the downfall of which president of the United States?', '{"A":"Jimmy Carter","B":"Theodore Roosevelt","C":"Richard Nixon","D":"Lydon Johnson"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Watergate scandal was a major political scandal in the United States.The Watergate scandal involving the administration of President Richard Nixon from 1972 to 1974.', 0, 0, 0, 1790965690790) ON CONFLICT(id) DO NOTHING;
