INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_7860c23944955ea6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_current', 'Yasir Arafat remained the President of the Palestinian authority for almost _______?', '{"A":"6 years","B":"9 years","C":"15 years","D":"10 years"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Yasser Arafat (4 August 1929 – 11 November 2004) was a Palestinian political leader.He served as Chairman of the Palestine Liberation Organization (PLO) from 1969 to 2004.He was President of the State of Palestine from 1989 to 2004.He was also President of the Palestinian Authority (PNA) from 1994 to 2004.Arafat was a founding member of the Fatah political party, leading it from 1959 until 2004.', 0, 0, 0, 1790965690913) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_8cafa1457fd84f63', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_current', 'Financially motivated nonviolent crimes committed by business and government professionals are called?', '{"A":"White Collar Crimes","B":"Personal Crime","C":"Statutory Crimes","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation White-collar crimes are illegal activities that are financially motivated and usually non-violent.Examples of white-collar crimes include securities fraud, embezzlement, corporate fraud, money laundering, identity theft, forgery, and governmental corruption.The term "white-collar crime" was coined in the 1930s by sociologist and criminologist Edwin Sutherland.', 0, 0, 0, 1790965690913) ON CONFLICT(id) DO NOTHING;
