INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_80d1094fc0f5ec13', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_current', 'The idea of ''Asia Europe Meeting'' (ASEM) organization was initiated in 1994 by Mr. Goh Chok Tong, the Prime Minister of ______?', '{"A":"Singapore","B":"South Korea","C":"North Korea","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Goh Chok Tong, the Prime Minister of Singapore, initiated the idea of the Asia-Europe Meeting (ASEM) in 1994.It is an informal forum for cooperation and dialogue between Asia and Europe.It was launched in 1996 with 26 partners.It has since grown to 53 partners.The three main pillars of ASEM cooperation are political, economic, and socio-cultural.', 0, 0, 0, 1790965690913) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_32f981ed0475a7df', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_current', 'Jacob Zuma was the President of ____?', '{"A":"South Africa","B":"Kenya","C":"South Africa","D":"Zambaway"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jacob Zuma was the President of South Africa.He served as the fourth president of South Africa from 2009 to 2018.Zuma was also the president of the African National Congress from 2007 to 2017.He was a former anti-apartheid activist and member of the South African Communist Party.', 0, 0, 0, 1790965690913) ON CONFLICT(id) DO NOTHING;
