INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_5f861d92d1121d4e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'AD stands for relevant to count ages?', '{"A":"Anno Domini","B":"After Demonstration","C":"After Death","D":"After Domini"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation AD stands for Anno Domini.It is a Latin term meaning “in the year of our Lord.”It is used for years in the traditional Christian calendar.For example, AD 2026 means the year 2026 in the AD system.Additional information:BC: Before ChristCE: Common EraBCE: Before Common EraLast verified on 30-09-2026', 0, 0, 0, 1790965691783) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_d49c189f33702d3c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'What does ''PDF'' stand for?', '{"A":"Print Document Format","B":"Portable Disc Format","C":"Portable Document Format","D":"Portable Document Firewall"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Full Form: Portable Document Format (PDF)Developed by: Adobe Inc.Introduced: 1993Co-founder associated with Adobe: Charles GeschkePurpose: Reliable document sharing and viewingان سولات کو ضرور پڑھیںClick hereLast verified on 01-07-2026', 0, 0, 0, 1790965691783) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_ab0563bbc06adbb6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'CPU stands for?', '{"A":"Central Processing Unit","B":"Central Procedural Unit","C":"Central Processing Unique","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation CPU stands for Central Processing Unit.It is the main part of a computer that processes all instructions.It is considered the brain of the computer system.It performs all calculations and decision-making tasks.It controls the operations of all hardware and software.It is located on the motherboard.Last verified on 10-06-2026', 0, 0, 0, 1790965691783) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_1c8492ee0928ea2c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'BCC stands for _____?', '{"A":"Basic Carbon Copy","B":"Blind Carbon Copy","C":"Business Carbon Copy","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation BCC stands for: Blind Carbon CopyUsed in: Email communicationPurpose: Hides recipient email addresses from other recipientsAdditional information:CC (Carbon Copy): Recipients are visible to allBCC: Recipients are hidden from everyone except the senderLast verified on 16-01-2026', 0, 0, 0, 1790965691783) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_4bdb8b1a6a16b504', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'IP stands for ________?', '{"A":"Internet Process","B":"Intranet Protocol","C":"Internet Protocol","D":"Internal Protocol"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation IP stands for Internet Protocol.It is a set of rules used to address and route data between devices on a network.Every device on an IP network can be identified using an IP address.Additional information:IPv4: Uses 32-bit addresses.IPv6: Uses 128-bit addresses.Example of IPv4: 192.168.1.1Last verified on 27-09-2026', 0, 0, 0, 1790965691783) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_70d47bab0f3b569f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'ASCII stands for:', '{"A":"American Standard Conduct for Information Interchange","B":"Armenia Standard Code for Information Interchange","C":"American Standard Code for Information Interchange","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ASCII: American Standard Code for Information InterchangePurpose: Character encoding standardRange: 0–127Represents: Letters, numbers & punctuationWork began: May 1961Definitive version: Published in 1968Last updated by NA ON 16-09-2026', 0, 0, 0, 1790965691783) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_d4a0bc4d07a982d8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'CTBT stands for _______?', '{"A":"Collection Test Ban Treaty","B":"Conclusive Test Ban Treaty","C":"Comprehensive Test Ban Treat","D":"Competitive Test Ban Treaty"}', 'C', NULL, 0, 0, 0, 1790965691783) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_02e72b62311b5f15', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'JPEG stands for?', '{"A":"Joint Photo Editing Group","B":"Joint Photographic Experts Group","C":"Joint Photo Expert Group","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation JPEG stands for Joint Photographic Experts Group.JPEG is a common digital image compression and file format.The name comes from the organization that developed the standard.JPEG is widely used for photographs and web images.Its common file extensions are .jpg and .jpeg.Last verified on 08-09-2026', 0, 0, 0, 1790965691783) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_ff56d9bfed298bfb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'OGRA stands for _____?', '{"A":"Oil and Gas Regulatory Authority","B":"Oil and Gas Resource Association","C":"Oil and Gas Research Agency","D":"Oil and Gas Regulation Authority"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation OGRA stands for Oil and Gas Regulatory Authority.It is the regulatory body responsible for overseeing the oil and gas sector in Pakistan.It was established in 2002.It to ensure a fair and transparent regulatory framework for the exploration, production, transportation, and distribution of oil and gas resources.Last verified on 07-09-2026', 0, 0, 0, 1790965691854) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_036478416ad786cd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'USB stands for ______?', '{"A":"Universal serial Bussiness","B":"Universal Serial Bus","C":"Universal Secondary Bus","D":"Unary Serial Bus"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation USB stands for Universal Serial Bus.USB is a standard used to connect and transfer data between electronic devices.A USB flash drive is a data storage device that uses flash memory with an integrated USB interface.Ajay Bhatt is widely credited as a key figure in the development of USB technology in the 1990s.Last verified on 05-09-2026', 0, 0, 0, 1790965691854) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_6ddf1bd786d0855d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'FIR stands for _______?', '{"A":"First Information Regular","B":"First Information  Report","C":"First in charge Report","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation FIR stands for First Information Report.It a document prepared by police under Section 154 of the Code of Criminal Procedure (CrPC) 1898.It starting criminal proceedings in cognizable cases.Last verified on 11-05-2026', 0, 0, 0, 1790965691854) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_da646c3211c0bf62', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'PAEC stands for?', '{"A":"Pakistan Atomic Energy Commission","B":"Pakistan Atomic Employment Commission","C":"Basic Pay Scales","D":"None of above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation PAEC stands for Pakistan Atomic Energy Commission.It was established in 1956.Headquarters: Islamabad, Pakistan.PAEC is a federally funded government organization.It is mainly concerned with the peaceful uses of nuclear technology in Pakistan.Last verified on 05-09-2026', 0, 0, 0, 1790965691854) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_f506ed96ca68fdbe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'GPS is an abbreviation of _____?', '{"A":"Google Positioning System","B":"Global Positioning System","C":"Global Positioning Station","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation GPS is an abbreviation of the Global Positioning System.It is a satellite-based radio navigation system.Owned by the United States government. First launch: February 22, 1978Last verified on 05-09-2026', 0, 0, 0, 1790965691854) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_b18fc593e3bc7cd0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'SIM stands for ______?', '{"A":"Single in-line Module","B":"Single in-Line Memory","C":"Subscriber Identity Module","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation SIM stands for Subscriber Identity Module.A SIM card securely stores the subscriber''s identity and enables access to a mobile network.Additional information:First SIM card developed: 1991Invented in: Munich, GermanyManufacturer: Giesecke+Devrient (G+D)PIN: Personal Identification NumberPUK: Personal Unblocking KeyLast verified on 22-07-2026', 0, 0, 0, 1790965691854) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_344095965e82a399', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'DC stands for?', '{"A":"Direct Current","B":"Direct Collector","C":"District Controller","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation DC stands for Direct Current.In DC, electric current flows in one direction.Common sources include batteries, cells, and solar panels.AC stands for Alternating Current, where the direction periodically changes.Last verified on 04-09-2026', 0, 0, 0, 1790965691854) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_7d3867220768d7d5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'What does COVID stand for?', '{"A":"Corona Virus Infection Disease","B":"Contagious Viral Disease","C":"Coronavirus Disease","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Full Form: Coronavirus DiseaseOfficial Name Announced: 11 February 2020Announced By: World Health Organization (WHO)Causing Virus: SARS-CoV-2First Reported: Wuhan, China (December 2019)Last verified on 11-07-2026', 0, 0, 0, 1790965691854) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_afb32c2f27404bdc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'TCP stands for _____?', '{"A":"Transfer Communication Protocol","B":"Transmission Communication Process","C":"Transmission Control Protocol","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation TCP stands for Transmission Control Protocol.It is one of the main protocols of the Internet Protocol Suite.It was introduced in 1974.Robert Kahn and Vint Cerf are recognized as key inventors/developers of TCP/IP.Last verified on 03-09-2026', 0, 0, 0, 1790965691910) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_b9a045977188f6f7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'MRI is stands for _____?', '{"A":"Magnetic Resonance Imaging","B":"Magnetic Related  Imaging","C":"Both A and B","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation MRI stands for Magnetic Resonance Imaging.It is a medical imaging technique.It uses strong magnetic fields and radio waves to create detailed images of organs and tissues.Last verified on 03-09-2026', 0, 0, 0, 1790965691910) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_5f99c23577dbb5d8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'IBM stands for?', '{"A":"International Business Machine","B":"Integrated Business Machine","C":"Information Business Machines","D":"International Business Model","E":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation IBM: International Business Machines CorporationNickname: Big BlueFounded: June 16, 1911Headquarters: Armonk, New York, USANature: American multinational technology corporationOperations: Over 175 countriesFounders: Herman Hollerith, Charles Ranlett Flint, Thomas J. WatsonLast verified on 03-09-2026', 0, 0, 0, 1790965691910) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_78afbf71a9e26248', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'WASA stands for?', '{"A":"Water and Social Agency","B":"Water Supply Agency","C":"Water and Sanitation Agency","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation WASA: Water and Sanitation Agency.Established: 1976.Parent organization (Lahore): Lahore Development Authority (LDA).Main services: Water supply, sewerage, and drainage.Location: Lahore, Pakistan.Last verified on 02-09-2026', 0, 0, 0, 1790965691910) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_bf4eb2b23a817b76', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'NADRA stands for?', '{"A":"National Database and Registration Authority","B":"National Database and Registrar Authority","C":"Nation Database and Registrar Authority","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation NADRA stands for National Database and Registration AuthorityMotto: Empowerment through IdentityUnder the control of the Interior Secretary of PakistanEstablished on 10 March 2000Headquarters: IslamabadLast updated question by NA on 07 May 2026', 0, 0, 0, 1790965691910) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_77cdd8aed1d3029d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'PIA stands for?', '{"A":"Pakistan International Airlines","B":"Pakistan International Airport","C":"Pak International Airlines","D":"None of thesse"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation PIA stands for Pakistan International Airlines.It is an international airline that serves as the national flag carrier of Pakistan.Founded: 1946Headquarters: KarachiLast verified on 02-09-2026', 0, 0, 0, 1790965691910) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_b43cbfc124c8d7e4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'URL has an abbreviation of?', '{"A":"Uniform Resource Locator","B":"Universal Resource Link","C":"Uniform Reference Link","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation URL stands for Uniform Resource Locator.It is a specific type of Uniform Resource Identifier (URI).Domain: World Wide WebFirst published: 1994Latest version: Living Standard, 2023Used:Web page (HTTP/HTTPS)File transfer (FTP)Email (mailto)Database access (JDBC)Last verified on 08-06-2026', 0, 0, 0, 1790965691910) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_44cd7b8715e5e520', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'DNA is the abbreviation of _______?', '{"A":"Decomposednucleic Acid","B":"Degeneratenucleic Acid","C":"Deoxyribonucleic Acid","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation DNA stands for Deoxyribonucleic Acid.DNA is a biological molecule found in all living cells.It carries genetic information from parents to offspring.It controls growth, development, and body functions.DNA is present in the nucleus of cells (mainly in chromosomes).It is made of nucleotides arranged in a double helix structure.It was discovered by James Watson and Francis Crick (1953 structure model).Last verified on 01-06-2026', 0, 0, 0, 1790965691910) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_bbd972d444bde5c4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'CNN stands for ____?', '{"A":"Cable News Network","B":"Commercial News Network","C":"Common News Network","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation CNN is a major American television news channel.Its full form is Cable News Network.It was founded on 1st June 1980 by Ted Turner.CNN is famous for 24-hour global news coverage.It was the first channel to provide continuous news broadcasting.Last verified on 17-05-2026', 0, 0, 0, 1790965692013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_1b7cf454fb9884c4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'BRT stands for?', '{"A":"Bus Rapid Transit","B":"Basic Road Transport","C":"British Railway Transport","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation BRT stands for Bus Rapid Transit.The BRT project started in October 2017.Built at a cost of Rs 70 billion.It features a 27.5 kilometre-long corridor track.Includes 31 stations along the main route.Has 7 feeder routes stretching 62 km.These feeder routes include 146 stops.The system is designed to facilitate thousands of passengers daily.Last verified on 19-04-2026', 0, 0, 0, 1790965692013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_73c58efd2ceb8692', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'HTML stands for _____?', '{"A":"Hypertext Mark Language","B":"Hypertext Markup Language","C":"Hi Tech Meaningful Language","D":"Hypertext Markup Link"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation HTML: Hypertext Markup Language.Purpose: Creates and structures web pages.HTML File Extension: .html or .htm.It uses tags to structure content such as headings, paragraphs, images, links, and tables.Last verified on 11-08-2026', 0, 0, 0, 1790965692013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_cb4f40d354c41e95', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'PLO stands for?', '{"A":"Public Law Office","B":"Palestinian Labor Organization","C":"Palestine Liberation Organization","D":"Pacific Legal Office"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation PLO stands for Palestine Liberation Organization.Established: 28 May 1964Place: JerusalemFounded under: Arab LeagueFirst Chairman: Ahmad ShukeiriPurpose: To represent the Palestinian people and pursue Palestinian national rights.', 0, 0, 0, 1790965692013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_a15167a9b90ae502', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'BIOS stands for ______?', '{"A":"Board Input Output System","B":"Back Input Output System","C":"Basic Input Output System","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation BIOS stands for Basic Input Output System.Additional information:BIOS is a firmware stored on a computer’s motherboard.Initializes hardware during booting and provides runtime services.Acts as an interface between operating system and hardware.Last verified on 04-02-2026', 0, 0, 0, 1790965692013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_07b9fd97ecfdb970', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'IESCO stands for ____?', '{"A":"Islamabad Electric Supply Company","B":"International Energy Supply Corporation","C":"Islamabad Environment Services Co.","D":"Independent Energy Solutions Corp"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Full Form: Islamabad Electric Supply CompanyEstablished: 1998Ownership: Government of PakistanHeadquarters: Islamabad, PakistanMain Function: Distribution of electricity in Islamabad and adjoining regionsLast verified on 22-07-2026', 0, 0, 0, 1790965692013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_5fb206887de4ddb5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'PPRA is an abbreviation for?', '{"A":"Public Procurement Regulatory Authority","B":"Pakistan Pilgrimage and Religious Authority","C":"Public Policy and Research Association","D":"Provincial Procurement and Regulatory Authority"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Full Form: Public Procurement Regulatory AuthorityPurpose: Regulation of government procurementFunction: Ensures transparent tendering processEstablished under: Public Procurement ActArea: Pakistan government procurement systemLast verified on 10-06-2026', 0, 0, 0, 1790965692013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_cfc14a1499e4e80d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'FATF stands for?', '{"A":"Financial Action Task Force","B":"Financial Action Tast Force","C":"Financial Action Task Free","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation FATF stands for Financial Action Task Force.Additional information:Founded: 1989Founder: G7 countriesHeadquarters: Paris, FranceOfficial Languages: English, FrenchPresidency Term: 1 yearMembers: 39Main Purpose: Combat money laundering, terrorist financing, and proliferation financing.Last verified on 07-07-2026', 0, 0, 0, 1790965692013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_ecf497a202963f1e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'CPEC stands for _____?', '{"A":"China Pakistan Economic Council","B":"China–Pakistan Economic Corridor","C":"China Pakistan Energy Corridor","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation CPEC stands for China–Pakistan Economic Corridor.It was agreement was formally signed and launched in April 20, 2015 during the visit of Xi Jinping to Pakistan.CPEC was initiated in mid-2013.It is a major network of energy, transport, and infrastructure projects connecting China''s Xinjiang with Gwadar.The initial value of CPEC was about US$46 billion.Last verified on 06-07-2026', 0, 0, 0, 1790965692076) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_7a5043d8691952e7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'WWW stands for ____?', '{"A":"World Whole Web","B":"Wide World Web","C":"Web World Wild","D":"World Wide Web"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation WWW stands for World Wide Web.Additional information:It is an information system.First published: 6 August 1991Founder: Tim Berners-Lee in 1989.Birthplace: CERN near Geneva, Switzerland.Last verified on 01-07-2026', 0, 0, 0, 1790965692076) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_9a93115b2a268ce0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'GDP stands for _____?', '{"A":"Global Petroleum Corporation","B":"Global Demand for Production","C":"Gross Domestic Product","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation GDP (Gross Domestic Product)Definition: Total value of goods and services produced within a country in a yearComponents: Consumption, Investment, Government Spending, Net ExportsPurpose: Measures economic performance and standard of livingUnits: Usually in US dollars or local currencyMajor Example: Pakistan’s GDP in 2025 ≈ $500 billion (nominal)Last verified on 05-02-2026', 0, 0, 0, 1790965692076) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_a94cf8335d09e617', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'FATA stands for _____?', '{"A":"Federally Administrated Territory Areas","B":"Federally Administrated Tribal Areas","C":"Fixed Administrated Tribal Areas","D":"For  Administrated Tribal Areas"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Federally Administered Tribal Areas (FATA) consisted of two types of areas:Tribal Agencies (Tribal Districts)Frontier Regions (FRs)There were Seven Tribal Agencies and Six Frontier Regions.Last verified on 23-03-2026', 0, 0, 0, 1790965692076) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_504245cae5223fb6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'What does NEPRA stand for?', '{"A":"National Electric Power Regulatory Authority","B":"National Energy Policy and Regulation Authority","C":"New Energy Production Regulatory Agency","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation NEPRA is the regulatory authority in Pakistan for electricity generation, transmission, and distribution.It ensures fair pricing, licensing, and standards in the power sector.It was established in 1997.Last verified on 13-05-2026', 0, 0, 0, 1790965692076) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_72a7dfa970cc24a3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'NCOC stands for ______?', '{"A":"National Control and Operation Centre","B":"National Command and Operation Centre","C":"National Coordination and Operation Centre","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The early response to COVID-19 in Pakistan (2020) was led by National Disaster Management Authority (NDMA).Later, a central body was created called National Command and Operation Center (NCOC).NCOC was established in April 2020 on the orders of Prime Minister Imran Khan.It coordinated national efforts against COVID-19.NCOC was officially dissolved on 31 March 2022.Last verified on 30-04-2026', 0, 0, 0, 1790965692076) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_a1d4ca3a7648dc90', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'ALU stands for what?', '{"A":"Arithmetic Logic Unit","B":"Arithmetic and legal unit","C":"Alternating Logic Unit","D":"Alternate Local Unit"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ALU stands for Arithmetic Logic Unit.It is a core part of the CPU (Central Processing Unit).It performs arithmetic operations like addition and subtraction.It also performs logical operations like AND, OR, NOT.It is essential for processing data in a computer system.Last verified on 26-04-2026', 0, 0, 0, 1790965692076) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_ffe8f2fc76c7d81a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'MFN is the abbreviation of?', '{"A":"The most favored nation","B":"The most favorite nation","C":"The most friendly nation","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation MFN stands for Most Favored Nation.It is a principle in international trade (WTO system).It means giving equal trade treatment to all member countries.If one country gets benefits, others must also get the same.Last verified on 24-04-2026', 0, 0, 0, 1790965692076) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_4a8318cefacb97f6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'LED stands for _____?', '{"A":"Light Emitting Diode","B":"Laser Emitting Device","C":"Low Energy Device","D":"Liquid Emitting Display"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation LED (Light Emitting Diode) is a semiconductor device that emits light when electric current passes through it.It is widely used in lighting, displays, electronic indicators, and screens.Additional information:Energy efficiency: Up to 90% more efficient than traditional bulbsFirst discovery: H. J. Round – 1907Early research: Oleg Losev – 1927Practical LED development: James R. Biard – 1961First commercial production: October 1962 (Nick Holonyak)Last verified on 12-03-2026', 0, 0, 0, 1790965692158) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_a5df795b5f0f392b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'CSS stands for _____?', '{"A":"Central Superior Services","B":"Central Service System","C":"Civil Superior Services","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation CSS stands for Central Superior Services.It is a civil service examination and recruitment process in Pakistan for high-ranking government positions.Last verified on 01-02-2026', 0, 0, 0, 1790965692158) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_ec75c18868162dc1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'LNG stands for _____?', '{"A":"Liquid Natural Gas","B":"Liquid Neutral Gas","C":"Liquefied Natural Gas","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation LNG, or liquefied natural gas, is simply natural gas converted into a liquid by cooling it to -260°F (−162 °C).This process reduces its volume by a factor of more than 600.This allows natural gas to be transported efficiently by sea.LNG is mainly constituted of 90% methane and some mixture of ethane, propane, butane, some heavier alkanes, and nitrogen.It is odorless, colorless, non-toxic, and non-corrosive.', 0, 0, 0, 1790965692158) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_6a1bc4898858e2e2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', '''AWACS'' is an abbreviation of ______?', '{"A":"Airborne Warning and Control System","B":"Aircraft Warning and Control System","C":"Aircraft Warning and Coordination System","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Airborne Warning and Control System (AWACS)Provides airborne surveillance, command, control, and early warning for air defense First operational in 1977', 0, 0, 0, 1790965692158) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_3580752bffbb4bd2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'ATM stands for ____?', '{"A":"Automated Teller Machine","B":"Automated Tallest Machine","C":"Auto Transfer of Money","D":"None of These"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Automated Teller Machine (ATM) was invented by John Shepherd Barron.The first model was built and installed in London in 1967.The first ATM in Pakistan was installed in the mid-1980s.', 0, 0, 0, 1790965692158) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_4c72524b0b0e7c08', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'CNG stands for _______?', '{"A":"Composed Natural Gas","B":"Compressed Neutral Gas","C":"Compressed Natural Gas","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation CNG stands for Compressed Natural GasMethane is the main component of CNG the modern use of CNG as a fuel source began in the 1930s, American physicist Dr. J.P. Farley discovered that natural gas could be compressed to a high-pressure natural gas became a transport fuel during the First World War', 0, 0, 0, 1790965692158) ON CONFLICT(id) DO NOTHING;
