INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_64a60f7d09b9172c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'NAFTA stands for _____?', '{"A":"North American Free Trade Agencies","B":"North Alliance Free Trade Agreement","C":"North American Free Trade Agreement","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The NAFTA was signed by Canada, Mexico, and the United States in 1992.North American Free Trade Agreement full form of NAFTA.This agreement created one of the largest free-trade zones.', 0, 0, 0, 1790965692235) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_3c565c53cba8f862', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'GAAP stands for ______?', '{"A":"Generally Accepted Accounting Principles","B":"Generally Adopted Accounting Principles","C":"Generally Accepted Auditing Principles","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation GAAP (Generally Accepted Accounting Principles) is a set of accounting standards used for financial reporting. It ensures consistency, transparency, and accuracy in the preparation of financial statements.', 0, 0, 0, 1790965692235) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_70ff852b1348cc83', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'ICC stands for ______?', '{"A":"International Cricket Council","B":"International Cricket Career","C":"International Cricket Cash","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation International Cricket Council (ICC) Purpose Cricket Regulation Founded 15 June 1909 Headquarters Dubai, UAE', 0, 0, 0, 1790965692290) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_2af69f23ad1d6ff6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'SNGPL stands for _____?', '{"A":"Sui Northern Gas Pakistan Limited","B":"Sui Northern Gas Pipelines Limited","C":"Sui Northern Gas Pipeline Lahore","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation SNGPL stand for Sui Northern Gas Pipelines Limited. SNGPL was incorporated as a private limited Company in 1963.Converted into a public limited company in January 1964.***RY5022023', 0, 0, 0, 1790965692290) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_c2ddc2e86c5c2fb9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'LPG stands for _____?', '{"A":"Liquefied Pressure Gass","B":"Liquefied Per Gram","C":"Liquefied Petroleum Gas","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation LPG stand for Liquefied Petroleum Gas*****In order to supply fuel efficiently to the populace, we have four LPG Storage and Bottling Plants, one each in Karachi, Lahore, Dhurnal, and Akora Khattak.LPG is used as a fuel gas in heating appliances, cooking equipment, and vehiclesLPG is prepared by refining petroleum or "wet" natural gas, LPG was first produced in 1910 by Walter O. Snelling.', 0, 0, 0, 1790965692290) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_52adde92eeafaaf9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'The term DFA stands for ____?', '{"A":"Demand For Approval","B":"Draft For Approval","C":"Demand For Allowance","D":"Demand For Authentication"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "DFA" stands for "Designated for Assignment".In sports jargon, where a player''s contract is temporarily removed from the team''s active roster.In a different context, "Draft for Approval" refers to a document or proposal awaiting final decision from an approving authority.', 0, 0, 0, 1790965692290) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_c8cb1bcc05d22848', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'RADAR stands for ______?', '{"A":"Radio Adaptor Detection and Ranging","B":"Radio Diagnosing and Ranging","C":"Radio Detection and Ranging","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The term RADAR was coined in 1940 by the United States Navy It is an acronym for "radio detection and ranging".It is a radiodetermination method used to detect and track aircraft, ships, spacecraft, guided missiles, motor vehicles, map weather formations, and terrain.', 0, 0, 0, 1790965692290) ON CONFLICT(id) DO NOTHING;
