INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_0e1ff4532d204ab2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'What does CCTV stand for?', '{"A":"Central Camera Television","B":"Closed Circuit Television","C":"Critical Communication Television","D":"Compact Circuit Television"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation CCTV stands for closed-circuit television It''s a technology that uses video cameras to transmit signals to a limited number of monitors, rather than broadcasting to the public. CCTV is also known as video surveillance.', 0, 0, 0, 1790965692351) ON CONFLICT(id) DO NOTHING;
