INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_ca1d6543cad4a65e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'In Pakistan, IRSA stands for ______?', '{"A":"Indus River System Authority","B":"International River System Authority","C":"Indus River System Agency","D":"Internal Research Systematic Agency","E":"All of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Indus River System Authority (IRSA) is a water regulator in Pakistan, established in 1992 as an act of Parliament.Headquarters Islamabad, PakistanLocation Pakistan: Khyber Pakhtunkhwa, Gilgit-Baltistan, Punjab, Balochistan, Sindh & Azad Kashmir.', 0, 0, 0, 1790965692351) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_dcfb1643215d8e98', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_abbrev', 'India and Pakistan are making a bid for membership of NSG. What does NSG stand for?', '{"A":"Nuclear Suppliers Group","B":"Nuclear Support Group","C":"Nuclear Strategic Group","D":"Non-Nuclear Suppliers Group"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation NSG stands for Nuclear Suppliers Group.It is a multinational body that seeks to prevent nuclear proliferation by controlling the export and re-transfer of materials that may be used to develop nuclear weapons.', 0, 0, 0, 1790965692351) ON CONFLICT(id) DO NOTHING;
