INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_6ca208a331bb4d80', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_science', 'The science rover Perseverance of NASA landed on the Red Planet (Mars) on _____?', '{"A":"18 February 2021","B":"15 February 2021","C":"21 February 2021","D":"25 February 2021"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation NASA’s Perseverance rover landed on Mars on 18 February 2021.It landed in Jezero Crater, an ancient lakebed on Mars.The mission aimed to search for signs of ancient microbial life.It also collected rock and soil samples for possible future return to Earth.Last verified on 06-09-2026', 0, 0, 0, 1790965694230) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_195b787f6f4f10e3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_science', 'Dr. Abdul Salam won the Nobel Prize for physics in the year _____?', '{"A":"1996","B":"1979","C":"1964","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In 1979, Dr. Abdul Salam won the Nobel Prize for physics.Additional information:Received the Nobel Prize for combining two forces: the electromagnetic and weak forcesHe was the second Muslim scientist to get a Nobel Prize.First Pakistani to win a Nobel PrizeBorn in Jhang, Punjab, Jan. 29, 1926Died: Nov. 21, 1996Last verified on 22-07-2026', 0, 0, 0, 1790965694230) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_e21c41e29a4ceb13', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_science', 'Business through the internet is called?', '{"A":"E-Commerce","B":"Courier","C":"Credit card","D":"Online shopping"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation E-commerce, also known as electronic commerce or internet commerce.It is refers to the buying and selling of goods or services using the internet.Last verified on 20-04-2026', 0, 0, 0, 1790965694230) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_06b13542e62e32da', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_science', 'Name the famous book of Ibn-Sina in which he discussed human physiology and medicine?', '{"A":"Al-Qanun","B":"New Renaissance","C":"Tadhkira","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ibn Sina compiled The Canon of Medicine around 1025 AD.It is a five-volume medical encyclopedia written in Arabic.The book remained a standard medical reference in Europe and the Muslim world for centuries.Last verified on 03-04-2026', 0, 0, 0, 1790965694230) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_d70a33259b443160', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_science', 'Corona Virus initiated in which city of China?', '{"A":"Beijing","B":"Wuhan","C":"Tianjin","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first human cases of COVID-19 were reported in December 2019 in Wuhan City, China.The disease is caused by a novel coronavirus, later named SARS-CoV-2.COVID-19 quickly became a global pandemic affecting health, travel, and economies worldwide.Wuhan is a major transport and industrial hub in Hubei Province, China.Last verified on 17-03-2026', 0, 0, 0, 1790965694230) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_47ca899ae3871476', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_science', 'Block Chain technology is used in ______?', '{"A":"Cricket","B":"Crypto Currency","C":"Bricks","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A Blockchain is a chain of blocks that contain information. The data which is stored inside a block depends on the type of blockchain. For Example, A Bitcoin Block contains information about the Sender, Receiver, number of bitcoins to be transferred.', 0, 0, 0, 1790965694230) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_a733565adabfc576', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_science', 'After the discovery of atomic number, scientists noted that atomic number can be used to arrange elements in a systematic way. The atomic number was discovered by _______?', '{"A":"Isaac Newton","B":"James chadwak","C":"Henry Moseley","D":"Albert Einstein"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The atomic number was discovered by Henry Moseley in 1910.Henry Moseley was an English physicist.', 0, 0, 0, 1790965694230) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_d54def4c26e7fde7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_science', 'NASA’s Blue Ghost Mission-2 is planned for which year?', '{"A":"2024","B":"2025","C":"2026","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation NASA''s Blue Ghost Mission-2 is planned for 2026. It will be Firefly Aerospace''s second lunar mission.It is scheduled to deliver payloads to the far side of the Moon.', 0, 0, 0, 1790965694230) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_e74bf804ead90c04', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_science', 'Which one of the following is NOT an essential element of a State?', '{"A":"Population","B":"Territory","C":"Government","D":"Economy"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Economy is not considered an essential element.The four essential elements of a State are:PopulationTerritoryGovernmentSovereignty', 0, 0, 0, 1790965694286) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_53d1c2898b9bb371', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_science', 'The most powerful Space Telescope ever launched is?', '{"A":"Hubble space telescope","B":"James Webb Space Telescope","C":"Voyager-1","D":"Kepler Space Telescope"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation James Webb Space Telescope (JWST) is a space telescope designed primarily to conduct infrared astronomy.24 December 2021: Planned launch date after a delay due to communication issues between the observatory and the Launch VehicleJWST was launched into space on 25 December 2021.JWST is the world’s largest and most powerful space telescope developed by NASA.JWST cost approximately $10 billionSH26-8-2023', 0, 0, 0, 1790965694286) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_a297c37a1aea6d23', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_science', 'Which computer was invented by Attanasoff and Clifford?', '{"A":"Mark I","B":"Z3","C":"ABC","D":"None of these","E":"All of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Vincent Atanasoff and his student Clifford Berry, during the 1940s, created the ABC.ABC was the first electronic digital computer. ABC stands for Atanasoff-Berry Computer. AGM 07.5.23', 0, 0, 0, 1790965694286) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_10a2142ca0bd3e45', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_science', 'What does a computer operator do?', '{"A":"Make programs to solve problems","B":"Normally having a degree in computer science","C":"Operate the device","D":"All of these","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A computer operator makes programs to solve problems, has a degree in computer science & operates the device.computer operator means کمپیوٹر چلانے والا AGM 30.4.23', 0, 0, 0, 1790965694286) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_47fa9b9217c30bbc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_science', 'The term Morphology in Biology deals with:', '{"A":"Study of human beings","B":"Study of form and structure of animals and plants","C":"study of formation of words","D":"Study of meaning","E":"none of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Morphology in Biology Study of the form and structure of animals and plantsThe field of morphology was developed by Johann Wolfgang von Goethe (1790) and independently by the German anatomist and physiologist Karl Friedrich Burdach (1800).whileMorphology in linguists deals with the Study of the formation of words.The term was first used in linguistics by August Schleicher in 1859ND2-08-2023', 0, 0, 0, 1790965694286) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_1c4314c67eb1480d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_science', 'What element has an atomic number of 22 and a mass of 47.90?', '{"A":"Iron","B":"Gold","C":"Titanium","D":"Yttrium"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Titanium element has an atomic number of 22 and a mass of 47.90', 0, 0, 0, 1790965694286) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tg_73766526bb6295b9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_gk_science', 'Indicate the correct answer INVENTION INVENTOR', '{"A":"Television John Logie Baird","B":"Torpedo Samuel Morse","C":"Telegraph Igor Ivanovich Sikorsky","D":"Helicopter Robert Whitehead"}', 'A', NULL, 0, 0, 0, 1790965694286) ON CONFLICT(id) DO NOTHING;
