INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_caa2076595f9d746', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', '_____ is the special type of software and hardware system that provides service to its clients.', '{"A":"Biometric","B":"Web Server","C":"Operating system","D":"Web page"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A web server is a computer program or device that provides a service to another computer program and its user, also known as the client.', 0, 0, 0, 1790966324166) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_f2e2b224324f4184', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'An extended ASCII coding system provides ______________ different characters.', '{"A":"128","B":"256","C":"1024","D":"512","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An extended ASCII coding system provides 256 different characters. ASCII stands for American Standard Code for Information Interchange.Size: 8 bits = 256 codesStandard ASCII: 7 bits = 128 charactersExtra 128: Adds special symbols, accented letters, and graphics', 0, 0, 0, 1790966324166) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_ccf9d64ed116f279', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Short cut key to change font is?', '{"A":"ctrl+}","B":"ctrl+{","C":"Both","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ctrl + Shift + F is the shortcut key for “Change the font" in MS Word.Open the Font dialog box to change the font. Ctrl+Shift+F.Increase the font size. Ctrl+Shift+>Decrease the font size. Ctrl+Shift+<Increase the font size by 1 point. Ctrl+]Decrease the font size by 1 point. Ctrl+[RK11.06.2023', 0, 0, 0, 1790966324166) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d621480d155b61f3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of following is HTML tag', '{"A":"# and #","B":"{ and }","C":"! and ?","D":"< and >"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation HTML stands for HyperText Markup LanguageAll HTML tags must be enclosed within angular < > brackets.The correct sequence of HTML tags for starting a webpage is HTML, Head, Title, BodyWhich character is used to represent the closing of a tag in HTML /*******VU CBT FIA PAPER 30-12-2021,2023', 0, 0, 0, 1790966324166) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_0492ce69c2abb092', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'What is the Standard size of font_?', '{"A":"12","B":"13","C":"15","D":"17"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation MS word Minimum font size: 8Maximum font size: 72Standard font size: 12Ms Word manually font size (1-1638)Ctrl + Shift + P is used to change the font sizeTo increase the font size, press Ctrl + ] .To decrease the font size, press Ctrl + [ .', 0, 0, 0, 1790966324261) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_78d21e05208a5446', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which key is used for Excel to select the whole column highlight?', '{"A":"Shift + space","B":"CTRL + space","C":"Alt + space","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To highlight a column, Ctrl+Space is used.Additional information:Shift + Space is used for row.Help in MS Excel: F1Display active cells in Excel: Shift+BackspaceCurrent date in Excel: Ctrl+;GO TO tab in Ms. Excel: F5 Column highlight: CTRL + spaceSUM formula in MS Excel: ALT + =New worksheet in Excel: Shift + F11Format numbers in comma format: Shift+1Last updated NA on 10-09-2026', 0, 0, 0, 1790966324261) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_1176edef6f07364e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'In which of the following form, data is stored in the computer ___ ?', '{"A":"Decimal","B":"Binary","C":"Hexa Decimal","D":"Octal"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Data in any computer always stored and send in binary form. Binary form means 1 and 0.', 0, 0, 0, 1790966324261) ON CONFLICT(id) DO NOTHING;
