INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_95469f1cee177a8a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_general', 'Which of following action removes a sheet from workbook?', '{"A":"Select the sheet, then choose Edit > Delete Sheet","B":"Select the sheet then choose Format > Sheet > Hide","C":"Both","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To removes a sheet from workbook select the sheet, then choose Edit > Delete Sheet these options available in excel 2003 and earlier version.In Microsoft Excel 2007 onward Choose Home > Delete > Delete Sheet on the Ribbon.', 0, 0, 0, 1790966325747) ON CONFLICT(id) DO NOTHING;
