INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_a96efc721b79f34f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_abbrev', 'IC stand for _________?', '{"A":"Integrated Circuit","B":"Intelligence Community","C":"Intensive Care","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation the integrated circuit is a set of electronic circuits on one small flat piece of semiconductor material, usually silicon.', 0, 0, 0, 1790966334327) ON CONFLICT(id) DO NOTHING;
