INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_0c152077a9cda28e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_history', 'Third generation computers used ______?', '{"A":"Vacum  Tubes","B":"Transistors","C":"Integrated circuits","D":"Artificial Intelligence"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Third Generation (1965–1971): Integrated Circuits (ICs)A small semiconductor chip, usually made of silicon.Contains many tiny electronic components, including transistors/MOSFETs.Additional information:First Generation (1946–1959): Vacuum tubesSecond Generation (1959–1965): TransistorsThird Generation (1965–1971): Integrated Circuits (ICs)Fourth Generation (1972–1980): VLSI and microprocessors', 0, 0, 0, 1790966334455) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_582642ff16c26e80', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_history', 'IBM 1401 is_____?', '{"A":"Fourth generation computer","B":"First generation computer","C":"Third generation computer","D":"Second generation computer","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation IBM 1401 belongs to the second generation. Second generation of computers: 1956 to 1963Used in the second generation: TransistorsAdditional information:IBM stands for International Business MachinesFounded on June 16, 1911. Formerly: Computing-Tabulating-Recording Company (1911–1924)Renamed to IBM: 1924Founders George Winthrop FairchildCharles Ranlett FlintHerman HollerithHeadquarters: 1 Orchard Road, Armonk, New York, United StatesArea served: 170 countries', 0, 0, 0, 1790966334455) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_d23eb17ca6245bbe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_history', 'IBM stands for?', '{"A":"International Business Machine","B":"Integrated Business Machine","C":"Information Business Machines","D":"International Business Model","E":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation IBM: International Business Machines CorporationNickname: Big BlueFounded: June 16, 1911Headquarters: Armonk, New York, USANature: American multinational technology corporationOperations: Over 175 countriesFounders: Herman Hollerith, Charles Ranlett Flint, Thomas J. WatsonLast verified on 03-09-2026', 0, 0, 0, 1790966334455) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_6c5ec01c56e23490', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_history', 'Who is known as the father of computer?', '{"A":"Barbara Liskov","B":"Tim Berners-Lee","C":"Charles Babbage","D":"John von Neumann"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Charles Babbage is known as the Father of the Computer.He designed the more advanced Analytical Engine, which featured a "Mill" (CPU) and a "Store" (memory).Additional information:He was an English polymath.Born: 26 December 1791 London, EnglandDied: 18 October 1871 (aged 79) London, EnglandLast updated on 09-03-2026', 0, 0, 0, 1790966334455) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_eb047cef7a0463d5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_history', 'Who develop the idea for universal turing machines which become the basis for the first computer?', '{"A":"Bill gates","B":"Alan Turing","C":"Babbage","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Charles Babbage designed the first concept of a programmable mechanical computer, earning him the title Father of the Computer.Alan Turing developed the theoretical foundation of modern computers and is regarded as the Father of Theoretical Computer Science and Artificial Intelligence.', 0, 0, 0, 1790966334455) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_08772f17064ae47d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_history', 'Abacus was the first___?', '{"A":"mechanical computer","B":"mechanical calculator","C":"Electronic computer","D":"electronic calculator"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Abacus was the first mechanical calculatorAbacus was invented by Tim Cranmer.Abacus was invented in 1962.', 0, 0, 0, 1790966334455) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_05a2bb185cfeb98b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_history', 'UNIVAC is a _________?', '{"A":"Universal Automatic Computer","B":"First-generation computing device","C":"Both A and B","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation UNIVAC (Universal Automatic Computer) was the first commercially produced computer.It delivered to the U.S. Census Bureau in 1951. It was a first-generation computing device.It is using vacuum tubes for processing, like ENIAC.', 0, 0, 0, 1790966334455) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_23f12dff1c07fda7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_history', 'First generation computer use _____ technology.', '{"A":"Vacum  Tubes","B":"Transistors","C":"Integrated circuits","D":"None of these"}', 'A', NULL, 0, 0, 0, 1790966334455) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_9a0d31750415ba27', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_history', 'Who invented liquid crystal display panel?', '{"A":"Louis Zanoni","B":"David Sarnoff","C":"George Heilemier","D":"Friedrich Reinitor"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A liquid-crystal display is a flat-panel display or other electronically modulated optical device that uses the light-modulating properties of liquid crystals combined with polarizers. Liquid crystals do not emit light directly,instead using a backlight or reflector to produce images in color or monochrome.', 0, 0, 0, 1790966334530) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_564ed2aac4a6bd60', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_history', 'Who invented the first computer?', '{"A":"Barbara Liskov","B":"Tim Berners-Lee","C":"John von Neumann","D":"Charles Babbage"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Charles Babbage is known as the Father of the Computer.He was an inventor from the UK.He was born in 1791.He was died in 1871.', 0, 0, 0, 1790966334530) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_283afd05594dae24', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_history', 'Which of the following technologies was used in fifth generation computer??', '{"A":"Vacum  Tubes","B":"Transistors","C":"Integrated circuits","D":"Artificial intelligence"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Artificial intelligence is intelligence demonstrated by machines, as opposed to the natural intelligence displayed by humans or animals.First generation (1940 - 1956) vacuum tubes as a major piece of technology. The ENIAC is example of 1st generation computer.Second generation (1956 - 1963) use of transistors.Third generation (1964 - 1971) use of Integrated circuits.Fourth generation (1972 - 2010) use of the microprocessorFifth generation (2010 to present) use Artificial intelligence*********FIA VU CONSTABLE PAST PAPER 2021', 0, 0, 0, 1790966334530) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tc_869fa5f60b4307e2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_comp_history', 'Microprocessors was introduced in which generation of computer?', '{"A":"Second Generation","B":"Fourth Generation","C":"Third Generation","D":"Both (A) and (B)"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Microprocessors are used in many other electronic devices, including:Computers,Digital systems,CalculatorsInventor of Microprocessors: Marcian E HoffMicroprocessors in 4th generation computer.ND7-5-2023AGM 09-2-2023', 0, 0, 0, 1790966334530) ON CONFLICT(id) DO NOTHING;
