INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_26536b0495bb754d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Pakistan`s largest seaport is ?', '{"A":"Port of Karachi","B":"Muhammad Bin Qasim Port","C":"Gwadar port","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Largest & busiest seaport: Port of KarachiLocation: Karachi, Arabian SeaCargo handled: About 60% of Pakistan’s cargoHarbour size: 32 kmOpened: 1857Additional information:Muhammad Bin Qasim Port: Also called Port Qasim; located near Karachi.Gwadar Port: Deep-sea port in Balochistan; developed as part of CPEC.', 0, 0, 0, 1790967393715) ON CONFLICT(id) DO NOTHING;
