INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_199c1775de01e8e5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'When was the Objectives Resolution passed?', '{"A":"12 March 1947","B":"12 March 1948","C":"12 March 1949","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Adopted: 12 March 1949 Adopting Body: Constituent Assembly of Pakistan Presented By: Prime Minister Liaquat Ali Khan Date of Presentation: 7 March 1949Additional information:Total Members of Assembly: 75 Members Supporting the Resolution: 21 Minority Members: 10 All amendments proposed by minority members were rejected. As a result, all 10 minority members voted against the resolution.Last Updated on 12-01-2026', 0, 0, 0, 1790967393715) ON CONFLICT(id) DO NOTHING;
