INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8d3316378894a1e6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'In which year Swat was merged to Pakistan?', '{"A":"1870","B":"1869","C":"1969","D":"1970","E":"2014"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Swat officially merged into Pakistan on July 28, 1969. Nov 3, 1947: Swat acceded to Pakistan, keeping internal autonomy.Jul 28, 1969: Yahya Khan fully merged Swat, Dir, and Chitral into Pakistan.KNOWN ABOUT SWATDistrict in Malakand Division, Khyber Pakhtunkhwa, PakistanCapital: Saidu SharifLargest city: MingoraGwalerai — famous for applesLast updated NA on 10-09-2026', 0, 0, 0, 1790967393737) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_217ed5d219b242af', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'KANUPP is the abbreviation of ______?', '{"A":"Karachi Nuclear Power Project","B":"Karachi Nuclear Power Plant","C":"Karachi National Power Plant","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation KANUPP stands for Karachi Nuclear Power Plant.It is located in Karachi, Sindh.It was Pakistan’s first nuclear power plant.The original K-1 was developed with Canadian assistance.It began commercial operation in 1972.K-2 and K-3 are newer units developed with Chinese cooperation.Last verified on 09-09-2026', 0, 0, 0, 1790967393737) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7909a7c66f5a8ae4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Pakistan successfully tested five nuclear devices at Chaghi on _____?', '{"A":"May 25 1998","B":"May 20 1998","C":"May 28 1998","D":"None of these"}', 'C', NULL, 0, 0, 0, 1790967393737) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ea266e80c7366205', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who introduced Two Nations Theory in the subcontinent?', '{"A":"Muhammad Ali Jinnah","B":"Sir Syed Ahmad Khan","C":"Allama Muhammad Iqbal","D":"Zafar Ali khan"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Presented by: Sir Syed Ahmad KhanFamous Speech: Meerut SpeechDate: 16 March 1888Purpose: To explain that Muslims and Hindus were separate nations with different religious, cultural, and social identities.Importance: Became the ideological foundation of Pakistan.Last verified on 10-07-2026', 0, 0, 0, 1790967393737) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e8a4cbc40a35777d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'OGRA stands for _____?', '{"A":"Oil and Gas Regulatory Authority","B":"Oil and Gas Resource Association","C":"Oil and Gas Research Agency","D":"Oil and Gas Regulation Authority"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation OGRA stands for Oil and Gas Regulatory Authority.It is the regulatory body responsible for overseeing the oil and gas sector in Pakistan.It was established in 2002.It to ensure a fair and transparent regulatory framework for the exploration, production, transportation, and distribution of oil and gas resources.Last verified on 07-09-2026', 0, 0, 0, 1790967393737) ON CONFLICT(id) DO NOTHING;
