INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_5e9501b22fdb22e4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who chose the name of Pakistan?', '{"A":"Allama Iqbal","B":"Quaid-e-Azam","C":"Chaudry Rehmat Ali","D":"Hafiz Jalandhri"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Choudhry Rahmat Ali coined the name "Pakistan" He first used the name in his pamphlet titled "Now or Never; Are We to Live or Perish Forever?" On January 28, 1933. The word means "Land of the Pure" in Persian and Urdu (Pak means pure, and stan means land)He first thought of the name in 1932 while on a London bus,The name was also designed as an acronym for the Muslim-majority regions of northern British IndiaPunjab Afghania (North-West Frontier Province)KashmirSindh Baluchistan Last updated by NA on 5-09-2026', 0, 0, 0, 1790967393755) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_74f8be083207235e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who presented the Objective Resolution in the constituent Assembly?', '{"A":"Liaquat Ali Khan","B":"Quaid-e-Azam","C":"Abdul Ghuffar Khan","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Presented By: Prime Minister Liaquat Ali KhanAdopted: 12 March 1949Adopting Body: Constituent Assembly of PakistanDate of Presentation: 7 March 1949Additional information:Total Members of Assembly: 75Members Supporting the Resolution: 21Minority Members: 10All amendments proposed by minority members were rejected.As a result, all 10 minority members voted against the resolution.Last Updated on 12-01-2026', 0, 0, 0, 1790967393755) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_16b6b32ebea1b98c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'FBR is the abbreviation for _____?', '{"A":"Federal Board of Research","B":"Federal Board of Revenue","C":"First Board of Revenue","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation FBR stands for Federal Board of Revenue.It is Pakistan’s principal federal tax administration authority.Headquarters: Islamabad, Pakistan.FBR works to collect federal taxes and enforce tax laws.It operates under the Ministry of Finance, Government of Pakistan.Last verified on 05-09-2026', 0, 0, 0, 1790967393755) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_995a65ee4099a1dd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'FIR stands for _______?', '{"A":"First Information Regular","B":"First Information  Report","C":"First in charge Report","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation FIR stands for First Information Report.It a document prepared by police under Section 154 of the Code of Criminal Procedure (CrPC) 1898.It starting criminal proceedings in cognizable cases.Last verified on 11-05-2026', 0, 0, 0, 1790967393755) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e6527ae1c486ffbf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'PAEC stands for?', '{"A":"Pakistan Atomic Energy Commission","B":"Pakistan Atomic Employment Commission","C":"Basic Pay Scales","D":"None of above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation PAEC stands for Pakistan Atomic Energy Commission.It was established in 1956.Headquarters: Islamabad, Pakistan.PAEC is a federally funded government organization.It is mainly concerned with the peaceful uses of nuclear technology in Pakistan.Last verified on 05-09-2026', 0, 0, 0, 1790967393755) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d64fdc9a73ac3d62', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'MNA stands for _______?', '{"A":"Member of National Assembly","B":"Media Networking Area","C":"Multi-National Architecture","D":"Medical Nurse Association"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation MNA stands for Member of the National Assembly.Pakistan’s National Assembly has 336 seats.An MNA is an elected representative in the lower house of Parliament.The normal term of the National Assembly is 5 years, unless dissolved earlier.MNAs are elected through general elections.Last verified on 04-09-2026', 0, 0, 0, 1790967393755) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_fa532733a248f907', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'According to Population, Pakistan is ________ largest country in the world.', '{"A":"4th","B":"5th","C":"6th","D":"7th"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan is the world''s fifth-most populous country.The population density in Pakistan is 287 per km² (742 people per mi²).Pakistan world''s second-largest Muslim population.The top 10 most populous countries in the world:ChinaIndiaThe United StatesIndonesiaPakistanBrazilNigeriaBangladeshRussia MexicoLast verified on 04-09-2026', 0, 0, 0, 1790967393755) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e07bcba5fc85065b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'In which area of Pakistan 2000 Old Forest (Oldest Forest of Pakistan) is found?', '{"A":"Skardu","B":"Chitral","C":"Ziarat","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The oldest forest in Pakistan is found in Ziarat (Juniper Forest).It is famous for ancient juniper trees, some over 2000 years old.Ziarat Juniper Forest is sometimes called a “living museum of ancient trees” due to its extreme age and ecological importance.Changa Manga (largest planted forest in Pakistan)Last verified on 21-04-2026', 0, 0, 0, 1790967393755) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_789ad249322c8cbf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The Iran Pakistan gas pipeline is also called ______?', '{"A":"Friendship pipeline","B":"Future pipeline","C":"Peace Pipeline","D":"Unity Pipeline"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Other name: Peace PipelineCountries: Iran and PakistanPurpose: Transportation of natural gasProposed length: 2,775 kmPakistan President at inauguration ceremony: Asif Ali ZardariIranian President: Mahmoud AhmadinejadInauguration: 11 March 2013Last verified on 04-09-2026', 0, 0, 0, 1790967393773) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2faa99dffd75fb9d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'NAB stands for ______?', '{"A":"National and Badminton","B":"National Audit Branch","C":"National Accountability Bureau","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The National Accountability Bureau (NAB) is Pakistan''s lead anti-corruption agency.It established by Pervez Musharraf on November 16, 1999.Its headquarters are in Islamabad.It focuses on combating political corruption and ensuring accountability.Last verified on 04-09-2026', 0, 0, 0, 1790967393773) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9796234a1d6abcc5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which country is in the north west of Pakistan?', '{"A":"China","B":"India","C":"Iran","D":"Afghanistan"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Afghanistan is located to the north-west of Pakistan.Pakistan shares its longest land border (2,640 km) with Afghanistan.The border between Pakistan and Afghanistan is called the Durand Line.Additional information:East: IndiaNorth-east: ChinaSouth-west: IranSouth: Arabian SeaLast verified on 06-07-2026', 0, 0, 0, 1790967393773) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_137fa023c9f77243', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which country is situated in the east of Pakistan?', '{"A":"India","B":"China","C":"Iran","D":"Afghanistan"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation East: India 🇮🇳West: Afghanistan 🇦🇫 and Iran 🇮🇷North/Northeast: China 🇨🇳South: Arabian Sea 🌊Last verified on 03-09-2026', 0, 0, 0, 1790967393773) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_410928b0de198055', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which of the following lies in the South of Pakistan?', '{"A":"Indian Ocean","B":"China","C":"Arabian Sea","D":"Strait of Humoz"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Arabian Sea lies in the South of Pakistan.It is located south of Pakistan with a coastline of 1,046 kilometers.Addtional information:Pakistan is located in the North-West of India.Pakistan is located east is India, which has a 2,912 km border with Pakistan.To its west is Iran, which has a 909 km border with Pakistan.Iran and Pakistan are located in the North of the Arabian Sea.In the southern area of Pakistan, there is a mountain range called: Kirther RangeLast verified on 30-03-2026', 0, 0, 0, 1790967393773) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ed43b62e95eac3dd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The Line of Control came into existence in _____?', '{"A":"1972","B":"1949","C":"1957","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Line of Control (LoC) was established in 1949 after the Karachi Agreement.It was following the first Indo-Pak war over Kashmir.It was originally called the Ceasefire Line and renamed the LoC in the 1972 Simla Agreement.The LoC is approximately 740 km long.Last verified on 03-09-2026', 0, 0, 0, 1790967393773) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_901488fea0825072', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The Tashkent declaration between Pakistan and India was signed on?', '{"A":"10 January 1966","B":"1 January 1965","C":"15 January 1964","D":"1 February 1966"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Date Signed: 10 January 1966Place: Tashkent, Soviet Union (now Uzbekistan) It was a peace treaty between India and Pakistan following the 1965 warSignatories:Ayub Khan – President of PakistanLal Bahadur Shastri – Prime Minister of IndiaAlexei Kosygin – Premier of USSR (mediator)Last verified on 16-01-2026', 0, 0, 0, 1790967393773) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_99ade26995b8f3f2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who introduced the Basic Democracy?', '{"A":"Liaquat Ali Khan","B":"Ayoub Khan","C":"Muhammad Ali Bogra","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation After the Martial Law of 1958, General Muhammad Ayub Khan introduced the Basic Democracy System in 1959.It created a local government structure and an indirect electoral system in Pakistan.Additional information:Total Basic Democrats: 80,000East Pakistan: 40,000West Pakistan: 40,000These 80,000 members formed the Electoral College to elect the President and Assemblies.Last verified on 07-03-2026', 0, 0, 0, 1790967393773) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_0cb96afeec045219', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'APTMA stands for ______?', '{"A":"All Pakistan Textile Manufacturing Agency","B":"All Pakistan Textile Merchants Association","C":"All Pakistan Textile Mills Association","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation APTMA officially stands for All Pakistan Textile Mills Association.It represents spinning, weaving, processing, and composite textile mills.Additional information:Founded: 1958Role: Protects interests of textile industry and promotes exportsLast verified on 25-01-2026', 0, 0, 0, 1790967393795) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_cb536a26e957876d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'WASA stands for?', '{"A":"Water and Social Agency","B":"Water Supply Agency","C":"Water and Sanitation Agency","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation WASA: Water and Sanitation Agency.Established: 1976.Parent organization (Lahore): Lahore Development Authority (LDA).Main services: Water supply, sewerage, and drainage.Location: Lahore, Pakistan.Last verified on 02-09-2026', 0, 0, 0, 1790967393795) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_217fe551dc44a1ae', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'NHA is the abbreviation of _____?', '{"A":"Natural Highway Authority","B":"National Highway Authority","C":"New Highway Authority","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Abbreviation: NHAFormation: 1991Headquarters: Islamabad, PakistanOfficial language: Urdu and EnglishMinistry: Ministry of CommunicationsRole: Construction and maintenanceResponsible for: National highways and motorwaysLast updated 26-07-2026 by NA', 0, 0, 0, 1790967393795) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6ca638b87e08074f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Ahmadis were declared Non-Muslims in _______?', '{"A":"1975","B":"1974","C":"1976","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Year: 1974Amendment: Second Constitutional AmendmentPrime Minister: Zulfikar Ali BhuttoFounder of Ahmadiyya movement: Mirza Ghulam AhmadConstitution: Constitution of Pakistan, 1973Last verified on 02-09-2026', 0, 0, 0, 1790967393795) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b9d44706de88c321', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'PAEC is the abbreviation of ____?', '{"A":"Pakistan Atomic Energy Conference","B":"Pakistan Atomic Energy Commission","C":"Pakistan Agriculture Efficiency Commission","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation PAEC stands for Pakistan Atomic Energy Commission.It was established in March 1956 by Prime Minister Huseyn Suhrawardy.Nazir Ahmad, an experimental physicist, was appointed its first Chairman.PAEC is responsible for promoting the peaceful applications of nuclear technology in Pakistan.Last verified on 02-09-2026', 0, 0, 0, 1790967393795) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_83cac8dc394f9065', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'In which reforms Muslims demand of separate electorate was incorporated/introduced?', '{"A":"Minto-Hastings Reforms","B":"Minto-Morley Reforms","C":"Minto-Warren Reforms","D":"Minto-Cornwallis Reforms"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Indian Councils Act 1909, also called the Morley-Minto Reforms, introduced separate electorates for Muslims.Additional information:Date of introduction: 12 March 1909Total members in Central Legislative Council: 60Muslim reserved seats: 527 members were to be elected from different constituencies.Nehru Report (28 August 1928) rejected the demand for separate electorate.Last verified on 07-03-2026', 0, 0, 0, 1790967393795) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2b706a3e381f22e2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'NADRA stands for?', '{"A":"National Database and Registration Authority","B":"National Database and Registrar Authority","C":"Nation Database and Registrar Authority","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation NADRA stands for National Database and Registration AuthorityMotto: Empowerment through IdentityUnder the control of the Interior Secretary of PakistanEstablished on 10 March 2000Headquarters: IslamabadLast updated question by NA on 07 May 2026', 0, 0, 0, 1790967393795) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_1bf3d78c8fb86bf7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'PIA stands for?', '{"A":"Pakistan International Airlines","B":"Pakistan International Airport","C":"Pak International Airlines","D":"None of thesse"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation PIA stands for Pakistan International Airlines.It is an international airline that serves as the national flag carrier of Pakistan.Founded: 1946Headquarters: KarachiLast verified on 02-09-2026', 0, 0, 0, 1790967393795) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_fa17662ee506b52b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The length of LOC (Line of Control) in Kashmir is about?', '{"A":"740 km","B":"460 miles","C":"Both A and B","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Length: 740 km / 460 milesNamed after: Shimla Agreement (1972)Type: Military control line (not official border)Region: Jammu & KashmirCountries: Pakistan and IndiaLast verified on 12-06-2026', 0, 0, 0, 1790967393818) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_936596f354f0f043', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which is the most widely spoken language in Pakistan?', '{"A":"Urdu","B":"Sindhi","C":"Pashto","D":"Punjabi"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The percentage of Punjabi-speaking people in Pakistan is 39%.Additional information:Sindhi speaking in Pakistan: 15%Pashto speaking in Pakistan: 18%Urdu in speaking Pakistan: 8%Balochi speaking in Pakistan: 3%', 0, 0, 0, 1790967393818) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_42c83430b39c7e25', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who was the founder of Khaksar Tehreek (Khaksar Movement)?', '{"A":"Syed Abu-ala-Maududi","B":"Allama Inayatullah Mashraqi","C":"Maulana Abu-al-Kalam Azad","D":"Syed Atta-Ullah Shah Bukhari"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Khaksar Movement was established by Allama Inayatullah Mashraqi in 1931.It was a social movement based in Lahore, Punjab, British India.The movement aimed to free India from British rule.Allama Mashriqi disbanded the Khaksar Tehrik on July 4, 1947.Last verified on 01-09-2026', 0, 0, 0, 1790967393818) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_cf47756716ac2e26', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'What is the old name of Lahore?', '{"A":"Mansoora","B":"Bilalabad","C":"Mahmood pur","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Last verified on 01-09-2026', 0, 0, 0, 1790967393818) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f2dbe66ab568102c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'FIA stands for?', '{"A":"First Investigation Agency","B":"Federal Investigation Agency","C":"Federal Investigation Agent","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation FIA stands for Federal Investigation Agency.It was established under the FIA Act, 1974 to investigate federal-level crimes.Formed: 13 January 1975.Headquarters: Islamabad, Pakistan.Parent Ministry: Ministry of Interior.Last verified on 01-09-2026', 0, 0, 0, 1790967393818) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b143fc20355b15ec', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which country is located west of Pakistan?', '{"A":"Oman","B":"China","C":"India","D":"Iran"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan shares its western border with Iran.It is approximately 909 km long.It is also bounded by Afghanistan to the northwest and north.China to the northeast.India to the east and southeast.These borders define Pakistan''s geostrategic location in South Asia.Last verified on 01-09-2026', 0, 0, 0, 1790967393818) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_bac72498f3d6447f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Durand line is between which countries?', '{"A":"Pak-Afganistan","B":"Pak-China","C":"Pak-India","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Durand Line was established as the official border between British India and Afghanistan.It was drawn in 1893.British representative: Sir Mortimer DurandAfghan ruler: Amir Abdur Rahman KhanIt later became the international border between Pakistan and Afghanistan.Length: Around 2,640 kmLast verified on 09-06-2026', 0, 0, 0, 1790967393818) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_07523d7fcc0434ed', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Forests are only _____ of the total area of Pakistan.', '{"A":"6.3%","B":"8.4%","C":"3.6%","D":"4.8%"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Forest has about 4.8% (5%) of the total land area.The total area of Pakistan is 881,913 km.²In Pakistan''s hilly areas, about 40% forest comprises coniferous and scrub forests.The largest forest in Pakistan is Changa Manga.Last verified on 03-02-2026', 0, 0, 0, 1790967393818) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d283b2073f2d97b5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', '"PEMRA" stands for what?', '{"A":"Pakistan Electronic Medium Regulatory Authority","B":"Print and Electronic Media Regulatory Authority","C":"Pakistan Electronic Media Regulatory Authority","D":"Print and Electronic Media Regulatory Authority"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "PEMRA" stands for Pakistan Electronic Media Regulatory Authority.It is the organization responsible for regulating and licensing electronic media in Pakistan.It was established in March 2002.Last verified on 01-09-2026', 0, 0, 0, 1790967393838) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_74e32297d3bb048d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'In which Islamic month Pakistan was founded ?', '{"A":"Ramzan","B":"Muharram","C":"Safr","D":"Rajab"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan was founded in the Islamic month of RamadanOn 27th Ramadan 1366 AH on FridayGregorian Date: August 14, 1947Last updated by NA on 25-April-2026', 0, 0, 0, 1790967393838) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ffd4e3dfa8eb81c0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'MPA stands for?', '{"A":"Member of Pakistan Assembly","B":"Member of Provincial Assembly","C":"Member of Assembly","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation MPA stands for Member of Provincial Assembly.An MPA is an elected representative in a provincial legislative assembly.MPAs participate in making provincial laws and overseeing the provincial government.Additional information:MNA = Member of National Assembly.Last verified on 01-09-2026', 0, 0, 0, 1790967393838) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2b0760b5e168433d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which medal did Arshad Nadeem win in the Men''s Javelin Throw at the Paris Olympics 2024?', '{"A":"Bronze","B":"Silver","C":"Gold","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Medal: GoldWinning Throw: 92.97 mDate: 8 August 2024Origin: Mian Channu, PakistanPrevious Olympic Record: 90.57 m by Andreas Thorkildsen (Beijing 2008)Global Ranking: Sixth longest throw ever; best in the world in 2024Last verified on 02-02-2026', 0, 0, 0, 1790967393838) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b3b975bc5714eb62', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'When was Pakistan’s National Action Plan (NAP) established?', '{"A":"December 25, 2015","B":"December 25, 2016","C":"December 25, 2014","D":"December 25, 2017"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan’s National Action Plan (NAP) was approved on 25 December 2014.It was developed after the Army Public School (APS) attack in Peshawar on 16 December 2014.The plan aimed to strengthen Pakistan’s efforts against terrorism and extremism.It contained 20 points covering counter-terrorism and security measures.Victims: 140 people, including 132 schoolchildren.Last verified on 26-08-2026', 0, 0, 0, 1790967393838) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8d3fd1a45c31ef4b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'BRT stands for?', '{"A":"Bus Rapid Transit","B":"Basic Road Transport","C":"British Railway Transport","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation BRT stands for Bus Rapid Transit.The BRT project started in October 2017.Built at a cost of Rs 70 billion.It features a 27.5 kilometre-long corridor track.Includes 31 stations along the main route.Has 7 feeder routes stretching 62 km.These feeder routes include 146 stops.The system is designed to facilitate thousands of passengers daily.Last verified on 19-04-2026', 0, 0, 0, 1790967393838) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_015d2f35be364938', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which is the largest cantonment of Pakistan?', '{"A":"Quetta Cantt","B":"Kharian Cantt","C":"Karachi Cantt","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kharian Cantonment is regarded as one of the largest cantonments in Pakistan.It is located near Kharian city, District Gujrat, Punjab.The cantonment was developed in the late 1950s with U.S. support.Oldest cantonment: Sialkot CantonmentCantonment Boards: 42Karachi military cantonments: 6Last verified on 23-08-2026', 0, 0, 0, 1790967393838) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_67644630177e50cc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The National Fish of Pakistan is ______?', '{"A":"Mahseer","B":"Flounder","C":"Hogfish","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Mahseer is the National Fish of Pakistan.Mahseer fish are found in every province of Pakistan in semi-cold fresh water.It is also known as the “King of Swat.”Pakistan is an excellent place to find Mahseer.Mahseer is an important freshwater fish of Pakistan.Last verified on 23-08-2026', 0, 0, 0, 1790967393838) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6cfecd6ef31ecd9d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'What is total area of the Pakistan?', '{"A":"899,913 km²","B":"881,913 km²","C":"899,92222 km²","D":"799,92222 km²"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The total area of pakistan 881,913 km².In old books area of Pakistan is 796096 sq km.Pakistan is a country in South Asia.Pakistan world''s second-largest Muslim population.Additional information:Pakistan is the 33rd-largest country by area.The total cultivated area in Pakistan is 25%.The total forest area of Pakistan is estimated at 6.20 million hectares.The forest cover of Pakistan is 5.7%.Last verified on 02-05-2026', 0, 0, 0, 1790967393861) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8d4387d0a10fd569', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Khunjerab pass connects ______?', '{"A":"Pakistan with India","B":"Pakistan with China","C":"Pakistan with Turkey","D":"Pakistan with Iran"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Khunjrab pass connects Pakistan with China.Location: Hunza Pakistan - administered Gilgit–Baltistan and Xinjiang, ChinaRoad name: N-35Range: KarakoramLast verified on 01-07-2026', 0, 0, 0, 1790967393861) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3e4e5f58492875ba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who is the highest wicket taker in ODI and Tests for Pakistan?', '{"A":"Wasim Akram","B":"Waqar Younis","C":"Imran Khan","D":"Abdul Qadir"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Wasim Akram is Pakistan’s highest wicket-taker in both ODI and Test cricket.ODI: 502 wicketsTest: 414 wicketsAdditional information:Highest wicket-taker in T20 for Pakistan: Shadab Khan — 104 wicketsاس سوال کو ضرور پڑھیںWho scored highest Innings score in ODI for Pakistan?پاکستان میں سب سے زیادہ سکور کس نے کیاLast verified on 23-08-2026', 0, 0, 0, 1790967393861) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_86b7a6feb30bfec8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Pakistan is located in _______?', '{"A":"South Asia","B":"West Asia","C":"North Asia","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan, officially the Islamic Republic of Pakistan, is a country in South Asia.It is the world''s fifth-most populous country.It is the world''s second-largest Muslim population.It is the 33rd-largest country by area.The capital of Pakistan is Islamabad.The Currency of Pakistan is the Pakistani rupee.Last verified on 02-04-2026', 0, 0, 0, 1790967393861) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_dc3c53a5920f9b35', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Ibn Battuta, the famous Muslim explorer who came to India during regime of Mohammad Bin Tughlaq, belonged to which country?', '{"A":"Iraq","B":"Iran","C":"Spain","D":"Morocco"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ibn Battuta belonged to Morocco.He was a famous Muslim traveler who visited India during the reign of Muhammad bin Tughlaq.Additional information:Full Name: Abu Abdullah Muhammad ibn Battutah.Born: February 24, 1304, in Tangier, Morocco.Died: 1369, in Marrakesh, Morocco.He served at the court of Muhammad bin Tughlaq in Delhi after reaching India.Last verified on 23-98-2026', 0, 0, 0, 1790967393861) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_67699953d58ae1d9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Pakistan receives rainfall in the months of July to September.', '{"A":"Monsoon","B":"Summer","C":"Winter","D":"Autumn"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan receives most of its seasonal monsoon rainfall from July to September.Winter: December–February — generally cool and dry.Spring: March–May — generally hot and dry.Retreating monsoon: October–NovemberLast verified on 11-08-2026', 0, 0, 0, 1790967393861) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7e1cfdc0a6a4ef74', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Jallianwala Bagh is located in _____?', '{"A":"Lahore","B":"Ameristar","C":"Patiala","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jallianwala Bagh is located in Amritsar, Punjab, India, near the Golden Temple.Massacre: Took place on 13 April 1919.Commander: Brigadier-General Reginald Dyer ordered the troops to fire on the gathering.Casualties: The official British figure recorded 379 deaths, while Indian estimates were considerably higher.Last verified on 11-08-2026', 0, 0, 0, 1790967393861) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8de7a6e2a7f135fa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The largest coal deposits (coal reservoir) in Pakistan are found in?', '{"A":"Thal, Sindh","B":"Thar, Sindh","C":"Thatta, Sindh","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Largest Coalfield: Thar Coalfield, Tharparkar, SindhDiscovery Year: 1991Global Ranking: Among the world''s 16th-largest coal reservesThe Thar Coalfield covers an area of about 9,100 km² in the Thar Desert.Additional information:Sindh: 184.623Punjab: 0.235Balochistan: 0.217Khyber Pakhtunkhwa (KPK): 0.092Azad Jammu & Kashmir (AJK): 0.009Total Coal Reserves: 185.175 billion tonsLast verified on 20-07-2026', 0, 0, 0, 1790967393861) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9edc3911ffaf859a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Saindak Project is famous for _____?', '{"A":"Copper","B":"Silver","C":"Gold","D":"All of the above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Deposits of copper, gold, and silver were discovered in the 1970s.The Saindak Copper-Gold Project is located in Chagai District, Balochistan, Pakistan.Trial production began in 1995.The project has been developed and operated in collaboration with China.Saindak is an important mineral and mining project of Balochistan.Last verified on 11-08-2026', 0, 0, 0, 1790967393881) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d090ac7c596c9d9e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Lal Suhanra National Park is located near?', '{"A":"Bahawalpur","B":"Khanewal","C":"Lahore","D":"Karachi"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Location: Near Bahawalpur, Punjab, Pakistan.Established: 1972.It contains diverse desert, forest, and wetland ecosystems.It is one of the largest national parks in Pakistan.It is recognized by UNESCO as a Biosphere Reserve.Last verified on 11-08-2026', 0, 0, 0, 1790967393881) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_30d0775fdf83e372', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'When did Pakistan join SEATO?', '{"A":"1966","B":"1955","C":"1954","D":"1999"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation SEATO was founded on 8 September 1954.Pakistan joined SEATO in the same year 1954 as a member.It was a Cold War military alliance led by the United States.Pakistan later withdrew its association in the 1970s (after 1972/1973 period changes).SEATO was officially dissolved in 1977.Last verified on 29-04-2026', 0, 0, 0, 1790967393881) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_31cdd3ad8caab1e2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who is known as he father of Civil Service in India?', '{"A":"Muhammad Ali Jinnah","B":"Jawaharlal Nehru","C":"Charles Cornwallis","D":"Louis Mountbatten"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Person: Lord Charles CornwallisPosition: Governor-General of BengalCornwallis Code: 1793Period of major reforms: 1786–1793He is also associated with the Permanent Settlement of Bengal (1793).Last verified on 08-08-2026', 0, 0, 0, 1790967393881) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f68e3586d6f9090c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The Sultan of Delhi who is reputed to have built the biggest network of canals in India was?', '{"A":"IItutmish","B":"Ghiyasuddin Tughlaq","C":"Firoz Shah Tughlaq","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Firoz Shah Tughlaq built the largest network of canals in medieval India.He constructed several canals to improve irrigation and agriculture.He was the third ruler of the Tughlaq dynasty.Additional information:Born: 1309 ADReign: 1351–1388 ADDied: 1388 ADCanals Built: Yamuna–Hissar, Sutlej–Ghaggar, Sirmour Hills–Hansi, Ghaggar–FiruzabadNew Towns Founded: Firozabad, Fatehabad, Jaunpur, HisarLast verified on 06-08-2026', 0, 0, 0, 1790967393881) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ae8eb702e4ed18bb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who was the founder of the Unionist Party?', '{"A":"Liaqat Ali Khan","B":"Sir Fazal Hussain","C":"Molana Fazal ul Haq","D":"Syed Amir Hassan"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Unionist Party was jointly founded by Sir Fazli Husain, Sir Chhotu Ram, and Sir Sikandar Hayat Khan.It was founded in 1923 in Punjab, British India.The party represented the interests of Muslim, Hindu, and Sikh landlords of Punjab.Additional information:1937 Punjab Election: Unionist Party won 98 of 175 seatsMuslim Seats Won: 78 of 89Muslim League Seats: 2Last verified on 06-08-2026', 0, 0, 0, 1790967393881) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_dba135218cee1d2e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who is elect the first Sikh senator of Pakistan?', '{"A":"Ranjeet Singh","B":"Gurdeep Singh","C":"Maneet Singh","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Gurdeep Singh of Pakistan Tehreek-e-Insaf became the first turban-clad Sikh He is a representative from Khyber Pakhtunkhwa in Pakistan''s Senate.He secured 103 votes.While Jamiat Ulema-e-Islam''s Ranjeet Singh got 25 votes.Awami National Party''s Asif Bhatti received 12 votes.', 0, 0, 0, 1790967393881) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_97959b8fbacfae75', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The Pakistan Super League (PSL) 2019 won by ______?', '{"A":"Peshawar Zalmi","B":"Multan Sultans","C":"Quetta Gladiators","D":"Islamabad United"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan Super League (PSL) 2019Edition: FourthDates: 14 Feb – 17 Mar 2019Administrator: PCBFormat: Twenty20Venue: UAE & PakistanFinal venue: KarachiWinner: Quetta Gladiators (1st title)Quetta Gladiators won by: 8 wicketsRunner-up: Peshawar ZalmiParticipants: 6Matches: 34Player of the series: Shane Watson (Quetta Gladiators)Shane Watson made: 430 runsMost runs: Shane WatsonMost wickets: Hasan Ali (Peshawar Zalmi)Hasan Ali took: 25 wickets', 0, 0, 0, 1790967393881) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7f8c77e62f32b054', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which area of Pakistan has the biggest deposits of iron ore?', '{"A":"Kalabagh","B":"Nangarparkar","C":"Mithi","D":"Chachro"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kalabagh has the largest iron ore deposits in Pakistan.Kalabagh is located in Mianwali District, Punjab.The estimated iron ore reserves are about 309 million tons.Additional information:Largest Coal Deposits: Thar Coalfield (Sindh)Uranium Deposits: Dera Ghazi Khan (Punjab)Fuller''s Earth Deposits: Dera Ghazi Khan District (Punjab)Last verified on 04-08-2026', 0, 0, 0, 1790967393900) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_170ac7f11506e7dd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The first census in Pakistan was held in?', '{"A":"1948","B":"1951","C":"1953","D":"1957"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first census in Pakistan was held in 1951.Additional information:Total nationwide censuses in Pakistan: 71st Census: 19512nd Census: 19613rd Census: 19724th Census: 19815th Census: 19986th Census: 20177th Census: 2023Frequency: Every 10 years (approx.)Historical start: 1872 (British rule, first census in the region)Last verified on 17-01-2026', 0, 0, 0, 1790967393900) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_04edb950bc9cf36e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which of the following is the correct group of Kharif Crops?', '{"A":"Groundnut, Bajra, Barley, Sorghum, Wheat","B":"Rice, Millet, Maize, Cotton","C":"Jowar, Bajra, Rice, Cotton, Jute, Gram","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Major Kharif CropsRiceSugarcaneCottonMaizeBajraJowar (Millet)Additional information:Kharif Crop PeriodStart: April – JuneEnd: September – OctoberRabi Crop PeriodSowing: October – DecemberHarvesting: March – MayLast verified on 27-01-2026', 0, 0, 0, 1790967393900) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_eef740e242db53e5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'How many districts are there in Balochistan?', '{"A":"39","B":"40","C":"41","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation As of August 2026, Balochistan has the following 11 divisions. Quetta, Pishin, Khuzdar, Lasbela, Rakhshan, Makran, Naseerabad, Zhob, Sibi, Loralai & Koh-e-Sulaiman.Additional Information:Balochistan currently has 41 districts ad 127 Teshils/Sub Tehsils. ***', 0, 0, 0, 1790967393900) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d1899198293fb187', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'State of Kashmir was the biggest state in the sub-continent situated in the northern part of Indo Pak continent having boundaries with', '{"A":"Tibit","B":"Russia","C":"Afghanistan","D":"All of them"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The state of Kashmir has boundaries with:to the north and east by China (Xinjiang and Tibet), to the northwest by Afghanistan (Wakhan Corridor), to the west by Pakistan (Khyber Pakhtunkhwa and Punjab) to the south by India (Himachal Pradesh and Punjab). Jammu and Kashmir is a region administered by India as a union territory.It has been the subject of a dispute between India and Pakistan since 1947,And between India and China since 1962.Last updated 27-07-2026 by NA', 0, 0, 0, 1790967393900) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ceb3d39d621052c7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Pakistan purchased Gwadar from Muscat (Oman) in which year?', '{"A":"1956","B":"1957","C":"1958","D":"1959"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan purchased the Gwadar enclave from Oman on 8 September 1958 The Gwadar Port is situated on the Arabian Sea at Gwadar in the BalochistanTakeover Date: December 8, 1958.Purchase Amount: $3 million (approximately £3 million).Port Opening: 2002Last updated by NA on 23-April-2026', 0, 0, 0, 1790967393900) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_03bdf23b3b4e898c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The Lucknow Pact of 1916 was made between?', '{"A":"The british and india","B":"The Congress and the Muslim League","C":"The Hindus and the Muslims","D":"The moderates and extremists"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lucknow Pact (1916) was an agreement between:Indian National Congress – headed by Bal Gangadhar TilakAll-India Muslim League – led by Muhammad Ali JinnahPurposes of Lucknow Pact:Hindu-Muslim unityCongress-League cooperationConstitutional reformsSeparate electorates for MuslimsDemand for self-governmentLast verified on 19-01-2026', 0, 0, 0, 1790967393900) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7be0b6a3c4f23d16', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The highest civil award of Pakistan is _____?', '{"A":"Nishan-e-Imtiaz","B":"Nishan-e-Sadarat","C":"Nishan-e-Hyder","D":"Nishan-e-Pakistan"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nishan-e-Pakistan — Highest civil awardEstablished: March 19, 1956 (under the Decorations Act)First recipient: Quaid-e-Azam Muhammad Ali Jinnah (posthumously awarded in 1958)Additional informationAwardRankNishan-e-PakistanHighestHilal-e-Imtiaz2nd highestSitara-e-Imtiaz3rd highestTamgha-e-KhidmatSmallestCaptain Raja Muhammad Sarwar first to be awarded Nishan-e-Haider (military),Last updated 26-07-2026 by NA', 0, 0, 0, 1790967393900) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a5652cafa4d49c3c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'When Sir Syed Ahmed Khan became member of Imperial committee?', '{"A":"1876","B":"1877","C":"1878","D":"1879"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sir Syed Ahmed Khan became a member of the Imperial Legislative Council in July 1878.He served as an Additional Member from July 1878 to July 1880.He later served a second term until 1883.His membership recognized his contributions to education and social reforms.Additional information:Joined Government Service: 1839 (as Naib Munshi)Promoted as Sub-Judge: 1841Transferred to Delhi: 1846Last verified on 26-07-2026', 0, 0, 0, 1790967393923) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_fcf9a2af87642447', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The Shrine of Lal Shahbaz Qalander is situated in _____?', '{"A":"Uch Sharif","B":"Shahbaz Nagar","C":"Karachi","D":"Sehwan Sharif"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Shrine Location: Sehwan, SindhAdditional information:Full Name: Syed Usman Marwandi (Lal Shahbaz Qalandar)Birth Year: 1177 CEBirth Place: Marand, IranDeath Date: 19 February 1274 CELast verified on 26-07-2026', 0, 0, 0, 1790967393923) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_830b919062ac0718', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The road/highway connecting Pakistan and China is called?', '{"A":"Karakoram Highway","B":"Indus Highway","C":"Express Highway","D":"Hamaliya Highway"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Name: Karakoram Highway (KKH)Other Name: Friendship Highway (China side)Route Start: Hassan Abdal (Pakistan)Important Pass: Khunjerab Pass (Pakistan–China border)Total Length in Pakistan: About 1300 kmCompletion Year: 1979Route Type: Part of ancient Silk Route connectionLast verified on 13-05-2026', 0, 0, 0, 1790967393923) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_072f0f51a32d107d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The narrow strip in Afghanistan that separates Pakistan from Tajikistan is called _____?', '{"A":"Wakhan Corridor","B":"Durand Line","C":"Makhmud Bordar","D":"Khunjerab"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The narrow strip is called the Wakhan Corridor.It is located in northeastern Afghanistan.It separates Pakistan from Tajikistan.This corridor was created as a buffer zone during the 19th century (Great Game).Length: ~350 kmWidth: 13–65 km (approx.)Last verified on 31-03-2026', 0, 0, 0, 1790967393923) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6a9f2cf104cc473f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'When is Malala Day celebrated?', '{"A":"12 May every year","B":"12 December every year","C":"12 July every year","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation International Malala Day is observed every year on July 12 celebrate the life and legacy of Pakistani education activist and Nobel laureate Malala Yousafzai.*About Malala YousafzaiBorn: 1997Belongs: Mingora, SwatReceived Noble Prize in 2014She is the youngest Nobel Prize laureate ND06-08-2023', 0, 0, 0, 1790967393923) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_95a5f3f21288f717', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The M-8 Motorway is between _____?', '{"A":"Sukkur to Peshawar","B":"Sukkur to Multan","C":"Ratodero to Gwadar","D":"Karachi to Gwadar"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The M-8 Motorway connects Ratodero (Sindh) with Gwadar (Balochistan).It is the longest motorway in Pakistan.Length: 892 kmConstruction Started: 15 October 2004Planned Lanes: 4 lanesIt is being constructed by the National Highway Authority (NHA).Last verified on 22-08-2026', 0, 0, 0, 1790967393923) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b11afe0b16de1a6d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The Khewra Salt Mines are located in _____?', '{"A":"Mianwali","B":"Sargodha","C":"Chakwal","D":"Jehlum"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Khewra Salt Mine is located in Khewra near Pind Dadan Khan, Jhelum District, Punjab.It is the largest and oldest salt mine in Pakistan.It is the second-largest in the world.Additional information:It is also called the Mayo Salt Mine.The salt deposits were discovered during the campaign of Alexander the Great in 326 BC.The mine was officially opened in 1872 during the British period.Last verified on 14-03-2026', 0, 0, 0, 1790967393923) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_75e43b2c88240f16', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Rohtas Fort near Jehlum built by _______?', '{"A":"Akbar","B":"Sher Shah Suri","C":"Shah Jahan","D":"Baber"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Rohtas Fort near Jhelum was built by Sher Shah Suri.He was the founder of the Suri Empire in India.It is a 16th-century fortress.It is located near the city of Dina in Jhelum.The construction started in 1541.It has 14 gates.Last verified on 01-05-2026', 0, 0, 0, 1790967393923) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_087ec4412e8929fb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'IESCO stands for ____?', '{"A":"Islamabad Electric Supply Company","B":"International Energy Supply Corporation","C":"Islamabad Environment Services Co.","D":"Independent Energy Solutions Corp"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Full Form: Islamabad Electric Supply CompanyEstablished: 1998Ownership: Government of PakistanHeadquarters: Islamabad, PakistanMain Function: Distribution of electricity in Islamabad and adjoining regionsLast verified on 22-07-2026', 0, 0, 0, 1790967393943) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_86a714b211da9efd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'PPRA is an abbreviation for?', '{"A":"Public Procurement Regulatory Authority","B":"Pakistan Pilgrimage and Religious Authority","C":"Public Policy and Research Association","D":"Provincial Procurement and Regulatory Authority"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Full Form: Public Procurement Regulatory AuthorityPurpose: Regulation of government procurementFunction: Ensures transparent tendering processEstablished under: Public Procurement ActArea: Pakistan government procurement systemLast verified on 10-06-2026', 0, 0, 0, 1790967393943) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_4f40e73577376a0d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'In which year MAO College became University?', '{"A":"1918","B":"1922","C":"1924","D":"1920"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Converted into University: 1920 (Aligarh Muslim University)Full Form: Muhammadan Anglo-Oriental CollegeFounder: Sir Syed Ahmad KhanEstablished: 1877Location: Aligarh, IndiaAdditional information:School Established: 1875Intermediate Classes Started: 1878B.A. Classes Started: 1881Inaugurated by: Lord LyttonFirst Headmaster of M.A.O. School: Henry SiddonsLast verified on 10-07-2026', 0, 0, 0, 1790967393943) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7579265629224599', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'What is the name of the father of "Shah Waliullah"?', '{"A":"Shah Abdur Rahim","B":"Allama Hijazai","C":"Shah Ahmed","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Father: Shah Abdur RahimReal Name: Qutubuddin Ahmad SyedBorn: 21 February 1703, Phulat, Mughal EmpireDied: 20 August 1762 (aged 59), Delhi, Mughal EmpireBooks Written: 51Last verified on 21-07-2026', 0, 0, 0, 1790967393943) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_69afaf044634f412', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which was the first public airline of Pakistan?', '{"A":"Pakistan International airline","B":"Orinental airline","C":"Orient airline","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation First Airline: Orient AirwaysEstablished: 29 October 1946Initial Headquarters: Calcutta (Kolkata), British IndiaShifted to Pakistan: 1947 (Karachi)Renamed as: Pakistan International Airlines (PIA) – 1955Last verified on 21-07-2026', 0, 0, 0, 1790967393943) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7a5072dba422880c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who was the first woman to be appointed as permanent representative of Pakistan to the United Nations?', '{"A":"Hinna Rabani Khar","B":"Maleeha Lodhi","C":"Tehmina Janjua","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Name: Dr. Maleeha LodhiPosition: Permanent Representative of Pakistan to the United NationsOffice: 6 February 2015 – 30 September/30 October 2019Appointed by: Prime Minister Nawaz SharifPreceded by: Masood KhanSucceeded by: Munir AkramVerified & Updated', 0, 0, 0, 1790967393943) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_58d7267596b1b74e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'M5 motorway connects which cities?', '{"A":"Multan - Sukkur","B":"Lahore - Karachi","C":"Lahore - Peshawar","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The M-5 Motorway connects Multan (Punjab) with Sukkur (Sindh).It is part of Pakistan''s north-south motorway network.The motorway is 392 km (244 miles) long.It has been operational since 2018.The M-5 was constructed during the government of Nawaz Sharif.Additional information:M-1: Islamabad – PeshawarM-2: Lahore – Islamabad (Pakistan''s first motorway in 1999)M-3: Lahore – Abdul HakeemM-4: Pindi Bhattian – MultanLast verified on 02-07-2026', 0, 0, 0, 1790967393943) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_518978542727f62d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'When was the Basic Democracies System introduced in Pakistan?', '{"A":"23 March 1956","B":"7 October 1958","C":"27 October 1959","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Basic Democracies System was introduced in Pakistan on 27 October 1959.It was promulgated on 26 October 1959.Introduced By: Field Marshal Muhammad Ayub KhanSystem: Four-tier local governmentBasic Democrats: 80,000 elected representativesLast verified on 11-07-2026', 0, 0, 0, 1790967393943) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_192361e078dde55b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Silk route Karakoram Highway connects Pakistan with?', '{"A":"India","B":"Iran","C":"China","D":"Afghanistan"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Karakoram Highway (N-35) is a famous highway connecting Pakistan and China.It follows the ancient Silk Route path.It is called the “Friendship Highway.”It meets China at the Khunjerab Pass (Pakistan–China border).Additional information:It was constructed from 1959 to 1979.It is opened for public use in 1979.Total length: ~1,300 kmPakistan: 887 kmChina: 413 kmStarting point (Pakistan): Hassan AbdalHighest point connection: Khunjerab PassLast verified on 08-06-2026', 0, 0, 0, 1790967393964) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_468354d09582cd0d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The Makran Coastal Highway connects Karachi to?', '{"A":"Quetta","B":"Gwadar","C":"Turbat","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Makran Coastal Highway (N-10) connects Karachi to Gwadar.Length: 653 kmProvince: Sindh and BalochistanIt runs along Pakistan''s Arabian Sea coastline.Last verified on 07-07-2026', 0, 0, 0, 1790967393964) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_476261cbe1a28144', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The NFC Award is ______?', '{"A":"Water sharing formula within Federation","B":"Funds sharing formula within Federation","C":"Electricity sharing formula within Federation","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The NFC Award is a financial distribution formula between the Federal Government and the provinces of Pakistan.The award decides how national revenues and taxes are shared among provinces and the center.Additional information:NFC stands for National Finance Commission.The first revenue-sharing award in Pakistan was the Raisman Award (1952).The Constitution of 1973 formally established NFC under Article 160.The NFC Award is usually announced every 5 years.Last verified on 11-05-2026', 0, 0, 0, 1790967393964) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c453b57911425d1d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'What is the main basis of the Two-Nation Theory?', '{"A":"Cultural, religious, and social differences between Hindus and Muslims","B":"Economic differences","C":"Geographical differences","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Main Basis: Religious, cultural, and social differencesProposed By: Sir Syed Ahmad Khan (early idea)Strengthened By: Allama Muhammad Iqbal and Quaid-e-Azam Muhammad Ali JinnahPakistan Created: 14 August 1947Purpose: To safeguard the identity and rights of Muslims of the Indian subcontinentVerified & Updated', 0, 0, 0, 1790967393964) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_949796eaca4c7d8d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Gaddani Beach is famous for ____?', '{"A":"Ship Making","B":"Ship Breaking","C":"Ship Building","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Gaddani Beach is famous for ship breaking.The Gadani Ship-Breaking Yard is located on the Arabian Sea.It is 40 kilometers northwest of Karachi.It is located Gadani, District Lasbela, Balochistan.It''s the third largest ship-breaking yard in the world.It is with 132 ship-breaking plots along a 10 kilometer stretch of beach.The yard is known as the "graveyard of ships".Last verified on 19-07-2026', 0, 0, 0, 1790967393964) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b94f8526c838ef91', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Redcliff award was given in which date and time?', '{"A":"17th August 1947 5:00 PM","B":"14th August 1947 5:00 PM","C":"18th August 1947 5:00 PM","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Announcement: 17 August 1947, 5:00 PMPakistan''s Independence: 14 August 1947India''s Independence: 15 August 1947Boundary Commissioner: Sir Cyril RadcliffePurpose: To divide Punjab and Bengal between Pakistan and IndiaLast verified on 18-07-2026', 0, 0, 0, 1790967393964) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_520e1b9b36bdc49a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'CCI stands for _____?', '{"A":"Counsel of common inference","B":"Council of Common Interests","C":"Chronic Coronary Insufficiency","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Full Form: Council of Common InterestsEstablished: 1973 ConstitutionChairman: Prime MinisterPurpose: Federal-provincial coordinationFunction: Resolve inter-government disputesLast verified on 01-05-2026', 0, 0, 0, 1790967393964) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_edfe8ecd583cbf06', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Shah Waliullah was born in ______?', '{"A":"1703","B":"1704","C":"1705","D":"1706"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Shah Waliullah Dehlawi (1703–1762) was a great Islamic scholar and reformer of the Mughal era.His real name was Qutubuddin Ahmad Syed.He was born on 21 February 1703 in Phulat (India) during the reign of Aurangzeb.He translated the Holy Quran into Persian for the first time in the subcontinent.He wrote about 51 books on Islam, society, and reforms.Last verified on 02-04-2026', 0, 0, 0, 1790967393964) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9a7445f1a50de74d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'When was Operation Zarb-e-Azb launched/started?', '{"A":"June 15, 2014","B":"July 15, 2014","C":"December 15, 2014","D":"December 15, 2015"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Operation Zarb-e-Azb (15 June 2014 – 22 February 2017) was launched in North Waziristan, former FATA, Pakistan.Operation was led by Army Chief General Raheel Sharif to eliminate terrorist groups.‘Azb’ refers to one of the seven swords of the Holy Prophet (PBUH) used in Ghazwaz of Uhud and Badr.Additional information:Operation Radd-ul-Fasaad followed on 22 Feb 2017, led by General Qamar Javid Bajwa.Last verified on 16-01-2026', 0, 0, 0, 1790967393984) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_fbeab6c8a39b471e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'At the time of creation Pakistan, how many Radio Stations were there?', '{"A":"Five","B":"Three","C":"Two","D":"Four"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Total Radio Stations (1947): 3Peshawar: Established 1935Lahore: Established 1937Dhaka: Established 1939Independence: 14 August 1947Additional information:Organization: Pakistan Broadcasting Corporation (PBC)Popular Name: Radio PakistanEstablished: 20 December 1972Headquarters: Islamabad, PakistanMain Function: National public radio broadcasting and dissemination of news, education, and cultural programs.Last verified on 18-07-2026', 0, 0, 0, 1790967393984) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a050b8d4c8afea38', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which tanks are being produced in Pakistan?', '{"A":"Baktar","B":"Humza","C":"Al-Khalid","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Al-Khalid is Pakistan''s main battle tank (MBT) being produced in Pakistan.Manufacturer: Heavy Industries Taxila (HIT), PakistanDesigner: Norinco (China) & PakistanDesign period: 1993–1999Variants: Al-Khalid, Al-Khalid I, Al-Khalid II (under development)Last verified on 18-07-2026', 0, 0, 0, 1790967393984) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_16798194a6d0d28c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'What is length of Peshawar to Karachi railway route?', '{"A":"1681 km","B":"1605 km","C":"1661 km","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Karachi–Peshawar Railway Line is 1,872 (1681) kilometers (1,163 miles) long.The track gauge is 1,676 millimeters (5 ft 6 in).Current operating speed is 30–115 kilometers per hour (19–71 miles per hour).A proposed speed of 140 kilometers per hour (87 miles per hour).Last verified on 17-07-2026', 0, 0, 0, 1790967393984) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d7df3a6c7533efc5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Where is the tomb of Baba Bulleh Shah is located?', '{"A":"Kasur","B":"Multan","C":"Golra Sharif","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The tomb of Baba Bulleh Shah is located in Kasur, Punjab, Pakistan.His real name was Syed Abdullah Shah Qadri.He was a famous Punjabi Sufi poet, philosopher, and reformer.Born: 1680, Uch Sharif (present-day Punjab, Pakistan)Died: 1757, KasurLast verified on 17-07-2026', 0, 0, 0, 1790967393984) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d6241a2524a9b0f6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The Cripps Mission visited India in?', '{"A":"1942","B":"1946","C":"1944","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Visited India: 22 March 1942Stayed until: 12 April 1942Headed by: Sir Stafford CrippsObjective: Resolve constitutional issues and secure Indian support in World War IIReason: Japan''s advance towards India''s bordersResult: Mission failed, leading to the Quit India Movement (August 1942).Last verified on 17-07-2026', 0, 0, 0, 1790967393984) ON CONFLICT(id) DO NOTHING;
