INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_53c03fcc7bf3bf98', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Chaudhry Rehmat Ali first used the word ''Pakistan'' in his pamphlet ''now or never'' in which year?', '{"A":"1930","B":"1928","C":"1933","D":"1931"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation First Introduced: 1933 by Chaudhary Rahmat Ali.Pamphlet: Titled "Now or Never" meaning Are We to Live or Perish Forever?Additional information:First Use of Pakistan: Word appeared for the first time in this pamphlet.Based On: Two-nation theory of Syed Ahmed Khan.Regions Represented (Pakistan):PunjabAfghanistanKashmirSindhBaluchistanLast verified on 24-03-2026', 0, 0, 0, 1790967393984) ON CONFLICT(id) DO NOTHING;
