INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_568b4b631c4ca787', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which sector is the biggest consumer of electricity in Pakistan?', '{"A":"Domestic","B":"Industrial","C":"Commerical","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Largest electricity consumer: Domestic SectorLargest source of electricity generation: Natural Gas – 32.3%Second largest source: Hydroelectric (Hydel) – 24.7%Other sources: Coal, Nuclear, Oil, Wind, SolarMajor consumers: Domestic, Industrial, Commercial, AgriculturalLast verified on 07-07-2026', 0, 0, 0, 1790967394022) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6415c2c03f25bbce', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which country is the largest trading partner of Pakistan?', '{"A":"Saudi Arabia","B":"China","C":"Japan","D":"USA"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation China is Pakistan’s largest trade partner.Trade between Pakistan and China increased significantly after CPEC (2015).Both countries signed a Free Trade Agreement (FTA) in 2006.This partnership plays a key role in Pakistan’s economy and infrastructure development.Last verified on 17-05-2026', 0, 0, 0, 1790967394022) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7395049f6e81af57', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The "Communal Award" given by?', '{"A":"Lloyd George","B":"Ramsay Macdonald","C":"Winston Churchill","D":"Stanley Baldwin"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Communal Award was announced in August 16, 1932.It was given by Ramsay MacDonald.It introduced separate electorates for different communities.Aimed to provide political representation to minorities.It came after the 3rd Round Table Conferences.Last verified on 29-04-2026', 0, 0, 0, 1790967394022) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_82bada1374e5be78', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Dr. Abdul Salam won the Nobel Prize for the subject of _____?', '{"A":"Biology","B":"Chemistry","C":"Mathematics","D":"Physics"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dr. Abdus Salam won the Nobel Prize in Physics in 1979.He received the award for his contribution to the Electroweak Theory, which unified the electromagnetic and weak nuclear forces.Additional information:Born: 29 January 1926, Jhang, PunjabDied: 21 November 1996Ph.D.: 1952, Theoretical Physics, University of CambridgeAchievement: First Pakistani Nobel laureate and second Muslim Nobel laureateLast verified on 06-07-2026', 0, 0, 0, 1790967394043) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3317eaeeb002cc5c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'What do the green and white colors of the Pakistan flag represent?', '{"A":"Muslim majority in Pakistan","B":"Various religious minorities","C":"Both A and B","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dark green field: Represents Muslim majority in Pakistan.White stripe: Represents religious minorities.Crescent: Symbolizes progress.Star: Symbolizes light and knowledge.Colors Meaning:Green: Hope, joy, love, and IslamWhite: Peace and honestyLast verified on 14-03-2026', 0, 0, 0, 1790967394043) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_84f43ecb6c0a2acb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'First Five Year Plan was prepared by Pakistan in?', '{"A":"1951","B":"1955","C":"1956","D":"1957"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Plan Name: First Five-Year PlanDuration: 1955–1960Country: PakistanMain Focus: Education, agriculture, industrial developmentObjective: Economic and social developmentAdditional information:First Five-Year Plans (1955–1960)Second Five-Year Plans (1960–1965)Third Five-Year Plans (1965–1970)Fourth Five-Year Plans (1970–1975)Fifth Five-Year Plans (1978–1983)Sixth Five-Year Plan (1983–88)Seventh Five-Year Plan (1988–93)Eighth Five-Year Plan (1993–98)Last verified on 17-05-2026', 0, 0, 0, 1790967394043) ON CONFLICT(id) DO NOTHING;
