INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_749f1ec7cb9e23d9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'In which year Pakistan won the Cricket World Cup?', '{"A":"1990","B":"1980","C":"1970","D":"1992"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan won the Cricket World Cup in 1992Edition: FifthFormat: One Day International (ODI)Venue: Australia & New ZealandFinal held: 25 March 1992Final Venue: MelbourneWinner: Pakistan (First title)Runners-up: EnglandParticipating teams: 09Total Matches: 39Most wickets taken by: Wasim Akram (18 wickets)**** Question updated on 11-02-2026', 0, 0, 0, 1790967394718) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_de3a55b8eb6dfee5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Where was Sir Syed Ahmed Khan born?', '{"A":"Agra","B":"Madras","C":"Delhi","D":"Bengal"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sir Syed Ahmed Khan was born in 1817 in Delhi.He was died in 1898 and buried in Aligarh.He was an Islamic reformer and philosopher.Two nation theory first time introduced by Sir Syed Ahmed.He received his early education from his Maternal Grand Father.Mir Muttaql was the father of Sir Syed Ahmed Khan.Last verified 09-03-2026', 0, 0, 0, 1790967394718) ON CONFLICT(id) DO NOTHING;
