INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_57471bb30c7ea1e2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who was the founder of the Khilji Dynasty?', '{"A":"Jalaluddin Khilji","B":"Rehmat Ullah","C":"Khilji Alauddin Khilji","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation After the fall of the Slave (Mamluk) Dynasty, Delhi Sultanate became weak due to revolts.The Khilji Dynasty replaced the Slave Dynasty.Its founder was Jalal ud din Firuz Khilji.Additional information:He became Sultan in 1290 at about 70 years of age.He was later killed by his nephew Alauddin Khilji (Ali Gurshap).Last verified on 02-02-2026', 0, 0, 0, 1790967394838) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8d777dd32f219c09', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who scored highest Innings score in ODI for Pakistan?', '{"A":"Fakhar Zaman","B":"Babar Azam","C":"Hanif Mohammad","D":"Ahmed Shehzad"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In ODI cricket, the highest individual score for Pakistan is 210 not out by Fakhar Zaman.This record was set against Zimbabwe in 2018.Additional information:Babar Azam: 122 in T20I (highest for Pakistan in T20)Hanif Mohammad: 337 in Test cricket (highest Test score for Pakistan)Last verified on 01-02-2026', 0, 0, 0, 1790967394838) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9ff6cf48d8b693b2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Razia Sultana was the daughter of?', '{"A":"Shams ud-Din Iltutmis","B":"Qutub-ud-din Aibak","C":"Shah Jehan","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Razia Sultana was the first female ruler of Delhi Sultanate.She ruled India from 1236 to 1240.She was the daughter of Sultan Shams-ud-Din Iltutmish and Turkan Khatun.Known for her bravery, intelligence, and administrative skills.Last verified on 01-02-2026', 0, 0, 0, 1790967394838) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_06a4226e01c9215a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which day is observed as Black Day in Kashmir_____?', '{"A":"August 27","B":"September 27","C":"October 27","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kashmir Black Day is observed annually on 27 October.It commemorates 27 October 1947, when Indian forces entered Kashmir.The day has increased significance following the 5 August 2019, revocation of Article 370 by India.', 0, 0, 0, 1790967394838) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_63dce4dffe4db25e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'India did airstrikes in 2019. When India has struck it before?', '{"A":"1947","B":"1971","C":"1967","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The 2019 Balakot airstrike was a bombing raid conducted by IndianOn 26 February 2019 in Balakot, PakistanAgainst an alleged training camp of the terrorist group Jaish-e-MohammedIndia had previously conducted airstrikes on Pakistan in 1971 during the Indo-Pakistani War of 1971.', 0, 0, 0, 1790967394838) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6581406cbd96dedf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Indian forces occupied Kashmir in the year ______?', '{"A":"1947","B":"1950","C":"1948","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation India began its military presence in Kashmir on October 27, 1947 After the ruler of the princely state, Maharaja Hari SinghThis event marked the beginning of the Kashmir conflict between India and Pakistan.', 0, 0, 0, 1790967394838) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_17a34d7b40bd5c6a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Quit India Movement also called _____?', '{"A":"September Movement","B":"August Movement","C":"October Movement","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Quit India Movement is also called the August Movement or August Kranti (August Revolution). launched by Mahatma Gandhi on August 8, 1942,in Bombay.The movement, started by the Congress party.It''s demanded an end to British rule in India.Muhammad Ali Jinnah responded with the slogan "Divide and Quit India."', 0, 0, 0, 1790967394885) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d0fa0337f7dc0243', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Baba Fareed Ganj Shakar belongs to _____?', '{"A":"Chishti","B":"Suharwardi","C":"Naqshbandi","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Baba Fareed Ganj Shakar belongs to the Chishti Order (Chishtiyya) of SufismBaba Farīd or Fariduddin Masud was born in 1188 (573 AH) in KothewalHe was one of the founding fathers of the Chishti Sufi order.The Shrine is located in Pakpattan, PakistanBaba Fareed Shaker Ganj'' was the first poet of Punjabi', 0, 0, 0, 1790967394885) ON CONFLICT(id) DO NOTHING;
