INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_148fdafa4761baf7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Pakistan Ideology is based on the idea of ____?', '{"A":"Theocracy","B":"Democracy","C":"Monarchy","D":"Islam"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan''s ideology is fundamentally based on Islam and the Two-Nation TheoryIslamic Identity: The belief that Islam is a complete way of life Two-Nation Theory: Muslims and Hindus are two separate nations', 0, 0, 0, 1790967394885) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_eb895e65ef221ba1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Per Capita water availability in Pakistan is _____?', '{"A":"Constant","B":"Decreasing","C":"Increasing","D":"Fluctuating"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Per capita water availability in Pakistan is decreasing by 400pc.Due to population growth and diminishing water resources.This leading to increased concerns over water scarcity.Last verified on 27-01-2026', 0, 0, 0, 1790967394885) ON CONFLICT(id) DO NOTHING;
