INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a602f149978c7e5e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The government of Benazir Bhutto was dismissed for the second time on November 1996 by _____?', '{"A":"President of Pakistan Farooq Leghari","B":"Chief Justice of Pakistan Sajjad Ali Shah","C":"National Speaker of Pakistan Gohar Ayub Khan","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Farooq Ahmad Khan Leghari was the eighth president of Pakistan eighth president of Pakistan from 14 November 1993 until resigning on 2 December 1997. He was the first Baloch to be elected as president.He started his own Millat party In 1996 he dismissed Benazir GovernmentBorn: Sardar Farooq Ahmad Khan Leghari 29 May 1940Died: 20 October 2010 (aged 70) Rawalpindi, PakistanResting place: Choti Zareen, Dera Ghazi Khan, PakistanPolitical party: Pakistan Muslim League (Q) (2002–2010)', 0, 0, 0, 1790967395431) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_384e4df6e1f12dd4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which country uses GMT+5 as its standard time?', '{"A":"India","B":"Iran","C":"Iraq","D":"Pakistan"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan''s standard time is 5 hours from Greenwich means Time***Pakistan''s standard time was suggested by Professor Muhammad Anwar in 1951**Greenwich Mean Time (GMT) is the standard time of which of UK', 0, 0, 0, 1790967395431) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_1fa02fd3ce7bf6fb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', '+92 is the country code of _____?', '{"A":"China","B":"Russia","C":"USA","D":"Pakistan"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The County codes were introduced in 1960 by International Telecon Union.PK is the national code of Pakistan.+92 is the dialing code of Pakistan.', 0, 0, 0, 1790967395431) ON CONFLICT(id) DO NOTHING;
