INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ec406a877fed659a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Sir Syed Ahmed Khan was born in which year?', '{"A":"1817","B":"1818","C":"1820","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sir Syed Ahmed Khan was an Islamic reformer and philosopher.Sir Syed Ahmed Khan was born in 1817 in Delhi.Sir Syed Ahmad Khan died in 1898.Sir Syed Ahmad Khan Buried in Aligarh in 1898.Sir Syed Ahmad Khan received his early education from his Maternal Grand Father.**********VU CBT FIA PAPER 25-12-2021', 0, 0, 0, 1790967395431) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_417d54634d4e62c7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', '"K" in Pakistan stands for ______?', '{"A":"Kuffar","B":"Kashmir","C":"Kamyab","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The word was first introduced now or never in 1933 by Choudhry Rahmat Ali.The "Pakistan Declaration" titled Now or Never means Are We to Live or Perish Forever?In this pamphlet, the word Pakistan was used for the first time This pamphlet was derived from the two-nation theory of Muslim reformer Syed Ahmed Khanit was a pamphlet, referring to the names of the five northern regions of British India: PunjabAfghanistanKashmirSindhBaluchistan. (Pakistan)***', 0, 0, 0, 1790967395469) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_86265509f7efaab0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'SNGPL stands for _____?', '{"A":"Sui Northern Gas Pakistan Limited","B":"Sui Northern Gas Pipelines Limited","C":"Sui Northern Gas Pipeline Lahore","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation SNGPL stand for Sui Northern Gas Pipelines Limited. SNGPL was incorporated as a private limited Company in 1963.Converted into a public limited company in January 1964.***RY5022023', 0, 0, 0, 1790967395469) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_123702b6439889de', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Hakla-D.I. Khan Motorway, inaugurated on 5 January 2022 is also known as _____?', '{"A":"M12","B":"M10","C":"M14","D":"M8"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The M-14 Motorway, also known as the Islamabad–Dera Ismail Khan Motorway or Hakla–Yarik Motorway.It is a four-lane north-south motorway in Pakistan.It spans 285 km (177 mi) and has been operational since January 5, 2022.The motorway features 11 interchanges, 36 bridges, 33 flyovers, and 119 underpasses.', 0, 0, 0, 1790967395469) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_958a6ae5132f66ac', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Nadir Shah invaded India during the reign of ______?', '{"A":"Muhammad Shah","B":"Shah Alam","C":"Bahadur Shah","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nadir Shah invaded India during the reign of Mughal emperor Muhammad Shah.He ruled from 1719 to 1748.On February 24, 1739, Nadir Shah''s army defeated the Mughals at the Battle of Karnal.Muhammad Shah surrendered, and Nadir Shah entered Delhi on March 20, 1739.', 0, 0, 0, 1790967395469) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7407874a3befe0cb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The Chairman of Council of Common Interest is the _____?', '{"A":"President","B":"Chief Justice of Pakistan","C":"Prime Minister","D":"Attorney General"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Prime Minister of Pakistan is the Chairman of the Council of Common Interests (CCI).The CCI is a constitutional body established under Article 153 of the 1973 Constitution of the Islamic Republic of Pakistan. The CCI''s other members are:The four Provincial Chief MinistersThree members nominated by the Prime Minister, usually Cabinet members', 0, 0, 0, 1790967395469) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f512fd4c8ecb7e63', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who was the founder of Dar-Ul-Uloom Deoband institute?', '{"A":"Mehmood-Ul-Hassan","B":"Maulana Shabir Ahmed Usmani","C":"Muhammad Qasim Nanautavi","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation About Deoband MadrasahFounded: 31 May 1866Founder: Muhammad Qasim NanautaviFirst Principal: Maulana Muhammad QasimLocation: Saharanpur, Uttar Pardesh', 0, 0, 0, 1790967395469) ON CONFLICT(id) DO NOTHING;
