INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a05683099eeab513', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which is the oldest airline of Pakistan?', '{"A":"Pakistan Airline","B":"Shaheen Airline","C":"Orient Airways","D":"Aero Asia Airline"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Orient Airways is the oldest airline of Pakistan.It is founded in 1946.It is later merged with Pakistan International Airlines (PIA) in 1955 to become the national flag carrier.', 0, 0, 0, 1790967395678) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9ad3718e6329dd2f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'In March 2006, who was appointed as the bowling coach for Pakistan?', '{"A":"Shoaib Malik","B":"Waqar Younis","C":"Ramiz Raja","D":"Misbah-ul-Haq"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation On March 08, 2006Pakistan appointed former captain and fast bowler Waqar Younis as their bowling coach until the 2007 World Cup.Waqar Younis was re-appointed as Pakistan''s bowling and fielding coach for their tour of Australia in December 2009Waqar was appointed as the coach of the Pakistan cricket team on 3 March 2010. He resigned as Pakistan''s Cricket Coach on 19 August 2011 citing personal reasons.ND26-2-2023', 0, 0, 0, 1790967395678) ON CONFLICT(id) DO NOTHING;
