INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8ad3ed56541aaee5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Arya Samaj was founded in _______?', '{"A":"1873","B":"1875","C":"1874","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Arya Samaj was founded on April 10, 1875Location: Bombay, India Members: 10 million (world)8 million (India)Official language: HindiAdditional information Purpose: Educational, Religious studies, Spirituality, Social reformsArya Samaj: A community of people with noble and virtuous character.Arya: Means noble or virtuous person.Samaj: Means society or community.Last updated 26-07-2026 by NA', 0, 0, 0, 1790967395786) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e74d5b07b619f421', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who was responsible for the introduction of English as the official language in India?', '{"A":"Lord William Bentinck","B":"Lord Cornwallis","C":"Lord Canning","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lord William Bentinck is credited with introducing English as the official language of instruction in India.It primarily through the "English Education Act of 1835" which he implemented alongside Thomas Babington Macaulay.', 0, 0, 0, 1790967395786) ON CONFLICT(id) DO NOTHING;
