INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_5bb85f964d7accc6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'When Quid-e-Azam resigned from the Imperial legislative Council?', '{"A":"1918","B":"1919","C":"1920","D":"1921"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Quaid-e-Azam resigned from the Imperial Legislative Council as a protest against Rowlatt Act. The Chaotic and Revolutionary Crimes Act of 1919, commonly known as the Rowlatt Act, It was the act of the Imperial Legislative Council on March 18, 1919, in Delhi.', 0, 0, 0, 1790967395832) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_00e1f003da52abac', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'When did PTV start its colour transmission?', '{"A":"December 10, 1977","B":"December 20, 1976","C":"November 06, 1976","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation PTV started its color transmission in 1976It was founded on 26 November 1964.It is the first official television stationAdditional informationPTV started its live transmission on November 26, 1964On this date, it began its first transmission broadcasts from Lahore, followed by Dhaka.Ayub Khan inaugurated this first official transmission broadcasts A third center was established in Rawalpindi-Islamabad in 1965 The fourth center was established in Karachi in 1966.Aslam Azhar is widely considered to be the "father of Pakistan Television"', 0, 0, 0, 1790967395832) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a0dcdd79e1eb9950', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Toot oil and natural gas field is located in _____?', '{"A":"Sindh","B":"Balochistan","C":"Punjab","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation It is one of the oldest oil-producing regions in Pakistan, with commercial production starting in 1967.The field is located approximately 135 km southwest of Islamabad, in the Attock District.It was originally discovered in the early 1960s (1961).', 0, 0, 0, 1790967395832) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9b8fdf4228e7855d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Abdul Qadeer Khan Nuclear Research Laboratories was set up in Kahuta in the year ______?', '{"A":"1977","B":"1974","C":"1976","D":"1973"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Dr. A. Q. Khan Research Laboratories (KRL) was established in Kahuta, Pakistan on July 31, 1976.The KRL was founded by Pakistani nuclear physicist and metallurgical engineer Abdul Qadeer Khan.He is known as the father of Pakistan''s atomic bomb.The lab was created in response to India''s first nuclear bomb test in 1974.Khan was the lab''s senior scientist and chairman until he retired in 2001.', 0, 0, 0, 1790967395832) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_0f275461931368c6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'What is the length of M2 (Islamabad - Lahore ) Motorway?', '{"A":"367km","B":"388km","C":"375km","D":"398km"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The M-2 Motorway or the Lahore–Islamabad Motorway.Length: 375 kmConstructed: 1992North end: Kashmir Highway Interchange, IslamabadSouth end: Thokar Niaz Baig, Lahore***The M8 Motorway is the longest one in Pakistan****The Motorway M5 (Multan-Sukkur section) M-3 (Lahore-Abdul Hakeem)', 0, 0, 0, 1790967395832) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_85125347b43d5910', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'What is the total length of Gwadar Motorway?', '{"A":"892 km","B":"872 km","C":"812 km","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The M8 Motorway is the longest one in PakistanM8 is the 892KM long from Ratodero to Gwadar.The Motorway is partially operational and the remaining road is currently under constructionThe M8 will have 4-lanes**History**The M8 is being constructed by Pakistan''s National Highway Authority. Construction of the M8 commenced on 15 October 2004.', 0, 0, 0, 1790967395832) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e0aebc62e96276d8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The total Track’s length of Railways in Pakistan is _____?', '{"A":"11,881 kilometres (7,383 mi)","B":"7300 kilometres (4536 mi)","C":"12929 kilometres (8033 mi)","D":"5740 kilometres (3566 mi)"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan Railways was founded in 1861.The first railway line in Pakistan was laid between Karachi-Kotri.Pakistan Railways headquartered in Lahore.Pakistan Railways'' total length is 7,791 KM of track across Pakistan.Must Read itThe Current Federal Minister of Railways of Pakistan is?Who is the Current Inspector General of Pakistan Railways Police?', 0, 0, 0, 1790967395832) ON CONFLICT(id) DO NOTHING;
