INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ac35800a8a25bc8c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'One unit was dissolved on?', '{"A":"1st July 1970","B":"1st July 1971","C":"1st July 1972","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The One Unit scheme was dissolved on July 1, 1970.General Yahya Khan imposed Legal Framework Order No. 1970 to end the programand reinstate the provisional status of the Four Provinces as of August 1947.Additional information:The One Unit was the reorganization of the provinces of Pakistan Prime Minister Muhammad Ali Bogra led it on 22 November 1954 and passed on 30 September 1955This program merged the four provinces of West Pakistan into a single province to parallel the province of East PakistanWest PunjabSind NWFP Baluchistan', 0, 0, 0, 1790967396054) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9c7ced31bac1c24c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Kabul, Swat, Kunhar, Panjkora, Bara, Kurram and Gomal are the rivers of ________?', '{"A":"Punjab","B":"Khyber Pakhtunkhwa","C":"Sindh","D":"GB"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Khyber Pakhtunkhwa often abbreviated as KPK.It was formerly known as the North-West Frontier Province, is one of the four provinces of Pakistan. It is located in the northwestern region of the country, along the Afghanistan–Pakistan border.', 0, 0, 0, 1790967396054) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_efcd7a2467527cfc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Construction of Taj Mahal was completed in ______?', '{"A":"1647","B":"1645","C":"1648","D":"1649"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Taj Mahal Construction started 1632 Construction completed 1647 Built by Mughal Emperor Shah Jehan Built in the memory of Mumtaz Mahal Height 73 M Taj Mahal Most visited monument of India as of July 2022 Architecture Ustad Ahmed Lahori', 0, 0, 0, 1790967396054) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_995a1aa2f2aecbe9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'What was the title of the pamphlet in which Chaudhry Rahmat Ali proposed the name "Pakistan"?', '{"A":"Now or Never","B":"Freedom for Muslims","C":"Pakistan Zindabad","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The word was first introduced now or never in 1933 by Chaudhry Rahmat Ali.The "Pakistan Declaration" titled Now or Never means Are We to Live or Perish Forever?In this pamphlet, the word Pakistan was used for the first time This pamphlet was derived from the two-nation theory of Muslim reformer Syed Ahmed Khanit was a pamphlet, referring to the names of the five northern regions of British India: PunjabAfghanistanKashmirSindhBaluchistan. (Pakistan)***', 0, 0, 0, 1790967396054) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f8f6e47201f9ea63', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'When did Arfa Karim die?', '{"A":"January 14, 2012","B":"January 14, 2010","C":"January 14, 2008","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Arfa Karim (1995-2012) was a Pakistani student and computer prodigy.She became the youngest Microsoft Certified Professional (MCP) at the age of 9 in 2004.She was invited to visit Microsoft headquarters in Redmond, Washington, and met with Bill Gates.', 0, 0, 0, 1790967396054) ON CONFLICT(id) DO NOTHING;
