INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3b9996c7c21c7a90', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which is the first private Airport in Pakistan?', '{"A":"Multan","B":"SialKot","C":"Gawadar","D":"All of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sialkot International Airport is the first privately owned public airport in Pakistan. It was built by the business community of Sialkot by their own efforts.', 0, 0, 0, 1790967396260) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_69be7861c6abab3f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The first international organization joined by Pakistan was the ______?', '{"A":"UNO","B":"RCD","C":"British CommonWealth","D":"IMF"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation British Commonwealth Pakistan emerged as an independent state on 14th August 1947. Pakistan joined FAO on 7 September 1947. Pakistan joined UNESCO on 14 September 1949.Pakistan joined World Bank in 1950. Pakistan joined IMF on 11 July 1950.Pakistan joined SEATO in 1954.', 0, 0, 0, 1790967396260) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b24fe9e36fefd9cc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Kulbushan Jadev, an Indian spy, was arrested from ______?', '{"A":"Sindh","B":"Balochistan","C":"KPK","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kulbhushan Sudhir Jadhav is an Indian national. It is alleged by the Pakistani government that he was arrested in the Pakistani province of Balochistan was arrested on charges of terrorism and spying for India''s intelligence agency, the Research and Analysis Wing.', 0, 0, 0, 1790967396260) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_5852136b19dad78c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', '16th August, 1946 was declared as direct action day by?', '{"A":"Congress","B":"Muslim League","C":"British Government","D":"Hindus of subcontinent"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Direct Action Day, also known as the 1946 Calcutta Killings, was a day of nationwide communal riots by the Indian Muslim community announced by Muhammad Ali Jinnah.It led to large-scale violence between Muslims and Hindus in the city of Calcutta (now known as Kolkata) in the Bengal province of British.', 0, 0, 0, 1790967396260) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ef6dfdc1c0cb0565', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who is the real founder of Muslim rule in northern India?', '{"A":"Mehmood of Ghazni","B":"Shahab-ud-Din Muhammad Ghori","C":"Muhammad bin Qasim","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Shahabuddin Ghori is the founder of the Islamic State in India.***Sultan Muhammad Ghori was born in 1162.Shahabuddin Ghori was a warrior of Turkish origin who traveled from Ghor, Afghanistan, and conquered Delhi in 1192. He was the true founder of Muslim rule in India.***Muhammad Ghori was the ruler of the Ghori dynasty, invaded India in the year 1206 C.E and their rule extended until 1526 C.E', 0, 0, 0, 1790967396297) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6e36d0624e793843', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Most of the plain areas of Balochistan are irrigated by two canals dug out from _____?', '{"A":"Sukkur barrage","B":"Guddu barrage","C":"Chashma barrage","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Patfeeder Canal and Kirthar canal dug out from Guddu Barrage.Guddu is a barrage on the Indus River near Kashmore. Iskander Mirza laid the foundation-stone of Guddu Barrage in 1957, inaugurated by Ayub Khan in 1962.', 0, 0, 0, 1790967396297) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_cb57fbb502d8628b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which of the following receives rains more than all the other valleys?', '{"A":"Chitral valley","B":"Kashmir valley","C":"Swat valley","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kashmir Valley receives the highest rainfall due to its location in the western Himalayas.It experiences heavy precipitation from monsoon and western disturbances.', 0, 0, 0, 1790967396297) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7f76dd4e5f297013', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which were the main parties in the elections of 1970?', '{"A":"Pakistan People’s Party","B":"Awami League","C":"Both A and B","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first-ever general elections were held on 7th December 1970.Yahya Khan issued a Legal Framework Order for the first general elections.300 of the 313 seats in the National Assemblyof which 162 were in East Pakistan and 138 in West Pakistan.A further thirteen seats were reserved for women (seven of which were in East Pakistan and six of which were in West Pakistan)LeaderSheikh Mujibur RehmanZulfikar Ali BhuttoPartyALPPPSeats won167 86Popular vote12, 937, 1626, 148, 923Percentage39.20%18.63%', 0, 0, 0, 1790967396297) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_177f24f957a34ccb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'According to 1941 Census ______ of the population of Kashmir state was Muslim.', '{"A":"75%","B":"77%","C":"88%","D":"93%"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the last census of British India in 1941, the total population of Kashmir and Jammu was 3,945,000. 1. The total Muslim population was 2,997,000 (75.97%), 2. The Hindu population was 808,000 (20.48%), 3. The Sikh 55,000 (1.39%)', 0, 0, 0, 1790967396297) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_cd9f5a56e7f9e8c8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which of the following opposed the Pakistan membership in United Nation?', '{"A":"Iran","B":"Egypt","C":"Afghanistan","D":"Malaysia"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Afghanistan opposed Pakistan’s membership in the United Nations at the time of Independence:****Afghanistan was the only country to vote against Pakistan''s accession to the United Nations after its independencePakistan officially joined the United Nations (UN) on 30 September 1947Pakistan has been elected seven times (tied with Colombia and India) into the UN Security Council, with the most recent term in 2013.', 0, 0, 0, 1790967396297) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_bd607aaa42ec4ace', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Artificial Forests being maintained in ______?', '{"A":"Changa Manga","B":"Multan","C":"DG Khan","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Changa Manga is one of the largest man-made forests in Pakistan, located in Punjab.It was originally planted during the British colonial era to provide timber for railway networks.', 0, 0, 0, 1790967396297) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_abb9e0cbf50246df', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Chandka Medical college is located at ______?', '{"A":"Larkana","B":"Hyderabad","C":"Nawab Shah","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Chandka is the old name of Larkana.Larakana is also called city of Guavas.Larkana is a city located in Sindh.', 0, 0, 0, 1790967396297) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a1c5963443f4218f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Bala Hisar fort built by _________?', '{"A":"Akbar","B":"Babur","C":"Shah Jahan","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Babur first built a fort here in 1526 after capturing Peshawar.First mentioned by 7th-century explorer Xuanzang, the fort was used as a royal residence for the Durrani Empire since December 1747.The Maratha Empire captured it after the Battle of Peshawar in 1758.The Sikhs reconstructed the fort after capturing Peshawar in March 1823.', 0, 0, 0, 1790967396334) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7405dcb483c89eb6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The Silver Fibre of Pakistan is ________?', '{"A":"Cotton","B":"Wheat","C":"Rice","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cotton is known as the "Silver Fibre" of Pakistan due to its economic importance and export value.It plays a key role in Pakistan’s textile industry, the backbone of the country''s economy.', 0, 0, 0, 1790967396334) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_1fe7fef8f506185f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'In 1859 Sir Syed Ahmed Khan established/set up a first school where Persian and English were taught?', '{"A":"Muradabad","B":"Lucknow","C":"Bijnaur","D":"Aligarh"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In 1859, Sir Syed Ahmed Khan established a school in Muradabad, where Persian and English were taught. Later, he founded the Mohammedan Anglo-Oriental College in Aligarh in 1875, which became Aligarh Muslim University.', 0, 0, 0, 1790967396334) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_20622ef37ad3a690', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The Faisal Mosque and International Islamic University were built with the financial support of ______?', '{"A":"Kingdom of Saudi Arabia","B":"Turkey","C":"Libya","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The mosque was built by a Saudi King named King Faisal who gifted it in recognition of friendship between Pakistan and Saudi Arabia.Faisal Mosque of Pakistan was opened to the public in 1986 OR 1987**On 18th June 1988 the first prayer was held in the Faisal mosque**The Faisal Mosque is the largest mosque in Pakistan,located in the national capital city of Islamabad.Completed in 1986,it was designed by Turkish architect Vedat Dalokay', 0, 0, 0, 1790967396334) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d6ce5aa8ee79dfa3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Against whom did Syed Ahmad Shaheed lead his Jihad movement?', '{"A":"Peshawar Ruler","B":"British Rule","C":"Sikh Ruler","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Syed Ahmad Shaheed (1786-1831) was a Muslim leader and reformer who founded the Jihad movement in India.He led a rebellion against the Sikh Empire in the early 19th century.The Jihad movement, also known as the Tariqah-i-Muhammadiyah.It aimed to reform Islamic practices, promote religious purification, and resist British colonial rule.', 0, 0, 0, 1790967396334) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ac511b5f2942c74e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which of the following is the Oldest Language of Pakistan?', '{"A":"Sindhi","B":"Urdu","C":"English","D":"Arabic"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sindh is one of the world''s oldest languages, written in right-handed Perso-Arabic script***30 languages are spoken in PakistanwhileFive languages have more than 10 million speakers each – Punjabi PashtoSindhiSaraikiUrdu.whileThe most widely spoken language in Pakistan is Punjabi (48 % speak), followed by the Punjabi variant Siraiki (10 percent),2nd Sindhi 12%Pashto 8%Balochi 3%Hindko 2%ND18-2-2023RY5022023', 0, 0, 0, 1790967396334) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_5b15baec9b4c25b4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Sulimani and Makrani are the two dialects of which language?', '{"A":"Balochi","B":"Sindhi","C":"Pushto","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sulaimani and Makrani are two of the primary dialects of the Balochi language.Balochi is a Northwestern Iranian language,Makrani is the second-most spoken Balochi dialect Additional informationBalochistanProvince status: 1 July 1970Capital: QuettaArea: 347,190 km²Share of Pakistan''s area: About 42%Largest province by: AreaLast updated 18-07-2026 by NA', 0, 0, 0, 1790967396334) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b3aa0ba5c86fa160', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'RCD became dissolve/dis-functional after Iranian Revolution in which year?', '{"A":"1964","B":"1965","C":"1969","D":"1979"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation RCD was established on: 21 July, 1964RCD was dissolved in: 1979RCD stand for Regional Cooperation for DevelopmentRCD: Established by Iran, Pakistan and TurkeyRCD headquarters: Iran', 0, 0, 0, 1790967396334) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ddbfae01bd2f5500', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which team was the runner-up of Pakistan Super League (PSL) 2020?', '{"A":"Islamabad United","B":"Karachi Kings","C":"Quetta Gladiators","D":"Lahore Qalandars","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan Super League (PSL) 2020Edition: FifthDates: 20 Feb – 17 Nov 2020Administrator: PCBFormat: Twenty20Venue: PakistanWinner: Karachi Kings (1st title)Karachi Kings won by: 5 wicketsRunner-up: Lahore QalandarsParticipants: 6Matches:34Player of the series: Babar Azam (Karachi Kings)Babar Azam made: 473 runsMost runs: Babar AzamMost wickets: Shaheen Afridi (Lahore Qalandars)Shahid Afridi took: 17 wickets', 0, 0, 0, 1790967396381) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_4b3b19e085bb6789', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which mineral is found in Saindak (Balochistan)?', '{"A":"Copper","B":"Limestone","C":"Petroleum","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Copper mineral is found in Saindak (Baluchistan)**Saindak project is operated with the collaboration of ChinaProject Location: Chaghi, Balochistan**The discovery of gold, copper & silver deposits at Saindak was made in the 1970sTrial production at the Saindak Copper-Gold project started in 1995.', 0, 0, 0, 1790967396381) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6448bc91bb9ecc94', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who is known as the founder of Tahrik-e-Raishmi Romal (The Silk Letter Movement)?', '{"A":"Maulana Mahmood ul Hassan","B":"Maulana Qasim Nanotvi","C":"Allama Iqbal","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Maulana Mahmood ul Hassan was an Indian Muslim scholar and an independence activist The Silk Letter Movement, also known as Tehreek-e-Reshmi RumalIt was initiated by Deobandi leaders, particularly Maulana Mahmood Hasan DeobandiThis movement, active between 1913 and 1920,Its headquarters were in Kabul,They aimed to achieve Indian independence from British rule by allying with the"Ottoman EmpireAfghanistanGermanyThe letters, written on silk cloth, were intercepted by the Punjab CID, revealing the plot.', 0, 0, 0, 1790967396381) ON CONFLICT(id) DO NOTHING;
