INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_1a983b51169e0ba0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Pakistan is located in which continent?', '{"A":"Africa","B":"Europe","C":"Asia","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan, officially the Islamic Republic of Pakistan, is a country in South Asia.Pakistan is the world''s fifth-most populous country.Pakistan is the world''s second-largest Muslim population.Pakistan is the 33rd-largest country by area.The capital of Pakistan is: Islamabadthe Currency of Pakistan is: the Pakistani rupee', 0, 0, 0, 1790967396517) ON CONFLICT(id) DO NOTHING;
