INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_507ed53ff3cc57eb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which is the coldest place of Pakistan?', '{"A":"Murree","B":"Skardu","C":"Jacobabad","D":"Hazara"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The coldest place in Pakistan is SkarduSkardu is a city in the Gilgit-Baltistan region of Pakistan and serves as the capital of the Skardu District. The coldest place in Pakistan can be the glacial parts of Gilgit Baltistan, where in winter the average temperature remains below -20.***GB is the coldest province in PakistanThe coldest region in the atmosphere is: MesosphereUlaanbaatar is the coldest capital city in the worldND-8-08-2023', 0, 0, 0, 1790967396644) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_0ba8df338eefda37', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'When did Swat valley become part of Pakistan?', '{"A":"28th July 1969","B":"4th April 1969","C":"29th June 1970","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation State of Swat was Established in 1849.On 28 July 1969, General Yahya Khan announce full integration states of Chitral, Dir and Swat.', 0, 0, 0, 1790967396644) ON CONFLICT(id) DO NOTHING;
