INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_89ea819ac13de03b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Chashma is situated in ______?', '{"A":"Bhakkar","B":"Kundian","C":"Dadu Khel","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Chashma is located near Kundian, in Mianwali District, Punjab, Pakistan.It is known for the Chashma Barrage and Chashma Nuclear Power Plant.', 0, 0, 0, 1790967396716) ON CONFLICT(id) DO NOTHING;
