INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f2239fe0ec486997', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The first Nuclear Power Plant (KANUPP) was set up in Pakistan in _____?', '{"A":"1972","B":"1970","C":"1974","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first nuclear power plant in Pakistan was established in Karachi With the help of Canada KANUPP is Pakistan''s first nuclear power plant, inaugurated on November 28, 1972, with a total gross capacity of 137 MW.whileK2 & K3 with the help of China K2 started on 21 May 2021 and has an 1100 MW capacity.K3 is expected to be started in 2022.', 0, 0, 0, 1790967396716) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_bd40968a3591d10f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Parachinar is the main town of ______?', '{"A":"Khyber Agency","B":"North Waziristan","C":"South Waziristan","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Parachinar is a town and the capital of the Kurram District in the province of Khyber Pakhtunkhwa, Pakistan. It is mainly inhabited by Pashtun. Parachinar is situated on the west of PeshawarParachinar is the closest point in Pakistan to Kabul.', 0, 0, 0, 1790967396716) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6e0ecc22de003fa9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The real name of Hazrat Laal Shahbaz Qalandar was ______?', '{"A":"Hazrat Usman Marvandi","B":"Hazrat Ahmed Sindhi","C":"Hazrat Zubair","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The full name of Hazrat Lal Shahbaz Qalandar: Syed Shah Hussain MarwandiLal Shahbaz Qalandar wrote several books in Persian and ArabicLal Shahbaz Qalandar was a Sufi saint and poet of present-day Pakistan and AfghanistanBorn: 1177, Marand, IranDied: February 19, 1274, SehwānPlace of burial: Darbar Hazrat Usman Marvandi Lal Shahbaz Qalandar, SehwānTitle: QalandarThe shrine of Hazrat Laal Shahbaz Qalandar is situated in Sehwan SindhND18-5-2023ND17-7-2023', 0, 0, 0, 1790967396716) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9cdec82a6fbcd47c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'What was the real name of Titu Mir?', '{"A":"Sayed Ahmad","B":"Nisar Ali","C":"Muhammad Ali","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Syed Mir Nisar Ali famous as Titumir, was a Bengali Muslim freedom fighter who led a campaign against the British rule in India during the 19th century.*********FIA VU ASSISTANT 02-01-2022', 0, 0, 0, 1790967396716) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d2783db614a843aa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Fall of East Pakistan was on _____?', '{"A":"16 December 1970","B":"16 December 1971","C":"20 December 1970","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation On 16 December 1971, East Pakistan was liberated from Pakistan as the newly independent state of Bangladesh.East Pakistan was the eastern provincial wing of Pakistan between 1947 and 1971.Its land borders were with India and Burma, with a coastline on the Bay of Bengal.India firstly recognized to Bangladesh', 0, 0, 0, 1790967396716) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_795323d83f235aef', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The Central National Muhammadan Association in 1877 was founded by _____?', '{"A":"Sir Syed Ahmed Khan","B":"Chaudhry Rehmat Ali","C":"Waqar ul Mulk","D":"Allama Iqbal","E":"Syed Ameer Ali"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Central National Muhammadan Association was a political organization founded by Syed Ameer Ali in Calcutta in 1877.', 0, 0, 0, 1790967396751) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e4efe04a746f83ea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Bari Doab lies between which two rivers?', '{"A":"Ravi & Chenab","B":"Sindh & Chenab","C":"Bias & Ravi","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Five Important Doabs of Pakistan Sindh Sagar Doab is b/w: Indus & Jhelum rivers Jech Doab is b/w: Jhelum & Chenab rivers Bari Doab is b/w: Ravi & Sutlej riversRachna Doab is b/w: Ravi & Chenab rivers Bias Doab is b/w: Bias & Sutlej rivers Doab Chaj is b/w: Chenab and Jhelum.', 0, 0, 0, 1790967396751) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_505af7416c8d8c25', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which of the following movements truly reflected the spirit of Hindu-Muslim Unity?', '{"A":"Swadeshi movement","B":"Khilafat movement","C":"Civil disobedience movement","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Started: 1919Ended: 1924Main Aim: Protect the Ottoman CaliphateKey Leaders: Ali Brothers, Maulana Abul Kalam AzadSupporter: Mahatma GandhiSignificance: Promoted Hindu-Muslim unityAssociated Movement: Non-Cooperation Movement', 0, 0, 0, 1790967396751) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_cc4814f963ffb370', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Mohammad Bin Qasim was tortured to death in a prison in Iraq during the reign of _____?', '{"A":"Yazid","B":"Waleed","C":"Sulaiman","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Habib bin Muhallab was the governor of Sindh after the death of Muhammad Bin Qasim.Mohammad Bin Qasim, the Arab conqueror of Sindh, was tortured to death in 715 CE during the reign of Caliph Sulaiman.', 0, 0, 0, 1790967396751) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_117d9be39f1af3dc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Roosevelt hotel of PIA is located in which country?', '{"A":"Washington DC","B":"Karachi","C":"New York","D":"London"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Roosevelt Hotel in New York City has been owned.It is operated by Pakistan International Airlines (PIA) since 1979.It is a historic hotel located in Midtown Manhattan.PIA has maintained ownership and operation of the hotel as a subsidiary asset.', 0, 0, 0, 1790967396751) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_0bf91b2f671f5ca1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Bhambore is an archaeological site located in _______?', '{"A":"KPK","B":"Punjab","C":"Balochistan","D":"Sindh"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bhanbhore or Bhambhore, is a city dating to the 1st century BCE located in modern-day Sindh, Pakistan.The city ruins lie on the N-5 National Highway, east of Karachi.', 0, 0, 0, 1790967396751) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_fe421bdda5a8623c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'In Pakistan, IRSA stands for ______?', '{"A":"Indus River System Authority","B":"International River System Authority","C":"Indus River System Agency","D":"Internal Research Systematic Agency","E":"All of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Indus River System Authority (IRSA) is a water regulator in Pakistan, established in 1992 as an act of Parliament.Headquarters Islamabad, PakistanLocation Pakistan: Khyber Pakhtunkhwa, Gilgit-Baltistan, Punjab, Balochistan, Sindh & Azad Kashmir.', 0, 0, 0, 1790967396751) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2370ebbbf90017e7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'In which year PIA was established?', '{"A":"1955","B":"1957","C":"1958","D":"1959"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In 1955, Orient Airways merged with a newly formed state-owned entity.This resulting in the establishment of Pakistan International Airlines (PIA) on March 11, 1955.PIA serves as Pakistan''s national flag carrier.', 0, 0, 0, 1790967396751) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_eda20722b6f3755a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Where is the National Museum of Pakistan located?', '{"A":"Karachi","B":"Jamshoro","C":"Larkana","D":"Hyderabad","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The National Museum of Pakistan is located in Karachi, Pakistan. Situated in Burns Garden on Dr. Zia-ud-Din Ahmed RoadEstablished on 17 April 1950.There are approximately 16 museums in Pakistan.', 0, 0, 0, 1790967396785) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3f2772dc8c5d02e4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'In Pakistan, which organization is responsible for regulation of stock exchange?', '{"A":"NADRA","B":"SBP","C":"NBP","D":"SECP","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation SECP stands for Securities and Exchange Commission of Pakistan.SECP headquarters located in Karachi, Sindh.', 0, 0, 0, 1790967396785) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_1a3478ba95845064', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'When Pakistan introduced National Identity cards (NIC)?', '{"A":"1962","B":"1948","C":"1957","D":"1963","E":"1973"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan introduced National Identity cards (NIC) in 1973Pakistan initiated its National Identity Card System in 1973 under Article 30The card was first issued manually on hand-written paper in 1973the computerized card was issued in 2000IN 2012 the smart card was issuedThe first national identity card was issued by the authority to Zulfiqar Ali Bhutto.ND2023-2-12', 0, 0, 0, 1790967396785) ON CONFLICT(id) DO NOTHING;
