INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b47acb3d2c14b458', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who was the First Pakistani to climb K-2?', '{"A":"Mohsan Rizvi","B":"Ashraf Aman","C":"Nazir Hussain","D":"Nazir Sabir"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ashraf Aman, a mountaineer, adventurer, and engineer.He became the first Pakistani to summit K2 in 1977.He received the Pride of Performance Award in 1982.Pakistani climber Muhammad Ali Sadpara went missing on K2 with two foreign climbers on 5 February 2021.Samina Baig became the first Pakistani woman to climb K2 in July 2022.', 0, 0, 0, 1790967396785) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_567297e75dec65e9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Baltistan is called ______?', '{"A":"Paradise","B":"Little Tibet","C":"Land of Fairies","D":"Beauty of Earth","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Baltistan also known as Baltiyul or Little Tibet.***Baltistan is a mountainous region in Gilgit-Baltistan, Pakistan-administered Kashmir. It is located near the Karakoram mountains just south of K2The average altitude of the region is over 3,350 meters (10,990 ft). Baltistan is largely administered under the Baltistan Division.***', 0, 0, 0, 1790967396785) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_df5fd079e2797899', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Pakistan recognized China in ________?', '{"A":"1947","B":"1948","C":"1950","D":"1951"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan''s first Muslim Country to recognize China Recognition Date: January 4, 1950 (shortly after the founding of the PRC on October 1, 1949) .Diplomatic Relations: Formal diplomatic ties were established later on May 21, 195', 0, 0, 0, 1790967396785) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6071f3a130245efb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'When Pakistan signed the Baghdad pact, later called CENTO?', '{"A":"29 September 1955","B":"13 September 1955","C":"23 September 1955","D":"23 September 1956"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan joined the CENTO on 23 September 1955 and left in 1979The Central Treaty Organization (CENTO),Formerly known as the Middle East Treaty Organization (METO)Also known as the Baghdad PactMilitary alliance of the Cold War.Headquarters:Baghdad (1955 – 1958)Ankara (1958 – 1979)Formed on 24 February 1955 by:IranIraqPakistanTurkeyand the United Kingdom.Last updated question by NA on 07 May 2026', 0, 0, 0, 1790967396785) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_67766740a38d96c0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'When was Makran acceded to Pakistan?', '{"A":"March 17, 1948","B":"April 17, 1948","C":"August 17, 1948","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistani Makran, a former princely state that acceded in 1948, was constituted after 1955 a district of Kalāt division. Makran acceded to Pakistan on March 17, 1948. Makran was a princely state ruled by the Gichki Nawabs, who were of Rajput origin.The Gichki tribe settled in the Gichk valley of Panjgur and ruled the state of Makran from 1740 until 1955. *****', 0, 0, 0, 1790967396833) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_668d62df76eba282', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Abdul Sattar Edhi was passed away on _____?', '{"A":"8th July 2017","B":"8th July 2016","C":"8th July 2015","D":"8th July 2014"}', 'B', NULL, 0, 0, 0, 1790967396833) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_dc01fb567fdd95c4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'In which of the following cities Pakistan Command and Staff College is located?', '{"A":"Quetta","B":"Karachi","C":"Multan","D":"Islamabad","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan Command and Staff College is located in Quetta. The Command and Staff College is the Pakistan Army''s staff college for mid-career army officers. As the Army Staff College it was initially established in 1905 at Deolali and later shifted to Quetta in 1907, Baluchistan.', 0, 0, 0, 1790967396833) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_93ea022759fba5d8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who established Federal Security Force?', '{"A":"Ayub khan","B":"Askandar mirza","C":"Zulifqar Ali bhutto","D":"Zia ul haq"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Federal Security Force (FSF) was established in 1972 by President Zulfiqar Ali Bhutto.It functioned as a paramilitary force under the direct control of the Government of Pakistan.', 0, 0, 0, 1790967396833) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_560877f9a231bf31', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'JAMSHED MARKER distinguished himself in the field of ______?', '{"A":"Teaching","B":"Diplomacy","C":"Fiction writing","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jamsheed Marker, was a Pakistani diplomat and a former cricket commentator. The recipient of Hilal-e-Imtiaz, he was associated with diplomatic career for over 42 years.', 0, 0, 0, 1790967396833) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6a1732d0fff27399', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'OGRA is the regulatory body for _____?', '{"A":"Banking Sector","B":"Electronic Media","C":"Oil and Geology","D":"Oil and Gas"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation OGRA stands for Oil and Gas Regulatory Authority.It is the regulatory body responsible for overseeing the oil and gas sector in Pakistan.It was established in 2002.It to ensure a fair and transparent regulatory framework for the exploration, production, transportation, and distribution of oil and gas resources.', 0, 0, 0, 1790967396833) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_5e74baeab4aaf09e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Muhammadan Educational Conference was established by Sir Syed Ahmed Khan in which year?', '{"A":"1863","B":"1886","C":"1867","D":"1898"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Muhammadan Educational Conference, was established in Aligarh in 1886History:The Al India Muhammadan Educational Conference promotes modern education for the Muslim community in India.It was founded by Sir Syed Ahmed Khan It was the origin of the All-Indian Muslim League.Muslim League was born in the 20th session of the All India Muhammad Educational Conference, Established by Syed Ahmed Khan in Aligarh in 1886.', 0, 0, 0, 1790967396833) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8d356242f77260cf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who was Al-Khwarizmi?', '{"A":"Mathematician","B":"Musician","C":"Chemist","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Full Name: Muḥammad ibn Mūsā Al-Khwārizmī.Field: Muslim mathematician and astronomer.Contributions: Introduced Hindu-Arabic numerals and algebra into European mathematics.Born: Khwarazm.Died: Baghdad, Iraq.Era: Islamic Golden Age (Abbasid era).', 0, 0, 0, 1790967396833) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ac3e1856f6b5c0a3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The length of Khojak Tunnel is _____?', '{"A":"5.9 KM","B":"4.9 KM","C":"2.9 KM","D":"3.9 KM"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Khojak TunnelLocationBalochistanLength3.9 KMConnectsQila Abdullah with ChamanLongest Railway Tunnel ofPakistanAlso known asShela Bagh TunnelLocatedWest of QuettaConstruction started1888Completed1891Recognition: The State Bank of Pakistan acknowledged the Khojak Tunnel''s significance.Five-Rupee Note: A picture of the tunnel was featured on the five-rupee note.Circulation Period: The note was in circulation from 1976 to 2005.', 0, 0, 0, 1790967396864) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_20ed248f8e93fae4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which day Pakistani celebrate on 5th February?', '{"A":"Quaid-e-Azam Day","B":"Kashmir Solidarity Day","C":"Union Parishad Polls","D":"Defense Day"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kashmir Solidarity Day or Kashmir Day is a national holiday observed in Pakistan Date: February 5The Event Length: 1 DayIt is Related to the Kashmir ConflictIt was Started by: Jamaat-e-Islami Pakistan in 1990It was first proposed by Qazi Hussain Ahmad In 1991, the then-Prime Minister of Pakistan Nawaz Sharif called for a "Kashmir Solidarity Day Strike"Addtional information:یوم یکجہتی کشمیر 5 فروری کو ہندوستان کے زیر انتظام جموں و کشمیر اور کشمیریوں کے ساتھ پاکستان کی حمایت اور اتحاد کو ظاہر کرنے کے لیے منایا جاتا ہے۔', 0, 0, 0, 1790967396864) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_34415825f9e89b68', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Pakistan won a gold medal for the first time in Olympics in _____ ?', '{"A":"1960","B":"1964","C":"1968","D":"1972"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan won its first Olympic Games gold medal in 1960By defeating India in the final of the men''s hockey competition.The Summer Olympics were held in Rome, Italy.Competitors: 44 (all men)Took part in 35 events in 7 sportsMedalsRanked 20thGold1Silver0Bronze1Total2Pakistan has won a total of 04 gold medals in the Olympic Games so far Rome in 1960. Mexico, held in 1968. Angeles, USA, held in 1984.Javelin Throw in Paris held in 2024. *****', 0, 0, 0, 1790967396864) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_bf2ecd9965f13db3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who presented the Nehru Report?', '{"A":"Jawaharlal Nehru","B":"Subhas Chandra Bose","C":"Motilal Nehru","D":"Muhammad Ali Jinnah"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Motilal Nehru presented the Nehru Report with his son, Jawaharlal Nehru.Date Presented: August 1928 (at the All Parties Conference in Lucknow)Main Goal: To draft a new constitution and demand Dominion Status for India in response to a challenge by the British Secretary of State, Lord Birkenhead.', 0, 0, 0, 1790967396864) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e6c1d15e906de074', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The first-ever women police station was established in ______?', '{"A":"Islamabad","B":"Lahore","C":"Karachi","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan’s first women police station inaugurated by late Prime Minister Benazir Bhutto in Islamabad on January 25, 1994پاکستان کے پہلے خواتین پولیس اسٹیشن کا افتتاح وزیر اعظم بے نظیر بھٹو نے 25 جنوری 1994 کو اسلام آباد میں کیا', 0, 0, 0, 1790967396864) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b00ff63dd7effd51', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which one is the largest medal of bravery of Pakistan Police?', '{"A":"Nishan-e-Haider","B":"Quaid-e-Azam Medal","C":"Hilal-e-Jurat","D":"Nishan-e-Pakistan"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Quaid-e-Azam Police Medal is the highest bravery award in Pakistan Police, established in 1989.It is awarded for extraordinary acts of courage and bravery in the line of duty.Additional Information:Nishan-e-Haider (highest military honor)Hilal-e-Jurat (military award for gallantry)Nishan-e-Pakistan (civilian award for outstanding service)Sitara-e-Pakistan (civilian award for outstanding service)Tamgha-e-Pakistan (civilian award for dedicated service)', 0, 0, 0, 1790967396864) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_84180b8d478a3f4a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'NUML (National University of Modern Languages) is in _____?', '{"A":"Lahore","B":"Karachi","C":"Islamabad","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation NUML (National University of Modern Languages) is located in Islamabad, Pakistan, and serves as its main campus.NUML has regional campuses in cities like Lahore, Karachi, Peshawar, and Quetta.It was established in 1969 and gained university status in 2000.', 0, 0, 0, 1790967396864) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_21bc688292940145', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Gwadar is located in the _____?', '{"A":"Punjab","B":"Sindh","C":"Kyber Paktunkhawa","D":"Balochistan"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Gwadar Port is located on the Arabian Sea in Balochistan, Pakistan.It was opened in 2002.Pakistan purchased Gwadar from Oman on September 8, 1958.It was officially became part of Pakistan on December 8, 1958.Gwadar was under Omani rule for 174 years, from 1783 to 1958.', 0, 0, 0, 1790967396864) ON CONFLICT(id) DO NOTHING;
