INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ff4d4bc79766d62b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The old name of Sahiwal is ______?', '{"A":"Montgomery","B":"Jacob Abad","C":"Lahore","D":"Fort Sandeman"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sahiwal was originally called Gogera.It named after a village on the left bank of the River Ravi.It was later renamed Montgomery.It is now known as Sahiwal, located in Punjab, Pakistan.', 0, 0, 0, 1790967396886) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c279d61cb55d8bd3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Dyarchy was introduced in the subcontinent in the year _____?', '{"A":"1919","B":"1929","C":"1939","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dyarchy particularly referred to the system of shared rule in British India established by the Government of India Acts 1919 Dyarchy means the double system of government in which two heads are responsible for administration.Dyarchy was introduced as a constitutional reform by Edwin Samuel Montagu and Lord Chelmsford The Government of India Act of 1935 ended the system of Diarchy and established ''provincial autonomy''.ND17-1-2023۔', 0, 0, 0, 1790967396886) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_38e436f3f844de70', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'When Hamdard newspaper was started?', '{"A":"1908","B":"1909","C":"1911","D":"1913"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Muhammad Ali Johar launched the English weekly The Comrade in 1911 in Calcutta.He launched an Urdu-language daily newspaper Hamdard in 1913.', 0, 0, 0, 1790967396886) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d0a0a9697be94278', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'When did Kanpur Mosque tragedy occur?', '{"A":"1911","B":"1912","C":"1913","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kanpur mosque situated in the Kanpur, India.It was demolished by rioters during Hindu-Muslim riots.Kanpur mosque tragedy took place in 1913.', 0, 0, 0, 1790967396925) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e8e4835c2074663c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'What is the power generation capacity of the Karachi nuclear power plant?', '{"A":"136 MW","B":"137 MW","C":"139 MW","D":"141 MW"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first nuclear power plant in Pakistan was established in Karachi With the help of Canada.KANUPP is Pakistan''s first nuclear power plant, inaugurated on November 28, 1972, with a total gross capacity of 137 MW.whileK2 & K3 with the help of China K2 started on 21 May 2021 and has an 1100 MW capacity.K3 is expected to be started in 2022.ND23-2-2023', 0, 0, 0, 1790967396925) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_4f3ad53db10bda98', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'When was Fort William College established?', '{"A":"1875","B":"1800","C":"1798","D":"1804"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fort William College was established by Lord Richard Wellesley, Governor General of India.Fort William College was an academy of oriental studies and a centre of learning.Founded on 18 August 1800.Founder: Lord Wellesley.', 0, 0, 0, 1790967396925) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_1b52e8eaa40258a7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'C.R Formula was given by _______?', '{"A":"Abul Kalam Azad","B":"Raj Gopal Acharia","C":"V.P. Menon","D":"Lord Wavell"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation It was a proposal formulated by Chakravarti RajagopalachariC. R. formula is also known as the Rajaji formula In 1942, Chakravarti Rajagopalachar opposed the Congress party by differing against the Quit India Movement and left the party C. R.''s formula solves the political deadlock between the All India Muslim League and the Indian National Congress on the independence of British India.The CR formula acted as the basis for the negotiations. Gandhi and Jinnah met in September 1944 to ease the deadlock.ND14-10-2023', 0, 0, 0, 1790967396925) ON CONFLICT(id) DO NOTHING;
