INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6e965847e456f02a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who was the first Pakistani doctor who lost his life due to COVID-19 infection and was posthumously awarded Nishan-e-Kashmir on March 27, 2020?', '{"A":"Muhammad Usama","B":"Usama Riaz","C":"Usman Raza","D":"Raza Usman"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Riaz died on 23 March 2020, from COVID-19 complications at the age of 26.Riaz was the first Pakistani doctor to die from the virus.On 27 March 2020, he was posthumously awarded the Nishan-e-Kashmir, the highest award of the state, by Prime Minister of Azad Kashmir for his services.', 0, 0, 0, 1790967397661) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_5e212d5a86884476', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Due to Geostrategic position, no peace is possible in Afghanistan without the active support and cooperation of ______?', '{"A":"India","B":"Iran","C":"Pakistan","D":"China"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan shares a long border with Afghanistan and has significant geopolitical influence in the region. Due to its strategic location, Pakistan plays a crucial role in Afghanistan''s stability and security.Historically, Pakistan has had close ties with various Afghan groups and has been involved in Afghan affairs.', 0, 0, 0, 1790967397661) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8e0d570f659ca03e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'In the context of Pakistan''s political and judicial history what does PCO stands for?', '{"A":"Provisional Court Organization","B":"Pakistan Constitutional Ordinance","C":"Provincial Constitutional Order","D":"Pakistan''s Courts Ordinance"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In Pakistan''s political and judicial history, PCO stands for Provincial Constitutional Order.It issued during military regimes to suspend or amend the constitution, often affecting the judiciary.', 0, 0, 0, 1790967397692) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7b6437fd703f852a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The Lucknow pact granted the right of Separate Electorates to the _____?', '{"A":"Hindus","B":"Sikhs","C":"Muslims","D":"Christians"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation On 1st October 1906, a Muslim political delegation led by Aga KhanMet with the Viceroy of India to demand a separate electorate for Muslims.This delegation played a crucial role in the establishment of the Muslim League in 1906', 0, 0, 0, 1790967397692) ON CONFLICT(id) DO NOTHING;
