INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c54c5bfa5bb4fc8b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who was the founder of FIA (Federal Investigation Agency) Pakistan?', '{"A":"Zulfiqar Ali Bhutto","B":"General Zia ul Haq","C":"Pervez Musharraf","D":"None of these."}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Zulfiqar Ali Bhutto was the founder of FIA (Federal Investigation Agency) Pakistan****FIA of Pakistan was established on January 13, 1975****It was established under FIA Act, 1974 (Act-VIII of 1975) promulgated on 13-01-1975.FIA stands for Federal Investigation Agency********The operational structure of FIA****Headquarters----> Islamabad, PakistanAgency executive-->Mohsin Hassan Butt[1], Director-GeneralParent agency------->Ministry of InteriorMajor Units --------> 13', 0, 0, 0, 1790967398029) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_4444e58a384315e7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who founded the Pakistan Times?', '{"A":"Rehmat Ali","B":"Mian Iftikharuddin","C":"Who founded the Pakistan Times?","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation It was owned and operated by Mian Iftikharuddin, a Punjabi politician formerly of the Indian National Congress but of All-India Muslim League after 1946. The newspaper started publication on 4 February 1947. Its editor-in-chief in the 1940s was the communist poet Faiz Ahmed Faiz.', 0, 0, 0, 1790967398029) ON CONFLICT(id) DO NOTHING;
