INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a84660885323d7ff', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Path: highway', '{"A":"Yard:alloy","B":"Vien :artery","C":"branch :tree","D":"walkway:Ramp","E":"Brook:River"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A path is a little road (often so small that only one person can use it at a time), while a highway is a large road with room for thousands. A brook and a river have a similar size relationship.', 0, 0, 0, 1790967398859) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ece5cbe5b34d9053', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'M4 moterway will link ______', '{"A":"Faisalabad-Lahore","B":"Faisalabad-Multan","C":"Lahore- Vehari","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The M4 is a north–south motorway in Pakistan that connects the cities of Faisalabad and Multan. The 309 km motorway also connects to the M2, M3 and M5 motorways.', 0, 0, 0, 1790967398859) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a936e22a7ca16a8c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Hazrat Lal Shahbaz Qalandar is buried in ?', '{"A":"Multan","B":"Lahore","C":"Krachi","D":"Sehwan Shareef","E":"None"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lal Shahbaz Qalandar Place of burial: Darbar Hazrat Usman Marvandi Lal Shahbaz Qalandar, SehwānLal Shahbaz Qalandar wrote several books in Persian and ArabicLal Shahbaz Qalandar was a Sufi saint and poet of present-day Pakistan and AfghanistanThe full name of Hazrat Lal Shahbaz Qalandar: Syed Shah Hussain MarwandiBorn: 1177, Marand, IranDied: February 19, 1274, SehwānTitle: QalandarThe shrine of Hazrat Laal Shahbaz Qalandar is situated in Sehwan SindhND17-7-2023', 0, 0, 0, 1790967398859) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_4b3a8eaa479bea44', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The Salt range is situated between rivers Soan and ____?', '{"A":"River Jhelum","B":"River \tChenab","C":"River \tHuro","D":"River \tKabul","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The salt range is situated between rivers Soan and River JhelumThe highest peak of salt range is Soan SakaserThe Salt Range is a mountain range in the north of the Punjab province of PakistanThe range extends along the south of the Potohar Plateau and the north of the Jhelum River.Sakesar (Khushab District) is the highest mountain in the salt region675 meters is the average height of the salt rangeThe Upper Indus plain area is located in the South of the Salt Range and east of Sulemania******ND17-7-2023', 0, 0, 0, 1790967398859) ON CONFLICT(id) DO NOTHING;
