INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_cf6211b4352ce321', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The Mongols defeated?', '{"A":"The Abbasids","B":"Salahuddin Ayyubi","C":"Ummayed","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Mongol Empire of the 13th and 14th centuries It was the largest contiguous land empire in history.Founded: 1206Date dissolved: 1368', 0, 0, 0, 1790967398918) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_29fb228cac14003b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which Pakistan Cricketer announced retirement from ODI cricket on 10 November 2015?', '{"A":"Shoaib Malik","B":"Kamran Akmal","C":"Younas Khan","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Younis retired from ODI cricket in November 2015. He retired from all forms of international cricket after the series against the West Indies in May 2017.', 0, 0, 0, 1790967398918) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c0057c755cf28f19', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who was the first Civilian to hold the post of CMLA of Pakistan?', '{"A":"Zia-ul-Haq","B":"Ayoub Khan","C":"Zulfiqar Ali Bhutto","D":"Liaqat Ali Khan","E":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Zulfikar Ali Bhutto was a politician who served as the 9th Prime Minister of Pakistan from 1973 to 1977, and prior to that as the fourth President of Pakistan from 1971 to 1973. CMLA means Chief Martial Law Administrator.', 0, 0, 0, 1790967398918) ON CONFLICT(id) DO NOTHING;
