INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7022155a533b2a8d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'River Kabul joins Indus at?', '{"A":"Jhelum","B":"Mianwali","C":"Attock","D":"Sahiwal"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation River Kabul joins Indus at Attock.It flows from Afghanistan into Khyber Pakhtunkhwa before joining Indus.It passes through Kabul (Afghanistan), Jalalabad, and Peshawar.Additional information:Indus River – Longest river of PakistanJhelum River – Joins Indus at TrimmuChenab River – Joins Indus at PanjnadRavi River – Tributary of IndusSutlej River – Joins Indus at PanjnadLast verified on 19-07-2026', 0, 0, 0, 1790967399229) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f1afaf1f2344c857', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Mangla Dam was constructed/situated on the which river?', '{"A":"Indus","B":"Sutlej","C":"Jhelum","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Mangla Dam is situated on the Jhelum River.It is the seventh-largest dam in the world.Construction was started in 1961.It was completed in 1967.It has 5 tunnels and a power station.Last verified on 07-06-2026', 0, 0, 0, 1790967399229) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2372b92ba57b61d0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Baglihar Dam is constructed by India on over which river?', '{"A":"Sutlej","B":"Ravi","C":"Jhelum","D":"Chenab"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Baglihar Dam is a hydroelectric project constructed by India.It is built on the Chenab River in Jammu and Kashmir.The project was planned in 1992 and approved in 1996.Construction began in 1999 and the dam was completed in phases.Commissioning:Stage I: 2008–2009Stage II: 2015–2016Estimated Cost: Around US$1 billionLast verified on 16-05-2026', 0, 0, 0, 1790967399229) ON CONFLICT(id) DO NOTHING;
