INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b659cfa5a1a6f91a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which city is called the Heart of KPK?', '{"A":"Mardan","B":"Mansehra","C":"Abbotabad","D":"Peshawar"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Peshawar is considered the heart of KPK.The provincial capital, largest city.Known as the "City of Flowers".Located in the north-west.Additional information:Manchester of Pakistan: FaisalabadGateway of Pakistan: KarachiBrasilia of Pakistan: IslamabadCity of Textiles: FaisalabadCity of Lightening: KarachiLast verified on 17-07-2026', 0, 0, 0, 1790967399229) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_57b994cd36934044', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Lady Finger Peak is located in which country?', '{"A":"China","B":"Nepal","C":"India","D":"Pakistan"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lady Finger Peak, also known as Bublimotin, is located in Pakistan It is a distinctive rock spire situated in the Batura MuztaghA sub-range of the Karakoram Range in the Gilgit-Baltistan region. First ascent: May 22, 1982, by Patrick Cordier and Jacques MaurinLast updated by NA on 16-07-2026', 0, 0, 0, 1790967399229) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a2c88f7c2f5b2282', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which mountain range separate Afghanistan from Pakistan?', '{"A":"Pamir Range","B":"Karakorum Range","C":"The Hindu Kush Range","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Hindu Kush Range separates Afghanistan and Pakistan.It stretches across central Afghanistan into northern Pakistan.Length: Approximately 800 km (500 miles)Area: About 152,800 km²Additional information:Himalayas → Pakistan, India, Nepal, Bhutan, ChinaKarakoram → Pakistan, China, India (Contains K2 – 8,611 m)Pamir → Tajikistan, Afghanistan, China, Kyrgyzstan ("Roof of the World")Sulaiman Range → Pakistan and AfghanistanSafed Koh (Spin Ghar) → Along the Pakistan–Afghanistan borderLast verified on 15-07-2026', 0, 0, 0, 1790967399229) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_cf01841d43a14c8c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Balochistan Became Province in _______?', '{"A":"14th August 1973","B":"14th August 1947","C":"1st July 1970","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Province status: 1 July 1970Capital: QuettaArea: 347,190 km²Share of Pakistan''s area: About 42%Largest province by: AreaLast verified on 06-07-2026', 0, 0, 0, 1790967399260) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8791e9ffab796ba0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Tarbela Dam is located in which district?', '{"A":"Hafizadad","B":"Jhelum","C":"Mirpur","D":"Swabi"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tarbela Dam was built on the Indus River in Swabi District Tehsil Topi of KPK.It is the largest earth-filled dam in the world.The construction began in 1968.They were opened in 1976.Height: 470 feet (143 m)Last verified on 30-03-2026', 0, 0, 0, 1790967399260) ON CONFLICT(id) DO NOTHING;
