INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d177cf45dcfa29b0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The largest earth filled dam of the world is _____?', '{"A":"Mangla  dam","B":"Basha dam","C":"Tarbela dam","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Tarbela Dam in Pakistan is the largest earth-filled dam in the world.It is built on the Indus River.Additional information:Location: Haripur District, Khyber Pakhtunkhwa, PakistanCompleted: 1976Length: 2,743 meters (longest earth-filled dam)Height: 143 metersPurpose: Irrigation, hydroelectric power (3,478 MW), flood controlLast verified on 15-01-2026', 0, 0, 0, 1790967399260) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9edb1260b2f7a13c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which of the following mountain peaks is called Killer Mountain?', '{"A":"Nanga Parbat","B":"Godwin Austin","C":"Broad Peak","D":"Raka Poshi"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nanga Parbat is famously called the "Killer Mountain."Its height 8,126 metres (26,660 feet).It is located in Gilgit-Baltistan.It is part of the Western Himalayas.It is locally known as Diamer.It is the 9th-highest mountain in the world.It is famously called the "Killer Mountain."First Ascent: 3 July 1953Shehroze Kashif became the youngest Pakistani to successfully summit Nanga Parbat.Last verified by on 16-05-2026', 0, 0, 0, 1790967399260) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a0e66b88f293bf38', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Indus River originates from _____?', '{"A":"Ladakh","B":"Tibet","C":"Jammu","D":"Kashmir"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Indus River starts in Tibet (China).It is originates from the Mansarovar lake.It is flows through India, Pakistan.It is finally falls into the Arabian Sea near Karachi.River Indus starts making a delta near the city of Thatta.Additional information:The old name of the Indus river was: SindhuNational River of Pakistan: Indus RiverThe Six Barrages constructed in Indus River.Indus River Length: 3,180 kmIndus River 2nd source: Gar TsangpoThe upper Indus plain starts from Kalabagh.The upper Indus plain ends at Mithankot.Last verified on 17-03-2026', 0, 0, 0, 1790967399260) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_4ca99990bafcbba5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which lake in Sindh overflew because of floods in 2022?', '{"A":"Keenhar Lake","B":"Attabad Lake","C":"Manchar Lake","D":"Malir Lake"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lake: Manchar LakeProvince: SindhFlood Year: 2022Drainage Efforts: September 2022Villages Affected in Dadu: About 300Last verified on 09-07-2026', 0, 0, 0, 1790967399260) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_57eff7705fa1dd9b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which was the first barrage constructed / commissioned to work in Pakistan (1932)?', '{"A":"Sukkur Barrage","B":"Kotri Barrage","C":"Chashma Barrage","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sukkur Barrage is the first major barrage built on the Indus River in Pakistan.It was commissioned in 1932 during British India to control floods and provide irrigation.It is located near Sukkur, Sindh.It has 66 gates to control water flow for farming and flood management.Additional information:Kotri Barrage – 1955Gudu Barrage – 1968Chashma Barrage – 1971Last verified on 06-03-2026', 0, 0, 0, 1790967399293) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_dde47588d9dd4614', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Guddu Barrage was constructed on the river _______?', '{"A":"River Ravi","B":"River Indus","C":"River Jhelum","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation River: Indus RiverLocated: Kashmore, SindhFoundation Laid: February 1957Foundation by: President Iskander MirzaCompleted: 1962Construction Cost: 474.8 million rupeesLast verified on 09-07-2026', 0, 0, 0, 1790967399293) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_bd6370c69e57a75d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Kirthar national park is in which province of Pakistan?', '{"A":"Punjab","B":"Sindh","C":"KPK","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Province: SindhEstablished: 1974Mountain Range: Kirthar RangeHighest Peak: Zardak Peak – 2,260 m (7,430 ft)Elevation of Kirthar Mountains: 2,260 m (7,410–7,430 ft)Last verified on 07-07-2026', 0, 0, 0, 1790967399293) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_03b686a8458617ff', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The Arabian Sea is part of which ocean?', '{"A":"Indian Ocean","B":"Southern Ocean","C":"Atlantic Ocean","D":"Pacific Ocean"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Arabian Sea is part of the Indian Ocean.It is located in the northwestern part of the Indian Ocean.It lies between the Indian Peninsula and Arabian Peninsula.It covers an area of about 3.86 million km².Additional information:Location: Between India, Pakistan, Arabian Peninsula, and Horn of AfricaIt connects with the Persian Gulf through the Gulf of Oman.Last verified on 16-06-2026', 0, 0, 0, 1790967399293) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6b06c53d08916465', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The area between rivers Jhelum and Chenab is called?', '{"A":"Chaj","B":"Gandhara","C":"Harrapa","D":"None of these"}', 'A', NULL, 0, 0, 0, 1790967399293) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c29a21dbdf9f53f2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The smallest/shortest dam in Pakistan is?', '{"A":"Tarbela Dam","B":"Mangla dam","C":"Warsak dam","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Warsak Dam is the smallest major dam in Pakistan.It is located near Peshawar in Khyber Pakhtunkhwa.It is built on the Kabul River.It is construction began in 1949.Opened: 1960Height: 76 mLength: 140.2 m (460 ft)It was completed under the Colombo Plan in two phases.It was financed by the Government of Canada.Additional information:The largest dam of Pakistan is the Tarbela Dam.Last verified on 24-06-2026', 0, 0, 0, 1790967399293) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c8d056e235a675cc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which is the smallest river of Pakistan?', '{"A":"Indus","B":"Ravi","C":"Neelm","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The smallest river of Pakistan is River Ravi.It is one of the five major rivers of the Indus River system.Ravi originates from Himachal Pradesh (India) and enters Pakistan.It flows along the Indo-Pak border before fully entering Punjab.Additional information:The largest/longest river of Pakistan is River Indus.It flows from Tibetan Plateau and enters Pakistan from Gilgit-Baltistan.It finally drains into the Arabian Sea near Karachi.Last verified on 24-06-2026', 0, 0, 0, 1790967399293) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_39fe5a54459d988a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which city in Punjab, Pakistan, is renowned for beautiful camel skin art, handicrafts, and glazed pottery?', '{"A":"Quetta","B":"Karachi","C":"Sukkur","D":"Multan"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Multan is famous for camel skin art, handicrafts, and glazed pottery, especially its traditional painted lamps.Province: Punjab, PakistanNickname: City of SaintsLast verified on 22-06-2026', 0, 0, 0, 1790967399293) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_0694177ac00e5aa2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Baltoro Glacier is found in _____ ranges of Pakistan.', '{"A":"Hindu Kush","B":"Karakorum","C":"Himalayas","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Range: Karakoram MountainsLength: about 63 km (39 miles)Area: about 1,500 sq km (580 sq mi)Type: Non-polar glacierLocation: Shigar District, Gilgit-Baltistan, PakistanLast verified on 10-06-2026', 0, 0, 0, 1790967399343) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_53fab392c5e976da', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'In which year was the Gwadar Port Authority established?', '{"A":"1998","B":"2000","C":"2002","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Gwadar Port Authority (GPA) was established in 2002.The Gwadar Port is situated on the Arabian Sea at Gwadar in the Balochistan, Pakistan.Omani Rule: Gwadar remained under Oman for 174 years (1783–1958).Purchase Date: 8 September 1958 by Pakistan.Official Integration: 8 December 1958.Additional information:Pakistan has three big sea ports:Karachi PortMuhammad Bin Qasim portGwadar portLast verified on 16-03-2026', 0, 0, 0, 1790967399343) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_bbc9a46ca1c78e31', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Hub Dam is located in which province?', '{"A":"Sindh","B":"Punjab","C":"Khyber Pakhtunkhwa","D":"Balochistan"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hub Dam is located in Balochistan province.It is near the Sindh border and supplies water to Karachi.It is built on the Hub River about 56 km from Karachi.The dam lies between Lasbela District (Balochistan) and Karachi (Sindh).Last verified on 20-06-2026', 0, 0, 0, 1790967399343) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_00ad002f6a721c96', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The Indus Waters Treaty was signed on 19 September 1960 in Karachi by?', '{"A":"Jawaharlal Nehru and Ayub Khan","B":"Indira Gandhi and Ayub Khan","C":"Jawaharlal Nehru and Zulifqar Ali Bhutto","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Indus Water Treaty was signed between Pakistan (President Ayub Khan) and India (Prime Minister Jawaharlal Nehru).Eugene R. Black (President of the World Bank) brokered the Indus Waters Treaty on behalf of the World Bank.It was signed on September 19, 1960, in Karachi.It became effective on April 1, 1960.Western Rivers (given to Pakistan): Indus, Jhelum, ChenabEastern Rivers (given to India): Ravi, Beas, SutlejLast verified on 30-03-2026', 0, 0, 0, 1790967399343) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ce78a8bd22965d5c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'How many barrages are there in Sindh?', '{"A":"4","B":"3","C":"2","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There are three major barrages in Sindh.Guddu Barrage – Foundation laid on 2 February 1957Kotri Barrage – Completed in 1955Sukkur Barrage – Built 1923–1932 (British era, also called Lloyd Barrage)These barrages are built on the Indus River.Additional information:Sindh is known as Bab-ul-Islam.It has 30 districts and 6 divisions.Kirthar Range is the main mountain range in Sindh.Last verified on 26-04-2026', 0, 0, 0, 1790967399343) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3874ae0bce64046a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The Kirthar National Park lies in which districts of Sindh?', '{"A":"Dadu  & Jamshoro","B":"Dadu & Karachi","C":"Both A and B","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Districts: Dadu + Jamshoro / Dadu + KarachiProvince: SindhEstablished: 1974Type: National Park / Wildlife ReserveArea rank: 3rd largest national park in PakistanStatus: Important Bird and Biodiversity Area (IBA) since 2004Last verified on 14-06-2026', 0, 0, 0, 1790967399343) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_cdc2618f3d23c7bf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Through which pas, Karakorum highway (Shahrah-e-Resham) connects Pakistan with China?', '{"A":"Khunjerab Pass","B":"Khyber Pass","C":"Tochi Pass","D":"Gomal Pass"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Shahrah-e-Resham (Karakoram Highway) connects Pakistan and China through Khunjerab Pass.It is the highest paved international road in the world.It links Hassan Abdal (Pakistan) with Kashgar (China).It passes through the Karakoram mountain range.It is a symbol of strong Pakistan–China friendship.Additional information:The highway is also known as the Karakoram Highway (N-35).It was completed in 1979.Its total length is about 1,300 km.It is often called the “Eighth Wonder of the World” due to its difficult terrain.Last verified on 17-05-2026', 0, 0, 0, 1790967399343) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_801ee65b2bf28033', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Famous Lake Saif-ul-Maluk is situated in?', '{"A":"Kaghan (Naran)","B":"Swat","C":"India","D":"Murree"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Location: Kaghan Valley, Naran areaDistrict: MansehraProvince: Khyber Pakhtunkhwa (KPK)Distance from Naran: ~9 km northNearby peak: Malika Parbat (highest in Kaghan Valley)Last verified on 03-04-2026', 0, 0, 0, 1790967399343) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_668a4a4d8357b231', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Who mediated/brokered the Indus Water Treaty in 1960?', '{"A":"Soviet Union","B":"China","C":"World Bank","D":"UNO"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Indus Waters Treaty was signed on September 19, 1960, in Karachi.It was signed between Pakistan (President Ayub Khan) and India (Prime Minister Jawaharlal Nehru).It was brokered by the World Bank.It became effective on April 1, 1960.Western Rivers (given to Pakistan): Indus, Jhelum, ChenabEastern Rivers (given to India): Ravi, Beas, SutlejLast verified on 30-03-2026', 0, 0, 0, 1790967399386) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_fe38daa9c3d1f3df', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which is the second biggest/largest Dam of Pakistan?', '{"A":"Tarbela","B":"Mangla","C":"Warsak","D":"Hub"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Second largest dam: Mangla DamRiver: Jhelum RiverCompletion year: 1967Location: Mirpur, Azad KashmirAdditional information:First largest dam: Tarbela DamLast verified on 12-06-2026', 0, 0, 0, 1790967399386) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_21f7c75d1f4b558c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'In Pakistan Banana is mostly cultivated in which province?', '{"A":"Punjab","B":"FATA","C":"Sindh","D":"Balochistan"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Banana is mostly cultivated in Sindh province of Pakistan.More than 90% of banana cultivation area is in Sindh.It contributes about 80% of total national banana production.Pakistan grows bananas on around 34.9 thousand hectares of land.Last verified on 12-06-2026', 0, 0, 0, 1790967399386) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_63c60ee9e8bb149e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Approximately how many Afghan refugees were in Pakistan at the peak of the crisis?', '{"A":"Three and half million","B":"Two million","C":"One million","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation At the peak of the Afghan refugee crisis, Pakistan hosted approximately 3.5 million Afghan refugees.This occurred mainly during the Soviet-Afghan War (1980s).This making the Pakistan one of the largest refugee-hosting countries at that time.Last verified on 12-06-2026', 0, 0, 0, 1790967399386) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b679f75bf02d348a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which is the largest natural fresh water lake of Pakistan?', '{"A":"Kaghan Lake","B":"Satpara Lake","C":"Manchhar Lake","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Manchhar Lake is the largest natural freshwater lake in Jamshoro Sindh Pakistan.It collects water from the Kithar mountain range.It is one of South Asia''s largest.It covers an area of 23.5 km (14.6 mi)It is the part of Indus River basin.Last verified on 31-03-2026', 0, 0, 0, 1790967399386) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_63a967b52208b63d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The dam inaugurated in October 2020 by the Sindh Government in Nagarparkar, District Tharparkar, was?', '{"A":"Kalidas Dam","B":"Sohan Dam","C":"Ningharahr Dam","D":"Dasu Dam"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dam Name: Kalidas DamLocation: Nagarparkar, Tharparkar, SindhInauguration Date: 29 October 2020Cost: Rs. 333 millionPurpose: Water storage and supplyAdditional information:Dams completed by Sindh Government at that time: 23Additional dams under construction: 11Expected completion of those dams: by July 2022Last verified on 11-06-2026', 0, 0, 0, 1790967399386) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_aea3e30b9e5ac999', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Mohenjo-Daro is located in which district of Sindh?', '{"A":"Dadu District","B":"Larkana District","C":"Hyderabad District","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mohenjo-Daro is located in the Larkana district of Sindh.Mohenjo Daro means Mound of the Dead.It was discovered in 1922 by R. D. Banerji.It is a 4000-year-old city of the Indus Civilization.It was built around 2500 BC.Last verified on 11-06-2026', 0, 0, 0, 1790967399386) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9001f2c8281e96cd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'In Pakistan "City of Garden" is known as?', '{"A":"Karachi","B":"Lahore","C":"Islamabad","D":"Peshawar"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lahore is known as the "City of Gardens" (باغوں کا شہر).The title was given because Lahore historically had a large number of beautiful gardens.Famous Garden: Shalimar GardensRiver: Ravi RiverIt is also known as the Cultural Heart of Pakistan.Last verified on 10-06-2026', 0, 0, 0, 1790967399386) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_81c11b483ed6587a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which city of Pakistan is called Manchester of Pakistan?', '{"A":"Islamabad","B":"Lahore","C":"Faisalabad","D":"Gujranwala"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Faisalabad is called Manchester of Pakistan.Because it''s the biggest textile city in Pakistan.It is formerly known as Lyallpur.It is the third-largest city in Pakistan.It is the second largest city in the Province of Punjab.It is famous for its textile mills.Last verified on 16-03-2026', 0, 0, 0, 1790967399424) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ee0e516e9937775e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which is the Smallest province of Pakistan by area?', '{"A":"KPK","B":"Punjab","C":"Baluchistan","D":"Sindh"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The smallest province of Pakistan by area is KPK.Balochistan is the largest province of Pakistan by area.Area wise second largest province of Pakistan is Punjab.Sr. No.Province / Capital territoryArea (km²)1Balochistan347,1902Punjab205,3453Sindh140,9144KPK101,741Last verified on 30-03-2026', 0, 0, 0, 1790967399424) ON CONFLICT(id) DO NOTHING;
