INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d17b56bc00c2379d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Hanna lake is located in _____?', '{"A":"Karachi","B":"Dadu","C":"Quetta","D":"Peshawar"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hanna Lake is located near Quetta city (Balochistan, Pakistan).It is about 10 km away from Quetta in Urak Valley.The lake was built in 1894 during British rule.It is a famous tourist spot in Pakistan.It covers an area of about 27 acres.Last verified on 06-06-2026', 0, 0, 0, 1790967399424) ON CONFLICT(id) DO NOTHING;
