INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_76205faa27088e5f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which is largest (longest) and important river of Pakistan?', '{"A":"Indus","B":"Ravi","C":"Jehlum","D":"Chenab"}', 'A', NULL, 0, 0, 0, 1790967399497) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_acb3d5c3c77e25d4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Blind Dolphins are found in _______ river in Pakistan.', '{"A":"Jhelum","B":"Indus","C":"Ravi","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Blind dolphins are found in the Indus River.They are also called Indus River Dolphin or “Bhulan”.Scientifically described in 1853 by Richard Owen.Known for side-swimming behavior.It is one of the rare freshwater dolphin species.Last verified on 02-05-2026', 0, 0, 0, 1790967399534) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ac1d707481e01790', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'What is the length of the coastal line of Sindh, Pakistan?', '{"A":"100 km / 150 miles","B":"250 km / 200 miles","C":"150 km / 75 miles","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sindh coastline: 250 km / 200 milesTotal Pakistan coastline: 1,046 kmLongest coastline: Balochistan (~800 km)Sea: Arabian SeaMain coastal city: KarachiLast verified on 01-05-2026', 0, 0, 0, 1790967399534) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_35cb161de8d4f5a4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which is the first dry port of Pakistan?', '{"A":"Lahore","B":"Karachi","C":"Islamabad","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation First dry port: Lahore Dry PortYear: 1973Authority: Pakistan RailwaysLocation: Mughalpura, LahorePurpose: Inland cargo/custom clearanceAdditional information:Karachi Dry Port (1974)Quetta Dry Port (1984)Peshawar Dry Port (1986)Multan Dry Port (1988)Rawalpindi Dry Port (1990)Last verified on 01-05-2026', 0, 0, 0, 1790967399534) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b9367932d2a7b28e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Kallar Kahar lake is located in _____?', '{"A":"Suleman range","B":"Salt range","C":"Kirthar range","D":"Noshaq"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kallar Kahar is a town and subdivision of Chakwal District in Punjab, Pakistan. It is the capital of Kallar Kahar Tehsil.Range: Salt RangeFeatures: Salt water lake, natural gardens, dancing peacocks, spiritual sitesAltitude: 1,500 ft above sea levelArea: 8 kmMaximum depth: 4–5 ftLast verified on 01-05-2026', 0, 0, 0, 1790967399534) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a3eede2a7e4f4dc7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Lalusar Lake is situated in ____?', '{"A":"Kaghan Valley","B":"Swat Valley","C":"Neelam Valley","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lulusar Lake is located in Kaghan Valley (KPK).It lies about 48 km from Naran.The lake is at an ارتفاع of 3,410 meters (11,190 ft).It is the main source of the Kunhar River.Known for its natural beauty and tourism.Last verified on 01-05-2026', 0, 0, 0, 1790967399534) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_1c6e0f5982acc6fb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Islamabad was declared the Capital of Pakistan in ______?', '{"A":"1960","B":"1958","C":"1965","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Islamabad was named on 24 February 1960.It was declared the new capital of Pakistan during the era of Ayub Khan.The capital was shifted from Karachi to Islamabad for better administration and a central location.The city was planned and designed by the Greek architect Constantinos Apostolou Doxiadis.Additional information:1961 – Construction of the new capital city started1967 – Government offices gradually shifted to IslamabadLast verified on 16-03-2026', 0, 0, 0, 1790967399534) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ed683031d6d5498c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'In which year, the construction of Mangla Dam was completed?', '{"A":"1967","B":"1977","C":"1987","D":"1997"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mangla Dam was completed on 23 November 1967.Its construction started in 1962.It is built on the Jhelum River in Mirpur District, Azad Kashmir.It is an earth-filled embankment dam.Height – 147 metersLength – 3,140 metersLast verified on 30-04-2026', 0, 0, 0, 1790967399534) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ad1420bcab1cc55b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The lower Indus plain lies between?', '{"A":"Multan and Arabian Sea","B":"Dera Ghazi Khan and Arabian Sea","C":"Mithan Kot and Arabian Sea","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lower Indus Plain is a major agricultural region.It lies between Mithan Kot and the Arabian Sea.It is formed by the Indus River and its tributaries.It includes parts of Sindh and southern Punjab.Indus River length in Pakistan – about 2,900 km (approx.)Additional information:Upper Indus Plain – Northern PunjabMiddle Indus Plain – Central PunjabLast verified on 30-04-2026', 0, 0, 0, 1790967399534) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_87fd937ba8d2b5a5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'In which city of Pakistan Second Islamic Summit Conference was held?', '{"A":"Karachi","B":"Islmabad","C":"Lahore","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan hosted the 2nd Islamic Summit Conference of the OIC from 22–24 February 1974 in Lahore.An Extraordinary OIC Summit was also held later in 1997 in Islamabad on Pakistan’s Golden Jubilee.Additional information:1st Summit: Rabat, Morocco – September 19693rd Summit: Makkah, Saudi Arabia – 25–28 January 1981Last verified on 07-03-2026', 0, 0, 0, 1790967399569) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8e83d44a3a95493e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Indus civilization developed around _____?', '{"A":"2800BC","B":"2900BC","C":"3100 BC","D":"3000 BC"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Indus Valley Civilisation (IVC)Also known as the Indus Civilisation.A Bronze Age civilisation in the northwestern regions of South Asia.Existed from 3300 BCE to 1300 BCE.Reached its mature phase between 2600 BCE and 1900 BCE.Last verified on 30-04-2026', 0, 0, 0, 1790967399569) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_88fb0cef8d246836', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Sukkur Barrage was built in which year?', '{"A":"1932","B":"1910","C":"1930","D":"1928"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Sukkur Barrage, officially named Lloyd Barrage, is located in Sindh Province.It built from 1923 to 1932 during the British Raj.It was rehabilitated in November 2004. The barrage is approximately 2 km (1 mi) long.It is the oldest in Pakistan, with seven canals taking off from it.Last verified on 14-03-2026', 0, 0, 0, 1790967399569) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_fa598c5a91c72347', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Indus River system in Pakistan comprises of?', '{"A":"Three rivers","B":"Five rivers","C":"Six rivers","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Indus River system is mainly known as the Punjab river system.It consists of five major rivers.These rivers are: Indus, Jhelum, Chenab, Ravi, and Sutlej.They are the main source of irrigation in Pakistan.This system supports agriculture and economy.Last verified on 26-04-2026', 0, 0, 0, 1790967399569) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9761050c771e3d10', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', '‘Chotiari Reservoir’ is situated in which province?', '{"A":"Balochistan","B":"Sindh","C":"Punjab","D":"KPK"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Chotiari Dam is an artificial water reservoir.It situated 35 km away from the Sanghar town in the Sanghar District of the Sindh province of Pakistan.Chotiari Dam is another name for Baqar Lake.It is also known as the "Jungle of Lakes".The reservoir is fed by the Nara Canal.Last verified on 25-04-2026', 0, 0, 0, 1790967399569) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ea0ea4b68629caf5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which is the city of Shrines and Tombs?', '{"A":"Lahore","B":"Faisalabad","C":"Karchi","D":"Multan"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Multan is a city in the Punjab provinceKnown as the "City of Saints" and the "City of Shrines and Tombs."Located along the eastern bank of the Chenab RiverIt is the sixth-largest citySettled: 3000 BCGovernment Type: Metropolitan Corporation*****Last updated by NA on 25-April-2026', 0, 0, 0, 1790967399569) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3e1f633280833c3f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which is the former capital of Pakistan?', '{"A":"Lahore","B":"Karachi","C":"Islamabad","D":"Faisalabad"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Karachi was the first capital of Pakistan From 1947 until 1959, for 12 yearsSelected by Muhammad Ali Jinnah.Interim Capital (1959–1967): Rawalpindi.Current Capital ( August 14, 1967–Present): Islamabad. Last updated by NA on 25-April-2026', 0, 0, 0, 1790967399569) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_005e2db141b1383f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'How many countries share border with Pakistan?', '{"A":"4","B":"2","C":"5","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan shares land borders with four neighboring countriesIndia (East): 2,100 km (East)Afghanistan (Northwest): 2,611 km (West/Northwest)Iran (Southwest): 909 km (West)China (Northeast): 599 km (Northeast)Other borders:Arabian Sea coast: 1,058 km (South)Total land border: 6,219 kmLand + Sea border: 7,277 kmLand + Sea + LOC & Working Boundary: 8,340 kmLast updated question by NA 22-April-2026', 0, 0, 0, 1790967399569) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_68d58af81b44f167', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Thar desert is famous for its _____?', '{"A":"Sand","B":"Coal Deposits","C":"Gas fields","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Thar Desert is the largest desert in Pakistan.It is famous for its arid climate, sand dunes, and unique culture.It is the only subtropical desert in Asia.It is the 3rd largest in Asia.It spans an area of 175,000 square kilometers.It covers large areas of Pakistan and India.Pakistan hosts five major deserts which were historic forests:Cholistan (Bahawalpur, Punjab)Thal (Bakhar district of Punjab)Katpana desert (Sakardu)Kharan desert (Balochistan)Thar desert (Sindh)Last updated by NA on 20-April-2026', 0, 0, 0, 1790967399606) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_88470e7fbaf2781b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Famous love story of “Sohni Mahiwal” is associated with which river?', '{"A":"Indus","B":"Chenab","C":"Ravi","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sohni Mahiwal is a famous Punjabi love story.It tells the tale of Sohni, a potter’s daughter, and Mahiwal, a buffalo herder.Written by Fazal Shah Sayyad.Considered one of the four most popular Punjabi romances.Their tomb is 75 km from Hyderabad, Pakistan.Last verified on 03-04-2036', 0, 0, 0, 1790967399606) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7231433c970796d4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which of the following dam is situated at the highest altitude of Pakistan?', '{"A":"Warsak Dam","B":"Tarbela Dam","C":"Kalabahg Dam","D":"Mohmand Dam"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mohmand DamConstruction Start: 2 May 2019Expected Opening: 2026-27Location: Mohmand District, Khyber Pakhtunkhwa, PakistanLast verified on 03-04-2026', 0, 0, 0, 1790967399606) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b9d266811592b8fc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which is the highest mountain pass in the world?', '{"A":"Alpine","B":"Khunjerab Pass","C":"Tochi Pass","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Khunjerab Pass is the highest mountain pass in the world.It is located at an elevation of approximately 4,693 meters (15,397 feet).It is situated on the border between Pakistan and China.It connecting the Gilgit-Baltistan region of Pakistan with China''s Xinjiang region.Last verified on 02-04-2026', 0, 0, 0, 1790967399606) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9390375504524525', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Keenjhar lake is located in which district of _______?', '{"A":"Dadu","B":"Thatta","C":"Jamashro","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Keenjhar Lake, also known as Kalri Lake.It is one of the largest freshwater lakes in Pakistan.It is located in Thatta District, Sindh, about 122 km from Karachi and 18 km from Thatta city.The lake was formed by merging Sonehri Lake and Keenjhar Lake.It was designated as a Ramsar Wetland Site on 23 July 1976.Last verified on 02-04-2026', 0, 0, 0, 1790967399606) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ca932de0c972c127', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The second highest peak K-2 in the world is located in?', '{"A":"Sub-Himalayan Range","B":"Karakoram Range","C":"Hindukush Mountain Range","D":"None of these"}', 'B', NULL, 0, 0, 0, 1790967399606) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7f70dc008098094b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Pakistan purchased Gwadar port from which country?', '{"A":"Oman","B":"Saudi Arabia","C":"Qatar","D":"UAE"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Gwadar Port is situated on the Arabian Sea at Gwadar in the Balochistan, Pakistan.Omani Rule: Gwadar remained under Oman for 174 years (1783–1958).Purchase Date: 8 September 1958 by Pakistan.Official Integration: 8 December 1958.Port Opening: 2002 (development of the modern deep-sea port began).Additional information:Pakistan has three big sea ports:Karachi PortMuhammad Bin Qasim portGwadar portLast verified on 16-03-2026', 0, 0, 0, 1790967399606) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7f500d6fddfa74a8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'What is the longest glacier in the Karakoram and second-longest in the world’s non-polar areas?', '{"A":"Siachen Glacier","B":"Hispar Glacier","C":"Passu Glacier","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Siachen Glacier is the longest glacier in the Karakoram Range.It is the second-longest glacier in the world outside polar regions.It is located in the eastern Karakoram (Himalayan region).Its length is about 76 km.Last verified on 31-03-2026', 0, 0, 0, 1790967399606) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_4ed04f64c5290c3e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Thal desert is located in _____?', '{"A":"Balochistan","B":"Gilgit","C":"Sindh","D":"Punjab"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Thal DesertLocation: East Punjab Between: Indus & Jhelum rivers Length: 190 milesLast verified on 30-03-2026', 0, 0, 0, 1790967399639) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a2db60711fe66c5c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which is the largest district of Balochistan by area?', '{"A":"Quetta","B":"Gwadar","C":"Chagai","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Largest district of Pakistan by area: Chagai (Balochistan)Largest district of Pakistan by population: KarachiSmallest district of Pakistan by area: Tor GharLargest district of Punjab by area: BahawalpurLast verified on 30-03-2026', 0, 0, 0, 1790967399639) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d609270bae7077ce', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which city of Pakistan receives highest annual rainfall?', '{"A":"Quetta","B":"Murree","C":"Sialkot","D":"Multan"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Murree receives the highest rainfall in all of Pakistan with an annual average of more than 1500 mm.The area having the lowest rainfall in Pakistan is Nokhudi (Balochistan)Equatorial regions receive rainfall throughout the year.Last verified on 23-03-2026', 0, 0, 0, 1790967399639) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c26217ae112e32b2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which province is known as the "Land of Five Rivers" (Punjab)?', '{"A":"Sindh","B":"Punjab","C":"Khyber Pakhtunkhwa","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Punjab, Pakistan is called the "Land of Five Rivers".Because five major rivers—Jhelum, Chenab, Ravi, Beas, Sutlej—flow through it.Additional information:There are a total of 24 rivers flowing through Pakistan.8 rivers flow in KPK5 in Punjab4 in Sindh7 in BalochistanLast verified on 15-03-2026', 0, 0, 0, 1790967399639) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e397a678e45dba20', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which is the largest lake in Pakistan?', '{"A":"Karambar Lake","B":"Attabad Lake","C":"Manchar Lake","D":"Rama Lake"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Manchar Lake is the largest natural lake in Pakistan.It is part of the Indus River basin.Covered Area: ~260 km² (100 square miles)Location: Jamshoro District, SindhWater Source: Kirthar Mountains and surrounding streamsLast verified on 14-03-2026', 0, 0, 0, 1790967399639) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_24ee76e4f950602d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The official/old name of Sukkur barrage is?', '{"A":"Kotri Barrage","B":"Ghulam Muhammad Barrage","C":"Lloyd Barrage","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Sukkur Barrage, officially named Lloyd Barrage, is located in Sindh Province.It built from 1923 to 1932 during the British Raj.It was rehabilitated in November 2004. The barrage is approximately 2 km (1 mi) long.It is the oldest in Pakistan, with seven canals taking off from it.Last verified on 14-03-2026', 0, 0, 0, 1790967399639) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a63eb8e2bb519ee0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which river flows in Balochistan? Zhob, Dasht, Gomal, All of these', '{"A":"Zhob","B":"Dasht","C":"Gomal","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation All of these rivers (Zhob, Dasht, and Gomal) flow in or border the province of BalochistanThere are many rivers in BalochistanThe important rivers in Balochistan are:ZhobNariBolanPishinLoraMulaHubPoraliHingol is the largest river in BalochistanRakshanDasht.***while24 rivers are present in Pakistan5 rivers flow in Punjab Province4 rivers flow in Sindh Province7 rivers flow in Balochistan Province8 rivers flow in Khyber Pakhtunkhwa ProvinceLast updated on 09-03-2026', 0, 0, 0, 1790967399639) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_56c39fec8ff9b848', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The largest river of Pakistan is located in?', '{"A":"Punjab","B":"KPK","C":"Sindh","D":"Balochistan"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The National and largest river of Pakistan is the Indus River. Located in SindhAlso known as the Sindhu RiverStarts making a delta near the city of ThattaOriginates from the Mansarovar lakeFlows through India, Pakistan,Finally falls into the Arabian Sea near Karachi.Old name of the Indus River was Sindhu6 Barrages constructedLength: 3,180 km2nd source: Gar TsangpoThe upper Indus plain ends at Mithankot The upper Indus plain starts from KalabaghLast updated on 09-03-2026', 0, 0, 0, 1790967399639) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ebe8d540cc5cde3b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Sukkur Barrage located on which river?', '{"A":"Chanab River","B":"Sutlej River","C":"Jehlum River","D":"Indus River"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Sukkur Barrage is located on the Indus RiverFormerly known as Lloyd Barrage.Built during the British Raj from 1923 to 1932 Located in Sindh ProvinceLatest built in November 2004Completed in 1932Length: Approximately 2 km (1 mi)The oldest barrage in Pakistan.7 canals take off from the Sukkur BarrageLast updated on 09-03-2026', 0, 0, 0, 1790967399674) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_85aa9e72a4b4f53f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which side of the Indus Water gave control in Pakistan as per the Indus Water Treaty of 1960?', '{"A":"Western tributaries","B":"Eastern tributaries","C":"Northern tributaries","D":"Southern tributaries"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Indus Water Treaty (1960) was signed between Pakistan and India to share the Indus River system.Pakistan got control of the western rivers: Indus, Jhelum, and Chenab.India got control of the eastern rivers: Ravi, Beas, and Sutlej.Last verified on 08-03-2026', 0, 0, 0, 1790967399674) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8e8cb2ba54d4bd1c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Worldwide Nanga Parbat is _______ highest mountain.', '{"A":"2","B":"5","C":"9","D":"11"}', 'C', NULL, 0, 0, 0, 1790967399674) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9b01f5afca95d42a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The biggest/largest district of Pakistan by area?', '{"A":"Mastung","B":"Chaghi","C":"Kalat","D":"Noski"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Chaghi District in Balochistan is the largest district of Pakistan by area.It covers over 38,000 km².Additional information:Lahore District in Punjab is the largest district of Pakistan by population.According to the 2017 Census, it had a population of 11,126,285.Last verified on 07-03-2026', 0, 0, 0, 1790967399674) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3974bfc931972426', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Kartarpur Corridor is in the district of _____?', '{"A":"Narowal","B":"Sialkot","C":"Kasur","D":"Lahore"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kartarpur Corridor is a visa-free border corridor between Pakistan and India for Sikh pilgrims.It is located in Narowal District, Punjab, Pakistan.The corridor allows Indian Sikhs to visit Gurdwara Darbar Sahib in Kartarpur.Opened: 9 November 2019Length: 4.7 kmLast verified on 07-03-2026', 0, 0, 0, 1790967399674) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9f3595e9087829be', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'What is the height of Tarbela Dam', '{"A":"143 m","B":"100 m","C":"200 m","D":"300 m"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tarbela Dam is 143 metres (470 ft) high above the riverbed.It is the largest earth-filled dam in the worldMax Elevation: 1,550 feet (472.44 m).Length: 9,000 feet (2743 m).Capacity: 11.6 million acre-feet (MAF)Location: Haripur District, Khyber Pakhtunkhwa,Construction began: 1968Opening date: 1976Last updated on 06-March-2026', 0, 0, 0, 1790967399674) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b88c3e658cc19092', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The Friendship Gate is built on the border between Pakistan and _____?', '{"A":"Iran","B":"Afghanistan","C":"China","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Friendship Gate is built on the border between Pakistan and Afghanistan. Located at the Chaman border in Balochistan,The Spin Boldak District in Kandahar, Afghanistan, This crossing is known as the Afghanistan–Pakistan Friendship Gate. The gate was erected in 2003On 1 December 2003, the gate was openedLast updated on 06-March-2026', 0, 0, 0, 1790967399674) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_911e7a4cd7eb835d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which province of Pakistan has the longest coastline?', '{"A":"Punjab","B":"Balochistan","C":"KPK","D":"Sindh"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Balochistan has the longest coastline in PakistanThe coastline of Pakistan is bifurcated into two parts:Sindh Coast (250 km) Makran Coast (770-800 km).The new length of the coastline of Pakistan is 1058 kmThe old length of the coastline is 1046KMLast updated question 26 feb 2026', 0, 0, 0, 1790967399674) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7523819c31e66a51', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The Red Sindhi and Nili Ravi are breeds of which livestock in Pakistan?', '{"A":"Cattle (Cow and Buffalo)","B":"Poultry","C":"Goats","D":"Sheep"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Red Sindhi: Indigenous cow breed, reddish color, high milk yield, heat tolerantNili Ravi: Famous water buffalo breed, large body, high-fat milk productionMain Purpose: Dairy production for local and commercial useMajor Regions: Punjab, Sindh (Pakistan)Adaptability: Well-suited to tropical and subtropical climatesLast verified on 05-02-2025', 0, 0, 0, 1790967399706) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_afb9276b700361f7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Rakaposhi is located in which mountain range?', '{"A":"Himalayas","B":"Karakoram","C":"Hindu Kush","D":"Andes"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Rakaposhi is located in the Gilgit-Baltistan region of Pakistan.It is the 27th-highest mountain in the world.It is the steepest peak in the world.Rakaposhi rises over the Nagar Valley.It is the part of the Karakoram range.It is the 12th highest mountain in Pakistan.The first successful ascent was in 1958 by Mike Banks and Tom Patey.Rakaposhi is also known as Dumani, meaning "Mother of Mist" or "Mother of Clouds."', 0, 0, 0, 1790967399706) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_cae3a8d403cf319a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Cholistan desert is also called _____?', '{"A":"Fertile Desert","B":"Rohi Desert","C":"Sandy Desert","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cholistan DesertLocal Name: RohiLocation: Southern Punjab, PakistanDistance from Bahawalpur: ~30 kmFamous Event: Cholistan Jeep RallyArea Coverage: Approximately 26,000 km²Last verified on 18-01-2026', 0, 0, 0, 1790967399706) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_47dcde274fbf88a6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Taj Mahal is located on the Bank of the river?', '{"A":"Yamuna","B":"Ganga","C":"Indus","D":"Nerbaba"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Taj Mahal is located in Agra, Uttar Pradesh, IndiaOn the west side of the Yamuna River.ADDITIONAL INFORMATION REALTED TAJ MEHALThe Taj Mahal, "Crown of Palaces", also "the Taj"It is a white marble mausoleum.It is located in Agra, Uttar Pradesh, IndiaConstruction started1632Construction completed1647Built byMughal Emperor Shah JehanBuilt-in the memory ofthe memory of his third wife, Mumtaz Mahal.Height73 MArchitectureUstad Ahmed Lahori', 0, 0, 0, 1790967399706) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_725d54c1fde9e183', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Chenab meets Jhelum at which place?', '{"A":"Panjnand","B":"Trimmu","C":"Attock","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Chenab River meets the Jhelum River at Trimmu (Punjab).Chenab originates from the Chandra and Bhaga rivers in the Himalayas, India.Flows through Jammu region and enters Punjab plains in Pakistan.Total length: 1,200 km (750 mi) approx.Historically called Asikni due to dark-colored waters.Additional information:The area between Jhelum and Chenab is called Chaj Doab.Rachna Doab: Between Ravi and ChenabBari Doab: Between Beas and RaviLast verified on 17-01-2026', 0, 0, 0, 1790967399706) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_cf17dd7e15670e64', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which of the following provinces of Afghanistan share border with Pakistan?', '{"A":"Balkh, Samangan, Kunduz","B":"Bamiyan, Farah, Herat","C":"Ningrahar, Paktia, Ghazni","D":"None of these"}', 'C', NULL, 0, 0, 0, 1790967399706) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7b3cd54371a571d4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Working boundary is the border between Pakistan and _______?', '{"A":"Indian-occupied Kashmir","B":"Iran","C":"Afghanistan","D":"India"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation It is the line between Pakistan along Sialkot and Indian-held Kashmir. It is called a working boundary because: on one side is internationally recognized land (Sialkot)on the other is a disputed territory.', 0, 0, 0, 1790967399706) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_aacac37f7c2a81df', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which is the largest/biggest barrage of Pakistan?', '{"A":"Sukkur","B":"Guddu","C":"Chashma","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Sukkur Barrage is the largest in Pakistan.It Is the pride of Pakistan''s Irrigation system and in the whole world.Additional information:Sukkur Barrage is a barrage on the River Indus The barrage was built during the British Raj Build from 1923 to 1932 Its old name was named Lloyd Barrage.It is located in Sindh Province', 0, 0, 0, 1790967399706) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_0d285880301aeb2f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Deepest port of Pakistan is _______?', '{"A":"Gwadar","B":"Pasni","C":"Horber","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan purchased Gwadar port (Balochistan) from Oman on 8th September 1958.Gwadar officially became part of Pakistan on 8th December 1958.*******', 0, 0, 0, 1790967399736) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b39ed76bd0e6de09', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Ghulam Muhammad Barrage is also called?', '{"A":"Kandyaro Barrage","B":"Indus Barrage","C":"Chashma Barrage","D":"Kotri Barrage"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kotri Barrage, also known as the Ghulam Muhammad Barrage.It is a barrage on the Indus River between Jamshoro and Hyderabad in Sindh, Pakistan.The barrage was completed in 1955Inaugurated by Ghulam Muhammad Khan.Length 1,600 m (5,200 ft)It has a discharge capacity of 24,800 cubic metres per second (875,000 cu ft/s). It is a gate-controlled weir type barrage with a navigation lock.', 0, 0, 0, 1790967399736) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2751e44f61042d32', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Khanki Headwork is located on which river?', '{"A":"Jehlum","B":"Chenab","C":"Indus","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Location: River Chenab, Gujranwala DistrictFirst Built: 1889Old Khanki Barrage: Built from 1892–1898Purpose: Diverts water to the Lower Chenab CanalOne of Pakistan''s oldest headworksNew Khanki Barrage: Completed in 2017Purpose of New Barrage: Flood control and better water managementLast updated 27-07-2026 by NA', 0, 0, 0, 1790967399736) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_4c1114bd1d812f2d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The best Variety of Apples is grown in which province of Pakistan ?', '{"A":"KPK","B":"AJK","C":"Baluchistan","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Baluchistan is the key contributor of Apple production While KPK stands on second number with contributing 25 percent of national Apple growth. Baluchistan is called land of Apples.', 0, 0, 0, 1790967399736) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2231fa0c9535c22a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The Indus Basin irrigation system, one of the largest in the world primarily serves agriculture in which region of Pakistan?', '{"A":"Southern Punjab","B":"Northern Punjab","C":"Eastern Balochistan","D":"KPK"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Indus basin system is composed of more than 63,213 kms of channels The Sukkur Barrage, is the pride of Pakistan''s irrigation systemIt is the largest single irrigation network of its kind in the world.', 0, 0, 0, 1790967399736) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_5e2ef0c3e531bedd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'How many rivers in Punjab?', '{"A":"4","B":"5","C":"2","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There are a total of five Rivers in PunjabPunjab is known as the land of five rivers. Sr#River NameProvinceLength Final1Sutlej RiverPunjab1450 km2Chenab RiverPunjab960 km3Jhelum RiverPunjab725 km4Ravi RiverPunjab720 km5Beas RiverPunjab250 km', 0, 0, 0, 1790967399736) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d45e562f438931d7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which fort of Sindh is also known as “The Great Wall Of Sindh”?', '{"A":"Ghotki Fort","B":"Umarkot Fort","C":"Naukot Fort","D":"Ranikot Fort"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The fort of Sindh, known as the “Great Wall of Sind,h” is Ranikot FortIt is a 19th-century (reconstructed) Talpur-era fort near Sann in Jamshoro District, Sindh, Pakistan. The fort''s ramparts have been compared to the Great Wall of China.The site was nominated in 1993 by the Pakistan National Commission for UNESCO world heritage status. Length: 32 kilometer,19.88 (mi)Location: Jamshoro district, Sindh', 0, 0, 0, 1790967399736) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9d29b63dc291af48', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Doab between Ravi and Chenab rivers is called?', '{"A":"Chaj doab","B":"Bari doab","C":"Rachna doab","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Rachna doab includes all the area between the Chenab and Ravi RiversRachna Doab can be classified as one of the main regions of Punjab, Pakistan.The name was given by the Mughal emperor Akbar***Five Important Doabs of Pakistan Sindh Sagar Doab is b/w: Indus & Jhelum rivers Jech Doab is b/w: Jhelum & Chenab rivers Bari Doab is b/w: Ravi & Sutlej riversRachna Doab is b/w: Ravi & Chenab rivers Bias Doab is b/w: Bias & Sutlej rivers Doab Chaj is b/w: Chenab and Jhelum.', 0, 0, 0, 1790967399736) ON CONFLICT(id) DO NOTHING;
