INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_4ad2fc47a22aed42', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Makli Hill Graveyard is located in which city?', '{"A":"Karachi","B":"Hyderabad","C":"Makli","D":"Thatta"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Makli Necropolis was inscribed as a UNESCO World Heritage Site in 1981.Makli Necropolis, located in Thatta, Pakistan.It is one of the largest funerary sites in the world.It is the final resting place of some 125,000 local rulers, Sufi saints, and other eminent persons from the 14th to the 18th century.', 0, 0, 0, 1790967399795) ON CONFLICT(id) DO NOTHING;
