INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a8cd9e00be55443c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'In which city was the first women''s bank established in 1989?', '{"A":"Multan","B":"Lahore","C":"Islamabad","D":"Karachi"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation First Women Bank Limited commenced its business on 02 December 1989.First Women Bank Limited (FWBL) is a commercial bank located in Karachi. Prime Minister Benazir Bhutto set up the first bank in December 1988. ND8-1-2023', 0, 0, 0, 1790967399830) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_57f9522b13d5dc6d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which of the following merges in the Jhelum River?', '{"A":"Kabul","B":"Ravi","C":"Sutlej","D":"Kunhar"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Kunhar River merges into the Jhelum River. It originates from Lulusar Lake in the Kaghan Valley, joining it near Muzaffarabad.', 0, 0, 0, 1790967399830) ON CONFLICT(id) DO NOTHING;
