INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ad2ecbbbe46f34b0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Astola and Manora islands are located in which sea?', '{"A":"Arabian Sea","B":"South China Sea","C":"Atlantic Ocean","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Astola and Manora are coastal islands of Pakistan, both located in the Arabian Sea.Astola is Pakistan’s largest offshore island, while Manora is near Karachi.', 0, 0, 0, 1790967399859) ON CONFLICT(id) DO NOTHING;
