INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d1ac6523614af29d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'What is the largest artificial lake in Pakistan?', '{"A":"Rawal Lake","B":"Manchar Lake","C":"Keenjhar Lake","D":"Tarbela Lake"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Keenjhar Lake is also known as Kalri Lake.It is the largest artificial lake in Pakistan, located in Thatta District, Sindh.It was formed by building a bund (dam) on the eastern side, uniting two lakes: Sonehri and Keenjhar.', 0, 0, 0, 1790967399931) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_78cbd5ca5d316813', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The most popular breed of buffalo in Sindh is ______?', '{"A":"Kundhi","B":"Cholistani","C":"Phalli","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kundhi buffalo is the most popular and best-known breed in Sindh, Pakistan.It is valued for its high milk yield and adaptability to the Sindh climate.', 0, 0, 0, 1790967399931) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b6fef169da5fb40a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The city of Mangoes is called to which city of sindh?', '{"A":"Larkana","B":"Mirpurkhas","C":"Karachi","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation MirpurKhas is known for its mango cultivation.It is also called the “City of Mangoes”.It has been home to an annual mango festival Pakistan since 1955.', 0, 0, 0, 1790967399931) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c09627fa6de1997f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which city/district of sindh is famous for Date Palms (Khajoor) production?', '{"A":"Khairpur","B":"Ghotki","C":"Sukkur","D":"Naushahro Feroze"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Khairpur is a city and the capital of the Khairpur District.Khairpur is famous for Faiz Mahal and Kot Diji Fort.It is the 46th largest city in Pakistan by population.District: KhairpurDivision: SukkurProvince: SindhThe district is further divided into eight sub-districts: Khairpur Tehsil, Mirwah Tehsil, Kot Diji Tehsil, Kingri Tehsil, Sobho Dero Tehsil, Gambat Tehsil, Faiz Ganj Tehsil and Nara Tehsil', 0, 0, 0, 1790967399931) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a87f496dd05548a7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which one is the capital of Punjab?', '{"A":"Islamabad","B":"Lahore","C":"Multan","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lahore is the second largest city of Pakistan.Lahore is the capital of Punjab province.', 0, 0, 0, 1790967399931) ON CONFLICT(id) DO NOTHING;
