INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_5694399cfa07622d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'In which City (District) Manchhar Lake is situated?', '{"A":"Dadu","B":"Larkana","C":"Jamshoro","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Manchhar Lake is the largest natural freshwater lake in Jamshoro Sindh Pakistan.It collects water from the Kithar mountain range.It is one of South Asia''s largest.Manchhar Lake is the largest natural freshwater lake in Pakistan.Manchhar Lake covers an area of 23.5 km (14.6 mi).It is part of Indus River basin.', 0, 0, 0, 1790967400028) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b27e418c9a20e1e3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Port Qasim is near the which city in Pakistan?', '{"A":"Karachi","B":"Multan","C":"Baluchistan","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Port Qasim is located in Karachi, Sindh, Pakistan.It is one of the busiest ports in Pakistan.It is situated on the coast of the Arabian Sea.It is approximately 35 kilometers east of Karachi''s city center.Opened: September 1980', 0, 0, 0, 1790967400028) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_acb3b169291e28eb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'First school for transgenders in Punjab inaugurated in the city of ______?', '{"A":"Sialkot","B":"Multan","C":"Lahore","D":"Sargodha"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first school for transgender persons in Punjab was inaugurated in Multan.The South Punjab Education Department opened the first school in Multan in July 2021.The initiative aimed to provide educational opportunities to the transgender community.Last verified on 31-08-2026', 0, 0, 0, 1790967400028) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e33450c2160dd34a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Gawadar is a part of which province?', '{"A":"Baluchistan","B":"Sindh","C":"Punjab","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan purchased Gwadar port from Oman on 8th September 1958.Gwadar officially became part of Pakistan on 8th December 1958.Gwadar remained under Omani rule for 174 years from 1783 -1958 Gwadar Port is situated on the Arabian Sea at Gwadar in Balochistan province.Opened: 2002 while Pakistan has three big sea ports It was purchased from Oman in 1958.Karachi Port,Muhammad Bin Qasim portand Gwadar port.', 0, 0, 0, 1790967400057) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_492bfe65935e9159', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Sidhnai Headworks has been constructed on river?', '{"A":"Chenab","B":"Ravi","C":"Jhelum","D":"Sutlej"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sidhnai Headworks has been constructed on the Ravi River.The new Sidhnai Barrage was constructed 31000 ft upstream of old Sidhnai weir with design capacity of 150,000 CsDownstream straight reach was excavated and widened to increase the capacity from 100,000 Cs to 150,000 Cs.It is the last Headworks over Ravi River before its confluence into Chanab River about 15 KM ahead. It is situated about 2 KM from Abdul Hakeem.', 0, 0, 0, 1790967400057) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_5e4fe8f43df20401', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Fort Munro is located in which province?', '{"A":"Punjab","B":"KPK","C":"Sindh","D":"Balochistan"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fort Munro, formerly known as Loilaresir, is a hill station which is located at a height of 6,470 feet.It is located in Sulaiman Range.It is located in Dera Ghazi Khan District, Punjab.', 0, 0, 0, 1790967400057) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_30b9eb2ca858eaad', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The turquoise waters of LOTUS LAKE are a sight to behold, very calm and peaceful and it is located in ______?', '{"A":"Quetta","B":"Islamabad","C":"Kaghan","D":"Karachi"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lotus Lake is located in Islamabad, Pakistan.It is known for its serene environment and blooming lotus flowers during the season.It attracting visitors for its natural beauty.', 0, 0, 0, 1790967400057) ON CONFLICT(id) DO NOTHING;
