INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_23a533aa61afd95c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which city was considered as Pearl of Gandhara Civilization??', '{"A":"Rawalpindi","B":"Taxila","C":"Peshawar","D":"Quetta","E":"Attock"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Gandhara Civilization flourished in Pakistan during the rule of Buddhist Kings.Taxila was considered as Pearl of Gandhara Civilization. language of the Gandhara civilization was: Prakrit***Gandhara''s language was a Prakrit or "Middle Indo-Aryan" dialect, usually called Gāndhārī.Hindko from Peshawar, which was the capital of Gandhara, came from Shuraseni Prakrit a language spoken in Gandhara.', 0, 0, 0, 1790967400590) ON CONFLICT(id) DO NOTHING;
