INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_82c5eb726343971e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'How many districts are there in Gilgit Baltistan (GB)?', '{"A":"12","B":"18","C":"14","D":"9","E":"7"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation All districts of Gilgit Baltistan:1. Astore2. Darel3. Diamer4. Ghanche5. Ghizer 6. Gilgit 7. Gupis–Yasin 8. Hunza 9. Kharmang 10. Nagar11. Roundu 12. Shigar 13. Skardu 14. Tangir**Gilgit Baltistan is located on the North side of PakistanGilgit is a city of: Gilgit-Baltistan PakistanGilgit-Baltistan, formerly known as the Northern Areas, is a region administered by Pakistan as an administrative territory.Gilgit-Baltistan was Established on 1 November 1948Capital of Gilgit-Baltistan is GilgitLargest city of Gilgit-Baltistan is SkarduND-8-08-2023', 0, 0, 0, 1790967400590) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ec4643f94fbf89b2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The largest District of AJK is------?', '{"A":"Neelum Valley","B":"Haveli","C":"Sudhnati","D":"Kotli"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Neelam Valley is the largest district of Azad Kashmir by area.The valley extends for approximately 200 kilometers along the Neelum River. ****there are 10 districts of Azad KashmirKotli is the biggest district of Azad Kashmir by populationSudhnati is the smallest district by areaHaveli is the smallest district in the population of Azad Kashmir.*** ND03-12-2022', 0, 0, 0, 1790967400590) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_45b76487e3ed31c1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Loralai is a district of which province?', '{"A":"Punjab","B":"Sindh","C":"Balochistan","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Loralai District is a district in northeast of Balochistan province of Pakistan. Loralai town is the district headquarters.', 0, 0, 0, 1790967400621) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8c60ec02ace714a6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Sehwan city is famous for its mausoleum of ______________.', '{"A":"Shah Rukan-e-Alam","B":"Sh. Usman Merwandi","C":"Feroz Shah Tughlaq","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hazrat Sayyid Usman Marwandi, popularly known as Lal Shahbaz Qalandar , was a Sufi saint and poet of present-day Pakistan and Afghanistan.Born Usman 1177 MaiwandDied 19 February 1274 Sehwan Religion IslamSehwan is a historic city located in Jamshoro District of Sindh.', 0, 0, 0, 1790967400621) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ac230e9449a96d61', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which is most urbanized division of Punjab ?', '{"A":"Multan","B":"Rawalpindi","C":"Lahore","D":"Sargodha"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The divisions of Punjab are the first-order administrative bodies of the Punjab Province of Pakistan.There are 10 divisions,. Divisions are governed by Commissioners while districts are governed by Deputy Commissioners.', 0, 0, 0, 1790967400621) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7936e936d1275eb9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The Upper Indus Plain consists of areas between Attock to:', '{"A":"Faisalabad","B":"Hyderabad","C":"Sukkur","D":"Multan","E":"Mithankot"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Upper Indus plain height: 180m to 300m. Five rivers of Punjab drain this plain and cover it with alluvial soils.', 0, 0, 0, 1790967400621) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9e3d73f45eeb78ce', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'River Jhelum rises in the Himalayas and meets the River Chenab in southwest of Jhang. Its length is ____ kms.', '{"A":"725","B":"635","C":"625","D":"none"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jhelum River, river of northwestern India and northern and eastern Pakistan. It constitutes the westernmost of the five rivers of the Punjab region that merge with the Indus River in eastern Pakistan.', 0, 0, 0, 1790967400621) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7ca4388fc2ebb254', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'AL Tarbela dam, pressurized water runs through ?', '{"A":"gases pass through narrow opening","B":"gases pass through brought opening","C":"gases pass through opening","D":"None of these option"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The blades spin at high speed and compress or squeeze the air. The compressed air is then sprayed with fuel and an electric spark lights the mixture. The burning gases expand and blast out through the nozzle, at the back of the engine. As the jets of gas shoot backward, the engine and the aircraft are thrust forward', 0, 0, 0, 1790967400621) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f590b2d8cb73ea99', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Paristan Lake is in district?', '{"A":"sakardu","B":"quetta","C":"Karachi","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Paristan Lake was discovered in 2018 by mountaineers exploring near Skardu in Gilgit-Baltistan.At 15,641 feet above sea level. It is the highest lake in Pakistan and also one of the highest lakes in the world. ****ND8-1-2023', 0, 0, 0, 1790967400621) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7ad963ced9584cc8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Where Attabad Lake, a newly born lake in 2010 is situated Pakistan?', '{"A":"Gilgit Baltistan","B":"KPK","C":"Punjab","D":"Sindh"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Attabad Lake is a lake located in the Gojal region of Hunza Valley in Gilgit−Baltistan, PakistanIt was created in January 2010 Length: 20.9 kmMax. depth: 109 m (358 ft)Area: 72,971 km²Founded: July 1, 1970Largest city: Skardu**AGM 09-2-2023Princely state', 0, 0, 0, 1790967400621) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6d21e0ea6ca168ef', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'River Indus started at.............?', '{"A":"Kashmir","B":"Ladakh.","C":"Tibet","D":"Jammu"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Indus River starts in TibetThe river Indus originates from the Mansarovar lakeThe Indus River flows through India, Pakistan,The Indus River finally falls into the Arabian Sea near Karachi.River Indus starts making a delta near the city of ThattaThe old name of the Indus river was: SindhuNational River of Pakistan: Indus River6 Barrages constructed in Indus RiverIndus River Length: 3,180 kmIndus River 2nd source: Gar TsangpoThe upper Indus plain ends at Mithankot The upper Indus plain starts from KalabaghND11-2-2023', 0, 0, 0, 1790967400650) ON CONFLICT(id) DO NOTHING;
