INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9f3088b01c7572d7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', '……dam is being built at river Indus?', '{"A":"Kargil Dam","B":"Tarbela Dam","C":"Dimmer Bahasa Dam","D":"None of These"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan is currently constructing the Diemer Bhasha Dam on the Indus River, which will extend the life of the Tarbela Dam by 35 years. The new dam project is partially funded by the United States', 0, 0, 0, 1790967400650) ON CONFLICT(id) DO NOTHING;
