INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b992c49d6c35a9f2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Rakaposhi is a mountain in the Gilgat Baltistan region of Pakistan .Rakaposhi means ?', '{"A":"Black stone","B":"Golden stone","C":"Snow covered","D":"Green covered","E":"All of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Rakaposhi, is a mountain in the Karakoram mountain range in Pakistan. It is situated in the Nagar Valley approximately 100 km north of the city of Gilgit in the Gilgit District of the Gilgit–Baltistan province of Pakistan. Rakaposhi means "Snow Covered" in the local language', 0, 0, 0, 1790967400680) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_359e5f40ed41d46c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Give The Length Of Karakoram Mountain From Hunza To Shyok:', '{"A":"500 Km","B":"100 km","C":"400 Km","D":"700 Km","E":"600 Km"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hunza: a mountain valley in Hunza district Shyok: A valley located on Shyok River', 0, 0, 0, 1790967400680) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d238ec7793f3acf0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Name of the border between India and Pakistan in Punjab?', '{"A":"Radcliffe Line","B":"Wagah Border","C":"Line of Control (LoC)","D":"The Durand Line"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The name of international borderline between India and Pakistan is called the Radcliffe line,the border line was drawn by a British officer Cyrill Radcliffe in 1947 and the same line became the border after partition in 1947. ***Line of Control (LoC) is the De facto boundary between Indian-administered Kashmir and Pakistani-administered Kashmir. Its current form was demarcated after the 1972 Simla Agreement.', 0, 0, 0, 1790967400680) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_08d643ff5cd3fb00', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which of the following state of India does not have border with Pakistan?', '{"A":"Punjab","B":"Gujarat","C":"Rajasthan","D":"Haryana"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The India-Pakistan border is also known as International Border.The total length of the India-Pakistan border is 2,100 kilometers.Gujarat: 505 KmPunjab: 425 KmRajasthan: 1,170 Km', 0, 0, 0, 1790967400680) ON CONFLICT(id) DO NOTHING;
