INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_0f65bfba606989fc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'If population of Gilgit and Azad Kashmir is also taken in account then by population Pakistan is world''s __________ largest country.', '{"A":"Seventh","B":"Fifth","C":"Eighth","D":"Sixth","E":"Fourth"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan is the world''s fifth-most populous countryThe population density in Pakistan is 287 per Km2 (742 people per mi2).Pakistan world''s second-largest Muslim population.the top 10 most populous countries in the worldChinaIndiathe United StatesIndonesiaPakistanBrazilNigeriaBangladeshRussiaand Mexico', 0, 0, 0, 1790967400709) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b2ceb60e06b11db1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Blind Dolphins are found in the river of:', '{"A":"Ganges River","B":"Nile River","C":"Yellow River","D":"Yangtze River","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Blind Dolphins are found in Indus river in Pakistan and Ganges river in India and Bangladesh.***********The Indus River dolphin, also known as the “bhulan,” is one of the world''s most endangered cetaceans. It is endemic to the Indus River Basin of Pakistan and northwestern India. Blind Dolphins are found in the lower parts of the Indus River in Pakistan and in River Beas, a tributary of the Indus River in Punjab, India.ND20-6-2023', 0, 0, 0, 1790967400709) ON CONFLICT(id) DO NOTHING;
