INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_80290aa97c93a300', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The Arabian Sea lies in the ____ of Pakistan?', '{"A":"North","B":"South","C":"East","D":"West"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Arabian Sea lies in the South of PakistanIt is located south of Pakistan with a coastline of 1,046 kilometers.Indus River Falls into the Arabian Sea near KarachiIndus River flows into the Arabian Sea called the Indus Delta Indus Delta Designated on 5 November 2002', 0, 0, 0, 1790967400770) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_68152b9fe91ddd98', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Former northern areas granted autonomy under the name of ''Gilgit-Baltistan'' on_?', '{"A":"23 August 2009","B":"24 August 2009","C":"27 August 2009","D":"29 August 2009"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Gilgit is a city of: Gilgit-Baltistan PakistanGilgit Baltistan is located on the North side of PakistanGilgit-Baltistan, formerly known as the Northern Areas, is a region administered by Pakistan as an administrative territory.Granted autonomy under the name of ''Gilgit-Baltistan'' on 29 August 2009Gilgit-Baltistan was Established on 1 November 1948Capital of Gilgit-Baltistan is GilgitLargest city of Gilgit-Baltistan is Skardu', 0, 0, 0, 1790967400770) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_85bc13fb2d0873ee', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Sindh Madrasah-tul-Islam of Karachi was founded by?', '{"A":"Sir Agha Khan","B":"Hassan Ali Effandi","C":"Sir Syed Ahmed Khan","D":"Khalifa Hameed ud din","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sindh Madrasah-tul-Islam, Karachi was Founded on 1st of September 1885 by Hassan Ali Effendi.Sindh Madrasah-tul-Islam, Karachi was Granted University Status in 2012.', 0, 0, 0, 1790967400770) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3d5f2401170e5d76', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which political party in Sindh won the maximum seats in elections of 1937?', '{"A":"Sindh independent party","B":"Muslim League","C":"Sindh United Party","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Sindh United Party emerged the leader with 22 seats, and the Congress secured 8 seats. Mohammad Ali Jinnah had tried to set up a League Parliamentary Board in Sindh in 1936, but he failed, though 72% of the population was Muslim.', 0, 0, 0, 1790967400770) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_313c737a19639583', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Kalabagh is located in which province?', '{"A":"Sindh","B":"Punjab","C":"Khyber Pakhtunkhwa","D":"Punjab"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The proposed site for the dam is situated at Kalabagh, in Mianwali district of Punjab. Height: 83 mLocation: Kalabagh, Mianwali DistrictActive capacity: 7.52 km3 Installed capacity: 3,600 MW', 0, 0, 0, 1790967400770) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ba55e23b8e383800', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The border between Afghanistan and Pakistan was demarcated in the year?', '{"A":"1947","B":"1845","C":"1893","D":"1900"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The length of the common border between Pakistan and Afghanistan is 2611 km...The common border between Pakistan and Afghanistan called Durand Line..Durand line is drawn in 1893 between Mortimer Durand and Abdul RahmanDurand line agreement between Mortimer Durand and Abdul Rahman.******** According to the Survey of Pakistan, the border between Pakistan and Afghanistan is 2611 km', 0, 0, 0, 1790967400770) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e2fa9abc1c0dc9d9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Who becomes first Pakistani woman to summit world’s 10th highest mountain', '{"A":"Nadia Kahef","B":"Naila Kiani","C":"Samina Baig","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In April 2023, Pakistan''s Naila Kiani became the first woman from the country to summit 8,091m high Annapurna in Nepal.', 0, 0, 0, 1790967400770) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_480d1de6d7a5f8b3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which city of Pakistan recorded highest record temperature on 28 May 2017?', '{"A":"Jacobabad","B":"Sibi","C":"Sukkur","D":"Turbat","E":"Dera Murad Jamali"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Highest Temperature in PakistanHappened: 28 May 2017Location: Turbat, BalochistanGauge: 53.5°C Note: It equaled the previous record which was set in Mohenjo Daro on May 27, 2010.', 0, 0, 0, 1790967400800) ON CONFLICT(id) DO NOTHING;
