INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_52847e46b5acbd8e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Bilafond Glacier claimed by both India and Pakistan and controlled by which country?', '{"A":"China","B":"India","C":"Iceland","D":"Pakistan"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bilafond Glacier is located in the Siachen region across Karakoram Range in Pakistan. It is the main source of the Saltoro River. It is under Pakistani control. SH2-8-2023', 0, 0, 0, 1790967400800) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_424039fffa5e20f8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The city that has the highest literacy rate in Pakistan is?', '{"A":"Karachi","B":"Quetta","C":"Multan","D":"Sukkur","E":"Islamabad"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The overall literacy rate of Pakistan is 62.3 % which means that around 90 million people in the country cannot read and writeliteracy rate in Pakistan Province-wise data suggests that:Punjab leads with 63%Khyber Pakhtunkhwa with 53 %Balochistan with 44 percent.has the lowest literacy rate in PakistanIslamabad has around 88% literacy rate, which is the highest rate in Pakistan.ND08-3-2023', 0, 0, 0, 1790967400800) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_bdb348e2dd0c700d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Kartarpur Corridor is located in which district of India?', '{"A":"Assam","B":"Gurdaspur","C":"Andhra Pradesh","D":"Bihar","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kartarpur is a town located in the tehsil Shakargarh, Narowal District in Punjab in Pakistan. Kartarpur Corridor is located in Gurdaspur district of India. it is said to have been founded by the first guru of Sikhism, Guru Nanak, who he established the first Sikh commune.Located on the right bank of the Ravi RiverND6-08-2023', 0, 0, 0, 1790967400800) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a4b080044b7b7057', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The main occupation of the people of the Indus valley civilization was:', '{"A":"Tourism","B":"Agriculture","C":"Cattle rearing","D":"Hunting","E":"Trade"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The main occupation of the people of the Indus valley civilization was Agriculture.The Indus valley people knew the use of Gold, Silver, Copper, and Bronze but not ironThe Indus Valley Civilisation, also known as the Indus Civilisation.The Indus Valley Civilisation (IVC) was a Bronze Age civilization Major sites: Harappa, Mohenjo-Daro, Dholavira, and Rakhigarhi****ND8-1-2023', 0, 0, 0, 1790967400800) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e007a6f4398a11b6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Gilgit is a city of:', '{"A":"Punjab","B":"KPK","C":"Balochistan","D":"Gilgit-Baltistan"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Gilgit is a city of: Gilgit-Baltistan PakistanGilgit Baltistan is located on the North side of PakistanGilgit-Baltistan, formerly known as the Northern Areas, is a region administered by Pakistan as an administrative territory.Gilgit-Baltistan was Established on 1 November 1948Capital of Gilgit-Baltistan is GilgitLargest city of Gilgit-Baltistan is SkarduND12_8_2023', 0, 0, 0, 1790967400800) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_960295b984e52790', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Winder Dam located in which province?', '{"A":"Punhjab","B":"Sindh","C":"KPK","D":"Baluchistan"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Winder Dam is an earth core rockfill, hydroelectric power generation dam of 0.3-megawatt generation capacity, located across Winder River. Chief Minister Balochistan Jam Kamal laid the foundation stone of Winder Dam on 10 August 2021.', 0, 0, 0, 1790967400830) ON CONFLICT(id) DO NOTHING;
