INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_89c403be6c43e044', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'GT Road was constructed by _____?', '{"A":"Feroz Tughluk","B":"Tipu Sultan","C":"Sher Shah Suri","D":"Ameer Kror"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation GT Road: Grand Trunk RoadConstructed/Developed by: Sher Shah SuriPurpose: Connected major cities and improved trade and travel.Original Name: Known as Sadak-e-Azam or Badshahi Sarak.Length: 3,655 km (2,271 mi)East end: Teknaf, BangladeshWest end: Kabul, Afghanistan', 0, 0, 0, 1790967400885) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8e062f55e0187b4d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'When was the Indian National Congress (INC) formed?', '{"A":"December 28, 1888","B":"December 28, 1885","C":"December 28, 1886","D":"December 28, 1880"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Indian National Congress (INC) was formed on 28 December 1885 in Bombay (now Mumbai), British India.The first session was held at Gokuldas Tejpal Sanskrit College.Headquarters: New Delhi, IndiaFounder: Allan Octavian Hume (with support from Indian leaders)First President: Womesh Chunder BonnerjeePurpose: To represent Indian political interests and later lead the Indian independence movement.Last verified on 11-07-2026', 0, 0, 0, 1790967400885) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a54fc90ad122b47b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Simla agreement was signed between Indira Gandhi and ________?', '{"A":"Ayoub Khan","B":"Zulfiqar Ali Bhutto","C":"Yahiya Khan","D":"General Zia"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Simla Agreement was signed between Zulfikar Ali Bhutto and Indira Gandhi.It was signed on 2 July 1972.It took place in Shimla, India.It aimed to resolve issues after the 1971 war.Both countries agreed to settle disputes through bilateral talks.Last verified on 29-04-2026', 0, 0, 0, 1790967400885) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6ef8d95c7c194659', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Who Presented Lahore Resolution (Pakistan Resolution) on 23rd March, 1940 at Minto Park?', '{"A":"Allama Iqbal","B":"A.K Fazlul-Haq","C":"Quaid-e-Azam Muhammad Ali Jinnah","D":"Liaquat Ali Khan"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Lahore Resolution was passed on 23 March 1940 at Minto Park, Lahore.Presented by A. K. Fazlul HuqPrepared text by Muhammad Zafarullah KhanIt demanded separate states for Muslims of the subcontinent.It is also called the Pakistan Resolution.Additional information:Key Participants (by region)Punjab → Zafar Ali KhanSindh → Sir Abdullah HaroonBengal → A.K. Fazlul HuqKPK → Sardar Aurangzeb KhanUnited Provinces → Khalid ZamanLast verified 04-05-2026', 0, 0, 0, 1790967400885) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7bc909ae5f97e712', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'The main demand of simla Muslim Deputation accepted in Minto Morley Reforms of 1906 was about?', '{"A":"Separate electorates","B":"Separate muslim state","C":"Separation of Sindh from Bombay","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Main Demand: Separate electorates for MuslimsPlace: Simla (Shimla)Date: 1 October 1906Leader: Sir Aga Khan IIIMet: Lord MintoThe Simla Deputation consisted of 35 members.Last verified on 08-08-2026', 0, 0, 0, 1790967400885) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_025b95ac928d7895', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'When was the Lucknow Pact made between the Muslim League and Congress?', '{"A":"November 1915","B":"December 1917","C":"November 1914","D":"December 1916"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lucknow Pact (December 1916) was an agreement between:Indian National Congress – headed by Bal Gangadhar TilakAll-India Muslim League – led by Muhammad Ali JinnahAdditional information:Congress adopted the pact at Lucknow session on 29 December 1916.Muslim League approved it on 31 December 1916.Last verified on 19-01-2026', 0, 0, 0, 1790967400885) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ac39b4d60a954c49', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'When did the Simla Deputation took place?', '{"A":"1st October 1906","B":"14th August 1905","C":"30th December 1907","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Simla Deputation took place on October 1, 1906Location: Viceregal Lodge, Simla (now Shimla, India)Leader: Sir Aga Khan IIIParticipants: 35 prominent Muslim leadersMet With: Lord Minto, the Viceroy of India.Main Demand: Separate electorates for MuslimsAdditional informationThe Simla Agreement was signed on July 2, 1972.Last updated by NS on 5-09-2026', 0, 0, 0, 1790967400885) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ae8925c0408dfc69', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'What was the reaction of Congress in response to the failure of Cripps Plan?', '{"A":"Passed a resolution for freedom","B":"Quit India resolution","C":"Agitation","D":"Accepted Crips Plans"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation After the failure of the Cripps Mission, Congress reacted strongly.It launched the Quit India Movement in 1942.This was led by Mahatma Gandhi.The demand was for immediate British withdrawal from India.It became a major mass movement against British rule.Last verified on 29-04-2026', 0, 0, 0, 1790967400885) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9fb89c57bbe2ccdb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'When was All India Muslim League founded?', '{"A":"30 December 1906","B":"30 November 1906","C":"30 August 1947","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The All India Muslim League was founded on 30 December 1906.Location: Dhaka (Dacca), BangladeshFounder: Nawab Khwaja SalimullahFirst President: Sir Agha KhanHeadquarters: LucknowThe party was dissolved on 14 August 1947.When the Muslim League ended in 1947, it split into three parties:Muslim League in PakistanAwami League in BangladeshIndian Union Muslim League in IndiaLast verified on 10-07-2026', 0, 0, 0, 1790967400918) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_588beddb14b94d56', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'When was the Lahore Resolution (Pakistan Resolution) passed?', '{"A":"14 March 1945","B":"23 March 1940","C":"12 March 1948","D":"28 March 1947"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Lahore Resolution was passed on 23 March 1940 at Minto Park, Lahore.It demanded separate states for Muslims of the subcontinent.It is also called the Pakistan Resolution.Additional information:Presented by A. K. Fazlul HuqPrepared text by Muhammad Zafarullah KhanKey Participants (by region)Punjab → Zafar Ali KhanSindh → Sir Abdullah HaroonBengal → A.K. Fazlul HuqKPK → Sardar Aurangzeb KhanUnited Provinces → Khalid ZamanLast verified on 04-05-2026', 0, 0, 0, 1790967400918) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b4b6a648eca778eb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Lahore Resolution was passed in the ________ annual session of All India Muslim League.', '{"A":"27th","B":"21th","C":"37th","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lahore Resolution was passed in the 27th annual session of the All India Muslim League.It was presented by A. K. Fazlul Huq.Adopted by the All-India Muslim League on the occasion of its three-day general session in Lahore on 22–24 March 1940.The session was held at Minto Park, Lahore.Muhammad Ali Jinnah presided over the historic session.Last verified on 01-09-2026', 0, 0, 0, 1790967400918) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ce390b8f05cdb657', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'The period of 1947 to 1953 of Pakistan is known as era of _______?', '{"A":"Neutrality","B":"Alliances","C":"Bilateralism","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 1947–1953: NeutralityAdditional information:1954–1962: Alliances1963–1978: Bilateralism1979–1989: Alliances1990–present: Post-Cold WarLast verified on 01-09-2026', 0, 0, 0, 1790967400918) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c5e5230f0948bd1f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'The first war fought between India and Pakistan after Partition (1947–48) was fought over which issue?', '{"A":"Kashmir","B":"Ladakh","C":"Sir Creek","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first war fought between India and Pakistan after Partition (1947–48) was fought over the Kashmir issue.The First Indo-Pakistani War began in 1947 and continued until 1948.The main dispute was over the princely state of Jammu and Kashmir.The conflict ended with a UN-mediated ceasefire that took effect on 1 January 1949.Last verified on 10-08-2026', 0, 0, 0, 1790967400919) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d3b466395761b171', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'What was the number of Sugar mills in Pakistan in 1947?', '{"A":"2","B":"6","C":"9","D":"15"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sugar Mills in 1947: 2Current Sugar Mills (Approx.): About 88 according to Pakistan Sugar Mills Association (PSMA)Punjab: About 45 millsSindh: About 38 millsBalochistan: About 5 millsMain Raw Material: SugarcaneLast verified on 26-07-2026', 0, 0, 0, 1790967400919) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_cb774f1317c4e8ee', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Quaid''s daughter Dina Wadia died in which city?', '{"A":"Karachi","B":"Lahore","C":"New York City","D":"London"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dina Wadia, the daughter of Quaid-e-Azam Muhammad Ali Jinnah,Date of Death: November 2, 2017, from pneumonia Location: New York City, USAAge: 98 years oldBorn: 15 August 1919, London, EnglandParents Muhammad Ali Jinnah (father)Rattanbai Petit Jinnah (mother)****Last updated by NS on 01 MAY 2026', 0, 0, 0, 1790967400919) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8a76094408ab9bb1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'When Quaid-e-Azam presented his historical fourteen (14) points?', '{"A":"September 1921","B":"March 1927","C":"September 1928","D":"March 1929"}', 'D', NULL, 0, 0, 0, 1790967400919) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ee77ec65cfe908a4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'After the defeat in the War of Independence (1857), Bahadur Shah Zafar was exiled to ______, where he died.', '{"A":"Delhi, India","B":"Rangoon, Burma","C":"Agra, India","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bahadur Shah Zafar was exiled to Rangoon, Burma, after his defeat, where he died.Full name: Abu Zafar Siraj-ud-din Muhammad Bahadur Shah Zafar.Reign: 1837–1857.Exile: Sent to Rangoon, Burma, in 1858.Death: 7 November 1862, in Rangoon.He was also a renowned poet, musician, and calligrapher.Last verified on 11-08-2026', 0, 0, 0, 1790967400947) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3b909edc43bf1fcd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'When did Lord Mountbatten announced the partition plan?', '{"A":"3 June 1944","B":"3 June 1949","C":"3 June 1947","D":"3 June 1948"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Date: 3 June 1947Announced by: Lord Louis MountbattenPosition: Last Viceroy of British IndiaPurpose: Partition of British IndiaOutcome: Creation of India and PakistanLast verified on 16-05-2026', 0, 0, 0, 1790967400947) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_656221d95c7e3f2f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'The title “Quaid-e-Millat” refers to which Pakistani politician?', '{"A":"Liaquat Ali Khan","B":"Muhammad Ali Jinnah","C":"Zulfikar Ali Bhutto","D":"Allama Iqbal"}', 'A', NULL, 0, 0, 0, 1790967400947) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9424c9c53a06d7fd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'The Khilafat movement was started/founded by _____?', '{"A":"Muhammad Ali Jinnah","B":"Dr. Zakir Hussain","C":"Fakruddin Ali Ahmed","D":"Ali Brothers"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Khilafat Movement was mainly led by the Ali Brothers (Maulana Muhammad Ali Jauhar and Shaukat Ali)It was started in 1919 AD in the Indian Subcontinent.It aimed to protect the Ottoman Caliphate after World War I.The movement lasted from 1919 to 1924 AD and ended after the abolition of the Caliphate.Last verified on 21-04-2026', 0, 0, 0, 1790967400947) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_11b121c35215556b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Which Congress leader was called “Show Boy of Congress” by Quaid-e-Azam?', '{"A":"Mahatma Gandhi","B":"Abul Kalam Azad","C":"Raja Gopal Acharya","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Quaid-e-Azam Muhammad Ali Jinnah referred to Maulana Abul Kalam Azad as the "Congress Showboy."Jinnah used this term during the political disagreements between the All-India Muslim League and the Indian National Congress.Additional information:Jinnah also referred to Abul Kalam Azad as "Muslim Lord Haw-Haw" in political criticism.Maulana Abul Kalam Azad served as the first Education Minister of independent India (1947–1958).Last verified on 27-07-2026', 0, 0, 0, 1790967400947) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_14ed039426428635', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'In which of the following cities All India Muslim League was found?', '{"A":"Delhi","B":"Lahore","C":"Dhaka","D":"Allahabad"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Place: Dhaka (then Bengal, British India)Founded on: 30 December 1906Founders: Nawab Salimullah, Agha Khan III, etc.Objective: Protection of Muslim political rightsRole: Key political force behind Pakistan MovementLast verified on 21-04-2026', 0, 0, 0, 1790967400947) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_84dd1c271bd28b06', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Quaid-e-Azam joined All India Muslim League in _____?', '{"A":"1908","B":"1909","C":"1907","D":"1913"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Quaid-e-Azam Muhammad Ali Jinnah joined the All India Muslim League in 1913. He was about 37 years old when he became a member of the Muslim League.Additional information:Quaid-e-Azam joined the Indian National Congress in 1906 and left it in 1920.Last verified on 21-07-2026', 0, 0, 0, 1790967400947) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7a1c160e5eed5d9a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Who helped the Quaid-e-Azam in preparation of fourteen (14) points?', '{"A":"Maulana Muhammad Ali Johar","B":"Sir Syed Ahmed Khan","C":"Allama Iqbal","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Maulana Muhammad Ali Johar helped Quaid-e-Azam Muhammad Ali Jinnah in the preparation of the Fourteen Points.The Fourteen Points were presented by Quaid-e-Azam in March 1929.They were a response to the Nehru Report (1928).Their main purpose was to safeguard the political and constitutional rights of Muslims.Last verified on 13-07-2026', 0, 0, 0, 1790967400947) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_dbd26a53270a0dbf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'How many Round Table Conferences were held in London to resolve the Hind-Muslim differences?', '{"A":"1","B":"2","C":"3","D":"5"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Three sessions were held in London from 1930 to 1932.Chaired by British PM Ramsay MacDonald. (from: 5 June 1929 – 7 June 1935)Discussed constitutional reforms in India.Led to the Government of India Act, 1935.First Session (1930): Boycotted by the Indian National Congress.Second Session (1931): Mahatma Gandhi attended after the Gandhi-Irwin Pact.Third Session (1932): Poorly attended, boycotted by major parties.Last updated 25-07-2026 by NA', 0, 0, 0, 1790967400977) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_958f5c2b3f6c1785', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'When Muslim League demand for principal of self-rule for India?', '{"A":"1919","B":"1913","C":"1914","D":"1915"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The All-India Muslim League adopted the principle of self-rule for India in 1913.The decision was made during the 1913 session of the All-India Muslim League.It helped bring the Muslim League and the Indian National Congress closer politically.The demand later contributed to the Lucknow Pact (1916).Last verified on 22-07-2026', 0, 0, 0, 1790967400977) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_be157a6f8a9ecb9f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'The first session of constituent Assembly of Pakistan held at ______ on 10th August 1947.', '{"A":"Karachi","B":"Lahore","C":"Islamabad","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Venue: Sindh Assembly Building, KarachiFirst Session: 10 August 1947Pakistan''s Independence: 14 August 1947First Constituent Assembly Period: 10 August 1947 – 24 October 1954First President of the Assembly: Muhammad Ali JinnahAdditional information:On 11 August 1947, Muhammad Ali Jinnah delivered his historic presidential address to the Constituent Assembly.The First Constituent Assembly was dissolved by Governor-General Ghulam Muhammad on 24 October 1954.Last verified on 21-07-2026', 0, 0, 0, 1790967400977) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_117e940ccc88d3fa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Who divided Bengal into East and West Bengal (partitioned) in July 1905?', '{"A":"Lord Canning","B":"Lord Linlithgow","C":"Lord Wavell","D":"Lord Curzon"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Partition of Bengal, implemented in 1905 by Lord Curzon.It was formally annulled in 1911. He divided Bengal into two provinces on 16-10-1905.The province was divided into:West Bengal, which had a majority of Hindus,East Bengal, which had a majority of MuslimsLast verified on 30-03-2026', 0, 0, 0, 1790967400977) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9672241e47ad4d97', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'The partition of Bengal was made in 1905, it was annulled in?', '{"A":"1909","B":"1911","C":"1908","D":"1910"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Partition of Bengal, implemented in 1905 by Lord Curzon.It was formally annulled in 1911. He divided Bengal into two provinces on 16-10-1905.The province was divided into:West Bengal, which had a majority of Hindus,East Bengal, which had a majority of MuslimsLast verified on 30-03-2026', 0, 0, 0, 1790967400977) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_75d9c51673db4488', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'On what date did the All-India Muslim League observe the “Day of Deliverance” after the resignation of Congress ministries?', '{"A":"22 October 1938","B":"22 October 1939","C":"22 December 1939","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation On December 2, 1939, Jinnah appealed to Indian Muslims to celebrate December 22, 1939.The "Day of Deliverance" was declared by Muslim League President Muhammad Ali Jinnah.It marked freedom from Congress during the Indian independence movement.Last verified on 30-04-2026', 0, 0, 0, 1790967400977) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_5e050fcf2cd56207', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'The main objective for the formation of Muslim League?', '{"A":"To degrade Hindus","B":"To degrade Sikhs","C":"To safeguard the interests and rights of the Muslim of India","D":"To represent Muslim"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The objective of All India Muslim League is to safeguard the interests and rights of the Muslim of India.It was founded on 30 December 1906 in Dacca, British India (now Dhaka, Bangladesh).Founder: Nawab Khwaja SalimullahFirst President: Sir Agha KhanHeadquarters: LucknowThe party was dissolved on 14 August 1947.When the Muslim League ended in 1947, it split into three parties:Muslim League in PakistanAwami League in BangladeshIndian Union Muslim League in IndiaVerified & Updated', 0, 0, 0, 1790967400977) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f9cdc86cb8de5f73', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'The 1857 War of Independence started from _____?', '{"A":"Agra","B":"Lucknow","C":"Meerut","D":"Delhi"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The 1857 War of Independence started from Meerut on 10 May 1857.It began as a sepoy (soldier) mutiny against the British East India Company.It is also known as the Indian Rebellion of 1857 or the First War of Independence.Major Centers: Delhi, Kanpur, Lucknow, Jhansi, BareillyEnded: 1858, after the British suppressed the revolt.Last verified on 03-04-2026', 0, 0, 0, 1790967400977) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ad6008a2039c33e6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'What major historical event took place in 1857?', '{"A":"Partition of India","B":"Creation of Pakistan","C":"War of Independence","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Event: War of Independence (Indian Rebellion of 1857)Started: 10 May 1857Place: Meerut, IndiaAgainst: British East India CompanyResult: British Crown assumed direct control of India in 1858Last verified on 10-07-2026', 0, 0, 0, 1790967401006) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9be2bae7446b7849', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Following leaders led the Muslim League''s delegation for Simla Conference?', '{"A":"Jinnah and Nizamuddin","B":"Jinnah and Liaquat","C":"Jinnah, Liaquat and Nizamuddin","D":"Liaquat and Nizamuddin"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Muslim League Leaders: Muhammad Ali Jinnah, Liaquat Ali Khan, Khwaja NazimuddinConference: Simla ConferenceDates: 25 June – 14 July 1945Place: Simla (Shimla), IndiaConvened by: Lord WavellLast verified on 06-07-2026', 0, 0, 0, 1790967401006) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_606d0ca159d095c4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Quaid-e-Azam gave his Fourteen (14) Points in response to ____?', '{"A":"Simon Commission","B":"Nehru report","C":"British people","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Quaid-e-Azam presented his 14 Points in March 1929 in response to the Nehru Report (1928).The 14 Points were aimed at safeguarding the political, religious, and constitutional rights of Muslims in British India.Muhammad Ali Johar assisted Quaid-e-Azam in preparing the Fourteen Points.Last verified on 06-07-2026', 0, 0, 0, 1790967401006) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e9351afb31ae6b28', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Who give the title “Quaid-e-Azam” to Muhammad Ali Jinnah?', '{"A":"Maulana Mazharuddin Shaheed","B":"Moulana Muhammad Ali Johar","C":"Syed Ameer Ali","D":"Allama Iqbal"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Maulana Mazharuddin Shaheed gave the title "Quaid-e-Azam" to Muhammad Ali Jinnah in 1938.The title means "Great Leader."Additional information:Born: 25 December 1876, KarachiDied: 11 September 1948, KarachiLast verified on 06-07-2026', 0, 0, 0, 1790967401006) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_60e06798be4be064', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'When Muhammad Ali jinnah was given the title of Quaid-e-Azam?', '{"A":"1999","B":"1944","C":"1938","D":"1934"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The title “Quaid-e-Azam” was given in 1938The title was given by Maulana Mazharuddin Shaheed Pakistan''s first governor-general until his deathLeader of All-India Muslim League (1913–1947)Founder of Pakistan (14 August 1947)First Governor-General of Pakistan (1947–48)Born: 25 December 1876 (Karachi)Died: 11 September 1948 (Karachi)Spouse: Rattanbai Jinnah, Emibai JinnahDaughter: Dina WadiaSister: Fatima JinnahLast updated by NA on 27 April 2026', 0, 0, 0, 1790967401006) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_5d17114ab71329df', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Syed Ameer Ali established Muslim League in London in ______?', '{"A":"1905","B":"1906","C":"1907","D":"1908"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sayyid Ameer Ali founded the London Muslim Federation in 1908.This organization was an independent organization and was not a branch of the All-India Muslim Federation.In 1909 he became the first Indian to sit as a member of the Privy Council''s judicial committee.He served that role until his death in 1928.Last verified on 04-04-2026', 0, 0, 0, 1790967401006) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_748fdbd785afd04b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'The Shimla (Simla) agreement between India and Pakistan was singed in?', '{"A":"1965","B":"1969","C":"1972","D":"1974"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Simla Agreement was signed on 2 July 1972.It took place in Shimla, India.Signed between Zulfikar Ali Bhutto and Indira Gandhi.It aimed to resolve issues after the 1971 war.Both countries agreed to settle disputes through bilateral talks.Last verified on 29-04-2026', 0, 0, 0, 1790967401006) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d0ef22646972311b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'What was Mother tongue of Quaid-e-Azam?', '{"A":"Baluchi","B":"Sindhi","C":"Gujrati","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Gujarati was the mother tongue of Quaid-e-Azam Muhammad Ali Jinnah.His family belonged to the Kathiawar region of Gujarat and spoke Gujarati at home.Additional information:Born: 25 December 1876Birthplace: Karachi, British IndiaProfession: Lawyer and PoliticianTitle: Quaid-e-Azam (Great Leader)Died: 11 September 1948 (Karachi)Last verified on 30-06-2026', 0, 0, 0, 1790967401006) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_5ac5722ddccac71a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Who was the viceroy of India at the time of architect of partition of Bengal?', '{"A":"Lord Curzon","B":"Lord Minto","C":"Lord Algan","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lord Curzon was the Viceroy of India when the Partition of Bengal was announced in 1905.The decision divided Bengal into Eastern Bengal and Assam and Bengal Province.It faced strong opposition from the Indian National Congress and many Hindu groups.Additional information:Partition announced: 20 July 1905Implemented: 16 October 1905Revoked: December 1911Announced by: King George V at Delhi DurbarLast verified on 24-06-2026', 0, 0, 0, 1790967401035) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a2d3befc88ea0a64', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'East India Company was established in ______?', '{"A":"December 23, 1600","B":"December 31, 1700","C":"December 23, 1600","D":"December 31, 1600"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Established: 31 December 1600It was an English joint-stock company formed for trade with Asia.Additional information:Ceased operations: 1 June 1874; 149 years agoHeadquarters: London, United KingdomFounder figures: Thomas Smythe, John WattsCharter granted by: Queen Elizabeth ILast verified on 24-06-2026', 0, 0, 0, 1790967401035) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_556296ca5b1cb360', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Liaquat Ali Khan was assassinated in Rawalpindi on?', '{"A":"17 November 1951","B":"17 September 1951","C":"16 October 1951","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Liaquat Ali Khan was assassinated on 16 October 1951.Age: 56 yearsHe was Pakistan’s first Prime Minister.Birth: 1 October 1895Place of assassination: Company Bagh (Liaquat Bagh), RawalpindiTitle: Shaheed-e-Millat (Martyr of the Nation)His assassin Syed Akbar was immediately killed on the spot by police.Last verified on 01-05-2026', 0, 0, 0, 1790967401035) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6c85d3e3fb47daf8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', '"Jinnah of Pakistan" written by?', '{"A":"Stanly Wolpert","B":"Hector Bolitho","C":"Philip Hitti","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Jinnah of Pakistan" was written by Stanley Wolpert.It was published in 1984.The book is a famous biography of Muhammad Ali Jinnah, covering his public and private life.It describes Jinnah’s journey from his birth in 1876 to his death in 1948.Stanley Wolpert was an American historian known for his works on South Asian history.Last verified on 20-06-2026', 0, 0, 0, 1790967401035) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_373403e5d9abd8ae', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'What was the name of Quaid-e-Azam Muhammad Ali Jinnah''s mother?', '{"A":"Mithibai Jinnah","B":"Rattanbai Jinnah","C":"Emibai Jinnah","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The mother of Muhammad Ali Jinnah was Mithibai Jinnah.She belonged to a Gujarati Khoja family.Jinnah was born in Karachi in 1876.His father was Jinnahbhai Poonja.He was the eldest of seven children.Additional information:Siblings of Quaid-e-Azam:Fatima Jinnah – Dentist, political leader, Madar-e-MillatAhmad Ali Jinnah – BrotherBunde Ali Jinnah – BrotherRahmat Bai – SisterMaryam Bai – SisterShireen – SisterBachu – Brother – Died early in childhoodLast verified on 14-06-2026', 0, 0, 0, 1790967401035) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8bb3bffbd733be92', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'British Government gave the title of "Sir" to Sir Syed Ahmed Khan in _____?', '{"A":"1888","B":"1886","C":"1887","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Title awarded: Sir (Knighthood)Year: 1888 ADMovement: Aligarh MovementMajor institution: Muhammadan Anglo-Oriental College (1875)Death year: 1898 ADLast verified on 21-04-2026', 0, 0, 0, 1790967401035) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_893ad303a4eee91e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'What was the number of Muslim league Ministers in the interim Government of 1946?', '{"A":"2","B":"3","C":"4","D":"5"}', 'D', NULL, 0, 0, 0, 1790967401035) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6bf16b9fc0126b80', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'The First annual session of Muslim League was held in?', '{"A":"Karachi, 1907","B":"Lahore, 1900","C":"Patna, 1906","D":"Lucknow, 1908"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first annual session of the All India Muslim League was held in Karachi in 1907.Additional information:Formation of Muslim League: 30 December 1906 (Dhaka)First President: Aga Khan III (Sir Sultan Muhammad Shah)Purpose: Protection of Muslim interestsKey leaders: Nawab Salimullah, Muhammad Ali Jinnah (later joined)Last verified on 11-06-2026', 0, 0, 0, 1790967401035) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_510eacd0959181da', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'All India Muslim League observed the “Direct Action Day” on which date?', '{"A":"August 6, 1946","B":"3rd February, 1928","C":"August 16, 1946","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Date: 16 August 1946Location: Calcutta (now Kolkata), Bengal, British IndiaOrganizer: All India Muslim LeagueAnnounced By: Muhammad Ali JinnahOutcome: Large-scale communal riots and violence between Hindus and MuslimsLast verified on 02-02-2026', 0, 0, 0, 1790967401065) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e5e8b36d4c331f17', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'The Pakistan Resolution most logically transformed Muslim politics by proposing that?', '{"A":"Separate electorates should be replaced by joint electorates","B":"A single all-India federation would solve communal issues permanently","C":"Muslim-majority contiguous areas should be reorganized into independent states","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Passed on 23 March 1940 at Minar-e-Pakistan (then Minto Park).Presented by A. K. Fazlul Huq.Presided over by Muhammad Ali Jinnah.Demanded independent states in North-West & East regions.Rejected the idea of a single all-India federation.Last verified on 06-05-2026', 0, 0, 0, 1790967401065) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_81b2c2030bc8b903', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Who is called the "Tiger of Bengal"?', '{"A":"A.K Fazal Ul Haque","B":"Sir Ashutosh Mukherjee","C":"Swami Vivekananda","D":"Both A and B"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Full Name: A.K. Fazlul Huq (Abul Kasem Fazlul Huq)Title: Known as “Sher-e-Bengal” (Tiger of Bengal) for his bold leadershipBorn–Died: 1873 – 1962Position: First elected Prime Minister of Bengal (1937)Famous Role: Presented the Lahore Resolution (1940) in Muslim League sessionLast verified on 09-06-2026', 0, 0, 0, 1790967401065) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_df18a3a1990ce7f4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'When was Lord Macaulay/Bentick Resolution''s report presented on the Sub-Continent during British rule?', '{"A":"1813","B":"1835","C":"1837","D":"1855"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lord Thomas Babington Macaulay was a British historian and politician.He presented his famous “Minute on Indian Education” on 2 February 1835.It was supported during the period of Lord William Bentinck.The aim was to promote English education in India.It sought to create a class of educated Indians to assist British administration.Last verified on 03-06-2026', 0, 0, 0, 1790967401065) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a808d56fd437e500', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'The first movement launched against the British in India was?', '{"A":"Khilafat Movement","B":"Swadeshi Movement","C":"Non-cooperation Movement","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first major organized movement against British rule was the Swadeshi Movement.It started in 1905 after the Partition of Bengal.People boycotted British goods and promoted local products.Additional information:Khilafat Movement – 1919–1924Non-Cooperation Movement – 1920–1922Quit India Movement – 1942Last verified on 01-05-2026', 0, 0, 0, 1790967401065) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2401bc1aea0e978e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'How many seats won by All India Muslim League in 1945 Legislative Elections?', '{"A":"35","B":"32","C":"30","D":"28"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The All India Muslim League won 30 seats in the 1945 Legislative Elections.The Muslim League won all Muslim constituencies, but failed to win any other seats.The Indian National Congress emerged as the largest party, winning 57 of the 102 elected seats.Last verified on 23-05-2026', 0, 0, 0, 1790967401065) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_54b04731c5ffb310', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'According to the division of assets by British Government between India and Pakistan how much came as the share of Pakistan?', '{"A":"60 crore","B":"75 crore","C":"80 crore","D":"11 crore"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Indian government''s cash balance at the time of Partition was just under Rs 400 crore.Pakistan''s share of this balance was fixed at Rs 75 crore.This amount of Rs 75 crore included Rs 20 crore that was made available to Pakistan immediately.Last verified on 17-05-2026', 0, 0, 0, 1790967401065) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a74d1f92cf23a0b8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Who led the Simla Deputation?', '{"A":"Allama Iqbal","B":"Sir Agha Khan","C":"Rehmat Ali","D":"Sir Syed Ahmad"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Simla Deputation met the Viceroy of India on 1 October 1906.It was led by Sir Aga Khan III.The delegation consisted of about 35 members.First, the group met the Principal of Aligarh College (MAO College).The Principal arranged the meeting through Colonel Dunlop (Secretary to Viceroy), and then the delegation met Lord Minto.Since the meeting took place at Simla, it was called the Simla Deputation.Last verified on 02-05-2026', 0, 0, 0, 1790967401065) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f86fbae8a395feb8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'When was the second round table conference held?', '{"A":"1931","B":"1941","C":"1920","D":"1922"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Event: Second Round Table ConferenceStart Date: 7 September 1931End Date: 1 December 1931Location: London, United KingdomPurpose: Constitutional reforms for British IndiaAdditional information:1st Conference: 12 November 1930 – 19 January 19313rd Conference: November – December 1932Last verified on 16-05-2026', 0, 0, 0, 1790967401099) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ff27ccabd187b062', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Allama Iqbal qualifed as PhD scholar from which university?', '{"A":"Cambridge University","B":"Munich University","C":"Oxford University","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In 1907, Allama Iqbal moved to Germany for his doctoral studies.He earned a Doctor of Philosophy (PhD) degree in 1908 from the Ludwig Maximilian University of Munich.Iqbal worked under the guidance of Friedrich Hommel.His doctoral thesis was titled "The Development of Metaphysics in Persia."Last verified on 16-05-2026', 0, 0, 0, 1790967401099) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_10cdedce726f07e0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Who moved the resolution for establishing Muslim League?', '{"A":"Nawab of Dhaka","B":"Nawab of Dehli","C":"Nawab of Chittagong","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Year of establishment: 1906Place: Dhaka (now Bangladesh)Key figure: Nawab Salimullah Khan (Nawab of Dhaka)Event: Simla Deputation background led to political demandPurpose: Protect Muslim political rights in British IndiaLast verified on 16-05-2026', 0, 0, 0, 1790967401099) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d9a8e1cc64b53b64', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Which leader seconded the Lahore Resolution 1940 according to the book?', '{"A":"Nawab Ismail Khan","B":"Molana Zafar Ali Khan","C":"Chaudhry Khaliquzzaman","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lahore Resolution passed on 23 March 1940.Venue: Minto Park, Lahore (now Iqbal Park)Moved by: A.K. Fazlul HuqAmong them, Chaudhry Khaliquzzaman is widely recorded as a seconder.Last verified on 08-05-2026', 0, 0, 0, 1790967401099) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_123300485435c752', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Name of All-India Muslim League coined by?', '{"A":"Nawab Viqar ul Mulk","B":"Nawab Mohsin ul Mulk","C":"Nawab Salim ullah","D":"All of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The All India Muslim League was a political party of Muslims in British India.It was founded on 30 December 1906 at Dhaka to protect Muslim rights.The name was associated with Nawab Khwaja Salimullah’s initiative.Headquarters later shifted to Lucknow and other cities.Last verified on 15-05-2026', 0, 0, 0, 1790967401099) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_5c4f6768d6c1924c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Which of the following country opposed Pakistan’s membership in the United Nations at the time of Independence?', '{"A":"India","B":"Iran","C":"China","D":"Afghanistan"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Afghanistan was the only country that voted against Pakistan admission to the United Nations in 1947.Pakistan officially joined the UN on 30 September 1947, shortly after independence on 14 August 1947.Afghanistan opposed Pakistan mainly because of the Durand Line dispute and the issue of Pashtunistan.Additional information:UN Headquarters: New York CityFounded: 24 October 1945Founder Nations: 51 original member statesOfficial Languages: Arabic, Chinese, English, French, Russian, SpanishLast verified on 14-05-2026', 0, 0, 0, 1790967401099) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_70c88cce3a646678', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'On what date did Gandhi-Jinnah talks begin at the residence of Quaid-e-Azam in Bombay?', '{"A":"24 June 1945","B":"14 August 1944","C":"9 September 1944","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Gandhi-Jinnah Talks began on 9 September 1944 at the residence of Quaid-e-Azam in Bombay.These talks were held between Muhammad Ali Jinnah and Mahatma Gandhi.The main issue was the political future of Muslims and the demand for Pakistan.Gandhi opposed the demand for Pakistan, while Jinnah strongly defended the Two-Nation Theory.Last verified on 13-05-2026', 0, 0, 0, 1790967401099) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_bf9d1880a2bb141f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Which leader not attend first round table conference?', '{"A":"Allama Iqbal","B":"Quaid e Azam","C":"Gandhi","D":"Sir Agha Khan"}', 'C', NULL, 0, 0, 0, 1790967401099) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d26694fdbe9dd136', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Why Quaid-e-Azam said that Kashmir is a life line of Pakistan?', '{"A":"All five major rivers of Pakistan originate from Kashmir.","B":"It is the most beautiful place on earth.","C":"Kashmir contains huge reserve of mineral resources.","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Muhammad Ali Jinnah called Kashmir the “life line of Pakistan” due to its water importance.All major rivers of Pakistan originate from Kashmir region and Himalayas.These rivers are essential for agriculture, drinking water, and electricity (hydropower).Without Kashmir water resources, Pakistan’s economy would be seriously affected.Hence, Kashmir is strategically and economically very important.Last verified on 02-05-2026', 0, 0, 0, 1790967401134) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_65203d2d1636f644', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Separate electorate demand by Muslim League was put forward in ____?', '{"A":"1909","B":"1906","C":"1911","D":"1918"}', 'B', NULL, 0, 0, 0, 1790967401134) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_befe8fcb7dc6473c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Lord Mountbatten replaced ______ as Viceroy of India in 1947.', '{"A":"Lord Chelmsford","B":"Lord Curzon","C":"Lord Wavell","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lord Mountbatten replaced Lord Wavell as Viceroy of India in 1947.He oversaw the partition of India and Pakistan''s independence on August 14-15, 1947.Last verified on 01-05-2026', 0, 0, 0, 1790967401134) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8d1cdcebd7b2a002', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Name the city which was the central point of agitation against the partition of Bengal?', '{"A":"Lahore","B":"Calcutta","C":"Hyderabad","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The agitation against the Partition of Bengal 1905 was centered in Calcutta.Calcutta was the political and intellectual hub of Bengal.The movement included boycotts and protests (Swadeshi Movement).It strongly opposed the decision by Lord Curzon.The agitation led to the reversal of partition in 1911.Last verified on 01-05-2026', 0, 0, 0, 1790967401134) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_1885b12295f64586', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Just after partition, when did India cut off Pakistan''s water supply (stop headworks of Pakistani canals) without notice thus creating drought like conditions?', '{"A":"1st March 1948","B":"1st February 1948","C":"1st April 1948","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation India began halting water supplies to Pakistani canals on April 1, 1948, after a short-term standstill agreement expired.The halt started at the Ferozepur Headworks, affecting the Dipalpur Canal and other Pakistani canals.This event led to water disputes between India and Pakistan, culminating in the Indus Waters Treaty in 1960.Last verified on 01-05-2026', 0, 0, 0, 1790967401134) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_880de9d65749b622', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Name two Indian provinces In which the Muslim League formed government during the war years of 1939-45?', '{"A":"Bengal and Sindh","B":"Bengal and Assam","C":"Sindh and Assam","D":"Sindh and Punjab"}', 'A', NULL, 0, 0, 0, 1790967401134) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ef392549e8fbe9d7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Who started Jihad/stood against the Akbar''s new religion Din-e-Illahi?', '{"A":"Shah Wali Ullah","B":"Mujadad Alif Sani","C":"Maulana Bakhtiar Kaki","D":"Mirza Abdul Qadir"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mujadad Alif Sani initiated the Jihad against Din-e-Illahi.Sheikh Ahmad Sirhindi, also known as Imam Rabbani.It is a religious movement introduced by Emperor Akbar in 1582.Origin: Fatehpur Sikri, Agra, Mughal EmpireMembers: 19Other name Tawhid-i-Ilahi(توحید الهی)Last verified on 30-04-2026', 0, 0, 0, 1790967401134) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6a2a5116e1166787', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Allama Iqbal gave his historical Presidential Address at ____?', '{"A":"Allahabad","B":"Lahore","C":"Delhi","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Allama Iqbal delivered his famous Presidential Address on 29 December 1930.It was held at the Allahabad session of the All-India Muslim League.November 9, 1877 – Born in Sialkot1922 – Actively joined Muslim League politicsApril 21, 1938 – Died in LahoreLast verified on 30-04-2026', 0, 0, 0, 1790967401134) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9983d21bcdb79a34', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'On which occasion Jinnah totally disillusioned Hindus and decided "Parting the ways"?', '{"A":"All Parties Conference December 1928","B":"Nehru Report","C":"Simon Commission","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Muhammad Ali Jinnah became disillusioned during the All Parties Conference (December 1928).The conference discussed the Nehru Report.Jinnah proposed amendments to protect Muslim rights, but they were rejected.This led him to feel that Hindus were not willing to accommodate Muslims.He then decided on “parting of the ways”, marking a turning point in history.Jinnah is called the “Ambassador of Hindu-Muslim Unity” before this event.Last verified on 30-04-2026', 0, 0, 0, 1790967401175) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_1bdcf01c8eb4ce2f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Bengal was divided into two provinces in _____?', '{"A":"1905","B":"1906","C":"1907","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Partition of Bengal was carried out on 16-10-1905 by Lord Curzon.Bengal was divided into East Bengal & Assam and West Bengal.The main purpose was administrative efficiency, but it had political effects.It created strong opposition from Hindus and support from many Muslims.The partition was later reversed in 1911.Last verified on 30-04-2026', 0, 0, 0, 1790967401175) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_68ad15bb2108a31f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'The Viceroy who put forward the proposal of August offer in 1940?', '{"A":"Lord wavell","B":"Lord Curzon","C":"Lord Linlithgow","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The famous August Offer was made by the Viceroy named Lord Linlithgow Victor Alexander John Hope, 2nd Marquess of LinlithgowPurpose: To secure Indian cooperation in World War II.Date: August 8, 1940.Last question by NA on 26 April 2026', 0, 0, 0, 1790967401175) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_1c907015acd3cf8e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Quit India Movement was launched by the Congress after the failure of ____?', '{"A":"Cabinet Mission","B":"Cripps Mission","C":"Rowlatt Act","D":"First Factory Act"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Quit India Movement was launched in August 1942 by the Indian National Congress.It came after the failure of the Cripps Mission.The mission failed to satisfy Indian demands for independence.As a result, a mass movement was started against British rule.Additional information:Leader: Mahatma GandhiSlogan: “Do or Die”Last verified on 23-04-2026', 0, 0, 0, 1790967401175) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ceb90666f9bb6838', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Quaid-e-Azam presented his Delhi proposal in ____?', '{"A":"1916","B":"1926","C":"1927","D":"1928"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Quaid-e-Azam presented the Delhi proposals in 1927The conference was held on March 20, 1927Resulting in proposals between Delhi and Muslims', 0, 0, 0, 1790967401175) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7781e566f17efa5d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Allama Iqbal studied at these universities in Europe?', '{"A":"Cambridge, Heidelberg","B":"London, Hamburg","C":"Edinburgh, Leiden","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Allama Iqbal studied in Europe at:University of Cambridge (England)Heidelberg University (Germany)National poet of Pakistan, pursued higher education in Europe. Last verified on 04-04-2026', 0, 0, 0, 1790967401175) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f59a4499464c2f58', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Where is Quaid-e-Azam solar park located?', '{"A":"Lahore","B":"Karachi","C":"Multan","D":"Bahalwalpur"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Quaid-e-Azam Solar Park is located in Bahawalpur.It is in the desert area of Lal Sohanra, Cholistan.It is the largest solar power plant in Pakistan.The park was built in May 2015.Installed capacity is 400–600 MW, generating clean energy.Total cost of construction was $121 million.Last verified on 02-04-2026', 0, 0, 0, 1790967401175) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_49673aafcfc4d8a5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'When the Partition of Bengal took place?', '{"A":"1905","B":"1906","C":"1907","D":"1908"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Partition of Bengal, implemented in 1905 by Lord Curzon.It was formally annulled in 1911. He divided Bengal into two provinces on 16-10-1905.The province was divided into:West Bengal, which had a majority of Hindus,East Bengal, which had a majority of MuslimsLast verified on 30-03-2026', 0, 0, 0, 1790967401175) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_47e0e2c8ee3d3fc1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'When did Khilafat Movement come to an end?', '{"A":"1923","B":"1921","C":"1924","D":"1922"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Khilafat Movement came to an end in 1924 when Mustafa Kemal Atatürk abolished the Ottoman Caliphate.The movement started in 1919.It was led by Indian Muslim leaders like Maulana Muhammad Ali Jauhar and Maulana Shaukat Ali to protect the Caliphate.Last verified on 02-04-2026', 0, 0, 0, 1790967401206) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3ae530e4f4477701', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Who was appointed by Quaid-e-Azam as a first ambassador of Pakistan to Iran?', '{"A":"Raja Ghazsnfer Ali","B":"Abdur Rab Nishter","C":"Qazi Muhammad Esa","D":"Agha Shahi"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Iran was the first country to recognize Pakistan as a sovereign nation after its independence in August 1947.Quaid-e-Azam appointed Raja Ghazanfar Ali Khan as Pakistan''s first ambassador to Iran.Prime Minister Liaquat Ali Khan made his first state visit to Iran in May 1949.The Shah of Iran became the first foreign head of state to visit Pakistan in March 1950.Last verified on 01-04-2026', 0, 0, 0, 1790967401206) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_eda059dbc6b0afc8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'A woman who fought in 1857 War of Independence?', '{"A":"Razia Sultana","B":"Chand Bibi","C":"Rani of Jhansi","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The woman who fought in the 1857 War of Independence is Rani of Jhansi. Rani Lakshmibai, also known as the Rani of Jhansi, She was a prominent figure in the Indian Rebellion of 1857. She led the resistance against British rule in Jhansi, Uttar Pradesh.Last verified on 01-04-2026', 0, 0, 0, 1790967401206) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e008a2a6fd1128b3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Which country first recognize Pakistan after its independence?', '{"A":"China","B":"Turkey","C":"India","D":"Iran"}', 'D', NULL, 0, 0, 0, 1790967401206) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2a8176db65b89bd4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Babar laid the foundation of Mughal empire in 1526 by defeating _____?', '{"A":"Daulat khan Lodhi","B":"Rana Sanga","C":"Alaudin Khiligi","D":"Ibrahim Lodhi"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation First Battle of Panipat: 21 April 1526Fought Between: Babur Vs LodiWon by: BaburAdditional information:Second Battle of Panipat: November 5, 1556Fought Between: Hemu Vs AkbarWon by: AkbarThird Battle of Panipat: 14 January 1761Fought Between: Abdali Vs MarathasWon by: AbdaliLast verified on 30-03-2026', 0, 0, 0, 1790967401206) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e2b138f4eaec69c0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Humayun was removed from throne by _____?', '{"A":"Sher Shah","B":"Akbar","C":"Jahangir","D":"Alamgir"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Humayun was removed from the throne by Sher Shah Suri, an Afghan leader, in 1540.Sher Shah defeated Humayun at the Battle of Chausa and again at the Battle of Bilgram.This leading to Humayun''s exile in Persia (modern-day Iran) for several years.Last verified on 30-03-2026', 0, 0, 0, 1790967401206) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3afe1d3109432589', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'On which date was the Pakistan resolution passed?', '{"A":"22 March 1940","B":"26 March 1940","C":"23 March 1940","D":"21 March 1940"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Lahore Resolution also called the Pakistan Resolution.It was written and prepared by Muhammad Zafarullah Khan.It was presented by A. K. Fazlul Huq on 23-03-1940.Last verified on 13-03-2026', 0, 0, 0, 1790967401206) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_081538b797101482', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Who was the chairman of boundary commission during the partition of Subcontinent in 1947?', '{"A":"Abbot Radcliff","B":"Cyril Radcliff","C":"Norman Redcliff","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sir Cyril Radcliffe chaired the Boundary Commission and drew the borders between India and Pakistan.The border he established on 17 August 1947 is famously known as the Radcliffe Line.The announcement of the partition and borders was made by Lord Mountbatten in 1947.Last verified on 11-03-2026', 0, 0, 0, 1790967401206) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_87726b4409a28204', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'From where did Allama Iqbal obtained his Degree in PHD?', '{"A":"England","B":"Germany","C":"USA","D":"Australia"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Allama Iqbal was a renowned poet, philosopher, and politician.He obtained his PhD in Philosophy from Germany.His thesis was titled “The Development of Metaphysics in Persia.”He is famously known as the “Poet of the East”.Additional information:Born: 9 November 1877, SialkotFather: Sheikh Noor MuhammadMother: Imam BibiDied: 21 April 1938, buried at Badshahi MosqueLast verified on 10-03-2026', 0, 0, 0, 1790967401235) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_de4b5a5f3392c7dc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Who presided over the session of All India Muslim League at Allahabad in 1930?', '{"A":"Sir Agha Khan","B":"Quad e Azam","C":"Allama Iqbal","D":"Choudry Rehmat Ali"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Allama Iqbal (1877–1938) is the National Poet of Pakistan.Joined Muslim League: 1908 in London, 1922 in Indian subcontinent.Delivered Presidential Address at 25th All-India Muslim League session, Allahabad, 29 Dec 1930.Additional information:Born: 9 November 1877, SialkotDied: 21 April 1938, LahoreBurial: Tomb of Allama Iqbal, LahoreKnown as “Mufakkir-e-Pakistan” (Thinker of Pakistan) and “Shair-e-Mashriq” (Poet of the East).Last verified 09-03-2026', 0, 0, 0, 1790967401235) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_534d876ae98a4aca', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'The title “Ambassador of Hindu-Muslim-Unity” was given to Mr Jinnah by ____?', '{"A":"Mustafa-Kamal","B":"Allama-Iqbal","C":"Sarojini-Naidu","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Quaid-e-Azam Muhammad Ali Jinnah was given the title “Ambassador of Hindu-Muslim Unity”.This title was conferred by Sarojini Naidu, a prominent Indian political leader and poet.At that time, Jinnah was working for unity between Hindus and Muslims.Last verified on 13-01-2026', 0, 0, 0, 1790967401235) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_607afb8b115bafbf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'The first Round Table Conference was held in which city?', '{"A":"Bengal","B":"London","C":"Delhi","D":"Karachi"}', 'B', NULL, 0, 0, 0, 1790967401235) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_eff424c15c38f5fb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Who wrote Akbar Nama?', '{"A":"Abu al Fazal","B":"Amjadi Bagum","C":"Gulbadan Bagum","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Akbarnama was written by Abul Fazl.It is the official chronicle of Emperor Akbar’s reign (1556–1605).Additional information:Born: 1551, Agra, IndiaDied: 1602, Patna, IndiaPosition: Court historian and vizier of AkbarFamous Work: Akbarnama (Three volumes)Volume 1: Akbar’s ancestry and early lifeVolume 2: Administrative and political historyVolume 3: Fatawa-e-Alamgiri / Akbar’s achievementsLast verified on 18-01-2026', 0, 0, 0, 1790967401235) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_39e85d498edf7cda', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Who was the Last viceroy of India after independence?', '{"A":"Warren Hasting","B":"Lord Canning","C":"Lord Mountbatten","D":"Lord Curzon"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Last Viceroy of India: Lord Mountbatten in 1947Additional information:First Viceroy of India: Lord Canning in 1858First Governor of Bengal: Robert CliveFirst Governor-General of Bengal: Warren Hastings (1772-1785)First Governor-General of India: William Bentinck in 1833Last verified on 16-01-2026', 0, 0, 0, 1790967401235) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_0716493d4e91d720', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', '____ was the first state which joined Pakistan on 1947?', '{"A":"Azad Kashmir","B":"Hyderabad","C":"Bahawalpur","D":"Makran"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation State: BahawalpurFounded: 1748 by Nawab Bahawal Khan IAccession to Pakistan: Signed on 5 October 1947, accepted on 9 OctoberLocation: Punjab, PakistanGeography: Mostly consists of desertsLast verified on 16-01-2026', 0, 0, 0, 1790967401235) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_4ddda668cdf2b896', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'The foundation stone of Quaid-e-Azam Mohammed Ali Jinnah’s Mausoleum was laid by whom?', '{"A":"Zulfiqar Ali Bhutto","B":"Zia ul Haq","C":"Sikandar Ali Mirza","D":"Ayoub Khan"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Leader who laid foundation: Field Marshal Ayub KhanDate: 31 July 1960Location: KarachiPurpose: Tomb of Quaid-e-Azam Muhammad Ali JinnahArchitecture: Modernist style with white marbleLast verified on 16-01-2026', 0, 0, 0, 1790967401235) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_1296c3f51ff41401', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Quaid-e-Azam resigned from Imperial Legislative Council due to _____?', '{"A":"Lucknow pact","B":"Rowlatt Act","C":"Simon commission","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Quaid-e-Azam Muhammad Ali Jinnah resigned from the Imperial Legislative Council in 1919.His resignation was a protest against the Rowlatt Act.He termed the Act as “a black law” because it curtailed civil liberties.Additional information:1919 – Rowlatt Act passed1919 – Jallianwala Bagh incident1916 – Lucknow Pact1928 – Simon Commission reportLast Updated on 13-01-2026', 0, 0, 0, 1790967401266) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2f84e2421ee8bcf2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Which of the following women participated in all three Round table Conferences?', '{"A":"Begum Shaista Ikramullah","B":"Begum Salma Tasaduq Hussain","C":"Begum Jahan Ara Shahnawaz","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Begum Jahan Ara Shahnawaz was the only Muslim woman who participated in all three Round Table Conferences.These conferences were held in London (1930–1932) to discuss constitutional reforms in British India.She was a leader of the All India Muslim League.Last Updated on 13-01-2026', 0, 0, 0, 1790967401266) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6a9eeefca63fda4c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Ahmad Khan Kharal the famous character of War of Independence belongs to _____?', '{"A":"Jhamra","B":"Cheecha Watni","C":"Gogera","D":"Satiana"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ahmad Khan Kharal was a leading freedom fighter of the War of Independence (1857).He led resistance against British rule in Punjab.He belonged to Jhamra.Jhamra is a village of the Faisalabad District in Punjab, Pakistan.Additional Details / FactsHe played a key role in uprisings around Gogera region.Martyred while fighting the British in 1857.', 0, 0, 0, 1790967401266) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_00f2419d89e8260b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Mustafa Kamal abolished Khilafat in _____?', '{"A":"1927","B":"1924","C":"1920","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mustafa Kemal Atatürk abolished the Khilafat (Caliphate) in 1924.This was part of his modernization and secularization reforms in Turkey.The abolition marked the end of the Ottoman Caliphate system.Additional Details / FactsCapital of Turkey moved from Istanbul to Ankara.Introduced Western-style legal and educational systems.Paved the way for the Republic of Turkey.', 0, 0, 0, 1790967401266) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_09ece6d96be9f6db', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Who was the founder of the All-India Muslim League?', '{"A":"A. K. Fazlul Huq","B":"Nawab Khwaja Salimullah","C":"Aga Khan III","D":"Nawab Waqar-ul-Mulk Kamboh"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The All India Muslim League was founded on 30 December 1906 in Dacca, British India (now Dhaka, Bangladesh).It''s founder was Nawab Khwaja Salimullah.It''s first President was Sir Agha Khan.The headquarters of the All India Muslim League was in Lucknow.The party was dissolved on 14 August 1947.When the Muslim League ended in 1947, it split into three parties:Muslim League in PakistanAwami League in BangladeshIndian Union Muslim League in India', 0, 0, 0, 1790967401266) ON CONFLICT(id) DO NOTHING;
