INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_66e030231152de71', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'When was Quaid-e-Azam first appointed as Third Presidency Magistrate in Bombay?', '{"A":"1899","B":"1900","C":"1947","D":"1930"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In 1900, P. H. Dastoor, a Bombay presidency magistrate, left the post temporarily and Jinnah succeeded in getting the interim position.After his six-month appointment period, Jinnah was offered a permanent position on a 1,500 rupee per month salary. But he refuses', 0, 0, 0, 1790967401473) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e1dbbedad5146ed9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'In the absence of Quaid-e-Azam, who led the Muslims delegation in the third round table conference?', '{"A":"Liaqat Ali Khan","B":"Sir Agha Khan","C":"Syed Suliman Nadvi","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In 1932 third round table conference held***Sir Agha Khan led the mulim delegation. First round table conference: 19302nd round table conference: 19313rd round table conference:1932All round table conference held in London***The three Round Table Conferences of 1930–32 were a series of conferences to formulate the future constitution of India in the light of suggestions given by the Indian Leaders***Gandhi a leader does not attend the first round table conference AGM-24-12-2022', 0, 0, 0, 1790967401473) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_434e68505b87ff05', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'The resolution was written in English language. Who translated the Pakistan resolution in Urdu?', '{"A":"Maulvi A.K Fazal Ul Haq","B":"Maulana Zafar Khan","C":"Zafarullah Khan","D":"None of these"}', 'B', NULL, 0, 0, 0, 1790967401512) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6f6e6b37fe6ba7e3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Approximately how many people attended the All India Muslim League session in Lahore in 1940?', '{"A":"Over 1 lakh/More than one lakh","B":"50,000","C":"75,000","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Attendance: Estimated at more than 100,000 (over one lakh) attendees.Dates: March 22 to March 24, 1940.Location: Minto Park (now Iqbal Park), Lahore.Presented by: A. K. Fazlul Hu.', 0, 0, 0, 1790967401512) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_4ac571c91b627de6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Lahore resolution was seconded from Punjab by ______?', '{"A":"Maulana Zafar Ali Khan","B":"Ch. Rehmat Ali","C":"Abdullah Hussain","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Lahore Resolution is commonly known as the Pakistan Resolution.It was moved in the general session by A. K. Fazlul Huq, the Chief Minister of undivided Bengal.It was seconded by:Chaudhry Khaliquzzaman from the United ProvincesZafar Ali Khan from PunjabSardar Aurangzeb Khan from the North-West Frontier ProvinceSir Abdullah Haroon from Sindh', 0, 0, 0, 1790967401512) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_81c3343cd836a717', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Through the ______ of 1946, the Pakistan Resolution was amended.', '{"A":"Delhi resolution","B":"Bombay resolution","C":"Karachi resolution","D":"Lucknow resolution"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The resolution passed on April 19, 1946, at the Delhi convention, clarified doubts about the word ''states'' in the original Lahore ResolutionIt demanded `an unequivocal understanding be given to implementing the establishment of Pakistan without delay’.NA23-7-2023', 0, 0, 0, 1790967401512) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_626f7816cf80ffb4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'The British Crown assumed direct control over India in which year?', '{"A":"1859","B":"1857","C":"1856","D":"1858"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The British Crown assumed direct control over India in 1858, following the Indian Rebellion of 1857.It is also known as the Sepoy Mutiny.This marked the end of the East India Company''s rule and the beginning of the British Raj, which lasted until India gained independence in 1947.The British ruled India directly for 90 years, from 1858 to 1947.', 0, 0, 0, 1790967401512) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_04b57ea9c437b5aa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'In which of the following cities Indian National Congress was found?', '{"A":"Bombay","B":"Delhi","C":"Allahabad","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Indian National Congress was founded at Gokuldas Tejpal Sanskrit College in Bombay On 28 December 1885. Allan Octavian Hume Place assumed office as the General Secretary, Womesh Chunder Bonnerjee of Calcutta was elected first President. Founders: Allan Octavian Hume Place', 0, 0, 0, 1790967401512) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6be35ed02060c6e2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Allama Iqbal Open University was established under which policy?', '{"A":"1970","B":"1972","C":"1974","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Open University (AIOU) was established in May 1974 under the Education Policy of 1972-80 to provide flexible learning opportunities.It was created by an act of Parliament to help those unable to attend full-time studies due to work or other commitments.', 0, 0, 0, 1790967401512) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2f36d43e53314967', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Which is the biggest ship breaking company in Pakistan?', '{"A":"Gadani","B":"Kiamari","C":"Pasni","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Gadani ship-breaking yard is the world''s third largest ship breaking yard located across a 10 km long beachfront at Gadani.Gadani is is located about 40 km northwest of Karachi. ***', 0, 0, 0, 1790967401512) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c999a7106d4fb792', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'After independence, which was the first Organization Pakistan joined?', '{"A":"UNO","B":"FAO","C":"UNESCO","D":"UNHCR"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation British Commonwealth Pakistan emerged as an independent state on 14th August 1947.Pakistan joined FAO on 7 September 1947.Pakistan joined UNESCO on 14 September 1949.Pakistan joined World Bank in 1950.Pakistan joined IMF on 11 July 1950.Pakistan joined SEATO in 1954.', 0, 0, 0, 1790967401546) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d7fb6bd088dc8a08', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Who was the second wife of Quaid-e-Azam?', '{"A":"Emibai","B":"Sakshi bai","C":"Ratan bai","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Emibai Jinnah was the first cousin and wife of Muhammad Ali Jinnah from 1892 until 1893.Rattanbai Jinnah was 2nd the wife of Muhammad Ali Jinnah from 1918 till 1929*******Mohammed Ali Jinnah died on September 11, 1948, in Karachi, Pakistan.He was the founder and first governor-general (1947–48) of PakistanHe Born: December 25, 1876, KarachiQuaid-e-Azam Residency also known as Ziarat Residency.It is located in Ziarat, Balochistan, Pakistan.', 0, 0, 0, 1790967401546) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_0b3e0c2e90c31fd4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'A proposal for the establishment of the All India Muslim League was presented by ______?', '{"A":"Allama Iqbal","B":"Quaid-e-Azam","C":"Sir Saleemullah Khan","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The proposal for the All India Muslim League was presented in 1906.It was during the Dhaka session of the All India Muhammadan Educational Conference.Sir Saleemullah Khan formally proposed it.Supported by:Hakim Ajmal KhanMaulana Muhammad Ali JauharZafar Ali KhanSyed Nabiullah (barrister from Lucknow)Ibraheem FaziliSyed Zahur Ahmad (eminent lawyer)And several others.', 0, 0, 0, 1790967401546) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_987a2e2f26546716', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'After independence the Father of the Nation, Quaid e Azam Muhammad Ali Jinnah, served for ______ and died on 11th September 1948.', '{"A":"One year and 25 days","B":"One year and 8 days","C":"One year and 20 days","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Quaid-e-Azam Muhammad Ali Jinnah was sworn in as the first Governor-General of Pakistan on 14th August 1947.He was served until his death on 11th September 1948—a period of 1 year and 25 days.He was born on 25th December 1876 in Karachi.', 0, 0, 0, 1790967401546) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_1da47e7fd5cbec3e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'When did Fatima Jinnah become the head of the women’s wing of the All India Muslim League?', '{"A":"1940","B":"1938","C":"1935","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fatima Jinnah became the head of the women''s wing of the All India Muslim League in 1938.She played a significant role in mobilizing women for the cause of Pakistan and the political activities of the Muslim League.', 0, 0, 0, 1790967401546) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6c4ea27a82af6b96', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'When did Fatima Jinnah joined All India Muslim league?', '{"A":"1939","B":"1927","C":"1930","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fatima Jinnah: younger sister of Quaid-e-Azam Muhammad Ali JinnahFatima Jinnah born: 30th July 1893Fatima Jinnah is referred as: Madr-e-Millat (Mother of Nation)Fatima Jinnah died: 9 July 1967Fatima Jinnah died at age: 71Fatima Jinnah died: KarachiFatima Jinnah profession: Dental Surgeon', 0, 0, 0, 1790967401546) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e53f6f2b57b7dea7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Who established the Muslim League in Balochistan on the instructions of Quaid-e-Azam in 1939?', '{"A":"Fazal Ahmed Ghazi","B":"Mir Jafar Khan Jamali","C":"Qazi Muhammad Isa","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Qazi Muhammad Isa established the Muslim League in Balochistan in 1939 on the instructions of Quaid-e-Azam Muhammad Ali Jinnah.He served as the President of All-India Muslim League''s Balochistan branch.', 0, 0, 0, 1790967401546) ON CONFLICT(id) DO NOTHING;
