INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_fdef48461d4a04be', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Quaid-e-Azam resigns/left from Indian National Congress in which year?', '{"A":"1925","B":"1922","C":"1920","D":"1913"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In 1920, Mohamed Ali Jinnah resigned from Congress due to a congress campaign of SatyagrahaJinnah joined Indian National Congress in 1906. Mohamed Ali Jinnah became a member of the All India Muslim League on October 10, 1913.***', 0, 0, 0, 1790967401579) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_78d0df20452a104c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'When was Liaquat Nehru Pact between Pakistan and India?', '{"A":"1948","B":"1949","C":"1950","D":"1951"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Liaquat Nehru pact was signed to deal with the issue of Rights of minorities in both countries. The treaty was signed in New Delhi by the Prime Minister of India Jawahar Lal Nehru and the Prime Minister of Pakistan Liaquat Ali Khan. Liaquat Nehru Pact was signed on April 8, 1950.', 0, 0, 0, 1790967401579) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_73a0d33da096492e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'In 1919, the Khilafat Conference held its first meeting in the city ______?', '{"A":"Delhi","B":"Karachi","C":"Dhaka","D":"Amritsar"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Khilafat movement was launched in the subcontinent in 1919 till 1924.The First Khilafat Conference was held in Delhi on 23 November 1919, to protest against the British policy towards the Ottoman Empire and to express support for the Caliphate.', 0, 0, 0, 1790967401579) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_41b72080bb6c1402', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Sher Shah Suri Ruled India for ________ years.', '{"A":"5","B":"9","C":"11","D":"2"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sher Shah Sur''s real name is Farīd Khān.Sher Shah Suri is well-known for his Land Revenue SystemSher Shah Suri Ruled India for 5 years from 1540 to 1545.Born: 1486, Sasaram, IndiaSher Shah Suri died: on 22 May 154Sher Shah Suri introduced: Rupee CurrencySher Shah Suri built: GT RoadSher Shah took control of the Mughal Empire in 1540.Sher Shah Suri buried in Sasaram', 0, 0, 0, 1790967401579) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3d68ba640ccfda14', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Allama Iqbal joined the Muslim League in _____?', '{"A":"1920","B":"1921","C":"1906","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Allama Iqbal joined the All-India Muslim League in 1906Quaid-e-Azam joined the Muslim League in 1913.Fatima Jinnah joined the Muslim League in 1939.', 0, 0, 0, 1790967401579) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_4f02ff33b680c085', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'When Allama Iqbal joined the Punjab legislative council?', '{"A":"1890","B":"1927","C":"1928","D":"1910"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Iqbal was elected to the Punjab Legislative Council in 1927.In his 1930 presidential address at the League''s annual meeting in Allahabad.Died: 21 April 1938 Born: 9 November 1877', 0, 0, 0, 1790967401579) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e5edfaeaae358b8f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Babar ruled India for how many years?', '{"A":"10","B":"2","C":"4","D":"9"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Babar ruled India for 4 years.He established the Mughal Empire in 1526.He reigned until his death in 1530.Babar was the first Mughal king to rule India.', 0, 0, 0, 1790967401579) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ab8573930f1e5951', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Quaid e Azam was elected as a member of Imperial Legislative Council from the Muslim Constituency of Bombay Presidency in ______?', '{"A":"1910","B":"1912","C":"1906","D":"1908"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Quaid-e-Azam was elected as a member of the Imperial Legislative Council from the Muslim Constituency of Bombay Presidency on 2nd December 1910 and resigned on 1st January 1913.', 0, 0, 0, 1790967401579) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_821e7340f39c21eb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'The boundary commission appointed at the time of Independence was headed by?', '{"A":"Lord Wavell","B":"Lord Mountbatten","C":"Lord Radcliffe","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cyril Radcliffe was the chairman of the Border Commission for India and Pakistan, announced by Lord Mountbatten in 1947The Commission consisted of four members from the Indian National Congressand four from the Muslim LeagueOn 17 August 1947, the borderline that separated India from Pakistan, known as the Radcliffe Line was revealed. The Radcliffe line is spread through the Rann of Kutch in Gujarat to the international border in Jammu in Jammu & Kashmir,dividing India and Pakistan into two different countries.ND23-4-2023', 0, 0, 0, 1790967401614) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_574a1240db949f68', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Quaid-e-Azam personal letters are saved in _____?', '{"A":"National Library Islamabad","B":"National Archives Islamabad","C":"National Documentation wing","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Quaid-e-Azam''s personal letters are preserved in the National Archives Islamabad.These archives contain important historical documents related to Pakistan''s founding.Including letters and papers of key figures like Quaid-e-Azam.', 0, 0, 0, 1790967401614) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3a1c1ef2d95da4dd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'The name of daughter of Quaid-e-Azam was _____?', '{"A":"Maryam","B":"Dina","C":"Khadija","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dina Wadia was the daughter of Muhammad Ali JinnahBorn: August 15, 1919, London, United KingdomDied: November 2, 2017, New York, New York, United StatesNationality: American, BritishND26-2-2023', 0, 0, 0, 1790967401614) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_01201e006538fbf5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'When did Lord Mountbatten arrive in Delhi as new Viceroy of India?', '{"A":"Mar 22, 1945","B":"Mar 22, 1948","C":"Mar 22, 1947","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In March 1947, Mountbatten was appointed Viceroy of India and oversaw the Partition of British India into India and Pakistan. The legislature representatives of the Indian National Congress, the Muslim League, and the Sikh community came to an agreement with Lord Mountbatten through "The Indian Independence Act of 1947"This plan is known as the 3 June Plan or Mountbatten Plan.This plan was the last plan for independence.ND17-1-2023', 0, 0, 0, 1790967401614) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_fa63f98d68dee645', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'At the time of partition only ______ industries came under the jurisdiction of Pakistan?', '{"A":"34","B":"44","C":"55","D":"66"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation At the time of partition in 1947, only 34 out of 921 industries came under the jurisdiction of Pakistan. These industries were part of the assets and resources inherited by Pakistan from the British Raj after independence.', 0, 0, 0, 1790967401614) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2d8671188fb8b8ef', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'During the period 1923-1934, Muslim League was divided in ___ factions.', '{"A":"Three","B":"Four","C":"Two","D":"Five"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation During the period 1923-1934, the All India Muslim League was divided into two factions: one led by Nawab Salimullah Khan and the other by Muhammad Ali Jinnah.This division occurred due to internal disagreements and differences regarding the direction of the Muslim League, but it was later unified under Jinnah''s leadership.', 0, 0, 0, 1790967401614) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7069efc40955866b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Lord Curzon divided Bengal into how many provinces?', '{"A":"Three","B":"Two","C":"Four","D":"Six","E":"Nine"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lord Curzon divided Bengal into two provincesYear: October 16, 1905.Division: Eastern Bengal & Assam; BengalViceroy: Lord CurzonKnown as: Partition of Bengal', 0, 0, 0, 1790967401614) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ffea249280351de2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Mughal Empire in India lasted from?', '{"A":"1525-1857","B":"1526-1857","C":"1524-1857","D":"1526-1858"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mughal Empire lasted from 1526 to 1857.Babar invaded the kingdom of the Lodi Afghans in northern India in 1526.There are 17 Mughal families who rule in India.First Mughal Emperor: BabarLast Mughal Emperor: Behadur Shah Zafar.', 0, 0, 0, 1790967401614) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_4ab6ff9fc9c638f2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'What was Akbar''s number in the Mughal dynasty?', '{"A":"3rd","B":"1st","C":"4th","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Akbar was the third Mughal emperor after Babur and Humayun.He reigned from 1556 to 1605 AD.He was famously known as Akbar the Great.He was the son of Nasiruddin Humayun.He succeeded Humayun as emperor at the age of 13.', 0, 0, 0, 1790967401658) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d9162fb2cec99e75', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'The _______ was a gathering of 35 prominent Indian Muslim leaders led by the Aga Khan III at the Viceregal Lodge in Simla in October 1906.', '{"A":"Simla Deputation","B":"Minto conference","C":"Delhi Convention","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In 1906, Sir Aga Khan met with a prominent Congress leader at the Viceregal Lodge in ShimlaThe Simla Deputation was a gathering of 35 prominent Indian Muslim leadersThe Aga Khan III led them at the Viceregal Lodge in Simla in October 1906.The deputation aimed to convince Lord Minto, then Viceroy of India, to grant Muslims greater representation in politics.', 0, 0, 0, 1790967401658) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e970c5880c10ed9e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'The All India Muslim League’s meeting was held in Delhi on 20th March 1927, under the leadership of Quaid-e-Azam. He presented a set of proposals called ______?', '{"A":"Revolution Proposals","B":"Delhi Proposals","C":"Bombay Proposals","D":"Shimla Proposals"}', 'B', NULL, 0, 0, 0, 1790967401658) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_96eead25af86ec5e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'In 1848, British entered Punjab and annexed Punjab into the British control after defeating the ______?', '{"A":"Hindus","B":"Sikhs","C":"Muslims","D":"Portuguese"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation British defeated the Sikh Empire in the Second Anglo-Sikh War (1848–1849).This led to the annexation of Punjab into British India in 1849.', 0, 0, 0, 1790967401658) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2cca34f50d487558', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'The Mughal Empire founded by Babur in 1526, came to an end in ______?', '{"A":"1857","B":"1589","C":"1785","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mughal Empire lasted from 1526 to 1857.Babar invaded the kingdom of the Lodi Afghans in northern India in 1526 There are 17 Mughal families who rule in IndiaFirst Mughal Emperor: BabarLast Mughal Emperor: Behadur Shah Zafar', 0, 0, 0, 1790967401658) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d44dae451228950e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'What was the name given to India''s Partition Plan?', '{"A":"Cabinet Mission Plan","B":"Independence Act","C":"June 3rd Plan","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation On 3 June 1947 Lord Mountbatten announced the partition plan**The 3rd June 1947 Plan was also known as the Mountbatten Plan.The 3rd June Plan announced the partition of British India into 2 states:IndiaPakistanPunjab and Bengal were divided in the 3rd June Plan.The third June Plan was worked out by Lord Mountbatten.****The 3 June 1947 Plan was also known as the Mountbatten Plan.The British government proposed a plan, announced on 3 June 1947, that included these principles:***ND16-1-2023', 0, 0, 0, 1790967401658) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_5fd5711ff813ebc0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'The Simla delegation called on Lord Minto, the Viceroy of India in October 1906. The delegation was led by?', '{"A":"Gandhi","B":"Sir Agha Khan","C":"Allama Iqbal","D":"Saleemullah Khan"}', 'B', NULL, 0, 0, 0, 1790967401658) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_acbf743341fc95a4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'The third Khilafat Conference was held in 1921 in which city?', '{"A":"Dhaka","B":"Karachi","C":"Istanbul","D":"Amritsar","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation First Khilafat Conference: Held in Bombay (now Mumbai) in July 1919.Second Khilafat Conference: Held in Delhi in November 1919.Third Khilafat Conference: Held in Amritsar in December 1919.Fourth Khilafat Conference: Held in Allahabad in July 1920.Fifth Khilafat Conference: Held in Calcutta (now Kolkata) in November 1920.Sixth Khilafat Conference: Held in Nagpur in December 1920.Seventh Khilafat Conference: Held in Karachi in February 1921.Eighth Khilafat Conference: Held in Delhi in November 1921.', 0, 0, 0, 1790967401658) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_752907a77b9a32f5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'The capital of British India was transferred from Calcutta to Delhi in which year?', '{"A":"12th December 1911","B":"12th November 1911","C":"12th October 1911","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The capital of British India was transferred from Calcutta (now Kolkata) to Delhi in the year 1911. The announcement to shift the capital was made during the Delhi Durbar held in December 1911 to commemorate the coronation of King George V.The new capital in Delhi was known as New Delhi and was designed by the architect Edwin Lutyens. It became the center of British colonial administration in India.', 0, 0, 0, 1790967401701) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a6228a90fa4a094b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Which one of the following was the first fort constructed by the British in India?', '{"A":"Fort St.George","B":"Fort St.Angelo","C":"Fort William","D":"Fort St. David"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fort St. George, the first English fortress in India.It was founded in 1639 in Madras (now Chennai).Built by the British East India Company in 1640, it became a citadel by 1644.It houses St. Mary''s Church, a museum with British Rule artifacts, and Wellesley Residence with paintings of the fortress Governor.', 0, 0, 0, 1790967401701) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_da48f62b66c239b3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Professional qualification of Quaid-e-Azam was _____?', '{"A":"MA, LLB","B":"BA, LLB","C":"Bar-at-Law","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Quaid-e-Azam Muhammad Ali Jinnah completed his Bar-at-Law in 1896 from Lincoln''s Inn, London, becoming a qualified lawyer.', 0, 0, 0, 1790967401701) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_4e191c4f7bf9581d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Jinnah the only film on the life of Quaid-e-Azam was produced by?', '{"A":"Akbar S. Ahmed","B":"Jamil Dehlavi","C":"Shabab dhlvl","D":"Pervaiz iqbal cheema","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Film Jinnah Directed by Jamil DehlaviFilm Jinnah Written by Akbar S. Ahmed and Jamil DehlaviFilm Jinnah Filming Locations Karachi, Sindh, PakistanFilm Jinnah Languages English and UrduFilm Jinnah Budget $6 million', 0, 0, 0, 1790967401701) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_70784000aab4e254', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Quaid-e-Azam retained the control of which ministry in his own hands?', '{"A":"Ministry of Refugee and Rehabilitation","B":"Ministry of State and Frontier Regions","C":"Ministry of Law","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Quaid-i-Azam has decided that the new Ministry will be called “The Ministry of States and Frontier Regions”.1st Governor-General of Pakistan Quaid e Azam was born on:25 December 1876 in KarachiDied on: 11 September 1948In-office: 14 August 1947 – 11 September 1948Prime Minister Liaquat Ali KhanSucceeded by Khawaja NazimuddinND29-5-2023', 0, 0, 0, 1790967401701) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_003057f73f2954e2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Mughal Empire Aurangzeb Alamgir ruled the subcontinent from _____?', '{"A":"1754-1759","B":"1658-1707","C":"1525-1530","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Alamgir, sixth emperor of the Mughal Empire.Reign: 1658–1707 (49 years).Birth: November 3, 1618, in Dhod, Malwa.Death: March 3, 1707, in Bhingar, Aurangabad Subah.Third son of Shah Jahan and Mumtaz Mahal.', 0, 0, 0, 1790967401701) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_cb63c8fa156e778d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Which was the favourite game of Quaid-I-Azam Muhammad Ali Jinnah?', '{"A":"Tennis","B":"Billiards","C":"Football","D":"Baseball"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Favourite Sports: Quaid-i-Azam enjoyed billiards and cricket.He was a member of the Orient Club in India, where he also played chess.Famous Image: An iconic picture shows him playing billiards.Favourite Food: His favorite dish was curry and rice.', 0, 0, 0, 1790967401701) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_4d199288957e210c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Liaquat - Nehru pact was announced at Delhi in ______?', '{"A":"April 8, 1950","B":"May 8, 1950","C":"June 8, 1950","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Liaquat-Nehru Pact, also called the Delhi Pact.It was signed on April 8, 1950.It was an agreement between: India and Pakistan to address minority rights.The pact was signed by :PM Jawaharlal Nehru of India PM Liaquat Ali Khan of Pakistan.Last updated by NA on 27 April 2026', 0, 0, 0, 1790967401701) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_764e76412d9079ad', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Sher Shah Suri is well-known for his _______?', '{"A":"Land Revenue System","B":"Military System","C":"Education System","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sher Shah Sur''s real name is Farīd Khān.Sher Shah Suri is well-known for his Land Revenue System.Sher Shah Suri Ruled India for 5 years from 1540 to 1545.Born: 1486, Sasaram, IndiaSher Shah Suri died: on 22 May 154Sher Shah Suri introduced: Rupee CurrencySher Shah Suri built: GT RoadSher Shah took control of the Mughal Empire in 1540.Sher Shah Suri buried in Sasaram.', 0, 0, 0, 1790967401738) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_16151999e60953d1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'In which year British East India Company occupied Punjab?', '{"A":"1847","B":"1846","C":"1850","D":"1849","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation British East India Company Founder John Watts. British East India Company Founded in December 31, 1600 Ceased operations June 1, 1874', 0, 0, 0, 1790967401738) ON CONFLICT(id) DO NOTHING;
