INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_58243f6a1970b810', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'The First Round Table Conference lasted from:', '{"A":"12th Aug 1930 to 19th Jan 1931","B":"12th Sep to 19th Jan 1931","C":"12th Oct 1930 to 19th Jan 1931","D":"12th Nov 1930 to 19th Jan 1931"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first Round Table Conference convened from 12 November 1930 to 19 January 1931The Second Round table conference was held from 7 September 1931 to 1 December 1931 in London. ****The Third Round Table Conference was held in 1932 between November and December. ****', 0, 0, 0, 1790967402013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ee9e1cdfa0fb85bc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Who presided over inaugural meeting of Muslim League in London?', '{"A":"Hassan Bilgrami","B":"Sir Mian Shafi","C":"Maulana M A Johar","D":"Syed Ameer Ali"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ANS= DSyed Ameer Ali organized the branch of Muslim association at London. The inaugural assembly was held on 6th May 1908, at London Caxton Lobby. It was taken part by the Muslim and those British individuals who favored their see point.', 0, 0, 0, 1790967402013) ON CONFLICT(id) DO NOTHING;
