INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a130890661002836', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Akbar wanted to establish friendship with the Rajputs because:', '{"A":"Friendship with the Rajputs was politically immensely fruitful","B":"With the Mughal links with Central Asia having been completely snapped","C":"Akbar had tomake friendly alliances in India","D":"He wanted to make Rajputana a stepping stone for his Gujarat and Deccan conquests","E":"All of the above"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Answer:Akbar''s dream of expanding the kingdom and establishing a large and powerful Mughal Empire would not have been possible without the help of Rajput. This was also the main reason why Akbar made a very wise decision in this direction and made all Rajput his friends.', 0, 0, 0, 1790967402046) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ba1bb7c23395e08c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Accession of Aurangzeb happened and Shah Jahan was imprisoned', '{"A":"1655","B":"1658","C":"1678","D":"1663"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This set off a battle of succession amongst his four sons wherein his third son, Aurangzeb, emerged successful and usurped his father''s throne. Shah Jahan recovered from his infection, but Emperor Aurangzeb positioned his father below house arrest in Agra castle from July 1658 till his loss of life in January 1666.', 0, 0, 0, 1790967402046) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_460b1f962efd705c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'A London Muslim League delegation headed by Syed Ameer Ali met John Morley, the secretary of State for demands including:', '{"A":"Independence","B":"Protection of the rights of Muslims","C":"Separate electorate","D":"Jobs for the Muslims of India"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Separate electorateThe All-India Muslim League (advanced as the Muslim Alliance) was a political party built up in 1906 in British India. Its solid promotion, from 1930 onwards, for the foundation of a isolated Muslim-majority nation-state, Pakistan, effectively driven to the segment of India in 1947 by the British Realm and include separate electorate.', 0, 0, 0, 1790967402046) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f3cb873a85b4d008', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Simla Conference was held between all parties of the Subcontinent at Simla in:', '{"A":"1951","B":"1945","C":"1947","D":"1944"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Simla Conference of 1945 was a meeting between the Viceroy of India Lord Wavell and the major political leaders of British India at the Viceregal Lodge in Simla.', 0, 0, 0, 1790967402046) ON CONFLICT(id) DO NOTHING;
