INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c86effa356e73041', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Allama Iqbal was born on:', '{"A":"9 November 1875","B":"9 November 1876","C":"9 November 1877","D":"9 November 1878","E":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Know about Allama IqbalBorn: November 9, 1877 (Sialkot)Father: Sheikh Noor MuhammadMother: Imam BibiReceived PhD: GermanyTitle: Poet of the EastFamous books: Bang-e-Dara, Zarb-i-Kalim, Armughan-e-HijazFamous Punjabi Books/Poem: Piyaara Jedi, Baba Bakri WalaDied: 21 April 1938Burial: Badshahi Mosque in LahoreAGM 5.2.23 *******VU CBT FIA PAPER 30-12-2021', 0, 0, 0, 1790967402070) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8d0ba6943649a164', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'What was the title of Allama Iqbal’s PHD Thesis?', '{"A":"The Development of Metaphysics in Persia","B":"Reconstruction of Religious Thought in Islam","C":"Concept of Social Justice in Islam","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Allama Iqbal''s PhD thesis, submitted to the University of Munich (Germany) in 1908 and published in the same year.It was titled "The Development of Metaphysics in Persia".Iqbal qualified for a scholarship from Trinity College, University of Cambridge, and obtained a Bachelor of Arts in 1906.', 0, 0, 0, 1790967402070) ON CONFLICT(id) DO NOTHING;
