INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_aba0da90d36b4e54', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Jinnah Barrage has been built on River?', '{"A":"Chenab","B":"Jehlum","C":"Indus","D":"Neelum"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Jinnah Barrage is a barrage on the River Indus near Kalabagh, Pakistan. It is part of the Thal Project which helps irrigate 770,000 ha in the Sindh Sagar Doab east of the IndusJinnah Barrage is in the district Mianwali of Punjab near Kalabagh Jinnah Barrage construction began in 1939 and opened in 1946 Height: 8.5 m', 0, 0, 0, 1790967402084) ON CONFLICT(id) DO NOTHING;
