INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_fed66bddb0351150', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', '. Within two years of his marriage with Amber Princess (1562), the liberal measures taken by Akbar were:', '{"A":"(1562)","B":"Withdrawal of pilgrim taxes throughout the Mughal Empire (1563)","C":"Total withdrawal of Jizyah from the Hindus (1564)","D":"All of the above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Answerd', 0, 0, 0, 1790967402189) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_0609ea91b4d3f987', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'The Jesuit missionary, who held personal discussions with Akbar and has written an interesting account of him was:', '{"A":"Sir Thomas Roe","B":"Antony Monserrate","C":"Rudolf Aquaviva","D":"Francis Henriquez"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Answer:B', 0, 0, 0, 1790967402189) ON CONFLICT(id) DO NOTHING;
