INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_646baa7e75c2d9e0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'The first governor general of Pakistan was:', '{"A":"Sikandar Ali Mirza","B":"Quaid e Azam","C":"Khan Liaquat Ali Khan","D":"Muhammad Ayoub Khan"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation List of Governer General of Pakistan Term Name Birth–Death Took office Left office Political party Remarks 1 Muhammad Ali Jinnah (1876–1948) 15-Aug-47 11-Sep-48 Pakistan Muslim League died in office 2 Sir Khawaja Nazimuddin (1894–1964) 14-Sep-48 17-Oct-51 Pakistan Muslim League became prime minister 3 Sir Ghulam Muhammad (1895–1956) 17-Oct-51 7-Aug-55 Independent dismissed 4 Iskander Mirza (1899–1969) 7-Aug-55 23-Mar-56 Republican Party became president اچھی تیاری کرنا چاہتے تو یہ سوالات ضرور پڑھیں Must read Click here', 0, 0, 0, 1790967402273) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b303d99ef583688a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who was the first President of Pakistan?', '{"A":"Muhammad Ali Jinnah","B":"Malik Ghulam Muhammad","C":"Sir Khawaja Nazimuddin","D":"Iskander Mirza"}', 'D', NULL, 0, 0, 0, 1790967402273) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_cfec4738c28964ca', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'The oath of the Governor General was administered to Quaid-e-Azam by?', '{"A":"Justice Abdur Rasheed","B":"Juctice Patel","C":"Justice Munir","D":"Justice Shah Din"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The oath of the Governor General was administered to Quaid-e-Azam by Justice Mian Sir Abdur Rashid.He was the first Chief Justice of Pakistan (or Chief Justice of the Lahore High Court )He appointed him on 15 August 1947Jinnah served in this position until his death on September 11, 1948.Last updated question 18-02-2026', 0, 0, 0, 1790967402273) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_21dd60febd75a2f1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who was the first Prime Minister of Pakistan?', '{"A":"Quaid-e-Azam Muhammad Ali Jinnah","B":"Liaquat Ali Khan","C":"Ayoub Khan","D":"Yahya Khan"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first Prime Minister of Pakistan was Liaquat Ali KhanTenure: 15-08-1947 to 16-10-1951.Party: Pakistan Muslim League.Secretary of the All-India Muslim League in 19361st Minister of Defence from 15 August 1947 – 16 October 19511st Minister of Foreign Affairs from 15 August 1947 – 27 December 1949Born: 1 October 1895, Karnal, Punjab, IndiaDied: 16 October 1951 (aged 56), RawalpindiManner of death: Assassination**Last updated by NS on 5-09-2026', 0, 0, 0, 1790967402273) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_4472050009cd0a31', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'What was the name of last Mughal emperor/ruler in India?', '{"A":"Shah Alam","B":"Akbar","C":"Bahadur Shah Zafar","D":"Aurangzeb"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bahadur Shah Zafar is the last Mughal emperor of India (reigned 1837–57). He was a poet, musician, and calligrapher, more an aesthete than a political leader.He was born October 24, 1775, in Delhi, India.He died November 7, 1862, in Rangoon [now Yangon], Myanmar.Additional information:The first Mughal emperor was Babur, who founded the empire in 1526.Last verified on 01-06-2026', 0, 0, 0, 1790967402273) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_42e85af1a2ed3f8d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'What is the name of the Prime Minister of India at the time of the 1965 war?', '{"A":"Sanjay Gandhi","B":"Indira Gandhi","C":"Lal Bahadur Shastri","D":"Morarji Desai"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Indian PM (1965 War): Lal Bahadur Shastri Pakistani President (1965 War): Ayub Khan War duration: August – September 1965 Peace agreement: Tashkent Agreement, 10 January 1966Last verified on 17-01-2026', 0, 0, 0, 1790967402273) ON CONFLICT(id) DO NOTHING;
