INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b9df07fe8cec5326', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who became the first female / woman Chief Minister of Punjab and of any province in Pakistan?', '{"A":"Benazir Bhutto","B":"Hina Rabani Khar","C":"Maryam Nawaz","D":"Marriyum Aurangzeb"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Chief Minister: Maryam NawazOath Taken: 26 February 2024Province: PunjabPredecessor: Mohsin NaqviPolitical Party: Pakistan Muslim League (N) – PML-NAdditional information:Benazir Bhutto was Pakistan''s first woman Prime Minister.She was serving from 1988–1990 and 1993–1996.Last verified on 26-07-2026', 0, 0, 0, 1790967402363) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f53025c21231103d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who was the first and only Vice President of Pakistan?', '{"A":"Iskander Ali Mirza","B":"Ghulam Muhammad","C":"Nur-ul-Amin","D":"Lord Mayo"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nurul Amin was the first and only Vice President of Pakistan.He was serving from 20 December 1971 to 14 August 1973.He also served as the 8th Prime Minister of Pakistan, but only for 13 days (7 December 1971 – 20 December 1971).The office of Vice President was abolished after the 1973 Constitution came into force on 14 August 1973.Nurul Amin was a prominent political leader from East Pakistan (now Bangladesh).Last verified on 20-07-2026', 0, 0, 0, 1790967402363) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_178946da026bab81', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who was the President of Pakistan during the Indo­ Pak war 1965?', '{"A":"Yahya Khan","B":"Pervez Musharraf","C":"Ayub Khan","D":"Zulfikar Ali Bhutto"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Field Marshal Muhammad Ayub Khan was the President of Pakistan during the Indo–Pak War of 1965.The Indo–Pak War of 1965 was fought between Pakistan and India from August to September 1965.Ayub Khan served as the 2nd President of Pakistan from 1958 to 1969.The war ended with the UN-sponsored ceasefire on 23 September 1965.It was followed by the Tashkent Agreement on 10 January 1966.Last verified on 23-07-2026', 0, 0, 0, 1790967402363) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_186851a7a2cee206', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who headed the Cabinet Mission in 1946?', '{"A":"A.V.Alexander","B":"Sir Stafford Cripps","C":"Lord Pethick Lawrence","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Cabinet Mission Plan 1946 was headed by Lord Pethick-Lawrence.Its members included Stafford Cripps and A.V. Alexander.It was announced on 16 May 1946 from New Delhi.It arrived in India on 24 March 1946.The mission was sent by the British government to plan transfer of power.Last verified on 01-05-2026', 0, 0, 0, 1790967402363) ON CONFLICT(id) DO NOTHING;
