INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8b9984dc4bb0249f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'The Simla Agreement signed by Prime Minister Indira Gandhi and President Zulfikar Ali Bhutto of Pakistan on _____?', '{"A":"2nd July 1971","B":"2nd July 1972","C":"3rd June 1973","D":"2nd July 1974"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Simla Agreement was signed on July 2, 1972, by Indian Prime Minister Indira Gandhi and Pakistani President Zulfikar Ali Bhutto, following the Bangladesh Liberation War in 1971.The agreement established the Line of Control (LoC) in Kashmir and paved the way for the repatriation of prisoners of war and the return of occupied territories.', 0, 0, 0, 1790967402770) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_79473c05a0599158', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who from the following is the first Muslim female prime minister?', '{"A":"Benazir Bhutto","B":"Mafuja Khatun","C":"Massouda Jalal","D":"Sheikh Hasina"}', 'A', NULL, 0, 0, 0, 1790967402770) ON CONFLICT(id) DO NOTHING;
