INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_05b948c5e2ef113e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who was the first Mughal Emperor to allow Britishers to establish trade links with India?', '{"A":"Jahangir","B":"Akbar","C":"Shah Jahan","D":"Aurangzeb"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jahangir was the first Mughal Emperor to allow Britishers to establish trade links with India.He gave permission for trade to the British East India Company, allowing them to establish a factory at Surat in 1613.This marked the beginning of British trade in India during the Mughal era.', 0, 0, 0, 1790967402770) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_75522caeb161c3a8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'The downfall of Muslim rule in India started with the demise of emperor _____?', '{"A":"Aurangzeb","B":"Akbar","C":"Jahangir","D":"Bahadur Shah Zafar"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Muhi al-Din Muhammad, commonly known as AurangzebAurangzeb was the sixth emperor of the Mughal Empire ruling from July 1658 until his death in 1707Aurangzeb was Born on November 3, 1618, in Dahod, IndiaAurangzeb was Died on: March 3, 1707, Bhingar, Ahmednagar, IndiaAurangzeb, one of the highest debated Mughal emperorsUnlike other rulers, Aurangzeb only had one wife.****nd9-2-2023', 0, 0, 0, 1790967402771) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c45c35585611b0c7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who won the 1965 presidential election in Pakistan?', '{"A":"Ayub Khan","B":"Miss Fatima Jinnah","C":"Mian Mumtaz Daultana","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Date of election: March 21, 1965Winner: Ayub KhanResult: Ayub Khan won 62.43% of the Electoral voteFatima Jinnah''s vote share: 35.86%', 0, 0, 0, 1790967402771) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6ab9b89cf6a1a520', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Shah Jehan was son of King Jehangir. His real name was _____?', '{"A":"Khurram","B":"Muzafar Shah","C":"Zareef-u-Jehan","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Shahab-ud-din Muhammad Khurram was the original name of Shah Jahan.He was the fifth Mughal emperor from 1628 to 1658.He was the son of Emperor Jehangir.He is famous for building the Taj Mahal.', 0, 0, 0, 1790967402771) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2059c3f883cdd504', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who was the first Defense Minister of Pakistan?', '{"A":"Muhammad Ali Jinnah","B":"Liaquat Ali Khan","C":"Sardar Abdur Rab Nishtar","D":"None of these"}', 'B', NULL, 0, 0, 0, 1790967402771) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_510111bd642b6b3d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who was the first federal law minister of Pakistan?', '{"A":"Liaquat Ali Khan","B":"Zafarullah Khan","C":"Ghulam Muhammad","D":"Jogendra Nath Mandal"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jogendra Nath Mandal was the first federal law minister of Pakistan.He was appointed to the position in 1947.He played a significant role in the early governance of the country.', 0, 0, 0, 1790967402800) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_62eebc71b52d7876', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'The reign of which Mughal Emperor is said to be the "Golden Era"?', '{"A":"Babar","B":"Aorangzaib","C":"Shah Jahan","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Shah Jehan became emperor in 1628.The reign of Shah Jahan is considered the "Golden Era" of the Mughal Empire.It was marked by architectural achievements like the Taj Mahal, and the empire reached its cultural and economic peak.', 0, 0, 0, 1790967402800) ON CONFLICT(id) DO NOTHING;
