INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_5d237b82ea889ad7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'To whom Lord Mountbatten succeeded as Governor General of India?', '{"A":"Lord Wavell","B":"Lord Curzon","C":"Lord Cornwallis","D":"Lord Mayo"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lord Mountbatten replaced Lord Wavell as the viceroy of India in 1947.Lord Mountbatten: The last Viceroy of IndiaLord Mountbatten passed away on 27 August 1979In March 1947, Mountbatten was appointed Viceroy of India and oversaw the Partition of British India into India and Pakistan. The legislature representatives of the Indian National Congress, the Muslim League, and the Sikh community came to an agreement with Lord Mountbatten through "The Indian Independence Act of 1947"This plan is known as the 3 June Plan or Mountbatten Plan.ND28-4-2023', 0, 0, 0, 1790967402861) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_dce5d65e97fef6f7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Which of the following leaders took part in Presidential Election?', '{"A":"Mohtarma Fatima Jinnah","B":"Begum Ghazi Esa","C":"Begum Liaqat Ali Khan","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mohtarma Fatima Jinnah contested the 1965 presidential election as the leader of the Combined Opposition Parties (COP).She ran against Ayub Khan, who represented the Pakistan Muslim League.', 0, 0, 0, 1790967402861) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2f51adeee0a8ef47', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Muhammad Khan Junejo, PM of Pakistan, left his office on which date?', '{"A":"20 May 1988","B":"10 June 1988","C":"29 May 1988","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Muhammad Khan Junejo, the tenth Prime Minister of Pakistan, left his office on May 29, 1988.He was dismissed by President Muhammad Zia-ul-Haq due to their conflicting views on governance and military control.He was succeeded by general elections held in 1988.', 0, 0, 0, 1790967402861) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7fb10f0c3ab65e26', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Name the Mughal king died in 1556 after falling from stairs?', '{"A":"Shah Jahan","B":"Humayun","C":"Babar","D":"Akbar"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation On 24th January , 1556, King Humayun was slipped and fell down the stairs and died on January 26, 1556.Reign 26 December 1530 – 17 May 1540Coronation 29 December 1530, AgraPredecessor BaburSuccessor Sher Shah Suri Second time Reign 1555 – 1556', 0, 0, 0, 1790967402861) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_81c20c6e439e42af', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Mughal Emperor Akbar enforced Din-I-Ilahi in ______?', '{"A":"1583","B":"1582","C":"1581","D":"1584","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mughal emperor Akbar enforced Din-i-Ilahi in 1582.****Akbar was born: 1542Akbar died: in 1605Mughal Emperor Akbar was born in:SindhAkbar was the ruler Mughal emperor from 1556 to 1605.Mughal Emperor Akbar is buried: AgraMughal Emperor Akbar was the third Emperor from Mughal Family', 0, 0, 0, 1790967402861) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3d302acd6fab86da', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Name the Prime Minister who presented Objectives Resolution in 1949?', '{"A":"Liaquat Ali Khan","B":"Khawaja Nazimuddin","C":"Muhammad Ali Bogra","D":"Feroz Khan Noon"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Constituent Assembly Pakistan adopted the Objectives Resolution on March 12, 1949.Prime Minister, Liaquat Ali Khan, had presented it in the assembly on March 7, 1949Out of 75 members of the assembly, 21 voted for it.All the amendments proposed by minority members were rejectConsequently, all ten of them voted against it.The resolution, in its entirety, has been made part of the Constitution of Pakistan under Article 2(A).*********', 0, 0, 0, 1790967402891) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_18c99f71b69c86f8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'A person appointed as Chief Election Commissioner of Pakistan shall hold office for a term of ______?', '{"A":"3 Years","B":"5 Years","C":"6 Years","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The President of Pakistan appoint the Chief Election Commissioner and four members of Election Commission of Pakistan. Election commission was established in 1950.', 0, 0, 0, 1790967402891) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_dd713fb6ac2a9ab9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who was the ruler of Kashmir at the time of partition?', '{"A":"Gureet Singh","B":"Gulab Singh","C":"Hari Singh","D":"Ranjeet Singh"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Maharaja Sir Hari Singh was the last ruling Maharaja of the princely state of Jammu and Kashmir. In 1947 Hari Singh, who had ascended the throne of Kashmir in 1925Reign: 23 September 1925 — 17 November 1952Predecessor: Pratap SinghBorn: September 23, 1895, JammuDied: April 26, 1961, Mumbai, India***The first Muslim ruler of Kashmir was Shah Mir', 0, 0, 0, 1790967402891) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_eddcbf93d3ea7f5c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Durand Line Treaty was signed between Sir Mortimer Durand and King ______ of Afghanistan in 1893.', '{"A":"Amir Amanullah","B":"Noor Muhammad","C":"Abdul Rehman","D":"Ahmad Shad Abdali"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Pak-Afghan border, known as the Durand Line, was drawn in 1893.It was established through an agreement between the British Indian government and the Afghan Amir, Abdur Rahman Khan.The line demarcates the boundary between Pakistan and Afghanistan.', 0, 0, 0, 1790967402891) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e2e83640df858edc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Akbar was only _____ years old when he was crowned Emperor.', '{"A":"12","B":"13","C":"10","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Akbar was crowned Emperor at the age of 13.After the death of his father Humayun in 1556.He was born on October 15, 1542.He became the third Mughal Emperor at a very young age.', 0, 0, 0, 1790967402891) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_24403bb057d26db7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who was the first ruler of slave Dynasty?', '{"A":"Sultan Ghouri","B":"Qutab ud Din Aibak","C":"Muhammad Shah","D":"None of these"}', 'B', NULL, 0, 0, 0, 1790967402891) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_0f72fe56fc71af1e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'According to the 1973 constitution, what is the term of the office of President?', '{"A":"5 years","B":"6 years","C":"3 years","D":"4 years","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation According to the constitution''s 1973, minimum age for President of Pakistan: 45 Years The president is elected indirectly for a term of five years. The incumbent president is eligible for re-election to that office, but cannot hold that office for more than two consecutive terms.ND22-6-2023', 0, 0, 0, 1790967402891) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b70a86cc69172a57', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who was the Leiutenant-Governor of the North-Western Provinces in 1895-1896?', '{"A":"Lord Rippon","B":"Libert","C":"Montgomer","D":"Sir Anthony Patrick"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sir Anthony Patrick MacDonnell was the Lieutenant-Governor of the North-Western Provinces in 1895-1896.He was a prominent British administrator in India known for his reforms in the provinces.He particularly focusing on famine relief and public administration.', 0, 0, 0, 1790967402891) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_02ecf8bad61a9ca9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'The Electoral College of Pakistan for the election of President of Pakistan consists of _____?', '{"A":"The Members of the provincial assemblies","B":"The Members of both Houses","C":"The Members of both Houses and the Members of the provincial assemblies","D":"The Members of the National Assembly"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The President of Pakistan is chosen by an electoral college, in Pakistan. According to Article 41(3) of the Constitution of Pakistan, this electoral college consists of: the Senatethe National Assembly of Pakistan the Provincial Assemblies of the four provinces.There are currently 538 electors in the Electoral College.A majority of 270 electoral votes is required to elect the president.', 0, 0, 0, 1790967402921) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_0455b9be139ddc77', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who was the last ruler of Lodi dynasty?', '{"A":"Ibrahim Lodhi","B":"Bahlol Lodhi","C":"Akbar Lodhi","D":"None of these"}', 'A', NULL, 0, 0, 0, 1790967402921) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_75ee718631464cc4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who became the first president of Anjumaan-I- Himayat-i-Islam?', '{"A":"Qazi Khalifa Hameed ud din","B":"Mufti Bhar Ata","C":"Qasim Nantavi","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Qazi Hameeduddin was originally from Tijara and born on 16 Sha''aban 1290 AH / 1873 AD. ****Anjuman e Himayat e Islam was founded in September 1884.****Who floated the idea of the establishment of Anjuman-e-Hamiat-e-Islam? Munshi Charag ud Din.Who became the first president of Anjumaan-I- Himayat-i-Islam?Qazi Khalifa Hameed ud din The Anjuman-i-Himayat-i-Islam was founded with the objective of?To defend Islam against the onslaughts of the missionaries and provide western instructions education along with religious instructions***RK151222', 0, 0, 0, 1790967402921) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_74f74f9856125384', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who was the last Governor General of India under the British East India Company?', '{"A":"Lord Mayo","B":"Lord Curzon","C":"Lord Robert Clive","D":"Lord Canning"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lord Canning was the last Governor-General of East India Company.He became the first Viceroy of India under Crown rule after the Queen Victoria''s proclamation (also called Magna Carta of India) in 1858, following the Indian Rebellion of 1857.', 0, 0, 0, 1790967402922) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ce7fbfcc56ecbb1b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Before becoming Prime Minister of Pakistan, Feroz Khan Noon was the Governor of ____?', '{"A":"East Pakistan","B":"Sindh","C":"Punjab","D":"KPK"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Feroz Khan Noon was the Governor of East Pakistan from 1953 to 1955, before becoming the Prime Minister of Pakistan in 1957.He served as the seventh Prime Minister of Pakistan from December 1957 to October 1958.', 0, 0, 0, 1790967402922) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_95490cba5699f548', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Which country paid an official visit by the first Prime Minister of Pakistan in 1950?', '{"A":"Iran","B":"America","C":"China","D":"Saudi Arabia"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The state visit of Liaquat Ali Khan to the United States from 3 May to 5 May 1950.An official state visit paid by the first Prime Minister of Pakistan. Liaquat Ali Khan, accompanied by the First Lady of Pakistan, Ra''ana Liaquat Ali Khan.', 0, 0, 0, 1790967402922) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_34dc5d1f0020e6a4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Under which amendment of the Constitution of the Islamic Republic of Pakistan (1973), the President was allowed to unilaterally dissolve the National Assembly and elected governments?', '{"A":"8th Amendment","B":"7th Amendment","C":"11th Amendment","D":"12th Amendment"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The 8th Amendment to the Constitution of the Islamic Republic of Pakistan (1973) allowed the President to unilaterally dissolve the National Assembly and elected governments.This amendment significantly increased presidential powers during its time.', 0, 0, 0, 1790967402922) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_675f9f6cb7294150', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'First Governor-General of Pakistan fixed his salary as?', '{"A":"Rs 1","B":"Rs 4","C":"Rs 6","D":"Rs 10"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation List of Governors-General of Pakistan Term Name Birth–Death Monarch Took office Left office Political party Remarks 1 Muhammad Ali Jinnah (1876–1948) George VI (1947–1952) 15-Aug-47 11-Sep-48 Pakistan Muslim League died in office 2 Sir Khawaja Nazimuddin (1894–1964) = 14-Sep-48 17-Oct-51 Pakistan Muslim League became prime minister 3 Sir Ghulam Muhammad (1895–1956) = 17-Oct-51 7-Aug-55 Independent dismissed 4 Iskander Mirza (1899–1969) Elizabeth II (1952–1956) 7-Aug-55 23-Mar-56 Republican Party became president', 0, 0, 0, 1790967402922) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d05a6911e5a99b7f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'In 1956 the designation of Governor General changed to _____?', '{"A":"President","B":"Chief Executive","C":"Prime Minister","D":"None of these"}', 'A', NULL, 0, 0, 0, 1790967402950) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_63d83511c53be16f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'The last ruler of Ottoman Empire was _____?', '{"A":"Sultan Ahmad","B":"Abdul Majeed II","C":"Sultan Mehmood","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The last ruler of the Ottoman Empire was Abdul Majeed II, also known as Abdulmecid II.He was the 40th Head of the House of Osman and the last Caliph of the Ottoman Caliphate.He reigned from 1922 to 1924, when the Ottoman Empire was dissolved and modern-day Turkey was established.', 0, 0, 0, 1790967402950) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d76a259914f4761e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'At the time when Khilafat delegation visited England in 1920, the British PM was ______?', '{"A":"Lloyd George","B":"Churchill","C":"Chamber line","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Khilafat delegation, led by Muhammad Ali, Shaukat Ali, and other Indian Muslim leaders, visited England in 1920 to protest the treatment of the Ottoman Empire and its Caliph (the spiritual leader of the Muslim world) by the British government.At that time, David Lloyd George was the Prime Minister of the United Kingdom, serving from 1916 to 1922.', 0, 0, 0, 1790967402950) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7409baa7ab8f97cd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who among the following Mughal rulers was a contemporary of Queen Elizabeth I of England?', '{"A":"Jahangir","B":"Aurangzeb Alamgir","C":"Zaheer Ud Din Babur","D":"Akbar the Great"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Akbar the Great was the third Mughal emperor, who reigned from 1556 to 1605. So Elizabeth I is the contemporary of Akbar.Elizabeth I was Queen of England and Ireland from 17 November 1558 until her death on 24 March 1603.ND5.3.2023', 0, 0, 0, 1790967402950) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_1bb0be53d5d20a27', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who was the President at the time of 18th amendment in Pakistan?', '{"A":"Mamnoon Hussain","B":"Farooq Ahmed Laghari","C":"Asif Ali Zardari","D":"Rafiq Tarar","E":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Eighteenth Amendment of the Constitution of Pakistan was passed by the National Assembly of Pakistan on April 8, 2010, removing the power of the President of Pakistan to dissolve the Parliament.', 0, 0, 0, 1790967402950) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ca972b16b106f183', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who was the last governor of undivided Punjab?', '{"A":"Sir Evan Jenkins","B":"Francis mudie","C":"Abdur Rab Nashter","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sir Evan Jenkins was a British colonial official and the British Empire’s last governor of the Punjab.******Sir Edward Douglas Maclagan was the first governor of undivided Punjab.In Pakistan, the first governor of West Punjab was Sir Francis Mudie.RY 15-01-2023', 0, 0, 0, 1790967402950) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_4acbdc160b9c14d8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who was the 3rd President of Pakistan?', '{"A":"Mr. Z.A Bhutto","B":"Ayyub khan","C":"Gen Yahya Khan","D":"Mr. Pervez Musharaf"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Gen. Yahya Khan became the third President of Pakistan after Ayub Khan*****Yahya Khan was a Pakistani general who served as the third president of Pakistan from 25 March 1969 until December 1971.****List Of Presidents Of Pakistan From 1947 To 2022', 0, 0, 0, 1790967402950) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6c89b0711a748197', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Mamnoon Hussain was the ________ President of Pakistan.', '{"A":"10th","B":"13th","C":"11th","D":"12th"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mamnoon Hussain served as the 12th President of Pakistan from 2013 to 2018.He was first appointed Governor of Sindh in June 1999 by President Rafiq Tarar.Mamnoon Hussain Died on 14 July 2021 (aged 80) in Karachi, Sindh.ND23-4-2023', 0, 0, 0, 1790967402950) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f0b4137989f099a1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'In which city Indus Water Treaty signed by the Prime Minister of India and President of Pakistan?', '{"A":"Lahore","B":"Karachi","C":"Kolkata","D":"Multan"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Indus Waters Treaty (IWT) is a water-distribution treaty between India and Pakistan.Indus Waters Treaty brokered by the World BankIt was signed in Karachi on 19 September 1960Sighed by Indian Prime Minister Jawaharlal Nehru and Pakistani President Ayub Khan.the following 3 rivers were given to Pakistan: Indus, Jhelum and Chenab the following 3 rivers were given to India: Sutlej, Beas, Ravi.', 0, 0, 0, 1790967402981) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_4049362c9cf88bbb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Muhammad Zia ul Haq became the _______ President of Pakistan.', '{"A":"Fourth","B":"Fifth","C":"Sixth","D":"Seventh"}', 'C', NULL, 0, 0, 0, 1790967402981) ON CONFLICT(id) DO NOTHING;
