INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b1c6273942671d0a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Which of following dynesty "Razia Sultana". The ruler of Indian subcontinent belonged to _____?', '{"A":"The Slave Dynasty","B":"The Gohri Dynasty","C":"The Tughlaq Dynasty","D":"The Monghul  Dynasty"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Razia Sultan belonged to the Slave Dynasty.She was the first female Muslim ruler of the subcontinentShe was the first and last Muslim lady to rule Delhi.She ruled India from 1236 to 1240Born: 1205, Budaun, IndiaShe was assassinated in KaithalDied: October 15, 1240, Kaithal, IndiaHer mother name is Turkan KhatunHer Father''s name is Shams ud-Din Iltutmis', 0, 0, 0, 1790967402981) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2c65fe7f2d1c4968', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'The politician who served as both Governor General and Prime Minister of Pakistan was ________?', '{"A":"Iskandar Mirza","B":"Gulam Mohammad","C":"Khawja Nazimuddin","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Khawja Nazimuddin served as the Governor General of Pakistan from 1948 to 1951 and then as the Prime Minister from 1951 to 1953.The simultaneously Iskandar Mirza served as the Governor General from 1956 to 1958 and then as the President of Pakistan from 1958 to 1959.', 0, 0, 0, 1790967402981) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d3d98f878889ec6d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'According to the 1956 constitution, President of Pakistan should be ____?', '{"A":"Muslim","B":"Non-Muslim","C":"Both A and B","D":"None of these"}', 'A', NULL, 0, 0, 0, 1790967402981) ON CONFLICT(id) DO NOTHING;
