INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e5734e49da04f600', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'The first Emperor of Tughluq Dynasty?', '{"A":"Ghiyasuddin Tughlaq","B":"Alaudin","C":"Ameer gulzar tughluq","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ghiyath al-Din Tughluq, was the founder of the Tughluq dynasty in India. who reigned over the Sultanate of Delhi from 1320 to 1325. He founded the city of Tughluqabad.', 0, 0, 0, 1790967402981) ON CONFLICT(id) DO NOTHING;
