INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_5263caa45fe9accf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'According to 1973 constitution, who elects the president of Pakistan?', '{"A":"National Assembly","B":"Senate","C":"Provincial Assembly","D":"Both A & B","E":"All of the above"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Zulifqar Ali Bhutto introduced 1973 constitution in Pakistan on August 14, 1973. According to 1973 constitution, Provincial assembly, National assembly, and senate elect the President. Whereas the prime minister is elect by only national assembly. Bicameral Legislature system was introduced for the first time in Pakistan in the constitution of 1973.', 0, 0, 0, 1790967403010) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9519f63f0963bb99', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Collectively how many Governor Generals ruled over Pakistan?', '{"A":"2","B":"3","C":"4","D":"5"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Governor-General of Pakistan # Name Date of Birth and Death 1 Muhammad Ali Jinnah 25 December 1876 – 11 September 1948 2 Sir Khawaja Nazimuddin 19 July 1894 - 22 October 1964 3 Ghulam Mohammad 20 April 1895 - 12 September 1956 4 Iskander Mirza 13 November 1899 - 12 November 1969', 0, 0, 0, 1790967403010) ON CONFLICT(id) DO NOTHING;
