INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_70508cebc2d0a13c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'The Mughal Emperor who promulgated a new faith entitled “Din-E-Elahi” in 1581 AD was __________', '{"A":"Jahangir","B":"Akbar","C":"Humayun","D":"Babar"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Mughal Emperor who promulgated a new faith entitled “Din-E-Elahi” in 1581 AD was Akbar****Akbar born: 1542Akbar died: 1605Mughal Emperor Akbar was born in:SindhAkbar was the ruler Mughal emperor from 1556 to 1605.Mughal Emperor Akbar is buried: AgraMughal Emperor Akbar was the third Emperor from Mughal Family**Muhammad Shah was the last Mughal emperor to sit on the Peacock', 0, 0, 0, 1790967403101) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_52bea12c832f8e72', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'The last Mughal Emperor imprisoned by the English in _______.', '{"A":"Sri Lanka","B":"Bangladesh","C":"Bengal","D":"Myanmmar"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Behadur Shah Zafar was the last Mughal Emperor who was imprisoned by the English in Myanmar.Bahadur Shah Zafar was the last Mughal emperor of India (reigned 1837–57).He was a poet, musician, and calligrapher, more an aesthete than a political leader.Bahadur Shah Zafar was born October 24, 1775, in Delhi, IndiaBahadur Shah Zafar died November 7, 1862, in Rangoon [now Yangon], Myanmar.', 0, 0, 0, 1790967403101) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b7f7b29add6e9381', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'The last Mughal emperor deposed by the British All India Company was?', '{"A":"Aurangzeb","B":"Muhammad Shah","C":"Shah Alam II","D":"Bahadur Shah Zafar"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Behadur Shah Zafar was the last Mughal Emperor who was imprisoned by the English in Myanmar.Bahadur Shah Zafar was the last Mughal emperor of India (reigned 1837–57).He was a poet, musician, and calligrapher, more an aesthete than a political leader.Bahadur Shah Zafar was born October 24, 1775, in Delhi, IndiaBahadur Shah Zafar died November 7, 1862, in Rangoon [now Yangon], Myanmar.', 0, 0, 0, 1790967403101) ON CONFLICT(id) DO NOTHING;
