INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ab25002d603aa6da', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who was Prime Minister of Pakistan for the shortest time period?', '{"A":"I.I.Chundrigar","B":"Nurul Amin","C":"M.Feroz Khan Noon","D":"M.Ali Bogra"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nurul Amin was the shortest in Pakistan''s historyServing only 13 days (7 December 1971 to 20 December 1971) of his term.*****The premiership of I. I. Chundrigar was serving only 55 days (17 October 1957 to 16 December 1957) of his term.Sharif is the longest-serving prime minister.Sharif was re-elected for a third non-consecutive term on 5 June 2013, which is a record in the history of Pakistan.', 0, 0, 0, 1790967403135) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_021aa4dabe1efa68', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'President of Pakistan shall be Muslim and not less than ___________ years of age.', '{"A":"18 Years","B":"25 Years","C":"35 Years","D":"45 Years"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The minimum age for President of Pakistan: 45 YearsThe minimum age for Governor of Pakistan: 35 YearsThe minimum age for PM of Pakistan: 35 YearsThe minimum age for Senator of Pakistan: 30 Years The minimum age for National Assembly Member: 25 Years', 0, 0, 0, 1790967403135) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f467a5bc4e2d8451', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'What was election symbol of Ayoub Khan?', '{"A":"Bat","B":"Red Rose","C":"Wheel","D":"Lion"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A rare image of a 1965 presidential election poster. The contest was held between the incumbent Ayub Hahn (Convention Muslim League / Symbol Rose) and Mrs. Fatima Jinnah (Opposition Joint Party / Lantern). Ayub won in most cities. Jinna won the Karachi and Dhaka championships.', 0, 0, 0, 1790967403195) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c690d099bd3a99a3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Mughal Emperor Zahiruddin Babur was buried in which city?', '{"A":"Kabul","B":"Agra","C":"Delhi","D":"Ajmer Sharif","E":"Ferghana"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Babur died in Agra at the age of 47 on 5 January 1531.He was first buried in Agra but, as per his wishes, his mortal remains were moved to Kabul and reburied in Bagh-e Babur in Kabul sometime between 1539 and 1544.', 0, 0, 0, 1790967403195) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_30ba0f8d1769a72e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who has not been prime minister of Pakistan?', '{"A":"Nawaz Sharif","B":"Liaqat Ali Khan","C":"Benazir","D":"Ayoub Khan","E":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Field Marshal Muhammad Ayub Khan was the president of Pakistan.General Ayoub Khan remained PM of Pakistan from 7 October 1958 to 26 October 1958.', 0, 0, 0, 1790967403195) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_63bfdfd5b1c686d3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'A yellow cab scheme was introduced by which prime minister?', '{"A":"Moeen Qureshi","B":"Benazir Bhutto","C":"Nawaz Sharif","D":"Imran Khan","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A yellow cab scheme was introduced by the then prime minister Nawaz Sharif.Launched in 1992.', 0, 0, 0, 1790967403195) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_87f992bf372d8138', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Iskandar Mirza became the first president of Pakistan on 23 March____?', '{"A":"1954","B":"1956","C":"1958","D":"1962"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Iskandar Mirza was the last Governor-General and first President of Pakistan, serving from 1956 to 1958.A former civil servant and military officer, he imposed martial law in 1958 but was soon ousted by General Ayub Khan.', 0, 0, 0, 1790967403195) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_5d23e187166e4bf7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'The election commission of Pakistan was formed on 23 March_?', '{"A":"1954","B":"1956","C":"1955","D":"1957","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The President of Pakistan appoints the Chief Election Commissioner and four members of the Election Commission of Pakistan for 5 years.The election commission was established on 23 March 1956.', 0, 0, 0, 1790967403195) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a7c6cd1452a854f5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'The Last Hindu ruler of the Sub-continent was?', '{"A":"Raja Pirthavi Raj","B":"Raja Dahir","C":"Raja Jay Pal","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prithviraj Chauhan has often been described as “the last Hindu emperor”the twelfth-century Indian ruler Prithviraj Chauhan, Prithviraj III, popularly known as Prithviraj Chauhan or Rai Pithora, Prithviraj was a king from the Chauhan dynasty who ruled the territory of Sapadalaksha, with his capital at Ajmer in present-day Rajasthan.Born: 1166, Gujarat, IndiaDied: 1192, Ajmer, IndiaReign: c. 1177–1192 CEND06-08-2023', 0, 0, 0, 1790967403195) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7aa00048dafb41ff', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who became the first CM of Balochistan in 1970?', '{"A":"General Riaz Hussain","B":"Nawab Akbar Khan","C":"Ataullah Mengal","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ataullah Mengal was a Pakistani politician and feudal figurethe 1st Chief Minister of Balochistan during Zulfikar Ali Bhutto''s premiership from 1 May 1972 to 13 February 1973.The post was established by President Yahya Khan on July 1, 1970.Full name: Ataullah Khan MengalBorn: March 24, 1929, WadhDied: September 2, 2021, in KarachiParty: Balochistan National Party (Mengal)ND18-5-2023', 0, 0, 0, 1790967403195) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2e7fd57577bc353d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Prime Minister Imran Khan reached Moscow for a 2-day official visit to Russia on?', '{"A":"February 23, 2022","B":"February 13, 2022","C":"February 03, 2022","D":"February 01, 2022","E":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prime Minister Imran Khan will visit Russia on February 23-24, diplomatic sources said in Islamabad on Monday,signaling the first visit by a Pakistani premier to Moscow in 23 yearsOn Wednesday, Pakistani Prime Minister Imran Khan will be the first foreign leader to meet with Russian President Vladimir Putin.***Who has recently urged PM Imran Khan to raise the issue of Ukraine during Russia visit?Ukrainian Ambassador to PakistanND30-4-2023', 0, 0, 0, 1790967403234) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8a27c343857e9f92', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'The Khewra salt mine were discovered by which emperor in 326 BC ?', '{"A":"Porus","B":"Darius","C":"Alexander","D":"none"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation It is Pakistan’s largest and oldest salt mine and the world’s second-largest mine.The Khewra Salt Mine (or Mayo Salt Mine) is in Khewra, north of Pind Dadan Khan, an administrative subdivision of Jhelum District, Punjab Region, Pakistan.The Khewra salt mine was discovered by Alexander emperor in 326 BC ProductionProducts Rock saltProduction 3,50,000 MTThe financial year 2019–20HistoryOpened 1872Active 150 yearsND23-4-2023', 0, 0, 0, 1790967403234) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3fd14fbd7a2acd85', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Quaid e Azam remained President of Muslim League for how many year?', '{"A":"35","B":"38","C":"36","D":"34","E":"31"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation All India Muslim League was founded on 30 December, 1906 in Dhaka. Quaid e Azam joined All India Muslim League in 1913. Quaid e Azam remained President of AIML for 34 years.', 0, 0, 0, 1790967403234) ON CONFLICT(id) DO NOTHING;
