INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7dcd0f9dd2cb697f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Governor of province is appointed by?', '{"A":"Chief minister","B":"Prime Minister","C":"President","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A Governor in Pakistan is the appointed Head of State of a province. The Provincial Governor is appointed by the President of Pakistan, on the advice of the Prime Minister. The Governor''s tenure lasts for five years.Minimum 35 years age required for Governor', 0, 0, 0, 1790967403234) ON CONFLICT(id) DO NOTHING;
