INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_dfd8dec1670a50cb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Shah Jahan became emperor of India in:', '{"A":"1628","B":"1629","C":"1566","D":"1634"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Shah Jahān, also spelled Shāhjahān or Shah Jehan, additionally called (until 1628) Prince Khurram, unique name Shihāb al-Dīn Muḥammad Khurram, (born January 5, 1592, Lahore [now in Pakistan]—died January 22, 1666, Agra [now in India]), Mughal emperor of India (1628–fifty eight) who built the Taj Mahal.', 0, 0, 0, 1790967403264) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_264e0c905b3e0ac7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Gerald R. Ford became US president by:', '{"A":"Appointment","B":"Elections","C":"Nomination","D":"Succession"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation BANS:he 1976 United States presidential election was the 48th quadrennial presidential race. It was held on Tuesday, November 2, 1976. Democrat Jimmy Carter of Georgia vanquished occupant Republican President Gerald Portage from Michigan by a limit triumph of 297 constituent college votes to Ford''s 240.', 0, 0, 0, 1790967403264) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d8e686c4a4fd9f06', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who became the Governor-General of British India in 1910?', '{"A":"Lord Mayo","B":"Lord Curzon","C":"Lord Hardinge","D":"Lord Minto"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation CANS:A grandson of Lord Hardinge, governor-general of India in 1844–48, Charles Hardinge entered the conciliatory benefit in 1880. Appointed minister to Russia in 1904 and lasting beneath secretary for remote issues in 1906, he was raised to the peerage and designated emissary of India in 1910.', 0, 0, 0, 1790967403264) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_0f764ba660a36723', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'What deadline did the British prime minister clement Attlee announce for granting of granting of independence to India on February 20,1947?', '{"A":"June 1948","B":"June 1947","C":"July 1948","D":"June 1949"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Clement Attlee was leader of the Labour Party from 1935 to 1955, Britain''s Prime Minister from 1945 to 1951.', 0, 0, 0, 1790967403264) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_74027fcae3e3dcd7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Which party won the provincial election in 1937?', '{"A":"Muslim league","B":"Congress","C":"Muslim Students Federation","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Elections were held in eleven provinces - Madras, Central Provinces, Bihar, Orissa, United Provinces, Bombay Presidency, Assam, NWFP, Bengal, Punjab and Sindh.', 0, 0, 0, 1790967403264) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_55b4b14da9647a13', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who was First President of Pakistan Muslim League in 1949?', '{"A":"Ch. Khaliquzzaman","B":"Nawab Saleem ullah Khan","C":"Nawab Waqar ul Mulk","D":"All of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation All India Muslim League Founder: Nawab Khwaja SalimullahAll India Muslim League 1st President: Sir Agha KhanAll India Muslim League Founded: 30 December 1906 at Dacca, British India (now Dhaka, Bangladesh)All India Muslim League Headquarters: LucknowAll India Muslim League Dissolved: 14 August 1947جب 1947 میں مسلم لیگ ختم ہوئی تو یہ تین پارٹیاں بن گئی1- Muslim League in Pakistan2- Awami League in Bangladesh3- Indian Union Muslim League in India', 0, 0, 0, 1790967403293) ON CONFLICT(id) DO NOTHING;
