INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_28adb502cc3031e4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'One Unit Bill was passed in which year?', '{"A":"1955","B":"1948","C":"1950","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The One Unit was the reorganization of the provinces of Pakistan .Prime Minister Muhammad Ali Bogra led it on 22 November 1954.and passed on 30 September 1955This program merged the four provinces of West Pakistan into a single province to parallel the province of East PakistanWest PunjabSindNWFPBaluchistanAdditional information:The One Unit scheme was dissolved on July 1, 1970General Yahya Khan imposed Legal Framework Order No. 1970 to end the programand reinstate the provisional status of the Four Provinces as of August 1947.', 0, 0, 0, 1790967403750) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_27a301f9e84dc418', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Who was the first Chairman of Senate?', '{"A":"Tasleem  Aslam","B":"Habib Ullah Khan","C":"Abdul Rasheed","D":"Sikandar Mirza"}', 'B', NULL, 0, 0, 0, 1790967403750) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c75476900468e2ca', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Article 25 of the 1973 Constitution of Pakistan deals with?', '{"A":"Rule of Law","B":"Equality of citizens","C":"Equal protection of law","D":"All of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Article 25 of the 1973 Constitution of Pakistan deals with Equality of citizens.Article 25(A) of constitution of 1973 deals with Right to education.Last updated 18-07-2026 by NA', 0, 0, 0, 1790967403750) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_5441b54a28a415b8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'After how many years Pakistan got its first constitution?', '{"A":"7 years","B":"11 years","C":"9 years","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation After 09 years Pakistan got its first constitution.on 23rd March 1956 first constitution of Pakistan was enforced.Choudhry Mohammad Ali was the Prime Minister of Pakistan during the enforcement of the first constitution.There were 234 articles 13 parts and 6 schedules.After the abrogation of the first constitution, the new constitution was enforced by Ayoub Khan on June 1962AGM 02.05.2023', 0, 0, 0, 1790967403750) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_634abf9e671f609b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Who is the current speaker of National Assembly of Pakistan?', '{"A":"Pervaiz Ilahi","B":"Asad Qaiser","C":"Raja Pervez Ashraf","D":"Sardar Ayaz Sadiq"}', 'D', NULL, 0, 0, 0, 1790967403750) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_1dc97448b533723f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'India revoked the special status granted under Indian constitution of Jammu Kashmir on?', '{"A":"3 August 2019","B":"5 August 2019","C":"4 August 2019","D":"6 August 2019","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation On 5 August 2019, the Parliament of India voted in favour of a resolution tabled by Home Minister Amit Shah to revoke the temporary special status, or autonomy, granted under Article 370 of the Indian Constitution to Jammu and KashmirAGM 02.05.2023', 0, 0, 0, 1790967403750) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_bf715b7fcdb6c3f2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'The Montagu-Chelmsford report formed the basis of Indian Council Act as?', '{"A":"The government of India act 1935","B":"The government of India act 1909","C":"The government of India act 1919","D":"The government of India act 1947"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Montagu-Chelmsford Report was published on July 8, 1918.The report was the result of discussions between Edwin Montagu, secretary of state for India from 1917 to 1922, and Lord Chelmsford, the viceroy of India between 1916 and 1921.The report was used as the basis for the Government of India Act of 1919.', 0, 0, 0, 1790967403793) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_63e24b245d5549f8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'The 1973 Constitution of Pakistan came into force on?', '{"A":"14th August 1973","B":"23rd March 1973","C":"27th October 1973","D":"8th June 1973"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The 1973 Constitution of Pakistan was Passed on April 10, 1973Approved on April 12Enforced on August 14, 1973Drafted by Zulfikar Ali Bhutto''s government,This Constitution is called the Constitution of the Islamic Republic of Pakistan 1973Additional informationFeature of the 1973 Constitution(Majlis-e-Shoora) consisting of the National Assembly and the Senate.Declares Islam as the state religionRequires all laws to conform to the Quran and Sunnah.Last updated on 09-03-2026', 0, 0, 0, 1790967403793) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e74a087a1923fee3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Under which article of the 1973 Constitution any law inconsistent with or in derogation of Fundamental Rights to be void?', '{"A":"Article 10","B":"Article 8","C":"Article 7","D":"Article 9"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Article 8 of the 1973 Constitution of Pakistan states that any law inconsistent with or in derogation of Fundamental Rights will be considered void.This ensures the protection of citizens'' fundamental rights under the Constitution.', 0, 0, 0, 1790967403793) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b275a4efc47428e4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Pakistan''s Constitution provides protection against retrospective punishment _____?', '{"A":"Yes","B":"No","C":"Not mentioned","D":"Is vague"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan''s Constitution does provide protection against retrospective punishment under Article 12.It states that no law shall authorize punishment for an act that was not punishable when committed.', 0, 0, 0, 1790967403793) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_edaf3c4cfd10c3de', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Article 6 of the constitution of Pakistan 1973 deals with _____?', '{"A":"High treason","B":"Fundamental Rights","C":"Protection of minorities","D":"Right of education"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation High Treason means سنگین غداری Any person who abrogates or subverts or suspends or holds in abeyance, or attempts or conspires to abrogate or subvert or suspend or hold in abeyance, the Constitution by use of force or show of force or by any other unconstitutional means shall be guilty of high treason.************FIA CBT VU PAPER 17-12-2021', 0, 0, 0, 1790967403793) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2187c63b9678f7c4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Article 73(1) of the Constitution of Pakistan 1973, a money bill shall be originated in _____?', '{"A":"The National Assembly","B":"The Senate Only","C":"The President Secretariat","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Article 73(1) of the Constitution 1973 states that a Money Bill can only originate in the National Assembly.This maintains the principle that financial control rests with directly elected representatives of the people.', 0, 0, 0, 1790967403793) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9316e94afbd2aea1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Which article of the Constitution of Pakistan obligates the state to provide free and compulsory education to children of the age group 5 to 16 years?', '{"A":"52-B","B":"25-A","C":"27-B","D":"29-B"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Article 25-A of the Constitution of Pakistan obligates the state to provide free and compulsory education to children aged 5 to 16 years.This article ensures that every child has access to education as a fundamental right.', 0, 0, 0, 1790967403793) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f60c1b5ffd462ab0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Who appoints the Judges of the Federal Shariat Court?', '{"A":"President","B":"Prime Minister","C":"Chief Justice of Pakistan","D":"President of Pakistan"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Judges of the Federal Shariat Court (FSC) are appointed by the President of Pakistan under Article 203C of the Constitution.More Details The Court consists of 8 Muslim Judges, including the Chief Justice. The President consults with the Chief Justice of Pakistan before appointment.وفاقی شرعی عدالت کے ججوں کو پاکستان کے صدر آئین کے آرٹیکل 203C کے تحت مقرر کرتے ہیں۔', 0, 0, 0, 1790967403793) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d03610ca018f5511', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Which of the following court unfreezes PIA assets in the Reko Diq award case?', '{"A":"International Court of Justice","B":"International Court of Justice","C":"British Virgin Islands High court","D":"All of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The British Virgin Islands High Court has ordered unfreezing offshore assets of the Pakistan International Airlines in the Reko Diq case on May 25, 2021. The court has recalled its December 2020 orders to attach certain PIA assets in the Reko Diq case against Pakistan.', 0, 0, 0, 1790967403834) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b11a4e0cb57367af', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'According to the Article 18(a) of the Constitution of Pakistan 1973, No person shall be punished for the same offence more than _____?', '{"A":"Thrice","B":"Once","C":"Twice","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Article 13(a) of the Constitution of Pakistan 1973 states: No person shall be prosecuted or punished for the same offence more than once.This is the constitutional guarantee against double jeopardy.', 0, 0, 0, 1790967403834) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2a398f1963ad5613', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Who is the Present/Current Deputy Speaker of National Assembly of Pakistan?', '{"A":"Dost Muhammad Mazari","B":"Zahid Akram Durrani","C":"Ghulam Mustafa Shah","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ghulam Mustafa Shah is the current deputy speaker of National Assembly. Appointing date: 01 March 2024Party name: PPPPredecessor: Zahid Akram Durrani', 0, 0, 0, 1790967403834) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_086ff0999cff804a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'When the second Martial Law was imposed in Pakistan?', '{"A":"October 7, 1958","B":"March 25, 1969","C":"December 25, 1970","D":"March 23, 1970"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation List of Martial Laws Held in Pakistan from 1947 to 2022Sr# Martial Law NumberDate of Martial LawMartial Law Implemented by1First Martial Law7th October 1958Iskandar Mirza22nd Martial Law25th March 1969General Yahya Khan33rd Martial Law25th July 1977General Zia ul Haq44th Martial Law12th October 1999General Pervaiz Musharraf There are total four martial laws Implemented in Pakistan from 1947 to 2022', 0, 0, 0, 1790967403834) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_042617397afe7774', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Total number of seats in National Assembly of Pakistan are _______?', '{"A":"336","B":"332","C":"342","D":"344"}', 'A', NULL, 0, 0, 0, 1790967403834) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8844ac19d2e26170', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'How many articles were there in the constitution of 1956?', '{"A":"100 Articles","B":"200 Articles","C":"234 Articles","D":"254 Articles"}', 'C', NULL, 0, 0, 0, 1790967403834) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_4f953ffaf55de2c3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Which language was declared as National in the 1973 constitution of Pakistan?', '{"A":"English","B":"Urdu","C":"Punjabi","D":"None of these"}', 'B', NULL, 0, 0, 0, 1790967403834) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e5fc453a167a8754', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Under which constitution of Pakistan Islamabad was confirmed as the capital of Pakistan?', '{"A":"1973","B":"1956","C":"1962","D":"1935"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Article 1(2)(b) of the Constitution of the Islamic Republic of Pakistan, 1973 declared the status of Islamabad Capital Islamabad officially became the capital of Pakistan on 14 August 1967.Ayoub Khan made Islamabad the capital of PakistanThe area before its declaration as the capital of Pakistan was known as Raj Shahi.Islamabad is the country''s ninth-most populous city, with a population of over 1.2 million peopleThe name Islamabad means City of Islam.Islamabad Constructed 1960', 0, 0, 0, 1790967403834) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ddccb4d90edfda3a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'The first Martial Law was imposed in Pakistan in the which year?', '{"A":"1955","B":"1956","C":"1958","D":"None of these"}', 'C', NULL, 0, 0, 0, 1790967403870) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ed9e17506140b91f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'The first constitution of Pakistan was abrogated in favor of the Legal Framework Order (LFO) on ______?', '{"A":"7th October 1956","B":"7th October 1958","C":"7th October 1960","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation On 7th October 1958, President Iskander Mirza abrogated the 1956 Constitution and imposed martial law.This paved the way for General Ayub Khan’s takeover under the Legal Framework Order (LFO).', 0, 0, 0, 1790967403870) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7527be1f59623399', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'What is the age of Retirement of a Judge of Supreme Court in Pakistan?', '{"A":"55","B":"60","C":"62","D":"65"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A Judge of the Supreme Court can hold his office until the age of 65 yearsThis age was decided in the 6th amendment of the Constitution.Additional informationSupreme Court comprises 17 Judges High Court Judge can hold his office until 62 years.', 0, 0, 0, 1790967403870) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_19761b6ffd546e5c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Retirement age of High Court Judge is _____?', '{"A":"55 years","B":"60 years","C":"62 years","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Retirement age of High Court Judge is: 62 years.The retirement age of Supreme Court Judge is: 65 years.Unless he sooner resigns or is removed from office in accordance with the Constitution.', 0, 0, 0, 1790967403870) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9dbbe42d30cdd09f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Where is the Principle Seat of Supreme Court located?', '{"A":"Islamabad","B":"Lahore","C":"Peshawar","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Principal Seat of the Supreme Court of Pakistan is in Islamabad.However, registries also exist in Lahore, Karachi, Peshawar, and Quetta.The Supreme Court of Pakistan is the highest appellate court of the country and court of last resort. It is the final arbiter of the law and the Constitution. All executive and judicial authorities are bound to act in aid of the Supreme Court. It comprises 17 Judges.', 0, 0, 0, 1790967403870) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_82d5a93582b6a715', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'According to the Constitution of Pakistan, the Chief Executive and most powerful person in Pakistan is _____?', '{"A":"Governor","B":"Chief Minister","C":"President","D":"Prime Minister"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Prime Minister is the Chief Executive who heads and exercises the authority of the Government of Pakistan. After obtaining a vote of confidence, the Prime Minister is invited by the President to take the oath of office and form the government.Term 5 years.', 0, 0, 0, 1790967403870) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e77c3d281095dcb6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'For a no-confidence motion to be successful, the support of a simple majority ______ of the total 342 members in the lower house of parliament is required.', '{"A":"152","B":"172","C":"180","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The National Assembly has 342 seats, 272 of which are directly elected.60 are reserved for women and a further 10 for religious minorities.', 0, 0, 0, 1790967403871) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8e1c5ef5da7f94df', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Who has power to grant pardons or commute sentences passed by any court of Pakistan?', '{"A":"Prime minister","B":"President","C":"Governor","D":"Chief minister"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Under Article 45 of the Constitution of Pakistan, the President has the power to grant pardons, reprieves, respites, or commute any sentence passed by any court.This power applies to all types of punishments, including death sentences, across Pakistan.', 0, 0, 0, 1790967403871) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_afba775582472b38', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'The Presiding head of National Assembly _________?', '{"A":"Deputy Speaker","B":"Speaker","C":"Prime Minister","D":"President"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Speaker is the presiding head of the National Assembly of Pakistan.The Speaker conducts proceedings, maintains order, and represents the Assembly in its relations with the President and other authorities.', 0, 0, 0, 1790967403913) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_4e4923db1700b558', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'As per Article 176 of Constitution of Pakistan 1973, The Supreme Court shall consist of a Chief Justice Shall be known as chief justice of Pakistan and so many other judges as may be determined by act of Majlis-e-Shoora or untill so determined as may be fixed by the _______ of Pakistan.', '{"A":"Parliament","B":"Judicial commission","C":"President","D":"Chief Justice"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The President is the head of state of Pakistan.Article 176 of the Constitution of Pakistan 1973 states that the number of Supreme Court judges, until fixed by Act of Majlis-e-Shoora, shall be determined by the President of Pakistan.The Chief Justice of Pakistan is appointed separately, while the President decides the total strength of judges until Parliament legislates otherwise.', 0, 0, 0, 1790967403913) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_51bf7517001ad925', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'As per Article 75(3) of the Constitution of Pakistan 1973, when the ______ has assented or is deemed to have assented to a Bill, it shall become law and be called an Act of Majlis-e-Shoora (Parliament).', '{"A":"Prime Minister","B":"President","C":"Senate Chairman","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Article 75(3) states that when the President assents or is deemed to have assented to a Bill, it becomes law.After assent, it is formally called an Act of Majlis-e-Shoora (Parliament).', 0, 0, 0, 1790967403913) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_adca28993c139383', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'As per Article 60(2) of the Constitution of Pakistan 1973, the term of office of the Chairman or Deputy Chairman shall be _____ years from the day on which he enters upon his office.', '{"A":"5","B":"3","C":"2","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Article 60(2) specifies that the Chairman and Deputy Chairman of the Senate hold office for three years.This term limit ensures periodic leadership rotation in the Senate.', 0, 0, 0, 1790967403913) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_0b6d1a1f6346e4e5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'As per Article 3 of the Constitution of Pakistan 1973, the _____ shall ensure the elimination of all forms of exploitation and the gradual fulfilment of the fundamental principle, from each according to his ability to each according to his work.', '{"A":"State","B":"Executive","C":"Legislature","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Article 3 places the responsibility on the State to eliminate exploitation.It also promotes the principle of fair contribution and reward based on ability and work.', 0, 0, 0, 1790967403913) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_620abb461a14d6a5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'As per the Case of Miss Asma Jillani vs Government of Pakistan (PLD 1972 S.C 139), the precise question the Supreme Court was whether the High Courts had jurisdiction under Article 98 of the _____ to enquire into the validity of detention under the Martial Law Regulation No. 78 of 1971 in view of the bar created by the provisions of jurisdiction of Courts (Removal of Doubts) Order 1969.', '{"A":"Constitution of Pakistan 1956","B":"Constitution of Pakistan 1962","C":"Constitution of Pakistan 1973","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Asma Jillani case was decided when the 1962 Constitution was in force.Article 98 of the 1962 Constitution dealt with the High Courts’ writ jurisdiction.', 0, 0, 0, 1790967403913) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e564f1333bb0e9a4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Under Constitution of Pakistan 1973, the Chairman and Deputy Chairman of Senate to take oaths before entering upon their offices in the form set out in the ______?', '{"A":"Third Schedule","B":"First Schedule","C":"Second Schedule","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The oath of office for the Chairman and Deputy Chairman of the Senate is prescribed in the Third Schedule of the 1973 Constitution.This Schedule contains oath formats for key constitutional offices, ensuring loyalty to Pakistan and adherence to the Constitution.', 0, 0, 0, 1790967403913) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ce21993612e76151', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'As per Article 33 of the Constitution of Pakistan 1973, the State shall discourage _____ sectarian and provincial prejudices among the citizens.', '{"A":"Religious","B":"Regional","C":"Parochial","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Article 33 of the Constitution of Pakistan 1973 directs the State to discourage parochial, racial, tribal, sectarian, and provincial prejudices.The aim is to promote unity and harmony among all citizens of Pakistan.', 0, 0, 0, 1790967403913) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_86dae825d1a19832', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'As per Article 1(1) of the Constitution of Pakistan 1973, Pakistan shall be ______ Republic to be known as the Islamic Republic of Pakistan.', '{"A":"Federal","B":"Islamic","C":"Democratic","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Article 1(1) of the Constitution of Pakistan 1973 states that “Pakistan shall be a Federal Republic to be known as the Islamic Republic of Pakistan.”This highlights Pakistan’s system of government as a federation of provinces under one republic.', 0, 0, 0, 1790967403947) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_bd05ff4cf87e1c2e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'As per Article 65 of the Constitution of Pakistan 1973, a person elected to a House shall not sit or vote until he has made before the House oath in the form set out in ______ the schedule.', '{"A":"Third","B":"Second","C":"First","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation According to Article 65 of the Constitution of Pakistan 1973, a person elected to a House cannot sit or vote until they fulfill a formal requirement.They must take an oath before the House in the form set out in the Third Schedule of the Constitution.', 0, 0, 0, 1790967403947) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_229267c20395951f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'As per the Case of Miss Asma Jillani vs Government of Pakistan (PLD 1972 S.C 139), filed against the detention of Malik Ghulam Jillani which was dismissed by the Lahore High Court, one of the questions before the Supreme Court was whether the doctrine enunciated in the case of _____ was correct.', '{"A":"State vs Dosso (PLD 1958 SC 533)","B":"Maulvi Tamiz-ud-Din Khan vs Governor General of Pakistan (PLD 1955 F.C 240)","C":"Muhammad Nawaz Sharif vs President of Pakistan (PLD 1993 SC 473)","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In Miss Asma Jillani vs Government of Pakistan (PLD 1972 S.C 139), the Court examined the validity of the doctrine of necessity.This doctrine had been enunciated in State vs Dosso (PLD 1958 SC 533), which the Court reviewed and overruled.', 0, 0, 0, 1790967403947) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_cb6af2b1a34d5976', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'As per Article 177(1) of the Constitution of Pakistan 1973, the Chief Justice of Pakistan and each of the other Judges of the Supreme Court shall be appointed by the _____ in accordance with Article 175A.', '{"A":"President","B":"Chief Justice","C":"Prime Minister","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Article 177(1) specifies that the President appoints the Chief Justice and other judges of the Supreme Court.The process must follow the procedure laid out in Article 175A, involving the Judicial Commission and Parliamentary Committee.', 0, 0, 0, 1790967403947) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9c40d5fa97d97d02', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'How many seats are reserved for women in the National Assembly of Pakistan?', '{"A":"40","B":"50","C":"60","D":"70"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The National Assembly has a total of 342 seats.Of these, 266 are filled through direct elections.10 seats are reserved for religious minorities.60 seats are reserved for women, allocated through proportional representation to parties with more than 5% of the vote.ProvinceGeneralWomenNon-MuslimsTotalPunjab1413310174Sindh611475KPK45954Balochistan16420Islamabad3-3 2666010', 0, 0, 0, 1790967403947) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ca67278f273645aa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'What is the total number of judges of the supreme court of Pakistan?', '{"A":"17","B":"10","C":"16","D":"19"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Chief Justice of Pakistan and each of other judges of the Supreme Court shall be appointed by the President in accordance with Article 175A, inserted through 18th and 19th Constitutional amendments.In the light of this provision “The Supreme Court (Number of Judges) Act, 1997” has determined that the number of the Judges of the Supreme Court of Pakistan other than the Chief Justice shall be sixteen.', 0, 0, 0, 1790967403947) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_15b732d5b157ae0e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Which constitution named Pakistan as Islamic Republic of Pakistan?', '{"A":"1962","B":"1956","C":"1973","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation After nine years of efforts, Pakistan was successful in framing a constitution.The Constituent Assembly adopted it on 29 February 1956it was enforced on 23 March 1956 proclaiming Pakistan to be an Islamic republic.This constituent consists of:234 Articles divided into 13 parts and 6 schedules.23rd March became our Republic dayIn 1957 Pakistan officially renamed the Islamic Republic of Pakistan', 0, 0, 0, 1790967403947) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_bd4d236ccf9014f9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'How many members are elected to the National Assembly of Pakistan for a term of five years?', '{"A":"342","B":"272/342 (266/366)","C":"296","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation According to Article 51 (1) and 3(a) of the Constitution of the Islamic Republic of PakistanArticle 51. (1) There shall be [three hundred and thirty-six] seats for members in the National Assembly, including seats reserved for women and non-Muslims. Province / AreaGeneral SeatsWomen SeatsNon-MuslimTotal SeatsBalochistan16420Khyber Pakhtunkhwa451055Punjab14132173Sindh611475Federal Capital3-31010Total2666010336', 0, 0, 0, 1790967403947) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a730b28c5d0c3647', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Which is the highest court of justice in Pakistan?', '{"A":"Lahore High Court","B":"Sindh High Court","C":"Islamabad High Court","D":"Supreme Court of Pakistan"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The highest court of justice in Pakistan is the Supreme Court of Pakistan.It has the ultimate authority in judicial matters and oversees the constitutionality of laws and decisions.', 0, 0, 0, 1790967403977) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_70c374270f022c4e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'When the first constitution was abrogated and the first martial law was enforced/proclaimed?', '{"A":"7th January 1958","B":"7th April 1958","C":"7th June 1958","D":"7th October 1958"}', 'D', NULL, 0, 0, 0, 1790967403977) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e9d613ac02f3378f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Constitution(s) having preamble(s) based on Objective Resolution?', '{"A":"1962","B":"1956","C":"1973","D":"Both A and C","E":"Both B and C"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Constitutions having preambles based on the Objective Resolution are "1956" and "1973."The Objective Resolution, adopted in 1949, was incorporated into these Constitutions to reflect its principles.', 0, 0, 0, 1790967403977) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_95c679ce55e518c9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Objective Resolution defines the role of _____ in the constitution of Pakistan.', '{"A":"Religion","B":"People","C":"Minorities","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Objective Resolution defines the role of the sovereignty of Allah/Islamic principlesSpecifically, that sovereignty belongs to Allah, and authority is delegated to the peopleThe foundational principles of democracy, freedom, equality, and social justice Passed on March 12, 1949, by the first Constituent Assembly. Now incorporated directly into the 1973 Constitution as Article 2ALast updated question NS on 09 MAY 2026', 0, 0, 0, 1790967403977) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_4c3491b6444a26aa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'The Upper House of the Parliament of Pakistan is known as?', '{"A":"Cabinet","B":"National Assembly","C":"Senate","D":"Presidency"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation After the 2021 Senate Election total seats of Senate = 100(4 seats less due to FATA merging into KPK)in 2023 it reduce till 96The Senate of Pakistan ایوان بالا is the upper legislative chamber of the bicameral legislature of Pakistan.**************', 0, 0, 0, 1790967403977) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9f02970ceec584fa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'When third and longest martial law in the history of Pakistan imposed?', '{"A":"5 July 1972","B":"5 July 1979","C":"5 July 1977","D":"5 July 1991","E":"5 July 1969"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation List of martial lawsSr# Martial Law NumberDate of Martial LawMartial Law Implemented by1First Martial Law7th October 1958Iskandar Mirza22nd Martial Law25th March 1969General Yahya Khan33rd Martial Law25th July 1977General Zia ul Haq44th Martial Law12th October 1999General Pervaiz Musharraf', 0, 0, 0, 1790967403977) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_43246b178b23f274', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'The whole Government of India Act of 1935 came into operation in Provincial part?', '{"A":"3rd April 1937","B":"3rd April 1936","C":"3rd April 1935","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Government of India Act of 1935 came into effect in the provinces of India in 1937. The act was passed by the British Parliament in 1935.', 0, 0, 0, 1790967403977) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6d7113555f722e82', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'The Government of India Act, 1935 was enforced in _______?', '{"A":"July 1935","B":"July 1779","C":"June 1935","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Government of India Act, 1935 was an Act adapted from the Parliament of the United Kingdom.It originally received royal assent in August 1935.It was the longest Act of (British) Parliament ever enacted until Greater London Authority Act 1999 surpassed it.', 0, 0, 0, 1790967403977) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_1fd25b86bdf30b70', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'What is the minimum age to become a member of Provincial Assembly?', '{"A":"21 years","B":"25 years","C":"27 years","D":"29 years"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation According to Article 113 of the Constitution of Pakistan, the minimum age to become a member of the Provincial Assembly is 25 years.The candidate must also be a registered voter in any part of Pakistan.', 0, 0, 0, 1790967404011) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e91663d49bdba788', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Who among the following was/were resigned from the Imperial Legislative Council against Rowlatt Act?', '{"A":"Madan Mohan Malaviya","B":"Mazhar-ul-Haq","C":"Mohammed Ali Jinnah","D":"All of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Muhammad Ali Jinnah, Madan Mohan Malaviya, and Mazhar-ul-Haq resigned from the Imperial Legislative CouncilOfficial Name: Anarchical and Revolutionary Crimes Act, 1919Passed: 18 March 1919Location: Delhi, British IndiaHis resignation was a protest against the Rowlatt Act.He termed the Act “a black law” because it curtailed civil liberties.Last updated 27-07-2026 by NA', 0, 0, 0, 1790967404011) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_14d930f122c2df00', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'The report which was presented by Nehru for the future Constitution of India was rejected by ______?', '{"A":"The Muslim League","B":"The Congress","C":"The British","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Nehru Report (1928) proposed a united India without separate electorates, which was unacceptable to the Muslim League. Jinnah rejected it and later presented his Fourteen Points (1929) in response.', 0, 0, 0, 1790967404011) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e361f26512c24e66', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'A judge of the Supreme Court of Pakistan shall hold office until he or she attains the age of ______?', '{"A":"62 years","B":"65 years","C":"68 years","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A Judge of the Supreme Court can hold his office until the age of 65 years.While a High Court Judge can hold his office until 62 years.This age was decided in the 6th amendment of the constitution.Supreme Court comprises 17 Judges.', 0, 0, 0, 1790967404011) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8a7ea33565843e36', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'How many members of the National Assembly of Pakistan?', '{"A":"342","B":"336","C":"360","D":"320"}', 'B', NULL, 0, 0, 0, 1790967404011) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_0951bd28405dd7e9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'What was the official language declared in 1962 constitution?', '{"A":"Urdu","B":"Urdu and Bengali","C":"Urdu and Pashto","D":"Urdu and Punjabi"}', 'B', NULL, 0, 0, 0, 1790967404011) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e79b8d8dd6be225a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Under Yahya’s LFO, what option National Assembly had if it couldn’t frame the constitution within 120 days?', '{"A":"Extension in time frame","B":"Dissolved automatically","C":"President will dissolve it","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation LFO stands for Legal Framework Order. LFO was implemented in 1970 by Yahya Khan in Pakistan.', 0, 0, 0, 1790967404011) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e8442499bb0255e2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'In accordance with 25th Constitutional Amendment, the total senate seats will be reduced to ____ from existing 104 after the retirement of FATA Senators in 2024.', '{"A":"94","B":"98","C":"96","D":"100"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Passed In National Assembly: May 24th, 2018In Senate: May 25th, 2018In Provincial Assembly of Khyber Pakhtunkhwa: May 27th, 2018Assented to May 31st, 2018', 0, 0, 0, 1790967404011) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c95c37975e848654', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'When the constitution of 1962 was abrogated?', '{"A":"21th March 1968","B":"22nd March 1969","C":"25th March 1969","D":"26th March 1968","E":"28th March 1969"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation President Ayub Khan promulgated the Constitution of 1962 on 1 March 1962 It finally came into effect on 8 June 1962In 1962 constitution:The presidential government system was introduced Urdu and Bengali was Declared as the Official Language Iskandar Ali Mirza, the first president of Pakistan abrogated the constitution of 1956 Ayoub Khan was made chief of martial law after this abrogationAyoub Khan enforced the new constitution on 8th June 1962Yahiya Khan abrogated the 1962 constitution and became CMLA', 0, 0, 0, 1790967404040) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_26c7a380beb338f4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'In which Constitution of Pakistan, the Ministers were neither members of the parliament nor answerable to the Parliament?', '{"A":"1956 constitution","B":"1962 constitution","C":"1973 constitution","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The 1962 Constitution of Pakistan introduced a presidential system, where ministers were appointed by the president and were not members of the parliament.They were directly accountable to the president, not the legislature.The Constitution of 1962 was promulgated by President Ayub Khan on 1 March 1962 and finally came into effect on 8 June 1962.', 0, 0, 0, 1790967404040) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_833fac8781f06aed', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Who is set to become the second female judge of Supreme Court of Pakistan?', '{"A":"Tahira Safdar","B":"Ayesha Malik","C":"Musarrat Hilali","D":"Khalida Rashid Khan"}', 'C', NULL, 0, 0, 0, 1790967404040) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3409109088ee1ec6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'What document was firstly drafted to give pace to constitution making process?', '{"A":"Objective Resolution","B":"Independence Act","C":"Pakistan Act","D":"Representative Act"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Objectives Resolution was adopted by the Constituent Assembly of Pakistan on March 12, 1949. Prime Minister, Liaquat Ali Khan, had presented it in the assembly on March 7, 1949. Out of 75 members of the assembly, 21 voted for opposing it****Moved by liaqiat Ali khan on 7 March 1949Passed on 12 March 1949ND5-07-2023', 0, 0, 0, 1790967404040) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_54d700987dc17efb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Presidential form of government in Pakistan was introduced under the Constitution of ____?', '{"A":"1962","B":"1956","C":"1973","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Constitution of 1962 envisaged a Federal State with a Presidential form of government,with the National Assembly at the center and the Provincial Assemblies in the Provinces***The Constitution of 1962 was promulgated by President Ayub Khanon 1 March 1962 and finally came into effect on 8 June 1962.Urdu and Bengali Was The Official Language Ayoub Khan was made chief of martial law after this abrogationAyoub Khan enforced the new constitution on 8th June 1962Yahiya Khan abrogated the 1962 constitution and became CMLA', 0, 0, 0, 1790967404040) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_905d471e4bfe9eb2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'According to the Government of India Act of 1935, elections in the subcontinent were conducted in which year?', '{"A":"1935","B":"1936","C":"1937","D":"1938"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Government of India Act of 1935 was passed by the British Parliament in August 1935.But the elections were not conducted immediately.The act came into force in April 1937.The first elections under the act were held the same year.', 0, 0, 0, 1790967404040) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_866f70d30a7d1235', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'In the National assembly of Pakistan, minorities are allocated ______ seats?', '{"A":"Ten","B":"Twenty","C":"Eight","D":"Thirteen","E":"Thirty"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ProvinceGeneralWomenNon-MuslimsTotalPunjab1413310174Sindh611475KPK45954Balochistan16420Islamabad3-3 2666010336', 0, 0, 0, 1790967404040) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e9583996747d4ce7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Who suspended the 1973 Constitution in 1977?', '{"A":"Zulfikar Ali Bhutto","B":"General Muhammad Zia-ul-Haq","C":"Pervez Musharraf","D":"General Ayub Khan"}', 'B', NULL, 0, 0, 0, 1790967404040) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e5a15b49d5811c52', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Which article of the 1973 constitution provides hat no person shall be deprived of life or liberty save in accordance with law?', '{"A":"8","B":"9","C":"5","D":"4","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Article 9 of the Constitution of the Islamic Republic of Pakistan states, "No person shall be deprived of life or liberty save in accordance with law"The 24th Amendment reallocated National Assembly seats among federating units.It allowed election authorities to update constituency boundaries based on the provisional results of the 2017 Census.', 0, 0, 0, 1790967404071) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9f6d24d1c5984500', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'What was the old name of Lahore High Court?', '{"A":"Chief court of punjab","B":"Chief court of Pakistan","C":"High court of Pakistan","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Established on 21 March 1919.Number of position 60.Judge term length 62 years.There are 5 high courts in Pakistan.', 0, 0, 0, 1790967404071) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_edeab4e70689ffd4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Iftikhar Muhammad Chaudhry was restored as Chief Justice by the Supreme Court on _____?', '{"A":"20 July 2007","B":"20 July 2008","C":"20 July 2009","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation On 9 March 2007, Musharraf asked Chaudhry to resign, which he refused to do, and was suspended from office. The resultant civil disorder led to the Lawyers'' Movement, which succeeded in the restoration of Chaudhry as Chief Justice on 20 July 2007.', 0, 0, 0, 1790967404071) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ff7a712171f8c203', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Who drafted the constitution of 1973 in Pakistan?', '{"A":"Zulifqar Ali Bhutto","B":"Iskandar Ali Mirza","C":"Tikka Khan","D":"Yahiya Khan","E":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Constitution of 1973:Zulifqar Ali Bhutto introduced new constitution in Pakistan on August 14, 1973.According to 1973 constitution, both national assembly and senate elect president for Pakistan whereas the prime minister is selected by national assembly.Bicameral Legislature system was introduced for the first time in Pakistan in the constitution of 1973.According to this constitution, a candidate must be 25 to contest for the election of national assembly.', 0, 0, 0, 1790967404071) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8c3d3fc60e0fe06e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'What is the name of first woman Deputy chairperson of Senate of Pakistan?', '{"A":"Dr Noor Jahan Panezai","B":"Shamshad Akhtar","C":"Asifa Saleem","D":"None of these"}', 'A', NULL, 0, 0, 0, 1790967404071) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c599615b45339af0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Which of the following are not members of the Council of Common Interests according to the 1973 constitution?', '{"A":"Prime Minister","B":"Governors","C":"Chief Ministers of Provinces","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation According to the 1973 Constitution of Pakistan, the Council of Common Interests (CCI) comprises:The Prime Minister of Pakistan (as chairperson)The Chief Ministers of the provinces (Punjab, Sindh, Khyber Pakhtunkhwa, and Balochistan)The Governors of the provinces (as members)However, the Prime Minister is not a member of the CCI.', 0, 0, 0, 1790967404071) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6fe0d63a684729ac', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Which Amendment made in the constitution, on April 1974, defines the boundaries of Pakistan?', '{"A":"Second","B":"Third","C":"First","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The First Amendment to the Constitution of Pakistan, enacted on May 4, 1974, redefined Pakistan''s boundaries and eliminated references to East Pakistan.The amendment also redefined Pakistan''s federal and naval treaties.The First Amendment was introduced during the tenure of Zulfikar Ali Bhutto to protect against internal and external destabilization.', 0, 0, 0, 1790967404071) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6754afb66634918d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Article 58(2b) of constitution 1973 is about _____?', '{"A":"Power of President to dismiss Army Chief","B":"Power of President to dissolve Provincial Assemblies","C":"Power of President to dissolve National Assembly","D":"Power of President to dissolve Senate","E":"All of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation These powers included the right, expressed in sub-section 2(b) inserted into Article 58, to dissolve the National Assembly (but not the Senate) if, in his or her opinion, "a situation has arisen in which the Government of the Federation cannot be carried on in accordance with the provisions of the Constitution', 0, 0, 0, 1790967404071) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_89d2cc17fe190b05', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'When was Lahore High Court established?', '{"A":"1919","B":"1989","C":"1920","D":"1980"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Established on 21 March 1919.Number of position 60.Judge term length 62 years.There are 5 high courts in Pakistan.', 0, 0, 0, 1790967404098) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d4eeab61391aa0aa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Article ______ of Pakistan''s Constitution says that Islam should be the State Religion.', '{"A":"1","B":"2","C":"3","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Article 2 of the Constitution says that Islam shall be the State Religion of Pakistan. Additional information:Article 3 of the Constitution of Malaysia 1957 declares that Islam is a religion of the federationArticle 12 of the Constitution says that:the official religion is Islam and the twelve Jaffrey Schools in Asul-al-Din and Fiqh will remain eternally immutable.', 0, 0, 0, 1790967404098) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f0eb7a20383e0cab', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', '1962 constitution of Pakistan lasted for how many years?', '{"A":"5 years","B":"7 years","C":"9 years","D":"11 years"}', 'B', NULL, 0, 0, 0, 1790967404098) ON CONFLICT(id) DO NOTHING;
