INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7d7a9ac8a4d92690', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Article of Constitution which gives Supreme Court Suo moto power?', '{"A":"Article 144 (3)","B":"Article 164 (3)","C":"Article 184 (3)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Article 184 (3) directly empowers the judiciary to enforce Fundamental Rights.Suo moto means an Action initiated By Court Itself', 0, 0, 0, 1790967404098) ON CONFLICT(id) DO NOTHING;
