INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c2f584e1a9594b09', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'Allama Muhammad Iqbal delivered his famous Allahabad Address in?', '{"A":"29 December 1928","B":"29 December 1929","C":"29 December 1930","D":"29 December 1945"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Delivered Presidential Address at 25th All-India Muslim League session, Allahabad, 29 December 1930.Allama Iqbal (1877–1938) is the National Poet of Pakistan.Joined Muslim League: 1908 in London, 1922 in Indian subcontinent.Additional information:Born: 9 November 1877, SialkotDied: 21 April 1938, LahoreBurial: Tomb of Allama Iqbal, LahoreKnown as “Mufakkir-e-Pakistan” (Thinker of Pakistan) and “Shair-e-Mashriq” (Poet of the East).Last verified 09-03-2026', 0, 0, 0, 1790967404312) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_339196b42e9e0b74', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'Heer Ranjha was written by whom?', '{"A":"Waris Shah","B":"Sultan Bahu","C":"Bullay Shah","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Author: Waris ShahWritten in: 1766Language: PunjabiGenre: Epic poetry / RomanceOrigin Date: Late 15th century (traditionally)Related: Mirza Sahiban, Sohni Mahiwal, Sassui PunnhunLast updated by NS on 06-09-2026​', 0, 0, 0, 1790967404312) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_50a5b3de855c423f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'Who wrote the book Hayat-e-Muhammad?', '{"A":"Muhammad Husain Haykal","B":"Shibli Nomani","C":"Syed Sulaiman Nadvi","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hayat-e-Muhammad was written by Muhammad Husain Haykal.The book is a famous biography (Seerah) of Prophet Muhammad (ﷺ).It was originally written in Arabic.Additional information:Sirat-un-Nabi → Shibli Nomani (completed by Syed Sulaiman Nadvi)Ar-Raheeq Al-Makhtum (The Sealed Nectar) → Safi-ur-Rahman MubarakpuriMuhammad: His Life Based on the Earliest Sources → Martin LingsThe Life of Muhammad → Ibn Ishaq (preserved and edited by Ibn Hisham)Verified & Updated', 0, 0, 0, 1790967404312) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8ebd3073f2e274e0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'The book Hayat-i-Afghani was primarily written about?', '{"A":"The Mughal Empire","B":"The Pashtun tribes and Afghanistan","C":"The Delhi Sultanate","D":"The Ottoman Empire"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hayat-i-Afghani, authored by Muhammad Hayat KhanIt is a historical and genealogical study of Pashtun tribes and the geography of Afghanistan Published in 1867Last question by NA on 09 July 2026', 0, 0, 0, 1790967404312) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d1adc94a13eb4bf1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'Hayat e javeed is written by?', '{"A":"Mirza ghalib","B":"Sir syed","C":"Altaf Hussain Hali","D":"Iqbal"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hayate-e-Javed is written by Altaf Hussain Hali about Sir Sayyid Ahmad Khan. He got it published twice- first in 1901 and then in 1903.', 0, 0, 0, 1790967404312) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_83e146c4b2b8e039', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'The Nehru Report was published in _____?', '{"A":"August 1928","B":"September 1928","C":"October 1928","D":"November 1928"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Published: 28 August 1928Place: Lucknow ConferenceChairman: Motilal NehruMember: Jawaharlal NehruMain Demand: Dominion status & federal system for IndiaMuslim League Response: Muhammad Ali Jinnah rejected it and presented his 14 Points.Last verified on 10-06-2026', 0, 0, 0, 1790967404312) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d699a05e0b4bb927', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'Who was the first Punjabi poet?', '{"A":"Shah Hussain","B":"Waris Shah","C":"Bulle Shah","D":"Baba Fareed"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Baba Farid is considered the first Punjabi poet.He was born in 1173 and died on 7 May 1266.His birthplace is Kothewal village near Multan.He spread Sufi teachings through poetry and songs.His shrine is located in Pakpattan, Pakistan.Additional information:Hazrat Hassan ibn Sabit (R.A): First poet of IslamAllama Iqbal: National Poet of Pakistan, called “Poet of the East”Amir Kror Suri: First poet of Pashto languageLast verified on 01-04-2026', 0, 0, 0, 1790967404312) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b8bce12a5c4c7898', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'Who is known as the Poet of East?', '{"A":"Allama Iqbal","B":"Hali","C":"Ghalib","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Allama Muhammad Iqbal is known as the Poet of the East (Shair-e-Mashriq).He is regarded as the National Poet of Pakistan.Additional information:Born: 9 November 1877, SialkotFather: Sheikh Noor MuhammadMother: Imam BibiPhD: Ludwig Maximilian University, Munich, Germany (1908)Died: 21 April 1938Burial Place: Badshahi Mosque, LahoreLast verified on 10-07-2026', 0, 0, 0, 1790967404343) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_cbc0e39c69b3cb05', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', '“My brother” book was written by?', '{"A":"Gulbadam Bagum","B":"Fatima Jinnah","C":"Hajra Masroor","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "My Brother" was written by Fatima Jinnah.The book is about the life and personality of her brother, Muhammad Ali Jinnah.It provides personal memories and insights into Quaid-e-Azam''s struggle for Pakistan.Language: EnglishPublisher: Quaid-i-Azam AcademyPublication: 1987Additional information:Fatima Jinnah was popularly known as Madar-e-Millat (Mother of the Nation).Last verified on 09-07-2026', 0, 0, 0, 1790967404343) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_868013c2f8dc6b95', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'The book "Friends not Masters" was written by?', '{"A":"Sir Syed Ahmed Khan","B":"Liaquat Ali Khan","C":"Zulfiqar Ali Bhutto","D":"General Ayoub Khan"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Author: Muhammad Ayub KhanYear: 1967Subject: Foreign policy of PakistanPosition of author: President of Pakistan (1958–1969)Type: Political / Autobiographical workLast verified on 02-04-2026', 0, 0, 0, 1790967404343) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7eb7e42942519aed', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'Daughter of East was written by?', '{"A":"Fatima Jinnah","B":"Benazir Bhutto","C":"Ghanwa Bhutto","D":"Begum Raina Liaqat Ali Khan"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Author: Benazir BhuttoBook Type: AutobiographyPublished: 7th January 1989Publisher: Simon & SchusterTheme: Politics, struggle, democracyAdditional information:Benazir Bhutto was the first female Prime Minister of Pakistan.She served two non-consecutive terms: 1988–1990 and 1993–1996.Last verified on 20-06-2026', 0, 0, 0, 1790967404343) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ad3a445445de07ed', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'The book "Great Tragedy" was written by?', '{"A":"Safdar Mehmood","B":"G.Allance","C":"Ameer Ali","D":"Z.A Bhutto"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The book "The Great Tragedy" was written by Zulfikar Ali Bhutto (Z.A. Bhutto).Published: 1971Topic: 1971 political crisis / East Pakistan separationLanguage: EnglishLast verified on 10-06-2026', 0, 0, 0, 1790967404343) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_637e5d88ff1ac470', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'Hayat-e-Javed is written by Altaf Hussain Hali about _____?', '{"A":"Agha Khan","B":"Muhammad Ali Jinnah","C":"Allama Iqbal","D":"Sir Sayyid Ahmad Khan"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hayat-e-Javed is a biography written by Altaf Hussain Hali.It is about the life of Sir Syed Ahmad Khan.The book highlights his reforms and educational services.It was first published in 1902.Last verified on 06-06-2026', 0, 0, 0, 1790967404343) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_14a7eb8c949d6daa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'Which Pakistani poet got Lenin prize in 1962?', '{"A":"Faiz Ahamad Faiz","B":"Ahmad Faraz","C":"Wasif Ali Wasif","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Faiz Ahmed Faiz was the first Asian poet to receive the Lenin Peace Prize.He was awarded in 1962 by the Soviet Union for his contributions to literature and peace.He was also nominated for the Nobel Prize in Literature.He wrote extensively in Urdu and Punjabi.Born: February 13, 1911, Narowal, PakistanDied: November 20, 1984, Lahore, PakistanLast verified on 01-04-2026', 0, 0, 0, 1790967404343) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_44119e750d70dcc7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'Who wrote Asar-ul-Sanadid in 1847?', '{"A":"Mirza Galib","B":"Sir Syed Ahmad Khan","C":"Allama Iqbal","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Asar-ul-Sanadeed: A historical and architectural account of Delhi by Sir Syed Ahmad Khan.First edition published in 1847.Second edition published in 1854.Last verified on 01-05-2026', 0, 0, 0, 1790967404343) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_90f2158a238959af', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', '"Shahnama" was written by _____?', '{"A":"Firdausi","B":"Al- Beruni","C":"Ameer Khusro","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Shahnama" is an epic poem that was written in 1010.It contains about 60,000 couplets.The author of "Shahnama" was Abu Al-Qasim Firdausi.The epic poem is also known as the "Book of Kings".Last verified on 30-03-2026', 0, 0, 0, 1790967404374) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d9654f6df4224b4c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'The Kashaf-ul-Mahjub was written by?', '{"A":"Maulana Altaf Hussain Hali","B":"Hazrat Data Gunj Buksh/Hazrat Ali Hajveri","C":"Maulana Zakaullah","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Author: Ali Hujwiri Also known as Data Ganj Bakhsh).Date: 11th century.Language: Persian.Topic: First major treatise on Sufism.Additional informationBirth: ~1009 AD (Ghazni)Death: 8 August 1072 (Lahore)Last updated 27-07-2026 by NA', 0, 0, 0, 1790967404374) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ca17a207dae10edb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'Kitab-ul-Umm was written by ______?', '{"A":"Imam Shafi","B":"Imam Hambal","C":"Imam Abu Hanifa","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kitab-ul-Umm was written by Imam Shafi’i, a renowned Islamic jurist.It is considered the first major book of Fiqh.The book explains Islamic laws and jurisprudence in detail.Its teachings form the basis of the Shafi’i school of thought.Published between 1903–1907 in printed form.Last verified on 01-04-2026', 0, 0, 0, 1790967404374) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2b62e320f265020a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'The book named "The spirit of Islam" is written by?', '{"A":"Syed Ameer Ali","B":"Nawab Mohsin","C":"Sir Syed Ahmad Khan","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Syed Ameer Ali authored "The Spirit of Islam".It was published in 1891.The book provides a comprehensive study of Islam''s core principles and beliefs.Last verified on 25-04-2026', 0, 0, 0, 1790967404374) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3e2328a083248c41', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'Iqbal Day is celebrated on _____?', '{"A":"24th January","B":"21st April","C":"9th November","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Allama IqbalBorn: November 9, 1877 (Sialkot)Father: Sheikh Noor MuhammadMother: Imam BibiReceived PhD: GermanyTitle: Poet of the EastFamous books: Bang-e-Dara, Zarb-i-Kalim, Armughan-e-HijazFamous Punjabi Books/Poem: Piyaara Jedi, Baba Bakri WalaDied: 21 April 1938Burial: Badshahi Mosque in LahoreLast verified on 30-03-2026', 0, 0, 0, 1790967404374) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d2e927bd4fa76e3d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', '"Mast Tawakali" is a famous poet of _______?', '{"A":"Urdu Language","B":"Balochi language","C":"Pashto Language","D":"Saraiki Language"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mast Tawakali (1817–1892) was a prominent Sufi poet of Balochistan.He was dedicated to the poor and often opposed the oppressive feudal system.Contemporary of Khwaja Farid and Mian Muhammad Bakhsh, he also wrote resistance poetry against colonial powers.Last verified on 03-04-2026', 0, 0, 0, 1790967404374) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_66fb131da33a7479', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'Kitab-ul-Hind was written by _____?', '{"A":"Al Biruni","B":"Al Farabi","C":"Sir Syed Ahamd","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The author of Kitab-ul-Hind is Al-Biruni.Publisher: Anjuman Taraqqi Urdu (Hind), Delhi.Year of Publication: 1941.The language of Al-Biruni''s ''Kitab-ul-Hind'' is Arabic.Last verified on 02-04-2026', 0, 0, 0, 1790967404374) ON CONFLICT(id) DO NOTHING;
