INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a9eec161975c7099', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'Pakistan’s Foreign Policy, A Historical Analysis was written by:', '{"A":"Samuel Martin Burke","B":"Dr. Zafar Mahmood","C":"Hassan Askari Rizvi","D":"Agha Shahi","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan’s Foreign Policy, A Historical Analysis was written by Samuel Martin BurkeSamuel Martin Burke was a Pakistani writer and professor, died in 2010. ***************vu FIA CBT PAPER 15-12-2021MUG 10-12-2022', 0, 0, 0, 1790967404687) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_30792dbc9f0683f7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'Who is the writer of Tuzk-e-Babri?', '{"A":"Gulbadin Begum","B":"Kamran Mirza","C":"Zaheer-ud-din Babar","D":"Nasir-ud-din Muhammad"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tuzuk-i-Baburi is written by Babur.Babarnama is also known as Tuzuk-i-Baburi. Babur and Jahangir are the only two emperors of Mughal Empire who wrote their own biographies.', 0, 0, 0, 1790967404687) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ced94d408e6d73bd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'Armughan i Hijaz was written by ________?', '{"A":"Ahmed Fraz","B":"Allama Iqbal","C":"Abul Kalam Azad","D":"Mir Aman Delhvi","E":"Sir syed ahmed khan"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Armaghan-i-Hijaz was a philosophical poetry book of Allama Iqbal.Armaghan-i-Hijaz was originally published in Persian in 1938.', 0, 0, 0, 1790967404687) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_caadfb6a8719b0da', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'Who wrote the book "Making of Pakistan?', '{"A":"Naseem hizaji","B":"Ahmad fraz","C":"K K Aziz","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The book "Making of Pakistan" is written by Khursheed Kamal Aziz.written in the English Language.KK Aziz write this book in 1967.He wrote 44 valuable books on modern history of Indian be subcontinent*******VU CBT FIA PAPER 30-12-2021', 0, 0, 0, 1790967404687) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f1ab4360f74cda85', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'Ch Rahmat Ali published a leaflet "Now are Never .We to live or Perish forever issued on January 28,1933; from Cambridge with the objective .', '{"A":"To create a separate and independent Muslim state","B":"To grow the concept of Indianism","C":"To develop amity with the British as a Muslim community","D":"To work with other Indian communities for liberation of India"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The word was first introduced now or never in 1933 by Choudhry Rahmat Ali.The "Pakistan Declaration" titled Now or Never means Are We to Live or Perish Forever?In this pamphlet, the word Pakistan was used for the first time This pamphlet was derived from the two-nation theory of Muslim reformer Syed Ahmed Khanit was a pamphlet, referring to the names of the five northern regions of British India: PunjabAfghanistanKashmirSindhBaluchistan. (Pakistan)***', 0, 0, 0, 1790967404687) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2b0960dcbc77ed88', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'Fiaz Ahmad Faiz was', '{"A":"A poet","B":"A journalist","C":"An army personnel","D":"All the above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Faiz Ahmad Faiz is also the author of Urdu and Punjabi literature.He was the first Asian poet to be awarded the Lenin Peace Prize (1962) by the Soviet Union Born: February 13, 1911, NarowalDied: November 20, 1984, in LahoreAwards: Lenin Peace PrizeNishan-e-ImtiazNigar AwardsAvicenna Prize', 0, 0, 0, 1790967404687) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_71700f35a27b5c72', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'The poem Iblees Ki Majlis-e-Shura is written by:', '{"A":"Bahadur Shah Zafar","B":"Sir Syed Ahmed Khan","C":"Allama Iqbal","D":"Jinnah","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Iblees Ki Majlis-e-Shura" is an Urdu poem written by Muhammad Iqbal in 1935The poem is written as a meeting between: Iblees (the first of the Devils, or Satans in Islam) and his five advisers. ND13-5-2023', 0, 0, 0, 1790967404687) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3be327bfebdfe847', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'The Loyal Muhammadans of India was written by ______?', '{"A":"Sir Syed Ahmad Khan","B":"Syed Ameer Ali","C":"Allam Iqbal","D":"Ghalib"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Syed Ahmad bin Muttaqi Khan, commonly known as Sir Syed.He was an Indian Muslim pragmatist, Islamic reformist, and philosopher of nineteenth-century British India. He founded the Loyal Muhammadans of India newspaper.', 0, 0, 0, 1790967404687) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c18ec420a2691ad4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'Who is the Shakespeare of Urdu literature?', '{"A":"Agha Hashar Kashmiri","B":"Deputy Nazir Ahmed","C":"Hafeez Jhalandari","D":"Mirza Ghalib","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Agha Hashar Kashmiri is the Shakespeare of Urdu literature.He started to show interest in stage dramas and moved to Bombay at the age of 14Agha Hashar Kashmiri''s first play, Aftab-e-Muhabbat, was published in 1897Born: Muhammad Shah 3 April 1879 Banaras, IndiaDied: 1 April 1935 (aged 56) Lahore****Waris Shah called the Shakespeare of Punjabi literature.ND06-08-2023', 0, 0, 0, 1790967404720) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b1345073b09aa48b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'Which poet is called Romi of Kashmir?', '{"A":"Hashim Shah","B":"Syed Bulleh Shah","C":"Syed Waris Shah","D":"Mian Mohammad Bakhsh"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mian Mohammad Bakhsh is also called Romi of Kashmir. Mian Mohammad Bakhsh was a great sufi poet and scholar.', 0, 0, 0, 1790967404720) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ec8dac86fc69d6c8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'A famous book  Neither a Hawk nor a Dove is written by a Pakistani Politician. What is his name?', '{"A":"Khurshid Qasoori","B":"Gohar Ayub","C":"Dr Maliha Lodhi","D":"K.K Aziz"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Author Khurshid Mahmud KasuriLanguage EnglishGenre NonfictionPublisher Oxford University Press PakistanPublication date 2015Khurshid Mahmud Kasuri is a Pakistani politician and writer He served as the Minister of Foreign Affairs of Pakistan between November 2002 until November 2007.', 0, 0, 0, 1790967404720) ON CONFLICT(id) DO NOTHING;
