INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a208568bdcffcd1a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'The first general elections in Pakistan were held on?', '{"A":"December 7, 1970","B":"December 6, 1970","C":"December 5, 1970","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first general elections in Pakistan were held on 7 December 1970.Conducted under the Legal Framework Order (LFO) issued by General Yahya Khan.Seats Structure:Total seats: 313 seats in National AssemblyGeneral seats: 300 seatsEast Pakistan: 162 seatsWest Pakistan: 138 seatsReserved seats for women: 13 seatsEast Pakistan: 7 seatsWest Pakistan: 6 seatsMain Results:Sheikh Mujibur Rahman (Awami League)Seats won: 167Votes: 12,937,162Percentage: 39.20%Zulfikar Ali Bhutto (PPP)Seats won: 86Votes: 6,148,923Percentage: 18.63%Last verified on 21-06-2026', 0, 0, 0, 1790967404788) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e5767a549684d2a4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'Pakistan Air Force Day is celebrated on which date?', '{"A":"6th September","B":"7th September","C":"8th September","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan Air Force Day (PAF) is celebrated on 7 September every year.Due to honor the achievements and sacrifices of the PAF in the Indo-Pakistani War of 1965.It is observed one day after Defence Day.Additional information:6 September: Defence Day (commemorates Pakistan Army’s role in 1965 war)8 September: Navy Day (commemorates Pakistan Navy services)***', 0, 0, 0, 1790967404788) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8d93ca9a8f49de84', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'The war of 1971 between India and Pakistan lasted for how many days?', '{"A":"12","B":"13","C":"14","D":"15"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The 1971 India-Pakistan war lasted for 13 days.Duration: December 3 – December 16, 1971.Surrender: Over 90,000 Pakistani personnel surrendered.Outcome: Formation of the new nation of Bangladesh.Name: Celebrated as Vijay Diwas in India and Victory Day in Bangladesh.Last updated by NA on 22-April-2026', 0, 0, 0, 1790967404788) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_eaa6b055fea51383', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'Who was the first female Lieutenant General of Pakistan Army?', '{"A":"Nigar Johar","B":"Samina Shah","C":"Zareena Khan","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lieutenant General Nigar Johar became the first female Lieutenant General of the Pakistan Army.She was also appointed as the first female Surgeon General of the Pakistan Army.She was promoted from Major General to Lieutenant General.She hails from Panjpeer, District Swabi, Khyber Pakhtunkhwa (KPK).Last verified on 23-08-2026', 0, 0, 0, 1790967404788) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_086d67b6219cd727', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'Who was honored with Nishan-e-Haider for his bravery in 1965 Indo-Pak War?', '{"A":"Muhammad Sarwar","B":"Raja Aziz Bhatti","C":"Rsahid Minhas","D":"None of these"}', 'B', NULL, 0, 0, 0, 1790967404788) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_29c479604a6d2917', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'General Elections are held in Pakistan after every ______ years.', '{"A":"4","B":"3","C":"2","D":"5"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation General Elections are held after every 5 years.The first-ever general elections were held on 7th December 1970.Yahya Khan issued a Legal Framework Order for the first general elections.LeaderSheikh Mujibur RehmanZulfikar Ali BhuttoPartyALPPPSeats won167 86Popular vote12, 937, 1626, 148, 923Percentage39.20%18.63%', 0, 0, 0, 1790967404788) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_710d095b74e329c9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'Who was the first Commander-in-Chief of Pakistan Army?', '{"A":"Gen. George Murphy","B":"G.M. Ayub Khan","C":"Gen. Frank Meservy","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation First Commander-in-Chief: General Sir Frank Messervy (Aug 1947 – Feb 1948)Additional information:Second Commander-in-Chief: General Sir Douglas Gracey (Feb 1948 – Jan 1951)First Muslim Commander-in-Chief: General Muhammad Ayub Khan (1951)Last verified on 18-01-2026', 0, 0, 0, 1790967404788) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c78830f8990eb10e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'Which agreement led to the formal end of the 1971 War between India and Pakistan?', '{"A":"Tashkent Agreement","B":"Simla Agreement","C":"Geneva Agreement","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Simla Agreement was signed on 2 July 1972.It took place in Shimla, India.Signed between Zulfikar Ali Bhutto and Indira Gandhi.It aimed to resolve issues after the 1971 war.Both countries agreed to settle disputes through bilateral talks.Last verified on 29-04-2026', 0, 0, 0, 1790967404788) ON CONFLICT(id) DO NOTHING;
