INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_00cba237c5d76930', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'War of 1965 resulted in signing of?', '{"A":"Tashkent Pact","B":"Shimla Pact","C":"Lahore Pact","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Agreement Name: Tashkent Declaration / PactDate Signed: 10 January 1966Mediator: Soviet UnionLeaders:India: Lal Bahadur ShastriPakistan: Ayub KhanLocation: Tashkent, UzbekistanLast verified on 20-06-2026', 0, 0, 0, 1790967404816) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f138d3993be7b435', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'The first battle of Panipat was fought during in the year?', '{"A":"1528","B":"1526","C":"1525","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation First Battle of Panipat: 21 April 1526Fought Between: Babur Vs LodiWon by: BaburAdditional information:Second Battle of Panipat: November 5, 1556Fought Between: Hemu Vs AkbarWon by: AkbarThird Battle of Panipat: 14 January 1761Fought Between: Abdali Vs MarathasWon by: AbdaliLast verified on 20-06-2026', 0, 0, 0, 1790967404816) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c62b12e83f38d2a9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'Which state was attacked by India and occupied unlawfully on 11th September 1948?', '{"A":"State of Jammu and Kashmir","B":"State of Hyderabad Daccan","C":"State of Junagarh","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Annexation of Hyderabad took place in September 1948.India launched a military action called Operation Polo.The Hyderabad State was ruled by the Nizam.Hyderabad was founded in 1724 by Nizam-ul-Mulk Asaf Jah I.The ruler in 1948 was Mir Osman Ali Khan.Last verified on 30-04-2026', 0, 0, 0, 1790967404816) ON CONFLICT(id) DO NOTHING;
