INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_04bb4544b00f6b1c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'Indo-Pak war of 1965 lasted for how many days?', '{"A":"27 days","B":"17 days","C":"47 days","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation War year: 1965Duration: 17 days (Started-August and Ended-September)Countries involved: Pakistan and IndiaCeasefire: United Nations–brokeredPost-war agreement: Tashkent Declaration (1966)Additional information:Indo-Pak Wars:1947 – First Indo-Pak War (Kashmir)1965 – Second Indo-Pak War (17 days)1971 – Third Indo-Pak War (East Pakistan)1999 – Kargil ConflictLast verified on 18-01-2026', 0, 0, 0, 1790967404816) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b5eb4a3f65c9d699', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'The Movement for the Restoration of Democracy (MRD), was a political alliance in Pakistan founded by the political parties opposing the military government of _______?', '{"A":"General Yahya Khan","B":"General Ayub Khan","C":"Zia-ul-Haq","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Movement for the Restoration of Democracy (MRD)Type: Political alliance in PakistanFounded: 1981, to oppose General Muhammad Zia-ul-Haq’s military regimeLeader: Benazir Bhutto of Pakistan Peoples Party (PPP)Purpose: Restore democracy and challenge military dictatorshipLast verified on 08-02-2026', 0, 0, 0, 1790967404816) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_4d7611e793a90de7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'Third Battle of Panipat was fought in?', '{"A":"1761","B":"1764","C":"1763","D":"1765"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Third Battle of Panipat was fought on 14 January 1761.It took place at Panipat (near Delhi, India).The battle was between the Maratha Empire and Ahmad Shah Durrani’s Afghan forces.The Marathas were led by Sadashivrao Bhau.The result was a decisive victory for Ahmad Shah Durrani.Additional information:1st Battle: 1526 (Babur vs Ibrahim Lodhi)2nd Battle: 1556 (Akbar vs Hemu)Last verified on 01-05-2026', 0, 0, 0, 1790967404816) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_021f610868f2fda2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'An ordinance which had privileged by General Ayub Khan in 1959 was?', '{"A":"PRODA","B":"NRO","C":"EBDO","D":"LFO"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Elective Bodies Disqualification Order (EBDO) was introduced by Ayub Khan in August 1959.It aimed to disqualify politicians accused of corruption or misconduct.About 75 political leaders were affected.Disqualification period was 8 years (till 1966).It restricted many leaders from taking part in politics.Last verified on 01-05-2026', 0, 0, 0, 1790967404846) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a1926c5e9a18961b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'Battle of Plassey was fought in ______?', '{"A":"1674","B":"1666","C":"1757","D":"1707"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fought between: British East India Company (led by Robert Clive) vs. Nawab of Bengal (Siraj-ud-Daulah) and his French allies.The Battle of Plassey was fought on 23 June 1757.It established British dominance in India.Location: Palashi (Plassey), Bengal.Captured CalcuttaLast updated by NA on 25-April-2026', 0, 0, 0, 1790967404846) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d0d8629813cd4179', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'Who was the first Muslim C-in-C of Air Force?', '{"A":"Air Marshal Paery Cane","B":"Air marshal Asgher Khan","C":"Air marshal Zafar Khan","D":"Air marshal anwar khan","E":"None of them"}', 'B', NULL, 0, 0, 0, 1790967404846) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_912ff99ca4e8ea5d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'On July 9, 1948, Government of Pakistan issued for the very first time?', '{"A":"Coins","B":"Currency note","C":"Postal stamp","D":"100 rupee note"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan’s first coin was issued on 3rd January 1948.The First Postal Stamp of Pakistan was issued on 9th July 1948.Pakistan’s first currency note was issued on March 1, 1949.Last verified on 02-04-2026', 0, 0, 0, 1790967404846) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c4deeeda5ee1ae89', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'The Battle of Plassey was fought in 1757 between?', '{"A":"Aurangzaib and Marhatas","B":"Lord Clive and Nawab Siraj-ud-Daula","C":"Humayun and Sher Shah Suri","D":"Hindus and Muslims"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Battle of Plassey was fought on 23 June 1757.It took place at Plassey (Palashi) near the Hooghly River.The battle was between the British East India Company and Siraj-ud-Daulah.The British were led by Robert Clive.It marked the beginning of British control in India (Bengal).Last verified on 31-03-2026', 0, 0, 0, 1790967404846) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_bccf99ce64914aed', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'The Pakistan Navy Headquarters is located in ______?', '{"A":"Rawalpindi","B":"Islamabad","C":"Lahore","D":"Karachi"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Pakistan Navy is the naval branch of the Pakistan Armed Forces.Headquarters: IslamabadFounded: August 14, 1947Gifford James was the first C-in-C of the Pakistan Navy.Admiral Mohammad Siddique was the first Muslim C-in-C of the Pakistan Navy.The Chief of the Naval Staff, a four-star admiral, commands the navy.Last verified on 17-03-2026', 0, 0, 0, 1790967404846) ON CONFLICT(id) DO NOTHING;
