INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_df2a78c3b59bf4da', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_economy', 'Which are major seasons for agriculture crop in Pakistan?', '{"A":"Kharif & Barani","B":"Kharif & Rabi","C":"Barani & Rabi","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Rabi crops are agricultural crops that are sown in winter and harvested in the spring in Pakistan.There are two principal crop seasons in Pakistan namely “Kharif”, with sowing beginning in April and harvest between October and December and “Rabi” beginning in October-December and ending in April-May.', 0, 0, 0, 1790967405250) ON CONFLICT(id) DO NOTHING;
