INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_4e6eb5c1a2a10a47', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_economy', 'What do you understand by the term "Kerb in foreign currency dealings?', '{"A":"The exchange rate of currencies in the open market","B":"The exchange rate of currencies determined by the State Bank of Pakistan","C":"All sort of monetary dealings in foreigncurrencies within the stock exchange.","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kerb can represent both the unofficial stock market on which buying and selling operations are processed after marketplace closure, in addition to casual deals. As a standard rule, such operations are processed through brokers on the order of customers when, for some purpose or other, their orders could not be processed at the stock market.', 0, 0, 0, 1790967405250) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_bdf28d2990e5cba7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_economy', 'The main three sectors of economy of Pakistan are agricultural, industrial and ______ sectors.', '{"A":"Manufacturing","B":"Transport","C":"Services","D":"Export"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The main three sectors of economy of Pakistan are agricultural, industrial and services sectors.Textile is the largest export industry in PakistanAgriculture is the largest sector of economy of Pakistan.', 0, 0, 0, 1790967405277) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b357cc44b0d2b83e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_economy', 'The second major food crop of Pakistan is _____?', '{"A":"Cotton","B":"Rice","C":"Maize","D":"Wheat"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The most important crops are: wheatsugarcanecottonrice which together account for more than 75% of the value of total crop output.ND23-6-2023', 0, 0, 0, 1790967405277) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_0c4c8705dd58b80a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_economy', 'The picture on the back of 75 Rupee Pakistani Note is?', '{"A":"Markhor","B":"Deodar Tree","C":"Khojak Tunnel","D":"Both A & B","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation State Bank of Pakistan (SBP) unveiled the design of a commemorative note of Rs 75 to mark the nation''s diamond jubilee.', 0, 0, 0, 1790967405277) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_5359a51a67c095df', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_economy', 'Which is the second largest industry of Pakistan?', '{"A":"Sugar industry","B":"Food and beverage processing industry","C":"Auto Mobile Industry","D":"Cottage Industry"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The food and beverage processing industry is the 2nd largest industry of Pakistan after textiles, accounting for 27% of the value-added production and 16% of employment in the manufacturing sector.ND28-4-2023', 0, 0, 0, 1790967405277) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_13c8fde6b6dea83c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_economy', 'How many crop seasons are in Pakistan?', '{"A":"2","B":"3","C":"4","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan has two main crop seasons (Kharif and Rabi),Kharif Season (Summer)Timing: Sows April–June; harvests October–December [FAO].Crops: Rice, cotton, sugarcane, and maize [FAO].Rabi Season (Winter)Timing: Sows October–December; harvests April–May [FAO].Crops: Wheat, barley, gram, and mustard [FAO].Last updated 13 August 2026 by NA', 0, 0, 0, 1790967405277) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_16ea56020d34d7b6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_economy', 'The Picture on the back of 100 Rupee Pakistani Note?', '{"A":"K-2","B":"Quaid-e-Azam Residency","C":"Faisal Mosque","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first banknotes issued by the State Bank of Pakistan were released on the 1st of October 1948, i printed by Thomas De La Rue & Company.***The Picture on the back of the 100 Rupee Pakistani Note Quaid-e-Azam ResidencyThe Picture on the back of the 500 Rupee Pakistani Note Badshahi MosqueThe Picture on the back of the 10 Rupee Pakistani Note is Khyber PassThe Picture on the back of the 5000 Rupee Pakistani Note Faisal Mosque NA23-7-2023', 0, 0, 0, 1790967405277) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_5a0635f31a887a1b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_economy', 'Which one of the following is the largest sector of Pakistan’s economy?', '{"A":"Agriculture","B":"Banking","C":"Industry","D":"Manufacturing"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The main three sectors of economy of Pakistan are agricultural, industrial and services sectors.Textile is the largest export industry in PakistanAgriculture is the largest sector of economy of Pakistan.', 0, 0, 0, 1790967405277) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7c8478d236f4c1ef', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_economy', 'Government of Pakistan issues currency on the basis of:', '{"A":"Availability of gold in the country","B":"Demand for money in the country","C":"Availability of dollars in the country","D":"Tax collection"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Availability of gold in the countryUnder Article 24, the State Bank of Pakistan has the sole right to issue banknotes. The National Bank of Pakistan introduced the first urgent issue at face value of 5, 10, 100 rupees. It was printed by De La Rue & Company Great Britain and published between 1948 and 1960.', 0, 0, 0, 1790967405277) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b06d170499d339af', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_economy', 'Central bank''s rate of lending to commercial banks is called:', '{"A":"(a) Interest rate","B":"(b) Discount rate","C":"(c) Money rate","D":"(d) Control rate"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Discount rate', 0, 0, 0, 1790967405303) ON CONFLICT(id) DO NOTHING;
INSERT INTO subject (id, user_id, name, parent_id, total_mcqs, created_at) VALUES ('top_pks_intl', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'International Relations', 'top_pakistan_study', 56, 1790967405337) ON CONFLICT(id) DO UPDATE SET total_mcqs = 56;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_bdecf95c70712c97', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_intl', 'What is the primary purpose of the CPEC road?', '{"A":"To facilitate trade and connectivity","B":"To promote tourism","C":"To enhance military logistics","D":"To provide energy resources"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation CPEC: China–Pakistan Economic CorridorPurpose: Trade and connectivityConnects: Xinjiang (China) to Gwadar (PakistanFocus: Infrastructure & energyLaunched: 2015Part of: Belt and Road Initiative (BRI)Initial Investment: $46 billionLast updated NA on 10-09-2026', 0, 0, 0, 1790967405395) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6f42ff0578630eef', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_intl', 'What was the initial estimate of CPEC Project?', '{"A":"$ 46 billion","B":"$ 49 billion","C":"$ 48 billion","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The initial value of CPEC was about US$46 billion.The China–Pakistan Economic Corridor (CPEC) agreement was formally signed and launched in April 2015 during the visit of Xi Jinping to Pakistan.CPEC was initiated in mid-2013.It is a major network of energy, transport, and infrastructure projects connecting China''s Xinjiang with Gwadar.Last verified on 05-09-2026', 0, 0, 0, 1790967405395) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_489c57507ede6415', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_intl', 'In which agreement the ceasefire line in Kashmir was named Line of Control?', '{"A":"Simla Agreement","B":"Ceasefire Agreement","C":"Both A and B","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Line of Control (LoC) was established in 1949 after the Karachi Agreement.It was following the first Indo-Pak war over Kashmir.It was originally called the Ceasefire Line and renamed the LoC in the 1972 Simla Agreement.The LoC is approximately 740 km long.Last verified on 03-09-2026', 0, 0, 0, 1790967405395) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_494794fe2c4d9ce6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_intl', 'Pakistan has been elected as a non-permanent member of which UN body?', '{"A":"Security Council","B":"UNHCR","C":"UNICEF","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan has been elected as a non-permanent member of the United Nations Security Council (UNSC) for the 2025–2026 term.This marks the eighth time Pakistan has secured a seat on the 15-member council.It is responsible for maintaining international peace and security.Last verified on 05-08-2026', 0, 0, 0, 1790967405395) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_afd57119507fa1cc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_intl', 'When was the CPEC project officially launched after the agreement between China and Pakistan was signed?', '{"A":"20 June 2015","B":"20 June 2014","C":"20 April 2014","D":"20 April 2015"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Full Form: China–Pakistan Economic CorridorInitiated: 5 July 2013Formal Agreement & Launch: 20 April 2015Occasion: Visit of Chinese President Xi Jinping to PakistanInitial Investment: About US$46 billionPurpose: Development of energy, transport, and infrastructureLast verified on 06-07-2026', 0, 0, 0, 1790967405395) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_fb4b7bc0a6b2f1e0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_intl', 'CPEC is a part of which initiative?', '{"A":"Silk Road Project","B":"Belt and Road Initiative (BRI)","C":"South Asian Corridor","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation CPEC is part of China’s Belt and Road Initiative (BRI).CPEC connects Gwadar Port in Pakistan with Kashgar in China’s Xinjiang region.The project was initiated in 2013.It was formally launched in April 2015.Initial estimated investment was about $46 billion.Last verified on 09-05-2026', 0, 0, 0, 1790967405395) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_05e0c2ad180882e8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_intl', 'When Pakistan became a full member of the Shanghai Cooperation Organisation (SCO)?', '{"A":"1st June 2017","B":"5th June 2017","C":"7th June 2017","D":"9th June 2017"}', 'D', NULL, 0, 0, 0, 1790967405395) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_fbe64b526652731d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_intl', 'When did Pakistan become member of IMF?', '{"A":"1948","B":"1951","C":"1949","D":"1950"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan became a member of the IMF and the World Bank in 1950.WTO in 1995.Additional information:Founded: 22 July 1944Headquarters: Washington, D.C., USAMembers: 191 countriesPurpose: Financial stability, economic growth, and balance of payments supportFirst Managing Director: Camille GuttLast Verified on 13-01-2026', 0, 0, 0, 1790967405395) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a79af80c536da87b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_intl', 'Where is the headquarters of CPEC located?', '{"A":"Beijing, China","B":"Karachi, Pakistan","C":"Islamabad, Pakistan","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The headquarters of the China–Pakistan Economic Corridor (CPEC) is located in Islamabad, Pakistan.CPEC is a flagship project of China''s Belt and Road Initiative (BRI).Launched: 20 April 2015Partner Countries: Pakistan and ChinaConnects: Gwadar (Pakistan) to Kashgar (China)Main Purpose: Infrastructure development, energy projects, trade, and regional connectivityLast verified on 10-07-2026', 0, 0, 0, 1790967405431) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_db7dcace063d59ac', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_intl', 'CPEC stands for _____?', '{"A":"China Pakistan Economic Council","B":"China–Pakistan Economic Corridor","C":"China Pakistan Energy Corridor","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation CPEC stands for China–Pakistan Economic Corridor.It was agreement was formally signed and launched in April 20, 2015 during the visit of Xi Jinping to Pakistan.CPEC was initiated in mid-2013.It is a major network of energy, transport, and infrastructure projects connecting China''s Xinjiang with Gwadar.The initial value of CPEC was about US$46 billion.Last verified on 06-07-2026', 0, 0, 0, 1790967405431) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_47e4bb399e78cf6b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_intl', 'Pakistan joined SAARC in which year?', '{"A":"1985","B":"1984","C":"1983","D":"1987"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan joined SAARC in 1985.South Asian Association for Regional Cooperation (SAARC):Member Countries (8): Afghanistan, Bangladesh, Bhutan, India, Maldives, Nepal, Pakistan, Sri LankaFounded: 8 December 1985Headquarters: Kathmandu, NepalOfficial Language: EnglishPurpose: Promote regional cooperation, economic growth, and cultural exchange among South Asian nationsLast verified on 15-01-2026', 0, 0, 0, 1790967405431) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_fa38c439cdb1d7a8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_intl', 'Who was, at one time, called "Ambassador of Hindu-Muslim Unity"?', '{"A":"Nehru","B":"Quaid-e-Azam","C":"Abu ul Kalam Azad","D":"Gandhi"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Quaid-e-Azam Muhammad Ali Jinnah was given the title “Ambassador of Hindu-Muslim Unity”.This title was conferred by Sarojini Naidu, a prominent Indian political leader and poet.At that time, Jinnah was working for unity between Hindus and Muslims.Last verified on 13-01-2026', 0, 0, 0, 1790967405431) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_befd58c7bdf9af05', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_intl', 'In which year was OIC founded?', '{"A":"December 7, 1985","B":"4 April 1949","C":"September 25, 1969","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation OIC (Organization of Islamic Cooperation)Foundation Date: 25 September 1969Headquarters: Jeddah, Saudi ArabiaOfficial Languages: Arabic, English, FrenchTotal Members: 57 countriesFirst Summit: Rabat, MoroccoSignificance: Largest international organization after the UNLast verified on 20-06-2026', 0, 0, 0, 1790967405431) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e51c70405d5ee1f8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_intl', 'The China-Pakistan Economic Corridor (CPEC) is important for Pakistan because?', '{"A":"It improves infrastructure and energy projects","B":"It reduces Pakistan''s debt","C":"It promotes cultural exchange","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation CPEC stands for China-Pakistan Economic Corridor.Mission statement: Securing Energy Import and Trade Boost for China, Infrastructure Development for Pakistan.Established: 20 April 2015 Budget: $62 billionLast verified on 11-06-2026', 0, 0, 0, 1790967405431) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_191a35c85b4b2567', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_intl', 'CPEC is a ______?', '{"A":"Joint venture between China and India","B":"Joint venture between China and Iran","C":"Game changer / Economic connectivity","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The China-Pakistan Economic Corridor (CPEC) is widely described as a “game changer” for regional development.It enhances economic connectivity through roads, railways, energy projects, and Gwadar Port.Additional information:It connects Xinjiang (China) to Gwadar (Pakistan).It is a major infrastructure and energy project.CPEC started in mid-2013 (planning stage) and launched in 2015.It is a part of China’s Belt and Road Initiative (BRI).Estimated investment is about $46 billion (initial phase).Last verified on 08-06-2026', 0, 0, 0, 1790967405431) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_927485a1416c40f0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_intl', 'Taubat-un-Nusooh is written by?', '{"A":"Mirza Ghalib","B":"Allama Iqbal","C":"Deputy Nazir Ahmad","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Maulvi Nazir Ahmad Dehlvi, also known as Deputy Nazir Ahmad.Born: 1830, Rehar, IndiaDied: May 3, 1912, Delhi, IndiaNationality: IndianLast verified on 16-05-2026', 0, 0, 0, 1790967405431) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_5e9e6eb9548621b9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_intl', 'Pakistan and China have signed an agreement for ______ railway track in 2019.', '{"A":"ML-1","B":"ML","C":"MS-5","D":"Pak China Train"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan and China signed an agreement for the ML-1 railway track in 28 April 2019.The agreement aims to upgrade and reconstruct the existing Karachi-Lahore-Peshawar (ML-1) railway track.This project is part of the CPEC.Last verified on 11-05-2026', 0, 0, 0, 1790967405464) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d947488f786bb462', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_intl', 'Father of former US Secretary of State Madeleine Albright was also a member of UN Commission on India-Pakistan and author of the book “Danger in Kashmir”. What was his name?', '{"A":"Josef Albright","B":"Josef Korbel","C":"Owen Dixon","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Josef Korbel was the father of Madeleine Albright.He served in the UN Commission on India and Pakistan (UNIP).He also wrote the book Danger in Kashmir.Last verified on 01-05-2026', 0, 0, 0, 1790967405464) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_1009a4618dd66b61', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_intl', 'In ______ Pakistan and Iran signed an agreement for supply of 750 million cubic feet gas per day.', '{"A":"2005","B":"2009","C":"2008","D":"2013"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan and Iran signed the gas supply agreement in 2009.The deal was part of the Iran-Pakistan (IP) Gas Pipeline Project.Under this agreement, Iran would supply 750 million cubic feet gas per day.The project aimed to overcome Pakistan’s energy crisis.It was a major step in regional energy cooperation.Last verified on 29-04-2026', 0, 0, 0, 1790967405464) ON CONFLICT(id) DO NOTHING;
