INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_59d78fdf2f7f3dfc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_symbols', 'Pakistan won the Hockey World Cup in 1994 against which team in the final?', '{"A":"Germany","B":"Netherlands","C":"Australia","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan defeated the Netherlands in the 1994 Hockey World Cup Final.The final was played on 5 December 1994 in Sydney, Australia.Pakistan won the match in a penalty shootout (4–3) after the game ended 1–1 in regular time.It was Pakistan''s 4th Hockey World Cup title.Additional information:First International Match: 2 August 1948 (vs Belgium, won 2–0)World Cup Titles (4): 1971, 1978, 1982, 1994Last verified on 26-07-2026', 0, 0, 0, 1790967405630) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_116b7f5e80df6059', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_symbols', 'Which flower is the National flower of Pakistan?', '{"A":"Rose","B":"Sunflower","C":"Lilly","D":"Jasmine"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jasmine (Chambeli) is the national flower of Pakistan.It was chosen as the national flower in 1961.Additional information:National Bird: ChukarNational Animal: MarkhorNational Dish: NihariNational Fruit: MangoNational Tree: DeodarNational Flower: JasmineNational Vegetable: Lady Finger (Okra)Last verified on 08-03-2026', 0, 0, 0, 1790967405630) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c0fe7b631d27d8cb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_symbols', 'When National Anthem was officially adopted/approved by the government?', '{"A":"11 August 1949","B":"12 August 1950","C":"14 August 1952","D":"16 August 1954"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Official Adoption: 16 August 1954Tune Composer: Ahmad G. Chagla (1949)Official Urdu lyrics were written by Hafeez Jalandhari (1952)Duration: About 80 secondsWords: 48 words, 15 linesFirst played on the radio: August 13, 1954Last updated NA on 10-09-2026', 0, 0, 0, 1790967405630) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_0fed70e6bc1bca04', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_symbols', 'The National Anthem of Pakistan for the first time was played on?', '{"A":"August 13th 1954","B":"August 11th 1954","C":"August 14th 1954","D":"August 12th 1954"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The national anthem of Pakistan was first played on August 13, 1954.The anthem was officially adopted on August 16, 1954The music for the national anthem was written by Ahmad G. Chagla in 1949.The Urdu lyrics were written by Hafeez Jalandhari in 1952Additional information March 1, 1950: The music without words was played for the first time by a Pakistan Navy band during the state visit of the Shah of Iran, Mohammad Reza Shah Pahlavi.Last updated question by NA on 12-JUNE-2026', 0, 0, 0, 1790967405630) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e0c27e08de36d257', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_symbols', 'National Flag of Pakistan was designed/made by _____?', '{"A":"Hafeez Jalandhri","B":"Ahmed Ghulam Ali Chaghla","C":"Amir Uddin Kidwai","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Designer: Amir Uddin Kidwai Adoption Date: 11 August 1947 (officially adopted) Additional information: Green field – represents Muslims of Pakistan White stripe – represents minorities and religious minorities’ rights Crescent and star – symbol of progress and light Proportion of flag: 2:3 (height:width)Last verified on 16-01-2026', 0, 0, 0, 1790967405630) ON CONFLICT(id) DO NOTHING;
