INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7101fa05dc8f6086', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_symbols', 'Pakistan Men''s Hockey Team has won the Asian Games gold medal _____ times.', '{"A":"8","B":"4","C":"6","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan men''s national field hockey team has won the Asian Games gold medal eight times: 1958, 1962, 1970, 1974, 1978, 1982, 1990, and 2010.Pakistan is the only Asian team to win the Champions Trophy three times (1978 and 1980).The team has won three Olympic gold medals, Pakistan with their first in 1960, defeating India in the final.', 0, 0, 0, 1790967405646) ON CONFLICT(id) DO NOTHING;
