INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_57d0b606e9ef1393', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_symbols', 'Urdu was declared the national language of Pakistan in which year?', '{"A":"August 1947","B":"April 1954","C":"April 1956","D":"April 1958"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ConfusionUrdu is the national language of Pakistan since 14 August 1947.In 1954 Urdu and Bengali were declared the national language of Pakistan. The 1973 Constitution recognizes Urdu as Pakistan’s only national language. ****Urdu declared as official language In subcontinent in 1832', 0, 0, 0, 1790967405723) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_416b3a5bd47071e5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_symbols', 'What is the National Dish of Pakistan?', '{"A":"Halwa poori","B":"Ground met fish","C":"Nihari","D":"Khaddii kabab"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation . Nihari is Pakistan''s national dish and a favorite of people from all walks of life. It originated from the Urdu-speaking community, which brought the food to the Indian subcontinent.', 0, 0, 0, 1790967405723) ON CONFLICT(id) DO NOTHING;
