INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_283ef7a12de5815c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'One of the following is the crucial to the ecosystem because they cycle nutrient form the organism back to environment :', '{"A":"Omnivores","B":"Carnivores","C":"Top carnivores","D":"Decomposers"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Decomposers are organisms that break down dead or decaying organisms; they carry out decomposition, a process possible by only certain kingdoms, such as fungi.', 0, 0, 0, 1790968056230) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fd8e3e68a076663a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Paris Pact ended with _______.', '{"A":"WW2","B":"WW1","C":"War of independence","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Location: Paris, FranceDrafted: 30 November – 12 December 2015 Treaty on climate change. Paris Peace Treaty-1947: Agreement that ended WW-2 in 1945.', 0, 0, 0, 1790968056230) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1d47a91a1992dbff', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Total number of small and large bones in human body are ___ .', '{"A":"206","B":"205","C":"208","D":"209","E":"300"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The femur is the longest bone in the human body and the shortest bone is the stapes found in the middle ear. New born child has 300 bones.*****', 0, 0, 0, 1790968056230) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7f56f46add228b31', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Healing of wounds is hastened by?', '{"A":"Vitamin C","B":"Vitamin K","C":"Vitamin A","D":"Vitamin K"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Vitamin C, commonly known as ascorbic acid (AA). The primary function of vitamin C in wound healing is to facilitate the synthesis of collagen, The most abundant protein in connective tissue.', 0, 0, 0, 1790968056230) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4eb972876964de96', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Less dew is formed on cloudy nights because of', '{"A":"in cloudy nights the radiation takes place very slowly","B":"In cloudy nights the radiation takes place very quickly","C":"clouds scatter moisture","D":"clouds absorbs the falling dew"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Radiation is very slow on cloudy nights, resulting in less condensation on cloudy nights. On cloudy nights, the clouds are thick and trap heat and water vapor in the clouds, resulting in very slow radiation. This all shows why dew levels drop on cloudy nights.', 0, 0, 0, 1790968056230) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e4580592da9f1383', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What are the health benefits of oral contraception?', '{"A":"Reduction of severity of menstrual cramps","B":"Cleaning up acne and improving bone density","C":"Prevention of certain cancers","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Oral contraceptives can have some health benefits. They may reduce: the severity of menstrual cramps improve acne protect against iron deficiency anemia and increase bone density***Monophasic pills are the most common oral contraceptive***ND1-2-2023', 0, 0, 0, 1790968056230) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_703b1329e202f7ab', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Besides incorrect use, what is another reason that condoms may not be effective?', '{"A":"They can break during intercourse","B":"Most men buy the incorrect size","C":"They do not contain enough spermicide","D":"people lie about using them"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Using condoms the right way can help prevent pregnancy and lower the risk of getting a sexually transmitted infection (STI).the disadvantages of using a condom:May disrupt spontaneity during sex.Can reduce sensitivity.Some men cannot maintain an erection when using a condom.Some men and women can develop an allergy or sensitivity to latex***ND1-2-2023', 0, 0, 0, 1790968056230) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a9190921ce7833a8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Population is a group of:', '{"A":"Individuals in a species","B":"Species in a community","C":"Individuals in a family","D":"communities in an ecosystem","E":"none of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A group of organisms of one species occupying a defined area is termed a population. In nature, we rarely find isolated, single individuals of any species.The total number of people living in an area, city, country, or the world at a specific time is called Population. ***ND1-2-2023', 0, 0, 0, 1790968056230) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_52cd01e24c924c0e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What is the most common cause of death in Diarrhea?', '{"A":"Abdominal pain","B":"Lethargy","C":"Vomiting","D":"Dehydration","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Diarrhoeal disease is the second leading cause of death in children under five years old.In the past, for most children, severe dehydration and fluid loss were the main causes of death from diarrhea. Now, other causes such as septic bacterial infections are an increasing proportion of all diarrhea-associated deaths.***ND1-2-2023', 0, 0, 0, 1790968056265) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fb989148ddfd8ce8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'If the number of people living in Country X are 50 then the population density of country X is', '{"A":"45","B":"48","C":"50","D":"60","E":"25"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To calculate the population density, you will divide the population by the size of the area. formula: Population Density = Number of People/Land Area. The unit of land area should be square miles or square kilometers.***ND1-2-2023', 0, 0, 0, 1790968056265) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1f09c4ccbde619c8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Anything that can be used to earn a living is called:', '{"A":"Outcome","B":"Reservoir","C":"Resource","D":"None of these","E":"All of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Resource means وسیلہ، ذریعہA resource is a physical material that humans need and value such as land, air, and water. Resources are characterized as renewable or nonrenewable; a renewable: resource can replenish itself at the rate it is used, while a nonrenewable: resource has a limited supply.***ND1-2-2023', 0, 0, 0, 1790968056265) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c6c32de886f67b00', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What is the global recommendation for the period for breast-feeding of baby?', '{"A":"At least one year","B":"Two years or longer","C":"As long as possible","D":"Until the mother milk dries up","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation breastfeeding is important for the baby because Breastfed babies are healthierthe World Health Organization also recommends exclusive breastfeeding for about the first 6 months for up to 2 years of age or longer.World Breastfeeding Week first observed in 1991.World breastfeeding week: 1st to the 7th of August annually Theme 2022: Step Up for Breastfeeding: Educate and Support***ND1-2-2023', 0, 0, 0, 1790968056265) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9d3c1e8ae8acc8f3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Why is breastfeeding important for the baby?', '{"A":"I do not believe it is different from formula feeding","B":"Formula feeding allows the father of baby to be more involved","C":"Breastfed babies are healthier","D":"Breastfed babies remain closer to their mothers throughout their lives"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation breastfeeding is important for the baby because Breastfed babies are healthierIt protects against allergies, sickness, and obesity. It protects against diseases, like diabetes and cancer. the World Health Organization also recommends exclusive breastfeeding for about the first 6 months for up to 2 years of age or longer.World Breastfeeding Week first observed in 1991.World breastfeeding week: 1st to the 7th of August annually Theme 2022: Step Up for Breastfeeding: Educate and Support***ND1-2-2023', 0, 0, 0, 1790968056265) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6e42120bd2dbc07a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The population which does not get necessary food, is classified as:', '{"A":"Over nourished population","B":"Under fed population","C":"well-fed population","D":"undernourished population"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Undernourishment: the proportion of undernourished people as a percentage of the population (reflecting the share of the population with insufficient caloric intake)***The term malnutrition addresses 3 broad groups of conditions: undernutrition, which includes wasting (low weight for height) stunting (low height-for-age) and underweight (low weight-for-age)***ND1-2-2023', 0, 0, 0, 1790968056265) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_eec359d2a330e09b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The best method for preventing the problem of prevalence of acute diarrhea is:', '{"A":"Use of boiled water","B":"Provision of sanitary latrine","C":"Anti-diarrhea drugs","D":"immunization against cholera & typhoid","E":"all of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Acute diarrhea is defined as three or more loose or watery stools per dayThe most common causes of acute and persistent diarrhea are: infectionstravelers'' diarrhea and side effects of medicines.**Key measures to prevent diarrhea include:access to safe drinking water;use of improved sanitation;hand washing with soap***ND1-2-2023', 0, 0, 0, 1790968056265) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_12764c5c3fdc3c2e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The number of people/square kilometer of land is classified as:', '{"A":"Housing density","B":"Population density","C":"Society density","D":"Population intensity","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The number of individuals living within that specific location determines the population densityPopulation density is a measurement of population per unit of land area.It is mostly applied to humans, but sometimes to other living organisms tooPopulation density can be used to describe the location growthand migration of many organisms***ND1-2-2023', 0, 0, 0, 1790968056265) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b61ecf25a0b3b25e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The clinic nurse who guides client''s development in effective problem solving and decision making begins by:', '{"A":"Identifying health goals and behavior change options","B":"Emphasizing teaching self-care activities","C":"Health history, health risk assessment, and health beliefs review","D":"Asking the client to re-order priorities"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An occupational health nurse is responsible for offering: health promotion education classes and blood pressure and cholesterol screenings for the employees and their families.**The nursing process functions as a systematic guide to client-centered care with 5 sequential steps. These are assessment, diagnosis, planning, implementation, and evaluation.***ND1-2-2023', 0, 0, 0, 1790968056304) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cf6064da6f433eea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Who invented Jet Engine______?', '{"A":"Lewis E. Waterman","B":"Gottlieb Daimler","C":"Roger Bacon","D":"Sir Frank Whittle","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Air Commodore Sir Frank Whittle, was an English Royal Air Force air officer. He is credited with inventing the turbojet engine. A patent was submitted by Maxime Guillaume in 1921 for a similar invention; however, this was technically unfeasible at the time.RY30012023', 0, 0, 0, 1790968056304) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_259e9149ccbb9415', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Who is credited for discovery of Planetry motion___?', '{"A":"Nicolaus Copernicus","B":"Kepler","C":"Darwan","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Johannes Kepler published his first two laws about planetary motion in 1609, having found them by analyzing the astronomical observations of Tycho Brahe. Kepler''s third law was published in 1619.******RY 15-01-2023', 0, 0, 0, 1790968056304) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3fe6bde0b946a89f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'I intend to visit my grandparents _____ this weekend.', '{"A":"In","B":"On","C":"During","D":"By","E":"For"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We use Preposition During to say when something happens.During this year, During this weekend, During this decade etc.', 0, 0, 0, 1790968056304) ON CONFLICT(id) DO NOTHING;
