INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fc1430ab4af6934f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The pancreas secretes:', '{"A":"Insulin","B":"Bile Juice","C":"Vitamin A","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation the endocrine gland in the pancreas are insulin and glucagonThe pancreas secretes hormones, including: the blood sugar-regulating hormones: insulin and glucagonThe pancreas secrets pancreatic juice which breakdown the: Proteins and sugars***ND16-12-2022', 0, 0, 0, 1790968056304) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_96d07ec124f00223', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following will you use to remove rust stains on cloth?', '{"A":"Alcohol","B":"Oxalic Acid Solution","C":"Kerosene oil","D":"none of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Oxalic acid is used in removing ink stain from clothes as it is helpful in the reaction of insoluble iron to the soluble complex ion.MUG 11-12-2022', 0, 0, 0, 1790968056304) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_87b9972c6284b639', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What are Vaccines?', '{"A":"Same as monoclonal antibodies","B":"MHC proteins","C":"Treated bacteria or virus or one of their proteins","D":"Sounds of nuclacic acids"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Vaccines are made from:Weakened or killed bacteria or virusesSmall pieces of bacteria or viruses, like proteins or sugarsGenetic material (DNA or RNA) from bacteria or virusesThese components stimulate an immune response, helping the body build immunity against specific diseases.', 0, 0, 0, 1790968056304) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4b1bc5fa396a1390', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Lungs of birds consist of:', '{"A":"Alveoli","B":"Parabronchi","C":"Both","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In birds, gas exchange occurs in the lungs as air moves through small tubes (parabronchi) in one direction; in mammals, air flows tidally into and out of the alveoli.', 0, 0, 0, 1790968056338) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_489c513196d0019b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Animals and plants bodies are made up of more or less than ___ of water?', '{"A":"50%","B":"60%","C":"70%","D":"90%"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Both plant and animal cells are eukaryotic.Animal cells have centrosomes , whereas Plant cells have a cell wall.', 0, 0, 0, 1790968056338) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_eca96aaba5d4c794', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The part of body that is directly affected by Pneumonia?', '{"A":"Circulatory system","B":"Respiratory system","C":"Digestive system","D":"Excretory system"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pneumonia is an infection that inflames the air sacs in one or both lungs. The air sacs may fill with fluid or pus (purulent material), causing cough with phlegm or pus, fever, chills, and difficulty breathing.', 0, 0, 0, 1790968056338) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_eac4c24f939899ca', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Retina in the eyes acts as a____ in the camera.', '{"A":"Film","B":"Lens","C":"Shutter","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The film of the Camera is analog to the retina in the human eye ****The retina is a thin membrane that covers the internal lower back of the attention. Like film in a camera, the retina is the light-touchy surface in which photos from the outdoor international come to a focus.***The retina gets those photographs with thousands and thousands of microscopic photoreceptor cells called rods and cones. The retina includes two regions known as the macula and the fovea.', 0, 0, 0, 1790968056338) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_29c56b6575929573', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Flowers of monocots have ___ floral parts.', '{"A":"2","B":"3","C":"4","D":"5"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Flowers of monocots have three floral partsSepalsPetalsStamens', 0, 0, 0, 1790968056338) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1d7cc4dd45371f81', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'An activity related to earthquake is:', '{"A":"Seismic activity","B":"Hormonal activity","C":"Geographical activity","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A sudden violent shaking of the ground, typically causing great destruction, as a result of movements within the earth''s crust or volcanic action.', 0, 0, 0, 1790968056338) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7f1b6b4a10781403', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Malfunctioning of which of the following organs causes jaundice ?', '{"A":"Liver","B":"Lungs","C":"Kidneys","D":"Heart","E":"Brain"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Malfunctioning of liver causes jaundice.جون ڈس جگر کی ایک بیماری ہے جس کی وجہ سے مریض کی جلد پیلی ہوجاتی ہے۔', 0, 0, 0, 1790968056338) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_02a0171ea0c771d2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The word LEAVES is a/an:', '{"A":"Proper noun","B":"singular noun","C":"abstract noun","D":"plural noun"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Singular noun: Leave Plural noun: Leaves Leave means پتہ', 0, 0, 0, 1790968056338) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d40b0b9e3ad075fb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Green color of plants leaves is due to ۔', '{"A":"Sun","B":"Water","C":"Chlorophyll","D":"All"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Chlorophyll is a green pigment found in the chloroplasts of plant cells and is essential for photosynthesisThe process by which plants convert light energy into chemical energy to produce sugars from carbon dioxide and water. Chlorophyll absorbs light energy, particularly in the blue and red regions of the visible spectrum,While reflecting green light, giving leaves their characteristic green color. This absorption of light energy by chlorophyll initiates the process of photosynthesis, allowing plants to produce their own food.', 0, 0, 0, 1790968056369) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2ed529d1bc64562b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following is not a part of Darwinism?', '{"A":"Inheritance for acquired characters","B":"Natural selection","C":"Over production","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Darwinism is a theory of biological evolution developed by the English naturalist Charles DarwinDarwin''s theory of evolution, also called Darwinism, can be further divided into 5 parts: "evolution as such", common descent, gradualism, population speciation, and natural selection.***There are four principles at work in evolution—variation, inheritance, selection and time.ND11-07-2023', 0, 0, 0, 1790968056369) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_18dcd6d62f40b30f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Climate of area is calculated by?', '{"A":"temperature","B":"Water","C":"Both","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The two most important factors in the climate of an area are temperature and precipitation.', 0, 0, 0, 1790968056369) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4c5e991a977ba235', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Every living thing is made up mostly of:', '{"A":"Sand","B":"Air","C":"Water","D":"Atom"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Every living thing is made up mostly of water. Water is the most abundant substance in living organisms, making up approximately:- 55-60% of an adult human''s body weight- 70-80% of a plant''s weight- 70-90% of an animal''s weightWater is essential for many biological processes, including:- Regulating body temperature- Transporting nutrients and oxygen- Removing waste products- Maintaining cell shape and structureWater is truly the foundation of life!', 0, 0, 0, 1790968056369) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_478a4b1beb6c7d18', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Elements are classified into ___ classes?', '{"A":"8","B":"4","C":"3","D":"2"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Elements can be classified as metals, metalloids, and nonmetals.', 0, 0, 0, 1790968056369) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1c4007a489d9fe61', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The common ore of aluminum is', '{"A":"Cryolite","B":"Bauxite","C":"Chromite","D":"Monazite"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bauxite is the most common aluminum ore. Approximately 98% of primary aluminum production is based on bauxite', 0, 0, 0, 1790968056369) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_470b9656215c03ee', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Ball bearings are used to reduce friction by:', '{"A":"Applying lubricant in the balls used","B":"Reducing the area of the contact with the use of metallic balls","C":"Increasing the area of contact with the use of metallic balls","D":"None of these","E":"All of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ball bearing reduces friction by using smooth balls lubricated with oil or grease that freely roll between a smooth inner and outer surface.SH5-8-2023ND06-08-2023', 0, 0, 0, 1790968056369) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b78b2f184bd6a17a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'In a refrigerator cooling is produced by', '{"A":"The ice that deposits on the freezer","B":"the evaporation of a volatile liquid","C":"Both of these","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Refrigerators are cooled through the evaporation of a volatile liquid that is, they use a liquid that evaporates very easily, and this evaporation creates a cooling effect.ND06-08-2023', 0, 0, 0, 1790968056369) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_861fd689860dbd2f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Conching of chocolate results in:', '{"A":"Improvement of flavour","B":"decline in viscosity","C":"Reduction of microorganisms","D":"colour development"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Conching is considered an important step for flavor development in chocolateThe conching results in reduces sweetness and an intense increase of harmonious and mellow taste and chocolate note.ND06-08-2023', 0, 0, 0, 1790968056402) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b07152a2194cd12e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Motion of planets follow _______ law.', '{"A":"Kepler law","B":"Hooke Law","C":"Newton Law","D":"None of these","E":"All of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kepler''s law explains the motions of planets in the solar system.Kepler''s Laws of Planetary MotionThey describe how: (1) planets move in elliptical orbits with the Sun as a focus(2) a planet covers the same area of space in the same amount of time no matter where it is in its orbit(3) a planet''s orbital period is proportional to the size of its orbit (its semi-major axis).ND06-08-2023', 0, 0, 0, 1790968056402) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bdc69a520c314a31', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The kingdom Protista includes:', '{"A":"Algae, Fungi, Virus, Bacteria","B":"Fungi, Protozoa, Bacteria","C":"Virus, Fungi Protozoa, Algae","D":"None of these","E":"All of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kingdom Protista includes all eukaryotes that are not animals, plants, or fungi.Kingdom Protista is very diverse. It consists of both single-celled and multicellular organisms.ND6-08-2023', 0, 0, 0, 1790968056402) ON CONFLICT(id) DO NOTHING;
