INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_38cc7e6c40013a82', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'A fan makes a hot noon to feel cool by', '{"A":"Letting in air cool","B":"regulating the airflow","C":"blowing out hot air","D":"increasing the rate of evaporation"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Answer:DFans help by replacing hot and humid air with cooler, dry air that allows for more evaporation. Cold air evaporates sweat and creates a wind-cooling effect that cools us without affecting room temperature.', 0, 0, 0, 1790968056669) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fa436ad4903f12bf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The internal antenna of a transistor set is made of', '{"A":"Copper","B":"iron","C":"Ferro-chrom","D":"Alnico"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Answer:cThe Ferro-chromite rod aerial antenna is a form of RF antenna that is almost universally used in portable transistor broadcast receivers as well as many hi-fi tuners where reception on the long, medium, and possibly the short wave bands is required.', 0, 0, 0, 1790968056669) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fed5bb2322bb5aed', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The dynamo converts?', '{"A":"Mechanical Energy into electrical energy","B":"Mechanical Energy into magnetic energy","C":"Electrical energy into Mechanical energy","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Answer:AThe feature of the dynamo is to alternate mechanical strength into electricity. The managed equipment related to the dynamo regulates the modern output in step with the needs of the electrical device and the country of the battery.', 0, 0, 0, 1790968056669) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_96f31e76cf0a6071', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which metal is commonly used as an electromagnet?', '{"A":"Nickel","B":"Copper","C":"Iron","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Answer: C The coil of the iron core is called an electromagnet. The iron core increases the magnetic field strength of the coil. Wrap a wire around an iron nail to make a simple electromagnet.', 0, 0, 0, 1790968056669) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dc32fcda1278809c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following diseases is characterized by inflammation of the membranes', '{"A":"Tonsilitis","B":"Hepatitis","C":"Pericarditis","D":"Meningitis"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Answer:DMeningitis is a clinical syndrome characterized by inflammation of the meninges i-e membranes', 0, 0, 0, 1790968056669) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bd5e37d9bb67d90a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The raw material used for the manufacture of Glass and Cement is?', '{"A":"Limestone","B":"Gypsum","C":"Washing soda","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Limestone (چونے کا پتھر) is a type of carbonate sedimentary rock.', 0, 0, 0, 1790968056669) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_04cf5e0c183270e0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Part of microscope which holds the slides is referred to as:', '{"A":"Course adjustment","B":"Arm","C":"Stage clip","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Stage clips hold the slides in place. If your microscope has a mechanical stage, the slide is controlled by turning two knobs instead of having to move it manually.', 0, 0, 0, 1790968056669) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5dc826ebe4d1adcf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Peanut butter is an example of a:', '{"A":"High viscosity liquid","B":"Low viscosity liquid","C":"Isnt a liquid at all! Don''t be silly","D":"All of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Peanut butter is a food paste or spread made from ground, dry-roasted peanuts.', 0, 0, 0, 1790968056707) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_de02fb5932d25b11', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'People living in high altitudes (like mountains) usually have a _________?', '{"A":"smaller number of Red Blood Cells","B":"larger number of Red Blood Cells","C":"smaller number of White Blood Cells","D":"larger number of White Blood Cells"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation More details about this question will be shared soon.', 0, 0, 0, 1790968056707) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_af811fa29c02969e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Permanent hardness of water cannot removed by', '{"A":"Adding caustic soda","B":"Distillation","C":"Addind soda","D":"Boiling"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Answer:DThe permanant hardness cannot be removed even if it is boiled. The permanent hardness of water can be removed by the gun''s palm tit method, ion exchange resin method, and cleaning soda method. This means that the permanent hardness of water cannot be removed with boiling water.', 0, 0, 0, 1790968056707) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_00f2610262ca42ce', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Permanent hardness of water, due to sulphates of the metal, can be destroyed by the use of:', '{"A":"Nitrates","B":"Zeolites","C":"Sulphonates","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Zeolites are microporous, aluminosilicate minerals commonly used as commercial adsorbents and catalysts.', 0, 0, 0, 1790968056707) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8569ccff91c094f4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Pile foundation is generally provided if soil is', '{"A":"Compressible","B":"Water Logged","C":"Made up","D":"All of the above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790968056707) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9530debf42b9f941', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Plaster of Paris is produced by heating:', '{"A":"Gypsum","B":"Zinc","C":"Graphite","D":"Sand"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Plaster of Paris is made by heating the mineral gypsum. When gypsum is heated to about 150°C it losses water and produces the powder of plaster of Paris.', 0, 0, 0, 1790968056707) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1668e54599fc6e45', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Pitch is the black residue of:', '{"A":"coal","B":"coal tar","C":"coke","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Coal tar is a thick dark liquid which is a by-product of the production of coke and coal gas from coal. It has both medical and industrial uses.', 0, 0, 0, 1790968056707) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e32d242f722ea885', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The substances are radioactive, which have:', '{"A":"Electrons in their nuclei","B":"Electrons removed from the outermost shell","C":"Unstable nuclei","D":"Nuclei with less number of neutrons"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Answer:Radionuclides (or radioactive substances) are a type of chemical substance whose atomic nucleus is unstable. They achieve stability through nuclear fission (spontaneous fission, emission of alpha particles, or conversion of neutrons to protons, or vice versa).', 0, 0, 0, 1790968056707) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_32e6b3fab434dc83', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Recent advances made in color Doppler M.R.I works on:', '{"A":"Electro-magnetic waves","B":"Infra-red radiation","C":"Sound waves","D":"Micro wave oscillation"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation MRI, and the detailed images it produces, has been a huge benefit for the study of the brain. Its greatest innovation is allowing us to see which parts of the brain have been damaged while a patient is still alive.', 0, 0, 0, 1790968056738) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_60e72bafaaad06c6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Reptiles are the example of:', '{"A":"Vertebrate","B":"Invertebrate","C":"Reptiles","D":"Amphibians"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A vertebrate is an animal with a spinal cord surrounded by cartilage or bone. Vertebrates include birds, fish, amphibians, reptiles, and mammals.', 0, 0, 0, 1790968056738) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c990147b605e1924', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which one of the following is a non-metallic mineral?', '{"A":"Manganese","B":"Magnesium","C":"Gypsum","D":"Bauxite"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation non-metallic minerals are: limestone mica gypsum coaldolomitephosphatesalt granite.****whileOres of iron, aluminum, gold, and silver are examples of metallic minerals. Diamond, slat, potash, etc.', 0, 0, 0, 1790968056738) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_da952be39285734a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Separation of water or water sand cement from a freshly concrete is known as', '{"A":"Bleeding","B":"Creeping","C":"Segregation","D":"Flooding"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Separation of water or sand or cement from freshly mixed concrete is known as: Segregation.18-Feb-2019', 0, 0, 0, 1790968056738) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c7c157bc0430ec28', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Short-sightedness is due to the ____?', '{"A":"Shifting of iris","B":"Elongation of eyeball","C":"Weakness of Retina","D":"Weaker muscles"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Short-sightedness is caused due to elongation of the eyeball It also may result when the curve of the cornea is too steep. The messages sent from the retina to the brain are perceived as blurry', 0, 0, 0, 1790968056738) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_415d728c05512f2a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Snake is a/an ___ and ____', '{"A":"Inveterate,reptile","B":"Inveterate,amphibian","C":"Vertebrate ,reptile","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Vertebrate is an animal of a large group distinguished by the possession of a backbone or spinal column, including mammals, birds, reptiles, amphibians, and fishes.', 0, 0, 0, 1790968056738) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2d895c1829c3ebf8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Slum test of concrete is a of its', '{"A":"Consistency","B":"Compressive strength","C":"Tensile strength","D":"Impact value"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790968056738) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f4ecb3f56e06b4b7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Sociologist employ primary perspectives?', '{"A":"Five","B":"Four","C":"Three","D":"Two"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sociologists today employ three primary theoretical perspectives: the symbolic interactionist perspective, the functionalist perspective, and the conflict perspective. These perspectives offer sociologists theoretical paradigms for explaining how society influences people, and vice versa.', 0, 0, 0, 1790968056738) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7591b9536242bbf6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Surge tanks are used', '{"A":"For storage of water","B":"To increase the velocity in a pipeline","C":"As over flow valves","D":"To guard against water hammers"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790968056771) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_04cf026e95f806dd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'That the earth rotating on its axis is established by fact that', '{"A":"Tha moon and stars move in the sky","B":"The earth experiences day and night","C":"The planetary winds are blowing","D":"The time in different parts of earth is not same"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The earth experiences day and night is the correct answer.', 0, 0, 0, 1790968056771) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_df9c7af84aa241d8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The beating of pulse is due to:', '{"A":"flow of water","B":"flow of blood","C":"energy","D":"none"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A normal resting heart rate should be between 60 to 100 beats per minute, but it can vary from minute to minute.', 0, 0, 0, 1790968056771) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b098b5d36a3f73d9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The boundary between the mantle and the core lies at a depth of approximately ________ .', '{"A":"3000 kilometers","B":"1000 kilometres","C":"300 kilometers","D":"400 kilometers"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The mantle–core boundary is the Gutenberg discontinuity at a depth of about 2,800 kilometres. The outer core is thought to be liquid because shear waves do not pass through it.', 0, 0, 0, 1790968056771) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b5b6f6ef29a0e110', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The capability of a soil mass of full width and depth to transmit water is known', '{"A":"Porosity","B":"Permeability","C":"Transmissibility","D":"None the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790968056771) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2c93a1b773c0c44c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The density of sea water is highest as', '{"A":"Depth decrease and salinity increase","B":"Depth increase and salinity increase","C":"Depth  increase and salinity decrease","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Answer: BThe density of sea water is highest as depth increase and salinity increase.', 0, 0, 0, 1790968056771) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d11f24ee44743cd4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The fundamental unit in S.I system are', '{"A":"Centimeter, gram, second","B":"Food, pound, second","C":"Meter, kilogram, second","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The fundamental units in the SI (International System of Units) are:The meter (m) for length, The kilogram (kg) for mass, The second (s) for time, The ampere (A) for electric current, The kelvin (K) for thermodynamic temperature, The mole (mol) for the amount of substance, The candela (cd) for luminous intensity. These seven base units are independent and form the foundation of the SI system, from which all other units are derived.', 0, 0, 0, 1790968056771) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_eb196fb3da692dd4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The humidity in air tells us about the ratio of ____in the air', '{"A":"Oxygen","B":"Water vapors","C":"Nitrogen","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A hygrometer is an instrument used to measure relative humidity. Humidity is the measure of the amount of moisture in the air. A psychrometer is an example of a hygrometer.', 0, 0, 0, 1790968056771) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0a8a8cb868c14950', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The initial setting of cement is caused due to', '{"A":"Tri-calcium silicate","B":"Di-calcuim silicate","C":"Tri-aluminum","D":"Di-Aluminum"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The initial setting of cement is caused by: Hydration of Tricalcium Aluminate (C₃A). Reaction of C₃A with water, which starts rapidly after mixing. Formation of calcium aluminate hydrates, causing the paste to stiffen. Gypsum is added to slow down this reaction and prevent flash setting.', 0, 0, 0, 1790968056805) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1840ba0b7a2570a2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The instrument used in a submarine to see the object in the surface of water is:', '{"A":"Periscope","B":"Telescope","C":"Kaleidoscope","D":"Microscope"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Periscopes allow a submarine, when submerged at a relatively shallow depth, to search visually for nearby targets and threats on the surface of the water and in the air. When not in use, a submarine''s periscope retracts into the hull.', 0, 0, 0, 1790968056805) ON CONFLICT(id) DO NOTHING;
