INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_aedfcb39047f63e3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'which fuel produces least air pollution?', '{"A":"CNG","B":"Petrol","C":"Diesel","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation CNG as compared to other fuels, causes less pollution. The reason is that it is made up of methane.There is less carbon emission.', 0, 0, 0, 1790968056943) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5da77666d6e44e31', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which is the largest joint in the human body?', '{"A":"Knee","B":"Albow","C":"Ankle","D":"Wrist"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The hip and knee are the largest joints in the body.The femur is the longest bone in the human body and the shortest bone is the stapes found in the middle ear.', 0, 0, 0, 1790968056943) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5d93792a2a1e4899', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which is the thinnest earth layer?', '{"A":"Crust","B":"Core","C":"Outer Mental","D":"Inner Mental"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Earth can be divided into four main layers: the solid crust on the outside, the mantle, the outer core and the inner core. Out of them, the crust is the thinnest layer of the Earth, amounting for less than 1% of our planet''s volume.', 0, 0, 0, 1790968056943) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_970adb0f93d4d9fb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of following color of water is not due to algae?', '{"A":"Red","B":"Green","C":"Blue","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The color of water varies with the ambient conditions in which that water is present.', 0, 0, 0, 1790968056943) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_39da20694b547490', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of following phenomenon gives an evidence for the spherical shape of Earth:', '{"A":"Solar Eclipse","B":"Lunar Eclipse","C":"Venus Transition","D":"Mars Transition"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A lunar eclipse occurs when the Moon moves into the Earth''s shadow. This can occur only when the Sun, Earth, and Moon are exactly or very closely aligned with Earth between the other two, and only on the night of a full moon.', 0, 0, 0, 1790968056943) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_44e21a42ec2f85b4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following is a way to reduce the Traffic noise on the highway?', '{"A":"Increase the speed of the vehicles","B":"Horning in unnecessary time","C":"Using old engine vehicles","D":"Using new engine vehicles","E":"Constructing the vertical barriers"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation · The path of traffic noise can be locked by constructing vertical barriers along the highways.· Proper highway planning and design are essential for controlling traffic noise. · Establishing lower speed limits for highways also reduced the noise.', 0, 0, 0, 1790968056974) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1c3953dd2a6a9f54', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following latent functions among the defined human functions by Robert Merton?', '{"A":"Easily apparent","B":"Intension or obvious","C":"Unintentional and not obvious","D":"Visible"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Manifest and latent functions are social scientific concepts created by anthropologist, Bronislaw Malinowski in 1923 while studying the Trobiand Islanders in the Western Pacific.', 0, 0, 0, 1790968056974) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b3c7f9375c0fb3a6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following terms is not associated with psychoanalysis?', '{"A":"Free association","B":"Dream analysis","C":"Self-actualization","D":"Hypnosis"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The top 5 related words for "psychoanalysis" are: psychotherapy, neurosis, melanie klein, transference, and sigmund freud.', 0, 0, 0, 1790968056974) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3f7295cadad87fb4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of these senses least developed in humans.', '{"A":"Listen","B":"Hearing","C":"Smell","D":"Sight"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Vision is the least developed sense at birth, as the womb is a dark place and there is little opportunity for development.Hearing: Develops relatively well during pregnancy, allowing babies to hear sounds from around the 20th week. Touch: Also develops fairly well in utero, providing comfort and a sense of security. Smell and Taste: These senses are closely linked and are important for newborns to recognize their mother''s breastmilk and establish bonding.', 0, 0, 0, 1790968056974) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_75cbacd56e62474f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which part of an eye shows colours_____?', '{"A":"Retina","B":"Irish","C":"Pupil","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790968056974) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_60566454af19dd24', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Who build the first modern motorcar which worked with Gasoline', '{"A":"John Volta","B":"Karl Benz","C":"Henry Burmann","D":"Henry Austin"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Karl Benz was a German engine designer and automobile engineer. His Benz Patent Motorcar from 1885 is considered the first practical automobile.', 0, 0, 0, 1790968056974) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4f87bec3bc3fb400', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Who discovered Radium?', '{"A":"Perri Curie","B":"Marie Curie","C":"Rontgen","D":"Galileo"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Radium is a chemical element with the symbol Ra and atomic number 88.', 0, 0, 0, 1790968056974) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_26ae8e49d7fb3bd2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Who initiated the theory of human life bio genesis', '{"A":"Louis Pasture","B":"Mendel","C":"Darwan","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Biogenesis is the production of new living organisms.', 0, 0, 0, 1790968056974) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5f197857d73a9fe0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Who invented adding machine?', '{"A":"Blaise Pascal","B":"Leonardo Da Vinci","C":"Wilbur Wright","D":"Karl Benz","E":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Pascaline was designed and built by the French mathematician-philosopher Blaise Pascal between 1642 and 1644.', 0, 0, 0, 1790968057013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_25554b95fb628b5f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Who invent chronometer ___ ?', '{"A":"John Harrison","B":"Marconi","C":"John Baird","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Portable timekeeping device of great accuracy, particularly one used for determining longitude at seaIn 1735', 0, 0, 0, 1790968057013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4eef6ea31b424169', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'xylem function in plants', '{"A":"Deliver water","B":"photosynthesizes","C":"Both","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Xylem is one of the two types of transport tissue in vascular plants, the other being phloem. The basic function of xylem is to transport water from roots to stems and leaves, but it also transports nutrients.', 0, 0, 0, 1790968057013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f93a7cd4f5c4c33e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', '___________ is the lightest substance on the earth.', '{"A":"Nitrogen","B":"Oxygen","C":"Hydrogen","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hydrogen and helium, the lightest two gases,Hydrogen is a chemical elementIt is colorless, odorless, tasteless, non-toxic, and highly combustible. Symbol: HAtomic mass: 1.00784 uAtomic number: 1Atomic mass : zeroBoiling point: -252.9 °CDiscoverer: Henry Cavendish', 0, 0, 0, 1790968057013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_318315e2517a1e02', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'To an astronaut in the spacecraft, the sky appears to be.', '{"A":"White","B":"Red","C":"Blue","D":"Dark"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Answer:It looks dark to astronauts. On the earth, the blue sky can be seen due to the existence of the atmosphere. The atmosphere blocks the rays of the sun and you can see the color of the sky. In the universe, because there is no atmosphere, the rays reach the astronomer''s eyes without refraction and appear dark.', 0, 0, 0, 1790968057013) ON CONFLICT(id) DO NOTHING;
INSERT INTO subject (id, user_id, name, parent_id, total_mcqs, created_at) VALUES ('top_eds_physics', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'Physics', 'top_everyday_science', 286, 1790968057039) ON CONFLICT(id) DO UPDATE SET total_mcqs = 286;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f59c5e40ee1efcb3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The SI unit of energy is?', '{"A":"Kelvin","B":"Joule","C":"Temperature","D":"Mole"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The SI unit of energy is the Joule (J).It is the unit of energy, work, and heat.Additional information:1 Joule (J) = 1 Newton × 1 meterCalorie – 1 cal = 4.184 JKilowatt-hour (kWh) – 1 kWh = 3.6 × 10⁶ JElectronvolt (eV) – 1 eV ≈ 1.602 × 10⁻¹⁹ JErg (CGS unit) – 1 erg = 10⁻⁷ JLast verified on 17-01-2026', 0, 0, 0, 1790968057070) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d3548ed7561b559f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The light Bulb was invented by?', '{"A":"Newton","B":"Archimedes","C":"Thomas Edison","D":"Einstein"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Inventor: Thomas Alva Edison.Country: United States.Practical incandescent bulb: 1879.Other contributions: Electric power, sound recording, motion pictures.Famous invention: Phonograph.Last verified on 03-09-2026', 0, 0, 0, 1790968057070) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e2da83b81bb92b7e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The atmospheric pressure (air pressure) at any place is measured by _____?', '{"A":"Altimeter","B":"Pressure Meter","C":"Barometer","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A Barometer is an instrument used to measure air (atmospheric) pressure.It helps in weather forecasting by measuring changes in atmospheric pressure.The mercury barometer is the oldest type of barometer.It was invented by Evangelista Torricelli in 1643.Barometers are widely used in meteorology and aviation.Last verified on 09-07-2026', 0, 0, 0, 1790968057070) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fd3b06c67717f730', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Temperature of healthy person is 37°C. What is this temperature on Kelvin scales?', '{"A":"273 K","B":"300 K","C":"310 K","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To convert Celsius to Kelvin, use: K = °C + 273Given temperature = 37°C37 + 273 = 310 KAdditional information:0°C = 273 K100°C = 373 KLast verified on 06-09-2026', 0, 0, 0, 1790968057070) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ddff181d05102b5b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which principle explains why pressure cookers cook food faster?', '{"A":"Gay-Lussac''s Law","B":"Boyle''s Law","C":"Dalton''s Law","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pressure cookers cook food faster due to Gay-Lussac’s Law.This law states that pressure increases when temperature increases in a closed container.In a pressure cooker, steam is trapped, increasing pressure.Higher pressure raises the boiling point of water above 100°C.Food cooks at a higher temperature, so it cooks faster.Last verified on 14-06-2026', 0, 0, 0, 1790968057070) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6a8e9340c4fa7bb9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Normal human body temperature 98.6°F corresponds to _______?', '{"A":"55°C","B":"42°C","C":"37°C","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The normal body temperature is: 37°C.The average normal body temperature is generally accepted as 98.6°F (37°C).A temperature over 100.4°F (38°C) means you have a fever.Additional Information:Hypothermia is the term used for temperature less than 36.50°C.Mild Pyrexia is the term used for temperature (99-100°F).Moderate Pyrexia is the term used for temperature (100-103°F).Severe Pyrexia is the term used for temperature (103-105°F).Last verified on 16-02-2026', 0, 0, 0, 1790968057070) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_02100c021747ca73', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'A unit of pressure is equal to 1 newton per square meter (N/m²) is known as?', '{"A":"Newton","B":"Joule","C":"Pascal","D":"Kelvin"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The unit of pressure is N/m² (Newton per square meter).It is also called Pascal (Pa).Pressure means force applied per unit area.Higher force or smaller area increases pressure.Last verified on 17-06-2026', 0, 0, 0, 1790968057070) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_00bd84b1d9939be1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which is an alteration in the observed frequency of a sound due to motion of either the source or the observer?', '{"A":"Doppler effect","B":"Thermal effect","C":"Diffraction effect","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Doppler Effect is the change in the observed frequency of sound due to the relative motion between the source and the observer.If the source and observer move toward each other, the observed frequency increases.If they move away from each other, the observed frequency decreases.A common example is the changing pitch of an ambulance siren as it passes by.Last verified on 02-09-2026', 0, 0, 0, 1790968057070) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_595618967c079cf6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which Muslim scientist presented the theory of reflection and refraction of light?', '{"A":"Ibn al-Haytham","B":"Al-Khwarizmi","C":"Al-Biruni","D":"Ibn Sina"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ibn al-Haytham presented the theory of reflection and refraction of light.He is also known as Alhazen.His work, particularly his "Book of Optics", is titled Kitab al-Manazir, written during 1011–1021.Born: c. 965 (c. 354 AH) Basra, Buyid EmirateDied: c. 1040 (c. 430 AH)[1] (aged around 75) Cairo, Fatimid CaliphateLast verified on 02-09-2026', 0, 0, 0, 1790968057098) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_884e35d84fe7f5c9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Very High Frequency (VHF) have __________ wavelengths.', '{"A":"Longer","B":"Shorter","C":"Shortest","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Very high frequency is the ITU designation for the range of radio frequency electromagnetic waves from 30 to 300 megahertz,with corresponding wavelengths of ten to one meter.ND17-7-2023', 0, 0, 0, 1790968057098) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a9744e453329aa78', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The pitch of a sound wave is related to/depends on its ______?', '{"A":"Beats","B":"Frequency","C":"Amplitude","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The pitch of a sound wave depends on its frequency.Pitch tells us whether a sound is high or low.Higher frequency → higher pitch (e.g., whistle).Lower frequency → lower pitch (e.g., bass drum).Frequency is measured in Hertz (Hz).Last verified on 11-08-2026', 0, 0, 0, 1790968057098) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f28cf082921c11c1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The equation E = mc² indicates that energy _____?', '{"A":"Is fundamentally different than mass","B":"And mass are closely related","C":"Equals mass moving at the speed of the light square","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Einstein''s equation E=mc² shows that mass can be converted into energy and vice versa.c: Speed of light = 299,792,458 m/s (≈ 3×10⁸ m/s)E: Energym: MassIt was proposed by Albert Einstein in 1905 as part of the Special Theory of Relativity.Last verified on 28-07-2026', 0, 0, 0, 1790968057098) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_903857a9c4fcd6c5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The approximate value of the speed of sound in air at 0°C temperature ______?', '{"A":"332 m/s","B":"34 m/s","C":"17 m/s","D":"680 m/s"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The value 332 m/s is measured under standard atmospheric conditions.Additional information:Speed of sound in air at 20°C ≈ 343 m/s.Speed of sound is faster in solids than liquids and gases.Examples:Air: ~332 m/s (0°C)Water: ~1,480 m/sSteel: ~5,100 m/sLast verified on 21-07-2026', 0, 0, 0, 1790968057098) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e011d21585e3848c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The unit of measurement of intensity of sound is in?', '{"A":"Decibel (dB)","B":"Watt per square meter (W/m²)","C":"Hertz (Hz)","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The SI unit of sound intensity is watt per square meter (W/m²).Sound intensity is the amount of sound power passing through a unit area.It shows how strong or weak a sound wave is at a particular point.Sound intensity decreases as the distance from the source increases.Decibel (dB) is used to measure sound intensity level, not the actual intensityLast verified on 20-07-2026', 0, 0, 0, 1790968057098) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ea440b1c087650cd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The instrument used to measure temperature is called the?', '{"A":"Barometer","B":"Hygrometer","C":"Thermometer","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The instrument used to measure temperature is called a thermometer.A thermometer shows how hot or cold an object or place is.Additional information:Barometer measures air pressure.Hygrometer measures humidity (moisture in air).Last verified on 16-06-2026', 0, 0, 0, 1790968057098) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ab0685fded7b89dd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The SI unit of electric current is _____?', '{"A":"Ampere","B":"Volt","C":"Coloumb","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The SI unit of electric current is Ampere (A).Electric current measures the flow of electric charge.Defined using the elementary charge (e = 1.602176634 × 10⁻¹⁹ C).Named after: André-Marie Ampère (scientist).1 Ampere = 1 Coulomb per second (1 A = 1 C/s).Last verified on 08-06-2026', 0, 0, 0, 1790968057098) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_594f9978447d89e8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The speed of light is ________?', '{"A":"280,000 km/s","B":"300,000 km/s","C":"320,000 km/s","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kilometers per second: ≈ 300,000 km/sSpeed in vacuum: 299,792,458 m/sApproximate value: 3 × 10⁸ m/sSymbol: cDistance traveled in 1 second: About 300,000 kmLight from the Sun takes about 8 minutes 20 seconds to reach the Earth.Last verified on 16-05-2026', 0, 0, 0, 1790968057130) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_589452985c1d02ae', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which colur of light has the shortest wavelength?', '{"A":"Red","B":"Green","C":"Blue","D":"White"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Blue light has the shortest wavelength.In the visible spectrum, wavelength decreases from red to violet.Additional information:Red light rays have the lowest frequency and highest wavelength value.Last verified on 10-06-2026', 0, 0, 0, 1790968057130) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b4ae2dcf4e14cd6a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Energy is a nuclear reaction is produced due to _____?', '{"A":"Controlled chain of reaction","B":"Uncontrolled chain of reaction","C":"Chain of reaction","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In a nuclear reactor, energy is produced due to a controlled chain reaction.A controlled chain reaction releases energy steadily and safely.Control rods are used to regulate the number of neutrons and prevent excessive reactions.This controlled process is used to generate electricity in nuclear power plants.Additional information:An uncontrolled chain reaction occurs in nuclear bombs.Last verified on 11-07-2026', 0, 0, 0, 1790968057130) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a50baf4b89097256', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Sound waves travel in solvents in the form of _____?', '{"A":"Transverse Waves","B":"Longitudinal Waves","C":"Electromagnetic Waves","D":"Mechanical Waves"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sound waves in solvents (like liquids) travel as longitudinal waves, where particles vibrate parallel to the direction of wave propagation.These are a type of mechanical wave, requiring a medium to travel.Last verified on 19-03-2026', 0, 0, 0, 1790968057130) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a0db9821d9bc49f6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', '760 torr is equal to ____ Pascal.', '{"A":"1","B":"76","C":"760","D":"101325"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 760 torr = 101,325 Pa760 torr = 1 atm760 torr = 760 mmHgSI Unit of Pressure: Pascal (Pa)Last verified on 09-07-2026', 0, 0, 0, 1790968057130) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e44ccabc0762b9bf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The rate of doing work of a body is called?', '{"A":"Force","B":"Area","C":"Power","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Power is the rate of doing work or the rate at which energy is transferred.It is a scalar quantity (has magnitude only).It shows how quickly work is done.The SI unit of power is the Watt (W).1 Watt = 1 Joule per second (1 W = 1 J/s).Additional information:Formula: P = W/t = E/tSI Base Unit: kg·m²·s⁻³Dimension Formula: ML²T⁻³James Watt is the scientist after whom the Watt unit is named.Last verified on 09-07-2026', 0, 0, 0, 1790968057130) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cfefc7532b3c99b1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The rear (back) view mirror used in the vehicles is _____?', '{"A":"Parabolic mirror","B":"Plane mirror","C":"Concave mirror","D":"Convex mirror"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Rear view mirrors in vehicles are convex mirrors.They give a wider field of view.Images formed are virtual, upright, and smaller.This helps drivers see more traffic behind them.It is a curved mirror that bulges outward.It is commonly used in side mirrors of cars, buses, and motorcycles.Last verified 26-04-2026', 0, 0, 0, 1790968057130) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_713d9fd2b8a96eaa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', '______ is the unit of measurement for the potential difference that cause a current to flow through a conductor.', '{"A":"Ampere","B":"Volt","C":"Ohm","D":"Watt"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Volt (V) is the SI unit of potential difference (voltage).Potential difference is the electrical force that causes current to flow through a conductor.It is measured using a voltmeter.The SI unit is named after Alessandro Volta.Additional information:Electric Current: Ampere (A)Resistance: Ohm (Ω)Power: Watt (W)Charge: Coulomb (C)Last verified on 03-06-2026', 0, 0, 0, 1790968057130) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3fbf1a024df56e0a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Sound cannot travel through ______?', '{"A":"Solid","B":"Liquid","C":"Gases","D":"Vacuum"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sound cannot travel through a vacuum because there are no particles to carry sound vibrations.Sound needs a medium such as a solid, liquid, or gas to travel.Since space is nearly a vacuum, sound cannot be heard there.The speed of sound in a vacuum is 0 m/s.Additional information:Infrasound: Below 20 HzAudible sound: 20 Hz – 20,000 Hz (20 kHz)Ultrasound: Above 20 kHzSpeed of sound in air: 343 m/sSpeed of sound in water: 1,481 m/sLast verified on 07-06-2026', 0, 0, 0, 1790968057160) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5b5b84d546427102', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Primary colors of white light are?', '{"A":"White Black Blue","B":"Red Green Blue","C":"Yellow Black Blue","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The primary colors of white light are Red, Green, and Blue (RGB).White light is produced when these three colors of light combine in equal amounts.This is called the additive color model.RGB is used in screens, televisions, and digital displays.Additional information:The primary colors of Pigment is:RedYellowBlueLast verified on 25-06-2026', 0, 0, 0, 1790968057160) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2ac577c0c0742579', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'One horse power is equal to?', '{"A":"746 watt","B":"735 watt","C":"725 watt","D":"700 watt"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 1 hp = 746 W1 hp = 0.746 kW1 kW = 1.34 hp1 W = 0.00134 hpStandard unit system: SI unit of power is WattLast verified on 23-06-2026', 0, 0, 0, 1790968057160) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ade4bcaf2db6d0b0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The dimension of velocity is?', '{"A":"[L T⁻¹]","B":"[M L T⁻²]","C":"[L T²]","D":"[L² T⁻¹]"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The dimension of velocity is [L T⁻¹].Velocity is defined as displacement per unit time.It shows how fast and in which direction an object moves.It is a vector quantity.SI unit of velocity is m/s.Last verified on 17-06-2026', 0, 0, 0, 1790968057160) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f0515411dfab8706', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The light sensitive part of eye is _____?', '{"A":"Cornea","B":"Retina","C":"Optic nerve","D":"Iris"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The retina is the light-sensitive layer located at the back of the human eye.It contains special cells called rods and cones that detect light and color.These cells convert light into electrical signals.The signals are then sent to the brain through the optic nerve to produce vision.Last verified on 11-03-2026', 0, 0, 0, 1790968057160) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b40d257bb22292ce', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Recognize the part of eye which control the amount of light entering inside the eye is?', '{"A":"Cornea","B":"Iris","C":"Pupil","D":"Retina"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The part of the eye that controls the amount of light entering is the Iris.It adjusts the size of the pupil according to light intensity.In bright light, it reduces light entry; in dim light, it allows more light in.This process protects the retina and helps clear vision.Last verified on 17-05-2026', 0, 0, 0, 1790968057160) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_28de7fa672305a48', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The SI unit of Electrical Resistance is _____?', '{"A":"Volts (V)","B":"Ohms (Ω)","C":"Amps (A)","D":"Watts (W)"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The SI unit of electrical resistance is Ohm (Ω).It measures how much a material opposes the flow of electric current.Higher resistance means less current flows.It is defined by V = IR (Ohm’s Law).1 Ohm = 1 Volt per Ampere.Last verified on 10-06-2026', 0, 0, 0, 1790968057160) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_601e0206e8dea349', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The relationship between voltage, current, and resistance is described in terms of _____?', '{"A":"Joule–Thomson Effect","B":"Ohm’s law","C":"Boyle’s law","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The relationship between voltage, current, and resistance is described by Ohm’s Law.It states that current is directly proportional to voltage and inversely proportional to resistance.The mathematical form is V = IR.Last verified on 09-06-2026', 0, 0, 0, 1790968057160) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8450bc72ad3da224', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Splitting of light into its constituent colors is known as?', '{"A":"Dispersion","B":"Contraction","C":"Reflection","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The splitting of light into its constituent colors is called dispersion.White light splits into seven colors (VIBGYOR).It occurs when light passes through a prism.Different colors bend at different angles.This creates a spectrum of colors.Last verified on 08-06-2026', 0, 0, 0, 1790968057190) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_40142740ef93e09c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'When white light is passed through a prism, it splits into ______ colors.', '{"A":"7","B":"8","C":"2","D":"4"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When white light passes through a prism, it splits into 7 colors, forming a spectrum known as a rainbow:RedOrangeYellowGreenBlueIndigoViolet The separation of visible light into its different colours is known as dispersion.Last verified on 08-06-2026', 0, 0, 0, 1790968057190) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2b1992eac5c0f6af', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'What type of energy does a stretched spring possess?', '{"A":"Kinetic Energy","B":"Potential Energy","C":"Heat Energy","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A stretched spring possesses potential energy.When a spring is stretched or compressed, energy is stored in it.This stored energy is called elastic potential energy.It can be converted into kinetic energy when released.The more the stretch, the more energy is stored.Last verified on 08-06-2026', 0, 0, 0, 1790968057190) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cdbcf0146b79d7b0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'A device that converts mechanical energy into electric energy is called _______?', '{"A":"Motor","B":"Transformer","C":"Coil","D":"Generator"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An electric generator is a device that converts mechanical energy into usable electrical energy.This process is based on the principle of electromagnetic induction.Discovered in 1831 by British scientist Michael Faraday.Last verified on 27-04-2026', 0, 0, 0, 1790968057190) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2338c87434612629', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'When the velocity of a body is doubled its ______ is doubled.', '{"A":"Momentum","B":"K.E.","C":"P.E.","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Momentum (p = mv): If velocity doubles, momentum also doubles.Kinetic Energy (KE = ½mv²): If velocity doubles, KE becomes four times.Last verified on 07-06-2026', 0, 0, 0, 1790968057190) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_93041d9a2c47a8f8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which of the following is a conductor of electricity?', '{"A":"Copper","B":"Plastic","C":"Rubber","D":"Wood"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Copper (تانبا) is a good conductor of electricity.It allows electric current to flow easily.Additional information:Metals are generally good conductors.Non-metals usually do not conduct electricity.Good Conductors: Copper, Silver, Gold, Aluminum, GraphiteBad Conductors: Plastic, Rubber, Wood, Glass, AirLast verified on 07-06-2026', 0, 0, 0, 1790968057190) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cc13e122b888d7df', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'What play the most important role in regulating temperature and determining climate on the Earth?', '{"A":"Mountains","B":"Oceans","C":"Deserts","D":"Forests"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Oceans play the most important role in regulating Earth’s temperature and climate.They absorb heat from the Sun and distribute it across the planet.Ocean currents control weather patterns globally.They help maintain Earth’s temperature balance.Last verified on 06-06-2026', 0, 0, 0, 1790968057190) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a835105fa69b1a86', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Average distance covered by alpha particle (α-particle) in air before its ionizing power ceases is called its?', '{"A":"Trajectory","B":"Range","C":"Firing level","D":"Limit"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The average distance covered by an alpha particle in air before losing its ionizing power is called its range.Alpha particles lose energy continuously while moving through air.They stop ionizing after traveling a certain distance.This stopping distance is not straight-line path always due to collisions.Last verified on 05-06-2026', 0, 0, 0, 1790968057190) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_741e80c52d8b93d7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'In a very low temperature which from the following will freeze at last?', '{"A":"River water","B":"Canal water","C":"Sea water","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sea water contains a high amount of dissolved salts.Because of salinity, its freezing point is lower than fresh water.Fresh water freezes at 0°C, but saltwater freezes at a lower temperature.Last verified on 01-06-2026', 0, 0, 0, 1790968057223) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_20ddd6d6c6a8c88c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The normal temperature of human body is _________ degree Fahrenheit.', '{"A":"90.8°F","B":"37.5°F","C":"98.6°F","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The average normal body temperature is generally accepted as 98.6°F (37°C).A temperature over 100.4°F (38°C) means you have a fever.Additional Information:Hypothermia is the term used for temperature less than 36.50°C.Mild Pyrexia is the term used for temperature (99-100°F).Moderate Pyrexia is the term used for temperature (100-103°F).Severe Pyrexia is the term used for temperature (103-105°F).Last verified on 16-02-2026', 0, 0, 0, 1790968057223) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ce40aebc4acd8c04', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which radiation/particle/rays has highest/greatest/more penetrating power energy among these?', '{"A":"Gamma rays","B":"Alpha rays","C":"Beta rays","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Gamma rays have the highest penetrating power among these particles.Due to their lack of mass and charge.It allowing them to pass through most materials.Additional information:Alpha radiation has the lowest penetrating power.Last verified on 12-04-2026', 0, 0, 0, 1790968057223) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b9847163941066a8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The energy of photon is given by ______?', '{"A":"E = hf","B":"E = m.c²","C":"E = m.e","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The energy of a photon is calculated using the formula E = hf, where:h = Planck’s constantf = frequency of the photonThis shows that photon energy is directly proportional to its frequency.Last verified on 23-05-2026', 0, 0, 0, 1790968057223) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ea0b75048b6eacf1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which law explains the relationship between force, mass, and acceleration (Force = Mass x Acceleration)?', '{"A":"Newton’s First Law","B":"Newton’s Second Law","C":"Newton’s Third Law","D":"Law of Gravitation"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Newton''s Second Law of motion explains the relationship between force, mass, and acceleration Through the equation F = ma, which states that the acceleration of an object It is directly proportional to the net force acting on it and inversely proportional to its mass. This means a greater force produces greater acceleration, While a greater mass results in less acceleration for the same force.Last verified on 22-05-2026', 0, 0, 0, 1790968057223) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5ee4a0d9b35e83fe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The area under a velocity-time graph gives/represents ______?', '{"A":"Displacement","B":"Speed","C":"Acceleration","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A velocity–time graph shows how velocity changes with time.The slope gives acceleration.The area under the graph represents motion covered.It connects velocity with displacement.Last verified on 22-05-2026', 0, 0, 0, 1790968057223) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b52af88b2c3ceb8c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The current through a conductor between two points is directly proportional to the voltage across the two points, is known as?', '{"A":"Ohm’s law","B":"Kirchhoff’s 2nd law","C":"Kirchhoff’s 1st law","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ohm''s law, description of the relationship between current, voltage, and resistance. Georg Simon Ohm stated that the electric current through a conductor is directly proportional to the voltage across it, provided temperature remains constant. This relationship is called Ohm’s Law.Last verified on 22-05-2026', 0, 0, 0, 1790968057223) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b09589f6100f6b0d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which metal is the best conductor of electricity?', '{"A":"Silver","B":"Copper","C":"Brass","D":"None of them"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Metals allow electricity to pass through them easily.Among all metals, silver has the highest electrical conductivity.Copper and gold are also very good conductors.Silver is widely used in high-precision electrical applications.Copper is commonly used in wiring due to cost-effectiveness.Last verified on 16-05-2026', 0, 0, 0, 1790968057223) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8c75bee407f46624', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The major source of quick energy for our body is?', '{"A":"Carbohydrates","B":"Mineral","C":"Vitamin","D":"Protein"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Carbohydrates are the fastest and main source of energy.They are quickly converted into glucose in the body.Glucose is used immediately for energy production.They provide instant fuel for brain and muscles.Last verified on 14-05-2026', 0, 0, 0, 1790968057257) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a02ffcc5756117b7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which is the renewable source of energy?', '{"A":"Solar and wind","B":"Coal","C":"Natural gas","D":"Petroleum"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Solar and wind energy are renewable sources of energy, meaning they are sustainable and will not run out.Solar energy is generated from the sun''s rays.Wind energy is generated from the wind.Last verified on 09-02-2026', 0, 0, 0, 1790968057257) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c79f5beccd8b3eb3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which of the following lens is used in simple microscope?', '{"A":"Concave Lens","B":"Curved Lens","C":"Convex Lens","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A simple microscope is used to magnify small objects.It works by bending light to produce a larger image.Only a converging lens can produce a magnified virtual image.A convex lens has this property.Therefore, simple microscopes use a convex lens.Last verified on 12-04-2026', 0, 0, 0, 1790968057257) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b326cd2186514d03', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'At what temperature reading do the Fahrenheit and the Celsius temperature scales coincide (equal)?', '{"A":"100 degrees","B":"40 degrees","C":"-40 degrees","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Celsius and Fahrenheit are two temperature scales.At one special point, both scales show the same value.This happens when temperature is −40.So, −40°C = −40°F.Last verified on 11-04-2026', 0, 0, 0, 1790968057257) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f2521c2e8c1c2a0c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Energy possessed by body due to motion is called _____?', '{"A":"Kinetic energy","B":"Potential energy","C":"Chemical energy","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Energy due to motion is called kinetic energy.Any moving object possesses this energy.It depends on mass and velocity of the body.Faster motion means more kinetic energy.Last verified on 11-04-2026', 0, 0, 0, 1790968057257) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6c601db8c38a3c17', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The velocity (speed) of sound is maximum in? Steel, Air, Water, Vacuum', '{"A":"Air","B":"Glass","C":"Water","D":"Steel"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Solids → fastest sound speedLiquids → medium speedGases → slowest speedSteel is more elastic and dense.Steel ≈ 5000 m/sAir ≈ 332 m/sWater ≈ 1500 m/sLast verified on 11-04-2026', 0, 0, 0, 1790968057257) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ea5f43b9290bdef9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Isaac Newton gave?', '{"A":"Laws of motion and laws of gravition","B":"Laws of Geometary","C":"Laws planetary motion","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Isaac Newton (1642–1727) was an English physicist and mathematician.He formulated the laws of motion and law of universal gravitation.His work laid the foundation for classical mechanics.Last verified on 02-04-2026', 0, 0, 0, 1790968057257) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9e1918d462a3d08d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Myopia can be corrected by using which kind of lens?', '{"A":"Convex","B":"Concave","C":"Diverging","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Myopia (Nearsightedness) is an eye defect in which near objects are clear but distant objects appear blurred.It occurs when the image forms in front of the retina instead of on it.It is corrected by using a concave (diverging) lens.The concave lens helps to shift the image back onto the retina.Last verified on 01-04-2026', 0, 0, 0, 1790968057257) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1b31f30f3df1b053', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which colour has smallest wavelength in the spectrum of white light?', '{"A":"Red","B":"Blue","C":"Yellow","D":"Violet"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Violet light has the smallest wavelength, approximately 380-450 nanometers (nm).While red light has the longest wavelength, approximately 620-750 nanometers (nm).The order of colors in the spectrum, from longest to shortest wavelength, is: Red, Orange, Yellow, Green, Blue, Indigo, Violet (ROYGBIV).Last verified on 01-04-2026', 0, 0, 0, 1790968057289) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b2486b1e2f96729d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The cheapest source of electricity generation is _____?', '{"A":"Nuclear","B":"Solar","C":"Hydel","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The cheapest source of electricity generation is Solar Energy.Solar energy uses sunlight, which is free and renewable.Costs have dropped significantly due to modern solar panel technology.It avoids fuel costs and environmental pollution.Last verified on 31-03-2026', 0, 0, 0, 1790968057289) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8e8fbb448f3e0ecf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Material from which current passes through are called?', '{"A":"Insulators","B":"Conductors","C":"Semiconductors","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Conductors are materials that allow electricity to flow through them, such as copper, aluminum, and gold.They have a high concentration of free electrons, which are able to move freely within the material.Additional information:Materials that do not allow electricity to pass through them are called insulators.Last verified on 07-03-2026', 0, 0, 0, 1790968057289) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4543f5f1c06dee31', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'In which mode heat transfer in liquids and gases?', '{"A":"Convection","B":"Radiation","C":"Conduction","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In liquids and gases, heat is mainly transferred by convection.Convection involves the movement of particles carrying heat from one place to another.Essential for weather patterns, ocean currents, and heating systems.Last verified on 19-03-2026', 0, 0, 0, 1790968057289) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bac55af27c2e8c3b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'If an object absorbs all entire component/seven colours of light, it appears in ________ colour.', '{"A":"White","B":"Black","C":"Dark","D":"Green"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation If an object absorbs all seven colors of light (i.e., all the wavelengths of visible light), it appears black.This is because no light is being reflected, and our eyes perceive the absence of light as black.When an object reflects all the component colors of light, it appears white.Last verified on 18-03-2026', 0, 0, 0, 1790968057289) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2445631c85805085', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which of the following is a non-renewable resource used for energy production in Pakistan?', '{"A":"Water","B":"Coal","C":"Solar","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Coal is a non-renewable resource because it takes millions of years to form and cannot be replenished quickly.Pakistan uses coal for energy production, especially in power plants like the Thar coal project.Non-renewable energy sources:OilNuclear energyPetroleumNatural gas & coalRenewable sources of energy:Solar energyWind energyHydroelectric powerBiomass energyGeothermal energyTidal energyLast verified on 11-02-2026', 0, 0, 0, 1790968057289) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4dd45bc7c0a3cbc0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'When light passes through prism _____ occurs to form spectrum.', '{"A":"Refraction","B":"Reflection","C":"Diffraction","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Refraction: Bending of light when it passes from one medium to another.A prism bends light at different angles depending on wavelength.This separation of colors is called dispersion, forming a spectrum.Visible spectrum colors: Red, Orange, Yellow, Green, Blue, Indigo, Violet (ROYGBIV).Last verified on 13-03-2026', 0, 0, 0, 1790968057289) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2cbbd10e8d7688f3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Einstein was awarded the Nobel Prize for his work on:', '{"A":"Theory of the photoelectric effect","B":"General theory of relativity","C":"Special theory of relativity","D":"Invention of Electric Motor","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Albert Einstein received the Nobel Prize for his discovery of the Law of the photoelectric effectThe 1921 prize was actually awarded in 1922.', 0, 0, 0, 1790968057289) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e301083257561899', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'In a transverse wave, the distance between two successive/adjacent crests or troughs of a wave is called ______?', '{"A":"Frequency","B":"Amplitude","C":"Velocity","D":"Wavelength"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Wavelength is the distance between two successive crests or two successive troughs in a transverse wave.It represents one complete cycle of a wave.Additional information:Symbol used: λ (Lambda)SI unit: meter (m)Wave formula: v = fλExample wavelength values: 1 m, 0.5 m, 10 cm, 500 nm, 700 nmVisible light wavelength range: ~400 nm – 700 nmLast verified on 12-03-2026', 0, 0, 0, 1790968057327) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d919b75334acabd4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'An optical instrument used to measure the properties of visible light is called?', '{"A":"Spectroscope","B":"Telescope","C":"Microscope","D":"Binoculars"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An optical instrument used to measure the properties of visible light is called a Spectroscope.It analyzes the composition and properties of materials based on the light they emit or absorb.It helping us understand the physical and chemical properties of objects in the universe.Last verified on 12-03-2026', 0, 0, 0, 1790968057327) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_14285852e02601c0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The reaction which releases or gives off heat is called?', '{"A":"Exothermic Reaction","B":"Endothermic Reaction","C":"Oxidation Reaction","D":"Neutralization Reaction"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A chemical reaction that releases heat energy to the surroundings is called an Exothermic Reaction.In such reactions, energy is produced in the form of heat, light, or flames.Examples include combustion of fuel, respiration, and neutralization reactions.Additional information:An endothermic reaction, which absorbs heat from the surroundings.Last verified on 11-03-2026', 0, 0, 0, 1790968057327) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_268e8ce2f364d084', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The SI unit of “Pressure” is ______?', '{"A":"Henry","B":"Pascal","C":"Joule","D":"None of these"}', 'B', NULL, 0, 0, 0, 1790968057327) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5bf44d7d547511b7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Sound Waves are ______ radiation.', '{"A":"Longitudinal","B":"Electromagnetic","C":"Latitudinal","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sound waves require a medium (air, water, or solid) to travel, so they are mechanical waves. The particles of the medium vibrate parallel to the direction of wave propagation. This makes sound waves longitudinal waves. In a longitudinal wave, compressions and rarefactions carry the sound energy. Therefore, sound waves are mechanical longitudinal waves and cannot travel in a vacuum.Last updated on 09-03-2026', 0, 0, 0, 1790968057327) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7a81c6de0178cec2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which one is a vector quantity? Mass ,Weight, Time, Temperature', '{"A":"Mass","B":"Weight","C":"Time","D":"Temperature"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Weight is a vector quantity Because it is a force defined as the product of mass and the acceleration due to gravity (W = mg).It has both magnitude (amount of force) and direction (downward, towards the center of the Earth)Additional information Mass, Time, and temperature are scalar quantitiesLast updated on 09-03-2026', 0, 0, 0, 1790968057327) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7cd8adbbcb41484d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which one of the following does not depend on the magnetic effect of current for its working:', '{"A":"Carbon microphone","B":"Telephone receiver","C":"Electric Fan","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A carbon microphone does not depend on the magnetic effect of current.Based on the variation of electrical resistanceIt converts sound vibrations into electrical signals Additional information Devices like electromagnets, electric bells, and ammeters work due to the magnetic effect of current.Last updated on 09-03-2026', 0, 0, 0, 1790968057327) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_499f7a5310fc516f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The product of mass and velocity is known as _____?', '{"A":"Distance","B":"Momentum","C":"Velocity","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The product of mass and velocity is known as momentum. P = MVIf m is an object''s mass and v is its velocity (also a vector quantity), then the object''s momentum p is: p=mvIt is a vector quantity.It having both magnitude and direction.Common symbols: p, pSI unit: kg⋅m⋅s−1Dimension MLT^−1Last updated on 09-03-2026', 0, 0, 0, 1790968057327) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fb2e6adcc2a67538', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'What is the dimensional formula of force?', '{"A":"[M T² L⁻¹]","B":"[M L T⁻²]","C":"[L M⁻¹ T²]","D":"[M L² T⁻¹]"}', 'B', NULL, 0, 0, 0, 1790968057356) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1bd19c6cdc233426', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The acceleration of body due to the constant velocity is :', '{"A":"Positive","B":"Zero","C":"Negative","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When the velocity of a body is constant, its acceleration is zeroAcceleration = rate of change of velocity.If velocity does not change, the rate of change = 0.Constant velocity means both magnitude and direction remain constant.No net force acts on the body (Newton’s 1st law).Therefore, acceleration = 0Last updated question 25 feb 2026', 0, 0, 0, 1790968057356) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e3288fd2bd697c3e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'A wave transfers_______?', '{"A":"Energy","B":"Frequency","C":"Wavelength","D":"Velocity"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A wave transmits energy from one place to anotherWaves are disturbances that propagate through a medium.Particles of the medium oscillate around equilibrium but do not travel with the wave.The motion of particles transfers energy, not matter.Energy is carried in the form of kinetic and potential energy of oscillating particles.Last updated question 25 feb 2026', 0, 0, 0, 1790968057356) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dce934c685b97c1a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Force per unit area is called _____?', '{"A":"Volume","B":"Density","C":"Velocity","D":"Pressure"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pressure is a fundamental physical quantity that is defined as the force exerted per unit area.It is a measure of the strength of a force acting on a surface.It is typically measured in units such as Pascals (Pa) or pounds per square inch (PSI).Last verified on 10-02-2026', 0, 0, 0, 1790968057356) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_41f44633849b091c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which crop required high temperature, light rainfall or irrigation, 210 frost freer days, and bright sunshine for its growth?', '{"A":"Rice","B":"Wheat","C":"Jute","D":"Cotton"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cotton cultivation requires a significant number of frost-free days, typically around 210It is the crop that requires high temperatures (21°C to 30°C)It thrives in tropical and subtropical climatesIt''s grown in the Kharif season', 0, 0, 0, 1790968057356) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c031670abecab0e4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Sound Waves travel faster in a medium ____?', '{"A":"Denser","B":"Rigid","C":"Solid","D":"Soft"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sound waves are mechanical waves and need a medium to travel.They travel fastest in solids, slower in liquids, and slowest in gases.Solid particles are closely packed, allowing rapid vibration transfer.Last verified on 04-02-2026', 0, 0, 0, 1790968057356) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9d91e102ce22e0ce', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which rocks are formed by the alteration of pre-existing rocks by great heat or pressure?', '{"A":"Igneous rocks","B":"Sedimentary rocks","C":"Metamorphic rocks","D":"Acid rocks","E":"Basic rocks"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Metamorphic rocks are formed from pre-existing rocks (igneous, sedimentary, or older metamorphic rocks).They are changed by high heat and/or pressure without melting.Common examples include marble (from limestone) and gneiss (from granite).The process is called metamorphism, meaning “change in form.”', 0, 0, 0, 1790968057356) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7b474df43bbf8b85', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The SI unit of electric power is?', '{"A":"Watt","B":"Joules","C":"Volts","D":"Ampere"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Electric power: Rate of energy transfer.It is measured in watts (W), or one joule per second.Energy/Work: Measured in joules (J).Charge: Measured in coulombs (C).Pressure: Measured in pascals (Pa).Electric current: Measured in amperes (A).Electric resistance: Measured in ohms (Ω).Temperature: Measured in kelvin (K).Torque: Measured in newton metres (N m).Velocity: Measured in meters per second (m/s).Acceleration: Measured in meters per second squared (m/s²).', 0, 0, 0, 1790968057356) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_505995c8f11baade', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'In a p-type material/semi conductor the ______ is the majority carrier.', '{"A":"Proton","B":"Electron","C":"Atoms","D":"Holes"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The majority carriers in a p-type semiconductor are holes. When a semiconductor material is doped with trivalent impurity atoms (like Boron), it creates "holes" where electrons are missing, effectively giving a positive charge. These holes then become the majority charge carriers, meaning they are the primary contributors to electrical current flow in the material.', 0, 0, 0, 1790968057387) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_05edd1cc8765f176', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which is the Newton''s second law of motion?', '{"A":"F=ma","B":"P=mv","C":"F=sm","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Newton''s second law of motion states that F = ma, or net force is equal to mass times acceleration.The other name for Newton''s second law is the law of force and acceleration.', 0, 0, 0, 1790968057387) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4b816a38490f94a6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The energy value of food is measured in :', '{"A":"Proteins","B":"Joule","C":"Vitamins","D":"Calories"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Energy is measured in units of kilocalories One kilocalorie is equal to 4.18 kilojoules. The amount of energy a food contains per gram is known as its energy density, So we can describe fat as more energy-dense than protein or carbohydrate.', 0, 0, 0, 1790968057387) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a42eb5fe29710b40', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The force of attraction between two masses is given by _____?', '{"A":"Newton’s Law of Gravitation","B":"Newton’s Second Law","C":"Hooke’s Law","D":"Coulomb’s Law"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Newton''s Law of Gravitation states that every particle attracts every other particle in the universe with a force That is directly proportional to the product of their masses and inversely proportional to the square of the distance between their centers.', 0, 0, 0, 1790968057387) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b18afed8194483f6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'A solution which can dissolve more solute at given temperature is called?', '{"A":"Standard Solution","B":"Super Saturated solution","C":"Unsaturated Solution","D":"Saturated Solution"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Unsaturated Solution: A solution that can dissolve more solute at a given temperature.Saturated Solution: A solution that contains the maximum amount of solute that can dissolve at a specific temperature.', 0, 0, 0, 1790968057387) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4dea8cee10de990a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'As we climb up the mountain, the atmospheric pressure will _____?', '{"A":"Increases","B":"Decreases","C":"First increases then decreases","D":"Remains same"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The density of air varies with height.It is maximum near the surface of the earth and decreases as the height increases.When we climb up a mountain, the density of air decreases, and thus the atmospheric pressure also decreases.', 0, 0, 0, 1790968057387) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fe325be861aecff7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The penetrating power of X-rays depends on their ______?', '{"A":"Source","B":"Frequency","C":"Applied voltage","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The penetration power of the X-rays depends on the wavelength and frequency of X-raysThe penetration power of the X-rays will be more when the energy of the X-ray is more.***Related Question:X-rays have been discovered by __________?Wilhelm Conrad RoentgenND2-08-2023', 0, 0, 0, 1790968057387) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_09ce377e7efeb2e1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'What is the Unit of Force?', '{"A":"Newton","B":"Joule","C":"Watt","D":"Metre"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The SI unit of force is the newton (N).1 N = the force needed to accelerate 1 kg of mass by 1 m/s²Derived unit: N = kg·m/s²Named after Sir Isaac NewtonBased on F = ma (Newton''s second law)The base units relevant to force are:The metre, unit of length — symbol mThe kilogram, unit of mass — symbol kgThe second, unit of time — symbol s', 0, 0, 0, 1790968057387) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a9b0ff114ac1c942', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'A particle is projected from the ground with C kinetic energy E at an angle of 60 degree with the horizontal. Its kinetic energy at the highest point of its motion will be ____?', '{"A":"E/2","B":"E/4","C":"E/8","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation At the highest point, the vertical velocity becomes zero, only horizontal velocity remains.Horizontal velocity = u cos60° = u/2, so kinetic energy = 1/2m(u/2)² = E/4', 0, 0, 0, 1790968057416) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b56cea0af1b5ac89', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'A battery converts electric energy into which type of energy?', '{"A":"Chemical Energy","B":"Mechanical Energy","C":"Thermal Energy","D":"Nuclear Energy"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A battery stores energy in the form of chemical energy.This energy is later converted into electrical energy when the battery is used.', 0, 0, 0, 1790968057416) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fef5ee4a8945d26a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which of the following is called renewable energy? Geothermal, Solar, Hydropower, All of these', '{"A":"Geothermal","B":"Solar","C":"Hydropower","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Geothermal, Solar, and Hydropower all come from naturally replenished sources.These energies are renewable because they do not deplete with use and are environmentally friendly.Renewable sources of energy include:Solar energyWind energyHydropowerGeothermal energyBiomass', 0, 0, 0, 1790968057416) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ced74643abf452b7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which among the following acts as resistance/fight against disease and infection in the body?', '{"A":"Red Corpuscle (Red Blood Cells)","B":"Vitamins","C":"White  Corpuscles (White Blood Cells)","D":"Carbohydrates"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation White Corpuscles, or White Blood Cells (WBCs), or Leukocytes, act as a defense mechanism by fighting infections and diseases in the body. They play a key role in the immune system.They help fight infections and protect the body against foreign substances, such as bacteria, viruses, and other pathogens.', 0, 0, 0, 1790968057416) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_648d67faae649ea0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which one has the longest wavelength?Blue ,Yellow ,Red', '{"A":"Blue","B":"Yellow","C":"Red","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Red has the longest wavelength in the visible spectrum,Measuring roughly 620 to 750 nanometers (nm).Additional Information:Yellow: Incorrect – mid-to-long range, ~570–590 nmBlue: Incorrect – much shorter, ~450–495 nm', 0, 0, 0, 1790968057416) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_705ea65acc4a9792', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Sound differs from light in the sound _____?', '{"A":"Is a longitudinal wave rather than a transverse wave","B":"Is not subject to diffraction","C":"Does not require energy for his origin","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sound travels as a longitudinal wave, where particles vibrate parallel to the direction of wave motion.In contrast, light is a transverse wave, with vibrations perpendicular to the direction of propagation.', 0, 0, 0, 1790968057416) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a9939414cbe018b5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'A plane mirror forms an image that is ____?', '{"A":"Real and Inverted","B":"Virtual and Inverted","C":"Real and Upright","D":"Virtual and Upright"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A plane mirror produces a virtual image, meaning it''s not a real image that can be projected onto a screen.The image is also upright, meaning it''s not inverted or flipped.', 0, 0, 0, 1790968057416) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ca9c255c39d94d4c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which one of the following is the best heat conductor?', '{"A":"Copper","B":"Iron","C":"Aluminum","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Copper, silver, aluminum, gold, steel, and brass are common conductors of electricity.The most highly conductive metals are silver, copper, and goldSilver is the first-best conductor of heat.Copper is the second-best conductor of heat.', 0, 0, 0, 1790968057416) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_38965352b35e196c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Bending ability of light when passing from one medium to another is commonly observed in the phenomenon of ______?', '{"A":"Sublimation","B":"Refraction","C":"Convection","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Refraction is the bending of light as it passes from one medium to another (e.g., air to water).This occurs due to a change in the speed of light in different media.', 0, 0, 0, 1790968057448) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9ae26f81bc5387af', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The average internal temperature of human body is?', '{"A":"42°C","B":"37°C","C":"98°C","D":"35°C"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The average internal temperature of the human body is 37°C (98.6°F).It is the normal body temperature range for a healthy adult.', 0, 0, 0, 1790968057448) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_87b305b24e6bdfc0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which of the following is a vector quantity? Speed, Velocity ,Temperature, None of these', '{"A":"Speed","B":"Velocity","C":"Temperature","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Velocity is a vector quantity. A vector quantity has both magnitude and direction. Velocity, which describes the rate of change of position in a specific direction, needs both a magnitude (speed) and a direction to be fully defined. Vector Quantities: Velocity, momentum, torque, acceleration.Scalar Quantities: Work, distance, speed, mass.', 0, 0, 0, 1790968057448) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a3ff91fbb62809e9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The temperature scale which is independent of the nature of the working substance is?', '{"A":"Celsius scale","B":"Fahrenheit scale","C":"Centigrade scale","D":"Thermodynamic scale"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The thermodynamic (Kelvin) scale is based on absolute zero and does not depend on the substance used.Other scales like Celsius or Fahrenheit vary with the physical properties of specific substances.', 0, 0, 0, 1790968057448) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fc4e58134548653e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The melting point of ice at normal atmospheric pressure is ______?', '{"A":"0 °C","B":"0 K","C":"100 °C","D":"Both ''a'' and ''b''"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The melting point of ice at normal atmospheric pressure is 0 °C (zero degrees Celsius).Key Points:0 K (zero Kelvin) is equivalent to -273.15 °C, which is absolute zero, the lowest possible temperature.100 °C is the boiling point of water at normal atmospheric pressure.', 0, 0, 0, 1790968057448) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3a18519d480781a4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which one of the following will be good conductor of electricity?', '{"A":"Dilute solution of glucose","B":"Molten NaCl","C":"Pure distilled water","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Molten NaCl conducts electricity.Because it contains free-moving Na⁺ and Cl⁻ ions.', 0, 0, 0, 1790968057448) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_25bf9c05b4bb3262', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Atmospheric pressure at sea level is _______?', '{"A":"760 mm","B":"746 mm","C":"820 mm","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Atmospheric pressure at sea level is 1 atmWhich equals:101.325 kPa (1,013.25 hPa/millibars) 760 mmHg, or about 14.7 psi.', 0, 0, 0, 1790968057448) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8516ca741df9e008', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Ultra violet light is more likely to cause a photoelectric effect than a visible light. This is because photons of ultraviolet light _____?', '{"A":"Have a higher energy","B":"Have a longer wavelength","C":"Have higher velocity","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Photoelectric effect occurs when photons have energy E = hv greater than the work function of the material.Ultraviolet light has a higher frequency (shorter wavelength) than visible light, so its photons carry more energy, making the effect more likely.', 0, 0, 0, 1790968057448) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_55cf3e91edbda6f6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The dimension formula of angular momentum is?', '{"A":"[M L T⁻²]","B":"[M L² T⁻¹]","C":"[M L² T⁻²]","D":"[M L T⁻¹]"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Angular momentum = Moment of Inertia × Angular Velocity Moment of Inertia = Mass × (Length)² → [M L²] - Angular Velocity = [T⁻¹]= [M L²] × [T⁻¹] = [M L² T⁻¹].....The dimensional formula of momentum is:[M L T⁻¹]', 0, 0, 0, 1790968057477) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3bd3b6e96af5aad4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The angular acceleration is produced by _______?', '{"A":"Momentum","B":"Pressure","C":"Torque","D":"Power"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Angular acceleration is produced by torque. Torque is the rotational equivalent of force. And just as force causes linear acceleration, torque causes angular acceleration.', 0, 0, 0, 1790968057477) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_50763e9ff8306f93', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The focal length of thin convex lens is _____?', '{"A":"Greater than that of thick convex lens","B":"Smaller than that of thick convex lens","C":"Equal than that of thick convex lens","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A thinner convex lens has a longer focal length because it bends light rays less sharply than a thicker convex lens.A thicker convex lens has a shorter focal length as it bends light rays more strongly, bringing them to focus sooner.', 0, 0, 0, 1790968057477) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a4f640fb4733c571', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'What temperature is same in Centigrade and Fahrenheit scale?', '{"A":"70 degree","B":"60 degree","C":"-50 degree","D":"-40 degree"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Celsius and Fahrenheit are two temperature scales. The Fahrenheit and Celsius scales have one point at which they intersect. They are equal at -40°C and -40°F.', 0, 0, 0, 1790968057477) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_afa406f298982c0b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'What is the direction of energy flow in an ecosystem?', '{"A":"Always unidirectional","B":"Always bidirectional","C":"In any direction","D":"Always down directional"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The direction of energy flow in an ecosystem is unidirectional, moving through various trophic levels successively. It begins with the input of solar energy, which is captured by primary producers, such as plants, through photosynthesis.', 0, 0, 0, 1790968057477) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_adebbbd10e5531e1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', '1 kilowatt hour (kWh) is the energy equal to _____?', '{"A":"3,600,000 J","B":"7,200,000 J","C":"1,800,000 J","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 1 kilowatt hour (kWh) = 1000 watts × 3600 seconds1 kWh = 1,000 × 3,600 = 3,600,000 joules (J)', 0, 0, 0, 1790968057477) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b402ed42bd97716f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The original source of energy for biomass is _______?', '{"A":"Sun","B":"Moon","C":"Star","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Biomass energy comes from plants, which get their energy through photosynthesis using sunlight.So, the Sun is the original source of energy for all biomass.', 0, 0, 0, 1790968057477) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2352ec5a624db4c5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The area near an electric charge within which it exerts force on another charged particle is called ______?', '{"A":"Source charge","B":"Electric Field","C":"Coulomb","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An electric field is the region around a charged particle where it exerts a force on other charges.It is represented by field lines.It is measured in newtons per coulomb (N/C).', 0, 0, 0, 1790968057477) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9fa3fd3907512902', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'With altitude air pressure ?', '{"A":"increase","B":"Decrease","C":"Not change","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation As altitude increases, pressure decreases because there is less air above, resulting in less weight pressing down. This causes the air to become less dense and "thinner," meaning there are fewer air molecules in a given volume. Pressure measures force per unit area, with SI units of pascals (1 pascal = 1 newton per square metre, 1 N/m2).', 0, 0, 0, 1790968057512) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7c2bb94b4a198d70', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which is the path through which electric current passes?', '{"A":"Electric circuit","B":"Electric field","C":"Insulator","D":"Resistor"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An electric circuit is a closed path through which electric current flows.It enabling the transfer of electrical energy.Electric current is measured in amperes using an ammeter.', 0, 0, 0, 1790968057512) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_da4c3228ce71fd39', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Orbitals having same energy are called ______?', '{"A":"Degenerate orbitals","B":"Hybrid orbitals","C":"Valance orbitals","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Orbitals that have the same energy level are called degenerate orbitals. This concept is important in understanding electron behavior and how they fill atomic orbitals, following principles like the Aufbau principle and Hund''s rule. For example, in a hydrogen atom, all orbitals with the same principal quantum number (n) are degenerate.', 0, 0, 0, 1790968057512) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8e1ad9119c3c4625', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The induced current will flow in such a direction so as to oppose the cause that produces it is statement of _______?', '{"A":"Lenz''s Law","B":"Joule''s Law","C":"Ampere''s Law","D":"Faraday''s Law"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The induced current will flow in such a direction so as to oppose the cause that produces it is the statement of Lenz''s Law.This law reflects the principle of conservation of energy in electromagnetic induction.', 0, 0, 0, 1790968057512) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_09a9b9906db01c5f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The lens which coverage a beam of parallel rays of light are called ____?', '{"A":"Diverging lens","B":"Converging lens","C":"Cylindrical lens","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A converging lens (usually convex) bends parallel rays of light to meet at a single point (focus).It is commonly used in magnifying glasses and optical instruments.', 0, 0, 0, 1790968057512) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_98aa41146ec048f5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The unit of frequency is _____?', '{"A":"Hertz","B":"Metre","C":"Meter Per Second","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Frequency is the number of occurrences of a repeating event per unit of time.The SI unit of frequency is the hertz (Hz).1 Hz = 1 cycle or vibration per secondUnit: Hz = s⁻¹ (per second)Named after physicist Heinrich HertzUsed for waves, oscillations, sound, and electromagnetic radiationDerivations from other quantities: f = 1 / TDimension T^−1', 0, 0, 0, 1790968057512) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fc3a3895cdf7f8aa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'What is the SI unit of acceleration?', '{"A":"m/s²","B":"m/s","C":"s/s²","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The SI unit of acceleration is meters/second^2 (m/s^2 or ms^-2)Acceleration (a) is defined as the rate of change of velocity. Velocity is a vector quantity, and therefore acceleration is also a vector quantity.', 0, 0, 0, 1790968057512) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ba1d15d3dabc7821', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Who is known as the Father of Electricity?', '{"A":"Thomas Edison","B":"Nikola Tesla","C":"Graham Bell","D":"Michael Faraday"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Michael Faraday is known as the Father of Electricity.He discovered the laws of electromagnetism.He also built the first electric generator and first electric motor.PersonKnown as the Father ofTheophrastusBotanyGalileo GalileiModern PhysicsAlexander Graham BellTelephoneMichael FaradayElectricity', 0, 0, 0, 1790968057512) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2c05bdc49f5dad42', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Albert Einstein is best known for his ______?', '{"A":"Research on Universe","B":"Ideas about human development","C":"Theory of Relativity","D":"Theory of Evolution"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Albert Einstein is one of the most influential physicists of the 20th century.In 1905 Einstein published four landmark papers in physics.Einstein was awarded the Nobel Prize for his work on: Special theory of relativityAlbert Einstein received his Nobel Prize one year later, in 1922.', 0, 0, 0, 1790968057542) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_122462243286f082', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'If the distance between two points charges is doubled and force between them will become _____?', '{"A":"1/4","B":"1/2","C":"4 times","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation According to Coulomb’s Law, force is inversely proportional to the square of distance: F∝ 1/r².So, if distance is doubled, force becomes 1/(2)² = 1/2.', 0, 0, 0, 1790968057542) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_41f25170535a46b6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The measuring unit of pressure is ____?', '{"A":"Kelvin/Square Inch","B":"Pounds/Square Inch","C":"Ampere/Square Inch","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pressure is typically measured in units of force per unit area.In the Imperial system, pressure is commonly measured in Pounds per Square Inch (PSI).This is a widely used unit of pressure in engineering, physics, and many other fields.Other common units of pressure include:Atmospheres (atm)BarsPascals (Pa)Torr', 0, 0, 0, 1790968057542) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_16d94cc482a69bb8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'What is the S.I unit of temperature?', '{"A":"Kelvin","B":"Centigrade","C":"Fahrenheit","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The SI unit of temperature as per the International System of Units is Kelvin.It is represented by the symbol K.Note:Celsius is currently a derived unit for temperature in the SI system, Kelvin is the base unit.', 0, 0, 0, 1790968057542) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7e7bb1f25682d410', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'If a body moves with uniform velocity, then the distance time graph is ______?', '{"A":"Curve","B":"Straight line","C":"Parabola","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In uniform velocity, distance increases linearly with time.Hence, the distance–time graph is a straight line with constant slope.', 0, 0, 0, 1790968057542) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9f6187d792e36809', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Newton''s first law of motion is also called as?', '{"A":"Law of conservation of energy.","B":"Law of momentum.","C":"Law of inertia.","D":"Law of force."}', 'C', NULL, 0, 0, 0, 1790968057542) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a5199ba7d67c3cb6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which one of following is not an electromagnetic wave? Sound Wave, Infrared Rays, Radio Wave, X-Ray', '{"A":"Sound Wave","B":"Infrared Rays","C":"Radio Wave","D":"X-Ray"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sound wave is a mechanical wave.Electromagnetic waves are waves that consist of oscillating electric and magnetic fields That propagate through space without needing a medium. Sound waves, on the other hand, are mechanical waves that require a medium (like air, water, or solids) to travel through.', 0, 0, 0, 1790968057542) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_455b9847d69274a6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Kirchhoff''s Voltage Law (KVL) is based on the principle of conservation of ______?', '{"A":"Momentum","B":"Energy","C":"Mass","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kirchhoff’s Voltage Law (KVL) states that the algebraic sum of voltages around a closed loop is zero.This is based on the principle of conservation of energy, as energy is neither created nor destroyed in the loop.', 0, 0, 0, 1790968057542) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_658eb1755c42cb27', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'What is the SI unit of velocity?', '{"A":"m²-sec","B":"m/s","C":"m·s⁻¹","D":"Both B and C"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Velocity SI units: meters per second (m/s or m·s⁻¹).This unit is derived from the SI units for displacement (meter) and time (second), Velocity is defined as the rate of change of displacement over time (displacement/time).', 0, 0, 0, 1790968057570) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3f53cae6e6d0a0de', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'What is Unit of Power of a Lens?', '{"A":"Meter","B":"Watt","C":"Diopter","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The power of the lens is the reciprocal of focal length. The SI unit is dioptre.Dioptre (D)Power of lens = 1/ focal length in meter.', 0, 0, 0, 1790968057570) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d4794a3274a34255', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'What type of energy do solar cells convert?', '{"A":"Kinetic energy to electrical energy","B":"Thermal energy to electrical energy","C":"Solar (Sun''s) energy to electrical energy","D":"Chemical energy to electrical energy"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Solar cells, also known as photovoltaic cells, convert solar energy (sunlight) directly into electrical energy.They work by using semiconductor materials to absorb photons from sunlight and release electrons, generating electricity.', 0, 0, 0, 1790968057570) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7f827ad03ac07f2d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The force, which is always directed towards the same point is called as _____?', '{"A":"Central force","B":"Gravitational force","C":"Centripetal force","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A central force always acts along the line joining the object and a fixed point (the center).Gravitational and centripetal forces are specific examples of central force.', 0, 0, 0, 1790968057570) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c7aba2003b57cc6e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which one of the following is the direct source of energy in living bodies?', '{"A":"Glucose","B":"Fatty acid","C":"ATP","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ATP (Adenosine Triphosphate) is the direct source of energy in living bodies.Glucose and fatty acids provide energy indirectly, but ATP is the immediate usable energy currency.', 0, 0, 0, 1790968057570) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_34a64c36f5284afd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Absolute temperature is the temperature at which _____?', '{"A":"Mass becomes zero","B":"All molecular motion ceases","C":"Volume becomes zero","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Absolute temperature (0 K) is the theoretical lowest temperature.At this point, all molecular motion stops, and the system has minimum internal energy.', 0, 0, 0, 1790968057570) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_24b8d613eef899a8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The turning effect of force is called _____?', '{"A":"Moment","B":"Momentum","C":"Torque","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Turning effect of force is called torqueTorque is used to measure coupling while the moment is not.Both torque and moment have the Newton meter as the SI unit; torque is presented as Nm/revolution while moment is presented as Nm.Moment is a static force while torque is a movement force.', 0, 0, 0, 1790968057570) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c57993e56f926dce', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The splitting of white light into seven colors on passing through a glass prism is due to ______?', '{"A":"Diffraction","B":"Refraction","C":"Interference","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When white light passes through a prism, different wavelengths bend by different amounts.This dispersion due to refraction splits light into seven colors (VIBGYOR).', 0, 0, 0, 1790968057570) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8aab253a68bd4e8e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The process whereby energy is dissipated from the oscillating system is called _____?', '{"A":"Resonance","B":"Damping","C":"Oscillation","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Damping is the process in which oscillation amplitude decreases due to energy loss (like friction or resistance).It gradually reduces the motion of the system.', 0, 0, 0, 1790968057616) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_986fa29809d6a0e0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which of the following waves have smallest velocity in vacuum?', '{"A":"Sound","B":"Infrared","C":"Microwave","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In a vacuum, sound cannot travel at all (velocity = 0 m/s) because it needs a medium.Electromagnetic waves (infrared, microwave, ultraviolet) all travel at the speed of light in vacuum.', 0, 0, 0, 1790968057616) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_674ea38b69a75107', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Osmotic pressure of a solution is increased by ______?', '{"A":"Increasing the number of molecules of solute","B":"Decreasing the temperature","C":"Increasing both temperature and volume","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Osmotic pressure (π) is directly proportional to solute concentration (π = iCRT).More solute molecules → higher concentration → greater osmotic pressure.', 0, 0, 0, 1790968057616) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2c18a5956d6ea4ea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which one of the following units represents the largest amount of energy?', '{"A":"Joule","B":"Calorie","C":"Electron Volt","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Calorie is a larger unit of energy.1 Calorie ≈ 4.184 Joules.1 Joule = 10⁷ Ergs.1 Electron Volt (eV) = 1.602 × 10⁻¹⁹ Joules.Calorie is commonly used to measure energy in food and metabolic processes.', 0, 0, 0, 1790968057616) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_16abbf9c635e61a1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', '"X" is an imaginary plane which divides a crystal into two equal halves which are the exact mirror images of each other. The proper term for "X" is _____?', '{"A":"Axis of rotation","B":"Plane of symmetry","C":"Center of symmetry","D":"Axis of Inversion"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The proper term for "X" is Plane of symmetry. A plane of symmetry is an imaginary plane that divides a crystal into two halves, where each half is the mirror image of the other.', 0, 0, 0, 1790968057616) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1047316330332f50', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'If the temperature of the source of heat increases the efficiency of a Carnot engine?', '{"A":"Increases","B":"Decreases","C":"Remain constant","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation If the temperature of the source of heat increases, the efficiency of a Carnot engine will increase. The efficiency of a Carnot engine is directly related to the temperature difference between the hot and cold reservoirs. A higher source temperature leads to a greater temperature difference and thus, a higher efficiency.', 0, 0, 0, 1790968057616) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f0d0b619332b1cea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'When sound waves move from one medium to another the quantity which remains the same is?', '{"A":"Wavelength","B":"Frequency","C":"Speed","D":"Intensity"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When a sound wave moves from one medium to another, the quantity that remains the same is its frequency. The frequency of a sound wave is determined by the source of the sound and doesn''t change when it enters a different medium. However, the wavelength and speed of the wave can change depending on the properties of the new medium.', 0, 0, 0, 1790968057616) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_75b84b9b43f55ac4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which of the following type of force do not work?', '{"A":"Elastic force","B":"Frictional force","C":"Gravitational force","D":"Centripetal force"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A centripetal force always acts perpendicular to the direction of an object''s motion.Meaning it doesn''t contribute to the object''s speed or change in kinetic energy, which is the definition of work.', 0, 0, 0, 1790968057616) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6e948d07532c721f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'When a body moves against the force of friction on a horizontal plane, the work done by the body is?', '{"A":"Negative","B":"Positive","C":"Zero","D":"Maximum and positive"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When a body moves against the force of friction on a horizontal plane, the work done by the body is negative. This is because work is defined as the dot product of force and displacement, And when moving against friction, the force of friction acts in the opposite direction to the displacement of the body, Resulting in an angle of 180 degrees between them.', 0, 0, 0, 1790968057646) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8947d5b1b4f45db2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'A mass accelerates uniformly when the resultant force acting on it _____?', '{"A":"Is zero","B":"Is constant but not zero","C":"Increases uniformly with respect to time","D":"Is proportional to the displacement of mass from a fixed point"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation According to Newton''s second law, F=ma, a constant non-zero force results in uniform acceleration of the mass.', 0, 0, 0, 1790968057646) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_50e59fe18a3e54d6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The dimension of work is like the dimension of _____?', '{"A":"Impulse","B":"Torque","C":"Power","D":"Angular momentum"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The dimension of work is like the dimension of Torque. Both work and torque have the same dimensional formula: [ML²T⁻²]However, they are physically different quantities: - Work is a scalar (dot product of force and displacement). - Torque is a vector (cross product of force and radius).', 0, 0, 0, 1790968057646) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_08e414adc3e1e63a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Diode can work as _____?', '{"A":"Rectifier","B":"Oscillator","C":"Multi-vibrator","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A diode allows current in one direction only, blocking the reverse.This property makes it useful as a rectifier, converting AC into DC.', 0, 0, 0, 1790968057646) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_731ab027892866c1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'A motorist travels from A to B at a speed of 40 km/h and returns at a speed of 60 km/h. His average speed will be?', '{"A":"48 km/h","B":"50 km/h","C":"60 km/h","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation For equal distances, average speed = harmonic mean = 2𝑎𝑏/𝑎+𝑏 = 2⋅40⋅60/40+60 = 48.Not the arithmetic mean (which would be 50) because travel times differ.', 0, 0, 0, 1790968057646) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_933bf16cf2d2abaf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which of these is a scalar quantity? Velocity, Acceleration, Speed, Force', '{"A":"Velocity","B":"Acceleration","C":"Speed","D":"Force"}', 'C', NULL, 0, 0, 0, 1790968057646) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_823c5f49e4bf05fc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The SI Unit of Heat is _____?', '{"A":"Watt","B":"Volt","C":"Joule","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The SI unit of heat is the joule (J). Heat is a form of energy.The joule is the standard unit for energy in the International System of Units (SI). For instance, 1 joule of heat is the energy required to raise the temperature of 1 gram of water by 0.24°C.', 0, 0, 0, 1790968057646) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2bb712dceb4573dd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The rate of change of angular momentum is called?', '{"A":"Torque","B":"Force","C":"Work","D":"Angular velocity"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Torque is the rotational analog of force and equals the rate of change of angular momentum.Common symbols, T, MSI unit N⋅mOther units pound-force-feetIn SI base units kg⋅m2⋅s−2', 0, 0, 0, 1790968057646) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e72196b297700dad', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which of the following is longitudinal waves? Sound waves ,Light waves, Water waves, Electromagnetic waves', '{"A":"Sound waves","B":"Light waves","C":"Water waves","D":"Electromagnetic waves"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Longitudinal waves are also called: Compressional waves, Pressure waves, Compression waves.A longitudinal wave is a wave in which the particles of the medium vibrate in the same direction as the wave propagates.', 0, 0, 0, 1790968057674) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_75363471f58e61bc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The phenomenon of bending of light around edges of an obstacle are called _____?', '{"A":"Reflection","B":"Refraction","C":"Diffraction","D":"Dispersion"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Diffraction is the bending of light waves around obstacles or through small openings, causing the waves to spread out.This phenomenon occurs when the size of the obstacle or opening is comparable to the wavelength of light.', 0, 0, 0, 1790968057674) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_09869ee46b1445c7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which device is used to convert Alternating Current (AC) to Direct Current (DC)?', '{"A":"Inventor","B":"Rectifier","C":"Conductor","D":"Semiconductor"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A device that is used to convert AC voltage into DC voltage is called A Rectifier.Inverters and rectifiers are electronic circuits that can change the type of electric current.a rectifier converts AC to DC.An inverter converts DC to AC,Additional information:Semiconductor: the materials that have a conductivity between conductors and insulators are called semiconductors.Conductor: The material that has very high conductivity is called a conductor.', 0, 0, 0, 1790968057674) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7378b216d8dc0db1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'What is the SI unit of work or energy?', '{"A":"Horsepower","B":"Hertz","C":"Joule","D":"Ampere"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The SI unit of work or energy is the joule (J)Definition: Work done when a force of one newton moves an object one meter in the direction of the force.Expression: 1 J = 1 N·mBase units: Equivalent to kg·m²/s²Named after: James Prescott Joule, the English physicistCommon multiples: Kilojoule (kJ = 10³ J), megajoule (MJ = 10⁶ J)', 0, 0, 0, 1790968057674) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d51b55446ed0b02c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The energy due to motion is called _______?', '{"A":"Kinetic energy","B":"Potential energy","C":"Chemical energy","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kinetic energy is the energy an object possesses due to its motion.The faster the object moves, the more kinetic energy it has.', 0, 0, 0, 1790968057674) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_129a3621b1a377e2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which lens is used for the correction of long-sightedness?', '{"A":"Convex lens","B":"Concave lens","C":"Compact lens","D":"Conpave lens"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A convex lens has either one or both of its surfaces curving outwards, that is, wider divergence from the plan at the center. These lenses are used to correct long-sightedness (hypermetropia).', 0, 0, 0, 1790968057674) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_60069724b6d02b51', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Electric current is measured by ____?', '{"A":"Ammeter","B":"Ohmmeter","C":"Multimeter","D":"Both A and C"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Electric current can be measured by both an ammeter and a multimeter. An ammeter is a specialized device that measures only electric current. At the same time, a multimeter is a versatile tool that combines multiple functions, Including the ability to measure current like an ammeter, as well as voltage, resistance, and other electrical properties.', 0, 0, 0, 1790968057674) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a6c3464e24dfe401', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Escape velocity from the earth surface is ______?', '{"A":"9.1 km/sec","B":"11.2 km/sec","C":"1.7 km/sec","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Escape velocity is the minimum speed required for an object to escape Earth''s gravitational field without further propulsion.On Earth, this velocity is 11.2 km/s.It calculated using the formula vₑ = √(2GM/R), where G is the gravitational constant, M is Earth''s mass, and R is its radius.', 0, 0, 0, 1790968057674) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7b52edc4140b4b20', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The process in which pressure remains constant is called ______?', '{"A":"Isobaric","B":"Isothermal","C":"Adiabatic","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Iso-” means constant; “baric” relates to pressure. In an isobaric process, pressure remains unchanged. Volume or temperature can change during the process. Examples: heating a gas in a piston-cylinder system at constant atmospheric pressure. Isochoric = constant volume, isothermal = constant temperature, adiabatic = no heat transfer.Last updated question 25 feb 2026', 0, 0, 0, 1790968057704) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_75e8b6d6765cb965', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The dimensions of kinetic energy are?', '{"A":"ML²T⁻²","B":"ML⁻²T⁻²","C":"ML²T⁻²","D":"½ ML²T⁻²"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kinetic energy (KE) is expressed as: KE = 1/2 * mv² Where: m = mass (dimensions: M¹), v = velocity (dimensions: L¹T⁻¹), and v² = (L¹T⁻¹)² = L²T⁻². Therefore, the dimensions of KE are: KE = M¹ * (L²T⁻²) = M¹L²T⁻²', 0, 0, 0, 1790968057704) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9c0dbaf50b918c96', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The energy stored in coal is _____?', '{"A":"Kinetic Energy","B":"Chemical Energy","C":"Potential Energy","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The energy stored in coal is classified as chemical energy.It is released during combustion when the chemical bonds in the coal are broken.This energy is harnessed for heating and electricity generation.', 0, 0, 0, 1790968057704) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bab92f13c7891285', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Concave lens causes rays to _____?', '{"A":"Spread apart","B":"Diverge","C":"Both A and B","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A concave lens causes light rays to diverge or spread apart after passing through it.That''s why it’s also called a diverging lens.', 0, 0, 0, 1790968057704) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c2585f5b7deb3516', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Law of conservation of momentum defines that the total momentum of a system of two bodies before and after collision ______?', '{"A":"Remains constant","B":"Retains more momentum","C":"Losses some momentum","D":"None of the above is true"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The law of conservation of momentum states that the total momentum of a closed system (such as a system of two bodies) remains constant over time, as long as there are no external forces acting on the system.This means that the total momentum before a collision is equal to the total momentum after the collision.', 0, 0, 0, 1790968057704) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bd5e2d70f0ba1279', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which colour has largest wavelength in the spectrum of white light?', '{"A":"Violet","B":"Green","C":"Red","D":"Blue"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Red light has the longest wavelength, approximately 620-750 nanometers (nm).While violet light has the shortest wavelength, approximately 380-450 nm.The order of colours in the spectrum, from longest to shortest wavelength, is: Red, Orange, Yellow, Green, Blue, Indigo, Violet (ROYGBIV).', 0, 0, 0, 1790968057704) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_142ca606a68eabee', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Light travels in a ______?', '{"A":"Curved Path","B":"Zigzag Pattern","C":"Straight Line","D":"Circular Motion"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Light travels in a straight line.It is also known as a rectilinear path.It in a homogeneous medium like air or vacuum.', 0, 0, 0, 1790968057704) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e0a119722c0c551f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'A car travels east at constant velocity. The net force on the car is ______?', '{"A":"Zero","B":"Up","C":"East","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When a car moves at constant velocity, it means there is no acceleration.According to Newton’s First Law, if there’s no acceleration, the net force acting on the object is zero.', 0, 0, 0, 1790968057704) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4f972d46589ab2b6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'What is the work done by a centripetal force?', '{"A":"Zero","B":"Positive","C":"Negative","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Centripetal force acts perpendicular to the direction of motion, so it does no work.Work = Force × Displacement × cos(θ); since θ = 90°, cos(90°) = 0, so Work = 0.', 0, 0, 0, 1790968057734) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6506393d5e95bacf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which of the following is not a vector quantity?Work, Mass, Distance, All of these', '{"A":"Work","B":"Mass","C":"Distance","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Work, mass and distance are scalar quantities because they have magnitude but no direction, but they are not vector quantities.Vector Quantities: Velocity, momentum, torque, acceleration, weight, displacement.Scalar Quantities: Work, distance, speed, mass.', 0, 0, 0, 1790968057734) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ee5049475df9bacb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'A reaction in which heat energy is absorbed or taken into the system is called __________?', '{"A":"Exothermic reaction","B":"Endothermic reaction","C":"Elimination reaction","D":"Thermite reaction"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A reaction in which heat is absorbed is called an endothermic reaction.These reactions lower the temperature of their surrounding area, thereby creating a cooling effect.', 0, 0, 0, 1790968057734) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_56c08ec7326828ca', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The trade/commercial unit of electrical energy is?', '{"A":"KMN","B":"KEH","C":"KWH","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A kilowatt-hour (unit symbol: kW⋅h or kW h; commonly written as kWh) is a non-SI unit of energy equal to 3.6 megajoules (MJ) in SI units .Kilowatt-hours are a common billing unit for electrical energy supplied by electric utilities.', 0, 0, 0, 1790968057734) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_94b752229e20ebf9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which component of the body works as an energy storage device?', '{"A":"Fats","B":"Proteins","C":"Liver","D":"Skin"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fats are the body’s primary energy storage molecules, stored in adipose tissue.They provide long-term energy and insulation when carbohydrates are depleted.', 0, 0, 0, 1790968057734) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2720f74d44a5f76d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Instrument used for measuring very high temperature is _____?', '{"A":"Hydrometer","B":"Cyclometer","C":"Calorimeter","D":"Pyrometer"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Pyrometer is used for measuring very high temperatures.Pyrometers can measure temperatures without direct contact.This making them ideal for extreme conditions.', 0, 0, 0, 1790968057734) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7a5770500e454b1d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Two major products of light reaction of photosynthesis are ______?', '{"A":"ATP & NADPH","B":"NADPH & CoA","C":"ATP & NADH","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The two major products of the light reaction of photosynthesis are ATP & NADPH.ATP provides energy, while NADPH acts as a reducing agent for the Calvin cycle.', 0, 0, 0, 1790968057734) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_430c86e08f2026c6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Distillation under very reduced pressure is ____ distillation.', '{"A":"Destructive","B":"Fractional","C":"Steam","D":"Vacuum"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Vacuum distillation is used to distill substances at lower temperatures by reducing the pressure, which lowers the boiling point of the substances.', 0, 0, 0, 1790968057734) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9f87fc8c3d5a63ed', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Spectrum of light formed by the radiation given off by a substance is called _____?', '{"A":"Line spectrum","B":"Continuous spectrum","C":"Emission spectrum","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Emission spectrum is produced when a substance emits light/radiation, showing specific wavelengths.It consists of bright lines or bands on a dark background, unique to each element.', 0, 0, 0, 1790968057765) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_089b9ef14e52ebba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The velocity of photon is _____?', '{"A":"Independent at its wavelength","B":"Depend on its wavelength","C":"Equal to square of its amplitude","D":"Depends on its source"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The velocity of a photon is independent of its wavelength. The velocity of a photon is determined by the speed of light in a vacuum, which is a constant value (approximately 299,792,458 meters per second) and does not change based on the photon''s wavelength or amplitude. The speed of light is a fundamental constant of nature.', 0, 0, 0, 1790968057765) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f914e5f4b52e3880', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The distance between two charges reduced to half, then coulombs force would become ______?', '{"A":"Four Times","B":"One Fourth","C":"Half","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation According to Coulomb''s Law, the force between two charges is inversely proportional to the square of the distance between them.If the distance is halved, the force becomes four times stronger.', 0, 0, 0, 1790968057765) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9dcb020a2c1a6068', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'If potential difference between plates of parallel plate capacitor is doubled then energy stored in it will ______?', '{"A":"Remains same","B":"Two times","C":"Four times","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The energy stored in a capacitor is given by U = (1/2)CV². If the potential difference (V) is doubled:U ∝ V²U'' ∝ (2V)² = 4V²So, the energy stored will increase by a factor of 4.', 0, 0, 0, 1790968057765) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ef2d8f7c3bb33c43', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The Sl unit of energy density of electric field is ______?', '{"A":"J/m²","B":"J/C","C":"J/m³","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Energy density is defined as energy per unit volume, so the SI unit is joules per cubic meter (J/m³).It applies to electric fields where𝑢 = 1/2𝜀𝐸², with 𝑢 being energy density.', 0, 0, 0, 1790968057765) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d1077b59ff7c23f0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The weight of a man in an elevator descending with an acceleration of 4.9 ms⁻² will become?', '{"A":"Twice","B":"Zero","C":"Half","D":"Unchanged"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The weight of a man in an elevator descending with an acceleration of 4.9 m/s² will become:Let: Actual weight W=mg Acceleration due to gravity g=9.8m/s^2 Acceleration of the elevator a=4.9m/s^2 When an elevator descends with acceleration aa, the apparent weight becomes:W′=m(g−a) Substitute values:W′=m(9.8−4.9)=m(4.9)W′=1​/2×mg So, the apparent weight becomes half of the actual weight.', 0, 0, 0, 1790968057765) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e230cca7da36b348', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Angular frequency is basically a characteristic of ______?', '{"A":"Circular motion","B":"Linear motion","C":"Vibratory motion","D":"Elliptical motion"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Angular frequency (ω) measures how quickly something moves through an angle in circular motion. It''s given by: omega = frac{2pi}{T} = 2pi fω=2π​/T=2πf Where: TT = time period ff= frequency While it’s also used in oscillations, it is fundamentally defined from circular motion.', 0, 0, 0, 1790968057765) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c9b4855350f8e6ed', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The slope of a velocity-time graph at any instant represents ______?', '{"A":"Instantaneous acceleration","B":"Instantaneous velocity","C":"Work done","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The slope of a velocity-time graph gives the rate of change of velocity, which is acceleration.At any instant, this slope shows the instantaneous acceleration.', 0, 0, 0, 1790968057765) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a29261fd5b9c8b84', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The angular momentum L is given by?', '{"A":"mω","B":"ω × F","C":"r × f","D":"r × p"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Angular momentum (L) is defined as the cross product of the position vector (r) of a particle with its linear momentum (p) relative to a chosen origin.', 0, 0, 0, 1790968057801) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0a361b52f6f40c87', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The type of lens found in human eye is _____?', '{"A":"Convex Lens","B":"Curved Lens","C":"Concave Lens","D":"All of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A biconvex lens is the type of lens found in the human eye, and it is responsible for forming genuine imagesThe lens, or crystalline lens, is a transparent biconvex structure in most land vertebrate eyes (We are all vertebrates)***The image formed at the retina of the human eye is real and inverted.ND-8-08-2023', 0, 0, 0, 1790968057801) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_18fe90584ab3e0f4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The current which flows in one direction is called _____?', '{"A":"Alternating current","B":"Direct current","C":"Fixed current","D":"Variable current"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Direct current is produced when electrons flow constantly in one direction. It''s abbreviated as "DC". Since direct current flows in one direction only, its electrical pressure or voltage is always oriented in one direction, or "polarity".', 0, 0, 0, 1790968057801) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_221d6a0c9019da6a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Suitable temperature for photosynthesis is between _____?', '{"A":"25° to 35°","B":"25° to 30°","C":"15° to 30°","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Photosynthesis occurs most efficiently in this temperature range, as enzymes involved in the process function optimally.Temperatures above 35°C can inhibit enzyme activity, reducing the rate of photosynthesis.', 0, 0, 0, 1790968057801) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_64ad4fa290800f28', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'When an object reflects the entire component colours of light, it appears ____?', '{"A":"White","B":"Black","C":"Green","D":"Dark"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When an object reflects all the component colors of light, it appears white.This is because the object is reflecting all the wavelengths of visible light, which are then perceived by our eyes as white.If an object absorbs all seven colors of light (i.e., all the wavelengths of visible light), it appears black.', 0, 0, 0, 1790968057801) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d25760b3e569ff12', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Sound travels fastest in _______?Air ,Water ,Diamond ,Steel', '{"A":"Air","B":"Water","C":"Diamond","D":"Steel"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sound travels fastest in diamond, With a speed of approximately 12,000 meters per second (m/s).Because sound travels fastest in stiff, dense materialsAdditional information The speeds of sound in different materials:Air: 343 m/sWater: 1433 m/sWood: 3300-3600 m/sBrick: 4176 m/sSteel: 6100 m/sDiamond: 12000 m/s', 0, 0, 0, 1790968057801) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_71ec56992fd3f84a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The straight line passing through the pole (P) and the center of curvature (C) of a mirror is called the _______ of that mirror.', '{"A":"Principal Axis","B":"Principal Focus","C":"Pole","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The principal axis is a straight line passing through the center of curvature and the pole of a spherical mirror.It serves as the reference line for measuring distances and analyzing image formation in mirrors.', 0, 0, 0, 1790968057801) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1f34387cc7f2874b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'If one of the surfaces of a lens is concave and the other is convex such that the central region of the lens is thinner than its edges, is is called _____?', '{"A":"Convex concave lens","B":"Double convex lens","C":"Concave convex lens","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A lens with one concave surface and one convex surface, where the central region is thinner than the edges, is called a concave convex lens (also known as a plano-concave lens).This type of lens diverges light rays passing through it', 0, 0, 0, 1790968057801) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b9c92a161fe52230', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The conversion of Alternating Current (AC) into Direct Current (DC) is carried by ______?', '{"A":"Anemometer","B":"Battery","C":"Rectifier","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A rectifier is an electrical device that converts Alternating Current (AC) into Direct Current (DC).It works by allowing current to flow only in one direction using diodes.', 0, 0, 0, 1790968057833) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_66b57f0429cc253d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Wind energy is the ______ energy.', '{"A":"Potential","B":"Transverse","C":"Kinetic","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The wind is used to produce electricity by converting the kinetic energy of air in motion into electricity.Wind energy is the energy obtained from the force of the wind.The unit of wind is: joule', 0, 0, 0, 1790968057833) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_453ef2b2dace478d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Joule is the unit of ______?', '{"A":"Joule","B":"Energy/Heat","C":"Work","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Joule is a unit of work or energy or heat.Joule is a scalar quantity.SI base units: kg⋅m2⋅s−2Symbol: JAdditional Information:It is equal to the work done by the force of one newton acting through one meter.Named in honor of the English physicist James Prescott Joule.Joule equals 107 ergs or approximately 0.7377 foot-pounds.', 0, 0, 0, 1790968057833) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_097001e47b5f3086', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Light is a form of ______?', '{"A":"Kinetic Energy","B":"Heat Energy","C":"Potential Energy","D":"Electrical Energy"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Light is a form of energy.Light is actually energy made of small particles called photons.Another name for light energy is electromagnetic energy.', 0, 0, 0, 1790968057833) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_081cab306a10f31a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Materials which do not allow heat to flow through them are called ____?', '{"A":"Insulators","B":"Diodes","C":"Blockers","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Materials are classified based on how they conduct heat.- Conductors: Allow heat to pass through easily (e.g., metals like copper, iron).- Insulators: Do not allow heat to flow through easily.- Examples of insulators: Wood, plastic, rubber, glass.- Used in cooking handles, thermal flasks, and electrical wire coatings.', 0, 0, 0, 1790968057833) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3e48032ce60cbe4c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'When ice cream is melting down, what type of energy is decreasing in it?', '{"A":"Thermal","B":"Electrical","C":"Chemical","D":"Light"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation As ice cream melts, it absorbs thermal energy from the surroundings, but its internal thermal energy decreases as it changes from solid to liquid.This is a physical change.', 0, 0, 0, 1790968057833) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cb5fa60ea20d4e91', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Pascal is the SI unit of pressure and 1 Pa = ______?', '{"A":"760 N/m²","B":"50 N/m²","C":"1 N/m²","D":"None of these"}', 'C', NULL, 0, 0, 0, 1790968057833) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_497005fabbf4f32c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which of the following is a renewable source of energy?', '{"A":"Water","B":"Coal","C":"Gas","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Non-renewable energy sources:OilNuclear energyPetroleumNatural gas & coalRenewable sources of energy:Solar energyWind energyHydroelectric powerBiomass energyGeothermal energyTidal energy', 0, 0, 0, 1790968057833) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9696d092e0696a67', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The melting point of pure ice at Standard Temperature and Pressure (STP) is?', '{"A":"0°C","B":"100°C","C":"200°C","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The melting point of ice at 1 atmosphere of pressure is very close to 0°C.This temperature is also referred to as 32°F or 273 K.It is commonly known as the "ice point" where ice transitions from solid to liquid.', 0, 0, 0, 1790968057867) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7cc5b53c85f87c82', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'A wave in which the particles of the medium vibrate back and forth in the same direction, parallel to the motion of the wave, is called _____?', '{"A":"Longitudinal Wave","B":"Electromagnetic Wave","C":"Transverse Wave","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Wave motion defines the direction of energy propagation. Particle displacement can be parallel or perpendicular to wave motion. Longitudinal waves: particles vibrate parallel to wave propagation (compression and rarefaction). Examples: sound waves in air, seismic P-waves. Transverse waves: particles vibrate perpendicular; not applicable here.Last updated question 25 feb 2026', 0, 0, 0, 1790968057867) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e49f8519597e88c3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which one of the following is not a renewable energy source?', '{"A":"Hydroelectricity","B":"Fossil fuel","C":"Solar energy","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The renewable energy sources are:Water energyWind energyTidal energyHydroelectricOcean energyGeothermal energyBiomassBiogasThe non-renewable energy sources are:Fossil fuels or Hydrocarbon fuel (Oil, Natural gas, Coal)Nuclear energy', 0, 0, 0, 1790968057867) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8c22da0a8d581e22', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The formula of Pressure, P = ______?', '{"A":"F × A","B":"F × D","C":"F/A","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pressure formula is expressed as P = F/A, where P is pressure, F is force, and A is the area by which the force is applied perpendicularly.Its SI unit of pressure is Pascal (represented as Pa) Definition of Pressure: Pressure can be defined as the force acting per unit area.', 0, 0, 0, 1790968057867) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_937fe619b45e29b3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which of the following is an insulator?', '{"A":"Silver","B":"Copper","C":"Glass","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Glass is an insulator because it does not allow electricity to pass through easily.Silver, copper, and aluminum are conductors, meaning they allow electric current to flow.', 0, 0, 0, 1790968057867) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_908d2978e2315f85', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The attractive force among the molecules is stronger in _____?', '{"A":"Solid","B":"Gas","C":"Liquid","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In solids, molecules are tightly packed, and intermolecular forces are strongest. In liquids and gases, these forces are weaker, allowing movement and fluidity.', 0, 0, 0, 1790968057867) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4898e835c786ed23', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which of the following has the highest energy?', '{"A":"Alpha","B":"Beta","C":"Gamma","D":"X-rays"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Gamma rays have the highest energy among the options.They are electromagnetic waves with extremely high frequency and short wavelength.It gives them more energy compared to Alpha, Beta, and X-rays.', 0, 0, 0, 1790968057867) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cb76bfa24323020e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which type of electromagnetic radiation has the shortest wavelength and highest energy?', '{"A":"Ultraviolet rays","B":"Gamma rays","C":"X-rays","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Gamma rays have the shortest wavelength in the electromagnetic spectrum. Wavelength: Shorter than 0.01 nanometers (smaller than an atom''s nucleus)Energy & Frequency: Highest frequency and highest photon energy of any wave type.Origin: Created by radioactive atomic nuclei decay They are used in medical treatments and scientific research.', 0, 0, 0, 1790968057867) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_88b9222d549c6543', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'An equilateral prism and air have a critical angle of 45°. If the incoming ray is perpendicular to the refracting surface ______?', '{"A":"It keeps reflecting from all the three sides of the prism and never emerges out","B":"It gets reflected from second and third surfaces and emerges from the first surface","C":"It is reflected from the second surface and emerges perpendicular from the third surface","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Total Internal Reflection (TIR): Since the critical angle is 45°, and the incident ray is perpendicular to the first surface, it enters without deviation and strikes the second surface at 60° (greater than 45°), causing TIR.Emergence: After reflecting from the second surface, the ray reaches the third surface at 30°, which is less than the critical angle, so it emerges perpendicularly from the third surface.', 0, 0, 0, 1790968057899) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2394228a696e6f1c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which one of the following is not a conductor?', '{"A":"Aluminum","B":"Gold","C":"Graphite","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Aluminum, Gold, and Graphite are conductors.Aluminum is a metal that conducts electricity and heat.Gold is an excellent conductor of electricity and heat.Graphite is a form of carbon that conducts electricity.', 0, 0, 0, 1790968057899) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3fbac8a76559a556', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'If the wave length of photon is doubled _____?', '{"A":"Energy is doubled","B":"Frequency is doubled","C":"Energy is reduced by the factor of two","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Energy of a photon is given by E=hcλE = frac{hc}{lambda}​, so if the wavelength (λlambda) is doubled, energy (EE) is halved.Frequency (ff) and wavelength (λlambda) are inversely related (c=fλc = flambda), so doubling λlambda reduces ff by half.', 0, 0, 0, 1790968057899) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_61db28d22024b6bb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which is the instrument for measuring wind force/speed?', '{"A":"Hygrometer","B":"Anemometer","C":"Bolometer","D":"Galvanometer","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An anemometer is an instrument that measures wind speed.This type of anemometer has a spinning wheel.Additional Information:A hygrometer is an instrument used to measure humidityA salinometer is used to measure the salinityA bolometer is used to measure the power of incident electromagnetic radiationA barometer is used to measure air pressure in certain environment.', 0, 0, 0, 1790968057899) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a39018d64dbb9637', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which from the following is true for “Sound”?', '{"A":"Sound cannot travel through a vacuum","B":"Sound cannot travel through gases","C":"Sound cannot travel through liquids","D":"Sound cannot travel through solids"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The speed of light is much faster than the speed of sound in air.Light travels 186 thousand miles in 1 second.While sound takes almost 5 seconds to travel 1 mile.', 0, 0, 0, 1790968057899) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_01bb8d762cfc52f1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The average temperature for human ______ centigrade.', '{"A":"38","B":"39","C":"36","D":"37"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Normal adult body temperature is approximately 98.6°F (37°C) but can vary slightly between individuals.A temperature above 100.4°F (38°C) typically indicates a fever due to infection or illness.', 0, 0, 0, 1790968057899) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f75bb4211e576629', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which is the cheapest and environmentally friendly source of electricity?', '{"A":"Thermal","B":"Solar","C":"Hydroelectric","D":"Nuclear"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hydroelectric power is considered the cheapest and most environmentally friendly source of electricity.As it utilizes the energy from flowing water without emitting greenhouse gases.', 0, 0, 0, 1790968057899) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_065ed38050cc2f6b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Why is the light of an ordinary lamp hotter than that of the tube light?', '{"A":"It is due to ionization of gases","B":"It is due to incandescence","C":"Distribution of energy","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The light from an ordinary lamp is hotter than a tube light because of incandescence.The process by which light is produced through heat.In an incandescent light bulb, an electric current heats a thin metal filament until it glows and produces light.', 0, 0, 0, 1790968057899) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d03d9452db1a46c0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which light is more important for photosynthesis?', '{"A":"Violent Light","B":"Red Light","C":"Green Light","D":"All of these"}', 'B', NULL, 0, 0, 0, 1790968057939) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b9531349f7e71515', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The name of Robert Watson-Watt is associated with which of the following inventions?', '{"A":"Radio","B":"Radar technology","C":"Television","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Robert Watson-Watt: Scottish engineer and inventor.Known For: Developing the first practical radar system.First Demonstration: 1935Additional informationRadar: Stands for Radio Detection and Ranging.Function: Uses radio waves to detect and locate objects.Importance: Played a crucial role during World War II.Last updated 26-07-2026 by NA', 0, 0, 0, 1790968057939) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_98e055f244adfa3e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Tape speed is measured in _____?', '{"A":"Feet per second","B":"Meter per second","C":"Inch per second","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tape speed is measured in inch per second.', 0, 0, 0, 1790968057939) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a92fb3c0238a74a7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'What is the energy formed due to waterfall?', '{"A":"Potential energy","B":"Kinetic energy","C":"Both A and B","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation At the top of the waterfall, energy is stored in the form of gravitational potential energy but when it falls, it gets converted from potential to kinetic energyPotential energy due to the object''s height above the Earth is converted to kinetic energy as it fallsND13-5-2023', 0, 0, 0, 1790968057939) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5db1a4d8e3dd9e1a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'In the atmosphere, if the temperature is low then the pressure is ____?', '{"A":"Low","B":"High","C":"Normal","D":"All of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In a direct relationship, one variable follows the same change when it comes to increasing and decreasing. For example, Ø when the pressure increases then the temperature also increases. Ø When the pressure decreases, then the temperature decreases.', 0, 0, 0, 1790968057939) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e1c9e07779672335', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Car batteries use ____ that reacts with lead zirconate to generate electricity.', '{"A":"Sulphuric acid","B":"Nitric acid","C":"Hydrofluoric acid","D":"Hydrochloric acid"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The fluid in your lead-acid battery is called Electrolyte.It''s actually a mixture of sulphuric acid and water.', 0, 0, 0, 1790968057939) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f57e127dcae1b5a2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Imaginary horizontal line on atmosphere which represent equal atmospheric pressure?', '{"A":"Isobar","B":"Isotope","C":"Isotone","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An isobar is an imaginary line that connects places of equal barometric pressure. They can be used to find areas of low or high pressure over a large area.', 0, 0, 0, 1790968057939) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d2be239682f06569', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Light travels in a vacuum at the speed of _____?', '{"A":"146000 miles per second","B":"186282 miles per second","C":"176000 miles per second","D":"196000 miles per second"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The speed of light traveling through a vacuum is exactly 299,792,458 meters (983,571,056 feet) per second. That''s about 186,282 miles per second.A universal constant is known in equations as "c," or light speed.The speed of light in air is 2.9 × 10⁸ m/s.', 0, 0, 0, 1790968057939) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_46b50e9249601f98', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which of the following is highest energy photon?', '{"A":"Gamma rays","B":"Alpha rays","C":"Beta rays","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Gamma rays are the highest energy photons, with energies typically above 100,000 electronvolts (eV).They are a type of electromagnetic radiation, like X-rays and visible light, but with much shorter wavelengths and higher frequencies.', 0, 0, 0, 1790968057974) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6d663586d22a4229', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Microphone converts sound energy into _____?', '{"A":"Heat energy","B":"Electrical signals","C":"Optical Signals","D":"Microwaves","E":"both b & d"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A microphone converts sound into a small electrical current. Sound waves hit a diaphragm that vibrates, moving a magnet near a coil. In some designs, the coil moves within a magnet. Other microphones, such as condenser microphones, work on the principle of capacitance. ******* VU FIA PAPER 18-12-2021', 0, 0, 0, 1790968057974) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1a750301e439afbe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'An expert is interested to find the prevalence of problem energy malnutrition among children in an urban slum the most practical indicator in this survey would be?', '{"A":"Weight for height","B":"Weight for age","C":"Height for age","D":"Presence of edema at ankle region"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In assessing the prevalence of protein-energy malnutrition the most practical indicator would be weight for height. This measurement provides a quick and reliable assessment of acute malnutrition, as it reflects recent weight changes relative to height.', 0, 0, 0, 1790968057974) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fd59664dcae5bd8c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'In which component does the resistance decrease with a rise in temperature?', '{"A":"PTC Thermistor","B":"Resistor","C":"NTC Thermistor","D":"Variable Resistor"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Component: Thermistor (specifically an NTC thermistor)Why: As temperature rises, more charge carriers become available in the semiconductor materialResult: Resistance decreases with rising temperatureContrast: Most metals do the opposite — resistance increases with temperature (PTC behavior)', 0, 0, 0, 1790968057974) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_90a22318268d1668', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'A residual-current device (RCD) is widely used in electrical circuits?', '{"A":"For voltage regulation","B":"For shock safety","C":"For leakage current detection","D":"For circuit breaker"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A residual-current device (RCD) is widely used in electrical circuits for shock safety.It detects leakage currents and disconnects the circuit to prevent electric shocks.', 0, 0, 0, 1790968057974) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cd287c7cc48e37de', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which one of the following is not a factor affecting the resistance of a material?', '{"A":"Type of material","B":"Pressure exerted by material on smooth surface","C":"Temperature","D":"Cross sectional area"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pressure exerted by the material on a smooth surface is not a factor affecting the resistance of a material.The resistance is influenced by the type of material, temperature, and cross-sectional area.', 0, 0, 0, 1790968057974) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0cd98c80dbbe9986', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Sound is form of energy ____?', '{"A":"Longitudinal","B":"Transverse","C":"Mechanical","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A sound wave is a form of mechanical energy.Sound energy is the energy released by an objects vibrations.', 0, 0, 0, 1790968057974) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_40592a4fa64bcb0b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Energy is not carried by', '{"A":"Longitudinal progressive wave","B":"Transverse progressive wave","C":"Stationary Wave","D":"Electromagnetic Wave"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Stationary waves do not carry energy with them as it is stationary or does not change position.Stationary waves do not transfer energy from one place to another. ND06-08-2023', 0, 0, 0, 1790968057974) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9b978d3bbc6bc4b8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The magnet always points in the same direction if move freely i.e. towards north and south poles, because of:', '{"A":"Gravitational field A lot of metals deposits on north and south poles","B":"Due to attraction of north pole and repulsion of Western pole","C":"Earth is a huge magnet","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Earth''s South Magnetic Pole is geographically north, and the Earth''s magnetic North Pole is geographically south, so free-moving magnets are always north-south.', 0, 0, 0, 1790968058006) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ada63c5e0b425ff1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'When sound is reflected from floor ceiling or a wall, it mixes with the original sound and change its complexion, it is called as', '{"A":"Sound","B":"Reverberation","C":"Noise","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When sound is reflected from floor ceiling or a wall, it mixes with the original sound and change its complexion, it is called as Reverberation', 0, 0, 0, 1790968058006) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dc8c78817df87f40', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Steam already converted in to mechanical energy is usually _________', '{"A":"Warmer","B":"Colder","C":"produce water vapors","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A Steam Turbine is a mechanical device that extracts thermal energy from pressurized steam and transforms it into mechanical work.', 0, 0, 0, 1790968058006) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_452e1f44ee50e0af', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which of the following is not a renewable source of energy?', '{"A":"Hydrocarbon fuel","B":"Solar energy","C":"Wind energy","D":"Water energy"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Coal, fossil fuels, crude oil, natural gas, etc are all hydrocarbon fuels.These are called as non-renewable source of energy because they take millions of years to regenerate themselves.Water energy is renewable because it is regenerated by water cycle.Also wind energy and solar energy are renewable sources of energy.', 0, 0, 0, 1790968058006) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5a1c6af33c6debce', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'One may define Renewable Energy as', '{"A":"Energy derived from non-traditional sources","B":"Energy derived from sources that do not use up natural resources or harm the environment","C":"Energy fueled into ways that do not use up natural resources or harm the environment","D":"All of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Renewable energy is energy derived from natural sources that are replenished at a higher rate than they are consumed. Sunlight and wind, for example, are such sources that are constantly being replenished.', 0, 0, 0, 1790968058006) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3d37a2a47a300ad8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'In which law of thermodynamics, energy neither be created nor destroyed?', '{"A":"First Law of Thermodynamics","B":"Second Law of thermodynamic","C":"Third Law of Thermodynamics","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first law of thermodynamics is based on "the law of conservation of energy, which states that energy cannot be created or destroyed, but can be transferred from one form to another".', 0, 0, 0, 1790968058006) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1f8ac32dc3825fc4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Photon with energy greater than 1.02 MeV can interact with matter as?', '{"A":"Compton effect","B":"Photoelectric effect","C":"Pair Production","D":"All of these","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Photon with energy greater than 1.02 MeV can interact with matter as Pair Production.MeV stands for Mega electron-volt.****', 0, 0, 0, 1790968058006) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fd158c92004f3b53', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'What is the term for the process of extracting heat from water bodies to provide cooling for industrial facilities or air conditioning?', '{"A":"Water desalination","B":"Water heating","C":"Water source cooling","D":"Water recycling"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The energy extracted from the vaporised liquid as evaporation occurs will decrease the temperature of the liquid, resulting in a process known as evaporative cooling.', 0, 0, 0, 1790968058006) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_80fd64f1b1bfe9e9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', '___ are light sensitive variable resistors', '{"A":"Potential resistors","B":"Base resistors","C":"Terminal resistors","D":"Photo resistors"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Photo resistors are light sensitive variable resistors فوٹو ریزسٹرز روشنی کے حساس متغیر ریزسٹرس ہیں۔', 0, 0, 0, 1790968058039) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_74e4b6e1daf7e7c3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The minimum voltage which can flow current in the human body is :', '{"A":"40 to 50 volts","B":"50 to 60 volts","C":"60 to 70 volts","D":"70 to 80 volts"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The minimum voltage which can flow current in the human body is 70 to 80 volts کم از کم وولٹیج جو انسانی جسم میں کرنٹ بہا سکتا ہے 70 سے 80 وولٹ ہے', 0, 0, 0, 1790968058039) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a98016b68cbc3d44', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'White light from Sunshine on a green leaf. the Leaf will look green because the ________ leaf', '{"A":"White light is reflected from","B":"Green light is absorbed by","C":"Other than green color are absorbed by","D":"Other than green color are reflected by"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The leaf looks green because:White light from the sun contains all colors of the spectrumThe green leaf absorbs all colors except greenIt reflects green light back to your eyesYour eyes detect the reflected green light, making the leaf appear green', 0, 0, 0, 1790968058039) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_643d95bef1a75394', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Light travels ____ sound:', '{"A":"Slower than","B":"Faster than","C":"Equal to","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The speed of light is much faster than the speed of sound in air. Light travels 186 thousand miles in 1 second, while sound takes almost 5 seconds to travel 1 mileLight is a electromagnetic wave that''s why it travel faster than sound wave however electromagnetic waves don''t need medium to travel but sound wave need medium to travel ND5-07-2023', 0, 0, 0, 1790968058039) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d36678a8a4e8fc35', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', '153 kilo calories per 100gm energy are present in?', '{"A":"Banana","B":"Peanut","C":"Rice","D":"Meat","E":"Orange"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A 100-gram serving of cooked beef provides 250 calories, 35 grams of protein, and 10 grams of fat (5.2 grams which is healthier monounsaturated fat)', 0, 0, 0, 1790968058039) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b334c3ade5272784', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The electricity we use at home is called', '{"A":"Unswerving current","B":"transformed current","C":"Alternating current","D":"Direct Current"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The electricity we use in our homes is called Alternating Current/ Mains supply. Alternating current is used in most electricity distribution systems for several reasons, but the most important one is the ease with which it can be transformed from one voltage to another', 0, 0, 0, 1790968058039) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b7d4530c931cbaa7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The speed of sound is fastest in', '{"A":"Liquids","B":"Solids","C":"Gases","D":"Vacuum"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Solids are packed together tighter than liquids and gases, hence sound travels fastest in solidsSound can not travel through vaccum', 0, 0, 0, 1790968058039) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_95a9a61ee804dd8f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Velocity of Wind is measured?', '{"A":"Bolometer","B":"Anemometer","C":"Hygrometer","D":"Galvanometer","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An anemometer is an instrument that measures wind speed.This type of anemometer has a spinning wheel.', 0, 0, 0, 1790968058039) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cf93839a72dc3c06', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Einstein''s famous equation which states that mass and energy are interchangeable is:', '{"A":"E=mc2","B":"E=cm3","C":"M=ec2","D":"none of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ass times the speed of sunshine square." On the foremost basic level, the equation says that energy and mass (matter) square measure interchangeable; they''re completely different kinds of a similar issue.', 0, 0, 0, 1790968058070) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bd9791272ef53b05', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Long-sight defect could be corrected by using __________ lens?', '{"A":"Concave","B":"Convex","C":"diverging","D":"cylindrical","E":"none of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Short-sight defect could be corrected by using concave lens while long-sight defect could be corrected by using convex lens.', 0, 0, 0, 1790968058070) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_09d50b502944ba72', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The substances through which current cannot pass are called?', '{"A":"Conductors","B":"Non-metal","C":"Insulators","D":"Semi-conductors"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Insulators are the substances that do not allow electricity to pass through them. Examples of insulators are wax, wood, mud and plastic etc', 0, 0, 0, 1790968058070) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e57c635915301a09', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'What are soft drinks made with chilled water rather than water at room temperature?', '{"A":"Ingredients dissolve better in chilled water","B":"Chilled water attracts more carbon dioxide","C":"chilled water enhances the taste","D":"chilled water is more hygienic","E":"none of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Chilled water is used to cool a building''s air and equipment.', 0, 0, 0, 1790968058070) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c086684eb8e24d66', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Energy generation in stars is due to', '{"A":"Chemical reactions","B":"Fission of heavy nuclei","C":"Fusion of light nuclei","D":"Fusion of heavy nuclei"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Energy has been around since the dawn of time.The first source of energy was the sun, as it provided heat and light during the day.Energy generation in stars is due to nuclear fusion.', 0, 0, 0, 1790968058070) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_41df45c9999929e6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The biggest source of energy and heat is:', '{"A":"Thermal Power","B":"Sun","C":"Generator","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The energy of the sun is the original source of most of the energy found on earth.The principal source of energy: the Sun****ND10-1-2023', 0, 0, 0, 1790968058070) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1b132d1700d43513', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which cannot be considered as a renewable source of energy?', '{"A":"Wind","B":"Solar","C":"Petroleum","D":"all of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Petroleum, natural gas & coal are called non-renewable energy sources.The most popular renewable energy sources currently are:1. Solar energy2. Wind energy3. Hydro energy4. Tidal energy5. Geothermal energy6. Biomass energyRK12-12-2022', 0, 0, 0, 1790968058070) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a97d8aaa863d6921', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Renewable energy can be generated from:', '{"A":"Diesel","B":"Petrol","C":"Wind","D":"All"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The most popular renewable energy sources currently are:1. Solar energy2. Wind energy3. Hydro energy4. Tidal energy5. Geothermal energy6. Biomass energyRK12-12-2022', 0, 0, 0, 1790968058070) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_669c31c2d8a559ea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'From the given source of energy, which is renewable?', '{"A":"Solar energy","B":"Oil","C":"Thermal energy","D":"Hydel Power"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The most popular renewable energy sources currently are:1. Solar energy2. Wind energy3. Hydro energy4. Tidal energy5. Geothermal energy 6. Biomass energyRK12-12-2022', 0, 0, 0, 1790968058101) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4e524ea4d67dc13a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'When nuclear energy is intended to be harnessed for generation of electricity, potentially destructive neutrons released in a nuclear reactor are absorbed by:', '{"A":"Cubical blocks of steel Long rods of CD","B":"Heavy water","C":"A pile of blocks made of graphite","D":"Both A and C"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When nuclear energy is intended to be harnessed for the generation of electricity, potentially destructive neutrons released in a nuclear reactor are absorbed by Cubical blocks of steel Long rods of CD and A pile of blocks made of graphite', 0, 0, 0, 1790968058101) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_46e8bf2a9ebaf3f0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Loudness of sound is greatly depends upon:', '{"A":"Amplitude of vibration","B":"Height of object","C":"Nature of object","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The loudness of a sound depends on the Amplitude of the vibration Loudness is proportional to the square of the amplitudeif the amplitude is increased by three times, the loudness also increases by nine times.*****ND4-12-2022', 0, 0, 0, 1790968058101) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c0dd3056846feaf6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which from the following is NOT a conductor?', '{"A":"Aluminium","B":"Gold","C":"Graphite","D":"Silicon"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Silicon is not the conductor***Aluminum and gold are metals so they are good conductors of electricity.Now graphite is an allotropic form of carbon and is the only nonmetal that can conduct electricity.Silicon is a semiconductor. **********VU LDC UDC FIA PAPER 27-12-2021', 0, 0, 0, 1790968058101) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_701d1fb6dc3f1c74', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Which of the following scientific instruments is used to measure the atmospheric pressure?', '{"A":"Odometer","B":"Barometer","C":"Seismograph","D":"Audiometer"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The atmospheric pressure at any place is measured by a Barometer***The barometer was invented by Evangelista in 1644.**', 0, 0, 0, 1790968058101) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e4096f7175bb1280', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Earthquake waves ....... in velocity upon entering in the mantle.', '{"A":"Decreases","B":"Increase","C":"Remained unchanged","D":"Suspended"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The seismic velocity increases gradually with the depth of the mantle as the pressure increases with depth and therefore the density increases.', 0, 0, 0, 1790968058101) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_96f4a07a615e9497', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Light emitting diodes are made from specific compounds of:', '{"A":"Hydrogen","B":"Copper","C":"Gallium","D":"None of these","E":"All of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Light Emitting Diodes are light sources that are energy efficient and can be made in a variety of colors.Gallium is a soft, silvery metal used primarily in electronic circuits, semiconductors, and light-emitting diodes (LEDs).LEDs are comprised of compound semiconductor materials, which are made up of elements from group III and group V of the periodic tableSH5-8-2023ND06-08-2023', 0, 0, 0, 1790968058101) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_249db1b304943887', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Isaac Newton belonged to the country:', '{"A":"USA","B":"UK","C":"Germany","D":"Greek"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Isaac Newton discovered the laws of gravity and three laws of motion and invented calculus.Isaac Newton belonged to the United Kingdom (UK).', 0, 0, 0, 1790968058101) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c9e2444a12ea4f3d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Photo voltaic cells convert solar energy into electricity through a process?', '{"A":"Machinal","B":"Chemical","C":"Physical","D":"Photovoltaic cell"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Photovoltaic (PV) cells convert solar energy into electricity through a physical and chemical phenomenon known as the photovoltaic effect.Photovoltaic cells are also called solar cells.They convert light energy from the Sun directly into electrical energy.', 0, 0, 0, 1790968058130) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c633bad460a93550', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Radio waves travel ……then sound wave ….', '{"A":"very fast","B":"Faster","C":"very slowly","D":"Slowly"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sound travels at approximately 1,100 feet per second (766 miles per hour). Radio waves travel at the speed of light, which is approximately 186,000 miles per second.', 0, 0, 0, 1790968058130) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_62fa4ac9d13e9f1a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'speed of light was first determined by', '{"A":"Remer","B":"Galilee","C":"Albert Einstein","D":"Ole Romer"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ole Rømer, an astronomer from Denmark made the first quantitative measurements of the speed of light in 1676.', 0, 0, 0, 1790968058130) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_88081b4df5da576e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'speed of sound in dry air at 20 °C is___________?', '{"A":"343 m/s","B":"345 m/s","C":"353 m/s","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The speed of sound is the distance travelled per unit of time by a sound wave as it propagates through an elastic medium.', 0, 0, 0, 1790968058130) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f29f550ff24206f1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'An electric current can produce', '{"A":"Chemical effect","B":"Magnetic effect","C":"Heating effect","D":"All of these three","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Magnetic effect.Chemical effect.Heating effect.Electric shocks.', 0, 0, 0, 1790968058130) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_889506c1093581f6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The unit of home electricity energy consumption is :', '{"A":"Watt hour","B":"Kilowatt hour","C":"Joule hour","D":"Kilo joule hour"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The basic unit of electricity is the Kilowatt hour . In simple terms, 1 kWh is the amount of energy used by a 1kW (1000 watt) electric heater for 1 hour.', 0, 0, 0, 1790968058130) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fe14ddbe026cfe5c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Who said a body will remain at rest unless an external force acts on the body?', '{"A":"Galileo","B":"Einstein","C":"Newton","D":"Archimedes"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Newton''s first law of motion states that a stationary object remains stationary unless an external force acts on it, and an object moving at a constant velocity continues to move linearly unless an external force acts on it. ..', 0, 0, 0, 1790968058130) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_775238e7fd954f7b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Minimum / lowest sound recorded in which medium:', '{"A":"Air","B":"Water","C":"steel","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sound travels at different speeds depending on what it is traveling through. Of the three mediums (gas, liquid, and solid) sound waves travel the slowest through gases, faster through liquids, and fastest through solids. Temperature also affects the speed of sound.', 0, 0, 0, 1790968058130) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2a0ede69fc406a93', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Mechanics, heat, light and sound are the branches of:', '{"A":"Chemistry","B":"Astronomy","C":"Biology","D":"Physics","E":"All"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The subject matter of physics includes mechanics, heat, light and other radiation, sound, electricity, magnetism, and the structure of atoms."', 0, 0, 0, 1790968058159) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_813b2480d7aeedfd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Fluid changes the volume under external pressure due to', '{"A":"Plasticity","B":"Viscosity","C":"Compressibility","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790968058159) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_13919961971dfc45', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The process of light exposure in a 24-hour cycle that controls the growth and development of certain plants and animals is called', '{"A":"Photoperiodism","B":"Photosynthesis","C":"Photoionization","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Answer:The functional or behavioral response of an organism to changes in the duration of a daily, seasonal, or annual cycle of photoperiodism, light, and darkness. Photoperiodic responses are reasonably predictable, but temperature, diet, and other environmental factors also alter the organism''s response.', 0, 0, 0, 1790968058159) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_986e5b6c358e2003', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The average temperature for Wednesday, Thursday and Friday was 40°C. The average for Thursday, Friday and Saturday was 41° C. If temperature on Saturday was 42° C, what was the temperature on Wednesday?', '{"A":"39° C","B":"44° C","C":"38° C","D":"41° C"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Average temperature for Wednesday, Thursday and Friday = 40° CTotal temperature = 3 × 40 = 120° CAverage temperature for Thursday, Friday and Saturday = 41° CTotal temperature = 41 × 3 = 123° CTemperature on Saturday = 42° CNow,(Thursday + Friday + Saturday) - (Wednesday + Thursday + Friday) = 123 - 120;Saturday - Wednesday = 3 Wednesday = 42 - 3 = 39° C', 0, 0, 0, 1790968058159) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2420355261d89379', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Nuclear power reactors are operated at low temperatures and consequently with lower efficiency because:', '{"A":"High pressure inside the reactor reduces the temperature","B":"Uranium is difficult to heat","C":"The walls of nuclear reactors cannot withstand high temperature","D":"none of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Answer:CNuclear power reactors are operated at low temperatures and consequently with lower efficiency because The walls of nuclear reactors cannot withstand high temperature', 0, 0, 0, 1790968058159) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_aeca73af426c3060', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'A plant with green leaves placed in red light will appear', '{"A":"Green","B":"Black","C":"Red","D":"none of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Answer:Plants look green in sunlight, so they should look black or gray in red light because they don''t need to reflect green wavelengths to look green.', 0, 0, 0, 1790968058159) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ee7d2a075badedd5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Sounds usually associated with letters such as f, s, v, z, in which the air passes through a narrow contraction that causes the air to flow turbulently and thus create a noisy sound are called:', '{"A":"Plosives","B":"Fricatives","C":"Articulations","D":"Allophonic"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fricatives are the kinds of sounds usually associated with letters such as f, s; v, z, in which the air passes through a narrow constriction that causes the air to flow turbulently and thus create a noisy sound.', 0, 0, 0, 1790968058159) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5558312d7b5be4bf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Speed of sound is greater in solids than in liquids because:', '{"A":"The atoms in solids are regularly arranged","B":"The liquids has high electricity","C":"The solids have elasticity","D":"The atoms in liquids are closely packed"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Solids have a high degree of elasticity, which means they can return to their original shape after deformation. This property allows sound waves to travel more efficiently and quickly through solids Because the particles are tightly bound and can transmit vibrations rapidly.', 0, 0, 0, 1790968058159) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_29375679fabc4270', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Study of energy production in living bodies is called_________?', '{"A":"Bioenergetics","B":"Biomechanics","C":"Biology","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bioenergetics is the branch of biochemistry that focuses on how cells transform energy, often by producing, storing or consuming adenosine triphosphate (ATP). Bioenergetic processes, such as cellular respiration or photosynthesis, are essential to most aspects of cellular metabolism, therefore to life itself.', 0, 0, 0, 1790968058189) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d2b61b81b9afe644', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Tape recorder converts electrical energy into:', '{"A":"Sound energy","B":"Kinetic energy","C":"Heat energy","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sound energy is a form of energy that can be heard by living beings. Only those waves that have a frequency of 16 Hz to 20 kHz are audible to humans.', 0, 0, 0, 1790968058189) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2b02f749687e9cf0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The electric lines of force are____________?', '{"A":"physically existing near the charges","B":"physically existing every where","C":"imaginary","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Electric lines of force are always diverging from positive charge and they converge at a negative charge.', 0, 0, 0, 1790968058189) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1139dbc65dfcda02', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The process of measuring temperature is called?', '{"A":"Thermodynamics","B":"Thermometry","C":"Calorimetry","D":"Heat transfer"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Thermometry is the measurement of temperatureA device used to measure temperature is called a thermometer.Common temperature scales are Celsius, Fahrenheit, and Kelvin.Temperature indicates how hot or cold a body is.The SI unit of temperature is Kelvin (K).', 0, 0, 0, 1790968058189) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_771099e0cb87255c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'The temperature for pasteurization of milk is selected so as to', '{"A":"Store it for long time without coagulation","B":"Kill all bacteria","C":"Kill the microorganisms and other harmful bacteria","D":"Kill the microorganism"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Answer:C Pasteurization is a process of purification of milk. In this method microorganisms and all harmful bacteria have been removed by killing them at s specific temperature', 0, 0, 0, 1790968058189) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ba60df3d29f01373', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_physics', 'Who was the first scientist to study electricity?', '{"A":"Volta","B":"Gilbert","C":"Newton","D":"Edison"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Electricity would remain little more than an intellectual curiosity for millennia until 1600, when the English scientist William Gilbert wrote De Magnete, in which he made a careful study of electricity and magnetism, distinguishing the lodestone effect from static electricity produced by rubbing amber.', 0, 0, 0, 1790968058189) ON CONFLICT(id) DO NOTHING;
INSERT INTO subject (id, user_id, name, parent_id, total_mcqs, created_at) VALUES ('top_eds_chemistry', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'Chemistry', 'top_everyday_science', 276, 1790968058215) ON CONFLICT(id) DO UPDATE SET total_mcqs = 276;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0e5887a8a54add32', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Atomic number of hydrogen is?', '{"A":"4","B":"3","C":"2","D":"1"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The atomic number of hydrogen is 1. It is the first element on the periodic table. Named by: Antoine Lavoisier (1783)Atomic mass: 1.00784 uAppearance: Colorless gasSymbol: HProtons: 1Electrons: 1Last updated 26-07-2026 by NA', 0, 0, 0, 1790968058254) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ee84621fc1a763db', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The lightest gas that provides a larger elevation for balloons and is the lightest of all gases is _____?', '{"A":"Hydrogen","B":"Nitrogen","C":"Oxygen","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hydrogen and helium are the two lightest gases.Helium is the second most abundant element in the universe, after hydrogen. Helium has monatomic molecules.It is the lightest of all gases except hydrogen.Hydrogen is the lightest gas known.It provides the maximum lift for balloons due to its very low density.Last updated question 17-02-2026', 0, 0, 0, 1790968058254) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5e33fc4fe9afe2d1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The only elemental metal that is liquid at room temperature is?', '{"A":"Lead","B":"Zinc","C":"Mercury","D":"Aluminum"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mercury Symbol: HgAtomic number: 80Melting point: -38.83 °CAtomic mass: 200.59 uLast verified on 13-03-2026', 0, 0, 0, 1790968058254) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_83682ccf2e7fa207', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'What is the common name of sodium bicarbonate (Na₂CO₃)?', '{"A":"Baking soda","B":"Washing soda","C":"Caustic soda","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Washing soda, also known as sodium carbonate, has the chemical formula Na₂CO₃.It is commonly used in cleaning agents and water softeners.Washing soda is a whitish, odourless powder.Last verified on 03-09-2026', 0, 0, 0, 1790968058254) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2c89802cfd68e3b2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The chemical formula of bleaching powder is?', '{"A":"CaCl₂","B":"CaOCl₂","C":"Ca(OH)₂","D":"CaCO₃"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bleaching powder: CaOCl₂Chemical name: Calcium oxychloride.Main uses: Bleaching and disinfection.CaCl₂: Calcium chloride.Ca(OH)₂: Calcium hydroxide (slaked lime).Last verified on 03-09-2026', 0, 0, 0, 1790968058254) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8fa88f30b9e7ff2b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'What is the chemical formula of Baking Soda?', '{"A":"NaCl","B":"NaHCO₃","C":"KCl","D":"CaCO₃"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The chemical formula of baking soda is NaHCO₃, which stands for sodium bicarbonate.The chemical name of baking soda is sodium hydrogen carbonate or sodium bicarbonate (NaHCO3).Sodium bicarbonate is non flammableBaking soda is basic in nature.Last verified on 03-09-2026', 0, 0, 0, 1790968058254) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f058344856a30ce8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The Chemical formula of Table/Common Salt is?', '{"A":"NaCl","B":"KCl","C":"CaCl₂","D":"MgSO₄"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation It is an ionic compound with the chemical formula NaCl.It representing a 1:1 ratio of sodium and chloride ions. Table salt is the granulated white salt seen in most saltshakers.It is typically mined from underground deposits.It is commonly known as Sodium chloride.Last verified on 03-09-2026', 0, 0, 0, 1790968058254) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1ac5fefc9318185d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'What is the chemical formula of Washing Soda?', '{"A":"NaHCO₃","B":"Na₂SO₃","C":"Na₂CO₃","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Washing soda, also known as sodium carbonate, has the chemical formula Na₂CO₃.It is commonly used in cleaning agents and water softeners.Washing soda is a whitish, odourless powder.Last verified on 02-09-2026', 0, 0, 0, 1790968058254) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b57cd923a18b888e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which of the following gas mainly responsible for ozone layer depletion?', '{"A":"Chlorofluorocarbon/Freon","B":"CO2","C":"Nitrogen oxide","D":"Sulphur dioxide"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Main Cause: Freon / CFCsEffect: Breaks down O₃ molecules → more UV-B radiationOther Contributors: Halons, carbon tetrachlorideResult: Skin cancer, cataracts, climate impactAdditional information:The Montreal Protocol (1987) aimed to reduce CFC emissionsOzone layer protects Earth from harmful ultraviolet raysLast verified on 16-01-2026', 0, 0, 0, 1790968058285) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_16eaeb08fc7bb725', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which element is NOT abundant in the Earth''s crust?', '{"A":"Phosphorus","B":"Oxygen","C":"Silicon","D":"Aluminum"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Phosphorus is not among the top 10 most abundant elements in the Earth''s crust.Most abundant element in Earth crust is Oxygen.Oxygen in the crust is (46. 1%).The chemical formula of oxygen (dioxygen) is O2.List of 10 Most Abundant Elements in the Earth''s Crust:Sr#ElementAbundance percent by weight1Oxygen46.10%2Silicon28.20%3Aluminum8.23%4Iron5.63%5Calcium4.15%6Sodium2.36%7Magnesium2.33%8Potassium2.09%9Titanium0.57%10Hydrogen0.14%Last verified on 01-09-2026', 0, 0, 0, 1790968058285) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_119f6f39eda4990f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which isotope of hydrogen is radioactive?', '{"A":"Tritium","B":"Protium","C":"Deuterium","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tritium (³H) is the radioactive isotope of hydrogen.It undergoes beta (β) decay and changes into Helium-3.Additional information:Hydrogen Isotopes: 3 (Protium, Deuterium, Tritium)Protium (¹H): 1 proton, 0 neutrons (Stable)Deuterium (²H): 1 proton, 1 neutron (Stable)Tritium (³H): 1 proton, 2 neutrons (Radioactive)Half-life of Tritium: Approximately 12.3 yearsLast verified on 04-08-2026', 0, 0, 0, 1790968058285) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4721d48cc254e0de', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'According to Rutherford’s gold foil experiment, the mass of an atom is concentrated in its _____?', '{"A":"Nucleus","B":"Neutrons","C":"Protons","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Rutherford’s gold foil experiment (1911) showed that an atom has a small, dense, positively charged center called the nucleus.The mass of the atom is concentrated in the nucleus, while most of the atom is empty space.Additional information:Nucleus contains: Protons (+) and neutrons (neutral)Electrons move around the nucleus in mostly empty spaceThe experiment involved alpha particles being deflected by the nucleus.Last verified on 10-02-2026', 0, 0, 0, 1790968058285) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1c648f7bd86f32fe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'How many carats is the best gold?', '{"A":"18 Carat","B":"20 Carat","C":"24 Carat","D":"28 Carat"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 24-karat (24K) gold is considered the "best"Purity: 99.9% pure gold.Color: Rich, deep, bright yellow.Additional information22K Gold: 91.7% pure gold. It is mixed with harder metals like silver or copper.18K Gold: 75% pure gold. It is highly durable and excellent for diamond settings Carat is the unit of measurement for the physical weight of diamonds/gold.Last updated by NA on 16-07-2026', 0, 0, 0, 1790968058285) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4f5946fdb3daa911', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which gas is used in decoration lighting (advertising lights)?', '{"A":"Oxygen","B":"Hydrogen","C":"Nitrogen","D":"Neon"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Neon is the primary gas used in decorative and advertising lightsThe color of the light depends on the gas in the tube.Additional informationArgon: Produces a blue or (mixed with mercury) green/purple light.Helium: Glows yellow or pink.Krypton: Emits a whitish-yellow light.Xenon: Creates a violet/lavender light.Last updated by NA on 16-07-2026', 0, 0, 0, 1790968058285) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_308207cfdc6d47f1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The chemical name/main compound of synthetic vinegar is?', '{"A":"Acetic acid","B":"Sodium acid","C":"Sodium chloride","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Chemical Name: Acetic Acid (Ethanoic Acid)Chemical Formula: CH₃COOHVinegar Concentration: 4–8% Acetic AcidType of Acid: Weak Organic AcidUses: Food seasoning, pickling, preservation, cleaningLast verified on 10-07-2026', 0, 0, 0, 1790968058285) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a0a9c87a81103a6b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'At room temperature, the pH value of pure water is?', '{"A":"5","B":"6","C":"7","D":"8"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The pH value of pure water at room temperature is 7.A pH of 7 means the solution is neutral.Pure water contains equal amounts of H⁺ and OH⁻ ions.The pH scale ranges from 0 to 14.Room temperature is approximately 25°C.', 0, 0, 0, 1790968058285) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_30836e5bb8eb652d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Neutron was discovered by?', '{"A":"Rutherford","B":"Thomson","C":"J Perrin","D":"Chadwick"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sir James Chadwick discovered the neutron in 1932.He was a British physicist.His discovery completed the basic picture of the atomic nucleus.He received the Nobel Prize in Physics in 1935 for this discovery.Additional information:J. J. Thomson – Electron (1897)Ernest Rutherford – Atomic nucleus (1911) and Proton (1917)Last verified on 03-07-2026', 0, 0, 0, 1790968058314) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ec4d14a113917ca7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The chemical formula of ozone gas is ______?', '{"A":"O₂","B":"O₃","C":"CO₂","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation O₃ is the chemical formula of ozone gas.Ozone is an allotrope of oxygen containing three oxygen atoms.It is mainly found in the stratosphere, where it forms the ozone layer.The ozone layer protects Earth from harmful ultraviolet (UV) radiation.Last verified on 30-06-2026', 0, 0, 0, 1790968058314) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c22dd658a950596a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which of the following is a base quantity in SI unit? Density, Mass, Length, Both B and C', '{"A":"Density","B":"Mass","C":"Length","D":"Both B and C"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mass and Length are base quantities in SI units.Length SI Unit: meter (m)Mass SI Unit: kilogram (kg)Additional information:Base Quantities in SI System:Time (second)Electric current (ampere)Temperature (kelvin)Last verified on 16-06-2026', 0, 0, 0, 1790968058314) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d64133d56c09130d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Black gold is also named for?', '{"A":"Coal","B":"Gas","C":"Petroleum","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Black Gold: Petroleum (Crude Oil)Color: Dark black / brownish blackMain Uses: Fuel, petrol, diesel, kerosene, plasticsImportance: Backbone of modern industry and transportAdditional information:Top Oil-Producing Countries:Saudi ArabiaUSARussiaIraqIranLast verified on 16-06-2026', 0, 0, 0, 1790968058315) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0921e7da3bd87cf7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'What is the mass of one proton?', '{"A":"Equal to 1836 electron","B":"Equal to proton","C":"Equal to 1836 neutron","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The mass of a proton is approximately 1836 times greater than the mass of an electron.A proton is a positively charged particle found in the nucleus of an atom.It has almost the same mass as a neutron (slightly less).Electrons are much lighter compared to protons.Last verified on 22-06-2026', 0, 0, 0, 1790968058315) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_522e9b51b62f857d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'What is the chemical composition of chromosomes?', '{"A":"Proteins and carbohydrates","B":"RNA and lipids","C":"DNA and proteins","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Chromosomes are made of DNA and proteins.DNA carries genetic information.Proteins (mainly histones) help package DNA.Together they form chromatin material.Chromosomes are found in the nucleus of cells.Last verified on 18-06-2026', 0, 0, 0, 1790968058315) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c8b71d1d3671a925', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Chile saltpeter has the chemical formula?', '{"A":"KNO₃","B":"NaNO₃","C":"Ca(NO₃)₂","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Chile saltpeter is the common name for sodium nitrate (NaNO₃).It is found naturally in Chile and Peru.It is used in fertilizers and explosives.Last verified on 18-06-2026', 0, 0, 0, 1790968058315) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_651b7922245d008f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Ammonia reacts with carbon dioxide to form which compound?', '{"A":"Urea","B":"Ammonium nitrate","C":"Nitric acid","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ammonia reacts with carbon dioxide to form urea.2NH₃ + CO₂ → NH₂COONH₄ → CO(NH₂)₂ + H₂OProduct: Urea [CO(NH₂)₂]Urea contains about 46% nitrogen.The industrial production of urea was developed by Friedrich Wöhler.Last verified on 17-06-2026', 0, 0, 0, 1790968058315) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a32a5e9a018f9b08', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Percentage of oxygen in human body is _____?', '{"A":"65%","B":"70%","C":"10%","D":"18%"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The human body contains about 65% oxygen by mass.Oxygen is the most abundant element in the human body.It is mainly present in water (H₂O) and organic compounds.It is essential for respiration and energy production.Additional information:Carbon: ~18%Hydrogen: ~10%Nitrogen: ~3%Other elements: ~4% (calcium, phosphorus, etc.)Last verified 09-06-2026', 0, 0, 0, 1790968058361) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6b8f05459e5689ef', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which gas is commonly used in balloons and airships?', '{"A":"Hydrogen","B":"Helium","C":"Carbon dioxide","D":"All of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The usual gases used for lifting airships are hydrogen and helium. Hydrogen is the lightest known gas and thus has great lifting capacity,Helium is not as buoyant but is far safer than hydrogen because it does not burn.Last verified on 01-04-2026', 0, 0, 0, 1790968058361) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7539f51e23a72074', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Oxidation of secondary alcohols produces?', '{"A":"Aldehydes","B":"Ketones","C":"Ethers","D":"Esters"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Oxidation of secondary alcohols produces ketones.Secondary alcohols have –OH group attached to a carbon bonded with two other carbons.During oxidation, hydrogen is removed and a carbonyl (C=O) group is formed.Additional information:Primary alcohol → Aldehyde → AcidSecondary alcohol → Ketone (stops here)Tertiary alcohol → No easy oxidationLast verified on 05-06-2026', 0, 0, 0, 1790968058361) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_eeee65b07111a5ad', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Natural rubber is made up of / consists of polymers of the organic compound?', '{"A":"Isoprene","B":"Styrene","C":"Butadiene","D":"Ethylene"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Natural rubber consists of polymers of isoprene (C₅H₈).Isoprene is a five-carbon unsaturated hydrocarbon.Natural rubber is chemically known as cis-1,4-polyisoprene.It is obtained from the latex of rubber plants.Last verified on 05-06-2026', 0, 0, 0, 1790968058361) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cc5439a955a23711', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Ascorbic acid is?', '{"A":"Vitamin","B":"Hormone","C":"Enzyme","D":"Amino Acid"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ascorbic Acid is commonly known as Vitamin C.It is essential for growth, repair, and maintenance of body tissues.Prevents scurvy, a disease caused by Vitamin C deficiency.Additional information:Sources of Vitamin C (5):OrangeLemonGuavaStrawberryBell pepperFunctions:AntioxidantCollagen synthesisStrengthens immunityLast verified on 19-01-2026', 0, 0, 0, 1790968058361) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_61ca66083cadcfd3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which device converts chemical energy into electrical energy?', '{"A":"Generator","B":"Battery","C":"Modem","D":"Electric Motor"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Battery is a device that converts chemical energy into electrical energy.Batteries work by using a galvanic cell.It is an electrochemical device made up of two electrodes and an electrolyte solution.Last verified on 16-03-2026', 0, 0, 0, 1790968058361) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0db1bf2bfbd196c2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The chief constituent of natural gas is _____?', '{"A":"Methane","B":"Ethane","C":"Propane","D":"Chlorine"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Natural gas contains about 80% to 95% methane.It is a hydrocarbon fuel.It is the chief (major) component of natural gas.It is also a greenhouse gas.Chemical formula: CH₄It is a clean-burning fuel used in daily life.Last verified on 07-05-2026', 0, 0, 0, 1790968058361) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_604cb8ba73d69ce7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Isotopes of an element have the same number of _______?', '{"A":"Neutrons","B":"Protons","C":"Electrons","D":"Beta rays"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Isotopes of an element have the same number of protons.They differ in number of neutrons, which changes mass number.Chemical properties remain almost the same due to same protons.Last verified on 14-05-2026', 0, 0, 0, 1790968058361) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_eb06cfdb407de2d5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Mass number of an atom shows _____?', '{"A":"Numbers of protons","B":"Number of electrons","C":"Number of proton and neutron","D":"Number of proton and electrons"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Atoms are made of subatomic particles: protons, neutrons, and electrons.Mass number represents the total number of heavy particles in nucleus.Only protons and neutrons contribute to atomic mass.Last verified on 14-05-2026', 0, 0, 0, 1790968058402) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d7909f628f280f93', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which of the following is not known as a greenhouse gas?', '{"A":"Hydrogen / Argon","B":"Carbon Dioxide","C":"Nitrous oxide","D":"Methane"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hydrogen (H2) and Argon is not a greenhouse gas.Greenhouse gases are gases that trap heat in Earth’s atmosphere and cause the Greenhouse Effect.The main greenhouse gases are:Carbon dioxide (CO2)Methane (CH4)Nitrous oxide (N2O)Water vapor (H2O)Ozone (O3)Chlorofluorocarbons (CFCs)Hydrofluorocarbons (HFCs)Perfluorocarbons (PFCs)Last verified on 01-05-2026', 0, 0, 0, 1790968058402) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fd9358c3a376a4a4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'What is the chemical name of "chalk"?', '{"A":"Calcium carbonate","B":"Calcium nitrate","C":"Sodium nitrate","D":"Zinc carbonate"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The chemical name of chalk is Calcium carbonate.Its chemical formula is CaCO₃.It is a soft, white mineral.Commonly used in blackboard chalk and limestone.Found naturally in rocks and marine shells.Last verified on 30-04-2026', 0, 0, 0, 1790968058402) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2250c0c0d6da193b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The percentage of Oxygen in the air is _____?', '{"A":"20.94%","B":"21.94%","C":"22.94%","D":"25.7%"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Composition of Air:Nitrogen → 78%Oxygen → 20.95%Argon → 0.93%Carbon dioxide → 0.04%Other gases → very small tracesLast verified on 30-04-2026', 0, 0, 0, 1790968058402) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2e439c27e6a1aca7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Chemical formula of water is _____?', '{"A":"H₂G","B":"H₂O","C":"H₂u","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The empirical formula of water is H₂OFreezing point: 0°C (32°F)Boiling point: 100°CMolar mass: 18.015 g/molDensity: 997 kg/m³Melting point: 0°CLast updated by NA on 25-April-2026', 0, 0, 0, 1790968058402) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a53e2fd69c7e2a85', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which element is used to remove the permanent hardness of water?', '{"A":"Washing soda","B":"Ion exchange process","C":"Zeolite process","D":"Heating"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Washing soda is also known as sodium carbonate (Na2CO3).It is used to remove permanent hardness of water.Permanent hardness is caused by the presence of magnesium and calcium sulfates or chlorides in water, which cannot be removed by boiling.Washing soda helps to precipitate these minerals, making the water softer.Last verified on 23-04-2026', 0, 0, 0, 1790968058402) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0327c3a6f667a2bd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Pseudo Solid is _____?', '{"A":"Sodium chloride","B":"Glass","C":"Calcium chloride","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Glass and pitch are examples of pseudo solids.Pseudo solid is a solid which possesses the property of liquids.Glass is a pseudo solid and in a very slow process, it flows like a liquid due to which the base of glass gets thicker than top.Last verified on 02-04-2026', 0, 0, 0, 1790968058402) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4d9be13b8777a2b2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The study of the chemical composition of the Earth''s crust is called?', '{"A":"Mineralogy","B":"Petrology","C":"Geochemistry","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Geochemistry focuses on the chemical elements and compounds in Earth materials.It helps to understand rocks, minerals, and soil composition.Last verified on 01-04-2026', 0, 0, 0, 1790968058402) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c862d726b7b6d661', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The lightest gas which is used for filling party and advertisement balloons is ______?', '{"A":"Hydrogen","B":"Nitrogen","C":"Oxygen","D":"Carbon Dioxide"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation NOTE: Hydrogen is the lightest gas, but Helium is generally preferred. However, since "Helium" is not listed among your choices, the correct answer from the provided options is HydrogenHelium is the lightest safe gas commonly used for:Party balloonsAdvertisement balloonsWeather balloonsCommon MCQ ConfusionHydrogen is actually the lightest gas overall, but it is highly flammable and can catch fire.Helium is slightly heavier than hydrogen but is non-flammable and safe, so it is used in balloons.Last verified on 18-03-2026', 0, 0, 0, 1790968058438) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e837c2db945eb186', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The formula for sand molecule is _____?', '{"A":"SiO₂","B":"S₂iO","C":"Si₂O","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sand is primarily composed of silicon dioxide (SiO₂).It is a chemical compound made of silicon and oxygen atoms in a 1:2 ratio.SiO₂ is found in quartz, glass, and sand naturally.It is hard, chemically stable, and insoluble in water.Last verified on 16-03-2026', 0, 0, 0, 1790968058438) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_267c595780595a2c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The symbol of element Copper is?', '{"A":"Ag","B":"Cu","C":"He","D":"Ne"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Copper is a chemical element with the symbol Cu and atomic number 29. It is a soft, malleable, and ductile metal with a reddish-orange color.The some major elements with their symbols:Hydrogen - HSodium - NaCarbon - CNitrogen - NOxygen - OFluorine - FChlorine - ClPotassium - KHelium - HeNeon - NeCalcium - CaSulphur - SPhosphorus - PAluminium - AlMagnesium - MgIron - FeLast verified on 16-03-2026', 0, 0, 0, 1790968058438) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d76a3402cb2c6db6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The power of combining of an atom with other atoms to form molecules or compounds is called?', '{"A":"Atomic Mass","B":"Valency","C":"Electronegativity","D":"Ionization Energy"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Valency is the combining capacity of an atom to form molecules or compounds.It depends on the number of electrons an atom can lose, gain, or share to complete its outer shell.Last verified on 15-03-2026', 0, 0, 0, 1790968058438) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_57e053e61e92f2e5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The change from liquid to solid, or the reverse of melting, is called?', '{"A":"Melting","B":"Freezing","C":"Evaporation","D":"Condensation"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Freezing is the process by which a liquid changes to a solid.It is the reverse of melting, which is the process by which a solid changes to a liquid.Last verified on 13-03-2026', 0, 0, 0, 1790968058438) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_070a3d0d51f24835', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The particles of a liquid?', '{"A":"Are tightly packed and stay in a fixed position","B":"Are free to move in a container but remain in close contact with one another","C":"Are widely spaced and move freely in any direction","D":"Are sparse and vibrate at long distances"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Liquids have no fixed shape but have a fixed volume.Particles are close together but can slide past each other, allowing the liquid to flow.Additional information:Solid: Are tightly packed and stay in a fixed positionGas: Are widely spaced and move freely in any directionLast verified on 13-03-2026', 0, 0, 0, 1790968058438) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_916e885e6d96be82', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The study of heat changes in chemical reactions is called?', '{"A":"Electrochemistry","B":"Thermochemistry","C":"Biochemistry","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The branch of chemistry that studies heat energy released or absorbed during chemical reactions is called Thermochemistry.It explains how heat changes occur during reactions such as combustion, neutralization, and dissolution.It deals with concepts like enthalpy change (ΔH), exothermic reactions, and endothermic reactions.Last verified on 11-03-2026', 0, 0, 0, 1790968058438) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b7c62f2cf8249bd2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Elements or compounds combining in a chemical reaction are called _____?', '{"A":"Products","B":"Reagents","C":"Reactants","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Elements or compounds that combine in a chemical reaction are called reactants.Reactants are the starting substances in a chemical reaction. They can be elements or compounds. Reactants undergo chemical change during the reaction. They combine or break apart to form new substances. The new substances formed are called products.Last updated on 09-03-2026', 0, 0, 0, 1790968058438) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_85676e633ddde700', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which one of these is a fossil fuel? Petroleum, Coal, Natural gas', '{"A":"Petroleum","B":"Coal","C":"Natural gas","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Petroleum, Coal, and Natural gas are all fossil fuels. They are non-renewable energy sources Major contributors to global energy production.Coal: A solid fossil fuel primarily derived from ancient swamp plants.Petroleum (Oil): from the remains of marine microorganisms like plankton.Natural gas: Composed of methane, often found in underground deposits alongside petroleum or coalLast updated on 06-March-2026', 0, 0, 0, 1790968058472) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bc4c3460df562a6e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The process in which solid directly changes to gas is called?', '{"A":"Distillation","B":"Filtration","C":"Sublimation","D":"Crystallization"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sublimation is the process in which a solid directly changes into a gas without passing through a liquid phase. This endothermic phase transition Occurs when a substance absorbs enough energy to overcome intermolecular forces.Deposition: Gas to Solid (the reverse process).Examples: Dry ice, iodine, frost/snow.Last updated on 06-March-2026', 0, 0, 0, 1790968058472) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_87849c83902461ba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Atomic number of oxygen is:', '{"A":"5","B":"8","C":"11","D":"zero","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The atomic number of oxygen is 8. This indicates that an oxygen atom contains 8 protons in its nucleus. Atomic Symbol: OPosition: Located in Group 16 of the periodic table.Oxygen is a chemical element.Discoverers: Joseph Priestley, Antoine Lavoisier, Carl Wilhelm ScheeleOxygen Electrons per shell: 2, 6Last updated on 06-March-2026', 0, 0, 0, 1790968058472) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dfed9924b0e212c9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Oxidation is a chemical reaction involving the __________?', '{"A":"Gain of Electrons","B":"Loss of Electrons","C":"Gain of Protons","D":"Loss of Protons"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Oxidation is the chemical process of:Losing electronsOxidation state increasesAlways paired with reduction (together form redox)Reducing agent gets oxidized (it gives up the electrons)Additional information Reduction:Gain electronsOxidation state lowersAlways paired with oxidation (redox)Oxidizing agent gets reduced', 0, 0, 0, 1790968058472) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e3ad077d49e993ff', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which of the following is necessary for biological nitrogen fixation?', '{"A":"Calcium","B":"Molybdenum","C":"Zinc","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nitrogenase enzyme requires molybdenum. It helps convert atmospheric N₂ into ammonia. Leguminous plants rely on this process. Deficiency reduces nitrogen fixation. It is essential for symbiotic bacteria in root nodules.Last updated question 17-02-2026', 0, 0, 0, 1790968058472) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fa7314ea16b1e1f6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Ozone is a gas made up of _______ atoms of oxygen.', '{"A":"Two","B":"Three","C":"One","D":"Five"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ozone (O₃) consists of three oxygen atoms. It forms a protective layer in the stratosphere, shielding Earth from UV radiation.Last verified on 01-02-2026', 0, 0, 0, 1790968058472) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f1e33a26b400d2ed', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Urea fertilizer contains ______% nitrogen.', '{"A":"46%","B":"36%","C":"26%","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Urea fertilizer contains 46% nitrogen (N).Urea is a white crystalline solid.It is widely used as a fertilizer and animal feed additive.Last verified on 31-01-2026', 0, 0, 0, 1790968058472) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4527f283a8f8b2b1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The valency of carbon is ______?', '{"A":"4","B":"12","C":"6","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Carbon has a valency of 4, meaning it can form 4 covalent bonds with other atoms.This property allows carbon to form complex organic compounds.It is the backbone of all organic molecules.Additional information:Examples of Carbon Compounds (5):Methane (CH₄)Ethane (C₂H₆)Glucose (C₆H₁₂O₆)Ethanol (C₂H₅OH)Carbon dioxide (CO₂)Last verified on 19-01-2026', 0, 0, 0, 1790968058472) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_357d08554a79a3f9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Ascorbic Acid is also known as ______?', '{"A":"Vitamin A","B":"Vitamin B","C":"Vitamin C","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ascorbic Acid is commonly known as Vitamin C.It is essential for growth, repair, and maintenance of body tissues.Prevents scurvy, a disease caused by Vitamin C deficiency.Additional information:Sources of Vitamin C (5):OrangeLemonGuavaStrawberryBell pepperFunctions:AntioxidantCollagen synthesisStrengthens immunityLast verified on 19-01-2026', 0, 0, 0, 1790968058511) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7b5731b1db65355a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The gas common known as Laughing gas is?', '{"A":"Nitrous Oxide","B":"Oxygen","C":"Hydrogen","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nitrous oxide, commonly known as laughing gas.It is a colorless, non-flammable gas used in medicine.Nitrous oxide (N₂O) causes temporary laughing and relaxation.Additional information:Nitrous oxide was discovered by Joseph Priestley in 1772.Last verified on 18-01-2026', 0, 0, 0, 1790968058511) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5463b6f4ecb3dfb4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The first gas field Pakistan discovered in 1952 at ______?', '{"A":"Hyderabad","B":"Peshawar","C":"Sui","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Sui Gas Field, located near Sui in Balochistan Province, Pakistan.It was discovered by Pakistan Petroleum Limited in 1952.Production of Sui gas began in 1955.It remains the largest natural gas field in Pakistan.', 0, 0, 0, 1790968058511) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f2c9bc7b83bd0f86', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'When a gas turns into liquid, the process is called?', '{"A":"Condensation","B":"Evaporation","C":"Deposition","D":"Sublimation"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The process in which a gas turns back into a liquid is called condensationIt happens when gas molecules lose energy and cool down, causing them to come together and form droplets. Example: Dew forming on grass or water droplets on a cold glass.', 0, 0, 0, 1790968058511) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5698349de9dba57c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The electron was first identified by?', '{"A":"J. J. Thompson","B":"D. Rutherford","C":"J. Kepler","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Electron: Discovered by J. J. Thomson, 1897Additional information:Proton: Discovered by Ernest Rutherford, 1919Neutron: Discovered by James Chadwick, 1932Atomic Model Proposed: Plum Pudding ModelSignificance: First subatomic particle discoveredLast verified on 16-01-2026', 0, 0, 0, 1790968058511) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f5ec78967a221f00', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Who discovered Hydrogen?', '{"A":"Henry Cavendish","B":"Antoine Lavoisier","C":"Robert Boyle","D":"John Dalton"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation - Discovered by: Henry Cavendish - Year: 1766 Symbol: HAtomic mass: 1.00784 uAtomic number: 1Named by: Antoine Lavoisier (1783)', 0, 0, 0, 1790968058511) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f2072fda0aab2635', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which gas among the following is a major greenhouse gas?', '{"A":"Carbon Dioxide","B":"Nitrogen","C":"Argon","D":"Oxygen"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Carbon dioxide (CO2) is a major greenhouse gas.It responsible for about 65% of the Earth''s greenhouse effect.', 0, 0, 0, 1790968058511) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7c99ebda16a2d477', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'What is the percentage of nitrogen gas in air?', '{"A":"98%","B":"58%","C":"88%","D":"78%"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The air in Earth''s atmosphere is made up of approximately 78 percent nitrogen and 21 percent oxygen.', 0, 0, 0, 1790968058511) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0079d8cb8924183c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The pH of water is ______?', '{"A":"5","B":"6","C":"7","D":"7.7"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The pH of pure water (H20) is 7 at 25 °CpH stands for "Potential Hydrogen"whileBlood is normally slightly basic, with a normal pH range of about 7.35 to 7.45.', 0, 0, 0, 1790968058551) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fd455879e5250474', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The most common element found on Earth is _____?', '{"A":"Hydrogen","B":"Oxygen","C":"Nitrogen","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Aluminum is the most abundant metal in the Earth''s crust, and the third most abundant element therein, after oxygen and silicon.MOST IMPORTANT KEY POINTS:Most abundant elements found in air are? (1) Nitrogen (2) Oxygen (3) ArgonMost abundant elements found in earth’s crust are? (1) Oxygen (2) Silicon (3) AluminumMost abundant elements found in Universe are? (1) Hydrogen (2) Helium (3) OxygenMost abundant elements found in Human Body are? (1) Oxygen (2) Carbon (3) Hydrogen', 0, 0, 0, 1790968058551) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_03b9f12d7a4545aa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'After the discovery of atomic number, scientists noted that atomic number can be used to arrange elements in a systematic way. The atomic number was discovered by _______?', '{"A":"Isaac Newton","B":"James chadwak","C":"Henry Moseley","D":"Albert Einstein"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The atomic number was discovered by Henry Moseley in 1910.Henry Moseley was an English physicist.', 0, 0, 0, 1790968058551) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_30ec8d4e8ab9e056', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Carbon dating is used for the estimation of the age of ____?', '{"A":"Rocks","B":"Fossils","C":"Soil","D":"Water"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Carbon Dating is one of the methods to calculate the age of fossils. It is based on the principle of Radioactivity.Radioactive isotope: Carbon-14 (¹⁴C)Half-life: 5,730 yearsDeveloped by: Willard LibbyIntroduced: 1949Dating range: Up to 50,000 yearsLast verified on 20-07-2026', 0, 0, 0, 1790968058551) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f62fa141f9345999', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which one among the following is a hydrocarbon compound? Candle wax, Polyurethane, Glycerol, Aspirin', '{"A":"Candle wax","B":"Polyurethane","C":"Glycerol","D":"Aspirin"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hydrocarbon compounds are typically derived from fossil fuels and consist of hydrogen and carbon atoms.Examples include fuels like gasoline, natural gas, and propane, as well as waxes like candle wax and paraffin wax.', 0, 0, 0, 1790968058552) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_07bfa11ca0763875', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The atoms of same element which have the same atomic number but different mass numbers are known as?', '{"A":"Isotopes","B":"Isoelectronic","C":"Isomers","D":"Isobars"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Isotopes are atoms of the same element (same number of protons/nuclear charge) but different masses (different number of neutrons).Example: Hydrogen-1, Hydrogen-2 (Deuterium), and Hydrogen-3 (Tritium) are isotopes of hydrogen.', 0, 0, 0, 1790968058552) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f8b78a05f92baabf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'What type of acid is used in car batteries?', '{"A":"Hydrochloric acid","B":"Hydrofluoric acid","C":"Nitric acid","D":"Sulphuric acid"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The fluid in your lead-acid battery is called Electrolyte. It''s actually a mixture of sulphuric acid and water.', 0, 0, 0, 1790968058552) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8268612ab6bc4ec6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Where chemical digestion of proteins start?', '{"A":"Oesophagus","B":"Small intestine","C":"Mouth","D":"Stomach"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Chemical digestion of proteins begins in the stomachMechanical digestion (chewing) starts in the mouth, The chemical breakdown requires gastric juices, specifically hydrochloric acid (HCL) The enzyme pepsin activates and breaks down protein molecules.Last updated by NS on 20-April-2026', 0, 0, 0, 1790968058552) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a845272acef132b2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'DNA molecule does not contain ______?', '{"A":"Cytosine","B":"Adenine","C":"Uracil","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation DNA contains Adenine (A), Thymine (T), Cytosine (C), and Guanine (G).Uracil (U) is found only in RNA, replacing Thymine.', 0, 0, 0, 1790968058602) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_50146dd283e80dc0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Charge of a proton is?', '{"A":"Negative","B":"Neutral","C":"Positive","D":"Uncharged"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Proton has a positive charge.Its charge is +1e.1e = 1.602 x10^-19 C.Classification: BaryonComposition: 2 up quarks (u), 1 down quark (d)Statistics: FermionicFamily: HadronInteractions: Gravity, electromagnetic, weak, strongSymbol p, p+, N+, 11H+Theorized: William Prout (1815)Discovered: observed as H+ by Eugen Goldstein (1886). Identified in other nuclei (and named) by Ernest Rutherford (1917–1920).', 0, 0, 0, 1790968058602) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_815d4910bc63444a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Who discovered the periodic table?', '{"A":"Albert Einstein","B":"Dmitri Mendeleev","C":"Isaac Newton","D":"Marie Curie"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Discoverer: Dmitri Mendeleev, a Russian chemist.- Year: 1869Mendeleev’s periodic law states: “The properties of elements are a periodic function of their atomic masses.” - The modern periodic table is based on atomic number (not atomic mass), but Mendeleev’s work was crucial. - His table helped organize chemical knowledge and predict new elements.', 0, 0, 0, 1790968058602) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9f67195fa34ab4a5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which salt is used as a laxative in medicine to treat constipation?', '{"A":"Epsom salt (Magnesium sulfate)","B":"Copper Sulphate","C":"Sodium Chloride","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Magnesium Sulphate (Epsom salt) is a common laxative that helps relieve constipation by drawing water into the intestines.It works by softening stool and promoting bowel movements when taken in proper dosage.', 0, 0, 0, 1790968058602) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c305ebb17df4b7b3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Name the element which is used to fabricate solar cells and transistors?', '{"A":"Germanium","B":"Iron","C":"Silicon","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Silicon (Si) is the element most commonly used to fabricate solar cells and transistors. Silicon is a semiconductor material that is widely used in the production of electronic components, including:Solar cells (photovoltaic cells)TransistorsMicroprocessorsDiodes', 0, 0, 0, 1790968058602) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f8de3ec5e51d0c91', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which of the following instruments may be used to measure the optical activity of a compound?', '{"A":"Polarimeter","B":"Spectrophotometer","C":"Calorimeter","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A polarimeter measures the optical activity of a compound by analyzing the rotation of plane-polarized light.Optically active compounds, like chiral molecules, rotate light either clockwise (dextrorotatory) or counterclockwise (levorotatory).', 0, 0, 0, 1790968058602) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_49f47fb0be7e0a62', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'What is the name of common salt ?', '{"A":"Sulpher","B":"Vitamin","C":"Hydrogen","D":"Sodium chloride"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation salt (NaCl), sodium chloride, a mineral substance of great importance to human and animal health, as well as to industry. Formula: NaClMolar mass: 58.44 g/molMelting point: 801 °C******ND30-12-2022ND5-07-2023', 0, 0, 0, 1790968058602) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_96e945c13a2d0c8f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which poisonous gas is produced when coal is burnt without enough air supply?', '{"A":"Ammonia","B":"Carbon monoxide","C":"Nitrogen","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Carbon monoxide (CO) is a colorless, odorless, and tasteless gas that is produced when coal is burned without sufficient oxygen.CO is highly toxic.It can be deadly in high concentrations, as it displaces oxygen in the bloodstream.', 0, 0, 0, 1790968058602) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6a6c9c55b39932ba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Isotopes are atoms of the same element with different numbers of ______?', '{"A":"Electrons","B":"Protons","C":"Neutrons","D":"Positron"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Atoms of the same element with different numbers of neutrons are called isotopes.Atoms of the same element have the same number of protons and electrons but different numbers of neutrons.', 0, 0, 0, 1790968058640) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_87c77bc1071d5905', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'What happens in the rusting of iron?', '{"A":"Reduction","B":"Decomposition","C":"Displacement","D":"Oxidation"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Oxidation is the loss of electrons during a reaction by a molecule, atom or ion.Oxidation occurs when the oxidation state of a molecule, atom or ion is increased.The opposite process is called reduction, which occurs when there is a gain of electrons or the oxidation state of an atom, molecule, or ion decreases.', 0, 0, 0, 1790968058640) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2205ce1c6f7cbc48', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Neutral pH of a solution is ____?', '{"A":"1","B":"7","C":"14","D":"-7"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation As this diagram shows, pH ranges from 0 to 14, with 7 being neutral. pH less than 7 are acidic.pH greater than 7 are alkaline.', 0, 0, 0, 1790968058640) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8ad1cce083da3eb9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Acid rain is mainly caused by emissions of ______?', '{"A":"Sulfur dioxide and potassium niterate","B":"Sulfur dioxide and Nitrogen oxide in atmosphere","C":"Both A and B","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Acid rain is mainly caused by emissions of Sulfur dioxide and Nitrogen oxide in the atmosphere.Acid rain mainly Causes health problem like Asthma.', 0, 0, 0, 1790968058640) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_992132a1326dae43', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which of the following is not a chemical change?', '{"A":"Milk into curd","B":"Dissolving sugar in water","C":"Photosynthesis","D":"Burning"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dissolving sugar in water is a physical change—no new substance is formed.The sugar can be recovered by evaporation, showing it’s not a chemical reaction.', 0, 0, 0, 1790968058640) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_321c557244a9832e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'In periodic table elements are arranged according to ____?', '{"A":"Increasing atomic mass","B":"Decreasing atomic number","C":"Both A and B","D":"Increasing in atomic number"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The modern periodic table is arranged by increasing atomic number (number of protons).This arrangement resolves inconsistencies in earlier tables and groups elements with similar properties together.', 0, 0, 0, 1790968058640) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_03fa42f2362abc5a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Atom bomb is based on the principle of:', '{"A":"Radioactivity","B":"Nuclear Fission","C":"Nuclear Fusion","D":"Both A & B"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An atomic bomb is based on the nuclear reaction known as nuclear fission, A heavy atomic nucleus splits into two or more lighter nuclei, releasing a large amount of energy in an uncontrolled chain reaction. The bombs dropped on Hiroshima and Nagasaki were examples of nuclear fission bombs, utilizing uranium-235 or plutonium-239 as the fissionable material.', 0, 0, 0, 1790968058640) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_771621d973de8b70', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Diameter of an atom is in the order of?', '{"A":"0.2m","B":"0.2mm","C":"0.2nm","D":"0.2pm"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The diameter of an atom is in the order of 0.2 nanometers (nm), or 200 picometers (pm), which is equivalent to 2 x 10^-10 meters.', 0, 0, 0, 1790968058640) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_15ee7feb3f4f05cb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'A gaseous organic compound C, was burnt in an excess of oxygen. A = 0.112dm sample of C measured at S.T.P, produced 0.88 g of carbon dioxide. How many carbon atoms are there is one molecular?', '{"A":"3","B":"2","C":"4","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Given:Volume of compound C at STP = 0.112 dm³1 mole gas at STP = 22.4 dm³So, moles of C = 0.112 ÷ 22.4 = 0.005 molCO₂ produced:Mass = 0.88 gMoles of CO₂ = 0.88 ÷ 44 = 0.02 molMole ratio:0.005 mol of C → produced 0.02 mol of CO₂Ratio CO₂ : C = 0.02 ÷ 0.005 = 4👉 That means 4 carbon atoms are present in one molecule of C.', 0, 0, 0, 1790968058672) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1432cf18af7c9e1f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Atomic Mass number of oxygen is ______?', '{"A":"16","B":"12","C":"14","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Oxygen has 8 protons and typically 8 neutrons, giving it a mass number of 16.Mass number = Number of protons + Number of neutrons.Discoverers: Joseph Priestley, Carl Wilhelm ScheeleSymbol: OAtomic number: 8Electrons per shell: 2, 6Discovered: 1774', 0, 0, 0, 1790968058672) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8632239870367224', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The syntheses of an RNA molecule from DNA is called _______?', '{"A":"Transition","B":"Andora","C":"Transcription","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Transcription is the process where an RNA molecule is synthesized using DNA as a template.This is the first step in gene expression before translation into proteins.', 0, 0, 0, 1790968058672) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4f7f7791e93f2a13', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Total charge on electron is? –1.6 × 10⁻¹⁹ C, –1.6 × 10⁻¹⁸ C, –1.6 × 10⁻²⁰ C, –3.2 × 10⁻¹⁹ C', '{"A":"–1.6 × 10⁻¹⁹ C","B":"–1.6 × 10⁻¹⁸ C","C":"–1.6 × 10⁻²⁰ C","D":"–3.2 × 10⁻¹⁹ C"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation - The elementary charge on a single electron is -1.6 × 10⁻¹⁹ coulombs.- It’s a fundamental physical constant.The charges of Proton, Electron, Neutron respectively are:Proton: Positive charge (+1)Electron: Negative charge (-1)Neutron: Neutral charge (0)', 0, 0, 0, 1790968058672) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3339a0fdbde5179f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The oxidation state of nitrogen in HNO₃ is _____?', '{"A":"-5","B":"-5","C":"-6","D":"+5"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In HNO₃ (nitric acid):Hydrogen (H) = +1Oxygen (O) = -2 (×3 = -6)Let nitrogen = xSo, +1 + x + (−6) = 0⇒ x = +5Nitrogen has an oxidation state of +5 in HNO₃.', 0, 0, 0, 1790968058672) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e530955d8c01d56f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'In periodic table symbol for Gold is?', '{"A":"Au","B":"Ag","C":"S","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Au comes from the Latin word aurum, meaning "gold" (from "glowing dawn")Atomic number: 79Belongs to group 11 Category: transition metalAdditional information:Atomic mass: 196.97 uMelting point: 1,064°CBoiling point: 2,856°CDensity: 19.3 g/cm³ (very heavy)', 0, 0, 0, 1790968058672) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_76d0b2aba236be1f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The process of conversion of liquid water into vapour is called _____?', '{"A":"Precipitation","B":"Condensation","C":"Evaporation","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Evaporation is the process where liquid water turns into water vapour due to heat.It is a key part of the water cycle, occurring from surfaces like oceans, lakes, and soil.', 0, 0, 0, 1790968058672) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_808328653f03afbf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'What is the primary/main component of natural gas?', '{"A":"Methane","B":"Propane","C":"Butane","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The primary component of natural gas is methane (CH4).Making up 70% to 90% or more of its composition. It is a colorless, odorless, and highly flammable hydrocarbon gas.Characteristics: It is a fossil fuel, often found in rock formations alongside oil or on its own. Last updated question 15 March2026', 0, 0, 0, 1790968058672) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5e100419612fef05', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'What is the ideal gas equation?', '{"A":"PV=nRT","B":"𝑃 𝑉 = 𝑑 𝑅 𝑇","C":"𝐷 = 𝑉 𝑀","D":"Both A and B"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation PV=nRT is the standard form of the ideal gas law, where: PP = pressure VV = volume nn = number of moles RR = gas constant TT = temperature (in Kelvin) PV=dRT is a derived form of the ideal gas equation when you use density ddd instead of moles nn (using n=dVMn = frac{dV}{M}, where MMM is molar mass).', 0, 0, 0, 1790968058702) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9cdcfc98dc62d5c0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The mass of a neutron is nearly same as that of _____?', '{"A":"A proton","B":"An electron","C":"An epsilon","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A neutron has mass ≈ 1.675 × 10⁻²⁷ kg, very close to a proton’s mass.An electron is much lighter (≈ 1/1836 of a proton), so not comparable.', 0, 0, 0, 1790968058702) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0b9fc5642a68082e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The pH of a solution having H⁺ ions concentration of 1 X 10⁻⁷ will be _____?', '{"A":"Neutral","B":"Acidic","C":"Alkaline","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation pH is calculated as pH = -log[H⁺].For [H⁺] = 1 × 10⁻⁷ M, pH = 7 → the solution is neutral.', 0, 0, 0, 1790968058702) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_eb8dfcdaa61e1bfd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Who developed the atomic theory?', '{"A":"Joseph-Louis Proust","B":"John Dalton","C":"Henry Cavendish","D":"Antoine-Laurent Lavoisier"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation John Dalton proposed the Atomic Theory of Matter in 1803.He stating that all matter is made up of tiny indivisible particles called atoms.His theory laid the foundation for modern chemistry by explaining the laws of chemical combination.', 0, 0, 0, 1790968058702) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1c53fc56a2c2ea9c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Chemical formula of Plaster of Paris (Hemi-hydrated gypsum) is?', '{"A":"CaCO₃","B":"CaSO₄·2H₂O","C":"CaSO₄·½H₂O","D":"CaCl₂"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Plaster of Paris (POP) is calcium sulfate hemihydrate (CaSO₄·½H₂O). It is made by heating gypsum (CaSO₄·2H₂O) to remove water partially.', 0, 0, 0, 1790968058702) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_45281c3ca94e4747', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Photosynthesis involves which of the following? Energy rich carbohydrates are synthesized, CO₂ and H₂ of the water, Chlorophyll alone & converts light energy to chemical energy, All of the above', '{"A":"Energy rich carbohydrates are synthesized","B":"CO₂ and H₂ of the water","C":"Chlorophyll alone & converts light energy to chemical energy","D":"All of the above"}', 'D', NULL, 0, 0, 0, 1790968058702) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e8f78c2d25acb33b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Complete transfer of one or more electrons from one atom to different atom forms?', '{"A":"Ionic bonds","B":"Covalent bonds","C":"Metallic bonding","D":"Co-ordinate bonding"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The complete transfer of one or more electrons from one atom to another atom forms an ionic bond. This type of bond is characterized by the electrostatic attraction between two ions with opposite charges, typically a metal cation and a nonmetal anion. The atom that loses an electron becomes a positively charged ion (cation), while the atom that gains an electron becomes a negatively charged ion (anion).', 0, 0, 0, 1790968058702) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4a74a6515eb329d9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Number of elements present in fifth period of periodic table is _____?', '{"A":"12","B":"16","C":"18","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The 4th and 5th periods in the periodic table are known as the long periods.These periods contain 18 elements each, making them the longest periods in the periodic table.Important Points:Short periods: 1st and 2nd periods (2 and 8 elements, respectively)Long periods: 4th and 5th periods (18 elements each)Normal periods: 3rd and 6th periods (8 and 12 elements, respectively)', 0, 0, 0, 1790968058702) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_631a8a9b0a4127f7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which of the following is mono-atomic?', '{"A":"Oxygen","B":"Neon","C":"Nitrogen","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Neon is a noble gas that exists as single atoms (mono-atomic) in nature.Oxygen (O₂), Nitrogen (N₂), and Fluorine (F₂) are diatomic molecules.', 0, 0, 0, 1790968058733) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5a0815967ba3837e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which of the following is a synthetic chemical fertilizer?', '{"A":"Poultry manure","B":"Compost","C":"DAP","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation DAP (Diammonium Phosphate) is a synthetic chemical fertilizer rich in nitrogen and phosphorus.Manures and compost are natural fertilizers, not synthetic.', 0, 0, 0, 1790968058733) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2643904eac3ff56e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'A liquid boils at its _____?', '{"A":"Neutral point","B":"Melting point","C":"Boiling point","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A liquid boils at its boiling point, where its vapor pressure equals the external atmospheric pressure.Melting point is for solid → liquid change, not boiling.', 0, 0, 0, 1790968058733) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a962cf51b30daa8d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'In every atom, the number of protons is equal to ______?', '{"A":"Number of electrons","B":"Number of neutrons","C":"Number of nucleons","D":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In a neutral atom, the number of protons = electrons, ensuring electrical neutrality.Protons are not always equal to neutrons or nucleons (protons + neutrons).', 0, 0, 0, 1790968058733) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8873f52af0575f5e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The fact that when the temperature of given gas is held constant, its density is proportional to the absolute pressure. It is another statement of ____?', '{"A":"Boyle’s Law","B":"Charles’s Law","C":"Dalton''s Law","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Boyle’s Law: At constant temperature, pressure is directly proportional to density (P ∝ ρ).This is because P ∝ 1/V, and since ρ = m/V, higher pressure means higher density for a fixed mass.', 0, 0, 0, 1790968058733) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d2a56f6bd2f8b911', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', '_____ is a polymer compound.', '{"A":"CH₄","B":"SO₂","C":"PVC","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation PVC (Polyvinyl chloride) is a synthetic polymer made from repeating vinyl chloride monomers.CH₄, SO₂, and CO₂ are simple molecules, not polymers.', 0, 0, 0, 1790968058733) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_047d943baaab5db4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'When you stir salt into water, you are making a _____?', '{"A":"Molecule","B":"Solvent","C":"Solution","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Salt (solute) dissolves in water (solvent) to form a homogeneous mixture called a solution.The salt ions spread evenly throughout the water, making it uniform.', 0, 0, 0, 1790968058733) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_960095adc32bd276', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which of the following is an inert gas?', '{"A":"H₂","B":"O₂","C":"Argon","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Argon is a noble (inert) gas found in Group 18 of the periodic table; it is chemically unreactive.H₂ and O₂ are reactive gases.', 0, 0, 0, 1790968058733) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_66bcb3b3a5fce324', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The symbol of sodium is ______?', '{"A":"Na","B":"Sa","C":"Pa","D":"Ca"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Symbol: Na (from Latin natrium)Atomic number: 11Atomic mass: 22.99 uGroup: 1 (alkali metals)Period: 3State at room temperature: Solid', 0, 0, 0, 1790968058767) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a419f3ab99e57694', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The formula of sulfuric acid is ______?', '{"A":"H2SO3","B":"H2SO4","C":"H2SO5","D":"H2SO6"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The formula for sulfuric acid is H2SO4.It indicating that one molecule contains two hydrogen atoms, one sulfur atom, and four oxygen atoms.', 0, 0, 0, 1790968058767) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_227e877d6e712d66', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The electronic that have been knocked out of the outer most shell of an atom are known as?', '{"A":"Free Electrons","B":"Valence Electrons","C":"Core Electrons","D":"Conductors"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The electrons that have been knocked out of the outermost shell of an atom are free electrons, which are able to move freely and conduct electricity.', 0, 0, 0, 1790968058767) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f295718874f54d49', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'A real gas can be approximated to an ideal gas at ______?', '{"A":"Low density","B":"High pressure","C":"Low temperature","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A real gas can be approximated to an ideal gas at low density.This is typically achieved under conditions of low pressure and high temperature.', 0, 0, 0, 1790968058767) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c0fe4f3ec1489c5a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Potassium is kept in _____?', '{"A":"Kerosene","B":"Water","C":"Ammonia","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Potassium is a highly reactive alkali metal and reacts violently with water and air.Storing it under kerosene prevents contact with moisture and oxygen, keeping it safe.', 0, 0, 0, 1790968058767) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8fb2b9c820e4414f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Why does Neon (Ne) gas diffuse faster than CO₂ gas?', '{"A":"Neon is a noble gas","B":"Neon is less dense than air","C":"Neon atoms have lower mass","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation According to Graham’s law of diffusion, gases with lower molar mass diffuse faster.Neon (molar mass 20 g/mol) is lighter than CO₂ (44 g/mol), so it diffuses more quickly.', 0, 0, 0, 1790968058767) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0cf5d3e14fe64948', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Why is carbon used in the purification of drinking water?', '{"A":"It removes odors and impurities","B":"It disinfects the water","C":"It filters out solids","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Activated carbon has a large surface area that adsorbs odors, colors, and chemical impurities from water.It does not disinfect water or filter out large solids; its main role is purification by adsorption.', 0, 0, 0, 1790968058767) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8e8e6ff974151ba8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Hydrogen chloride molecule contains _____?', '{"A":"Co-ordinate bond","B":"Covalent bond","C":"Double bond","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In HCl, hydrogen and chlorine share one pair of electrons, forming a single covalent bond.The bond is polar covalent because chlorine is more electronegative than hydrogen.', 0, 0, 0, 1790968058767) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_940b06f4d940bac4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The law which describes the relationship between the volume and temperature of a gas at constant pressure is called _____?', '{"A":"Avogadro’s law","B":"Boyle’s law","C":"Charles’s law","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Charles’s law states that at constant pressure, the volume of a gas is directly proportional to its absolute temperature.Boyle’s law relates pressure and volume.Avogadro’s law relates volume and moles.Dalton’s law deals with partial pressures.', 0, 0, 0, 1790968058809) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_33c4eede2b9c4e57', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'If one mole of gaseous hydrogen is mixed with one mole of gaseous iodine in an empty container then with the passage of time rate of _____?', '{"A":"The forward reaction increases","B":"Both forward and reverse reaction remains unaffected","C":"The reverse reaction decreases","D":"The forward reaction decreases"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation If one mole of gaseous hydrogen is mixed with one mole of gaseous iodine in an empty container, then with time, the forward reaction decreases Because as the reaction proceeds, the concentration of hydrogen and iodine decreases, leading to a slower rate of forward reaction, while the reverse reaction starts to increase until equilibrium is reached.', 0, 0, 0, 1790968058809) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c06b36a8a755f4a6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'All of the following are liquid crystals except? Soap solution, DNA, Cholesteryl format, Engine oil', '{"A":"Soap solution","B":"DNA","C":"Cholesteryl format","D":"Engine oil"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A liquid crystal is a state of matter that exhibits properties of both liquids and crystals. It requires the molecules to have a specific structure, often long and rigid, to form ordered phases. While soap can form structures similar to liquid crystals when mixed with water (forming micelles), pure soap is not a liquid crystal. The other options listed, DNA, cholesteryl format, and engine oil, can all exhibit liquid crystal properties under certain conditions.', 0, 0, 0, 1790968058809) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_54ebe24a95ee419b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Methylamine and hydrogen peroxide are liquids due to?', '{"A":"Dipole-dipole forces","B":"Dispersion forces","C":"Hydrogen bonding","D":"Dipole-dipole forces and dispersion forces"}', 'C', NULL, 0, 0, 0, 1790968058809) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e2500cdcddc86c29', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'A container with a porous wall is filled with He, H2, N2, and CO2. Which one of these gases will diffuse out of the container in the least time to diffuse out the container?', '{"A":"He","B":"H2","C":"N2","D":"CO2"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation According to Graham’s Law of Diffusion, gases with lower molar mass diffuse faster.Molar masses:- H₂ = 2 g/mol (lowest)- He = 4 g/mol - N₂ = 28 g/mol - CO₂ = 44 g/mol Since H₂ has the smallest molar mass, it will diffuse the fastest and thus escape in the least time.', 0, 0, 0, 1790968058809) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_96781f0c983f089b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'If maximum value of principle quantum number for an atom is four then total number of electrons in an atom will be?', '{"A":"32","B":"60","C":"18","D":"28"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation If the maximum value of the principal quantum number (n) for an atom is 4, the total number of electrons in that atom is 32. This is because the maximum number of electrons in a shell is given by 2n², and for n=4, this calculation results in 2 * 4² = 32.', 0, 0, 0, 1790968058809) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f2bb7072c095452d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'One-gram atom of chlorine is equal to?', '{"A":"One mole of chlorine atoms","B":"71 grams","C":"One gram of chlorine atoms","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation One gram atom of any element refers to one mole of its atoms.- The molar mass of chlorine (Cl) is approximately 35.5 g, so: - One gram atom of chlorine = 1 mole of Cl atoms = 35.5 g, not 71 g (which is for Cl₂ molecules).', 0, 0, 0, 1790968058809) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f4a5945010ef7f82', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'One atom of sodium is?', '{"A":"23 g","B":"23 / Nₐ g","C":"1 mole","D":"6.022 × 10²³ atoms"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The atomic mass of sodium is 23 g/mol. - This means 1 mole (6.022 × 10²³ atoms) of sodium weighs 23 grams. - So, the mass of one atom of sodium is:= 23 g / Nₐ = 23 / (6.022 × 10²³) gramsSo the correct option is: 23 / Nₐ g.', 0, 0, 0, 1790968058809) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_37b277a4f55b220f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'In transistor, the emitter base function is?', '{"A":"Reverse biased","B":"Forward biased","C":"Neutral","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In a transistor, the emitter-base junction is forward-biased. For a transistor to function properly as an amplifier, the emitter-base junction needs to be forward-biased, allowing current to flow from the emitter to the base.', 0, 0, 0, 1790968058844) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3359315865f02e96', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'How many molecules of carbon dioxide will be produced from the breakdown of two molecules of glucose in aerobic respiration?', '{"A":"2","B":"4","C":"6","D":"12"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The breakdown of two molecules of glucose in aerobic respiration will produce 12 molecules of carbon dioxide (CO2). The balanced chemical equation for aerobic respiration shows that one molecule of glucose (C6H12O6) produces six molecules of carbon dioxide (6CO2).Therefore, if two molecules of glucose are broken down, the total number of CO2 molecules produced will be: 2 molecules of glucose * 6 molecules of CO2 per glucose = 12 molecules of CO2.', 0, 0, 0, 1790968058844) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_096f45838567c684', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The first stable product of dark reaction is ______ carbon molecule?', '{"A":"6","B":"4","C":"3","D":"5"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first stable product of the dark reaction (Calvin cycle) is 3-phosphoglycerate (3-PGA), a 3-carbon compound.This occurs after CO₂ fixation by RuBisCO.', 0, 0, 0, 1790968058844) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1df2f02cd049cf36', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which gas is used in the electric bulb?', '{"A":"Argon","B":"Silver","C":"Mercury","D":"Sodium"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Argon is a commonly used gas used to fill incandescent light bulbs. It increases bulb life by preventing the tungsten filaments from deteriorating too quickly. Other gases are also used in lighting such as:HeliumNeonNitrogenKrypton', 0, 0, 0, 1790968058844) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b30c48603c8291df', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Slight oxidation of a primary alcohol gives ______?', '{"A":"An aldehyde","B":"A ketone","C":"An ether","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Primary alcohols oxidize to form aldehydes first.Further oxidation converts aldehydes into carboxylic acids.', 0, 0, 0, 1790968058844) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f0e8675a3d8b5dea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The source of oxygen in photosynthesis is?', '{"A":"Water","B":"Salt","C":"Mineral","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation During photosynthesis, plants use water (H2O) along with carbon dioxide (CO2) to produce glucose and oxygen. The oxygen released comes specifically from the water molecule.Being split apart to provide the oxygen atoms needed for the glucose molecule.', 0, 0, 0, 1790968058844) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b88c1b1d856b8637', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'A process in which liquid changes into gas without boiling is called?', '{"A":"Condensation","B":"Melting","C":"Freezing","D":"Evaporation"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Evaporation is the process where liquid turns into gas at temperatures below its boiling point.It occurs at the surface of the liquid.It is influenced by factors like temperature and surface area.', 0, 0, 0, 1790968058844) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_892b6dafbd1dcfe1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'What is the first element on the periodic table?', '{"A":"Helium","B":"Hydrogen","C":"Lethium","D":"Beryllium"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The elements of the periodic table sorted by atomic numberAtomic number Name chemical element Symbol1 Hydrogen H2 Helium He3 Lithium Li******RY 15-01-2023', 0, 0, 0, 1790968058844) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2d4a4cced354598e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Symbol of Iron?', '{"A":"Fe","B":"Ff","C":"Fg","D":"None of thsese"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation IRON:Symbol: FeAtomic mass: 55.845 uAtomic number: 26Electron configuration: [Ar] 3d64s2Density: 7.874 g/cm³ (near room temperature)Electrons per shell: 2, 8, 14, 2Melting point: 1,538 °C', 0, 0, 0, 1790968058887) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_64e9736937c879d8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Citric Acid found in ____?', '{"A":"Lemons","B":"Apple","C":"Mango","D":"Banana"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Citric acid occurs naturally in:Lemons, Limes, Pineapples, Grapefruits, Berries (not blueberries), Tomatoes,Broccoli, Carrots, and some varieties of Peppers.', 0, 0, 0, 1790968058887) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7d8cdefb8c4b3210', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Common name for Sodium chloride (NaCl) is?', '{"A":"Baking soda","B":"Sugar","C":"Salt","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Common salt is chemically known as sodium chloride (NaCl), It is an ionic compound composed of sodium and chloride ionsRepresenting a 1:1 ratio of sodium and chloride ionsFormula: NaClMelting point: 801 °CDensity: 2.16 g/cm³Boiling point: 1,465 °CQuestion updated on 11-02-2026', 0, 0, 0, 1790968058887) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2ac4dc40b9ee955b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Acid rain contains high levels of _____?', '{"A":"Sulphuric Acid","B":"Nitric Acid","C":"Oxalic Acid","D":"Both A and B"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sulfur dioxide (SO₂) and nitrogen dioxide (NO₂) are primary precursors of acid rain. Acid rain is a consequence of these atmospheric pollutants reacting with water, oxygen, and other chemicals to form acidic compounds. These acids contribute to environmental damage.', 0, 0, 0, 1790968058887) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_201fc2b919ffd7c3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Select the atom with the largest ionization energy in the following atoms? N, P, AS, Sb', '{"A":"N","B":"P","C":"AS","D":"Sb"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation According to the periodic trends, Nitrogen (N) has the largest ionization energy among the given atoms: N, P, As, and Sb. Ionization energy generally increases from left to right across a period on the periodic table. Since Nitrogen is to the left of Phosphorus, Arsenic, and Antimony, it will have the highest ionization energy. Additionally, within a group, ionization energy decreases down the column.', 0, 0, 0, 1790968058887) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dcf654e359d8ebd3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Proton was discovered by _____?', '{"A":"Ernest Rutherford","B":"Alexander Fleming","C":"Darwin","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ernest Rutherford showed (1919) that nitrogen under alpha-particle bombardment ejects what appear to be hydrogen nuclei. By 1920 Ernest Rutherford had accepted the hydrogen nucleus as an elementary particle, naming it proton.whileElectron was discovered by J. J. Thomson in 1897.Neutron Discovered by James Chadwick', 0, 0, 0, 1790968058887) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e690bae87e753bcb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The rich source of iron is', '{"A":"Milk","B":"Eggs","C":"pulses","D":"Green vegetables"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Leafy vegetables such as spinach, kale, swiss chard, collard greens, and beet greens They contain 2.5-6.4 mg of iron per cooked cup or 14-36% of RDI.Rich sources of iron include both animal and plant-based foods. Heme iron, found in meat, poultry, and seafood, is more readily absorbed by the body. Non-heme iron, found in plant-based foods, is also important, and its absorption can be enhanced by vitamin C.', 0, 0, 0, 1790968058887) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a431f5ce4d936628', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The most electronegative element of the periodic table is ______?', '{"A":"Chlorine","B":"Nitrogen","C":"Fluorine","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fluorine is the most electronegative element (3.98 on the Pauling scale).7 valence electrons (2s² 2p⁵); needs one more for a stable noble gas configurationSmall atomic radius → strong pull on bonding electronsHigh effective nuclear charge', 0, 0, 0, 1790968058887) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_229c3888cbbf05ba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'What is the chemical name of limestone?', '{"A":"Sodium Bicarbonate","B":"Calcium carbonate","C":"Gypsum","D":"Limestone carbonate"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Limestone consists of calcium carbonate, which has the chemical formula CaCO3. Calcium carbonate is a chemical compound. It is a common substance found in rocks as the minerals calcite.', 0, 0, 0, 1790968058924) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_00ee9d68e997c26d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'What the chemical formula of Methane Gas?', '{"A":"CH8","B":"CH4","C":"CH9","D":"CH6","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Methane is a chemical compound with the chemical formula CH4 (one carbon atom bonded to four hydrogen atoms).*****', 0, 0, 0, 1790968058924) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_57d1e2594df34795', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which of the following increases the rate of a chemical reaction?', '{"A":"Catalyst","B":"Inhibitor","C":"Reactant","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A catalyst is a substance that speeds up a chemical reaction without being consumed or altered.Catalysts increase the rate of reaction by lowering the activation energy required for the reaction to occur.', 0, 0, 0, 1790968058924) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c5dd3e6864bec2a3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'As the number of proton increases, the ionization energy?', '{"A":"Decreases","B":"Increases","C":"Remain same","D":"Fluctuate"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Across a period: Ionization energy increases (stronger nuclear charge).Down a group: Ionization energy decreases (electron shielding + distance).Exceptions within a period:Group 13: slight dip (new p subshell).Group 16: slight dip (electron pairing repulsion).', 0, 0, 0, 1790968058924) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d481bd878c18e5a4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The element used in glass preparation due to the transparent nature of its compounds is _____?', '{"A":"Selenium","B":"Iodine","C":"Silicon","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Silicon is a chemical element with the symbol Si and atomic number 14.Silicon dioxide (SiO₂) is the primary component in glass, making it transparent and durable.It is obtained from sand (quartz).It is essential in glass manufacturing', 0, 0, 0, 1790968058924) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a4daa94b267e425d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'A solution with pH = 7 is _____?', '{"A":"Neutral","B":"Acidic","C":"Basic","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation If the pH value is greater than 7, the solution is basic (also known as alkaline).This means that the concentration of hydroxide ions (OH-) is higher than the concentration of hydrogen ions (H+).Key Points:pH < 7: AcidicpH = 7: NeutralpH > 7: Basic (or alkaline)', 0, 0, 0, 1790968058924) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_30b2bc2a40b26a7c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The position of an element in the Periodic Table is determined by its __________ number.', '{"A":"Electron","B":"Proton","C":"Neutron","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Elements are placed in order on the periodic table based on their atomic number, how many protons they have. In a neutral atom, the number of electrons will equal the number of protons, so we can easily determine electron number from atomic number.', 0, 0, 0, 1790968058924) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_11fb1c6fbc3825cd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'What is the atomic sign of potassium?', '{"A":"P","B":"Pb","C":"K","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Potassium is the chemical element.Symbol: K Atomic number: 19Electron configuration: 4s1Electrons per shell: 2, 8, 8, 1', 0, 0, 0, 1790968058924) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4a5c95b02453f4fa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Gas molecules in a container _______?', '{"A":"Move parallel","B":"Move randomly","C":"Unable to move","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Gas molecules move in random directions with high speed and energy.This random motion leads to collisions with each other and the container walls.', 0, 0, 0, 1790968058972) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7cfe0e4cb7773d85', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which gases/elements are used in gas-welding?', '{"A":"Oxygen, Acetylene and Argon","B":"Oxygen, Acetylene and Nitrogen","C":"Air and Acetylenes","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Oxy-acetylene welding is the most common gas welding method, using oxygen and acetylene to produce a high-temperature flame.Argon is sometimes used as a shielding gas in welding processes like TIG (Tungsten Inert Gas) welding, making the combination valid in broader gas welding contexts.', 0, 0, 0, 1790968058972) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_511688e349124d27', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The chemical formula for methane gas is?', '{"A":"CH8","B":"CH6","C":"CH4","D":"CH2"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Methane is the simplest of saturated hydrocarbons with a chemical formula CH4.It consists of four hydrogen atoms and one carbon atom.It is the simplest alkane.', 0, 0, 0, 1790968058972) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5c34d45893e02aa3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Cooking gas is mixture of ______?', '{"A":"Butane and Nitrogen","B":"Propane and Butane","C":"Carbon and Propane","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cooking gas, also known as liquified petroleum gas (LPG), is a mixture of propane and butane. It is a flammable mixture of hydrocarbon gases.', 0, 0, 0, 1790968058972) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_239fd37750607ad6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which disease is caused by deficiency of Iron?', '{"A":"Berberi","B":"Anaemia","C":"Rickets","D":"Scurvy"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Iron deficiency can lead to Anaemia, a condition characterized by:Low red blood cell countPale skinFatigueShortness of breathDizziness', 0, 0, 0, 1790968058972) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_09371817a803e05c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Isotopes are atoms with different atomic masses but differs in ______?', '{"A":"Number of Neutrons","B":"Number of Protons","C":"Number of Electrons","D":"None of these"}', 'A', NULL, 0, 0, 0, 1790968058972) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e97d9788914f5546', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Movement of liquid molecules from lower concentration to higher concentration is called as _____?', '{"A":"Pinocytosis","B":"Active Transport","C":"Phagocytosis","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Transport:Requires energy (ATP) to move molecules against the concentration gradient (low → high).Example: Sodium-potassium pump in cells.', 0, 0, 0, 1790968058972) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3983150b94343a73', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Hydrogen bomb is an example (depends upon) of the process of _____?', '{"A":"Nuclear Fission","B":"Nuclear Fusion","C":"Annihilation","D":"Pair production"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The core principle behind a hydrogen bomb is the fusion of light atomic nuclei.Specifically isotopes of hydrogen (deuterium and tritium), under extremely high temperatures and pressures.', 0, 0, 0, 1790968058972) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7e9509464f40ae54', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which of the following is NOT a compound?', '{"A":"Milk","B":"Chalk","C":"Ammonia","D":"Table Salt"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Milk is a mixture, not a compound — it contains water, fats, proteins, etc., physically combined.Chalk (CaCO₃), Ammonia (NH₃), and Table Salt (NaCl) are pure compounds with fixed chemical formulas.', 0, 0, 0, 1790968059016) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5518c1be3ae71fda', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'In modern periodic table, how many periods are there?', '{"A":"7","B":"8","C":"9","D":"6"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the modern periodic table, there are 7 periods (horizontal rows) and 18 groups (vertical columns).', 0, 0, 0, 1790968059016) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_938591b1f47309fa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'A bond between fatty acid and glycerol is _____?', '{"A":"Ester Bond","B":"Glycosidic linkage","C":"Peptide linkage","D":"Phosphate bridge"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The bond between a fatty acid and glycerol is called an ester bond. This bond forms when the hydroxyl group (-OH) of glycerol combines with the carboxyl group (-COOH) of the fatty acid, releasing a molecule of water (H2O) in a process called dehydration synthesis.', 0, 0, 0, 1790968059016) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fe925fe6641b8a35', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which of the following organic compound does not show position as well as functional group isomerism?', '{"A":"Pentanal","B":"Butanoic acid","C":"Pentanone","D":"Butanol"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pentanal is an aldehyde, and aldehydes do not show functional group isomerism with other groups.It also has no other position for –CHO group, so no position isomerism either.', 0, 0, 0, 1790968059016) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6094c74ad733df30', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'When the 6d orbital is complete the entering electron goes into?', '{"A":"7f","B":"7s","C":"7p","D":"7d"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When the 6d orbital is completely filled, the next electron enters the 7p orbital. This is based on the Aufbau principle, which dictates that electrons first occupy the lowest energy levels available. After the 6d orbitals (which can hold up to 10 electrons) are filled.The 7p orbitals (which can hold up to 6 electrons) become the next lowest energy.', 0, 0, 0, 1790968059016) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_74d5ebc54743941c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which compound has most acidic hydrogen? Butane, 1 -butyne, 2-butyne, 1-butene', '{"A":"Butane","B":"1-butyne","C":"2-butyne","D":"1-butene"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In 1-butyne, the hydrogen is attached to a carbon with a triple bond (sp hybridization), which makes it more acidic because the carbon can better stabilize the negative charge formed after losing the hydrogen ion.', 0, 0, 0, 1790968059016) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ca76b14d1f360280', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Spinning electron creates ______?', '{"A":"Magnetic field","B":"Electric field","C":"Quantum field","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation While an electron always has an electric field due to its charge, its spin generates a magnetic field. The motion of a charged particle (even if it''s just spinning) creates a magnetic field.', 0, 0, 0, 1790968059016) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4ee82ece3d70eef8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Science of chemical characteristics stands under the heading of ______?', '{"A":"Industerial chemistry","B":"Experimental chemistry","C":"Analytical chemistry","D":"Physical chemistry"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The science of chemical characteristics falls under the heading of analytical chemistry. Analytical chemistry focuses on the study of the composition and structure of matter, which includes identifying and characterizing its chemical properties.', 0, 0, 0, 1790968059016) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e0785a1f1012021e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The force on an electron in a field of 1.8 x 10⁻⁸ NC?', '{"A":"1.6 x 10⁻²⁷","B":"2.6 x 10⁻⁸","C":"2.88 x 10⁻¹¹","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Given the formula and calculation:F = qE= (1.6 × 10⁻¹⁹ C) × (1.8 × 10⁻⁸ N/C)= 2.88 × 10⁻¹¹ N', 0, 0, 0, 1790968059059) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_25de5256ddb3b91d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The pH of mixture of CH₃COONa and CH₃COOH is _____?', '{"A":"7","B":">7","C":"<7","D":"1"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The pH of a mixture of CH₃COONa (sodium acetate) and CH₃COOH (acetic acid) is C. <7. This mixture forms a buffer solution, where the weak acid (CH₃COOH) Its conjugate base (CH₃COO-) is present together, resulting in a pH that is less than 7 (acidic) but not extremely so', 0, 0, 0, 1790968059059) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_72aa4e3d959a8af9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Density of an ideal gas can be calculated by the formula ______?', '{"A":"d=nRT","B":"d=PM/RT","C":"d= m/M RT","D":"d=PV/M"}', 'B', NULL, 0, 0, 0, 1790968059059) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dd801c2545d96c9f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Sucrose is converted into glucose and fructose by enzyme catalyst called _____?', '{"A":"Invertase","B":"Maltase","C":"Urease","D":"Zymase"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The enzyme that converts sucrose into glucose and fructose is called invertase It is also known as sucrase or beta-fructofuranosidase. This process is known as hydrolysis, where water is used to break the glycosidic bond between glucose and fructose in sucrose.', 0, 0, 0, 1790968059059) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dcfbde8640b84a5e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The existence of an element in more than one crystalline forms is known as ______?', '{"A":"Isotropy","B":"Anisotropy","C":"Entropy","D":"Allotropy"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The phenomenon where a chemical element exists in multiple crystalline forms is called allotropy Allotropy refers to the ability of an element to exist in two or more different forms in the same physical state. This is different from polymorphism, which is a broader term referring to any substance (not just elements) that can exist in multiple crystalline forms.', 0, 0, 0, 1790968059059) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fe94c0bac2ebc1ea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The ratio of 𝐶𝑝/𝐶𝑣 for a diatomic gas is equal to ______?', '{"A":"1.67","B":"1.4","C":"1.5","D":"1.6"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation For a diatomic gas (like O₂ or N₂), the ratio of specific heats 𝐶𝑝/𝐶𝑣 is approximately 1.4.This ratio is also known as the adiabatic index (γ).It is used in thermodynamic processes.', 0, 0, 0, 1790968059059) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6e19c4a58e353a63', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which is the average translational kinetic energy of molecules in a gas at temperature 27°C?', '{"A":"6.21 × 10⁻²³","B":"6.21 × 10⁻²⁶","C":"6.21 × 10⁻²¹","D":"6.21 × 10⁻²⁹"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The average translational kinetic energy of a molecule in an ideal gas is given by the formula:E=3/2​kT Where: k = 1.38 times 10^{-23} , text{J/K}k=1.38×10^−23J/K (Boltzmann constant) T=27∘C=300K (since 27°C + 273 = 300 K) Now calculate:E=3​/2×1.38×10^−23×300E=3/2​×4.14×10^−216.21×10^−21 J', 0, 0, 0, 1790968059059) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fc6362c7d49d8004', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'What is the process by which water vapor turns into liquid water, forming clouds?', '{"A":"Condensation","B":"Evaporation","C":"Sublimation","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Condensation is the process where water vapor cools and turns into liquid, forming clouds.Evaporation is when liquid water changes into vapor.Sublimation involves a solid turning directly into a gas.', 0, 0, 0, 1790968059059) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f1a316227541f0b9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'What is the atomic number of carbon?', '{"A":"5","B":"6","C":"7","D":"2"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation It belongs to group 14 of the periodic table.Carbon makes up only about 0.025 percent of Earth''s crust.Symbol: CAtomic mass: 12.011 uAtomic number: 6Electrons per shell: 2, 4', 0, 0, 0, 1790968059095) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fdcbd5f7facb0726', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'How many times the proton is heavier than an electron?', '{"A":"1030","B":"1205","C":"1650","D":"1836"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The mass of the proton is almost 1836 times heavier than that of an electron.whileA neutron is 1842 times heavier than an electron.', 0, 0, 0, 1790968059095) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_92811d6a5951f37f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The process in which an acid is mixed with a base, resulting in the formation of salt and water, is called ______?', '{"A":"Neutralization","B":"Addition","C":"Combustion","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The process in which an acid reacts with a base to form salt and water is called:NeutralizationThis is a common chemical reaction:Acid + Base → Salt + Water', 0, 0, 0, 1790968059095) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e7a04e55c8cd6529', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The most abundant element found in human body by weight is _____?', '{"A":"Hydrogen","B":"Nitrogen","C":"Oxygen","D":"Carbon"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Oxygen makes up about 65% of the human body by weight/mass.It mainly due to its presence in water and organic compounds.It is essential for respiration and various biochemical processes in the body.', 0, 0, 0, 1790968059095) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f2e301318a38aa2d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The smallest particle of an element that exhibits all the properties of the element is the ______?', '{"A":"Electron","B":"Molecule","C":"Atom","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An atom is the smallest unit of an element that retains its chemical properties.It consists of a nucleus (protons and neutrons) and electrons.It is the basic building block of matter.', 0, 0, 0, 1790968059095) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5b6c1766bcfd95c4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'An element has seven electrons in its valence shell, it''s valency is _____?', '{"A":"8","B":"1","C":"0","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An element with 7 valence electrons needs 1 more electron to complete its octet.Therefore, its valency is 1, as it tends to gain 1 electron during bonding.', 0, 0, 0, 1790968059095) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_370ee5407fc43cf3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'An isotope of cobalt is used in the ______?', '{"A":"Nuclear Reactor","B":"Treatment of Fever","C":"Treatment of Cancer","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cobalt-60, an isotope of cobalt, is widely used in radiation therapy to treat cancer.It emits gamma rays, which help destroy cancerous cells in medical treatments.', 0, 0, 0, 1790968059095) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d5762c37470d5671', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The molecular shape of carbon dioxide (CO2) is _____?', '{"A":"Linear structure","B":"Triangular structure","C":"Bent strict","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The carbon dioxide (CO₂) molecule has a linear structure, with a bond angle of 180°.Due to the two double bonds between carbon and oxygen atoms.', 0, 0, 0, 1790968059095) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ac0d4c82ff808a31', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'What Is the Chemical Formula of Sugar?', '{"A":"C12H22O11","B":"C12H21O10","C":"C6H12O11","D":"C12H12O6"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sucrose is also known as Table sugar.Sucrose is a type of common sugar.It is a disaccharide, a molecule which consists of two monosaccharides: glucose and fructose.', 0, 0, 0, 1790968059127) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a5a2337df7e8df44', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'What is the balanced chemical equation for the reaction following reaction? H2(g) + O2(g) → 2H2O(g)', '{"A":"2H₂ + O₂ → 2H₂O","B":"H₂ + 2O₂ → H₂O₂","C":"2H₂ + 2O₂ → 2H₂O","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 2H₂ + O₂ → 2H₂OThis balanced equation ensures 4 hydrogen atoms and 2 oxygen atoms on both sides.It correctly represents the formation of water from hydrogen and oxygen gases.', 0, 0, 0, 1790968059127) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_aecf9d00da78eb49', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The speed of sound in iron or steel (at 20°C) is ______?', '{"A":"5130 m/s","B":"3962 m/s","C":"1570 m/s","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The speed of sound in steel at 20°C is approximately 5100–5200 m/s, with 5130 m/s being a widely accepted value.Sound travels faster in solids like steel due to their high density and elasticity compared to gases and liquids.', 0, 0, 0, 1790968059127) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_725d6ca80cfc13fb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The Periodic Table, which arranges chemical elements according to their Atomic number and chemical properties, was formulated by _____?', '{"A":"John Dalton","B":"Antoine Lavoisier","C":"Otto Hahn","D":"Dmitri Mendeleev"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dmitri Mendeleev, a Russian chemist, formulated the Periodic Table in 1869, arranging chemical elements according to their atomic number (number of protons in the nucleus) and chemical properties.He organized the elements in a logical and systematic order.This making it easier to predict their behavior and relationships.', 0, 0, 0, 1790968059127) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2134def2348b3059', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'A positively charges ion in a compound is called ______?', '{"A":"Anion","B":"Cation","C":"Neutral ion","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cations are positively charged ions. Cations are formed when a metal loses its electrons.', 0, 0, 0, 1790968059127) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ed3b865e6ac888db', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The path which is followed by flow of electron is called ____?', '{"A":"Circuit","B":"Resistor","C":"Conduction","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A circuit is a closed path through which electrons (electric current) flow.It typically includes components like resistors, batteries, and wires, allowing controlled movement of current.', 0, 0, 0, 1790968059127) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_82f07954aaad9ef8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Organic compound Cholesterol is ______?', '{"A":"Carbohydrate","B":"Amino acid","C":"Steroid","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cholesterol is a steroid because it has a four-ring structure characteristic of sterols.It plays a key role in cell membrane stability and hormone synthesis.', 0, 0, 0, 1790968059127) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_33e01ced53963ce2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which chemical is used for purification (purity) of water?', '{"A":"Chlorine","B":"Florine","C":"Iodine","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Chlorine is a strong oxidant that rapidly kills many harmful microorganisms. Chlorine is a toxic gas.', 0, 0, 0, 1790968059127) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_584aa5715cfd2a23', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'All metals are solid except _______?', '{"A":"Silver","B":"Mercury","C":"Titanium","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mercury is the only metal that is liquid at room temperature, unlike the others (Copper, Brass, Aluminum, Silver, Titanium, Platinum) which are solid.It remains in liquid form due to its low melting point of about -38.83°C.', 0, 0, 0, 1790968059163) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_279aee1f464911cd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The most abundant element in earth crust is _____?', '{"A":"Carbon Dioxide","B":"Ozone","C":"Oxygen","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Most abundant element in Earth crust is Oxygen.Oxygen in the crust is (46.1%).The chemical formula of oxygen (dioxygen) is O2.****************List of 10 Most Abundant Elements in the Earth''s Crust Sr# Element Abundance percent by weight 1 Oxygen 46.10% 2 Silicon 28.20% 3 Aluminum 8.23% 4 Iron 5.63% 5 Calcium 4.15% 6 Sodium 2.36% 7 Magnesium 2.33% 8 Potassium 2.09% 9 Titanium 0.57% 10 Hydrogen 0.14%', 0, 0, 0, 1790968059163) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_34a1c5bace726f7b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The ability of a substance to go through a chemical change is called ______?', '{"A":"Physical property","B":"Reactivity","C":"Evaporation","D":"Condensation"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Reactivity is a chemical property that describes how easily a substance undergoes chemical change.It indicates how a substance reacts with others to form new substances.', 0, 0, 0, 1790968059163) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_85c620c8a13730a6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'If the pressure of a given mass of gas is doubled at constant temperature, what will happen to its volume?', '{"A":"Become halved","B":"Become doubled","C":"Remain unchanged","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation According to Boyle''s Law, at constant temperature, the volume of a gas is inversely proportional to its pressure.So, doubling the pressure will halve the volume.', 0, 0, 0, 1790968059163) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_aaf4e8d6ae4c8a26', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Oxygen has 6 electrons in its valence shell so its valency is ______?', '{"A":"2","B":"8","C":"18","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Valency is the number of electrons an atom gains, loses, or shares to complete its octet.Oxygen has 6 valence electrons and needs 2 more to complete its octet, so its valency is 2.', 0, 0, 0, 1790968059163) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_984b0163bc743988', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Galvanized iron sheets have on them a coating of ______?', '{"A":"Lead","B":"Chromium","C":"Tin","D":"Zinc"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Galvanized iron sheets have a coating of zinc. Galvanization is a process where a layer of zinc is applied to iron or steel to protect it from rusting, making "galvanized iron" essentially iron coated with zinc', 0, 0, 0, 1790968059163) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e53185c396367d53', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'What is the percentage of the noble gas in the atmosphere?', '{"A":"About 0.9%","B":"About 0.3%","C":"About 1.5%","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Noble gases (mainly argon) make up about 0.9% of Earth''s atmosphere. Argon is the most abundant, followed by neon, helium, krypton, and xenon.', 0, 0, 0, 1790968059163) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2896863c8f24dff8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Damage to buildings and stone statues caused by acid rain is commonly called _____?', '{"A":"Deforestation","B":"Global warming","C":"Stone cancer","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Acid rain reacts with minerals in stone structures, leading to their decay, which is termed "stone cancer."It mainly affects limestone and marble, causing surface erosion and weakening of buildings and statues.', 0, 0, 0, 1790968059163) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_70c0f94dcc0d085c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which gas is used to destroy the harmful bacteria in the water?', '{"A":"Chlorine","B":"Oxygen","C":"Iodine","D":"Fluorine"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Chlorine is the gas used to disinfect and purify water.It is passed through water to kill bacteria.', 0, 0, 0, 1790968059198) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c228401dcd3d6206', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'A chemical process that gives out heat is called _____?', '{"A":"Synthesis","B":"Conduction","C":"Polymerization","D":"Combustion"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Combustion is a chemical reaction where a substance burns in oxygen, releasing heat and light. It is an exothermic process, meaning it gives out heat.', 0, 0, 0, 1790968059198) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5d3e56201b83645e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The number of electrons of a neutral atom is automatically known if one knows the ______?', '{"A":"Atomic number","B":"Atomic weight","C":"Number of orbitals","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In a neutral atom, the number of electrons is equal to the atomic number.The atomic number represents the number of protons, which equals the number of electrons in a neutral atom.', 0, 0, 0, 1790968059198) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4fd6a79cb2a0696f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Carbon dating is used for _____?', '{"A":"Collecting carbon","B":"Finding the age","C":"Hardening the diamond","D":"Melting steel"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Carbon dating is used to estimate the age of fossils.Those that are less than 60,000 years old.It is composed of organic materials like wood or leather.', 0, 0, 0, 1790968059198) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4625d91d619f778d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which gas can be accumulated in poorly ventilated buildings?', '{"A":"Xenon","B":"Nitrogen","C":"Hydrogen","D":"Radon"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Radon is a gas that can be accumulated in poorly ventilated buildings.Radon is released from Radium.It originates from the natural decay of uranium in soil, rock, and water It can enter buildings through cracks and other openings in the foundation. Prolonged exposure to high levels of radon gas can increase the risk of lung cancer', 0, 0, 0, 1790968059198) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f73e6b79b3892426', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which one is called a greenhouse gas?', '{"A":"Water Vapors","B":"Argon","C":"Nitrogen","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Greenhouse gases include carbon dioxide (CO₂), methane (CH₄), nitrous oxide (N₂O), and water vapor (H₂O).These gases trap heat in the Earth''s atmosphere, leading to the greenhouse effect.The trapping of heat contributes to global warming and climate change.These gases allow sunlight to enter but prevent some of the heat from escaping into space.', 0, 0, 0, 1790968059198) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e9d232d9f44a8c53', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Oxygen was discovered by ____?', '{"A":"Boyle","B":"Scheele","C":"Priestley","D":"Cavandish"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Joseph Priestly discovered oxygen on August 1, 1774.The most abundant element in the Earth''s crust is oxygen.It making up 46.6% of Earth''s mass.', 0, 0, 0, 1790968059198) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6423e45f4fb43a77', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Compressed Natural Gas (CNG) has the same chemical composition as that of _____?', '{"A":"LPG","B":"Tear gas","C":"Hydrogen","D":"Sui Gas"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation CNG and Sui Gas have the same composition, primarily methane (CH₄).Both are used as fuel for heating and vehicles.It is used as a cleaner alternative to petrol and diesel in vehicles.', 0, 0, 0, 1790968059198) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f88ee9d0813a49b6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which Gas is used in the preparation of Soft drinks?', '{"A":"Nitrogen","B":"Carbon dioxide","C":"Oxygen","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Carbon dioxide is a colorless and non-flammable gas at normal temperature and pressure.The bubbles in fizzy drinks are caused by carbon dioxide (CO2).Soft drink manufacturers add fizz by dissolving carbon dioxide into the water at high pressures.***ND16-12-2022******ND30-12-2022', 0, 0, 0, 1790968059232) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_39975f4724543b75', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which of the following is a chemical reaction?', '{"A":"Melting of iron","B":"Tempering of iron","C":"Rusting of iron","D":"Bending of iron"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Rusting of iron is a chemical reaction where iron reacts with oxygen and water to form iron oxide (rust).Unlike physical changes like melting or bending, rusting involves a chemical transformation.', 0, 0, 0, 1790968059232) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3f000ad024d60727', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The element required for solar energy conversion is ____?', '{"A":"Silicon","B":"Germanium","C":"Uranium","D":"Selenium"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The key element required for solar energy conversion in most solar cells is siliconIt is the most common semiconductor material: Silicon is used in about 95% of solar cells sold today. It is a naturally occurring element: Silicon is the second most abundant element on Earth, after oxygen.', 0, 0, 0, 1790968059232) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e6cd37e53950245d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'For galvanizing of iron which of the following metals is used?', '{"A":"Zinc","B":"Lead","C":"Copper","D":"Aluminum"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Iron is galvanized by coating it with zinc.It prevents rusting and corrosion by acting as a protective barrier.', 0, 0, 0, 1790968059232) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e7ead9608ad5b6b5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'In the manufacture of banaspati ghee, the gas used is _____?', '{"A":"Helium","B":"Hydrogen","C":"Oxygen","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hydrogenation is the process by which hydrogen is used in the preparation of banaspati ghee from vegetable oil ***ND16-12-2022', 0, 0, 0, 1790968059232) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_28ded0107b99b4db', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The pH of milk is _____?', '{"A":"6","B":"7","C":"6.7","D":"7.5"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fresh milk has a pH value of 6.7.Bacteria from the family of Lactobacillaceae are lactic acid bacteria (LAB) responsible for the breakdown of the lactose in milk to form lactic acid.', 0, 0, 0, 1790968059232) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ff2c10a42c91c913', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which gas is 80 times potent than CO2 in Green House Effect?', '{"A":"Methane","B":"Oxygen","C":"Nitrogen","D":"Hydrogen"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation IMPORTANT QUESTIONS AND INFORMATION RELATED TO "GREEN HOUSE EFFECT"Green House Effect means the Trapping of Solar energy due to atmospheric carbon dioxideThe greenhouse effect is a good thing.It warms the planet to its comfortable average of 57 degrees Fahrenheit (13.9 degrees Celsius)The greenhouse effect keeps life on earth, well, livable.The Green House Effect is caused by an excess of Carbon dioxideThe greenhouse effect causes Global warmingMethane gas is 80 times potent than CO2 in Green House EffectND2-03-2023RY 23-12-2022', 0, 0, 0, 1790968059232) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2a18fb037b3e7c0c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The blotting paper helps observe liquid by ____?', '{"A":"Surface Action","B":"Capillary Action","C":"Viscosity","D":"Boldness"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Capillary action is the process of a liquid flowing in a narrow space without the assistance of, or even in opposition to, any external forces like gravity.', 0, 0, 0, 1790968059232) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_971e8271b2094ed1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which of following gas is combustible?', '{"A":"Hydrogen","B":"Nitrogen","C":"Oxygen","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Straw, camphor, alcohol, petrol, diesel etc. catch fire easily to release heat energy and light energy. So, these are examples of combustible substances.Examples of combustible gases are Hydrogen, Methane, Propane, Iso-butane. Mixture of a certain amount of combustible gas and Oxygen will explode in the presence of an ignition source.', 0, 0, 0, 1790968059267) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f547d38e16761e2f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which among the following happens in oxidation reactions?', '{"A":"Electrons are lost","B":"Electron is gained","C":"Protons are gained","D":"Protons are lost"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Electrons are lost in an oxidation reaction. Oxidation simply means a gain of oxygen and an oxidizing agent is a substance that oxidizes something. The reduction is the gain of electrons', 0, 0, 0, 1790968059267) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_de4873bbfae1e0cc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which is the process in which water directly condense into a solid form?', '{"A":"Sublimation","B":"Condensation","C":"Evaporation","D":"Predication"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sublimation is the process in which water vapour directly condenses into solid form.Condensation is the process of transformation of water vapour into water.Evaporation is process by which water or a liquid is transformed from liquid to gaseous state.Precipitation is the condensation of water vapor in air in form of water droplets or ice.', 0, 0, 0, 1790968059267) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9328c54d686b81ec', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Oxidation number of ''Mn'' in KMnO₄ is _______?', '{"A":"-7","B":"+7","C":"0","D":"+1"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The given compound is an ionic compoundIt is made up of:one potassiumone manganese,four oxygen atoms.Oxidation numbers of potassium (K) and oxygen (O) are +1 and -2 respectively.Let us assume that the oxidation number of Mn is x.Since ionic compounds are neutral, the net charge on them is zero.(Oxidation number of K) + (Oxidation number of Mn) + (4 × The oxidation number of O) = 0(1)×(K) + (1)×(Mn) + 4×(O) = 0(1)×(+1) + (1)×(x) + 4×(-2) = 0x = +7Hence, the oxidation number of Mn in KMnO4 is +7.', 0, 0, 0, 1790968059267) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_52c1d0bc4c7995f6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which gas present in the Earth’s atmosphere can absorb solar ultraviolet radiation?', '{"A":"Oxygen","B":"Ozone","C":"Carbon Dioxide","D":"Nitrogen"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The ozone layer protects living things from too much ultraviolet from entering the atomsphere.Oxygen layer in the atmosphereOzone protects us from the harmful ultraviolet radiation of the sun.Ozone formula: O3The ozone layer lies approximately 15-40 kilometers (10-25 miles) above the Earth''s surface, in the stratosphere.The ozone layer is depleting: Air pollution', 0, 0, 0, 1790968059267) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ed1667d9d9db0b6e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The compound used in anti-malarial drug is?', '{"A":"Neoprene","B":"Aspirin","C":"Chloroquin","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Chloroquine is a medication used to prevent and treat malaria.It is a disease caused by parasitic protozoans.It is commonly used as an anti-malarial drug.It has been widely used for decades.Chloroquine was discovered in 1934.', 0, 0, 0, 1790968059267) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_91688271630eb0d4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which of the following is responsible for largest amount of oxygen on earth?', '{"A":"Algae","B":"Peat bogs","C":"Trees","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Algae, especially phytoplankton in oceans, are responsible for producing the largest amount of oxygen on Earth.It contributing to over 50% of the planet''s oxygen supply.', 0, 0, 0, 1790968059267) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_52a9490b102bdf5e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The condition of fully charge battery is lead acid battery can be ascertained by ______?', '{"A":"Voltage","B":"Gassing","C":"Specific gravity of electrolyte","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The condition of a fully charged lead-acid battery can be checked by:Voltage: 2.1-2.2 volts per cell.Gassing: Battery emits gas when fully charged.Specific Gravity: 1.260-1.300 in the electrolyte.', 0, 0, 0, 1790968059267) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e2b5912e2f106503', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which gas helps in cooling in refrigerators?', '{"A":"Nitrogen","B":"Carbon dioxide","C":"Methane","D":"Tetrafluoroethane"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation R-600a (Isobutane): Most common in modern, energy-efficient household refrigerators.R-134a (Tetrafluoroethane): Widely used in previous decades and still common in light refrigeration.R-290 (Propane): Used in some eco-friendly cooling units.Ammonia (NH3): Used mainly in industrial or large-scale commercial refrigerationLast updated question by NA on 28 April 2026', 0, 0, 0, 1790968059308) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a8a2f5df825c3b52', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which of the following is made up of Calcium?', '{"A":"Plasma","B":"Bile","C":"Blood","D":"Teeth","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Teeth is made up of Calcium.Calcium hydroxide is an odorless white powder.It''s used in industrial settings, such as:sewage treatment,paper production,construction,and food processing', 0, 0, 0, 1790968059308) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_18e8398b60cb90e1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The most abundant natural Iron oxides are:', '{"A":"Magnetite and Pyrite","B":"Magnetite and Bauxite","C":"Hematite and Pyrite","D":"Hematite and Magnetite","E":"Hematite and Bauxite"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Iron oxide is a chemical compound of oxygen and iron and is most commonly found in the earth''s crust in the form of hematite (Fe2O3). It also exists in the form of magnetite (Fe3O4).', 0, 0, 0, 1790968059308) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3d87d730620496b1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Deficiency of iron in Human body cause:', '{"A":"Giotre","B":"Scurvy","C":"Anemia","D":"Rickets"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Deficiency of iron in human body causes anemia.Anemia: خون کی کمی کا مرضAGM 28.02.28', 0, 0, 0, 1790968059308) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3fac667ab5348d9f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Symbol of Potassium?', '{"A":"P","B":"K","C":"T","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Potassium is the chemical element Symbol K Atomic number 19Electron configuration: 4s1Electrons per shell: 2, 8, 8, 1', 0, 0, 0, 1790968059308) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cd4e62daf3cf031f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'In the covalent bonding, electron of two atoms', '{"A":"Share with each other","B":"Transfer from one atom to another","C":"Attract the ions and delocalized electrons","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A covalent bond is the force of attraction that holds together two atoms that share a pair of valence electrons. The shared electrons are attracted to the nuclei of both atoms. This forms a molecule consisting of two or more atoms.', 0, 0, 0, 1790968059308) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_65ab32adaef93237', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'During the combustion of gasoline in a vehicle engine, the energy used is', '{"A":"Chemical","B":"Mechanical","C":"Electrical","D":"All of these","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Combustion is when fuel reacts with oxygen to produce heat. Chemical reactions that produce heat we call exothermic reactions. Most vehicles use an engine to convert heat energy into mechanical energy. Mechanical energy gets transferred to the vehicle''s moving parts, like wheels or propellers.', 0, 0, 0, 1790968059308) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cca995746d843f59', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Linkage present between two heavy chains of antibody molecule?', '{"A":"Double H-bond","B":"Double disulphide","C":"Double covalent","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In human IgG1 the two heavy chains are linked by two proximal disulfide bridges in a portion of the molecule****', 0, 0, 0, 1790968059308) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1eb9a5f180a276e9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Atom is made up of how many basic components?', '{"A":"2","B":"3","C":"4","D":"5"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Three basic parts of an atom1. Electrons, 2. Protons, 3. Neutrons.ND5-07-2023', 0, 0, 0, 1790968059359) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b58e48868e010247', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Diamond is a very expensive ornament. It is composed of a single element :', '{"A":"Carbon","B":"Gold","C":"Silver","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Diamond is composed of the single element carbon, it is the arrangement of the C atoms in the lattice that give a diamond amazing properties.MUG 11-12-2022ND5-07-2023', 0, 0, 0, 1790968059359) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_94e574c741f379cb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'which of the following represent a chemical change', '{"A":"Sublimation of Iodine","B":"Heating a platinum wire in a bunsen flame","C":"Heating of Mercuric oxide powder","D":"Evaporation of Alcohol"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Answer: C: Heating of Mercuric oxide powder: The heating of Mercuric oxide powder is a permanent change. We cannot get powder by revere reaction so it is a chemical changeSublimation of Iodine: It is a physical changeHeating a platinum wire in a Bunsen flame: Platinum is a noble gas that cannot change its physical appearance after heating. So it is not a chemical change Evaporation of Alcohol: It is a physical change. The liquid is changed into gas', 0, 0, 0, 1790968059359) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_529b47d844217992', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The acid reacts with metal and releases____?', '{"A":"Water","B":"Electron","C":"Proton","D":"Hydrogen","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Acids react with metals to release hydrogen gas. When an acid reacts with metal, a salt and hydrogen gas are produced', 0, 0, 0, 1790968059359) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8817100ef1bab14b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'potassium permanganate is used for purifying water because?', '{"A":"It is a sterlizing agent","B":"It dissolves the impurities of water","C":"It is a reducing agent","D":"It is an oxidizing agent"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Potassium permanganate is an inorganic chemical compound and it is a strong oxidizing agent', 0, 0, 0, 1790968059359) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e45b5582b8e75221', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'A metal that is liquid at room temperature?', '{"A":"Mercury","B":"iron","C":"metal","D":"silver"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mercury is the only stable elemental metal that is liquid at standard room temperatureSymbol and Number: Mercury has the chemical symbol Hg and atomic number 80.Freezing Point: It melts at -38.8°C (-37.9°F)', 0, 0, 0, 1790968059359) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bd025076677c7c3b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Solid which undergoes sublimation is?', '{"A":"Iodine","B":"Argon","C":"Water","D":"Sodium Chloride","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sublimation is a process in which a solid substance directly converts into its gaseous form without passing through the liquid phase. Few of the substances which can undergo sublimation are iodine, ammonium chloride, camphor, naphthalene and carbon dioxide.', 0, 0, 0, 1790968059359) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6a69f1a8b138fa4f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The salinity of sea water is determined by the amount of common salt (Sodium Chloride) in __________ of sea water.', '{"A":"1 Kg","B":"1gram","C":"10 grams","D":"none of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Salinity in seawater is defined as the total weight of salt dissolved in 1 kilogram of seawater. Salinity is expressed in g / kg and is often expressed in ppt (parts per 1000) or ‰ (permit).', 0, 0, 0, 1790968059359) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_66d288700883db7e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Hydrogen has ____ Neutrons ?', '{"A":"1","B":"2","C":"zero","D":"8"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation It is a highly unstable isotope of hydrogen.Hydrogen has no neutron. It contain only one proton and one electron. But the deuterium contain one neutron and tritium contain two neurons, these are the isotopes of hydrogen. ******RY 15-01-2023', 0, 0, 0, 1790968059391) ON CONFLICT(id) DO NOTHING;
