INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3a3f11b50b6fbf80', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which of following gas is combustion', '{"A":"Hydrogen","B":"Oxygen","C":"nitrogen","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Oxygen is necessary for combustion.', 0, 0, 0, 1790968059391) ON CONFLICT(id) DO NOTHING;
