INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f20ed5aa2f50707b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'The symbol of Hydrogen is', '{"A":"H","B":"Hf","C":"HH","D":"Hs","E":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hydrogen is the chemical element with the symbol H and atomic number 1. With a standard atomic weight of 1.008, hydrogen is the lightest element in the periodic table.', 0, 0, 0, 1790968059490) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7460ac52453fa1c1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which is the rarest Isotope of Hydrogen:', '{"A":"Protium","B":"Deuterium","C":"Tritium","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tritium is a beta-emitting radioactive isotope of hydrogen. Its nucleus consists of one proton and two neutrons, making it three times as heavy as a hydrogen nucleus (with its one proton) and one-and-a-half times as heavy as deuterium (which contains one proton and only one neutron).', 0, 0, 0, 1790968059518) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_75fdb27e3b05e144', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Which of following element is essential for animals but not in plants?', '{"A":"Potassium","B":"Phosphorus","C":"Calcium","D":"Iodine","E":"None"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Iodine and sodium are essential for animals and are not required by most of the plants however, iodine is found in certain marine algae.', 0, 0, 0, 1790968059518) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dead6ed6d9e765fe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', '___ number of molecules of co2 are produced by an acetyl group of acetyl _ Co _ A in acid', '{"A":"2","B":"4","C":"5","D":"3citric acid"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In carbon dioxide molecule, a carbon atom is joined by four covalent bonds to two oxygen atoms, which have two covalent bonds each.', 0, 0, 0, 1790968059518) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c5c1b119872a88d7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', '________ of the codon is the redundancy of the genetic code, exhibited as the multiplicity of three base pair codon combinations that specified an amino acid', '{"A":"Universality","B":"Specificity","C":"Degeneracy","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Specificity of the codon is the redundancy of the genetic code, exhibited as the multiplicity of three base pair codon combinations that specified an amino acid', 0, 0, 0, 1790968059518) ON CONFLICT(id) DO NOTHING;
INSERT INTO subject (id, user_id, name, parent_id, total_mcqs, created_at) VALUES ('top_eds_biology', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'Biology & Human Body', 'top_everyday_science', 227, 1790968059544) ON CONFLICT(id) DO UPDATE SET total_mcqs = 227;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b4a7c6943a95caeb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Serve deficiency of Vitamin B complex results in?', '{"A":"Night Blindness","B":"Rickets","C":"Beriberi","D":"Scurvy"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Vitamin B Complex deficiency, specifically Vitamin B1 (Thiamine) deficiency, can cause:Beriberi, a disease characterized by:Fatigue and weaknessNerve damage and painHeart problemsSwelling of legs and feetAdditional information:Vitamin B3 (Niacin) deficiency → PellagraVitamin B12 deficiency → Megaloblastic anemia and neurological problemsLast verified on 01-10-2026', 0, 0, 0, 1790968059574) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b57a689d5e14d772', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which part of the cell contains genetic material?', '{"A":"Ribosome","B":"Cytoplasm","C":"Nucleus","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The nucleus contains the cell’s genetic material (DNA).DNA carries hereditary information.The nucleus controls many cell activities.In prokaryotic cells (like bacteria), DNA is not enclosed in a nucleus; it is found in the nucleoid region.Genetic material = DNA.', 0, 0, 0, 1790968059574) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0bad602895ddd449', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'How many bones in human body (skeleton)?', '{"A":"200","B":"206","C":"270","D":"300"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Total bones in adult human body = 206At birth = 270–300 bones (fuse to become 206)The total bones of our body can be divided into:Axial skeleton = 80 bonesAppendicular skeleton = 126 bonesAdditional information:Newborn baby has 300 bonesLongest bone = FemurShortest bone = StapesBones in human skull = 22Last verified on 30-03-2026', 0, 0, 0, 1790968059574) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_389013c1b9109976', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'A universal donor has the blood group?', '{"A":"B","B":"O-","C":"AB","D":"A"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation O⁻ (O Negative) is the universal donor blood group.It can be transfused to A, B, AB, and O blood groups.O⁻ blood lacks A, B, and Rh (D) antigens.Additional information:Universal Recipient: AB⁺ (AB Positive)ABO Blood Groups: A, B, AB, ORh Types: Positive (+) and Negative (−)Total Common Blood Groups: 8 (A⁺, A⁻, B⁺, B⁻, AB⁺, AB⁻, O⁺, O⁻)Last verified on 14-07-2026', 0, 0, 0, 1790968059574) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c99c4f1d7c664ca9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Deficiency of Vitamin C Causes?', '{"A":"Scurvy","B":"Cold","C":"Cancer","D":"Rickets"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Vitamin C deficiency causes scurvy.It can cause bleeding/loose gums, easy bruising, and poor wound healing.Other signs include rough skin, corkscrew hair, and red spots around hair follicles.Rickets is mainly caused by Vitamin D deficiency.Last verified on 13-09-2026', 0, 0, 0, 1790968059574) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_30ffeae9807f8236', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Insulin is produced and secreted by which organ of the body?', '{"A":"Liver","B":"Pancreas","C":"Kidney","D":"Brain"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Insulin is produced by the pancreas.The pancreas contains clusters of cells called the Islets of Langerhans.Beta (β) cells within these islets produce and secrete insulin.Insulin helps regulate blood glucose (sugar) levels by promoting glucose uptake into cells.Last verified on 07-09-2026', 0, 0, 0, 1790968059574) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0fbd1200e0a318ac', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Why do red blood cells lack a nucleus?', '{"A":"To maximize space for hemoglobin","B":"To reduce oxygen consumption","C":"To increase lifespan","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Red blood cells lack a nucleus to maximize space for hemoglobin, which carries oxygen.More hemoglobin means more oxygen transport.This makes RBCs highly efficient for gas exchange.Lack of nucleus also gives them a flexible shape.This helps them pass through narrow blood capillaries.Last verified on 14-06-2026', 0, 0, 0, 1790968059574) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d6252d36ad6eaab2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which one is not part of the brain? Pons, Medulla Oblongata, Hind Brain, Spinal Cord', '{"A":"Pons","B":"Medulla Oblongata","C":"Hind Brain","D":"Spinal Cord"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The spinal cord is not part of the brain; it is part of the central nervous system (CNS).The brain is broadly divided into forebrain, midbrain, and hindbrain.Pons and medulla oblongata are parts of the brainstem.The hindbrain includes the pons, medulla oblongata, and cerebellum.Last verified on 06-09-2026', 0, 0, 0, 1790968059574) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8244e1bae213e11d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'What does make the blood look red?', '{"A":"Red corpuscles","B":"Hemoglobin","C":"Plasma","D":"Certain secretions"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Blood is red because of a protein called hemoglobin inside our red blood cells, Which contains iron that changes color when it binds to oxygenLast updated by NS on 5-09-2026', 0, 0, 0, 1790968059603) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e909fe20def72e83', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Blood group is identified by _______?', '{"A":"Antibody","B":"Anti Toxin","C":"Antigens","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Blood groups are identified by specific antigens present on the surface of red blood cells.These antigens determine compatibility for blood transfusions.They are key to classifying blood types like A, B, AB, and O.Last verified on 04-09-2026', 0, 0, 0, 1790968059603) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_885552271366b204', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which acid is produced in the gastric juice of the stomach to digest food?', '{"A":"Hydrochloric Acid","B":"Nitric Acid","C":"Sulphuric Acid","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The stomach produces Hydrochloric Acid (HCl) as part of gastric juice.HCl creates a highly acidic environment with a pH of about 1.5–3.5.It activates pepsinogen into pepsin.Pepsin helps break down proteins into smaller peptides.Last verified on 03-09-2026', 0, 0, 0, 1790968059603) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2f195d1a8e89a61b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which is largest human cell in the body?', '{"A":"Ovum","B":"Stem","C":"Nerve","D":"Fat"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The ovum (egg cell) is generally considered the largest cell in the human body.It is the female reproductive cell and can be seen with the naked eye as a tiny dot.The ovum is approximately 0.1 mm (100 micrometers) in diameter.In contrast, the sperm cell is one of the smallest human cells.Last verified on 03-09-2026', 0, 0, 0, 1790968059603) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a2e5ecd42a6fdbb0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which is the largest part of the human brain?', '{"A":"Encephalus","B":"Cerebellum","C":"Middle brain","D":"Cerebrum"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Largest part: Cerebrum.Hemispheres: Two — right and left.Main functions: Thinking, memory, intelligence, speech, and voluntary movement.Cerebellum: Mainly controls balance and coordination.Brainstem: Connects the brain with the spinal cord and controls vital functions.Last verified on 03-09-2026', 0, 0, 0, 1790968059603) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1baa0cb6901d1182', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The largest Artery in human body is called?', '{"A":"Pulmonary artery","B":"Aorta artery","C":"Carotid artery","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Aorta is the largest artery in the human body.It carries oxygen-rich blood from the left ventricle of the heart to the rest of the body.It is the main artery of the systemic circulatory system.The aorta branches into smaller arteries to supply blood to all body organs except the lungs.Additional information:Arterioles are the smallest branches of arteries.They carry oxygenated blood from arteries to the capillaries.Arterioles regulate blood flow and blood pressure by constricting or dilating.Last verified on 21-07-2026', 0, 0, 0, 1790968059603) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6b207cda500e2ac9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which is the shortest/smallest bone in human body?', '{"A":"Stapes","B":"Tibia","C":"Femur","D":"Humerus"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Smallest bone: Stapes.Location: Middle ear.Three ear bones: Malleus, Incus, Stapes.Longest bone: Femur (thigh bone).Adult human skeleton: Usually 206 bones.Newborn: About 270 bones at birth; many later fuse together.Human skull: 22 bones (8 cranial + 14 facial)Last verified on 03-09-2026', 0, 0, 0, 1790968059603) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_69bc4192dd3d5bd2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which is the longest and the strongest bone in human body?', '{"A":"Femur","B":"Stapes","C":"Tibia","D":"Femur"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The largest bone in the human body is the femur (the thighbone)It is located in the upper leg, between the hip and the knee.It supports the weight of the body and helps you walk, run, and standIt is about 48 centimeters (18 inches) long.Additional information:The lowest part of the backbone is called the sacrum.The smallest bone is the stirrup (stapes).The strongest bone for its size is the lower jaw or mandible.Last updated by NA on 09-09-2026', 0, 0, 0, 1790968059603) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_50823a7deb1a8e77', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'What is the largest internal organ of human body?', '{"A":"Kidney","B":"Lungs","C":"Liver","D":"Brain"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The largest solid internal organ is the liver. It weighs approximately 3–3.5 pounds or 1.36–1.59 kilograms.It is about the size of a football.Additional information:Skin is the largest external organ of the human bodyLast verified on 03-09-2026', 0, 0, 0, 1790968059631) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b013e322b7099f08', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which organ purifies our blood?', '{"A":"Haert","B":"Kidney","C":"Lungs","D":"Tissue"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The kidneys purify the blood in the human body.They remove waste materials and extra water.Kidneys help maintain the body’s chemical balance.Each person has two kidneys.They produce urine as a waste product.Last verified on 07-06-2026', 0, 0, 0, 1790968059631) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1e6f7fd45ab3c21c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'What organ produces bile?', '{"A":"Gall bladder","B":"Kidneys","C":"Liver","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Liver produces bile, which helps in digestion of fats in the human body.Bile is a digestive fluid essential for fat breakdown.It is produced continuously by the liver.It is stored and concentrated in the gallbladder.It is released into the small intestine during digestion.Last verified on 08-06-2026', 0, 0, 0, 1790968059631) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0a9da351ad257895', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Organ of human body which is considered on the largest organ is ______?', '{"A":"Skin","B":"Digestive tract","C":"Liver","D":"Brain"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The skin is considered the largest organ of the human body.It covering an area of about 1.5-2 square meters (16-22 square feet).It weighing around 3-4 kilograms (7-9 pounds).Last verified on 01-09-2026', 0, 0, 0, 1790968059631) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cea4c8c73688e097', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Urine is produced in ____?', '{"A":"Kidney","B":"Pancreas","C":"Spleen","D":"Gallbladder"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Urine is produced in the kidneys by filtering the blood.The kidneys remove excess water, salts, and waste products from the blood.Urine is formed in tiny filtering units called nephrons.After formation, urine passes through the ureters to the urinary bladder.The kidneys help maintain the body''s fluid and electrolyte balance.Last verified on 04-08-2026', 0, 0, 0, 1790968059631) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_250c244ad24cadca', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Who discovered the circulation of blood?', '{"A":"Parker","B":"William Harvey","C":"Mendel","D":"Newton"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation William Harvey discovered the circulation of blood.He was the first physician to completely describe systemic blood circulation.Famous book: De Motu Cordis (On the Motion of the Heart and Blood) (1628)He is known as the Father of Circulation of Blood.Additional information:Birth: 1578Death: 1657Last verified on 23-06-2026', 0, 0, 0, 1790968059631) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_45175cec3a279d14', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which one of the following is herbivore? Cow, Deer, Lion, Both A and B', '{"A":"Cow","B":"Deer","C":"Lion","D":"Both A and B"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cow and Deer are herbivores because they feed on plants.Herbivores eat grass, leaves, fruits, and other plant materials.Additional information:Herbivores: Cow, Deer, Goat, Rabbit, ElephantCarnivores: Lion, Tiger, Leopard, Wolf, CheetahOmnivores: Human, Bear, Crow, Pig, HenLast verified on 27-07-2026', 0, 0, 0, 1790968059631) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5ccfa08e2aeba6e2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which contain two nuclei? Paramecium, Plasmodium, Monocytes, None of these', '{"A":"Paramecium","B":"Plasmodium","C":"Monocytes","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Paramecium contains two nuclei: a macronucleus and a micronucleus.The macronucleus controls daily metabolic and cellular activities.The micronucleus is responsible for reproduction and genetic exchange.Paramecium is a single-celled protozoan found in freshwater.It belongs to the phylum Ciliophora.Last verified on 27-07-2026', 0, 0, 0, 1790968059631) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a5cf2f569a494025', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The best source of vitamin C is _____? Butter, Potatoes, Orange, Meat', '{"A":"Meat","B":"Potatoes","C":"Oranges","D":"Butter"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Oranges are well-known for being rich in Vitamin C.It is essential for immune function, skin health, and other bodily processes.Additional information Vitamins are essential nutrients That your body requires in small amounts to function, grow, and develop properly. They are divided into two main groups: water-soluble (like Vitamin C and the B-vitamins) fat-soluble (like Vitamin A, D, E, and K)Last updated by NA on 16-07-2026', 0, 0, 0, 1790968059659) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c5bb5828991e74a3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Chemical compounds, protein in nature, made in the cells of living organisms are called?', '{"A":"Vitamins","B":"Hormones","C":"Enzymes","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Enzymes are protein-based chemical compounds produced in the cells of living organisms.They act as biological catalysts, speeding up chemical reactions.Enzymes are essential for digestion, metabolism, and energy production.Verified & Updated', 0, 0, 0, 1790968059659) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_39cceaafc0852ee2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Who discovered the Blood Group System?', '{"A":"William Murdock","B":"Karl Landsteiner","C":"Edward Jenner","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Karl Landsteiner discovered the ABO Blood Group System in 1900.He was an Austrian scientist and physician.His discovery made safe blood transfusions possible.He received the Nobel Prize in Physiology or Medicine in 1930 for his work.Last verified on 01-07-2026', 0, 0, 0, 1790968059659) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_227a580632c4f3aa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Solar plate consist of which type of cell?', '{"A":"Fuel cell","B":"Photo voltaic cell","C":"Both A and B","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Solar plates consist of photovoltaic (PV) cells.PV cells convert sunlight directly into electrical energy.These cells work on the photovoltaic effect. They are usually made of semiconductor materials like silicon.Additional information:Discovered photovoltaic effect: 1839 by Edmond BecquerelCommon types of solar cells:Monocrystalline silicon cellsPolycrystalline silicon cellsThin-film solar cellsLast verified on 23-06-2026', 0, 0, 0, 1790968059659) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d13c86c2d10194ca', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which part of human brain is involved in maintaining the posture and balance of the body?', '{"A":"Cerebrum","B":"Hypothalamus","C":"Cerebellum","D":"Medulla oblongata"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The cerebellum controls body posture, balance, and coordination.It helps muscles work smoothly during movement.It ensures the body stays balanced while standing or walking.It coordinates voluntary muscle actions.Damage to it causes loss of balance and shaky movements.Last verified on 21-06-2026', 0, 0, 0, 1790968059659) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_af031bb367a1c8a6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which organism is known as the powerhouse of the cell?', '{"A":"Organ powerhouse","B":"Cell membrane","C":"Cytoplasm","D":"Mitochondria"}', 'D', NULL, 0, 0, 0, 1790968059659) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_80d33bfc32f8975f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which of the following blood cells play an important role in blood clotting?', '{"A":"Thrombocytes (Platelets)","B":"Leukocytes (White Blood Cells)","C":"Erythrocytes (Red Blood Cells)","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Thrombocytes (Platelets) help in blood clotting.They stop bleeding by forming a clot at the injury site.They stick together when a blood vessel is damaged.This prevents excess blood loss.They are essential for wound healing.Last verified on 07-06-2026', 0, 0, 0, 1790968059659) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_212b82520b6fce9e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which part of a cell is responsible for protein synthesis?', '{"A":"Nucleus","B":"Ribosomes","C":"Mitochondria","D":"Golgi apparatus"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ribosomes are the sites of protein synthesis in the cell.They read genetic instructions (mRNA) and assemble amino acids into proteins.They can be found free in the cytoplasm or attached to rough ER.They are made of RNA and proteins.They are present in both prokaryotic and eukaryotic cells.Last verified on 06-05-2026', 0, 0, 0, 1790968059659) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2c4c21e938e8b2c9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The sub atomic particle, which is positively charged particle and and resides in the nucleus?', '{"A":"Neutron","B":"Electron","C":"Proton","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The charges of Proton, Electron, Neutron respectively are:Proton: Positive charge (+1)Electron: Negative charge (-1)Neutron: Neutral charge (0)Last verified on 24-05-2026', 0, 0, 0, 1790968059689) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ddda33cde9822545', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which radiation consists of high-speed electrons emitted from the nucleus?', '{"A":"Gamma rays","B":"Beta rays","C":"Alpha rays","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Beta radiation consists of high-speed electrons emitted from the nucleus.These are produced during beta decay of unstable atoms.They are more penetrating than alpha but less than gamma radiation.Beta radiation can be stopped by thin metal sheets (like aluminum).Last verified on 06-05-2026', 0, 0, 0, 1790968059689) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c31863570c5d13d2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Deficiency of Vitamin D results in _____?', '{"A":"Rickets","B":"Scurvy","C":"Night blindness","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Vitamin D is essential for healthy bones.Its deficiency leads to Rickets in children and Osteomalacia in adults.Sunlight is the best natural source of Vitamin D.Additional information:Deficiency effects:Bone painWeak bonesSkeletal deformitiesOther Vitamin Deficiencies:Vitamin A: Night blindnessVitamin C: ScurvyVitamin B7 (Biotin): Hair fallLast verified on 17-01-2026', 0, 0, 0, 1790968059689) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c569e76d21ba5160', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which vitamin helps in the clotting of blood?', '{"A":"Vitamin A","B":"Vitamin B","C":"Vitamin K","D":"Vitamin D"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Vitamin K helps to make various proteins that are needed for blood clotting and the building of bones.Prothrombin is a vitamin K-dependent protein directly involved with blood clotting.Additional information:Vitamin C may protect the body against the effects of pollution.It may also prevent blood clots and reduce bruising.Last verified on 31-03-2026', 0, 0, 0, 1790968059689) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9b52f891c886e0ea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which type of vitamin strengthens bones and teeth and prevents a disease called Rickets; which causes bones to become soft and weak?', '{"A":"Vitamin C","B":"Vitamin D","C":"Vitamin B","D":"Vitamin A"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Vitamin D is essential for strong bones and teeth.It helps the body absorb calcium and phosphorus.Its deficiency causes Rickets in children.Vitamin D = “Sunshine vitamin”Helps in bone mineralizationWorks with calcium to build strong skeletonLast verified on 07-05-2026', 0, 0, 0, 1790968059689) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_66fc731931ba7ac2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The most important part of the cell that controls all activities of the cell is called _____?', '{"A":"Vacuole","B":"Mitochondria","C":"Golgi bodies","D":"Nucleus"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The nucleus is the control center of the cell.It regulates all vital activities like growth, reproduction, and metabolism.It contains genetic material (DNA).Ribosomes make proteins, and cytoplasm supports cell structure.Last verified on 04-05-2026', 0, 0, 0, 1790968059689) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fda160e4079efc6d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Night blindness is caused due to the deficiency of vitamin ______?', '{"A":"B","B":"C","C":"A","D":"D"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Vitamin A deficiency → Night blindness (Nyctalopia)Vitamin A is important for vision and immune function.Additional information:Vitamin K is essential for blood clotting.Vitamin D helps in calcium absorption and bone mineralization.Vitamin B1 supports nerve function and energy metabolism.Last verified on 01-02-2026', 0, 0, 0, 1790968059689) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8637459b985e7853', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The deficiency of Vitamin A causes?', '{"A":"Scurvy","B":"Night Blindness","C":"Rickets","D":"Beriberi"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Vitamin A is essential for vision, skin health, and immune function. Its deficiency can lead to night blindness (poor ight vision) and other health problems.Additional information:Dry skin and eyesImpaired immune functionPoor wound healingIncreased risk of respiratory and urinary tract infectionsLast verified on 17-01-2026', 0, 0, 0, 1790968059689) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_94da4693f959f25d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The longest/largest cell in human body is?', '{"A":"Kidney cell","B":"Liver cell","C":"Muscle cell","D":"Nerve cell"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The longest cell in the human body is the nerve cell (neuron).Some neurons can extend up to 1 meter in length.They transmit impulses throughout the body.Additional information:The smallest cell in the human body is the sperm cell (spermatozoon).It is measures approximately 4–5 micrometers (µm) in length.It is mainly consisting of a nucleus and a tail.Last verified on 23-04-2026', 0, 0, 0, 1790968059717) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3db3b5104c6f47d3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'What is the structural and functional unit of kidney?', '{"A":"Neuron","B":"Nephron","C":"Follicles","D":"Loop of Henle"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The kidney is an important organ responsible for filtering blood and forming urine.Its structural and functional unit is the nephron.Each kidney contains millions of nephrons.They perform filtration, reabsorption, and secretion.Last verified on 23-04-2026', 0, 0, 0, 1790968059717) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f8b4509e203dd014', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'What is the process of splitting the nucleus of an atom into smaller units?', '{"A":"Fusion","B":"Dillusion","C":"Fission","D":"Diffusion"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fission is the process of splitting an atomic nucleus into smaller nuclei, releasing a large amount of energy.It is used in nuclear power plants and atomic bombs.Last verified on 12-04-2026', 0, 0, 0, 1790968059717) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6a0feb746eba5ae5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The non-protein part of a conjugate enzyme, if loosely attached, is called?', '{"A":"Co-enzyme","B":"Co-factor","C":"Holoenzyme","D":"Prosthetic Group"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Enzymes sometimes need a non-protein component to function properly.This non-protein part is called a cofactor.If it is loosely attached, it can easily separate from the enzyme.Cofactors help enzymes carry out biochemical reactions.They may be inorganic ions or organic molecules.Last verified on 10-04-2026', 0, 0, 0, 1790968059717) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_95bd3d88353e7998', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Cell most commonly attacked by HIV ______?', '{"A":"B cell","B":"Helper T cell","C":"Cytotoxic T cell","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The cell most commonly attacked and invaded by HIV (Human Immunodeficiency Virus) is the CD4+ T cellAlso known as CD4 T lymphocyte or helper T cell. Weakening the immune system.The destruction of these cells leads to AIDS making the body vulnerable to infections.', 0, 0, 0, 1790968059717) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f647013ca1d8cd4a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which vitamin is most soluble in water?', '{"A":"Vitamin D","B":"Vitamin B","C":"Vitamin C","D":"Both B and C"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Vitamins B and C are water-soluble vitamins, meaning they dissolve easily in water.Vitamin B: Includes several B vitamins (B1, B2, B3, etc.), all of which are water-soluble.Vitamin C (Ascorbic acid): Also highly soluble in water.Last verified on 02-04-2026', 0, 0, 0, 1790968059717) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_aff44619dc5bba96', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Normal blood pressure of healthy adult person is _____?', '{"A":"120/80 mm Hg","B":"150/50 mm Hg","C":"140/80 mm Hg","D":"140/100 mm Hg"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Normal blood pressure is 120/80 mmHg.High-normal: 130–139 mmHg, High: >140 mmHg.mmHg means millimeters of mercury, the unit of pressure.Blood pressure is measured using a Sphygmomanometer.Maintaining normal BP is essential for heart and overall health.Last verified on 02-04-2026', 0, 0, 0, 1790968059717) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ccdf6df767628f27', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which of these are involved in the clotting of blood?', '{"A":"Platelets","B":"Haemoglobin","C":"Albumin","D":"Globulin"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Platelets, also called thrombocytes.They are blood cells that play a vital role in blood clotting.When a blood vessel is injured, platelets aggregate to form a plug that stops the bleeding.Last verified on 02-04-2026', 0, 0, 0, 1790968059717) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_78d4e0079de59d28', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The average adult has a blood volume of about ___ litters.', '{"A":"6","B":"4","C":"8","D":"5"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The average adult has a blood volume of about 5 liters (5-6 litres), though this can range from 4.5 to 5.5 liters.Male: About 5.5 liters.Female: About 4.5 liters.Proportion: Blood makes up roughly 7% of a person''s total body weight. Last verified on 30-03-2026', 0, 0, 0, 1790968059753) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b181126580cca50d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Guava has the maximum amount of which Vitamin?', '{"A":"Vitamin K","B":"Vitamin B","C":"Vitamin C","D":"Vitamin D"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Guava is rich in Vitamin C.Contains more Vitamin C than oranges per 100 g.Strengthens immunity and skin health.Helps in iron absorption and antioxidant protection.Last verified on 30-03-2026', 0, 0, 0, 1790968059753) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_65a1ef41cc86d3de', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'How many proton and neutron are present in the nucleus of Tritium isotope?', '{"A":"2 and 1","B":"1 and 2","C":"3 and 2","D":"4 and 1"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tritium, also known as superheavy hydrogen.It has 1 proton and 2 neutrons in its atomic nucleus.Additional information:Protium (¹H) → 1 proton, 0 neutronsDeuterium (²H) → 1 proton, 1 neutronLast verified on 19-03-2026', 0, 0, 0, 1790968059753) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_09f6a4fc36b5b53d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The sum of protons and neutrons in the nucleus of an atom is known as ____?', '{"A":"Atomic Mass","B":"Mass Number","C":"Atomic Number","D":"Valance Number"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The mass number (A) is the sum of protons and neutrons present in the nucleus of an atom.It is a measure of the total number of nucleons (protons and neutrons) in the nucleus.It helps determine the atomic mass and distinguishes isotopes of an element.Last verified on 19-03-2026', 0, 0, 0, 1790968059753) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_52780e146e510bbe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which among the following is not present in the animal cell? Chloroplast, Nucleus, Cell wall, Both A and C', '{"A":"Chloroplast","B":"Nucleus","C":"Cell wall","D":"Both A and C"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Animal cells do not have chloroplasts, as they are not capable of photosynthesis.Animal cells also do not have a cell wall, unlike plant cells and some other organisms.The components of an animal cell:Cell MembraneCytoplasmSmall VacuoleNucleusChromosomesLast verified on 18-03-2026', 0, 0, 0, 1790968059753) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f8f5e5e94a516e4d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Doctors usually check the blood pressure of body through apparatus called _____?', '{"A":"Thermometer","B":"Sphygmomanometer","C":"Glucometer","D":"Stethoscope"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A sphygmomanometer is a medical device used to measure blood pressure.It consists of an inflatable cuff and a pressure gauge.Last verified on 17-03-2026', 0, 0, 0, 1790968059753) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_19a88e6d11d9ded9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Cell organelle that is the site of respiration in a cell is called?', '{"A":"Mitochondrion","B":"Nucleus","C":"Endoplasmic Reticulum","D":"Golgi Apparatus"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mitochondria are known as the powerhouse of the cell.They are the site of cellular respiration, where glucose is converted into ATP (energy).Mitochondria have a double membrane and their own DNA and ribosomes.They provide energy for all cell activities.Last verified on 13-03-2026', 0, 0, 0, 1790968059753) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e1f6e928a022ddae', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The basic physical and functional unit of heredity is called _____?', '{"A":"Chromosome","B":"Gene","C":"Cell","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Gene Definition: Basic physical and functional unit of heredityLocation: Found on chromosomes within DNAFunction: Codes for proteins or RNA molecules that determine traitsTypes: Structural genes (proteins), regulatory genes (control expression)Inheritance: Passed from parents to offspring during reproductionLast verified on 05-02-2026', 0, 0, 0, 1790968059753) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7c27f027ae3716f2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The body system that controls and coordinates for the function of all other organ systems is called ____?', '{"A":"Circulatory System","B":"Nervous System","C":"Respiratory System","D":"Digestive System"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The nervous system is the body system that controls and coordinates the functions of all other organ systems.It allowing for integration and regulation of various bodily functions.It consists of the brain, spinal cord, nerves, and sensory organs.Last verified on 09-03-2026', 0, 0, 0, 1790968059784) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4a3cdea826a361db', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'What is the pH value of Human Blood?', '{"A":"4.12 to 4.24","B":"3.20 to 4.20","C":"7.35 to 7.45","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Normal Range: 7.35–7.45 (slightly alkaline).Optimal Value: Often considered 7.4.Regulation: Maintained by blood buffers (such as bicarbonate), the respiratory system, and renal function (excretion of acids/bases).Fatal Range: A pH below 7.0 or above 7.7 can be fatal. Last updated 17-02-2026', 0, 0, 0, 1790968059784) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_69d889fcb8b594b0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Programmed cell death is known as _____?', '{"A":"Proliferation","B":"Apoptosis","C":"Cell differentiation","D":"Initiation"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Programmed cell death is known as apoptosis.It is a controlled process that allows the body to eliminate damaged or unnecessary cells without causing inflammation.Last verified on 11-02-2026', 0, 0, 0, 1790968059784) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6e50ae77c612149d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which of the following organ is responsible for filtering blood?', '{"A":"Intestine","B":"Brain","C":"Stomach","D":"Kidney"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The kidney is the primary organ responsible for filtering blood in the human body.Each kidney contains approximately one million microscopic units called nephronsThey actively remove metabolic wastes (such as urea and creatinine)', 0, 0, 0, 1790968059784) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cc48fda2c613f6ee', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'In oomycetes, a group of fungi, the cell wall is made of _____?', '{"A":"Chitin","B":"Lignin","C":"Murein","D":"Cellulose"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Oomycetes are fungus-like organisms, often called water molds.Although they resemble true fungi, their cell wall composition is different.In oomycetes, the cell wall is mainly composed of cellulose.Additional information:True fungi have chitin in their cell walls, while oomycetes have cellulose.A common example of oomycetes is Phytophthora, which causes plant diseases.Last verified on 23-01-2026', 0, 0, 0, 1790968059784) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_302e5aa42b6dc113', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Vitamin E is stored in ______?', '{"A":"Liver / Adipose tissue","B":"Kidney","C":"Stomach","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Vitamin E is a fat-soluble vitamin important for protecting cells from oxidative damage.It is stored in the body’s fat tissues and liver.Additional information:Vitamin E acts as an antioxidant.Found in nuts, seeds, vegetable oils, and green leafy vegetables.Last verified on 17-01-2026', 0, 0, 0, 1790968059784) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2eb3aa5621b05994', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The vitamin that controls the browning in fruits with the help of enzymes is _____?', '{"A":"Vitamin K","B":"Vitamin C","C":"Vitamin B","D":"Vitamin D"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Vitamin C (Ascorbic acid) helps prevent browning in fruits.By inhibiting the enzymes responsible for oxidation.It is commonly used to keep cut fruits fresh.Additional information:Commonly used in food preservation (lemon juice on fruits)Also essential for immunity and collagen formationLast verified on 16-01-2026', 0, 0, 0, 1790968059784) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7ffadb82d400576d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Vitamin ___ cannot be stored in Human Body.', '{"A":"C","B":"A","C":"D","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The vitamins not stored in the human body are Vitamin C and most B-complex vitamins Because they dissolve in water, the kidneys filter out what isn''t immediately used, preventing buildup and toxicity but necessitating daily replenishment. Vitamin C (Ascorbic Acid): Essential for collagen and immune function, but any surplus is flushed out. B Vitamins (except B12): Includes Thiamin (B1), Riboflavin (B2), Niacin (B3), Pantothenic Acid (B5), Pyridoxine (B6), Biotin (B7), and Folate (B9).', 0, 0, 0, 1790968059784) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e4d0aba043c60c1d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'What is the weight of heart of adult human being?', '{"A":"100 grams","B":"300 grams","C":"200 grams","D":"400 grams"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 300 grams is the weight of the heart of an adult human being.The average gross weight of the heart was for men 289.6 gThe average gross weight of the heart was for women 284.7 At the age of 61-70 years, the average weight of men was 345.9At the age of 61-70 years, the average weight of women was 285.1*****ٓAdditional Informations*****A human brain weight is 1400 grams.A human weight is 300 grams.', 0, 0, 0, 1790968059820) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5a81cdac9cd5fb89', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Fat soluble vitamins are _____?', '{"A":"A","B":"D","C":"E and K","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A, D, E, and K are fat-soluble vitamins.Fat-soluble vitamins are absorbed by the body along with dietary fats.They are present in foods that contain fats.The body stores these vitamins in the liver and fat tissue when they are not in use. Megadoses of fat-soluble vitamins can be toxic.', 0, 0, 0, 1790968059820) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6b3f0f4d2a0db2b5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The process in which nuclei of heavy elements are broken into lighter nuclei and produce a large amount of heat energy is called?', '{"A":"Fusion","B":"Geometry","C":"Regales","D":"Fission"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fission is the splitting of a nucleus that releases free neutrons and lighter nuclei.The fission of heavy elements is highly exothermic which releases about 200 million eV compared to burning coal which only gives a few eV.', 0, 0, 0, 1790968059820) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d9db70f762349260', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which vitamin strengthens the immune system and prevents from the disease called Scurvy?', '{"A":"Vitamin D","B":"Vitamin A","C":"Vitamin C","D":"Vitamin K"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ایک ایسی بیماری ہے جس سے کمزوری ہوجاتی ہے اور جسم میں خون کی کمی ہوجاتی ہےScurvyScurvy is a disease caused by a serious vitamin C deficiency.Not eating enough fruits and vegetables is the main cause of the disease. scurvy can lead to bleeding gums, loosened teeth and bleeding under your skin.Vitamin C, also known as ascorbic acid, is necessary for the growth, development and repair of all body tissues.', 0, 0, 0, 1790968059820) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7fe6c5e312fda605', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'How many chambers in human heart?', '{"A":"2","B":"4","C":"5","D":"3"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The heart consists of four chambers in which blood flows.Blood enters the right atrium and passes through the right ventricle. The right ventricle pumps the blood to the lungs where it becomes oxygenated.******ND11-12-2022', 0, 0, 0, 1790968059820) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1e1262269da8281a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which disease is caused due to the deficiency of vitamin D that causes bones to become soft and weak?', '{"A":"Beriberi","B":"Rickets","C":"Night Blindness","D":"Scurvy"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Vitamin D deficiency can cause Rickets, a disease characterized by:Soft and weak bonesSkeletal deformitiesStunted growthIncreased risk of fractures', 0, 0, 0, 1790968059820) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_36013c794efea343', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Red colour of the blood is due to ______?', '{"A":"Haemoglobin","B":"Myoglobin","C":"Thyroglobin","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Human blood is red because hemoglobin.It is carried in the blood and functions to transport oxygen.It is iron-rich and red in color.Octopuses and horseshoe crabs have blue blood. This is because the protein transporting oxygen in their blood, hemocyanin, is actually blue.', 0, 0, 0, 1790968059820) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9db538e3f15ee520', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'In human body, ______ is/are primarily used to stop bleeding by forming blood clots at the site of a damaged blood vessel.', '{"A":"Red blood cells","B":"White blood cells","C":"Platelets","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Platelets (a type of blood cell) and proteins in your plasma (the liquid part of the blood) work together to stop the bleeding by forming a clot over the injury. Vitamin K helps to make various proteins that are needed for blood clotting and the building of bones.Human blood platelets release fibrin which helps in clotting of blood.', 0, 0, 0, 1790968059820) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7b6e078d4534227c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which food contains the highest concentration of protein and iron?', '{"A":"Meat","B":"Fruits","C":"Vegetables","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Meat, especially lean options like chicken, beef, and pork, is a rich source of protein.It is also high in iron, essential for blood and energy production.', 0, 0, 0, 1790968059852) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fc556953ef1b8af6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Sunlight is a good source of vitamin ____?', '{"A":"D","B":"A","C":"B","D":"C"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sunlight is a good source of vitamin D.When our skin is exposed to sunlight, it produces vitamin D.It is essential for bone health, immune function, and the regulation of calcium levels in the blood.', 0, 0, 0, 1790968059852) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_263e36e41e69901b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Friendly bacteria live in our large intestines. Identify the vitamin they make for us?', '{"A":"Vitamin K","B":"Vitamin A","C":"Vitamin D","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Friendly bacteria in our large intestine produce Vitamin K, which helps in blood clotting.These bacteria mainly synthesize Vitamin K2, important for bone and heart health.', 0, 0, 0, 1790968059852) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_be05df76be58c55a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The Lifespan of White Blood Cells is _____?', '{"A":"13-20","B":"14-15","C":"15-30","D":"10-40"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The lifespan of white blood cells ranges from 13 to 20 days, after which time they are destroyed in the lymphatic system. When immature WBCs are first released from the bone marrow into the peripheral blood, they are called "bands" or "stabs."ND23-4-2023', 0, 0, 0, 1790968059852) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_95408e8d003951e5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Weakness in muscles and increase in the fragility of red blood cells is caused due to the _____?', '{"A":"Deficiency of vitamin E","B":"Deficiency of vitamin C","C":"Deficiency of vitamin A","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Vitamin E is a powerful antioxidant that helps protect cells from damage caused by free radicals. A deficiency can lead to oxidative stress that harms the central nervous system, causing muscle weakness and difficulties with coordination.A lack of vitamin E impairs the stability of red blood cells, making them more fragile and prone to rupture. This leads to a type of anemia called hemolytic anemia.', 0, 0, 0, 1790968059852) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d051496a279e6771', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The instrument used to measure blood pressure is?', '{"A":"E.C.G","B":"Tethoscope","C":"Sphygmomanometer","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A sphygmomanometer also known as a blood pressure monitor.It is a device used to measure blood pressure.A normal blood pressure level of 120/80 mmHg.High-normal: 130 to 139 mmHgHigh: Greater than 140 mmHgwhilemmHg stands for "Millimeter of Mercury"', 0, 0, 0, 1790968059852) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ce6f0a752585f430', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Blood cells are manufactured/produced by ______ of the body.', '{"A":"Kidney","B":"Bone marrow","C":"Liver","D":"Spleen"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Blood cells are made in the bone marrow. The bone marrow is the soft, spongy material in the center of the bones. It produces about 95% of the body''s blood cells.', 0, 0, 0, 1790968059852) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_03a93959b27ce9ff', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which part of the human brain is the center of memory, learning, thinking, and reasoning?', '{"A":"Cerebellum","B":"Cerebrum","C":"Medulla","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The cerebrum is the largest part of the brain.It is responsible for higher brain functions, including reasoning, thinking, emotions, and learning.Specifically, the frontal lobe of the cerebrum is associated with reasoning, problem-solving, and higher-level cognition.', 0, 0, 0, 1790968059852) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9abf1bf934786a3c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'What is the study of heredity called?', '{"A":"Genealogy","B":"Genetics","C":"Gynecology","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Genetics is a branch of biology concerned with the study of genes, genetic variation, and heredity in organisms.', 0, 0, 0, 1790968059897) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_04ce0bb8e69ab85d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The human cell contains _____ chromosomes?', '{"A":"44","B":"45","C":"46","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The human cell contains 46 chromosomes. These are organized into 23 pairs, where each parent contributes one chromosome to each pair, resulting in a total of 46 chromosomes in most human cells. This number includes 22 pairs of autosomes and 1 pair of sex chromosomes, determining an individual''s sex (XX for females and XY for males).', 0, 0, 0, 1790968059897) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2f970b3ced5036f0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The part of brain involved in reasoning is ______?', '{"A":"Fore brain","B":"Cerebrum","C":"Cortex","D":"Frontal lobe"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Frontal Lobe (part of the Cerebrum) controls reasoning, planning, and problem-solving. More Details Cerebellum → balance & coordination, Medulla → involuntary actions, Cerebrum → higher thinking functions, divided into 4 lobes (Frontal, Parietal, Temporal, Occipital).', 0, 0, 0, 1790968059897) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bcd900929d973fdc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'From the following in which fruit vitamin C.', '{"A":"Banana","B":"Apple","C":"Orange","D":"Grapes"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lemon is rich in Vitamin C, which helps boost immunity and improve skin health.Other citrus fruits like oranges and lime are also high in Vitamin C.Also known as ascorbic AcidDeficiency of vitamin C causes skin diseases', 0, 0, 0, 1790968059897) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_64ac3f39452b3aad', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The digested food is mainly absorbed into the blood through capillaries in _____?', '{"A":"Stomach","B":"Large intestine","C":"Small intestine","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Small intestine is the primary site for nutrient absorption into the bloodstream.It contains villi and microvilli, which increase the surface area for efficient absorption of digested food.', 0, 0, 0, 1790968059897) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6017a273fecdcdc1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The genetic information present in the shape of threads in nucleus is called ______?', '{"A":"Chromosomes","B":"Heredity","C":"Allele","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Chromosomes are thread-like structures in the nucleus carrying genetic information (DNA).They determine an organism’s traits and heredity.', 0, 0, 0, 1790968059897) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7ceec974c2c06f43', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'What is the standard unit of cell potential (electromotive force)?', '{"A":"Ampere","B":"Joule","C":"Volt","D":"Ohm"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The standard unit of cell potential, also known as electromotive force (EMF), is the volt (V). It represents the potential difference between the electrodes of a galvanic cell under standard conditions (1 M concentration for all species, 1 atm pressure for all gases, and a temperature of 25°C).', 0, 0, 0, 1790968059897) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_22f310ccd99319bc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The pH of human blood is ______?', '{"A":"7.2-7.3","B":"7.3-7.4","C":"7.4-7.5","D":"7.1-7.2"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation pH stands for "Potential Hydrogen"Blood is normally slightly basic, with a normal pH range of about 7.35 to 7.45. Usually, the body maintains the pH of blood close to 7.40.Acidosis is characterized by a pH of 7.35 or lower. Alkalosis is characterized by a pH level of 7.45 or higher.***', 0, 0, 0, 1790968059897) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a322e0fc5cc1e67e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Blood is cleaned by _____?', '{"A":"Kidneys","B":"Lungs","C":"Liver","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The function of kidneys is to remove toxins or waste products from your blood. Kidneys keep the right amount of water in the body.Your kidneys also help control your blood pressure.', 0, 0, 0, 1790968059952) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_285282facc530ff1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Marker of bone formation are all except? Osteocalcin, Hydroxyproline, Procollagen Residue lkaline, Phosphate', '{"A":"Osteocalcin","B":"Hydroxyproline","C":"Procollagen Residue","D":"lkaline Phosphate"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Marker of bone formation are OsteocalcinBone Markers are Blood and Urine tests that detect products of bones.Osteocalcin is a protein that helps to regenerate bone tissue.All are important markers of bone formation except hydroxyproline which is a marker for wound healing.', 0, 0, 0, 1790968059952) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bbdce9d771c6d57f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which of the following is a sac like structure which stores waste material for some time before its removal from the cell?', '{"A":"Cytoplasm","B":"Nucleus","C":"Cell membrane","D":"Vacuole"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A vacuole is a sac-like organelle in cells that stores waste materials, water, and nutrients before they are removed or used by the cell. It plays a key role in maintaining cell homeostasis.', 0, 0, 0, 1790968059952) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7044e8303541decf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The primary excretory organ in fishes is _____?', '{"A":"Skin","B":"Gills","C":"Kidney","D":"All of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The kidney is the primary excretory organ in fishes, responsible for osmoregulation and excretion of nitrogenous wastes. However, gills and skin also play minor roles in excretion.', 0, 0, 0, 1790968059952) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_baa6714ce277b40b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Bile helps in fat digestion and is secreted by which one of the following organs?', '{"A":"Liver","B":"Stomach","C":"Gall bladder","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bile is produced by the liver.It plays a key role in breaking down (emulsifying) fats for digestion.The gall bladder stores and releases bile.', 0, 0, 0, 1790968059952) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c1f19bb21573b15f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The most rigid form of connective tissue is _____?', '{"A":"Tendon","B":"Cartilage","C":"Bone","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bone is the hardest and most rigid connective tissue in the body.It provides structural support and protection to organs.', 0, 0, 0, 1790968059952) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d04622e30d330c3e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The concept of an atom with central nucleus was introduced/discovered by _____?', '{"A":"Rutherford","B":"Bohr","C":"J. J. Thomson","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ernest Rutherford (1911) proposed the nuclear model of the atom with a dense central nucleus.This came after his gold foil experiment, which showed atoms have a small, positively charged core.He was a New Zealand-born British physicist who came to be known as the father of nuclear physics.', 0, 0, 0, 1790968059952) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b7f7d896fb3a57d3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'In a kidney dialysis machine, which substance will not be diffused from the patient''s blood into the dialysis fluid?', '{"A":"Protein","B":"Salts","C":"Urea","D":"Water"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Proteins are indeed large molecules that cannot pass through the pores of a dialysis membrane due to their size, Allowing dialysis to be used for purification or buffer exchange by separating them from smaller molecules and ions.', 0, 0, 0, 1790968059952) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_749100cab09f5143', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'In the human heart, why is the wall of the right ventricle thicker than the wall of the right atrium?', '{"A":"The right atrium must pump blood all the way around the body","B":"The chambers have different oxygen concentrations","C":"The right ventricle must exert a greater force than the right atrium","D":"The right ventricle receives more blood than the right atrium"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The right ventricle is responsible for pumping deoxygenated blood to the lungs. While the right atrium receives blood from the vena cava, it only needs to passively push that blood into the right ventricle. The right ventricle, however, needs to generate significant force to propel the blood through the pulmonary artery to the lungs. This requires a thicker, more muscular wall.', 0, 0, 0, 1790968059993) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4380b815c1a04c70', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'In the human circulatory system, what causes the transfer of materials from the capillaries to the tissue fluid?', '{"A":"Active transport","B":"Blood pressure","C":"Capillarity","D":"Osmosis"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The primary force driving the transfer of materials from capillaries to tissue fluid is blood pressure. This pressure pushes fluid and solutes out of the capillaries at the arterial end, Where it is higher, and draws fluid back in at the venous end, where it is lower. This process is called filtration.', 0, 0, 0, 1790968059993) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_279bff6edaac635d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which statement about chromosome is correct? Genes include long DNA molecules called chromosomes, Chromosomes are long DNA molecules called genes which are divided into sections, Chromosomes include a long molecule of DNA divided into sections called genes, Chromosomes include genes which are divided into sections called DNA molecules', '{"A":"Genes include long DNA molecules called chromosomes","B":"Chromosomes are long DNA molecules called genes which are divided into sections","C":"Chromosomes include a long molecule of DNA divided into sections called genes","D":"Chromosomes include genes which are divided into sections called DNA molecules"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A chromosome is a long DNA molecule that carries genetic information.Genes are specific segments of DNA on the chromosome that code for proteins or functional RNA.', 0, 0, 0, 1790968059993) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7afae5061fc923c5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which statement is correct for all viruses but not for all bacteria and fungi? Most of the cell is cytoplasm, The outer layer is cellulose, They are all parasite, They have a nucleus containing DNA or RNA', '{"A":"Most of the cell is cytoplasm","B":"The outer layer is cellulose","C":"They are all parasite","D":"They have a nucleus containing DNA or RNA"}', 'D', NULL, 0, 0, 0, 1790968059993) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f546cc8e6efe64d4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The type of nerve impulse in non myelinated neuron will be _____?', '{"A":"Continuous","B":"Saltatory","C":"Electrical","D":"All of them"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The type of nerve impulse in a non-myelinated neuron is continuous. In unmyelinated neurons, the action potential travels along the entire axon membrane, requiring continuous depolarization and repolarization.Whereas in myelinated neurons, the action potential "jumps" from node to node (saltatory conduction), which is much faster.', 0, 0, 0, 1790968059993) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_da5dc50b2114506e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'A wave of electrochemical change that travels along the length of neuron, from one end to other is _____?', '{"A":"Reflex arc","B":"Reflex action","C":"Nerve impulse","D":"Influx"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A nerve impulse is an electrochemical signal that travels along a neuron’s axon.It results from the movement of ions across the neuron membrane (depolarization and repolarization).', 0, 0, 0, 1790968059993) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3aa35c5ec2a0ad69', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The organ of voice in birds is called _____?', '{"A":"Larynx","B":"Vocal cords","C":"Syrinx","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In birds, the syrinx is the voice-producing organ located at the base of the trachea.It allows birds to produce complex sounds and songs.', 0, 0, 0, 1790968059993) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_07fcbe640208f33b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Red blood cells that do not contain either A or B antigens on their surface are normally found in the person with blood type _____?', '{"A":"B","B":"O","C":"A","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Blood type O has no A or B antigens on the surface of red blood cells.That''s why type O is known as the universal donor in blood transfusion.', 0, 0, 0, 1790968059993) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fa6709c0b9202df7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Cell theory was given by _____?', '{"A":"Matthias Schleiden","B":"Theodor Schwann","C":"Both A and B","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The cell was first coined by an English scientist Robert Hooke in the year 1665. Later the cell theory was given by Matthias Schleiden and Theodor Schwann.', 0, 0, 0, 1790968060031) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_940107f7592d20dd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'A person with the following blood group is considered to be a universal recipient?', '{"A":"AB+","B":"B+","C":"O+","D":"A+"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation AB positive (AB+) and O negative (O-) are considered universal blood typesbecause they can receive blood from all blood kinds without experiencing any hemolytic reactions.', 0, 0, 0, 1790968060031) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8c469cef1d44e5cc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which organ is responsible the pumping blood in the human body?', '{"A":"Lungs","B":"Heart","C":"Liver","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The heart is the primary muscular organ Responsible for pumping bloodFour chambers (two atria and two ventricles) that manage blood flow.It ensures that oxygen and nutrients are delivered to tissues and organs.Last updated by NA on 23-April-2026', 0, 0, 0, 1790968060031) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4aee7ac2797e21b8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Hemoglobin combines with---and transport to different cells of the body.', '{"A":"White blood cells","B":"Red blood cells","C":"Both a and b","D":"Oxygen"}', 'B', NULL, 0, 0, 0, 1790968060031) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3baec999dee7cbb9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Protein is synthesized by which organelle in cell?', '{"A":"Mitochondria","B":"Ribosome","C":"Golgi apparatus","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ribosomes are the site of protein synthesis.They join amino acids to form proteins.Ribosomes can be free or attached to the rough ER.They are found free in the cytoplasm or attached to the rough endoplasmic reticulum (RER).', 0, 0, 0, 1790968060031) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2aa7c555d20e7597', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The cell wall is present in all types of cells Except _____? A) Plant, B) Bacteria, C) Animal, D)Fungus', '{"A":"Plant","B":"Bacteria","C":"Animal","D":"Fungus"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cell Wall Presence:Present in:Plants (made of cellulose),Bacteria (peptidoglycan),Fungi (chitin).Absent in: Animal cells (only have a cell membrane).', 0, 0, 0, 1790968060031) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6bc6d6033a1b6be2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which blood cells are called the Soldiers of Body?', '{"A":"Red Blood Cells","B":"White Blood Cells","C":"Platelets","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation White blood cells are called soldiers of the body, because the white blood cells provide immunity to our body. They help in fighting against diseases, infections, allergies and foreign particles.', 0, 0, 0, 1790968060031) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_09788f83a67d7538', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which of the following belongs to blood circulatory system?', '{"A":"Brain","B":"Heart","C":"Ears","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The heart is the central organ of the blood circulatory system, responsible for pumping blood throughout the body.It circulates oxygen, nutrients, and waste products via arteries and veins.', 0, 0, 0, 1790968060031) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dac0e48ead9ce1ed', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which of the following contains large quantity of Vitamin C? Lemon ,Banana ,Grapes ,None of these', '{"A":"Lemon","B":"Banana","C":"Grapes","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lemon is rich in Vitamin C, which helps boost immunity and improve skin health.Other citrus fruits like oranges and lime are also high in Vitamin C.But among the given options, lemon contains the most.', 0, 0, 0, 1790968060064) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_986c2a34957fa68f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The largest excretory organ of the body is ______?', '{"A":"Lungs","B":"Liver","C":"Skin","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The skin is the largest excretory organ of the body.It helps in the removal of waste products like sweat, which contains water, salts, and urea.', 0, 0, 0, 1790968060064) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_16a77cc10dada618', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The main excretory organ of the body is _____?', '{"A":"Liver","B":"Skin","C":"Kidney","D":"Lungs"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The kidneys are the primary organs responsible for removing waste and excess substances from the body through urine.They filter the blood and regulate electrolyte levels, playing a critical role in maintaining overall bodily function.', 0, 0, 0, 1790968060064) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c7e73b9ae2d992cf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which one is essential for the formation of hemoglobin?', '{"A":"Calcium","B":"Iron","C":"Water","D":"Carbohydrates"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Iron is essential for hemoglobin formation.About 70% of the body''s iron is in hemoglobin and myoglobin.Function → oxygen transport.Structure → Quaternary.Main component → Fe²⁺.B6 deficiency → ↓ hemoglobin.Heme → Protoporphyrin IX + Fe²⁺.Adult Hb level → 1st year.Fe³⁺ → not normal in Hb.Location → Red blood cells.', 0, 0, 0, 1790968060064) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e48e89e797f5f9ee', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The fluid part of blood can be used against COVID-19 is _________?', '{"A":"Plasma","B":"Platelets","C":"Blood cells","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Human blood consists of a fluid part called plasma and cellular part consisting of RBCs (red blood cells), WBCs (white blood cells) and platelets.Plasma from recovered COVID-19 patients contains antibodies that can help others fight the virus (called convalescent plasma therapy).It is the fluid part of blood that carries proteins, nutrients, and immune cells.', 0, 0, 0, 1790968060064) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_75a396c8105eb4ef', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The largest blood vessel in the body is the _____?', '{"A":"Aorta","B":"Inferior Vena Cava","C":"Pulmonary Vein","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The largest blood vessel in the body is the: Aort****The blood vessels that supply blood to heart muscles are: Coronary arteriesBlood vessels that carry blood away from the heart toward body tissues are called: ArteriesThe smallest blood vessels are called capillaries.', 0, 0, 0, 1790968060064) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7bc693627b4abe1e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'A vitamin that affects vision in dim light is ______?', '{"A":"C","B":"A","C":"D","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Vitamin A is essential for the formation of rhodopsin, a pigment in the retina that helps with vision in dim light.Deficiency of Vitamin A can lead to night blindness.', 0, 0, 0, 1790968060064) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5ab5d1bce2629082', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'What is the normal resting heart rate for a healthy adult?', '{"A":"60–100 beats per minute (bpm)","B":"30–50 beats per minute (bpm)","C":"120–150 beats per minute (bpm)","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 72 beats per minute is a good heart rate.Complete answer:The resting person usually has a pulse rate between 70 (beats per minute) and 80 (beats per minute).Your risk of dying from a heart attack is lower if your heart rate is below 80 beats per minute.A normal resting heart rate ranges from 60 to 100 beats per minute.', 0, 0, 0, 1790968060064) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a7310f4c95058cc5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Another name (chemical name) of vitamin C is ______?', '{"A":"Carbohydrates","B":"Riboflavin","C":"Enzymes","D":"Ascorbic acid"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Vitamin C, also known as ascorbic acid, is necessary for the growth, development and repair of all body tissues.Vitamin C is a water-soluble vitamin found in citrus fruits and other fruits and vegetables, and is also sold as a dietary supplement.A natural water-soluble vitamin (Vitamin C)Vitamin C, also known as ascorbic acid.Vitamin C is necessary for the growth, development, and repair of all body tissues.', 0, 0, 0, 1790968060098) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3e785a4674f85361', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The energy currency of the cell (body) is _____?', '{"A":"ATP","B":"AMP","C":"ADP","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ATP (Adenosine Triphosphate) is called the energy currency of the cell because it stores and provides energy for cellular activities.It releases energy when converted to ADP (Adenosine Diphosphate), which is then recycled back into ATP through cellular respiration.', 0, 0, 0, 1790968060098) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9182ff40bd91043f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The production of protein from messenger RNA is called ______?', '{"A":"Transduction","B":"Translation","C":"Transcription","D":"Replication"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The process of producing a protein from mRNA is called translation. First, mRNA, carrying the genetic code from DNA, is created through transcription. Then, this mRNA molecule travels to ribosomes, Where it is translated into a specific sequence of amino acids, forming a polypeptide chain. This polypeptide then folds into a functional protein.', 0, 0, 0, 1790968060098) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_17b735b916853da6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Blood cancer is also called ______?', '{"A":"Leukemia","B":"Thalassemia","C":"Edema","D":"Anemia"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Leukemia is a cancer of the body''s blood-forming tissues.Including the bone marrow and the lymphatic system.Some forms of leukemia are more common in children.', 0, 0, 0, 1790968060098) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6ad5041bb4d78276', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The fungal cells having two nuclei of different genetic types?', '{"A":"Heterokaryotic","B":"Dikaryotic","C":"Diploid","D":"Both (a) and (b)"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Heterokaryotic cells have two or more genetically different nuclei in the same cell.Dikaryotic is a type of heterokaryotic state with exactly two nuclei, often seen in fungi.', 0, 0, 0, 1790968060098) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_aff29530a5a66f63', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The ECG records _______ between points on human skin generated by electric process in the heart.', '{"A":"Heart Beat","B":"Pulse Rate","C":"Pressure","D":"Voltage"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ECG (Electrocardiogram) measures the electrical activity of the heart.It records the voltage differences between points on the skin caused by the heart''s electrical impulses.These voltages reflect the depolarization and repolarization of the heart muscles during each cardiac cycle.', 0, 0, 0, 1790968060098) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_da113841deec7961', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Human liver which substance cause cancer ______?', '{"A":"Carbon dioxide","B":"Chloroform","C":"Methane","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Chloroform is classified as a possible human carcinogen, particularly linked to liver and kidney cancer with prolonged exposure.It affects the liver by causing cellular damage.It has been shown to induce tumors in animal studies.', 0, 0, 0, 1790968060098) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3254d3ae50062570', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Amoeba and paramecium live in water and are unicellular. They are included into Kingdom ______?', '{"A":"Plantae","B":"Monera","C":"Protista","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Amoeba and Paramecium are unicellular, eukaryotic organisms classified under Kingdom Protista.They live in water and move using structures like pseudopodia (Amoeba) and cilia (Paramecium).', 0, 0, 0, 1790968060098) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_647042f9948a5720', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The nucleus of an atom consists of?', '{"A":"Protons and neutrons","B":"Neutrons and electrons","C":"Protons, neutrons and electrons","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The nucleus of an atom contains protons and neutrons.The nucleus is the central part of an atom.Protons have a positive charge.Neutrons have no electric charge.Electrons are found outside the nucleusThe nucleus makes up much less than. 01% of the volume of the atom, But typically contains more than 99.9% of the mass of the atom.', 0, 0, 0, 1790968060134) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b135b005e16aece8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The human brain is enclosed in a hard-bony protective structure called _____?', '{"A":"Cerebrum","B":"Cranium","C":"Parietal Lobe","D":"Temporal lobe"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The cranium is the bony structure that encloses and protects the human brain.It is also known as the skull.It forms the upper part of the skull.It providing a protective casing for the brain.', 0, 0, 0, 1790968060134) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cc2a5cfc9dd0fa18', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'A chemical process that changes vegetable oil into fat is called ________?', '{"A":"Combustion","B":"Hydrogenation","C":"Hydration","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A hydrogenation reaction occurs when vegetable oils are converted to fats. The double bonds of vegetable oils are broken down resulting in a saturated fat i.e. ghee.', 0, 0, 0, 1790968060134) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dfb46a3bfaec9ed9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which of the following is secreted by liver and stored in the gallbladder?', '{"A":"Saliva","B":"Bile","C":"Gastric juice","D":"Pancreatic juice"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bile is produced by the liver and stored in the gallbladder.It is released into the small intestine to facilitate fat digestion and absorption.Bile breaks down fats into smaller particles, making it easier for enzymes to digest them.', 0, 0, 0, 1790968060134) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2753dc26160975eb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which organ is made up of air carrying tubes and tiny sacs?', '{"A":"Brain","B":"Lungs","C":"Liver","D":"Heart"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The lungs are the organs responsible for exchanging oxygen and carbon dioxide through the process of respiration.They consist of air-carrying tubes (bronchi and bronchioles) and tiny sacs (alveoli) where gas exchange occurs.', 0, 0, 0, 1790968060134) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9445bd9d6403f365', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which arise from the pre-existing cells by cell division?', '{"A":"New cells","B":"Old cells","C":"Both A and B","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation All cells arise from pre-existing cells — this is cell theory.Confirmed by Rudolf Virchow (1855): "Omnis cellula e cellula" (every cell from a cell).New cells form through cell division — mitosis (growth/repair) and meiosis (reproduction).No cell appears spontaneously; all trace back to an earlier cell.', 0, 0, 0, 1790968060134) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6972a2f62ad00756', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'In human beings, there are 23 pairs of chromosomes. Down’s syndrome disorder is concerned with chromosome number _____?', '{"A":"23","B":"22","C":"21","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Down syndrome disorder is associated with chromosome number 21.It is a genetic condition caused by the presence of an extra full or partial copy of chromosome 21, Resulting in a total of 47 chromosomes instead of the typical 46. This condition is also known as Trisomy 21. Last updated question 28 feb 2026', 0, 0, 0, 1790968060134) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_560b1eb22c058e92', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which of the following is the type of Muscle?', '{"A":"Tissue","B":"Cell","C":"System","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Muscle is a type of tissue that contracts to produce movement.The three main types of muscle tissues are skeletal, smooth, and cardiac.', 0, 0, 0, 1790968060134) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_baaae69cd28dbf1b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Brain controls the body just like the _______ controls activities of a cell.', '{"A":"Ribosomes","B":"Nucleus","C":"Mitochondria","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Robert Brown discovered Nucleus in: 1831The nucleus controls the activities of a cell, similar to how the brain controls the activities of the body.The nucleus contains the genetic material (DNA) that directs cell functions, just as the brain sends signals to coordinate body functions.', 0, 0, 0, 1790968060163) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e4bfa0df77845185', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Lipid-rich component of bacterial cell are ______?', '{"A":"Capsule","B":"Cell membrane","C":"Call wall","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lipid-rich components of bacterial cells present in the bacterial membrane.Bacterial membranes present a large diversity of amphiphilic lipids.', 0, 0, 0, 1790968060163) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cd8ae6df1c3dcf28', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The total number of chromosomes in a somatic (body) cell of a human is _____?', '{"A":"44","B":"46","C":"45","D":"43"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A chromosome is made up of proteins and DNA organized into genes.Human somatic cells have 46 chromosomes (23 pairs).These include 22 pairs of autosomes and 1 pair of sex chromosomes.', 0, 0, 0, 1790968060163) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_99fb8718e4420077', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which part of the brain controls emotion experience?', '{"A":"Limbic system","B":"Receptor","C":"Medulla oblongata","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The limbic system is the part of the brain primarily involved in processing emotions and memory.It includes structures like the amygdala and hippocampus that regulate emotional responses.', 0, 0, 0, 1790968060163) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bda77736d2d32fd0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Chromosomes, gene, and ______ are the basis of heredity.', '{"A":"DNA","B":"Nucleosome","C":"Nucleoside","D":"Nome of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation DNA is the fundamental molecule that carries genetic information, forming the basis of heredity alongside chromosomes and genes.It is the hereditary material in almost all organisms, encoding the instructions for building proteins and other important molecules.', 0, 0, 0, 1790968060163) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d556df953b9aa26a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The brain of an adult human weighs between ______?', '{"A":"2000 – 2200 g","B":"1300 – 1400 g","C":"130 – 140 g","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The average weight of an adult human brain is about 1300 to 1400 grams.It makes up around 2% of the total body weight but consumes about 20% of the body''s energy.', 0, 0, 0, 1790968060163) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dd05c89b5d2ec41e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Who discovered the first living cell?', '{"A":"Rudolf Virchow","B":"Robert Hooke","C":"Robert Boyl","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Robert Hooke, a 17th-century philosopher and scientist.He was the first to use the word "cell" to describe a basic unit of life.A cell is the smallest unit that can live on its own.Cells make up all living organisms and the tissues of the body.', 0, 0, 0, 1790968060163) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_70aba448a0d440d5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which of the following blood pressure readings indicates hypotension (low blood pressure)', '{"A":"140/90 mmHg","B":"120/80 mmHg","C":"90/60 mmHg","D":"60/90 mmHg"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A blood pressure reading of 60/90 mmHg is considered low blood pressure (hypotension).', 0, 0, 0, 1790968060163) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fdb3861ac173703a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The good sources of Vitamin-B Complex are?', '{"A":"Green leafy vegetables","B":"Seeds","C":"Fresh vegetables and fruits","D":"Sea foods","E":"All of these"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Vitamin-B Complex is found in a wide variety of foods including leafy greens, seeds, fruits, and seafood.It helps in energy production and supports brain and nerve function.', 0, 0, 0, 1790968060193) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_eae6100301a4d852', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The condition in which sugar is found in urine is called?', '{"A":"Hyperglycemia","B":"Glycosuria","C":"Hypoglycemia","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Glycosuria is the presence of glucose in urine.It often due to high blood sugar levels.It is commonly associated with', 0, 0, 0, 1790968060193) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a385e8e3f51bf196', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Chili contain which vitamin?', '{"A":"Vitamin D","B":"Vitamin B","C":"Vitamin C","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Chilies are rich in Vitamin C, which boosts immunity and helps in skin health.They contain more Vitamin C than oranges by weight.', 0, 0, 0, 1790968060193) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_aae4abac0a2213ae', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'A nerve cell is called?', '{"A":"Reflex","B":"Neuron","C":"Dendrite","D":"Nerve"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A neuron, also known as a nerve cell.It is the basic building block of the nervous system.It receives, processes, and transmits information through electrical and chemical signals.It allowing for communication between different parts of the body.', 0, 0, 0, 1790968060193) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_736189828302c8b7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Blood pressure is measured in the pressure of blood in the _____?', '{"A":"Veins","B":"Arteries (Artery walls)","C":"Capillaries","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Blood pressure is the force exerted by blood against the walls of arteries.It reflects how hard the heart is working to pump blood through the arterial system.', 0, 0, 0, 1790968060193) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_28c6ec319a96d540', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The main constituent of Hemoglobin is _____?', '{"A":"Calcium","B":"Iron","C":"Chlorine","D":"Copper"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The main constituent of hemoglobin is iron.Hemoglobin transports oxygen and exhibits a quaternary protein structure.Iron is crucial for hemoglobin formation; its deficiency can impact hemoglobin production.Heme in hemoglobin is protoporphyrin IX.Infants reach adult hemoglobin levels by the end of their first year.Ferric ions are not part of hemoglobin.Hemoglobin is found dissolved in plasma.', 0, 0, 0, 1790968060193) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9ed6346560e41e3a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'During muscular contraction, if there is no change in the size of muscle, this contraction is said ______?', '{"A":"Isometric","B":"Isotonic","C":"Isokinetic","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In isometric contraction, muscle length remains the same while tension increases.No visible movement occurs, as seen in activities like holding a plank or pushing against a wall.', 0, 0, 0, 1790968060193) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ab6c0291e008bebd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The Lifespan of Red Blood Cells (RBCs) ____ days.', '{"A":"120","B":"130","C":"112","D":"110"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The lifespan of a red blood cell is around 120 days.Blood cells are made in the bone marrow.It produces about 95% of the body''s blood cells. Additional information:The lifespan of white blood cells ranges from 13 to 20 days,', 0, 0, 0, 1790968060193) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_eae3459a927cacea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which of the following is not a part of the hind brain?', '{"A":"Thalamus","B":"Cerebellum","C":"Medulla oblongata","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Hindbrain is divided into three main parts:Medulla Oblongata (controls breathing, heart rate, and blood pressure)Pons (involved in controlling sleep and arousal)Cerebellum (coordinates movement, balance, and learning)', 0, 0, 0, 1790968060220) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_109170f5c338ba57', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which organ helps in producing digestive enzyme?', '{"A":"Stomach","B":"Pancreas","C":"Liver","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The pancreas is the enzyme “powerhouse” of digestion. It produces the most important digestive enzymes, which are those that break down carbohydrates, proteins, and fats.the pancreas creates natural juices called pancreatic enzymes to break down foods.', 0, 0, 0, 1790968060220) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_892f51a7298f77bb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The strongest muscle in the human body is _____?', '{"A":"Upper arm","B":"Calf","C":"Thigh","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sartorius is the longest muscle in a human body.The stapedius muscle is considered the weakest and smallest skeletal muscle in the human body.', 0, 0, 0, 1790968060220) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7ebe01958bfdfe11', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The plant cell nucleus was discovered by _____?', '{"A":"Robert Hooke","B":"Matthias Schleiden","C":"Robert Brown","D":"Theodor Schwann"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Robert Brown discovered the nucleus in plant cells.It was first described by Franz Bauer in 1804 and in more detail in 1831 by Scottish botanist Robert Brown.', 0, 0, 0, 1790968060220) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0f4b9cd87c5a6e83', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which of the following is a fat-soluble vitamin?', '{"A":"Vitamin B","B":"Vitamin C","C":"Vitamin B12","D":"Vitamin K"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Vitamins A, D, E, and K are fat-soluble vitamins.Fat-soluble vitamins are absorbed by the body along with dietary fats.They are present in foods that contain fats.The body stores these vitamins in the liver and fat tissue when they are not in use. Megadoses of fat-soluble vitamins can be toxic.', 0, 0, 0, 1790968060220) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_471a8708c1846d9a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'What kind of energy is stored in a dry cell?', '{"A":"Solar","B":"Chemical","C":"Electrical","D":"Mechanical","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Chemical energy is stored in a dry cell.A dry cell is a device that converts chemical energy into electrical energy.Chemical energy is the energy stored in the bonds of atoms and molecules.', 0, 0, 0, 1790968060220) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cc67c4553bc3f809', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Overdose of vitamin _______ causes Kidney Disease?', '{"A":"C","B":"A","C":"D","D":"B"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Vitamin D toxicity, also called hypervitaminosis D.It causes hypercalcemia and renal failure.Daily Vitamin D requirement is 200–600 IU.While skin produces up to 10,000 IU after full UV exposure.', 0, 0, 0, 1790968060220) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_600229827d4ce9f7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'A branch of medicine studying blood and its disorders is called _____?', '{"A":"Dermatology","B":"Haematology","C":"Pathology","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Agrostology: Study of Grasses Agronomy: Soil management and crop production Odontology: Study of teeth Arthrology: Study of joints Nephrology: Study of kidneysHematology: Study of blood', 0, 0, 0, 1790968060220) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_93c30dff4bf651a2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Organic compound poured directly into the blood and transported to targeted tissue are _____?', '{"A":"Hormones","B":"Protiens","C":"Glocouse","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hormones are organic compounds secreted by glands directly into the bloodstream.They travel to target tissues to regulate physiological functions and maintain homeostasis.', 0, 0, 0, 1790968060247) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_01cb54fb216d261b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Kidney stones was formed by which element?', '{"A":"Calcium","B":"Calcium oxalate","C":"Potassium","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Calcium oxalate is the most common compound found in kidney stones.It forms when excess calcium and oxalate in the urine combine, creating hard crystals that can grow into stones.', 0, 0, 0, 1790968060247) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4950dcbe2a469c1a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Average male brain weights ______ ounces.', '{"A":"49","B":"44","C":"46","D":"51"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Weight of the adult men brain =49 ouncesSo, 49 ounces=4916 pounds=3.0625 poundsTherefore, the weight in pounds is 3.0625.', 0, 0, 0, 1790968060247) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bd38f5b7bd46d8c1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Vitreous Humor, Sclera and Iris are the part of which human organ?', '{"A":"Ear","B":"Eye","C":"Liver","D":"Brain"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The vitreous humor, sclera, and iris are all parts of the eye.The vitreous humor is a clear gel that fills the space between the lens and the retina.The sclera is the white outer layer of the eye.The iris is the colored part that controls the size of the pupil.', 0, 0, 0, 1790968060247) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_871b5591f39a8ed1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The Red Blood cells originate in the?', '{"A":"Spleen","B":"Liver","C":"Bone Marrow","D":"Heart","E":"Kidney"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Blood cells are made in the bone marrow.The bone marrow is the soft, spongy material in the center of the bones.It produces about 95% of the body''s blood cells.', 0, 0, 0, 1790968060247) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4d300b1094170fcc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Deficiency of which vitamin affects bones?', '{"A":"vitamin B","B":"vitamin C","C":"vitamin D","D":"vitamin K"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Rickets is a disorder that causes children to have bones that are weak and soft.Rickets is caused by a lack of vitamin D in the bodyND2-08-2023', 0, 0, 0, 1790968060247) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ea42ef381f9d18b0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'What is the weight of the average human brain?', '{"A":"1.9 kg","B":"1.4 kg","C":"2.3 kg","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The human brain weighs approximately about 1.4 kilograms or 1400 in gramand makes up about 2% of the human body weight.The brain is divided into three regions -Forebrain,midbrain, hindbrain.', 0, 0, 0, 1790968060247) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b63ab28af3777be3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The Human brain is __________ of body weight?', '{"A":"2%","B":"4%","C":"5%","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The human brain weighs approximately about 1.4 kilograms or 1400 in gramand makes up about 2% of the human body weight. The brain is divided into three regions - Forebrain, midbrain, hindbrain.', 0, 0, 0, 1790968060247) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1e158ca8ff0dbd63', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which one is not a vestigial organ of human being?', '{"A":"Appendix","B":"Eye lid","C":"Coccyx","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Vestigial organs are organs, tissues or cells in a body Which are no more functional the way they were in their ancestral form of the trait.', 0, 0, 0, 1790968060280) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f1f74464ad661e07', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Insects breathe through which organ?', '{"A":"Gills","B":"Spiracles","C":"Nostril","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Instead of nostrils, insects breathe through openings in the thorax and abdomen called spiracles. Insects that are diapausing or non-mobile have low metabolic rates and need to take in less oxygen. Insects exchange oxygen and carbon dioxide through spiracles (noted by circle)', 0, 0, 0, 1790968060280) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7ad28804ebe5acc8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which thing the brain demands the most?', '{"A":"Glucose","B":"Lactose","C":"Proteins","D":"Vitamins"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Glucose, a form of sugar, is the primary source of energy for every cell in the body. Because the brain is so rich in nerve cells, or neurons, it is the most energy-demanding organ, using one-half of all the sugar energy in the body.', 0, 0, 0, 1790968060280) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_01bac41fb75f4490', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The procedure of shattering the gallstones and kidney stones by shock waves, is called?', '{"A":"MRI","B":"Kidney surgery","C":"Angiography","D":"Lithotripsy"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lithotripsy uses sound wave to breakup large kidney stones into smaller pieces.Lithotripsy is a procedure involving the physical destruction of hardened masses like kidney stones, bezoars or gallstones, which may be done non invasively. The term is derived from the Greek words meaning "breaking stones".', 0, 0, 0, 1790968060280) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8616344b77affacf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Increased level of SGOT/AST in blood is an indication of ______?', '{"A":"Hepatitis","B":"Anemia","C":"Tuberculosis","D":"Myocardial infarction"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation SGOT (Serum Glutamic-Oxaloacetic Transaminase) and AST (Aspartate Transaminase) are enzymes found in the liver.Elevated levels of SGOT/AST in the blood indicate liver damage or inflammation, which can be a sign of:Hepatitis (liver inflammation)Liver cirrhosisLiver cancerLiver damage due to drugs or toxins', 0, 0, 0, 1790968060280) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ec394a390aaa7aee', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'A gene is a _____?', '{"A":"Type of body cell","B":"Sleep inducing drug","C":"Unit of heredity","D":"Kind of vitamin"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A gene is a segment of DNA that carries the genetic instructions used in the growth, development, and reproduction of organisms.It is the fundamental unit of heredity.', 0, 0, 0, 1790968060280) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5692b828dd99a2d9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Bile is manufactured and stored by which organ?', '{"A":"Stomach","B":"Pancreas","C":"Liver","D":"Gallbladder"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bile is produced by the liver and stored in the gallbladder. It is important for the digestion and absorption of fats in the small intestine.', 0, 0, 0, 1790968060280) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_43db2b50f2b759fa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The organ affected by Malaria is _____?', '{"A":"Spleen","B":"Kidney","C":"Lungs","D":"Heart","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mosquito causes Malaria which affects Spleen.Malaria is caused by Plasmodium parasites.Spleen means تلی******ND30-12-2022', 0, 0, 0, 1790968060280) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_223d27234355938c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'There are almost _______ of nephrons in each kidney in human body?', '{"A":"1000000","B":"5000000","C":"7000000","D":"6000000"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Each kidney contains around 1 million nephrons.They are the functional units responsible for filtering blood and producing urine.', 0, 0, 0, 1790968060316) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b1a69c5098cdad11', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'What percentage of plasma is composed of water?', '{"A":"70%","B":"80%","C":"90%","D":"92%"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Plasma contains 91% to 92% of water and 8% to 9% of solids. It mainly comprises of: Coagulants, mainly fibrinogen, aid in blood clotting. Plasma proteins, such as albumin and globulinThat help maintain the colloidal osmotic pressure at about 25 mmHg.', 0, 0, 0, 1790968060316) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5255d3de62e56d20', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The seat of memory in the human brain is located in the ____?', '{"A":"Cerebrum","B":"Cortex","C":"Cerebellum","D":"All of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The seat of memory in the human brain is located in the cerebrum.The cerebrum, particularly the hippocampus within it, plays a crucial role in memory formation and storage.', 0, 0, 0, 1790968060316) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_baa054521d1445df', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The electricity from a cell is called?', '{"A":"Direct Current (DC)","B":"Alternating Current (AC)","C":"Electric Potential (EP)","D":"Electric Resistance (ER)"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The electricity from a cell (such as a battery) is Direct Current (DC).It is the flow of electric charge in one direction only, without changing direction.This is the type of current used in electronic devices such as smartphones, laptops, and televisions.', 0, 0, 0, 1790968060316) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9e516dc96b611044', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'In case of muscles fatigue, which of the following vitamin should be taken?', '{"A":"Vitamin A","B":"Vitamin D","C":"Vitamin C","D":"Vitamin B"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The B vitamins, particularly B1 (thiamine), B2 (riboflavin), B3 (niacin), B6 (pyridoxine), and B12 (cobalamin),It plays an essential role in energy metabolism and muscle function. They help convert carbohydrates, fats, and proteins into energy That the muscles can use during physical activity.', 0, 0, 0, 1790968060316) ON CONFLICT(id) DO NOTHING;
