INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2ac91e9c08fa0787', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The lungs receive deoxygenated blood from heart through ____?', '{"A":"Renal artery","B":"Branchial artery","C":"Pulmonary artery","D":"Pulmonary vein"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The de-oxygenated blood from the heart comes to the lungs through the Pulmonary artery***The deoxygenated blood returns from the body to the right atrium and from there enter the right ventricle that pumps it to the lungs through the main pulmonary artery (pulmonary trunk).****The pulmonary veins transport oxygenated blood back to the heart from the lungs', 0, 0, 0, 1790968060371) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ac1f2234cde4fab3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Does heterozygous sickle cell anemia give protection against______________?', '{"A":"Malaria","B":"G6PD","C":"Thalassemia","D":"Dengue fever"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation heterozygous sickle cell anemia gives protection against malaria**Heterozygotes are therefore more resistant to the debilitating effects of malaria than the normal homozygotes.sickle cells are also resistant to malaria. Heterozygotes are resistant to malaria because of their recessive allele, but they lack sickle cell disease because of their dominant allele*****', 0, 0, 0, 1790968060371) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2a55796f89a63540', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'which of the following vitamin is produced in human body with the help of Sunlight.?', '{"A":"B","B":"C","C":"D","D":"E"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation During exposure to sunlight 7-dehydrocholesterol in the skin absorbs UV B radiation and is converted to previtamin D3 which in turn isomerizes into vitamin D3.agm 15.3.2023', 0, 0, 0, 1790968060371) ON CONFLICT(id) DO NOTHING;
