INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ae3192b98664c7bb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Third most abundant element in the Sun is:', '{"A":"Hydrogen","B":"Helium","C":"Oxygen","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hydrogen is the most abundant element in the Universe.Helium is second making up almost all of the remaining 25%. Oxygen is third most abundant element of universe.Hydrogen and helium are by far the most abundant elements found in the Sun, making up about 98 percent of its mass.*********FIA VU ASSISTANT 02-01-2022', 0, 0, 0, 1790968061046) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4a2641b2ed267709', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The inferred radiation by sun are strongly absorbed by........', '{"A":"Carbon dioxide","B":"Water","C":"Carbon dioxide and Water vapor","D":"Ozone"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Infrared radiation is strongly absorbed by water and by the atmosphere. Although invisible to the eye, infrared radiation can be detected as warmth by the skin. Nearly 50 percent of the Sun''s radiant energy is emitted in the infrared region of the electromagnetic spectrum, with the rest primarily in the visible region.', 0, 0, 0, 1790968061046) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_16b4bb98216d6501', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Largest galaxy in Universe is:', '{"A":"Andromeda Galaxy","B":"Milky way","C":"Spiral Galaxy","D":"Horseshoe Galaxy"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Spiral galaxies form a class of galaxy originally described by Edwin Hubble in his 1936 work The Realm of the Nebulae and, as such, form part of the Hubble sequence.', 0, 0, 0, 1790968061046) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4cbce894107e8db9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The biggest planet is', '{"A":"Venus","B":"Mars","C":"Mercury","D":"Jupiter"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jupiter is the biggest planetIt is the largest planet in the Solar System according to size.Saturn is the second largest planet in our solar system.Mercury Planet has the smallest diameterMoon One is not a planetVenus planet has no moonSaturn planet has the highest number of moonsMars is sometimes called the Red Planet.**These are the 8 planets1. Mercury2. Venus3. Earth4. Mars5. Jupiter6. Saturn7. Uranus8. Neptune', 0, 0, 0, 1790968061072) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_851da448e0123a27', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Ultraviolet Rays coming from the sun are filtered by:', '{"A":"Carbon Dioxide","B":"Ozone Layer","C":"Helium","D":"None of these","E":"All of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The ultraviolent rays are filtered through Ozone Layer.The ozone layer, often known as the ozone shield is a part of the Stratosphere.ND12_8_2023', 0, 0, 0, 1790968061072) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_235f7374b9501f65', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The age of Solar System is:', '{"A":"4.5 billion years","B":"5.5 billion years","C":"6.5 billion years","D":"7.5 billion years","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The solar system is a system constrained by the gravity of the sun and the objects that orbit it. The solar system was formed 4.6 billion years ago by the gravitational collapse of a huge interstellar molecule cloud.', 0, 0, 0, 1790968061072) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f7719361b7ad5541', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'An eclipse of the sun occurs when', '{"A":"The earth is between the sun and the Moon","B":"The sun is between the earth and the Moon","C":"The moon is between the sun and the Earth","D":"The earth casts its shadow on the moon","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation CA total solar eclipse occurs when the Moon is exactly positioned between the Sun and the Earth and the Earth passes through the Moon''s shadow. Solar eclipses can only happen during the day and at the time of a new Moon. Total solar eclipses last for only a few minutes.while on the other hand During a lunar eclipse, Earth comes between the Sun and the Moon, blocking the sunlight falling on the Moon. There are two kinds of lunar eclipses: A total lunar eclipse occurs when the Moon and Sun are on opposite sides of Earth.', 0, 0, 0, 1790968061072) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f6411315aa329666', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The time taken to complete one revolution of Earth around the Sun is called?', '{"A":"A month","B":"A day","C":"A year","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sun Light takes 500 seconds (8 minutes 19 seconds) to reach from the surface of the sun to the surface of the Earth.Moonlight takes about 1.3 seconds to reach the earth''s surface.The time taken to complete one revolution of Earth around the Sun is called A year.Earth is closer to the sun and revolves around it in about 365 days.Sun is a Star.', 0, 0, 0, 1790968061072) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6bd8cc53905cdf9e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The theory that refers to an explosion about 15 billion years ago, which most astronomers believe to be the origin of the Universe, is called:', '{"A":"The Red Shift Theory","B":"Relativity Theory","C":"Big Bang Theory","D":"Titanic Theory"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The theory describing the universe''s beginning with a rapid expansion from a hot, dense state is known as the Big Bang theoryis an American television sitcom created by Chuck Lorre and Bill Prady for CBS. It aired from September 24, 2007, to May 16, 2019', 0, 0, 0, 1790968061072) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7b9828a4b153ae3a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The earth revolves around the sun at a speed of', '{"A":"18.5 km/sec","B":"26.6 km/sec","C":"29 km/sec","D":"31.9 km/sec"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Earth revolves in orbit around the sun in one year, 6 hours, nine mins on the subject of the stars, at a velocity starting from 29.29 to 30.29 km/s. The 6 hours, 9 mins adds as much as approximately an extra day each fourth year, that''s particular a leap year, with the more day brought as February twenty ninth. Earth''s orbit is elliptical and reaches its closest method to the sun, a perihelion of 147,090,000 km, on approximately January fourth of each yr. Aphelion comes six months later at 152,100,000 km.', 0, 0, 0, 1790968061072) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_500082d44d1912d1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'What is the rank of the earth in the solar system in terms of size?', '{"A":"Third","B":"Fourth","C":"Fifth","D":"Sixth"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Earth is ranked fifth of eight by using length. however all of them are effortlessly dwarfed by way of any of the four gasoline giants (Jupiter, Saturn, Uranus and Neptune).', 0, 0, 0, 1790968061072) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a862936b85c67f7d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'These are cooler areas which move about on the sun''s surface and show up as dark spots', '{"A":"Red-spots","B":"Blue-spots","C":"Green-spots","D":"Sun-spots"}', 'D', NULL, 0, 0, 0, 1790968061092) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c0d295fd680a82f0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The sun derives its energy from', '{"A":"Nuclear fusion reactions","B":"Oxidation of helium","C":"Nuclear fission reactions","D":"Fission of noble metals"}', 'A', NULL, 0, 0, 0, 1790968061092) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_32eea986b79e5b70', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'NASA scientist have recently detected water vapour on which Jupiter''s moon?', '{"A":"Callisto","B":"Europa","C":"Lo","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Scientists at NASA have detected water vapour for the first time above the surface of Europa, a finding that supports the idea of a liquid water ocean sloshing beneath the miles-thick ice shell of the Jupiter''s moon.', 0, 0, 0, 1790968061092) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a25705d3d1c89d3d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Sun spots was discovered by___?', '{"A":"Newton","B":"Chadwick","C":"Galileo","D":"Alberoni"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sunspots were first observed telescopically in late 1610 by Thomas Harriot and Italian polymath Galileo GalileiSunspots are dark areas on the Sun’s surface caused by lower temperatures and strong magnetic activity.', 0, 0, 0, 1790968061092) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b425e2c467ec5872', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Sun consist of 70% ------', '{"A":"Hydrogen","B":"helium","C":"oxygen","D":"none"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Sun is a huge, glowing sphere of hot gas. Most of this gas is hydrogen (about 70%) and helium (about 28%). Carbon, nitrogen and oxygen make up 1.5% and the other 0.5% is made up of small amounts of many other elements such as neon, iron, silicon, magnesium and sulfur.', 0, 0, 0, 1790968061092) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8291b6ca3e652c55', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The father of Rocketry specially Saturn V Rocket which make successful moon landing was:', '{"A":"Dr. william Hale","B":"Hans Kammler","C":"Robert","D":"Dr Warner Von Braun"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Braun was a German-born American aerospace engineer and space architect.', 0, 0, 0, 1790968061092) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_be027abe13b8746c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The first American Astronaut to go into space was:', '{"A":"Walter Schiera","B":"John Glenn","C":"Neil Armstrong","D":"Allen Shepherd"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Allen Shepherd became the first American to travel into space in 1961, and in 1971, he walked on the Moon.', 0, 0, 0, 1790968061092) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9f7ff5b131d88964', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The phenomena in which the moon is seam to be big is known as:', '{"A":"Gibbous moon","B":"Waning moon","C":"Waxing moon","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation gibbous moon is the phase of the moon in which its illuminated part is greater than a semicircle and less than a circle.', 0, 0, 0, 1790968061092) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d6dad8e8e9fbf7b5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The radiant energy of the sun is transmitted in the form of ________', '{"A":"Short waves","B":"Long waves","C":"Particles","D":"None of these","E":"All of theese"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Radiant energy is the energy of electromagnetic waves. It is a form of energy that can travel through space. For example, we receive the heat from the sun, which is located very far from the earth via radiation. The sun''s heat is not transmitted through any solid medium, but through a vacuum. They are short waves.', 0, 0, 0, 1790968061112) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5949a263b0895329', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Total number of moons in the entire Solar System are:', '{"A":"More than 100","B":"More than 200","C":"More than 300","D":"More than 400"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Moon is Earth''s only natural satellite and the fifth largest moon in the solar system. \The Moon''s presence helps stabilize our planet''s wobble, which helps stabilize our climate', 0, 0, 0, 1790968061112) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a043cfa4bb027479', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'LIfe is absent on moon due to the lake of:', '{"A":"Carbon","B":"Hydrogen","C":"Water","D":"Nitrogen","E":"All"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There is no life on the moon because of several things. The absence of liquid water, atmosphere at a tolerable pressure and lack of tolerable temperature range', 0, 0, 0, 1790968061112) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_594196240f97cc6d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Icy bodies around the Sun are:', '{"A":"Comets","B":"Astride","C":"Plant","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Comets are cosmic snowballs of frozen gases, rock and dust that orbit the Sun. When a comet''s orbit brings it close to the Sun, it heats up and spews dust and gases into a giant glowing head larger than most planets.', 0, 0, 0, 1790968061112) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0b99a65506d8aedd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Huge cloud of gass and dust in the universe is called?', '{"A":"Nebula","B":"Meteorite","C":"Satellite","D":"Constellation"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Gigantic clouds of dust and gas in space are called nebulaePrimarily hydrogen and helium, plus dust (silicates, carbon, ice). Occupying the space between stars and acting as a nursery for new stars', 0, 0, 0, 1790968061112) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3de78ff7e879a2d2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Which layer protects earth from harmful rays of the Sun?', '{"A":"Ionosphere","B":"Ozone layer","C":"Troposphere","D":"Magnetosphere","E":"none of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The ozone layer protects the Earth against most UVB coming from the sun.', 0, 0, 0, 1790968061112) ON CONFLICT(id) DO NOTHING;
INSERT INTO subject (id, user_id, name, parent_id, total_mcqs, created_at) VALUES ('top_eds_health', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'Health & Medicine', 'top_everyday_science', 87, 1790968061132) ON CONFLICT(id) DO UPDATE SET total_mcqs = 87;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b8dfd7f29297637f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Who discover Penicillin?', '{"A":"Alexander Fleming","B":"Louis Pasteur","C":"Edward Jenner","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Discoverer: Alexander FlemingYear of discovery: 1928Place: St. Mary''s Hospital, LondonFirst patient treated with penicillin: Albert AlexanderDate of first treatment: 12 February 1941Last verified on 14-09-2026', 0, 0, 0, 1790968061150) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9e20c2ccab69bfe5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Myopia is a disease related to _____?', '{"A":"Stomach","B":"Liver","C":"Eye","D":"Neck"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Myopia (Nearsightedness) is an eye defect in which near objects are clear but distant objects appear blurred.It occurs when the image forms in front of the retina instead of on it.It is corrected by using a concave (diverging) lens.The concave lens helps to shift the image back onto the retina.Last verified on 01-04-2026', 0, 0, 0, 1790968061150) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0297df1051e59b54', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Who invented antibiotic medicine?', '{"A":"Michal Faraday","B":"Louis Posteur","C":"Alexander Flaming","D":"John Loannids"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Penicillin, the first true antibiotic, was discovered by Alexander Fleming.He made this discovery in 1928 at St. Mary’s Hospital, London.He found that a mould (Penicillium) killed bacteria in culture dishes.His findings were officially published in 1929.First patient treated: Albert Alexander (12 February 1941)Last verified on 01-06-2026', 0, 0, 0, 1790968061150) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ebbb6fe2f573a22d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'What is Albuminurophobia (Albumin Phobia) a fear of?', '{"A":"Fear of blood","B":"Fear of kidney disease","C":"Fear of water","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Albuminurophobia is a fear of kidney disease.The term is associated with an excessive or irrational fear of developing kidney disease.Albuminuria refers to the presence of albumin (a protein) in urine.The term is related to concerns about kidney health and disease.Last verified on 22-08-2026', 0, 0, 0, 1790968061150) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e2ff6259cc78f9f5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'The cause of malaria is _____?', '{"A":"Bacteria","B":"Virus","C":"Plasmodium","D":"Fungus"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Malaria is caused by the parasite Plasmodium.It is transmitted to humans through the bite of an infected female Anopheles mosquito.Malaria is a parasitic disease.It mainly affects the liver and red blood cells.Common symptoms include fever, chills, headache, and sweating.Last verified on 11-07-2026', 0, 0, 0, 1790968061150) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9c6d6e6fb9e20852', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Jaundice (hepatitis) is a disease of _____?', '{"A":"Liver","B":"Spleen","C":"Kidney","D":"Lungs"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jaundice is a condition characterized by yellowing of the skin and eyes.It is caused by excess bilirubin due to liver dysfunction or disease.Last verified on 01-04-2026', 0, 0, 0, 1790968061150) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1b33abc194b9cf59', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Necrophobia is a fear of ______?', '{"A":"Death","B":"Everything","C":"Wealth","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Necrophobia is the abnormal fear of death or dead bodies.It is a type of specific phobia related to mortality.Affected individuals feel extreme anxiety when thinking about death.It may also include fear of corpses or funerals.It is a psychological anxiety disorder.Last verified on 10-06-2026', 0, 0, 0, 1790968061150) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6ee0132def71ccf3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Of the following disease, the one caused by a worm is?', '{"A":"Sickle-cell anemia","B":"Klinefelter''s syndrome","C":"Ringworm","D":"Treichinosis"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Trichinosis is a disease caused by a parasitic worm.It is caused by Trichinella spiralis.It spreads through undercooked or infected meat.It affects muscles and digestive system in humans.Last verified on 04-06-2026', 0, 0, 0, 1790968061150) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_91c08f0fab8e8544', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Who developed the polio Vaccine?', '{"A":"Richard Gatling","B":"Joseph Priesty","C":"Jonas Edward Salk","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Polio Vaccines: Developed to prevent poliomyelitis, a viral disease causing paralysis.Jonas Salk (US, 1950s): Created the first inactivated (killed) polio vaccine; tested on himself and family in 1953; officially used in 1955.Albert Sabin (1961): Developed the live attenuated (weakened) oral polio vaccine.Recent Campaigns: Israel launched a polio vaccine drive in April 2022 after 1988 efforts.Last verified on 03-04-2026', 0, 0, 0, 1790968061166) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_119851ce4fb2eb4b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Fear of enclosed spaces is called?', '{"A":"Claustrophobia","B":"Philanthropy","C":"Both A and B","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Claustrophobia is the fear of enclosed or confined spaces.It is classified as an anxiety disorder.People with claustrophobia may panic in elevators, small rooms, or windowless spaces.Symptoms include shortness of breath, sweating, rapid heartbeat, and anxiety.Last verified on 02-04-2026', 0, 0, 0, 1790968061166) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_37b2854fe63576ae', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Which disease causes difficulty in breathing? Asthma, Anemia, Astigmatism, Autism', '{"A":"Asthma","B":"Anemia","C":"Astigmatism","D":"Autism"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Asthma is a chronic respiratory disease affecting the airways of the lungs.It causes narrowing and inflammation of the air passages, leading to difficulty in breathing.Common symptoms include wheezing, coughing, chest tightness, and shortness of breath.Last verified on 02-04-2026', 0, 0, 0, 1790968061166) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e7e9235c2fbd275c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Which of the following is not caused by virus? Typhoid, Choler, Flu, Jaundice, Both A and B', '{"A":"Typhoid","B":"Choler","C":"Flu","D":"Jaundice","E":"Both A and B"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Diseases can be caused by bacteria, viruses, or other pathogens.Flu (Influenza) and Jaundice (Hepatitis A, B, or C) are caused by viruses.Typhoid and Cholera are caused by bacteria.Therefore, Typhoid and Cholera are not viral diseases.Last verified on 31-03-2026', 0, 0, 0, 1790968061166) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d6a74e0525771e3c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Bacteria increase in number asexually by _____?', '{"A":"Binary fission","B":"Mitosis","C":"Conjugation","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bacteria reproduce asexually mainly by binary fission, where one cell splits into two identical cells.This is a rapid process, allowing bacteria to multiply quickly under favorable conditions.Last verified on 12-02-2026', 0, 0, 0, 1790968061166) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_115240beac89882e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'The process of ________ is accomplished by Rhizobium bacteria?', '{"A":"Nitrogen fixation","B":"Ammonification","C":"Denitrification","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Rhizobium bacteria live in root nodules of leguminous plants (e.g., peas, beans).They convert atmospheric nitrogen (N₂) into ammonia (NH₃), a usable form for plants.This process is called nitrogen fixation.It enriches soil fertility naturally.Essential for plant growth and agriculture.Last verified on 12-01-2026', 0, 0, 0, 1790968061166) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9af89138bef85513', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Germ theory of disease is given by ____?', '{"A":"Louis Pasteur","B":"Ronald Ross","C":"John Snow","D":"Robert Cock"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Germ Theory of Disease states that microorganisms (germs) cause diseases.Proposed by Louis Pasteur (1822–1895), a French scientist.This theory revolutionized medicine, leading to vaccines and sterilization methods.Additional information:Robert Koch later developed techniques to identify specific germs for specific diseases.Last verified on 29-01-2026', 0, 0, 0, 1790968061166) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ebb90f8c20259639', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'The bacteria which convert nitrite (NO₂⁻) to nitrate (NO₃⁻) is _____?', '{"A":"Rhizobium","B":"Azotobacter","C":"Nitrobacter","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nitrobacter bacteria convert nitrite (NO₂⁻) into nitrate (NO₃⁻) in the soil.This is the second step of the nitrification process, which is important for plant nutrition.Nitrite is toxic to plants, but nitrate is easily absorbed as a nutrient.Last verified on 22-01-2026', 0, 0, 0, 1790968061166) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f0e84c88b7a553e2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'The complete, mature & infectious particle of virus is known as?', '{"A":"Prion","B":"Envelope","C":"Capsomere","D":"Virion"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A virion is the fully developed, infectious form of a virus capable of infecting a host.It contains genetic material (DNA or RNA) and a protein coat (capsid), sometimes with an envelope.Additional information:Capsomere: Protein subunit of the capsid.Envelope: Lipid layer around some viruses.Prion: Infectious protein.Last verified on 19-01-2026', 0, 0, 0, 1790968061190) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f7a833cb6ff1b4f1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'The disease Diphtheria affects which part of human body?', '{"A":"Lungs","B":"Intestines","C":"Throat","D":"Joints"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Diphtheria primarily affects the nose, throat, and tonsils,Forming a thick gray coating (pseudomembrane) that blocks airwaysTonsils & Larynx (Voice Box): These areas are also commonly affected.', 0, 0, 0, 1790968061190) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5b7fccf022253257', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Who discover the Vaccine?', '{"A":"Edward Jenner","B":"Alexander Fleming","C":"J. J. Thomson","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Scientist: Edward JennerDiscovery Year: 1796Vaccine Type: SmallpoxSignificance: First ever successful preventive vaccineExtra Fact: Smallpox was declared eradicated in 1980 by WHOAdditional information:Edward Jenner is often called the “Father of Immunology.”Last verified on 16-01-2026', 0, 0, 0, 1790968061190) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_458ffb78be3e7af6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Cirrhosis is a disease that affects _____?', '{"A":"Lungs","B":"Liver","C":"Brain","D":"Heart"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cirrhosis is a chronic disease of the liver.Additional information:Nature of Disease: Chronic and progressiveMain Causes: Hepatitis B & C, alcohol abuse, fatty liver diseaseEffect: Scarring (fibrosis) reduces liver efficiencyLast verified on 16-01-2026', 0, 0, 0, 1790968061190) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c29fa91e0416cee2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Which disease is hereditary? Tuberculosis, Hemophilia, Malaria, Cholera', '{"A":"Tuberculosis","B":"Hemophilia","C":"Malaria","D":"Cholera"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hemophilia is a genetic blood disorder passed from parents to offspring.It causes failure of normal blood clotting, leading to excessive bleeding.', 0, 0, 0, 1790968061190) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7748340fea8d6530', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Hepatitis is a disease of _______?', '{"A":"Lungs","B":"Brain","C":"Heart","D":"Liver","E":"Bones"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation جب کوئی انسان جگر میں سوجن کا شکار ہوجائے تو اس بیماری کو ہیپاٹیٹس کہا جاتا ہے۔One person in every 30 seconds die due to Hepatitis in the world.World Health Organization (WHO) set a target to eliminate Hepatitis by 2030.Hepatitis is a disease of liver.', 0, 0, 0, 1790968061190) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ff5fc68a2eefc778', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Alzheimer''s disease is characterized by ______?', '{"A":"Kidney failure","B":"Bone density reduction","C":"Neuro degeneration","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Alzheimer''s disease is a progressive brain disorder marked by the degeneration of neurons.It leads to memory loss, cognitive decline, and behavioral changes.', 0, 0, 0, 1790968061190) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_041c91d2e9ea3794', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'The medical doctor who is specialist of eye sight is ______?', '{"A":"Orthodontist","B":"Orthopedist","C":"Ophthalmologist (Oculist)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ophthalmologist means a specialist in the branch of medicine concerned with the study and treatment of disorders and diseases of the eye.Ophthalmologist means ماہر امراض چشم', 0, 0, 0, 1790968061190) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_36eb53e292715c40', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Thalassemia is a hereditary disease affecting which of the following?', '{"A":"Lung","B":"Blood","C":"Kidney","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Thalassemia is a genetic blood disorder caused by an abnormality in hemoglobin production.It leads to reduced oxygen-carrying capacity of red blood cells.', 0, 0, 0, 1790968061228) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_640798540115a849', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Hydrophobia is a symptom of which of following diseases?', '{"A":"Malaria","B":"Cholera","C":"AIDS","D":"Rabies"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hydrophobia, or fear of water, is a well-known symptom of rabies.A viral disease that affects the central nervous system.', 0, 0, 0, 1790968061228) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3c182e79b1d9da6f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Which mineral’s deficiency can cause painful joints, osteoporosis, memory loss and diabetes?', '{"A":"Magnesium","B":"Calcium","C":"Sodium","D":"Iodine"}', 'A', NULL, 0, 0, 0, 1790968061228) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_53119288f696dbe5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'The deficiency of Anemia is caused by ______?', '{"A":"Iron","B":"Zinc","C":"Calcium","D":"Sodium"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Anemia can be caused by a deficiency of iron or vitamin B9 (folate).Iron deficiency impairs hemoglobin production.While vitamin B9 deficiency affects red blood cell formation.', 0, 0, 0, 1790968061228) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_34fe0bc9425a558e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Diabetes could be classified into___ types', '{"A":"Two","B":"Three","C":"Four","D":"Five"}', 'B', NULL, 0, 0, 0, 1790968061228) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7fdf05740f3da2bb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Which of the following is caused by bacteria?Malaria ,Tetanus ,Cancer , Rabies', '{"A":"Malaria","B":"Tetanus","C":"Cancer","D":"Rabies"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tetanus is caused by the bacterium Clostridium tetani. The other options are caused by different pathogens:Malaria is caused by a parasite (Plasmodium) transmitted through mosquito bites.Cancer is not caused by bacteria; it is a group of diseases involving abnormal cell growth.Rabies is caused by a virus (Rabies virus), not bacteria.', 0, 0, 0, 1790968061228) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d94fdee83748e50f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Polio vaccine was invented in ______?', '{"A":"UK","B":"USA","C":"Germany","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the early 1950s, the first successful vaccine was created by US physician Jonas Salk.Salk tested his experimental killed-virus vaccine on himself and his family in 1953First used Salk vaccine in 1955 ( in activated)while A live attenuated (weakened) oral polio vaccine developed by Dr. Albert Sabin and first used in 1961.Israel launched a polio vaccine drive after 1988 in April 2022.', 0, 0, 0, 1790968061228) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_466023943cf8bffe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Genetic material in virus is _____?', '{"A":"RNA only","B":"DNA only","C":"DNA or RNA","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Genetic Material in Viruses:Viruses can have either DNA or RNA as their genetic material, but never both in the same virus.Examples:DNA viruses: Herpesvirus, Smallpox.RNA viruses: HIV, Influenza, SARS-CoV-2.', 0, 0, 0, 1790968061228) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c67130f067158c3e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Which one of the following is/are not a bacterial disease? Influenza, Hepatitis and Poliomyelitis viral, TB (Tuberculosis), Typhoid and Pneumonia, Diarrhea', '{"A":"Influenza, Hepatitis and Poliomyelitis viral","B":"TB (Tuberculosis)","C":"Typhoid and Pneumonia","D":"Diarrhea"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Influenza is caused by the influenza virus, Poliomyelitis viral, and Hepatitis is caused by hepatitis viruses (A, B, C, etc.) — all three are viral diseases.The TB, Typhoid, Pneumonia, and some forms of Diarrhea — are primarily caused by bacteria.', 0, 0, 0, 1790968061261) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a0a90654b3fd32dd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Which is a non-viral disease? HIV/Aids, Measles ,Influenza ,Hypertension', '{"A":"HIV/Aids","B":"Measles","C":"Influenza","D":"Hypertension"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hypertension (high blood pressure) is a non-viral disease.Whereas HIV/Aids, Measles, and Influenza are all viral diseases.', 0, 0, 0, 1790968061261) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_749bdfc8a7280837', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Which of the following medicines is administered to patients suffering from diabetes?', '{"A":"Suggar","B":"Insulin","C":"Both A and B","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lack of insulin causes diabetes.Diabetes is a condition that happens when your blood sugar (glucose) is too high.It develops when your pancreas doesn''t make enough insulin.', 0, 0, 0, 1790968061261) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_35c814e05a6ba70f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Which immunoglobulin is primarily responsible for providing long-term immunity after a vaccination?', '{"A":"IgA","B":"IgG","C":"IgM","D":"IgE"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Immunoglobulin G (IgG) is the most abundant antibody in the human body. It plays a crucial role in long-term immunity by recognizing and neutralizing pathogens. IgG antibodies are produced after exposure to an antigen, such as a vaccine. They persist in the bloodstream for an extended period, allowing the body to respond to subsequent infections with the same pathogen quickly. IgG can also cross the placenta, providing passive immunity to newborns.', 0, 0, 0, 1790968061261) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2c05c85fc2b07885', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'All of the above are bacillus bacteria except? Pseudomonas, Clostridium, Salmonella, Streptococcus', '{"A":"Pseudomonas","B":"Clostridium","C":"Salmonella","D":"Streptococcus"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bacillus bacteria:These are rod-shaped, Gram-positive bacteria that can form endospores. Pseudomonas:These are Gram-negative bacteria, not bacilli. Clostridium:These are also Gram-positive bacteria, but they are anaerobic, unlike most Bacillus species. Salmonella:These are Gram-negative bacteria, not bacilli. Streptococcus:These are Gram-positive cocci (round bacteria), not bacilli.', 0, 0, 0, 1790968061261) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_385c8342f6368f31', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Which of the following causes tuberculosis and leprosy? Streptomyces, Actinomycetes, Mycoplasma, None of these', '{"A":"Streptomyces","B":"Actinomycetes","C":"Mycoplasma","D":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The bacteria that cause tuberculosis and leprosy are Mycobacterium tuberculosis and Mycobacterium leprae.So the correct answer is d) None of these', 0, 0, 0, 1790968061261) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_83c67b31dd35fe9e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'The shape of tobacco mosaic virus is _____?', '{"A":"Spiral","B":"Rod shaped","C":"Spherical","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tobacco mosaic virus (TMV) has a rod-like or cylindrical shape. It''s essentially a rigid, helical structure with a protein shell (capsid) surrounding a single-stranded RNA moleculeThe capsid is composed of protein subunits arranged in a helical structure.', 0, 0, 0, 1790968061261) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8df756d7b86c6353', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Cataract is the disease of ______?', '{"A":"Eye","B":"Ear","C":"Nervous system","D":"Brain"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A cataract is a clouding of the lens in the eye that affects vision.It is a common age-related condition that can cause blurry vision, double vision, and sensitivity to light.Cataracts can be treated with surgery to remove the cloudy lens and replace it with an artificial lens.', 0, 0, 0, 1790968061261) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dec199f5936e1030', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Malaria is caused by ________?', '{"A":"Bacterial infection","B":"Fungal bacteria","C":"Parasitic infection","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Malaria is caused by Plasmodium parasites.They are transmitted through the bite of infected female Anopheles mosquitoes.', 0, 0, 0, 1790968061290) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3505fe075ac40a8b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Which of the following diseases is caused by a virus?', '{"A":"Tuberculosis","B":"Malaria","C":"Smallpox","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Smallpox is caused by the variola virus.It was a contagious and deadly disease until it was eradicated globally through vaccination by 1980.', 0, 0, 0, 1790968061290) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4f8e90aeced16b9e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Which two organs are mainly affected by Malaria?', '{"A":"Lungs and Heart","B":"Kidneys and Lungs","C":"Heart and Brain","D":"Spleen and Liver"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Spleen and Liver are the two organs mainly affected by malaria.Malaria primarily targets the liver, where parasites multiply, and the spleen.It becomes enlarged due to the destruction of infected red blood cells.', 0, 0, 0, 1790968061290) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2da80098237a2a87', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Leukemia is a disease of the ______?', '{"A":"Lungs","B":"Blood","C":"Skin","D":"Nerves"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Leukemia is cancer of the body''s blood-forming tissues, including the bone marrow and the lymphatic system. Many types of leukemia exist. Some forms of leukemia are more common in children. Other forms of leukemia occur mostly in adults.', 0, 0, 0, 1790968061290) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b2997c04d083561b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Lack of ________ causes diabetes.', '{"A":"Sugar","B":"Insulin","C":"Calcium","D":"Vitamins"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lack of insulin causes diabetes.Diabetes is a condition that happens when your blood sugar (glucose) is too high. It develops when your pancreas doesn''t make enough insulin.', 0, 0, 0, 1790968061290) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_21679eec086ff5c0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Who proved that micro-organisms could cause disease?', '{"A":"Louis Pasteur","B":"A.V. Leeuwenhoek","C":"Robert Kock","D":"Robert Hooke"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Robert Koch established the germ theory of disease by demonstrating a causal relationship.Between specific microorganisms and particular diseases, most notably with his research on anthrax.', 0, 0, 0, 1790968061290) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5319d1a179effa99', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Dialysis is a medical treatment used for _____?', '{"A":"Respiratory Failure","B":"Nervous Failure","C":"Renal Failure","D":"Liver Failure"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dialysis is a medical treatment used when the kidneys are unable to filter waste products from the blood, typically in renal (kidney) failure.It helps maintain proper fluid and electrolyte balance in the body.', 0, 0, 0, 1790968061290) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d0275142078edfa7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Which is the cause of malaria?', '{"A":"Blood Issues","B":"Dirty Water","C":"Dirty environment","D":"Mosquito","E":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Malaria is caused by Plasmodium parasites. The parasites are spread to people through the bites of infected female Anopheles mosquitoes, called "malaria vectors.', 0, 0, 0, 1790968061290) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c5b4bc5ba8504035', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Which part of human body is more prone to damage from the "Hepatitis Virus"?', '{"A":"Liver","B":"Spleen","C":"Lungs","D":"Kidneys"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The part of the human body more prone to damage from the Hepatitis Virus is the Liver.Hepatitis is an inflammation of the liver, caused by various hepatitis viruses (A, B, C, etc.).It can lead to liver damage, cirrhosis, or liver cancer.', 0, 0, 0, 1790968061333) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8b0d9005f9a30ec5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Trachoma is a disease of _____?', '{"A":"Ear","B":"Blood","C":"Eye","D":"Brain"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Trachoma is a disease of the eye It is caused by infection with the bacterium Chlamydia trachomatis. It is a public health problem in 38 countries and is responsible for the blindness or visual impairment of about 1.9 million people', 0, 0, 0, 1790968061333) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fa5e4f1696ca9391', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'AIDS virus destroys which system of the body?', '{"A":"Digestion","B":"Brain","C":"Immune","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation AIDS stands for Acquired Immunodeficiency Syndrome.It is caused by the HIV virus.The virus primarily attacks the immune system.This weakens the body''s defense against infections and diseases.', 0, 0, 0, 1790968061333) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e58b999cb87fa63e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Which of the following is a disease caused by drinking contaminated water?', '{"A":"Typhoid","B":"Cholera","C":"Malaria","D":"Both A and B"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Typhoid and Cholera are both waterborne diseases that can be caused by drinking contaminated water.Typhoid fever is a bacterial infection caused by Salmonella Typhi, which can be spread through contaminated food and water.Cholera is a diarrheal disease caused by Vibrio cholerae, which can be spread through contaminated food and water, as well as through person-to-person contact.', 0, 0, 0, 1790968061333) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_45519bf56d42c8e5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Pneumonia is an inflammation of the lungs as a result of bacteria named _____?', '{"A":"Streptococcus","B":"Filamentous","C":"Paramyxo","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pneumonia is often caused by Streptococcus pneumoniae.It is a type of bacteria that leads to lung inflammation and infection.It affecting breathing and oxygen intake.', 0, 0, 0, 1790968061333) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1167aeab4d1e3552', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Bronchitis is a disease related to _____?', '{"A":"Brain","B":"Stomach","C":"Respiratory tract","D":"Nervous system"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bronchitis is a disease related to the respiratory tract.It is characterized by inflammation of the bronchial tubes.It leads to coughing and breathing difficulties.Bronchitis is a condition that develops when the airways in the lungs.It usually happens because of a virus that irritates the lungs such as: tobacco smokefumesdustand air pollution', 0, 0, 0, 1790968061333) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2064e75353185f4e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'The overcome diabetes mellitus, a person can increase the intake of _____ and reduce the intake of ______?', '{"A":"Fats and carbohydrate","B":"Carbohydrate and protein","C":"Carbohydrate and fats","D":"Protein and fats"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Controlling diabetes often involves: reducing carbohydrate intake to manage blood sugar levels increasing intake of healthy fats to provide sustained energy and support overall health.This approach stabilizes blood glucose levels while promoting a balanced and nutritious diet.', 0, 0, 0, 1790968061333) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0e48584a3f5db6ca', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'A disease that is liable to be transmitted to the people by the environment is known as _____?', '{"A":"Contagious","B":"Fatal","C":"Infectious","D":"Incurable"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation identify the disease that is liable to be transmitted to the people by the environment is called infectious***Communicable diseases are caused by infectious agents that can be transmitted to other peopleAGM 02.05.2023', 0, 0, 0, 1790968061333) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2eac2206de8ad173', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Insomnia is a disease of ____?', '{"A":"Color blindness","B":"Inability to sleep","C":"Depression","D":"Hypertension"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Insomnia is a common sleep disorder. With insomnia, you may have trouble :falling asleep, staying asleep, or getting good quality sleep.', 0, 0, 0, 1790968061362) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_66735d228499fb86', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'In general, the Cancer in a human body is caused by changes to?', '{"A":"Virus","B":"RNA","C":"DNA","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Most gene mutations occur after you''re born and aren''t inherited. A number of forces can cause gene mutations, such as smoking, radiation, viruses, cancer-causing chemicals (carcinogens), obesity, hormones, chronic inflammation and a lack of exercise.', 0, 0, 0, 1790968061362) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_368bc18f7a621805', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'An Antibiotic is a drug used to treat infections caused by', '{"A":"Protein","B":"Virus","C":"Bacteria","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Antibiotics are medicines that fight infections caused by bacteria in humans and animals by either killing the bacteria or making it difficult for the bacteria to grow and multiply. Bacteria are germs', 0, 0, 0, 1790968061362) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_269b821b3de420ad', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Disease-causing microorganisms are referred to as', '{"A":"Coliform bacteria","B":"Viruses","C":"Pathogens","D":"All of these","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Infectious diseases are caused by pathogens.Pathogens of all classes must have mechanisms for entering their host and for evading immediate destruction by the host immune system.', 0, 0, 0, 1790968061362) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ef999a287d9717bf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Pertussis vaccine is commonly given in how many forms?', '{"A":"Three","B":"Four","C":"Two","D":"One"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pertussis vaccine is commonly given in the following two forms:1. Whole-cell vaccine 2. Acellular vaccine', 0, 0, 0, 1790968061362) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c250622284e77c41', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Which one of the following used combined viral vaccine?', '{"A":"HGIG","B":"VZIG","C":"VIG","D":"MMR"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation MMR has used a combined viral vaccine. MMR stands for measles, mumps, and rubellaMumps, like measles, is a disease caused by an RNA virus classified in the Paramyxoviridae family. Unlike measles, mumps belongs to the Rubulavirus genus. It is a human disease with no animal reservoirs.ND-18-8-2023', 0, 0, 0, 1790968061362) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c5e245e751ecab47', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'The killed vaccine used against polio virus has following features EXCEPT?', '{"A":"induce immunity","B":"interrrust transmission","C":"Induce humoral IgG","D":"Induce Intestinal IgA"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Salk vaccine IPV consists of inactivated (killed) poliovirus strains of all three poliovirus types', 0, 0, 0, 1790968061362) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2243e5f1155f26ec', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Malaria and Dengue are the diseases spread by what?', '{"A":"Bees","B":"Dragonflies","C":"Mosquitoes","D":"Moth files"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Malaria is caused by a female mosquito, Anopheles; while dengue is caused by Aedes aegypti mosquito.', 0, 0, 0, 1790968061362) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b6eacd6ef4f98abf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Study of Bacteria in Biology is called', '{"A":"Micro Biology","B":"Dermatology","C":"Hematology","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Microbiology is the scientific study of microorganisms, those being unicellular, multicellular, or acellular. Important GK Agrostology: Study of Grasses Agronomy: soil management and crop production Odontology: study of teeth Arthrology:Study of joints Nephrology: study of kidneysHematology: Study of blood Dermatology: Study of skin', 0, 0, 0, 1790968061393) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0b1e146d2feb709c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Disease Insomnia means', '{"A":"Hot fever","B":"Dental decay","C":"Sleeplessness","D":"Tiredness"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Insomnia is a sleep disorder in which we have trouble falling and/or staying asleep. Such as,In Insomnia Difficulty falling asleepIn Insomnia Difficulty staying asleepIn Insomnia Difficulty returning to asleep after walkingInsomnia نیند نہ آنے کی بیماری', 0, 0, 0, 1790968061393) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_165851021c2b89be', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'The bacterial disease is to:', '{"A":"Leprosy","B":"Chicken Pox","C":"Influenza","D":"Polio"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The bacterial disease is: Leprosy***Hansen''s disease also known as leprosyHansen''s disease is an infection caused by slow-growing bacteria called Mycobacterium leprae.It can affect the nerves, skin, eyes, and lining of the nose (nasal mucosa).****the Brucellosis bacterial disease has recently hit China affecting over 3000 peopleHepatitis is not a bacterial disease', 0, 0, 0, 1790968061393) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1d3c5174c41acff7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', '.AIDS virus has:', '{"A":"None of theseDouble-stranded DNA","B":"Single-stranded DNA","C":"Double-stranded RNA","D":"single-stranded RNA"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation HIV is a retrovirus, meaning that it carries single-stranded RNA as a genetic material rather than the double-stranded DNA carried by human cells.Aids way to spread is TouchAIDS stands for Acquired Immunodeficiency Syndrome.HIV stands for Human Immunodeficiency Virus.HIV attacks the immune system of the body AIDS virus has single-stranded RNAAIDS is not a genetic disorder', 0, 0, 0, 1790968061393) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_afe774fdf5fd1cd9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Because penicillin prevents peptidoglycan synthesis, it is more effective on ___________ cells.', '{"A":"Gram Positive","B":"Gram Negative","C":"Acid Fast","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Penicillin works best on gram-positive bacteria by inhibiting peptidoglycan production, making the cells leaky and fragileThe cells burst open and are much easier for the immune system to break down, which helps the sick person heal more quickly.**Related QuestionPenicillin was discovered by Alexander Flaming In 1928Penicillin was the first true antibioticND04-08-2023', 0, 0, 0, 1790968061393) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f12054c7090169fc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Why the hospital practices are monitored?', '{"A":"To determine whether established targets are met","B":"The higher administration has to compile data","C":"We have an auditing group that does it report to authorities","D":"administration wants to make sure all patients are treated the same"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The principal methods of measuring hospital performance are: regulatory inspectionpublic satisfaction surveys third-party assessmentand statistical indicators***ND1-2-2023', 0, 0, 0, 1790968061393) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_eb4a5059352c5fe5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'A well was present in a rural area where an unsanitary bore-hole latrine with lots of flies was present within 10 feet of distance. The disease more likely to be transmitted through drinking this well water will be:', '{"A":"Dental caries","B":"Typhoid","C":"ancylostomiasis","D":"Leishmaniasis","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A ( borehole latrine) pit latrine, also known as a pit toilet, is a type of toilet that collects human feces in a hole in the ground.***typhoid fever can be contracted including: using a toilet contaminated with bacteria and touching your mouth before washing your hands.***Drinking such water is unsafe for our health***ND1-2-2023', 0, 0, 0, 1790968061393) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_38049076b2913776', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Who developed oral polio vaccine', '{"A":"Albert Sabin","B":"Edword Jenner","C":"Maurice Hileman","D":"Jonas Salk"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Albert Bruce Sabin was a Polish American medical researcher.Known for developing the oral polio vaccine which has played a key role in nearly eradicating the disease.', 0, 0, 0, 1790968061393) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ac3c30c16f2d2e12', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'A slippery outer covering in some bacteria that protects them from phagocytosis by host cells is:', '{"A":"Cell Wall","B":"Capsule","C":"Peptidoglycan","D":"Teichoic acid","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A slippery outer covering in some bacteria that protects them from phagocytosis by host cells is Capsule. Capsules can protect a bacterial cell from ingestion and destruction by white blood cellsCapsules confer resistance to phagocytosis.ND06-08-2023', 0, 0, 0, 1790968061425) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_af98176ebf22b999', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'the disease which spread in air ______?', '{"A":"Measles","B":"TB","C":"Both of these","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There are there following airborne diseases1. Measles 2. TB3. Chickenpox4. Influenza5. Pertussis (whooping cough) 6. Respiratory Syncytial Virus (RSV)*********FIA VU CONSTABLE PAST PAPER 2021', 0, 0, 0, 1790968061425) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fa50d60837d65a3d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Leukema is a disease of :', '{"A":"Lungs","B":"Blood","C":"Skin","D":"Nervwes"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Leukemia is a cancer of the blood and bone marrow.', 0, 0, 0, 1790968061425) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2e7af2bd6e6922ee', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'It is found recently that incidence of Malaria is increasing because', '{"A":"Of poor sanitary conditions","B":"with increase in population it has become impossible to mainatain cleanliness everywhere","C":"The mosquitoes have become DDT-resistance"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Answer::DA single gene mutation results in resistance to DDT and pyrethroids, a class of pesticides used in bed nets. According to a new study in the journal Geno Mosquitoes (Anopheles funestus), Geno Mosquitoes (Anopheles funestus) is a malaria vector, and most strategies for controlling disease epidemics focus on controlling mosquito populations with pesticides. I''m guessing. The spread of resistance genes can delay efforts to prevent disease.', 0, 0, 0, 1790968061425) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7e607baabd929c68', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'A virus can spread through:', '{"A":"Contaminated food or water","B":"Coughing","C":"Touch","D":"All","E":"None"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Virus is an ineffective agent that typically consists of a nucleic acid molecule in a protein coat, is too small to be seen by light microscopy, and is able to multiply only within the living cells of a host.', 0, 0, 0, 1790968061425) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_478346f2b5af2a5c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Foot and mouth disease is prevalent among', '{"A":"cattle and pigs only","B":"Sheep and cattle only","C":"cattle","D":"goats","E":"sheep and other hoofed animals"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Answer: DThe disease affects cattle, pigs, sheep, goats, and other ruminant ungulates. Intensively bred animals are more susceptible to disease than traditional breeds.', 0, 0, 0, 1790968061425) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_16e681e654eeaf3b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Pacemaker is a small device which control disease related to:', '{"A":"Ear","B":"Eye","C":"Throat","D":"Heart"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The heart is a muscular organ about the size of a fist, located just behind and slightly left of the breastbone. The heart pumps blood through the network of arteries and veins called the cardiovascular system.', 0, 0, 0, 1790968061425) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_84dee7633a8d47b9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Which of the following disease has posed a serious threat the world over', '{"A":"Paralytic stroke","B":"AIDS","C":"Tumour","D":"Tuberculosis"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Answer:BAIDS results from the disruption of the immune system caused by HIV infecting and destroying a special group of white blood cells called helpers for T4 cells. And with the collapse of the immune system, severe opportunistic infections. today, more than 1.2 million people are living with HIV in the U.S. and there are more than 35,000 new infections each year.', 0, 0, 0, 1790968061425) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c7ae88279186e762', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Presently a globally eliminated disease is:', '{"A":"Smallpox","B":"Chickenpox","C":"Leprosy","D":"Measles"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In 1980, the World Health Organization announced the global eradication of smallpox. It is the only human disease to be eradicated worldwide.', 0, 0, 0, 1790968061461) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8deba54e4bcac86e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'The disease caused by Dog bite is:', '{"A":"Rabies","B":"Alzheimer","C":"Parkinson","D":"Epilepsy"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Rabies is a deadly neurologic disease caused by a virus that spreads primarily through bites of infected animals.', 0, 0, 0, 1790968061461) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ab4b9e4863caf602', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'The study of cause origin and nature of disease is called :', '{"A":"Pathology","B":"Entomology","C":"Geology","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pathology is the study of the causes and effects of disease or injury.', 0, 0, 0, 1790968061461) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3ef34f017e675437', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Leukemia is a type of cancer in which there is an abnormal increase in number of:', '{"A":"Platelets","B":"Bone cells","C":"Red blood cells","D":"White blood cells"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation White blood cells, also called leukocytes are the cells of the immune system that are involved in protecting the body against both infectious disease and foreign invaders.The lifespan of white blood cells ranges from 13 to 20 days', 0, 0, 0, 1790968061461) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_80f71c35b437180e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Which of following part of bacteria has ability to self replicating', '{"A":"Plasmid","B":"Cell wall","C":"Ribosome","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bacteria are microscopic, single-celled organisms that thrive in diverse environments.', 0, 0, 0, 1790968061461) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f1c57f9fa1104611', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', 'Which of the following disease affects the skin ?', '{"A":"Pellagra","B":"Anemia","C":"Osteoporosis","D":"Rickets"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pellagra is a disease caused by a lack of the vitamin niacin (vitamin B3). Symptoms include inflamed skin, diarrhea, dementia, and sores in the mouth. Areas of the skin exposed to either sunlight or friction are typically affected first.', 0, 0, 0, 1790968061461) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_07e811c88f1e1779', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_health', '“Ricket” is a disease due to deficiency of?', '{"A":"Vitamin D","B":"Vitamin A","C":"Vitamin K","D":"Vitamin B"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fat soluble Sources include green vegetables, milk and its products, liver eggs and especially in carrots.leading cause of blindness in children worldwide', 0, 0, 0, 1790968061461) ON CONFLICT(id) DO NOTHING;
INSERT INTO subject (id, user_id, name, parent_id, total_mcqs, created_at) VALUES ('top_eds_branches', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'Branches of Science', 'top_everyday_science', 74, 1790968061495) ON CONFLICT(id) DO UPDATE SET total_mcqs = 74;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9c4d95bf7a680abf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'Study of earth is known as _______?', '{"A":"Ecology","B":"Biology","C":"Ethology","D":"Geology"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Geology means the study of the Earth.It is also called Earth Science or Geoscience.Geology studies the formation, structure, composition, and history of Earth.It also examines the processes acting on Earth, such as earthquakes, volcanoes, and erosion.A person who studies geology is called a geologist.Last verified on 15-09-2026', 0, 0, 0, 1790968061531) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f25de3ce284fc9d9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'The study of Earthquakes is known as _____?', '{"A":"Geology","B":"Seismology","C":"Numistatics","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Seismology is the study of earthquakes and seismic waves that move through and around the Earth. A seismologist is a scientist who studies earthquakes and seismic waves.Last verified on 03-04-2026', 0, 0, 0, 1790968061531) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_68ee462b765ced22', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'Who is known as the father of early chemistry and also made significant contributions to biological science?', '{"A":"Al-Razi","B":"Al-Biruni","C":"Ibn Sina","D":"Jabir Ibn Hayyan"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jabir ibn Hayyan, known as the "father of chemistry."He was an Arab Chemist.Composition of Alchemy was written by Jabir Bin Hayyan.Notable ideas:Use of organic substances in chemistrySulfur-mercury theory of metalsScience of the balanceScience of artificial generationLast verified on 07-02-2026', 0, 0, 0, 1790968061531) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5113b7de5f4a2937', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'Ophthalmology is the study of ____?', '{"A":"Nerves","B":"Blood","C":"Eyes","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ophthalmology is the study and medical specialty concerned with the eyes and vision.It deals with the structure, function, diseases, and treatment of the eyes.A doctor specializing in this field is called an ophthalmologist.Common eye conditions include cataracts, glaucoma, and refractive errors.Last verified on 08-08-2026', 0, 0, 0, 1790968061531) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9b50455f403a518c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'X-rays have been discovered by ______?', '{"A":"Charles Babbage","B":"Wilhelm Conrad Roentgen","C":"Ernest Rutherford","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Wilhelm Conrad Rontgen discovered X-rays He was discovered on 8 November 1895.He got the Nobel Prize in Physics in 1901.Additional questionsThe penetrating power of X-rays depends on their frequencyLast updated 26-07-2026 by NA', 0, 0, 0, 1790968061531) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0ca0cf29d35cd3d8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'What is the study of human life and culture?', '{"A":"Anthropology","B":"Sociology","C":"Psychology","D":"Biology"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Anthropology is the study of human life, culture, and societies.It examines human origins, customs, beliefs, languages, traditions, and cultural development.Anthropology helps us understand how humans have evolved and how different cultures function.Additional information:Sociology: Human society and social relationships.Psychology: Human mind and behavior.Biology: Living organisms and life processes.Last verified on 21-07-2026', 0, 0, 0, 1790968061531) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e51866f2835bbdb4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'The term Artificial Intelligence was invented by?', '{"A":"Albert Einstein","B":"John McCarthy","C":"Geoffrey Hinton","D":"Alan Turing","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation John McCarthy is recognized as the father of Artificial Intelligence due to his astounding contribution in the field of Computer Science.John McCarthy was an American computer scientistNote: Artificial Intelligence is a branch of Computer science, which aims to create intelligent machines so that machine can think intelligently in the same manner as a human does.', 0, 0, 0, 1790968061531) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8fc8fc5ebe925f62', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'The study of reptiles and amphibians is called ______?', '{"A":"Herpetology","B":"Ornithology","C":"Entomology","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Herpetology is the branch of zoology that studies reptiles and amphibians.Reptiles include: snakes, lizards, crocodiles, turtles.Amphibians include: frogs, toads, salamanders.The word comes from Greek “herpeton” meaning creeping animal.Last verified on 09-06-2026', 0, 0, 0, 1790968061531) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e419c79ef0544da8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'Who is called father of modern astronomy?', '{"A":"Nicolous Copernicus","B":"Galileo Galilei","C":"Archimedes","D":"None of above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nicolaus Copernicus is called the Father of Modern Astronomy.He introduced the heliocentric theory in 1543.This theory stated that the Sun is at the center of the solar system.His ideas changed the old belief that Earth is the center.Additional information:Galileo Galilei, a later figure, is often called the "father of observational astronomy".Last verified on 01-06-2026', 0, 0, 0, 1790968061570) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f4e94bc772f0ad6e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'Meteorology is study of _____?', '{"A":"Seasons","B":"Atmosphere for weather forecast","C":"Air and sounds","D":"Winds and clouds"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Meteorology is the scientific study of the atmosphere, especially weather and climate.It involves forecasting and understanding atmospheric phenomena.Meteorology is a branch of the atmospheric sciences.Metrology is the scientific study of measurement.Last verified on 03-04-2026', 0, 0, 0, 1790968061570) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4969fd82d65b5d20', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'Which of the following matter/metal are first discovered by man?', '{"A":"Bronze","B":"Silver","C":"Iron","D":"Copper"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first metal discovered and used by humans was Copper.It was found in native form (pure metal) in nature.Early humans used it for tools and ornaments before iron age.This period is known as the Copper Age (Chalcolithic Age).Last verified on 30-05-2026', 0, 0, 0, 1790968061570) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e23186b2a411f8d6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'The study of ancient societies is called _____?', '{"A":"Anthropology","B":"History","C":"Archaeology","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The study of ancient societies through remains and artifacts is called archaeology.It focuses on ruins, tools, coins, and old structures.It helps us understand past human civilizations.Last verified on 02-05-2026', 0, 0, 0, 1790968061570) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_15947492296bed22', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'Who is known as Father of Geography?', '{"A":"Herodotus","B":"Aristotle","C":"Erastosthenes","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The term Geography was first used by the Greek scholar Eratosthenes.He lived in the 3rd century BC (around 276–194 BC).He is also known as the “Father of Geography”.He calculated the circumference of the Earth with remarkable accuracy.His work laid the foundation of modern geographical studies.Last verified on 02-05-2026', 0, 0, 0, 1790968061570) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d6f2fdc29fb3256d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'Vaccination was discovered by?', '{"A":"Galileo","B":"Edward Jenner","C":"Baird","D":"Roentgen"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Edward Jenner was an English physician and scientist.He discovered the first vaccine for smallpox in 1796.He observed that milkmaids infected with cowpox were protected from smallpox.This led to the development of vaccination (cowpox-based immunity method).He is known as the Father of Immunology.Last verified on 02-05-2026', 0, 0, 0, 1790968061570) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e5abfdd36c36a288', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'Oncology is the Study of ______?', '{"A":"Onions","B":"Origins","C":"Diseases","D":"Cancer"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Oncology is a branch of medicine that deals with the study, treatment, diagnosis, and prevention of cancer.A medical professional who practices oncology is an oncologist.The name''s etymological origin is the Greek word ὄγκος, meaning "tumor", "volume" or "mass".Last verified on 03-04-2026', 0, 0, 0, 1790968061570) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_098484cf843758d3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'Dermatology is the study of _____?', '{"A":"Bones","B":"Skin","C":"Blood","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dermatology: Study of skin.It involves the study of health conditions that may affect the skin, fat hair, nails, and membranes.Additional information:Agrostology: Study of GrassesHematology: Study of bloodAgronomy: Study of soil management and crop productionOdontology: Study of teethArthrology: Study of jointsNephrology: Study of kidneysLast verified on 01-04-2026', 0, 0, 0, 1790968061570) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e2dbccd6901f76e1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'Study of plants is called ______?', '{"A":"Entomology","B":"Biology","C":"Botany","D":"None of these"}', 'C', NULL, 0, 0, 0, 1790968061606) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e4780aed8bae93ea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'Anthropology is restricted to the study of ______?', '{"A":"Primitive people only","B":"Pre-historic people only","C":"Modern people only","D":"Human beings in all times and places"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Anthropology is the scientific study of human beings.It covers all humans across time, including past, present, and future societies.It studies culture, evolution, behavior, and social life of humans everywhere.Last verified on 18-03-2026', 0, 0, 0, 1790968061607) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_21303d92f116bf9d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'Study of cultivating fruits, vegetables, flowers and ornamental plants is called?', '{"A":"Anatomy","B":"Horticulture","C":"Physiology","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Horticulture means پھول، جڑی بوٹیاں، پھل اور سبزیاں کاشت کرنے کا علمHorticulture is the agriculture of plants.Additional information:Agrostology: Study of grasses Agronomy: Soil management and crop production Odontology: Study of teeth Arthrology: Study of joints Nephrology: Study of kidneysHematology: Study of blood Dermatology: Study of skinLast verified on 30-01-2026', 0, 0, 0, 1790968061607) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0999f1fa36463903', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'The study of tissues is called _____?', '{"A":"Geology","B":"Histology","C":"Radiology","D":"Toxicology"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The study of tissues is called Histology.It involves examining the structure, composition, and function of cells and tissues under a microscope.Additional information:Geology is the study of rocks and Earth''s structure.Radiology is the study of medical imaging techniques like X-rays and MRI.Last verified on 22-01-2026', 0, 0, 0, 1790968061607) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a28900b78ef66e7a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'Who is called the Father of History?', '{"A":"Aristotle","B":"Socrates","C":"Herodotus","D":"Plato"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Herodotus is called the Father of History.Additional information:Born: 484 BC, Halicarnassus (modern-day Bodrum, Turkey)Died: 425 BC, Thurii, ItalyFamous Work: Histories – detailed accounts of Greco-Persian WarsContribution: First to collect, verify, and narrate historical events systematicallyLast verified on 18-01-2026', 0, 0, 0, 1790968061607) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fe9de989fc7cc451', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'The study of heavenly bodies is called ______?', '{"A":"Geology","B":"Geography","C":"Astronomy","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Astronomy is the science that deals with stars, planets, moons, and all objects beyond Earth’s atmosphere.It helps in understanding the origin, evolution, and structure of the universe.', 0, 0, 0, 1790968061607) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cbd25599dac92a39', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'Study of relationship of organisms to their environment is called?', '{"A":"Embryology","B":"Ecology","C":"Ethology","D":"Entomology"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The study of relationships between organisms and their environment is called Ecology.It helps understand how living things interact with each other and with their surroundings.Additional information:Embryology studies development of embryos.Ethology studies animal behavior.Entomology studies insects.Last verified on 16-01-2026', 0, 0, 0, 1790968061607) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cbf719df591e2314', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'Dynamite was discovered by Alfred Nobel in 1867 in _______?', '{"A":"America","B":"Spain","C":"Sweden","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dynamite was invented by Alfred Nobel in the 1860s.Additional Information REKATED ALFRED NOBELHe was a chemist from Sweden. Full name: Alfred Bernhard NobelBorn: October 21, 1833, Stockholm, SwedenThe founder of the Nobel PrizeInvented Nitro-glycerine in 1875.Died: on December 10, 1896, in Sanremo, Italy', 0, 0, 0, 1790968061607) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c6022f251022802c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'Meteorology is the science of _____?', '{"A":"Space","B":"Weather and Climate","C":"Earth quake","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Meteorology is the scientific study of the atmosphere, especially weather and climate.It involves forecasting and understanding atmospheric phenomena.', 0, 0, 0, 1790968061637) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0d90ea4ffc372734', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'The fundamental component of Earth science classes is the study of ______?', '{"A":"Geology","B":"Seismology","C":"Geography","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Geology focuses on the study of Earth’s structure, composition, and processes.It forms the core subject in Earth science education.', 0, 0, 0, 1790968061637) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6c5484387d5eb19e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'The study of the earth and its features is known as ______?', '{"A":"Geology","B":"Geography","C":"Crystallography","D":"Petrolgy"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Geography is the study of the Earth, its physical features, and human activities.It helps us understand landforms, climate, and the relationship between humans and the environment.', 0, 0, 0, 1790968061638) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3990e2c89ae54885', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'Radioactivity was discovered by _______?', '{"A":"Kelvin","B":"Rutherford","C":"Bacquerel","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Radioactivity was discovered by Henri Becquerel in 1896.They discovered radioactivity proving that the uranium emitted radiation without an external source of energy such as the SunMarie Curie with her husband Pierre Curie, coined the term radioactivity.In 1903, Henry Becquerel shared the Nobel Prize for Physics with Pierre and Marie CurieErnest Rutherford did many experiments studying the properties of radioactive decay (alpha, beta, and gamma)', 0, 0, 0, 1790968061638) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b5bd0d1736050666', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'Electrons discovered by?', '{"A":"Michael Faraday","B":"James Maxwell","C":"Yuri Gagarin","D":"J.J Thomson"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation J.J. Thomson discovered the electron in 1897 through his experiments with cathode rays.The proton was discovered by Ernest Rutherford.The neutron was discovered by James Chadwick.', 0, 0, 0, 1790968061638) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_df77da5a0e628569', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'Astronomy is the study of _______?', '{"A":"Planet","B":"Moon","C":"Stars","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Astronomy is the study of everything in the universe beyond Earth''s atmosphereGalileo Galilei is often referred to as the "father of modern astronomy" and the "father of modern physics".', 0, 0, 0, 1790968061638) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_40ece404d8c0bc1c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'Study of population is called:', '{"A":"Population expulsion","B":"Genetics","C":"Demography","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Demography is the statistical study of human populations. Demography examines the size, structure, and movements of populations over space and time.', 0, 0, 0, 1790968061638) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a5c4e95c60688d82', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'The study of insects is called ____?', '{"A":"Etymology","B":"Entomology","C":"Zoology","D":"Biology"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Entomology is the study of insects and their relationship to humans, the environment, and other organisms.whileZoology is the study of all animals.Biology is a natural science concerned with the study of life and living organisms.Etymology investigates and documents the lives.', 0, 0, 0, 1790968061638) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5a4a3402f5a68918', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'Philology is the study of ______?', '{"A":"Languages","B":"Skin","C":"Liver","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Philology is the study of languages in written historical sources. It includes the analysis of literary texts, history, and the development of languages.', 0, 0, 0, 1790968061671) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e58261c0a1031a11', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'Who is known as Father of Genetics?', '{"A":"Gregor Mendel","B":"Newton","C":"Jabar Bin Hayyan","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Gregor Mendel (from Austria) is called the Father of Genetics for his experiments on pea plants.He discovered the basic principles of heredity and inheritance through his work.', 0, 0, 0, 1790968061671) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_df59710a9c858aef', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'One word Substitution: Study of and exploration of caves is?', '{"A":"Ornithology","B":"Geology","C":"Speleological","D":"Oratory"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Speleology is the scientific study and exploration of caves.The word comes from the Greek words "spelaion", meaning "cave", and "-logy", meaning "study" or "science".', 0, 0, 0, 1790968061671) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dcb471759d31b941', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'All of the following are different branches of biology except? Pathology, Genetics, Microbiology, Mineralogy', '{"A":"Pathology","B":"Genetics","C":"Microbiology","D":"Mineralogy"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pathology, Genetics, and Microbiology are biological sciences dealing with life and living organisms.Mineralogy is a branch of geology that studies minerals, not biology.', 0, 0, 0, 1790968061671) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2316e89d633a2758', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'Study of viruses is called _____?', '{"A":"Mycology","B":"Parasitology","C":"Virology","D":"Microbiology"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The study of viruses is called virology.Virology encompasses the study of viruses, their structure, classification, evolution, and how they interact with living organisms.', 0, 0, 0, 1790968061671) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_31e3a1c05ac7d1d4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'Electromagnetic waves was discovered by ______?', '{"A":"Heinrich Rudolf Hertz","B":"Henri Becquerel","C":"James Clerk Maxwell","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Heinrich Rudolf Hertz discovered electromagnetic waves in 1887, experimentally confirming James Clerk Maxwell''s predictions.Hertz demonstrated the existence of radio waves, a type of electromagnetic wave, using a simple apparatus.', 0, 0, 0, 1790968061671) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_18aa36e74ce005de', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'Structure of DNA was discovered by ______?', '{"A":"James Watson","B":"Francis Crick","C":"Both A and B","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Structure of DNA was discovered by James Watson and Francis Crick in 1953.They discovered the double-helix structure of DNA using X-ray crystallography data.Their discovery revealed the double-helix structure of DNA, where two complementary strands are twisted together with sugar and phosphate molecules, and the nitrogenous bases (adenine, thymine, cytosine, and guanine) pair in a specific manner.', 0, 0, 0, 1790968061671) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dab03ae269beba67', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'Ballpoint pen was invented by _____?', '{"A":"Newton","B":"Louis Daguerre","C":"László Bíró","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation László Bíró, a Hungarian-Argentine inventor, invented the ballpoint pen in 1938.He created it to provide a smoother writing experience compared to fountain pens.', 0, 0, 0, 1790968061671) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d12449dbf339d9b9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'Vitamins was discovered by _____?', '{"A":"Casimir Funk","B":"Farady","C":"Jabar bin Hayyan","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Casimir Funk discovered Vitamins in the year 1912.', 0, 0, 0, 1790968061705) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8fafc8e395e87d43', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'The study of animals with respect of their environment is termed as ____?', '{"A":"Cytology","B":"Ecology","C":"Physiology","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ecology involves the study of animals and their interactions with the environment.It covers how organisms adapt, survive, and relate to each other and their surroundings.', 0, 0, 0, 1790968061705) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9324ece630b676ad', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'The general term for the study of internal structure of plants is ______?', '{"A":"Anatomy","B":"Phytotomy","C":"Both A & B","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Anatomy is the general term used for studying the internal structure of plants and animals.Phytotomy is specifically the plant anatomy — a branch of botany dealing with internal plant structures.', 0, 0, 0, 1790968061705) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_737e68963a787c0f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'Who is known as the father of modern Medicine?', '{"A":"Hippocrates","B":"Avicenna","C":"Ibn Rushid","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hippocrates was a Greek physician.Hippocrates is called the "Father of Modern Medicine" for his systematic approach to clinical medicine.He emphasized observation, diagnosis, and ethics, laying the foundation for modern medical practice.', 0, 0, 0, 1790968061705) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e710fb3566e59028', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'The study of fishes is called _____?', '{"A":"Mammalogy","B":"Ichthyology","C":"Herpetology","D":"Ornithology"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ichthyology is the study of fish.Ichthyology وہ علم جس میں مچھلی کا بیان یا ذکر ہوAdditional information:Agrostology: Study of grasses Agronomy: Study of soil management and crop production Odontology: Study of teeth Arthrology: Study of joints Nephrology: Study of kidneysHematology: Study of blood Dermatology: Study of skin', 0, 0, 0, 1790968061705) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_875aeabc24d5da9a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'Cryptography is a branch of science which deals with _____?', '{"A":"The study of crime and criminals","B":"The study of secrete writing","C":"The study of fingerprints","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cryptography is the art and science of keeping information secure from unintended audiences, of encrypting it.It is also called Crytology.The term was first introduced in 1553.', 0, 0, 0, 1790968061705) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_17ade9541c13a36c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'The study of life is called?', '{"A":"Geology","B":"Chemistry","C":"Biology","D":"Physics"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation BiologyLife and living organisms, including their structure, function, growth, evolution, and interaction with their environment.GeologyThe Earth, its materials (rocks, minerals), structure, and the processes that shape it (earthquakes, volcanoes, plate tectonics).ChemistryMatter, its properties, how it interacts, combines, and changes (chemical reactions, molecular bonds, atomic structure).Physics:The fundamental forces and principles of the universe, such as energy, motion, force, and the nature of matter.', 0, 0, 0, 1790968061705) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1b337db8ff03c864', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'The science of rearing honey bees for honey is known as ____?', '{"A":"Honey Culture","B":"Apiculture","C":"Sericulture","D":"Silvi Culture"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Apiculture is the science and practice of rearing honey bees for honey, beeswax, and other products.It involves the management and maintenance of bee colonies.As well as the harvesting and processing of honey and other bee products.', 0, 0, 0, 1790968061705) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d87537775cdf853a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'The "Law of Gravitation" was discovered by _____?', '{"A":"Isaac Newton","B":"Thomas Aiva Edison","C":"Hug Chavez","D":"Guhlielmo Marconi"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Isaac Newton proposed the law in 1687 and utilized it to clarify the observed movements of the planets and their moons. The law of Gravitation had been mathematically formulated by Johannes Kepler in the early 17th century.ND28-4-2023', 0, 0, 0, 1790968061752) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_14634a29f9499a4a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'Study of Spiders is known as??', '{"A":"Arachnology","B":"Serbology","C":"Germology","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Arachnology is the scientific study of spiders and other arachnids, such as scorpions, ticks, and mites.Arachnologists are biologists who specialize in the study of arachnids, including their behavior, ecology, evolution, and systematics.', 0, 0, 0, 1790968061752) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a50160d509ec1dbe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'Stethoscope was invented by ______?', '{"A":"Rene Laennec","B":"William Harway","C":"Both A and B","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Rene Laennec, a French physician, invented the stethoscope in 1816.He created the first stethoscope using a wooden tube that allowed him to listen to the heart and lungs of a patient without placing his ear on their chest.', 0, 0, 0, 1790968061752) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_64af214d01798974', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'The study of stars is known as ____?', '{"A":"Astrology","B":"Astronomy","C":"Seismography","D":"Discography"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Astronomy is the study of everything in the universe beyond Earth''s atmosphere. That includes objects we can see with our naked eyes, like the Sun , the Moon , the planets, and the stars', 0, 0, 0, 1790968061752) ON CONFLICT(id) DO NOTHING;
