INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_da7793c300743377', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'A branch of medicine dealing with eyes and related diseases is called ____?', '{"A":"Ophthalmology","B":"Obstetrics","C":"Physiology","D":"Hematology","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ophthalmology is a branch of medical science dealing with the structure, functions, and diseases of the eye.Ophthalmology means امراض چشم', 0, 0, 0, 1790968061783) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_52a73c235abc3be6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'Geology is to earth ,similarly Entomology is to:', '{"A":"Insects","B":"Cell","C":"Tissue","D":"Reptiles","E":"Plants"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Geology is the study of the various processes that occur on and inside the surface of the earth. Similarly, Entomology is the branch of biology that deals with the study of insects.Entomology: علم الحشرات، وہ علم جو حشرات کی ساخت سے تعلق رکھتی ہےInsects: کیڑے مکوڑے یا حشرات', 0, 0, 0, 1790968061783) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_99e2c4a9e810ebf7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'The Artificial Intelligence term was invented by?', '{"A":"Geoffrey Hindson","B":"Albert Einstein","C":"Alan M. Turning","D":"John McCarthy"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The term "AI" could be attributed to John McCarthy', 0, 0, 0, 1790968061783) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_00ed340aa8d65b98', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'The study of motion of body is called :', '{"A":"Mechanics","B":"Heat","C":"Light","D":"Sound"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kinematics is the study of motion.It describes position, velocity, and acceleration.It does not focus on the forces causing motion.Examples include linear motion, circular motion, and projectile motion.Additional informationMechanics → broad branch of physics dealing with motion and forces.Dynamics → studies motion and the forces causing it.', 0, 0, 0, 1790968061783) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_57c90bf9048e57e4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'Agrostology is the study of', '{"A":"Seeds of oil","B":"Leaves","C":"Roses","D":"Crops","E":"Grasses"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Agrostology, the branch of botany concerned with the study of grasses, especially their classification. Agrostology means مطالعہ گھاس', 0, 0, 0, 1790968061783) ON CONFLICT(id) DO NOTHING;
