INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tia_adb7d1817b979b8f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_ia_days', 'International Women’s Day is observe on which date?', '{"A":"1st March","B":"5th March","C":"8th March","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation International Women’s Day is observed on 8 March every year to celebrate women’s achievements.It began in the early 20th century, with the first official observance in 1911.Theme for 2026 is Rights. Justice. Action. For ALL Women and Girls***', 0, 0, 0, 1790970547896) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tia_4318f189e57558ae', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_ia_days', 'When is International Labour day observed?', '{"A":"May 1","B":"May 2","C":"May 3","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Date: 1 May every yearOrigin: Labour Day began on 1 May 1886.Historical Event: It commemorates the Haymarket Affair in Chicago.Significance: Recognizes the rights and contributions of workers.2026 Theme: “Ensuring a Healthy Psychosocial Working Environment.”Last updated: NA on 26-09-2026', 0, 0, 0, 1790970547896) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tia_5e3a79b2e88ef6f0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_ia_days', 'When is International Peace Day celebrated?', '{"A":"21 April","B":"20 March","C":"21 September","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation International Day of Peace (or World Peace Day), celebrated on September 21st each year, dedicated to strengthening the ideal of peace between all nations and people.International Day of Peace Established in 1981 by United Nations resolutionTheme 2025: Act now for a peaceful WorldTheme 2026: Invest in Peace – For Everyone, Everywhere, Every Day***', 0, 0, 0, 1790970547896) ON CONFLICT(id) DO NOTHING;
